import type { NistControlText } from "./nist-catalog";

export const controlText: Record<string, NistControlText> = {"AC-1":{"statement":[{"label":"a.","prose":"Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:","items":[{"label":"1.","prose":"[Selection (one or more): organization-level; mission/business process-level; system-level] access control policy that:","items":[{"label":"(a)","prose":"Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and"},{"label":"(b)","prose":"Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and"}]},{"label":"2.","prose":"Procedures to facilitate the implementation of the access control policy and the associated access controls;"}]},{"label":"b.","prose":"Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the access control policy and procedures; and"},{"label":"c.","prose":"Review and update the current access control:","items":[{"label":"1.","prose":"Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and"},{"label":"2.","prose":"Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]."}]}],"discussion":["Access control policy and procedures address the controls in the AC family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of access control policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies reflecting the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to access control policy and procedures include assessment or audit findings, security incidents or breaches, or changes in laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure."],"params":[{"id":"AC-1_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]"},{"id":"AC-01_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the access control policy is to be disseminated is/are defined"},{"id":"AC-01_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the access control procedures are to be disseminated is/are defined"},{"id":"AC-01_ODP[03]","kind":"Selection","value":"[Selection (one or more): organization-level; mission/business process-level; system-level]"},{"id":"AC-01_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined official]","guideline":"an official to manage the access control policy and procedures is defined"},{"id":"AC-01_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current access control policy is reviewed and updated is defined"},{"id":"AC-01_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require the current access control policy to be reviewed and updated are defined"},{"id":"AC-01_ODP[07]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current access control procedures are reviewed and updated is defined"},{"id":"AC-01_ODP[08]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require procedures to be reviewed and updated are defined"}],"related":["IA-1","PM-9","PM-24","PS-8","SI-12"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-12","url":"https://doi.org/10.6028/NIST.SP.800-12r1"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-39","url":"https://doi.org/10.6028/NIST.SP.800-39"},{"title":"SP 800-100","url":"https://doi.org/10.6028/NIST.SP.800-100"},{"title":"IR 7874","url":"https://doi.org/10.6028/NIST.IR.7874"}],"objectives":[{"label":"AC-01a.","prose":"","items":[{"label":"AC-01a.[01]","prose":"an access control policy is developed and documented;"},{"label":"AC-01a.[02]","prose":"the access control policy is disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"AC-01a.[03]","prose":"access control procedures to facilitate the implementation of the access control policy and associated controls are developed and documented;"},{"label":"AC-01a.[04]","prose":"the access control procedures are disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"AC-01a.01","prose":"","items":[{"label":"AC-01a.01(a)","prose":"","items":[{"label":"AC-01a.01(a)[01]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] access control policy addresses purpose;"},{"label":"AC-01a.01(a)[02]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] access control policy addresses scope;"},{"label":"AC-01a.01(a)[03]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] access control policy addresses roles;"},{"label":"AC-01a.01(a)[04]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] access control policy addresses responsibilities;"},{"label":"AC-01a.01(a)[05]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] access control policy addresses management commitment;"},{"label":"AC-01a.01(a)[06]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] access control policy addresses coordination among organizational entities;"},{"label":"AC-01a.01(a)[07]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] access control policy addresses compliance;"}]},{"label":"AC-01a.01(b)","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] access control policy is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines;"}]}]},{"label":"AC-01b.","prose":"the [Assignment: organization-defined official] is designated to manage the development, documentation, and dissemination of the access control policy and procedures;"},{"label":"AC-01c.","prose":"","items":[{"label":"AC-01c.01","prose":"","items":[{"label":"AC-01c.01[01]","prose":"the current access control policy is reviewed and updated [Assignment: organization-defined frequency];"},{"label":"AC-01c.01[02]","prose":"the current access control policy is reviewed and updated following [Assignment: organization-defined events];"}]},{"label":"AC-01c.02","prose":"","items":[{"label":"AC-01c.02[01]","prose":"the current access control procedures are reviewed and updated [Assignment: organization-defined frequency];"},{"label":"AC-01c.02[02]","prose":"the current access control procedures are reviewed and updated following [Assignment: organization-defined events]."}]}]}],"methods":[{"method":"Examine","objects":["Access control policy and procedures","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with access control responsibilities","organizational personnel with information security with information security and privacy responsibilities"]}]},"AC-2":{"statement":[{"label":"a.","prose":"Define and document the types of accounts allowed and specifically prohibited for use within the system;"},{"label":"b.","prose":"Assign account managers;"},{"label":"c.","prose":"Require [Assignment: organization-defined prerequisites and criteria] for group and role membership;"},{"label":"d.","prose":"Specify:","items":[{"label":"1.","prose":"Authorized users of the system;"},{"label":"2.","prose":"Group and role membership; and"},{"label":"3.","prose":"Access authorizations (i.e., privileges) and [Assignment: organization-defined attributes (as required)] for each account;"}]},{"label":"e.","prose":"Require approvals by [Assignment: organization-defined personnel or roles] for requests to create accounts;"},{"label":"f.","prose":"Create, enable, modify, disable, and remove accounts in accordance with [Assignment: organization-defined policy, procedures, prerequisites, and criteria];"},{"label":"g.","prose":"Monitor the use of accounts;"},{"label":"h.","prose":"Notify account managers and [Assignment: organization-defined personnel or roles] within:","items":[{"label":"1.","prose":"[Assignment: organization-defined time period] when accounts are no longer required;"},{"label":"2.","prose":"[Assignment: organization-defined time period] when users are terminated or transferred; and"},{"label":"3.","prose":"[Assignment: organization-defined time period] when system usage or need-to-know changes for an individual;"}]},{"label":"i.","prose":"Authorize access to the system based on:","items":[{"label":"1.","prose":"A valid access authorization;"},{"label":"2.","prose":"Intended system usage; and"},{"label":"3.","prose":"[Assignment: organization-defined attributes (as required)];"}]},{"label":"j.","prose":"Review accounts for compliance with account management requirements [Assignment: organization-defined frequency];"},{"label":"k.","prose":"Establish and implement a process for changing shared or group account authenticators (if deployed) when individuals are removed from the group; and"},{"label":"l.","prose":"Align account management processes with personnel termination and transfer processes."}],"discussion":["Examples of system account types include individual, shared, group, system, guest, anonymous, emergency, developer, temporary, and service. Identification of authorized system users and the specification of access privileges reflect the requirements in other controls in the security plan. Users requiring administrative privileges on system accounts receive additional scrutiny by organizational personnel responsible for approving such accounts and privileged access, including system owner, mission or business owner, senior agency information security officer, or senior agency official for privacy. Types of accounts that organizations may wish to prohibit due to increased risk include shared, group, emergency, anonymous, temporary, and guest accounts.","Where access involves personally identifiable information, security programs collaborate with the senior agency official for privacy to establish the specific conditions for group and role membership; specify authorized users, group and role membership, and access authorizations for each account; and create, adjust, or remove system accounts in accordance with organizational policies. Policies can include such information as account expiration dates or other factors that trigger the disabling of accounts. Organizations may choose to define access privileges or other attributes by account, type of account, or a combination of the two. Examples of other attributes required for authorizing access include restrictions on time of day, day of week, and point of origin. In defining other system account attributes, organizations consider system-related requirements and mission/business requirements. Failure to consider these factors could affect system availability.","Temporary and emergency accounts are intended for short-term use. Organizations establish temporary accounts as part of normal account activation procedures when there is a need for short-term accounts without the demand for immediacy in account activation. Organizations establish emergency accounts in response to crisis situations and with the need for rapid account activation. Therefore, emergency account activation may bypass normal account authorization processes. Emergency and temporary accounts are not to be confused with infrequently used accounts, including local logon accounts used for special tasks or when network resources are unavailable (may also be known as accounts of last resort). Such accounts remain available and are not subject to automatic disabling or removal dates. Conditions for disabling or deactivating accounts include when shared/group, emergency, or temporary accounts are no longer required and when individuals are transferred or terminated. Changing shared/group authenticators when members leave the group is intended to ensure that former group members do not retain access to the shared or group account. Some types of system accounts may require specialized training."],"params":[{"id":"AC-02_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined prerequisites and criteria]","guideline":"prerequisites and criteria for group and role membership are defined"},{"id":"AC-02_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined attributes (as required)]","guideline":"attributes (as required) for each account are defined"},{"id":"AC-02_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles required to approve requests to create accounts is/are defined"},{"id":"AC-02_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined policy, procedures, prerequisites, and criteria]","guideline":"policy, procedures, prerequisites, and criteria for account creation, enabling, modification, disabling, and removal are defined"},{"id":"AC-02_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to be notified is/are defined"},{"id":"AC-02_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"time period within which to notify account managers when accounts are no longer required is defined"},{"id":"AC-02_ODP[07]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"time period within which to notify account managers when users are terminated or transferred is defined"},{"id":"AC-02_ODP[08]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"time period within which to notify account managers when system usage or the need to know changes for an individual is defined"},{"id":"AC-02_ODP[09]","kind":"Assignment","value":"[Assignment: organization-defined attributes (as required)]","guideline":"attributes needed to authorize system access (as required) are defined"},{"id":"AC-02_ODP[10]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency of account review is defined"}],"related":["AC-3","AC-5","AC-6","AC-17","AC-18","AC-20","AC-24","AU-2","AU-12","CM-5","IA-2","IA-4","IA-5","IA-8","MA-3","MA-5","PE-2","PL-4","PS-2","PS-4","PS-5","PS-7","PT-2","PT-3","SC-7","SC-12","SC-13","SC-37"],"references":[{"title":"SP 800-162","url":"https://doi.org/10.6028/NIST.SP.800-162"},{"title":"SP 800-178","url":"https://doi.org/10.6028/NIST.SP.800-178"},{"title":"SP 800-192","url":"https://doi.org/10.6028/NIST.SP.800-192"}],"objectives":[{"label":"AC-02a.","prose":"","items":[{"label":"AC-02a.[01]","prose":"account types allowed for use within the system are defined and documented;"},{"label":"AC-02a.[02]","prose":"account types specifically prohibited for use within the system are defined and documented;"}]},{"label":"AC-02b.","prose":"account managers are assigned;"},{"label":"AC-02c.","prose":"[Assignment: organization-defined prerequisites and criteria] for group and role membership are required;"},{"label":"AC-02d.","prose":"","items":[{"label":"AC-02d.01","prose":"authorized users of the system are specified;"},{"label":"AC-02d.02","prose":"group and role membership are specified;"},{"label":"AC-02d.03","prose":"","items":[{"label":"AC-02d.03[01]","prose":"access authorizations (i.e., privileges) are specified for each account;"},{"label":"AC-02d.03[02]","prose":"[Assignment: organization-defined attributes (as required)] are specified for each account;"}]}]},{"label":"AC-02e.","prose":"approvals are required by [Assignment: organization-defined personnel or roles] for requests to create accounts;"},{"label":"AC-02f.","prose":"","items":[{"label":"AC-02f.[01]","prose":"accounts are created in accordance with [Assignment: organization-defined policy, procedures, prerequisites, and criteria];"},{"label":"AC-02f.[02]","prose":"accounts are enabled in accordance with [Assignment: organization-defined policy, procedures, prerequisites, and criteria];"},{"label":"AC-02f.[03]","prose":"accounts are modified in accordance with [Assignment: organization-defined policy, procedures, prerequisites, and criteria];"},{"label":"AC-02f.[04]","prose":"accounts are disabled in accordance with [Assignment: organization-defined policy, procedures, prerequisites, and criteria];"},{"label":"AC-02f.[05]","prose":"accounts are removed in accordance with [Assignment: organization-defined policy, procedures, prerequisites, and criteria];"}]},{"label":"AC-02g.","prose":"the use of accounts is monitored;"},{"label":"AC-02h.","prose":"","items":[{"label":"AC-02h.01","prose":"account managers and [Assignment: organization-defined personnel or roles] are notified within [Assignment: organization-defined time period] when accounts are no longer required;"},{"label":"AC-02h.02","prose":"account managers and [Assignment: organization-defined personnel or roles] are notified within [Assignment: organization-defined time period] when users are terminated or transferred;"},{"label":"AC-02h.03","prose":"account managers and [Assignment: organization-defined personnel or roles] are notified within [Assignment: organization-defined time period] when system usage or the need to know changes for an individual;"}]},{"label":"AC-02i.","prose":"","items":[{"label":"AC-02i.01","prose":"access to the system is authorized based on a valid access authorization;"},{"label":"AC-02i.02","prose":"access to the system is authorized based on intended system usage;"},{"label":"AC-02i.03","prose":"access to the system is authorized based on [Assignment: organization-defined attributes (as required)];"}]},{"label":"AC-02j.","prose":"accounts are reviewed for compliance with account management requirements [Assignment: organization-defined frequency];"},{"label":"AC-02k.","prose":"","items":[{"label":"AC-02k.[01]","prose":"a process is established for changing shared or group account authenticators (if deployed) when individuals are removed from the group;"},{"label":"AC-02k.[02]","prose":"a process is implemented for changing shared or group account authenticators (if deployed) when individuals are removed from the group;"}]},{"label":"AC-02l.","prose":"","items":[{"label":"AC-02l.[01]","prose":"account management processes are aligned with personnel termination processes;"},{"label":"AC-02l.[02]","prose":"account management processes are aligned with personnel transfer processes."}]}],"methods":[{"method":"Examine","objects":["Access control policy","personnel termination policy and procedure","personnel transfer policy and procedure","procedures for addressing account management","system design documentation","system configuration settings and associated documentation","list of active system accounts along with the name of the individual associated with each account","list of recently disabled system accounts and the name of the individual associated with each account"]},{"method":"Interview","objects":["Organizational personnel with account management responsibilities","system/network administrators","organizational personnel with information security with information security and privacy responsibilities"]},{"method":"Test","objects":["Organizational processes for account management on the system","mechanisms for implementing account management"]}]},"AC-2(1)":{"statement":[{"prose":"Support the management of system accounts using [Assignment: organization-defined automated mechanisms]."}],"discussion":["Automated system account management includes using automated mechanisms to create, enable, modify, disable, and remove accounts; notify account managers when an account is created, enabled, modified, disabled, or removed, or when users are terminated or transferred; monitor system account usage; and report atypical system account usage. Automated mechanisms can include internal system functions and email, telephonic, and text messaging notifications."],"params":[{"id":"AC-02(01)_ODP","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms used to support the management of system accounts are defined"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Access control policy","procedures for addressing account management","system design documentation","system configuration settings and associated documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with account management responsibilities","system/network administrators","organizational personnel with information security with information security responsibilities","system developers"]},{"method":"Test","objects":["Automated mechanisms for implementing account management functions"]}]},"AC-2(2)":{"statement":[{"prose":"Automatically [Selection: remove; disable] temporary and emergency accounts after [Assignment: organization-defined time period]."}],"discussion":["Management of temporary and emergency accounts includes the removal or disabling of such accounts automatically after a predefined time period rather than at the convenience of the system administrator. Automatic removal or disabling of accounts provides a more consistent implementation."],"params":[{"id":"AC-02(02)_ODP[01]","kind":"Selection","value":"[Selection: remove; disable]"},{"id":"AC-02(02)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"the time period after which to automatically remove or disable temporary or emergency accounts is defined"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Access control policy","procedures for addressing account management","system design documentation","system configuration settings and associated documentation","system-generated list of temporary accounts removed and/or disabled","system-generated list of emergency accounts removed and/or disabled","system audit records","system security plan"]},{"method":"Interview","objects":["Organizational personnel with account management responsibilities","system/network administrators","organizational personnel with information security with information security responsibilities","system developers"]},{"method":"Test","objects":["Automated mechanisms for implementing account management functions"]}]},"AC-2(3)":{"statement":[{"prose":"Disable accounts within [Assignment: organization-defined time period] when the accounts:"},{"label":"(a)","prose":"Have expired;"},{"label":"(b)","prose":"Are no longer associated with a user or individual;"},{"label":"(c)","prose":"Are in violation of organizational policy; or"},{"label":"(d)","prose":"Have been inactive for [Assignment: organization-defined time period]."}],"discussion":["Disabling expired, inactive, or otherwise anomalous accounts supports the concepts of least privilege and least functionality which reduce the attack surface of the system."],"params":[{"id":"AC-02(03)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"time period within which to disable accounts is defined"},{"id":"AC-02(03)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"time period for account inactivity before disabling is defined"}],"related":[],"references":[],"objectives":[{"label":"AC-02(03)(a)","prose":"accounts are disabled within [Assignment: organization-defined time period] when the accounts have expired;"},{"label":"AC-02(03)(b)","prose":"accounts are disabled within [Assignment: organization-defined time period] when the accounts are no longer associated with a user or individual;"},{"label":"AC-02(03)(c)","prose":"accounts are disabled within [Assignment: organization-defined time period] when the accounts are in violation of organizational policy;"},{"label":"AC-02(03)(d)","prose":"accounts are disabled within [Assignment: organization-defined time period] when the accounts have been inactive for [Assignment: organization-defined time period]."}],"methods":[{"method":"Examine","objects":["Access control policy","procedures for addressing account management","system security plan","system design documentation","system configuration settings and associated documentation","system-generated list of accounts removed","system-generated list of emergency accounts disabled","system audit records"]},{"method":"Interview","objects":["Organizational personnel with account management responsibilities","system/network administrators","organizational personnel with information security responsibilities","system developers"]},{"method":"Test","objects":["Mechanisms for implementing account management functions"]}]},"AC-2(4)":{"statement":[{"prose":"Automatically audit account creation, modification, enabling, disabling, and removal actions."}],"discussion":["Account management audit records are defined in accordance with [AU-02](#au-2) and reviewed, analyzed, and reported in accordance with [AU-06](#au-6)."],"params":[],"related":["AU-2","AU-6"],"references":[],"objectives":[{"label":"AC-02(04)[01]","prose":"account creation is automatically audited;"},{"label":"AC-02(04)[02]","prose":"account modification is automatically audited;"},{"label":"AC-02(04)[03]","prose":"account enabling is automatically audited;"},{"label":"AC-02(04)[04]","prose":"account disabling is automatically audited;"},{"label":"AC-02(04)[05]","prose":"account removal actions are automatically audited."}],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing account management","system design documentation","system configuration settings and associated documentation","notifications/alerts of account creation, modification, enabling, disabling, and removal actions","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with account management responsibilities","system/network administrators","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Automated mechanisms implementing account management functions"]}]},"AC-2(5)":{"statement":[{"prose":"Require that users log out when [Assignment: organization-defined time period of expected inactivity or description of when to log out]."}],"discussion":["Inactivity logout is behavior- or policy-based and requires users to take physical action to log out when they are expecting inactivity longer than the defined period. Automatic enforcement of inactivity logout is addressed by [AC-11](#ac-11)."],"params":[{"id":"AC-02(05)_ODP","kind":"Assignment","value":"[Assignment: organization-defined time period of expected inactivity or description of when to log out]","guideline":"the time period of expected inactivity or description of when to log out is defined"}],"related":["AC-11"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing account management","system design documentation","system configuration settings and associated documentation","security violation reports","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with account management responsibilities","system/network administrators","organizational personnel with information security responsibilities","users that must comply with inactivity logout policy"]}]},"AC-2(11)":{"statement":[{"prose":"Enforce [Assignment: organization-defined circumstances and/or usage conditions] for [Assignment: organization-defined system accounts]."}],"discussion":["Specifying and enforcing usage conditions helps to enforce the principle of least privilege, increase user accountability, and enable effective account monitoring. Account monitoring includes alerts generated if the account is used in violation of organizational parameters. Organizations can describe specific conditions or circumstances under which system accounts can be used, such as by restricting usage to certain days of the week, time of day, or specific durations of time."],"params":[{"id":"AC-02(11)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined circumstances and/or usage conditions]","guideline":"circumstances and/or usage conditions to be enforced for system accounts are defined"},{"id":"AC-02(11)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined system accounts]","guideline":"system accounts subject to enforcement of circumstances and/or usage conditions are defined"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing account management","system design documentation","system configuration settings and associated documentation","system-generated list of system accounts and associated assignments of usage circumstances and/or usage conditions","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with account management responsibilities","system/network administrators","organizational personnel with information security responsibilities","system developers"]},{"method":"Test","objects":["Mechanisms implementing account management functions"]}]},"AC-2(12)":{"statement":[{"label":"(a)","prose":"Monitor system accounts for [Assignment: organization-defined atypical usage]; and"},{"label":"(b)","prose":"Report atypical usage of system accounts to [Assignment: organization-defined personnel or roles]."}],"discussion":["Atypical usage includes accessing systems at certain times of the day or from locations that are not consistent with the normal usage patterns of individuals. Monitoring for atypical usage may reveal rogue behavior by individuals or an attack in progress. Account monitoring may inadvertently create privacy risks since data collected to identify atypical usage may reveal previously unknown information about the behavior of individuals. Organizations assess and document privacy risks from monitoring accounts for atypical usage in their privacy impact assessment and make determinations that are in alignment with their privacy program plan."],"params":[{"id":"AC-02(12)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined atypical usage]","guideline":"atypical usage for which to monitor system accounts is defined"},{"id":"AC-02(12)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to report atypical usage is/are defined"}],"related":["AU-6","AU-7","CA-7","IR-8","SI-4"],"references":[],"objectives":[{"label":"AC-02(12)(a)","prose":"system accounts are monitored for [Assignment: organization-defined atypical usage];"},{"label":"AC-02(12)(b)","prose":"atypical usage of system accounts is reported to [Assignment: organization-defined personnel or roles]."}],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing account management","system design documentation","system configuration settings and associated documentation","system monitoring records","system audit records","audit tracking and monitoring reports","privacy impact assessment"]},{"method":"Interview","objects":["Organizational personnel with account management responsibilities","system/network administrators","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Mechanisms implementing account management functions"]}]},"AC-2(13)":{"statement":[{"prose":"Disable accounts of individuals within [Assignment: organization-defined time period] of discovery of [Assignment: organization-defined significant risks]."}],"discussion":["Users who pose a significant security and/or privacy risk include individuals for whom reliable evidence indicates either the intention to use authorized access to systems to cause harm or through whom adversaries will cause harm. Such harm includes adverse impacts to organizational operations, organizational assets, individuals, other organizations, or the Nation. Close coordination among system administrators, legal staff, human resource managers, and authorizing officials is essential when disabling system accounts for high-risk individuals."],"params":[{"id":"AC-02(13)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"time period within which to disable accounts of individuals who are discovered to pose significant risk is defined"},{"id":"AC-02(13)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined significant risks]","guideline":"significant risks leading to disabling accounts are defined"}],"related":["AU-6","SI-4"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing account management","system design documentation","system configuration settings and associated documentation","system-generated list of disabled accounts","list of user activities posing significant organizational risk","system audit records","system security plan"]},{"method":"Interview","objects":["Organizational personnel with account management responsibilities","system/network administrators","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Mechanisms implementing account management functions"]}]},"AC-3":{"statement":[{"prose":"Enforce approved authorizations for logical access to information and system resources in accordance with applicable access control policies."}],"discussion":["Access control policies control access between active entities or subjects (i.e., users or processes acting on behalf of users) and passive entities or objects (i.e., devices, files, records, domains) in organizational systems. In addition to enforcing authorized access at the system level and recognizing that systems can host many applications and services in support of mission and business functions, access enforcement mechanisms can also be employed at the application and service level to provide increased information security and privacy. In contrast to logical access controls that are implemented within the system, physical access controls are addressed by the controls in the Physical and Environmental Protection ([PE](#pe)) family."],"params":[],"related":["AC-2","AC-4","AC-5","AC-6","AC-16","AC-17","AC-18","AC-19","AC-20","AC-21","AC-22","AC-24","AC-25","AT-2","AT-3","AU-9","CA-9","CM-5","CM-11","IA-2","IA-5","IA-6","IA-7","IA-11","IA-13","MA-3","MA-4","MA-5","MP-4","PM-2","PS-3","PT-2","PT-3","SA-17","SC-2","SC-3","SC-4","SC-12","SC-13","SC-28","SC-31","SC-34","SI-4","SI-8"],"references":[{"title":"PRIVACT","url":"https://www.govinfo.gov/content/pkg/STATUTE-88/pdf/STATUTE-88-Pg1896.pdf"},{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-57-1","url":"https://doi.org/10.6028/NIST.SP.800-57pt1r5"},{"title":"SP 800-57-2","url":"https://doi.org/10.6028/NIST.SP.800-57pt2r1"},{"title":"SP 800-57-3","url":"https://doi.org/10.6028/NIST.SP.800-57pt3r1"},{"title":"SP 800-162","url":"https://doi.org/10.6028/NIST.SP.800-162"},{"title":"SP 800-178","url":"https://doi.org/10.6028/NIST.SP.800-178"},{"title":"IR 7874","url":"https://doi.org/10.6028/NIST.IR.7874"}],"objectives":[],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing access enforcement","system design documentation","system configuration settings and associated documentation","list of approved authorizations (user privileges)","system audit records","system security plan","privacy plan"]},{"method":"Interview","objects":["Organizational personnel with access enforcement responsibilities","system/network administrators","organizational personnel with information security and privacy responsibilities","system developers"]},{"method":"Test","objects":["Mechanisms implementing access control policy"]}]},"AC-4":{"statement":[{"prose":"Enforce approved authorizations for controlling the flow of information within the system and between connected systems based on [Assignment: organization-defined information flow control policies]."}],"discussion":["Information flow control regulates where information can travel within a system and between systems (in contrast to who is allowed to access the information) and without regard to subsequent accesses to that information. Flow control restrictions include blocking external traffic that claims to be from within the organization, keeping export-controlled information from being transmitted in the clear to the Internet, restricting web requests that are not from the internal web proxy server, and limiting information transfers between organizations based on data structures and content. Transferring information between organizations may require an agreement specifying how the information flow is enforced (see [CA-3](#ca-3)). Transferring information between systems in different security or privacy domains with different security or privacy policies introduces the risk that such transfers violate one or more domain security or privacy policies. In such situations, information owners/stewards provide guidance at designated policy enforcement points between connected systems. Organizations consider mandating specific architectural solutions to enforce specific security and privacy policies. Enforcement includes prohibiting information transfers between connected systems (i.e., allowing access only), verifying write permissions before accepting information from another security or privacy domain or connected system, employing hardware mechanisms to enforce one-way information flows, and implementing trustworthy regrading mechanisms to reassign security or privacy attributes and labels.","Organizations commonly employ information flow control policies and enforcement mechanisms to control the flow of information between designated sources and destinations within systems and between connected systems. Flow control is based on the characteristics of the information and/or the information path. Enforcement occurs, for example, in boundary protection devices that employ rule sets or establish configuration settings that restrict system services, provide a packet-filtering capability based on header information, or provide a message-filtering capability based on message content. Organizations also consider the trustworthiness of filtering and/or inspection mechanisms (i.e., hardware, firmware, and software components) that are critical to information flow enforcement. Control enhancements 3 through 32 primarily address cross-domain solution needs that focus on more advanced filtering techniques, in-depth analysis, and stronger flow enforcement mechanisms implemented in cross-domain products, such as high-assurance guards. Such capabilities are generally not available in commercial off-the-shelf products. Information flow enforcement also applies to control plane traffic (e.g., routing and DNS)."],"params":[{"id":"AC-04_ODP","kind":"Assignment","value":"[Assignment: organization-defined information flow control policies]","guideline":"information flow control policies within the system and between connected systems are defined"}],"related":["AC-3","AC-6","AC-16","AC-17","AC-19","AC-21","AU-10","CA-3","CA-9","CM-7","PL-9","PM-24","SA-17","SC-4","SC-7","SC-16","SC-31"],"references":[{"title":"SP 800-160-1","url":"https://doi.org/10.6028/NIST.SP.800-160v1"},{"title":"SP 800-162","url":"https://doi.org/10.6028/NIST.SP.800-162"},{"title":"SP 800-178","url":"https://doi.org/10.6028/NIST.SP.800-178"},{"title":"IR 8112","url":"https://doi.org/10.6028/NIST.IR.8112"}],"objectives":[],"methods":[{"method":"Examine","objects":["Access control policy","information flow control policies","procedures addressing information flow enforcement","security architecture documentation","privacy architecture documentation","system design documentation","system configuration settings and associated documentation","system baseline configuration"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security and privacy architecture development responsibilities","organizational personnel with information security and privacy responsibilities","system developers"]},{"method":"Test","objects":["Mechanisms implementing information flow enforcement policy"]}]},"AC-4(4)":{"statement":[{"prose":"Prevent encrypted information from bypassing [Assignment: organization-defined information flow control mechanisms] by [Selection (one or more): decrypting the information; blocking the flow of the encrypted information; terminating communications sessions attempting to pass encrypted information; [Assignment: organization-defined procedure or method]]."}],"discussion":["Flow control mechanisms include content checking, security policy filters, and data type identifiers. The term encryption is extended to cover encoded data not recognized by filtering mechanisms."],"params":[{"id":"AC-04(04)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined information flow control mechanisms]","guideline":"information flow control mechanisms that encrypted information is prevented from bypassing are defined"},{"id":"AC-04(04)_ODP[02]","kind":"Selection","value":"[Selection (one or more): decrypting the information; blocking the flow of the encrypted information; terminating communications sessions attempting to pass encrypted information; [Assignment: organization-defined procedure or method]]"},{"id":"AC-04(04)_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined procedure or method]","guideline":"the organization-defined procedure or method used to prevent encrypted information from bypassing information flow control mechanisms is defined (if selected)"}],"related":["SI-4"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Access control policy","information flow control policies","procedures addressing information flow enforcement","system design documentation","system configuration settings and associated documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developers"]},{"method":"Test","objects":["Mechanisms implementing information flow enforcement policy"]}]},"AC-5":{"statement":[{"label":"a.","prose":"Identify and document [Assignment: organization-defined duties of individuals]; and"},{"label":"b.","prose":"Define system access authorizations to support separation of duties."}],"discussion":["Separation of duties addresses the potential for abuse of authorized privileges and helps to reduce the risk of malevolent activity without collusion. Separation of duties includes dividing mission or business functions and support functions among different individuals or roles, conducting system support functions with different individuals, and ensuring that security personnel who administer access control functions do not also administer audit functions. Because separation of duty violations can span systems and application domains, organizations consider the entirety of systems and system components when developing policy on separation of duties. Separation of duties is enforced through the account management activities in [AC-2](#ac-2), access control mechanisms in [AC-3](#ac-3), and identity management activities in [IA-2](#ia-2), [IA-4](#ia-4), and [IA-12](#ia-12)."],"params":[{"id":"AC-05_ODP","kind":"Assignment","value":"[Assignment: organization-defined duties of individuals]","guideline":"duties of individuals requiring separation are defined"}],"related":["AC-2","AC-3","AC-6","AU-9","CM-5","CM-11","CP-9","IA-2","IA-4","IA-5","IA-12","MA-3","MA-5","PS-2","SA-8","SA-17"],"references":[],"objectives":[{"label":"AC-05a.","prose":"[Assignment: organization-defined duties of individuals] are identified and documented;"},{"label":"AC-05b.","prose":"system access authorizations to support separation of duties are defined."}],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing divisions of responsibility and separation of duties","system configuration settings and associated documentation","list of divisions of responsibility and separation of duties","system access authorizations","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for defining appropriate divisions of responsibility and separation of duties","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Mechanisms implementing separation of duties policy"]}]},"AC-6":{"statement":[{"prose":"Employ the principle of least privilege, allowing only authorized accesses for users (or processes acting on behalf of users) that are necessary to accomplish assigned organizational tasks."}],"discussion":["Organizations employ least privilege for specific duties and systems. The principle of least privilege is also applied to system processes, ensuring that the processes have access to systems and operate at privilege levels no higher than necessary to accomplish organizational missions or business functions. Organizations consider the creation of additional processes, roles, and accounts as necessary to achieve least privilege. Organizations apply least privilege to the development, implementation, and operation of organizational systems."],"params":[],"related":["AC-2","AC-3","AC-5","AC-16","CM-5","CM-11","PL-2","PM-12","SA-8","SA-15","SA-17","SC-38"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing least privilege","list of assigned access authorizations (user privileges)","system configuration settings and associated documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for defining least privileges necessary to accomplish specified tasks","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Mechanisms implementing least privilege functions"]}]},"AC-6(1)":{"statement":[{"prose":"Authorize access for [Assignment: organization-defined individuals and roles] to:"},{"label":"(a)","prose":"[Assignment: organization-defined security functions (deployed in hardware, software, and firmware)]; and"},{"label":"(b)","prose":"[Assignment: organization-defined security-relevant information]."}],"discussion":["Security functions include establishing system accounts, configuring access authorizations (i.e., permissions, privileges), configuring settings for events to be audited, and establishing intrusion detection parameters. Security-relevant information includes filtering rules for routers or firewalls, configuration parameters for security services, cryptographic key management information, and access control lists. Authorized personnel include security administrators, system administrators, system security officers, system programmers, and other privileged users."],"params":[{"id":"AC-6.1_PRM_2","kind":"Assignment","value":"[Assignment: organization-defined security functions (deployed in hardware, software, and firmware)]"},{"id":"AC-06(01)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined individuals and roles]","guideline":"individuals and roles with authorized access to security functions and security-relevant information are defined"},{"id":"AC-06(01)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined security functions (deployed in hardware)]","guideline":"security functions (deployed in hardware) for authorized access are defined"},{"id":"AC-06(01)_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined security functions (deployed in software)]","guideline":"security functions (deployed in software) for authorized access are defined"},{"id":"AC-06(01)_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined security functions (deployed in firmware)]","guideline":"security functions (deployed in firmware) for authorized access are defined"},{"id":"AC-06(01)_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined security-relevant information]","guideline":"security-relevant information for authorized access is defined"}],"related":["AC-17","AC-18","AC-19","AU-9","PE-2"],"references":[],"objectives":[{"label":"AC-06(01)(a)","prose":"","items":[{"label":"AC-06(01)(a)[01]","prose":"access is authorized for [Assignment: organization-defined individuals and roles] to [Assignment: organization-defined security functions (deployed in hardware)];"},{"label":"AC-06(01)(a)[02]","prose":"access is authorized for [Assignment: organization-defined individuals and roles] to [Assignment: organization-defined security functions (deployed in software)];"},{"label":"AC-06(01)(a)[03]","prose":"access is authorized for [Assignment: organization-defined individuals and roles] to [Assignment: organization-defined security functions (deployed in firmware)];"}]},{"label":"AC-06(01)(b)","prose":"access is authorized for [Assignment: organization-defined individuals and roles] to [Assignment: organization-defined security-relevant information]."}],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing least privilege","list of security functions (deployed in hardware, software, and firmware) and security-relevant information for which access must be explicitly authorized","system configuration settings and associated documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for defining least privileges necessary to accomplish specified tasks","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Mechanisms implementing least privilege functions"]}]},"AC-6(2)":{"statement":[{"prose":"Require that users of system accounts (or roles) with access to [Assignment: organization-defined security functions or security-relevant information] use non-privileged accounts or roles, when accessing nonsecurity functions."}],"discussion":["Requiring the use of non-privileged accounts when accessing nonsecurity functions limits exposure when operating from within privileged accounts or roles. The inclusion of roles addresses situations where organizations implement access control policies, such as role-based access control, and where a change of role provides the same degree of assurance in the change of access authorizations for the user and the processes acting on behalf of the user as would be provided by a change between a privileged and non-privileged account."],"params":[{"id":"AC-06(02)_ODP","kind":"Assignment","value":"[Assignment: organization-defined security functions or security-relevant information]","guideline":"security functions or security-relevant information, the access to which requires users to use non-privileged accounts to access non-security functions, are defined"}],"related":["AC-17","AC-18","AC-19","PL-4"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing least privilege","list of system-generated security functions or security-relevant information assigned to system accounts or roles","system configuration settings and associated documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for defining least privileges necessary to accomplish specified tasks","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Mechanisms implementing least privilege functions"]}]},"AC-6(3)":{"statement":[{"prose":"Authorize network access to [Assignment: organization-defined privileged commands] only for [Assignment: organization-defined compelling operational needs] and document the rationale for such access in the security plan for the system."}],"discussion":["Network access is any access across a network connection in lieu of local access (i.e., user being physically present at the device)."],"params":[{"id":"AC-06(03)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined privileged commands]","guideline":"privileged commands to which network access is to be authorized only for compelling operational needs are defined"},{"id":"AC-06(03)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined compelling operational needs]","guideline":"compelling operational needs necessitating network access to privileged commands are defined"}],"related":["AC-17","AC-18","AC-19"],"references":[],"objectives":[{"label":"AC-06(03)[01]","prose":"network access to [Assignment: organization-defined privileged commands] is authorized only for [Assignment: organization-defined compelling operational needs];"},{"label":"AC-06(03)[02]","prose":"the rationale for authorizing network access to privileged commands is documented in the security plan for the system."}],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing least privilege","system configuration settings and associated documentation","system audit records","list of operational needs for authorizing network access to privileged commands","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for defining least privileges necessary to accomplish specified tasks","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Mechanisms implementing least privilege functions"]}]},"AC-6(5)":{"statement":[{"prose":"Restrict privileged accounts on the system to [Assignment: organization-defined personnel or roles]."}],"discussion":["Privileged accounts, including super user accounts, are typically described as system administrator for various types of commercial off-the-shelf operating systems. Restricting privileged accounts to specific personnel or roles prevents day-to-day users from accessing privileged information or privileged functions. Organizations may differentiate in the application of restricting privileged accounts between allowed privileges for local accounts and for domain accounts provided that they retain the ability to control system configurations for key parameters and as otherwise necessary to sufficiently mitigate risk."],"params":[{"id":"AC-06(05)_ODP","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to which privileged accounts on the system are to be restricted is/are defined"}],"related":["IA-2","MA-3","MA-4"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing least privilege","list of system-generated privileged accounts","list of system administration personnel","system configuration settings and associated documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for defining least privileges necessary to accomplish specified tasks","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Mechanisms implementing least privilege functions"]}]},"AC-6(7)":{"statement":[{"label":"(a)","prose":"Review [Assignment: organization-defined frequency] the privileges assigned to [Assignment: organization-defined roles and classes] to validate the need for such privileges; and"},{"label":"(b)","prose":"Reassign or remove privileges, if necessary, to correctly reflect organizational mission and business needs."}],"discussion":["The need for certain assigned user privileges may change over time to reflect changes in organizational mission and business functions, environments of operation, technologies, or threats. A periodic review of assigned user privileges is necessary to determine if the rationale for assigning such privileges remains valid. If the need cannot be revalidated, organizations take appropriate corrective actions."],"params":[{"id":"AC-06(07)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to review the privileges assigned to roles or classes of users is defined"},{"id":"AC-06(07)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined roles and classes]","guideline":"roles or classes of users to which privileges are assigned are defined"}],"related":["CA-7"],"references":[],"objectives":[{"label":"AC-06(07)(a)","prose":"privileges assigned to [Assignment: organization-defined roles and classes] are reviewed [Assignment: organization-defined frequency] to validate the need for such privileges;"},{"label":"AC-06(07)(b)","prose":"privileges are reassigned or removed, if necessary, to correctly reflect organizational mission and business needs."}],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing least privilege","list of system-generated roles or classes of users and assigned privileges","system design documentation","system configuration settings and associated documentation","validation reviews of privileges assigned to roles or classes or users","records of privilege removals or reassignments for roles or classes of users","system audit records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for reviewing least privileges necessary to accomplish specified tasks","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Mechanisms implementing review of user privileges"]}]},"AC-6(9)":{"statement":[{"prose":"Log the execution of privileged functions."}],"discussion":["The misuse of privileged functions, either intentionally or unintentionally by authorized users or by unauthorized external entities that have compromised system accounts, is a serious and ongoing concern and can have significant adverse impacts on organizations. Logging and analyzing the use of privileged functions is one way to detect such misuse and, in doing so, help mitigate the risk from insider threats and the advanced persistent threat."],"params":[],"related":["AU-2","AU-3","AU-12"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing least privilege","system design documentation","system configuration settings and associated documentation","list of privileged functions to be audited","list of audited events","system audit records","system security plan"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for reviewing least privileges necessary to accomplish specified tasks","organizational personnel with information security responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Mechanisms auditing the execution of least privilege functions"]}]},"AC-6(10)":{"statement":[{"prose":"Prevent non-privileged users from executing privileged functions."}],"discussion":["Privileged functions include disabling, circumventing, or altering implemented security or privacy controls, establishing system accounts, performing system integrity checks, and administering cryptographic key management activities. Non-privileged users are individuals who do not possess appropriate authorizations. Privileged functions that require protection from non-privileged users include circumventing intrusion detection and prevention mechanisms or malicious code protection mechanisms. Preventing non-privileged users from executing privileged functions is enforced by [AC-3](#ac-3)."],"params":[],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing least privilege","system design documentation","system configuration settings and associated documentation","list of privileged functions and associated user account assignments","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for defining least privileges necessary to accomplish specified tasks","organizational personnel with information security responsibilities","system developers"]},{"method":"Test","objects":["Mechanisms implementing least privilege functions for non-privileged users"]}]},"AC-7":{"statement":[{"label":"a.","prose":"Enforce a limit of [Assignment: organization-defined number] consecutive invalid logon attempts by a user during a [Assignment: organization-defined time period]; and"},{"label":"b.","prose":"Automatically [Selection (one or more): lock the account or node for [Assignment: organization-defined time period]; lock the account or node until released by an administrator; delay next logon prompt per [Assignment: organization-defined delay algorithm]; notify system administrator; take other [Assignment: organization-defined action]] when the maximum number of unsuccessful attempts is exceeded."}],"discussion":["The need to limit unsuccessful logon attempts and take subsequent action when the maximum number of attempts is exceeded applies regardless of whether the logon occurs via a local or network connection. Due to the potential for denial of service, automatic lockouts initiated by systems are usually temporary and automatically release after a predetermined, organization-defined time period. If a delay algorithm is selected, organizations may employ different algorithms for different components of the system based on the capabilities of those components. Responses to unsuccessful logon attempts may be implemented at the operating system and the application levels. Organization-defined actions that may be taken when the number of allowed consecutive invalid logon attempts is exceeded include prompting the user to answer a secret question in addition to the username and password, invoking a lockdown mode with limited user capabilities (instead of full lockout), allowing users to only logon from specified Internet Protocol (IP) addresses, requiring a CAPTCHA to prevent automated attacks, or applying user profiles such as location, time of day, IP address, device, or Media Access Control (MAC) address. If automatic system lockout or execution of a delay algorithm is not implemented in support of the availability objective, organizations consider a combination of other actions to help prevent brute force attacks. In addition to the above, organizations can prompt users to respond to a secret question before the number of allowed unsuccessful logon attempts is exceeded. Automatically unlocking an account after a specified period of time is generally not permitted. However, exceptions may be required based on operational mission or need."],"params":[{"id":"AC-07_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined number]","guideline":"the number of consecutive invalid logon attempts by a user allowed during a time period is defined"},{"id":"AC-07_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"the time period to which the number of consecutive invalid logon attempts by a user is limited is defined"},{"id":"AC-07_ODP[03]","kind":"Selection","value":"[Selection (one or more): lock the account or node for [Assignment: organization-defined time period]; lock the account or node until released by an administrator; delay next logon prompt per [Assignment: organization-defined delay algorithm]; notify system administrator; take other [Assignment: organization-defined action]]"},{"id":"AC-07_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"time period for an account or node to be locked is defined (if selected)"},{"id":"AC-07_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined delay algorithm]","guideline":"delay algorithm for the next logon prompt is defined (if selected)"},{"id":"AC-07_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined action]","guideline":"other action to be taken when the maximum number of unsuccessful attempts is exceeded is defined (if selected)"}],"related":["AC-2","AC-9","AU-2","AU-6","IA-5"],"references":[{"title":"SP 800-63-3","url":"https://doi.org/10.6028/NIST.SP.800-63-3"},{"title":"SP 800-124","url":"https://doi.org/10.6028/NIST.SP.800-124r1"}],"objectives":[{"label":"AC-07a.","prose":"a limit of [Assignment: organization-defined number] consecutive invalid logon attempts by a user during [Assignment: organization-defined time period] is enforced;"},{"label":"AC-07b.","prose":"automatically [Selection (one or more): lock the account or node for [Assignment: organization-defined time period]; lock the account or node until released by an administrator; delay next logon prompt per [Assignment: organization-defined delay algorithm]; notify system administrator; take other [Assignment: organization-defined action]] when the maximum number of unsuccessful attempts is exceeded."}],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing unsuccessful logon attempts","system design documentation","system configuration settings and associated documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with information security responsibilities","system developers","system/network administrators"]},{"method":"Test","objects":["Mechanisms implementing access control policy for unsuccessful logon attempts"]}]},"AC-8":{"statement":[{"label":"a.","prose":"Display [Assignment: organization-defined system use notification] to users before granting access to the system that provides privacy and security notices consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines and state that:","items":[{"label":"1.","prose":"Users are accessing a U.S. Government system;"},{"label":"2.","prose":"System usage may be monitored, recorded, and subject to audit;"},{"label":"3.","prose":"Unauthorized use of the system is prohibited and subject to criminal and civil penalties; and"},{"label":"4.","prose":"Use of the system indicates consent to monitoring and recording;"}]},{"label":"b.","prose":"Retain the notification message or banner on the screen until users acknowledge the usage conditions and take explicit actions to log on to or further access the system; and"},{"label":"c.","prose":"For publicly accessible systems:","items":[{"label":"1.","prose":"Display system use information [Assignment: organization-defined conditions], before granting further access to the publicly accessible system;"},{"label":"2.","prose":"Display references, if any, to monitoring, recording, or auditing that are consistent with privacy accommodations for such systems that generally prohibit those activities; and"},{"label":"3.","prose":"Include a description of the authorized uses of the system."}]}],"discussion":["System use notifications can be implemented using messages or warning banners displayed before individuals log in to systems. System use notifications are used only for access via logon interfaces with human users. Notifications are not required when human interfaces do not exist. Based on an assessment of risk, organizations consider whether or not a secondary system use notification is needed to access applications or other system resources after the initial network logon. Organizations consider system use notification messages or banners displayed in multiple languages based on organizational needs and the demographics of system users. Organizations consult with the privacy office for input regarding privacy messaging and the Office of the General Counsel or organizational equivalent for legal review and approval of warning banner content."],"params":[{"id":"AC-08_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined system use notification]","guideline":"system use notification message or banner to be displayed by the system to users before granting access to the system is defined"},{"id":"AC-08_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined conditions]","guideline":"conditions for system use to be displayed by the system before granting further access are defined"}],"related":["AC-14","PL-4","SI-4"],"references":[],"objectives":[{"label":"AC-08a.","prose":"[Assignment: organization-defined system use notification] is displayed to users before granting access to the system that provides privacy and security notices consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines;","items":[{"label":"AC-08a.01","prose":"the system use notification states that users are accessing a U.S. Government system;"},{"label":"AC-08a.02","prose":"the system use notification states that system usage may be monitored, recorded, and subject to audit;"},{"label":"AC-08a.03","prose":"the system use notification states that unauthorized use of the system is prohibited and subject to criminal and civil penalties; and"},{"label":"AC-08a.04","prose":"the system use notification states that use of the system indicates consent to monitoring and recording;"}]},{"label":"AC-08b.","prose":"the notification message or banner is retained on the screen until users acknowledge the usage conditions and take explicit actions to log on to or further access the system;"},{"label":"AC-08c.","prose":"","items":[{"label":"AC-08c.01","prose":"for publicly accessible systems, system use information [Assignment: organization-defined conditions] is displayed before granting further access to the publicly accessible system;"},{"label":"AC-08c.02","prose":"for publicly accessible systems, any references to monitoring, recording, or auditing that are consistent with privacy accommodations for such systems that generally prohibit those activities are displayed;"},{"label":"AC-08c.03","prose":"for publicly accessible systems, a description of the authorized uses of the system is included."}]}],"methods":[{"method":"Examine","objects":["Access control policy","privacy and security policies, procedures addressing system use notification","documented approval of system use notification messages or banners","system audit records","user acknowledgements of notification message or banner","system design documentation","system configuration settings and associated documentation","system use notification messages"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security and privacy responsibilities","legal counsel","system developers"]},{"method":"Test","objects":["Mechanisms implementing system use notification"]}]},"AC-10":{"statement":[{"prose":"Limit the number of concurrent sessions for each [Assignment: organization-defined account and/or account types] to [Assignment: organization-defined number]."}],"discussion":["Organizations may define the maximum number of concurrent sessions for system accounts globally, by account type, by account, or any combination thereof. For example, organizations may limit the number of concurrent sessions for system administrators or other individuals working in particularly sensitive domains or mission-critical applications. Concurrent session control addresses concurrent sessions for system accounts. It does not, however, address concurrent sessions by single users via multiple system accounts."],"params":[{"id":"AC-10_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined account and/or account types]","guideline":"accounts and/or account types for which to limit the number of concurrent sessions is defined"},{"id":"AC-10_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined number]","guideline":"the number of concurrent sessions to be allowed for each account and/or account type is defined"}],"related":["SC-23"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing concurrent session control","system design documentation","system configuration settings and associated documentation","security plan","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developers"]},{"method":"Test","objects":["Mechanisms implementing access control policy for concurrent session control"]}]},"AC-11":{"statement":[{"label":"a.","prose":"Prevent further access to the system by [Selection (one or more): initiating a device lock after [Assignment: organization-defined time period] of inactivity; requiring the user to initiate a device lock before leaving the system unattended]; and"},{"label":"b.","prose":"Retain the device lock until the user reestablishes access using established identification and authentication procedures."}],"discussion":["Device locks are temporary actions taken to prevent logical access to organizational systems when users stop work and move away from the immediate vicinity of those systems but do not want to log out because of the temporary nature of their absences. Device locks can be implemented at the operating system level or at the application level. A proximity lock may be used to initiate the device lock (e.g., via a Bluetooth-enabled device or dongle). User-initiated device locking is behavior or policy-based and, as such, requires users to take physical action to initiate the device lock. Device locks are not an acceptable substitute for logging out of systems, such as when organizations require users to log out at the end of workdays."],"params":[{"id":"AC-11_ODP[01]","kind":"Selection","value":"[Selection (one or more): initiating a device lock after [Assignment: organization-defined time period] of inactivity; requiring the user to initiate a device lock before leaving the system unattended]"},{"id":"AC-11_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"time period of inactivity after which a device lock is initiated is defined (if selected)"}],"related":["AC-2","AC-7","IA-11","PL-4"],"references":[],"objectives":[{"label":"AC-11a.","prose":"further access to the system is prevented by [Selection (one or more): initiating a device lock after [Assignment: organization-defined time period] of inactivity; requiring the user to initiate a device lock before leaving the system unattended];"},{"label":"AC-11b.","prose":"device lock is retained until the user re-establishes access using established identification and authentication procedures."}],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing session lock","procedures addressing identification and authentication","system design documentation","system configuration settings and associated documentation","security plan","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developers"]},{"method":"Test","objects":["Mechanisms implementing access control policy for session lock"]}]},"AC-11(1)":{"statement":[{"prose":"Conceal, via the device lock, information previously visible on the display with a publicly viewable image."}],"discussion":["The pattern-hiding display can include static or dynamic images, such as patterns used with screen savers, photographic images, solid colors, clock, battery life indicator, or a blank screen with the caveat that controlled unclassified information is not displayed."],"params":[],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing session lock","display screen with session lock activated","system design documentation","system configuration settings and associated documentation","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developers"]},{"method":"Test","objects":["System session lock mechanisms"]}]},"AC-12":{"statement":[{"prose":"Automatically terminate a user session after [Assignment: organization-defined conditions or trigger events]."}],"discussion":["Session termination addresses the termination of user-initiated logical sessions (in contrast to [SC-10](#sc-10), which addresses the termination of network connections associated with communications sessions (i.e., network disconnect)). A logical session (for local, network, and remote access) is initiated whenever a user (or process acting on behalf of a user) accesses an organizational system. Such user sessions can be terminated without terminating network sessions. Session termination ends all processes associated with a user’s logical session except for those processes that are specifically created by the user (i.e., session owner) to continue after the session is terminated. Conditions or trigger events that require automatic termination of the session include organization-defined periods of user inactivity, targeted responses to certain types of incidents, or time-of-day restrictions on system use."],"params":[{"id":"AC-12_ODP","kind":"Assignment","value":"[Assignment: organization-defined conditions or trigger events]","guideline":"conditions or trigger events requiring session disconnect are defined"}],"related":["MA-4","SC-10","SC-23"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing session termination","system design documentation","system configuration settings and associated documentation","list of conditions or trigger events requiring session disconnect","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developers"]},{"method":"Test","objects":["Automated mechanisms implementing user session termination"]}]},"AC-14":{"statement":[{"label":"a.","prose":"Identify [Assignment: organization-defined user actions] that can be performed on the system without identification or authentication consistent with organizational mission and business functions; and"},{"label":"b.","prose":"Document and provide supporting rationale in the security plan for the system, user actions not requiring identification or authentication."}],"discussion":["Specific user actions may be permitted without identification or authentication if organizations determine that identification and authentication are not required for the specified user actions. Organizations may allow a limited number of user actions without identification or authentication, including when individuals access public websites or other publicly accessible federal systems, when individuals use mobile phones to receive calls, or when facsimiles are received. Organizations identify actions that normally require identification or authentication but may, under certain circumstances, allow identification or authentication mechanisms to be bypassed. Such bypasses may occur, for example, via a software-readable physical switch that commands bypass of the logon functionality and is protected from accidental or unmonitored use. Permitting actions without identification or authentication does not apply to situations where identification and authentication have already occurred and are not repeated but rather to situations where identification and authentication have not yet occurred. Organizations may decide that there are no user actions that can be performed on organizational systems without identification and authentication, and therefore, the value for the assignment operation can be \"none.\""],"params":[{"id":"AC-14_ODP","kind":"Assignment","value":"[Assignment: organization-defined user actions]","guideline":"user actions that can be performed on the system without identification or authentication are defined"}],"related":["AC-8","IA-2","PL-2"],"references":[],"objectives":[{"label":"AC-14a.","prose":"[Assignment: organization-defined user actions] that can be performed on the system without identification or authentication consistent with organizational mission and business functions are identified;"},{"label":"AC-14b.","prose":"","items":[{"label":"AC-14b.[01]","prose":"user actions not requiring identification or authentication are documented in the security plan for the system;"},{"label":"AC-14b.[02]","prose":"a rationale for user actions not requiring identification or authentication is provided in the security plan for the system."}]}],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing permitted actions without identification or authentication","system configuration settings and associated documentation","security plan","list of user actions that can be performed without identification or authentication","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities"]}]},"AC-17":{"statement":[{"label":"a.","prose":"Establish and document usage restrictions, configuration/connection requirements, and implementation guidance for each type of remote access allowed; and"},{"label":"b.","prose":"Authorize each type of remote access to the system prior to allowing such connections."}],"discussion":["Remote access is access to organizational systems (or processes acting on behalf of users) that communicate through external networks such as the Internet. Types of remote access include dial-up, broadband, and wireless. Organizations use encrypted virtual private networks (VPNs) to enhance confidentiality and integrity for remote connections. The use of encrypted VPNs provides sufficient assurance to the organization that it can effectively treat such connections as internal networks if the cryptographic mechanisms used are implemented in accordance with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Still, VPN connections traverse external networks, and the encrypted VPN does not enhance the availability of remote connections. VPNs with encrypted tunnels can also affect the ability to adequately monitor network communications traffic for malicious code. Remote access controls apply to systems other than public web servers or systems designed for public access. Authorization of each remote access type addresses authorization prior to allowing remote access without specifying the specific formats for such authorization. While organizations may use information exchange and system connection security agreements to manage remote access connections to other systems, such agreements are addressed as part of [CA-3](#ca-3). Enforcing access restrictions for remote access is addressed via [AC-3](#ac-3)."],"params":[],"related":["AC-2","AC-3","AC-4","AC-18","AC-19","AC-20","CA-3","CM-10","IA-2","IA-3","IA-8","MA-4","PE-17","PL-2","PL-4","SC-10","SC-12","SC-13","SI-4"],"references":[{"title":"SP 800-46","url":"https://doi.org/10.6028/NIST.SP.800-46r2"},{"title":"SP 800-77","url":"https://doi.org/10.6028/NIST.SP.800-77r1"},{"title":"SP 800-113","url":"https://doi.org/10.6028/NIST.SP.800-113"},{"title":"SP 800-114","url":"https://doi.org/10.6028/NIST.SP.800-114r1"},{"title":"SP 800-121","url":"https://doi.org/10.6028/NIST.SP.800-121r2"},{"title":"IR 7966","url":"https://doi.org/10.6028/NIST.IR.7966"}],"objectives":[{"label":"AC-17a.","prose":"","items":[{"label":"AC-17a.[01]","prose":"usage restrictions are established and documented for each type of remote access allowed;"},{"label":"AC-17a.[02]","prose":"configuration/connection requirements are established and documented for each type of remote access allowed;"},{"label":"AC-17a.[03]","prose":"implementation guidance is established and documented for each type of remote access allowed;"}]},{"label":"AC-17b.","prose":"each type of remote access to the system is authorized prior to allowing such connections."}],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing remote access implementation and usage (including restrictions)","configuration management plan","system configuration settings and associated documentation","remote access authorizations","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for managing remote access connections","system/network administrators","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Remote access management capability for the system"]}]},"AC-17(1)":{"statement":[{"prose":"Employ automated mechanisms to monitor and control remote access methods."}],"discussion":["Monitoring and control of remote access methods allows organizations to detect attacks and help ensure compliance with remote access policies by auditing the connection activities of remote users on a variety of system components, including servers, notebook computers, workstations, smart phones, and tablets. Audit logging for remote access is enforced by [AU-2](#au-2). Audit events are defined in [AU-2a](#au-2_smt.a)."],"params":[],"related":["AU-2","AU-6","AU-12","AU-14"],"references":[],"objectives":[{"label":"AC-17(01)[01]","prose":"automated mechanisms are employed to monitor remote access methods;"},{"label":"AC-17(01)[02]","prose":"automated mechanisms are employed to control remote access methods."}],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing remote access to the system","system design documentation","system configuration settings and associated documentation","system audit records","system monitoring records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developers"]},{"method":"Test","objects":["Automated mechanisms monitoring and controlling remote access methods"]}]},"AC-17(2)":{"statement":[{"prose":"Implement cryptographic mechanisms to protect the confidentiality and integrity of remote access sessions."}],"discussion":["Virtual private networks can be used to protect the confidentiality and integrity of remote access sessions. Transport Layer Security (TLS) is an example of a cryptographic protocol that provides end-to-end communications security over networks and is used for Internet communications and online transactions."],"params":[],"related":["SC-8","SC-12","SC-13"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing remote access to the system","system design documentation","system configuration settings and associated documentation","cryptographic mechanisms and associated configuration documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developers"]},{"method":"Test","objects":["Cryptographic mechanisms protecting confidentiality and integrity of remote access sessions"]}]},"AC-17(3)":{"statement":[{"prose":"Route remote accesses through authorized and managed network access control points."}],"discussion":["Organizations consider the Trusted Internet Connections (TIC) initiative [DHS TIC](#4f42ee6e-86cc-403b-a51f-76c2b4f81b54) requirements for external network connections since limiting the number of access control points for remote access reduces attack surfaces."],"params":[],"related":["SC-7"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing remote access to the system","system design documentation","list of all managed network access control points","system configuration settings and associated documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Mechanisms routing all remote accesses through managed network access control points"]}]},"AC-17(4)":{"statement":[{"label":"(a)","prose":"Authorize the execution of privileged commands and access to security-relevant information via remote access only in a format that provides assessable evidence and for the following needs: [Assignment: organization-defined needs]; and"},{"label":"(b)","prose":"Document the rationale for remote access in the security plan for the system."}],"discussion":["Remote access to systems represents a significant potential vulnerability that can be exploited by adversaries. As such, restricting the execution of privileged commands and access to security-relevant information via remote access reduces the exposure of the organization and the susceptibility to threats by adversaries to the remote access capability."],"params":[{"id":"AC-17.4_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined needs]"},{"id":"AC-17(04)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined needs requiring remote access]","guideline":"needs requiring execution of privileged commands via remote access are defined"},{"id":"AC-17(04)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined needs requiring remote access]","guideline":"needs requiring access to security-relevant information via remote access are defined"}],"related":["AC-6","SC-12","SC-13"],"references":[],"objectives":[{"label":"AC-17(04)(a)","prose":"","items":[{"label":"AC-17(04)(a)[01]","prose":"the execution of privileged commands via remote access is authorized only in a format that provides assessable evidence;"},{"label":"AC-17(04)(a)[02]","prose":"access to security-relevant information via remote access is authorized only in a format that provides assessable evidence;"},{"label":"AC-17(04)(a)[03]","prose":"the execution of privileged commands via remote access is authorized only for the following needs: [Assignment: organization-defined needs requiring remote access];"},{"label":"AC-17(04)(a)[04]","prose":"access to security-relevant information via remote access is authorized only for the following needs: [Assignment: organization-defined needs requiring remote access];"}]},{"label":"AC-17(04)(b)","prose":"the rationale for remote access is documented in the security plan for the system."}],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing remote access to the system","system configuration settings and associated documentation","security plan","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Mechanisms implementing remote access management"]}]},"AC-18":{"statement":[{"label":"a.","prose":"Establish configuration requirements, connection requirements, and implementation guidance for each type of wireless access; and"},{"label":"b.","prose":"Authorize each type of wireless access to the system prior to allowing such connections."}],"discussion":["Wireless technologies include microwave, packet radio (ultra-high frequency or very high frequency), 802.11x, and Bluetooth. Wireless networks use authentication protocols that provide authenticator protection and mutual authentication."],"params":[],"related":["AC-2","AC-3","AC-17","AC-19","CA-9","CM-7","IA-2","IA-3","IA-8","PL-4","SC-40","SC-43","SI-4"],"references":[{"title":"SP 800-94","url":"https://doi.org/10.6028/NIST.SP.800-94"},{"title":"SP 800-97","url":"https://doi.org/10.6028/NIST.SP.800-97"}],"objectives":[{"label":"AC-18a.","prose":"","items":[{"label":"AC-18a.[01]","prose":"configuration requirements are established for each type of wireless access;"},{"label":"AC-18a.[02]","prose":"connection requirements are established for each type of wireless access;"},{"label":"AC-18a.[03]","prose":"implementation guidance is established for each type of wireless access;"}]},{"label":"AC-18b.","prose":"each type of wireless access to the system is authorized prior to allowing such connections."}],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing wireless access implementation and usage (including restrictions)","configuration management plan","system design documentation","system configuration settings and associated documentation","wireless access authorizations","system audit records","system security plan"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for managing wireless access connections","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Wireless access management capability for the system"]}]},"AC-18(1)":{"statement":[{"prose":"Protect wireless access to the system using authentication of [Selection (one or more): users; devices] and encryption."}],"discussion":["Wireless networking capabilities represent a significant potential vulnerability that can be exploited by adversaries. To protect systems with wireless access points, strong authentication of users and devices along with strong encryption can reduce susceptibility to threats by adversaries involving wireless technologies."],"params":[{"id":"AC-18(01)_ODP","kind":"Selection","value":"[Selection (one or more): users; devices]"}],"related":["SC-8","SC-12","SC-13"],"references":[],"objectives":[{"label":"AC-18(01)[01]","prose":"wireless access to the system is protected using authentication of [Selection (one or more): users; devices];"},{"label":"AC-18(01)[02]","prose":"wireless access to the system is protected using encryption."}],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing wireless implementation and usage (including restrictions)","system design documentation","system configuration settings and associated documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developers"]},{"method":"Test","objects":["Mechanisms implementing wireless access protections to the system"]}]},"AC-18(3)":{"statement":[{"prose":"Disable, when not intended for use, wireless networking capabilities embedded within system components prior to issuance and deployment."}],"discussion":["Wireless networking capabilities that are embedded within system components represent a significant potential vulnerability that can be exploited by adversaries. Disabling wireless capabilities when not needed for essential organizational missions or functions can reduce susceptibility to threats by adversaries involving wireless technologies."],"params":[],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing wireless implementation and usage (including restrictions)","system design documentation","system configuration settings and associated documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Mechanisms managing the disabling of wireless networking capabilities internally embedded within system components"]}]},"AC-18(4)":{"statement":[{"prose":"Identify and explicitly authorize users allowed to independently configure wireless networking capabilities."}],"discussion":["Organizational authorizations to allow selected users to configure wireless networking capabilities are enforced, in part, by the access enforcement mechanisms employed within organizational systems."],"params":[],"related":["SC-7","SC-15"],"references":[],"objectives":[{"label":"AC-18(04)[01]","prose":"users allowed to independently configure wireless networking capabilities are identified;"},{"label":"AC-18(04)[02]","prose":"users allowed to independently configure wireless networking capabilities are explicitly authorized."}],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing wireless implementation and usage (including restrictions)","system design documentation","system configuration settings and associated documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Mechanisms authorizing independent user configuration of wireless networking capabilities"]}]},"AC-18(5)":{"statement":[{"prose":"Select radio antennas and calibrate transmission power levels to reduce the probability that signals from wireless access points can be received outside of organization-controlled boundaries."}],"discussion":["Actions that may be taken to limit unauthorized use of wireless communications outside of organization-controlled boundaries include reducing the power of wireless transmissions so that the transmissions are less likely to emit a signal that can be captured outside of the physical perimeters of the organization, employing measures such as emissions security to control wireless emanations, and using directional or beamforming antennas that reduce the likelihood that unintended receivers will be able to intercept signals. Prior to taking such mitigating actions, organizations can conduct periodic wireless surveys to understand the radio frequency profile of organizational systems as well as other systems that may be operating in the area."],"params":[],"related":["PE-19"],"references":[],"objectives":[{"label":"AC-18(05)[01]","prose":"radio antennas are selected to reduce the probability that signals from wireless access points can be received outside of organization-controlled boundaries;"},{"label":"AC-18(05)[02]","prose":"transmission power levels are calibrated to reduce the probability that signals from wireless access points can be received outside of organization-controlled boundaries."}],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing wireless implementation and usage (including restrictions)","system design documentation","system configuration settings and associated documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Calibration of transmission power levels for wireless access","radio antenna signals for wireless access","wireless access reception outside of organization-controlled boundaries"]}]},"AC-19":{"statement":[{"label":"a.","prose":"Establish configuration requirements, connection requirements, and implementation guidance for organization-controlled mobile devices, to include when such devices are outside of controlled areas; and"},{"label":"b.","prose":"Authorize the connection of mobile devices to organizational systems."}],"discussion":["A mobile device is a computing device that has a small form factor such that it can easily be carried by a single individual; is designed to operate without a physical connection; possesses local, non-removable or removable data storage; and includes a self-contained power source. Mobile device functionality may also include voice communication capabilities, on-board sensors that allow the device to capture information, and/or built-in features for synchronizing local data with remote locations. Examples include smart phones and tablets. Mobile devices are typically associated with a single individual. The processing, storage, and transmission capability of the mobile device may be comparable to or merely a subset of notebook/desktop systems, depending on the nature and intended purpose of the device. Protection and control of mobile devices is behavior or policy-based and requires users to take physical action to protect and control such devices when outside of controlled areas. Controlled areas are spaces for which organizations provide physical or procedural controls to meet the requirements established for protecting information and systems.","Due to the large variety of mobile devices with different characteristics and capabilities, organizational restrictions may vary for the different classes or types of such devices. Usage restrictions and specific implementation guidance for mobile devices include configuration management, device identification and authentication, implementation of mandatory protective software, scanning devices for malicious code, updating virus protection software, scanning for critical software updates and patches, conducting primary operating system (and possibly other resident software) integrity checks, and disabling unnecessary hardware.","Usage restrictions and authorization to connect may vary among organizational systems. For example, the organization may authorize the connection of mobile devices to its network and impose a set of usage restrictions, while a system owner may withhold authorization for mobile device connection to specific applications or impose additional usage restrictions before allowing mobile device connections to a system. Adequate security for mobile devices goes beyond the requirements specified in [AC-19](#ac-19). Many safeguards for mobile devices are reflected in other controls. [AC-20](#ac-20) addresses mobile devices that are not organization-controlled."],"params":[],"related":["AC-3","AC-4","AC-7","AC-11","AC-17","AC-18","AC-20","CA-9","CM-2","CM-6","IA-2","IA-3","MP-2","MP-4","MP-5","MP-7","PL-4","SC-7","SC-34","SC-43","SI-3","SI-4"],"references":[{"title":"SP 800-114","url":"https://doi.org/10.6028/NIST.SP.800-114r1"},{"title":"SP 800-124","url":"https://doi.org/10.6028/NIST.SP.800-124r1"}],"objectives":[{"label":"AC-19a.","prose":"","items":[{"label":"AC-19a.[01]","prose":"configuration requirements are established for organization-controlled mobile devices, including when such devices are outside of the controlled area;"},{"label":"AC-19a.[02]","prose":"connection requirements are established for organization-controlled mobile devices, including when such devices are outside of the controlled area;"},{"label":"AC-19a.[03]","prose":"implementation guidance is established for organization-controlled mobile devices, including when such devices are outside of the controlled area;"}]},{"label":"AC-19b.","prose":"the connection of mobile devices to organizational systems is authorized."}],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing access control for mobile device usage (including restrictions)","configuration management plan","system design documentation","system configuration settings and associated documentation","authorizations for mobile device connections to organizational systems","system audit records","system security plan"]},{"method":"Interview","objects":["Organizational personnel using mobile devices to access organizational systems","system/network administrators","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Access control capability for mobile device connections to organizational systems","configurations of mobile devices"]}]},"AC-19(5)":{"statement":[{"prose":"Employ [Selection: full-device encryption; container-based encryption] to protect the confidentiality and integrity of information on [Assignment: organization-defined mobile devices]."}],"discussion":["Container-based encryption provides a more fine-grained approach to data and information encryption on mobile devices, including encrypting selected data structures such as files, records, or fields."],"params":[{"id":"AC-19(05)_ODP[01]","kind":"Selection","value":"[Selection: full-device encryption; container-based encryption]"},{"id":"AC-19(05)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined mobile devices]","guideline":"mobile devices on which to employ encryption are defined"}],"related":["SC-12","SC-13","SC-28"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing access control for mobile devices","system design documentation","system configuration settings and associated documentation","encryption mechanisms and associated configuration documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with access control responsibilities for mobile devices","system/network administrators","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Encryption mechanisms protecting confidentiality and integrity of information on mobile devices"]}]},"AC-20":{"statement":[{"label":"a.","prose":"[Selection (one or more): establish [Assignment: organization-defined terms and conditions]; identify [Assignment: organization-defined controls asserted]], consistent with the trust relationships established with other organizations owning, operating, and/or maintaining external systems, allowing authorized individuals to:","items":[{"label":"1.","prose":"Access the system from external systems; and"},{"label":"2.","prose":"Process, store, or transmit organization-controlled information using external systems; or"}]},{"label":"b.","prose":"Prohibit the use of [Assignment: organization-defined prohibited types of external systems]."}],"discussion":["External systems are systems that are used by but not part of organizational systems, and for which the organization has no direct control over the implementation of required controls or the assessment of control effectiveness. External systems include personally owned systems, components, or devices; privately owned computing and communications devices in commercial or public facilities; systems owned or controlled by nonfederal organizations; systems managed by contractors; and federal information systems that are not owned by, operated by, or under the direct supervision or authority of the organization. External systems also include systems owned or operated by other components within the same organization and systems within the organization with different authorization boundaries. Organizations have the option to prohibit the use of any type of external system or prohibit the use of specified types of external systems, (e.g., prohibit the use of any external system that is not organizationally owned or prohibit the use of personally-owned systems).","For some external systems (i.e., systems operated by other organizations), the trust relationships that have been established between those organizations and the originating organization may be such that no explicit terms and conditions are required. Systems within these organizations may not be considered external. These situations occur when, for example, there are pre-existing information exchange agreements (either implicit or explicit) established between organizations or components or when such agreements are specified by applicable laws, executive orders, directives, regulations, policies, or standards. Authorized individuals include organizational personnel, contractors, or other individuals with authorized access to organizational systems and over which organizations have the authority to impose specific rules of behavior regarding system access. Restrictions that organizations impose on authorized individuals need not be uniform, as the restrictions may vary depending on trust relationships between organizations. Therefore, organizations may choose to impose different security restrictions on contractors than on state, local, or tribal governments.","External systems used to access public interfaces to organizational systems are outside the scope of [AC-20](#ac-20). Organizations establish specific terms and conditions for the use of external systems in accordance with organizational security policies and procedures. At a minimum, terms and conditions address the specific types of applications that can be accessed on organizational systems from external systems and the highest security category of information that can be processed, stored, or transmitted on external systems. If the terms and conditions with the owners of the external systems cannot be established, organizations may impose restrictions on organizational personnel using those external systems."],"params":[{"id":"AC-20_ODP[01]","kind":"Selection","value":"[Selection (one or more): establish [Assignment: organization-defined terms and conditions]; identify [Assignment: organization-defined controls asserted]]"},{"id":"AC-20_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined terms and conditions]","guideline":"terms and conditions consistent with the trust relationships established with other organizations owning, operating, and/or maintaining external systems are defined (if selected)"},{"id":"AC-20_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined controls asserted]","guideline":"controls asserted to be implemented on external systems consistent with the trust relationships established with other organizations owning, operating, and/or maintaining external systems are defined (if selected)"},{"id":"AC-20_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined prohibited types of external systems]","guideline":"types of external systems prohibited from use are defined"}],"related":["AC-2","AC-3","AC-17","AC-19","CA-3","PL-2","PL-4","SA-9","SC-7"],"references":[{"title":"FIPS 199","url":"https://doi.org/10.6028/NIST.FIPS.199"},{"title":"SP 800-171","url":"https://doi.org/10.6028/NIST.SP.800-171r2"},{"title":"SP 800-172","url":"https://doi.org/10.6028/NIST.SP.800-172-draft"}],"objectives":[{"label":"AC-20a.","prose":"","items":[{"label":"AC-20a.01","prose":"[Selection (one or more): establish [Assignment: organization-defined terms and conditions]; identify [Assignment: organization-defined controls asserted]] is/are consistent with the trust relationships established with other organizations owning, operating, and/or maintaining external systems, allowing authorized individuals to access the system from external systems (if applicable);"},{"label":"AC-20a.02","prose":"[Selection (one or more): establish [Assignment: organization-defined terms and conditions]; identify [Assignment: organization-defined controls asserted]] is/are consistent with the trust relationships established with other organizations owning, operating, and/or maintaining external systems, allowing authorized individuals to process, store, or transmit organization-controlled information using external systems (if applicable);"}]},{"label":"AC-20b.","prose":"the use of [Assignment: organization-defined prohibited types of external systems] is prohibited (if applicable)."}],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing the use of external systems","external systems terms and conditions","list of types of applications accessible from external systems","maximum security categorization for information processed, stored, or transmitted on external systems","system configuration settings and associated documentation","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for defining terms and conditions for use of external systems to access organizational systems","system/network administrators","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Mechanisms implementing terms and conditions on the use of external systems"]}]},"AC-20(1)":{"statement":[{"prose":"Permit authorized individuals to use an external system to access the system or to process, store, or transmit organization-controlled information only after:"},{"label":"(a)","prose":"Verification of the implementation of controls on the external system as specified in the organization’s security and privacy policies and security and privacy plans; or"},{"label":"(b)","prose":"Retention of approved system connection or processing agreements with the organizational entity hosting the external system."}],"discussion":["Limiting authorized use recognizes circumstances where individuals using external systems may need to access organizational systems. Organizations need assurance that the external systems contain the necessary controls so as not to compromise, damage, or otherwise harm organizational systems. Verification that the required controls have been implemented can be achieved by external, independent assessments, attestations, or other means, depending on the confidence level required by organizations."],"params":[],"related":["CA-2"],"references":[],"objectives":[{"label":"AC-20(01)(a)","prose":"authorized individuals are permitted to use an external system to access the system or to process, store, or transmit organization-controlled information only after verification of the implementation of controls on the external system as specified in the organization’s security and privacy policies and security and privacy plans (if applicable);"},{"label":"AC-20(01)(b)","prose":"authorized individuals are permitted to use an external system to access the system or to process, store, or transmit organization-controlled information only after retention of approved system connection or processing agreements with the organizational entity hosting the external system (if applicable)."}],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing the use of external systems","system connection or processing agreements","account management documents","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Mechanisms implementing limits on use of external systems"]}]},"AC-20(2)":{"statement":[{"prose":"Restrict the use of organization-controlled portable storage devices by authorized individuals on external systems using [Assignment: organization-defined restrictions]."}],"discussion":["Limits on the use of organization-controlled portable storage devices in external systems include restrictions on how the devices may be used and under what conditions the devices may be used."],"params":[{"id":"AC-20(02)_ODP","kind":"Assignment","value":"[Assignment: organization-defined restrictions]","guideline":"restrictions on the use of organization-controlled portable storage devices by authorized individuals on external systems are defined"}],"related":["MP-7","SC-41"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing the use of external systems","system configuration settings and associated documentation","system connection or processing agreements","account management documents","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for restricting or prohibiting the use of organization-controlled storage devices on external systems","system/network administrators","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Mechanisms implementing restrictions on the use of portable storage devices"]}]},"AC-21":{"statement":[{"label":"a.","prose":"Enable authorized users to determine whether access authorizations assigned to a sharing partner match the information’s access and use restrictions for [Assignment: organization-defined information-sharing circumstances]; and"},{"label":"b.","prose":"Employ [Assignment: organization-defined automated mechanisms] to assist users in making information sharing and collaboration decisions."}],"discussion":["Information sharing applies to information that may be restricted in some manner based on some formal or administrative determination. Examples of such information include, contract-sensitive information, classified information related to special access programs or compartments, privileged information, proprietary information, and personally identifiable information. Security and privacy risk assessments as well as applicable laws, regulations, and policies can provide useful inputs to these determinations. Depending on the circumstances, sharing partners may be defined at the individual, group, or organizational level. Information may be defined by content, type, security category, or special access program or compartment. Access restrictions may include non-disclosure agreements (NDA). Information flow techniques and security attributes may be used to provide automated assistance to users making sharing and collaboration decisions."],"params":[{"id":"AC-21_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined information-sharing circumstances]","guideline":"information-sharing circumstances where user discretion is required to determine whether access authorizations assigned to a sharing partner match the information’s access and use restrictions are defined"},{"id":"AC-21_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms or manual processes that assist users in making information-sharing and collaboration decisions are defined"}],"related":["AC-3","AC-4","AC-16","PT-2","PT-7","RA-3","SC-15"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-150","url":"https://doi.org/10.6028/NIST.SP.800-150"},{"title":"IR 8062","url":"https://doi.org/10.6028/NIST.IR.8062"}],"objectives":[{"label":"AC-21a.","prose":"authorized users are enabled to determine whether access authorizations assigned to a sharing partner match the information’s access and use restrictions for [Assignment: organization-defined information-sharing circumstances];"},{"label":"AC-21b.","prose":"[Assignment: organization-defined automated mechanisms] are employed to assist users in making information-sharing and collaboration decisions."}],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing user-based collaboration and information sharing (including restrictions)","system design documentation","system configuration settings and associated documentation","list of users authorized to make information-sharing/collaboration decisions","list of information-sharing circumstances requiring user discretion","non-disclosure agreements","acquisitions/contractual agreements"]},{"method":"Interview","objects":["Organizational personnel responsible for information-sharing/collaboration decisions","organizational personnel with responsibility for acquisitions/contractual agreements","system/network administrators","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Automated mechanisms or manual process implementing access authorizations supporting information-sharing/user collaboration decisions"]}]},"AC-22":{"statement":[{"label":"a.","prose":"Designate individuals authorized to make information publicly accessible;"},{"label":"b.","prose":"Train authorized individuals to ensure that publicly accessible information does not contain nonpublic information;"},{"label":"c.","prose":"Review the proposed content of information prior to posting onto the publicly accessible system to ensure that nonpublic information is not included; and"},{"label":"d.","prose":"Review the content on the publicly accessible system for nonpublic information [Assignment: organization-defined frequency] and remove such information, if discovered."}],"discussion":["In accordance with applicable laws, executive orders, directives, policies, regulations, standards, and guidelines, the public is not authorized to have access to nonpublic information, including information protected under the [PRIVACT](#18e71fec-c6fd-475a-925a-5d8495cf8455) and proprietary information. Publicly accessible content addresses systems that are controlled by the organization and accessible to the public, typically without identification or authentication. Posting information on non-organizational systems (e.g., non-organizational public websites, forums, and social media) is covered by organizational policy. While organizations may have individuals who are responsible for developing and implementing policies about the information that can be made publicly accessible, publicly accessible content addresses the management of the individuals who make such information publicly accessible."],"params":[{"id":"AC-22_ODP","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to review the content on the publicly accessible system for non-public information is defined"}],"related":["AC-3","AT-2","AT-3","AU-13"],"references":[{"title":"PRIVACT","url":"https://www.govinfo.gov/content/pkg/STATUTE-88/pdf/STATUTE-88-Pg1896.pdf"}],"objectives":[{"label":"AC-22a.","prose":"designated individuals are authorized to make information publicly accessible;"},{"label":"AC-22b.","prose":"authorized individuals are trained to ensure that publicly accessible information does not contain non-public information;"},{"label":"AC-22c.","prose":"the proposed content of information is reviewed prior to posting onto the publicly accessible system to ensure that non-public information is not included;"},{"label":"AC-22d.","prose":"","items":[{"label":"AC-22d.[01]","prose":"the content on the publicly accessible system is reviewed for non-public information [Assignment: organization-defined frequency];"},{"label":"AC-22d.[02]","prose":"non-public information is removed from the publicly accessible system, if discovered."}]}],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing publicly accessible content","list of users authorized to post publicly accessible content on organizational systems","training materials and/or records","records of publicly accessible information reviews","records of response to non-public information on public websites","system audit logs","security awareness training records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for managing publicly accessible information posted on organizational systems","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Mechanisms implementing management of publicly accessible content"]}]},"AT-1":{"statement":[{"label":"a.","prose":"Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:","items":[{"label":"1.","prose":"[Selection (one or more): organization-level; mission/business process-level; system-level] awareness and training policy that:","items":[{"label":"(a)","prose":"Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and"},{"label":"(b)","prose":"Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and"}]},{"label":"2.","prose":"Procedures to facilitate the implementation of the awareness and training policy and the associated awareness and training controls;"}]},{"label":"b.","prose":"Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the awareness and training policy and procedures; and"},{"label":"c.","prose":"Review and update the current awareness and training:","items":[{"label":"1.","prose":"Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and"},{"label":"2.","prose":"Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]."}]}],"discussion":["Awareness and training policy and procedures address the controls in the AT family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of awareness and training policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to awareness and training policy and procedures include assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure."],"params":[{"id":"AT-1_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]"},{"id":"AT-01_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the awareness and training policy is to be disseminated is/are defined"},{"id":"AT-01_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the awareness and training procedures are to be disseminated is/are defined"},{"id":"AT-01_ODP[03]","kind":"Selection","value":"[Selection (one or more): organization-level; mission/business process-level; system-level]"},{"id":"AT-01_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined official]","guideline":"an official to manage the awareness and training policy and procedures is defined"},{"id":"AT-01_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current awareness and training policy is reviewed and updated is defined"},{"id":"AT-01_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require the current awareness and training policy to be reviewed and updated are defined"},{"id":"AT-01_ODP[07]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current awareness and training procedures are reviewed and updated is defined"},{"id":"AT-01_ODP[08]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require procedures to be reviewed and updated are defined"}],"related":["PM-9","PS-8","SI-12"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-12","url":"https://doi.org/10.6028/NIST.SP.800-12r1"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-39","url":"https://doi.org/10.6028/NIST.SP.800-39"},{"title":"SP 800-50","url":"https://doi.org/10.6028/NIST.SP.800-50"},{"title":"SP 800-100","url":"https://doi.org/10.6028/NIST.SP.800-100"}],"objectives":[{"label":"AT-01a.","prose":"","items":[{"label":"AT-01a.[01]","prose":"an awareness and training policy is developed and documented;"},{"label":"AT-01a.[02]","prose":"the awareness and training policy is disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"AT-01a.[03]","prose":"awareness and training procedures to facilitate the implementation of the awareness and training policy and associated access controls are developed and documented;"},{"label":"AT-01a.[04]","prose":"the awareness and training procedures are disseminated to [Assignment: organization-defined personnel or roles]."},{"label":"AT-01a.01","prose":"","items":[{"label":"AT-01a.01(a)","prose":"","items":[{"label":"AT-01a.01(a)[01]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] awareness and training policy addresses purpose;"},{"label":"AT-01a.01(a)[02]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] awareness and training policy addresses scope;"},{"label":"AT-01a.01(a)[03]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] awareness and training policy addresses roles;"},{"label":"AT-01a.01(a)[04]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] awareness and training policy addresses responsibilities;"},{"label":"AT-01a.01(a)[05]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] awareness and training policy addresses management commitment;"},{"label":"AT-01a.01(a)[06]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] awareness and training policy addresses coordination among organizational entities;"},{"label":"AT-01a.01(a)[07]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] awareness and training policy addresses compliance; and"}]},{"label":"AT-01a.01(b)","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] awareness and training policy is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines; and"}]}]},{"label":"AT-01b.","prose":"the [Assignment: organization-defined official] is designated to manage the development, documentation, and dissemination of the awareness and training policy and procedures;"},{"label":"AT-01c.","prose":"","items":[{"label":"AT-01c.01","prose":"","items":[{"label":"AT-01c.01[01]","prose":"the current awareness and training policy is reviewed and updated [Assignment: organization-defined frequency];"},{"label":"AT-01c.01[02]","prose":"the current awareness and training policy is reviewed and updated following [Assignment: organization-defined events];"}]},{"label":"AT-01c.02","prose":"","items":[{"label":"AT-01c.02[01]","prose":"the current awareness and training procedures are reviewed and updated [Assignment: organization-defined frequency];"},{"label":"AT-01c.02[02]","prose":"the current awareness and training procedures are reviewed and updated following [Assignment: organization-defined events]."}]}]}],"methods":[{"method":"Examine","objects":["System security plan","privacy plan","awareness and training policy and procedures","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with awareness and training responsibilities","organizational personnel with information security and privacy responsibilities"]}]},"AT-2":{"statement":[{"label":"a.","prose":"Provide security and privacy literacy training to system users (including managers, senior executives, and contractors):","items":[{"label":"1.","prose":"As part of initial training for new users and [Assignment: organization-defined frequency] thereafter; and"},{"label":"2.","prose":"When required by system changes or following [Assignment: organization-defined events];"}]},{"label":"b.","prose":"Employ the following techniques to increase the security and privacy awareness of system users [Assignment: organization-defined awareness techniques];"},{"label":"c.","prose":"Update literacy training and awareness content [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and"},{"label":"d.","prose":"Incorporate lessons learned from internal or external security incidents or breaches into literacy training and awareness techniques."}],"discussion":["Organizations provide basic and advanced levels of literacy training to system users, including measures to test the knowledge level of users. Organizations determine the content of literacy training and awareness based on specific organizational requirements, the systems to which personnel have authorized access, and work environments (e.g., telework). The content includes an understanding of the need for security and privacy as well as actions by users to maintain security and personal privacy and to respond to suspected incidents. The content addresses the need for operations security and the handling of personally identifiable information.","Awareness techniques include displaying posters, offering supplies inscribed with security and privacy reminders, displaying logon screen messages, generating email advisories or notices from organizational officials, and conducting awareness events. Literacy training after the initial training described in [AT-2a.1](#at-2_smt.a.1) is conducted at a minimum frequency consistent with applicable laws, directives, regulations, and policies. Subsequent literacy training may be satisfied by one or more short ad hoc sessions and include topical information on recent attack schemes, changes to organizational security and privacy policies, revised security and privacy expectations, or a subset of topics from the initial training. Updating literacy training and awareness content on a regular basis helps to ensure that the content remains relevant. Events that may precipitate an update to literacy training and awareness content include, but are not limited to, assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines."],"params":[{"id":"AT-2_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined frequency]"},{"id":"AT-2_PRM_2","kind":"Assignment","value":"[Assignment: organization-defined events]"},{"id":"AT-02_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to provide security literacy training to system users (including managers, senior executives, and contractors) after initial training is defined"},{"id":"AT-02_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to provide privacy literacy training to system users (including managers, senior executives, and contractors) after initial training is defined"},{"id":"AT-02_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that require security literacy training for system users are defined"},{"id":"AT-02_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that require privacy literacy training for system users are defined"},{"id":"AT-02_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined awareness techniques]","guideline":"techniques to be employed to increase the security and privacy awareness of system users are defined"},{"id":"AT-02_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to update literacy training and awareness content is defined"},{"id":"AT-02_ODP[07]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require literacy training and awareness content to be updated are defined"}],"related":["AC-3","AC-17","AC-22","AT-3","AT-4","CP-3","IA-4","IR-2","IR-7","IR-9","PL-4","PM-13","PM-21","PS-7","PT-2","SA-8","SA-16"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-50","url":"https://doi.org/10.6028/NIST.SP.800-50"},{"title":"SP 800-160-2","url":"https://doi.org/10.6028/NIST.SP.800-160v2"},{"title":"SP 800-181","url":"https://doi.org/10.6028/NIST.SP.800-181r1"},{"title":"ODNI CTF","url":"https://www.dni.gov/index.php/cyber-threat-framework"}],"objectives":[{"label":"AT-02a.","prose":"","items":[{"label":"AT-02a.01","prose":"","items":[{"label":"AT-02a.01[01]","prose":"security literacy training is provided to system users (including managers, senior executives, and contractors) as part of initial training for new users;"},{"label":"AT-02a.01[02]","prose":"privacy literacy training is provided to system users (including managers, senior executives, and contractors) as part of initial training for new users;"},{"label":"AT-02a.01[03]","prose":"security literacy training is provided to system users (including managers, senior executives, and contractors) [Assignment: organization-defined frequency] thereafter;"},{"label":"AT-02a.01[04]","prose":"privacy literacy training is provided to system users (including managers, senior executives, and contractors) [Assignment: organization-defined frequency] thereafter;"}]},{"label":"AT-02a.02","prose":"","items":[{"label":"AT-02a.02[01]","prose":"security literacy training is provided to system users (including managers, senior executives, and contractors) when required by system changes or following [Assignment: organization-defined events];"},{"label":"AT-02a.02[02]","prose":"privacy literacy training is provided to system users (including managers, senior executives, and contractors) when required by system changes or following [Assignment: organization-defined events];"}]}]},{"label":"AT-02b.","prose":"[Assignment: organization-defined awareness techniques] are employed to increase the security and privacy awareness of system users;"},{"label":"AT-02c.","prose":"","items":[{"label":"AT-02c.[01]","prose":"literacy training and awareness content is updated [Assignment: organization-defined frequency];"},{"label":"AT-02c.[02]","prose":"literacy training and awareness content is updated following [Assignment: organization-defined events];"}]},{"label":"AT-02d.","prose":"lessons learned from internal or external security incidents or breaches are incorporated into literacy training and awareness techniques."}],"methods":[{"method":"Examine","objects":["System security plan","privacy plan","literacy training and awareness policy","procedures addressing literacy training and awareness implementation","appropriate codes of federal regulations","security and privacy literacy training curriculum","security and privacy literacy training materials","training records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for literacy training and awareness","organizational personnel with information security and privacy responsibilities","organizational personnel comprising the general system user community"]},{"method":"Test","objects":["Mechanisms managing information security and privacy literacy training"]}]},"AT-2(2)":{"statement":[{"prose":"Provide literacy training on recognizing and reporting potential indicators of insider threat."}],"discussion":["Potential indicators and possible precursors of insider threat can include behaviors such as inordinate, long-term job dissatisfaction; attempts to gain access to information not required for job performance; unexplained access to financial resources; bullying or harassment of fellow employees; workplace violence; and other serious violations of policies, procedures, directives, regulations, rules, or practices. Literacy training includes how to communicate the concerns of employees and management regarding potential indicators of insider threat through channels established by the organization and in accordance with established policies and procedures. Organizations may consider tailoring insider threat awareness topics to the role. For example, training for managers may be focused on changes in the behavior of team members, while training for employees may be focused on more general observations."],"params":[],"related":["PM-12"],"references":[],"objectives":[{"label":"AT-02(02)[01]","prose":"literacy training on recognizing potential indicators of insider threat is provided;"},{"label":"AT-02(02)[02]","prose":"literacy training on reporting potential indicators of insider threat is provided."}],"methods":[{"method":"Examine","objects":["System security plan","privacy plan","literacy training and awareness policy","procedures addressing literacy training and awareness implementation","literacy training and awareness curriculum","literacy training and awareness materials","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel who receive literacy training and awareness","organizational personnel with responsibilities for literacy training and awareness","organizational personnel with information security and privacy responsibilities"]}]},"AT-2(3)":{"statement":[{"prose":"Provide literacy training on recognizing and reporting potential and actual instances of social engineering and social mining."}],"discussion":["Social engineering is an attempt to trick an individual into revealing information or taking an action that can be used to breach, compromise, or otherwise adversely impact a system. Social engineering includes phishing, pretexting, impersonation, baiting, quid pro quo, thread-jacking, social media exploitation, and tailgating. Social mining is an attempt to gather information about the organization that may be used to support future attacks. Literacy training includes information on how to communicate the concerns of employees and management regarding potential and actual instances of social engineering and data mining through organizational channels based on established policies and procedures."],"params":[],"related":[],"references":[],"objectives":[{"label":"AT-02(03)[01]","prose":"literacy training on recognizing potential and actual instances of social engineering is provided;"},{"label":"AT-02(03)[02]","prose":"literacy training on reporting potential and actual instances of social engineering is provided;"},{"label":"AT-02(03)[03]","prose":"literacy training on recognizing potential and actual instances of social mining is provided;"},{"label":"AT-02(03)[04]","prose":"literacy training on reporting potential and actual instances of social mining is provided."}],"methods":[{"method":"Examine","objects":["System security plan","privacy plan","literacy training and awareness policy","procedures addressing literacy training and awareness implementation","literacy training and awareness curriculum","literacy training and awareness materials","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel who receive literacy training and awareness","organizational personnel with responsibilities for literacy training and awareness","organizational personnel with information security and privacy responsibilities"]}]},"AT-3":{"statement":[{"label":"a.","prose":"Provide role-based security and privacy training to personnel with the following roles and responsibilities: [Assignment: organization-defined roles and responsibilities]:","items":[{"label":"1.","prose":"Before authorizing access to the system, information, or performing assigned duties, and [Assignment: organization-defined frequency] thereafter; and"},{"label":"2.","prose":"When required by system changes;"}]},{"label":"b.","prose":"Update role-based training content [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and"},{"label":"c.","prose":"Incorporate lessons learned from internal or external security incidents or breaches into role-based training."}],"discussion":["Organizations determine the content of training based on the assigned roles and responsibilities of individuals as well as the security and privacy requirements of organizations and the systems to which personnel have authorized access, including technical training specifically tailored for assigned duties. Roles that may require role-based training include senior leaders or management officials (e.g., head of agency/chief executive officer, chief information officer, senior accountable official for risk management, senior agency information security officer, senior agency official for privacy), system owners; authorizing officials; system security officers; privacy officers; acquisition and procurement officials; enterprise architects; systems engineers; software developers; systems security engineers; privacy engineers; system, network, and database administrators; auditors; personnel conducting configuration management activities; personnel performing verification and validation activities; personnel with access to system-level software; control assessors; personnel with contingency planning and incident response duties; personnel with privacy management responsibilities; and personnel with access to personally identifiable information.","Comprehensive role-based training addresses management, operational, and technical roles and responsibilities covering physical, personnel, and technical controls. Role-based training also includes policies, procedures, tools, methods, and artifacts for the security and privacy roles defined. Organizations provide the training necessary for individuals to fulfill their responsibilities related to operations and supply chain risk management within the context of organizational security and privacy programs. Role-based training also applies to contractors who provide services to federal agencies. Types of training include web-based and computer-based training, classroom-style training, and hands-on training (including micro-training). Updating role-based training on a regular basis helps to ensure that the content remains relevant and effective. Events that may precipitate an update to role-based training content include, but are not limited to, assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines."],"params":[{"id":"AT-3_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined roles and responsibilities]"},{"id":"AT-03_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined roles and responsibilities]","guideline":"roles and responsibilities for role-based security training are defined"},{"id":"AT-03_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined roles and responsibilities]","guideline":"roles and responsibilities for role-based privacy training are defined"},{"id":"AT-03_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to provide role-based security and privacy training to assigned personnel after initial training is defined"},{"id":"AT-03_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to update role-based training content is defined"},{"id":"AT-03_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that require role-based training content to be updated are defined"}],"related":["AC-3","AC-17","AC-22","AT-2","AT-4","CP-3","IR-2","IR-4","IR-7","IR-9","PL-4","PM-13","PM-23","PS-7","PS-9","SA-3","SA-8","SA-11","SA-16","SR-5","SR-6","SR-11"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-50","url":"https://doi.org/10.6028/NIST.SP.800-50"},{"title":"SP 800-181","url":"https://doi.org/10.6028/NIST.SP.800-181r1"}],"objectives":[{"label":"AT-03a.","prose":"","items":[{"label":"AT-03a.01","prose":"","items":[{"label":"AT-03a.01[01]","prose":"role-based security training is provided to [Assignment: organization-defined roles and responsibilities] before authorizing access to the system, information, or performing assigned duties;"},{"label":"AT-03a.01[02]","prose":"role-based privacy training is provided to [Assignment: organization-defined roles and responsibilities] before authorizing access to the system, information, or performing assigned duties;"},{"label":"AT-03a.01[03]","prose":"role-based security training is provided to [Assignment: organization-defined roles and responsibilities] [Assignment: organization-defined frequency] thereafter;"},{"label":"AT-03a.01[04]","prose":"role-based privacy training is provided to [Assignment: organization-defined roles and responsibilities] [Assignment: organization-defined frequency] thereafter;"}]},{"label":"AT-03a.02","prose":"","items":[{"label":"AT-03a.02[01]","prose":"role-based security training is provided to personnel with assigned security roles and responsibilities when required by system changes;"},{"label":"AT-03a.02[02]","prose":"role-based privacy training is provided to personnel with assigned security roles and responsibilities when required by system changes;"}]}]},{"label":"AT-03b.","prose":"","items":[{"label":"AT-03b.[01]","prose":"role-based training content is updated [Assignment: organization-defined frequency];"},{"label":"AT-03b.[02]","prose":"role-based training content is updated following [Assignment: organization-defined events];"}]},{"label":"AT-03c.","prose":"lessons learned from internal or external security incidents or breaches are incorporated into role-based training."}],"methods":[{"method":"Examine","objects":["System security plan","privacy plan","security and privacy awareness and training policy","procedures addressing security and privacy training implementation","codes of federal regulations","security and privacy training curriculum","security and privacy training materials","training records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for role-based security and privacy training","organizational personnel with assigned system security and privacy roles and responsibilities"]},{"method":"Test","objects":["Mechanisms managing role-based security and privacy training"]}]},"AT-4":{"statement":[{"label":"a.","prose":"Document and monitor information security and privacy training activities, including security and privacy awareness training and specific role-based security and privacy training; and"},{"label":"b.","prose":"Retain individual training records for [Assignment: organization-defined time period]."}],"discussion":["Documentation for specialized training may be maintained by individual supervisors at the discretion of the organization. The National Archives and Records Administration provides guidance on records retention for federal agencies."],"params":[{"id":"AT-04_ODP","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"time period for retaining individual training records is defined"}],"related":["AT-2","AT-3","CP-3","IR-2","PM-14","SI-12"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"}],"objectives":[{"label":"AT-04a.","prose":"","items":[{"label":"AT-04a.[01]","prose":"information security and privacy training activities, including security and privacy awareness training and specific role-based security and privacy training, are documented;"},{"label":"AT-04a.[02]","prose":"information security and privacy training activities, including security and privacy awareness training and specific role-based security and privacy training, are monitored;"}]},{"label":"AT-04b.","prose":"individual training records are retained for [Assignment: organization-defined time period]."}],"methods":[{"method":"Examine","objects":["Security and privacy awareness and training policy","procedures addressing security and privacy training records","security and privacy awareness and training records","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with information security and privacy training record retention responsibilities"]},{"method":"Test","objects":["Mechanisms supporting the management of security and privacy training records"]}]},"AU-1":{"statement":[{"label":"a.","prose":"Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:","items":[{"label":"1.","prose":"[Selection (one or more): organization-level; mission/business process-level; system-level] audit and accountability policy that:","items":[{"label":"(a)","prose":"Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and"},{"label":"(b)","prose":"Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and"}]},{"label":"2.","prose":"Procedures to facilitate the implementation of the audit and accountability policy and the associated audit and accountability controls;"}]},{"label":"b.","prose":"Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the audit and accountability policy and procedures; and"},{"label":"c.","prose":"Review and update the current audit and accountability:","items":[{"label":"1.","prose":"Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and"},{"label":"2.","prose":"Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]."}]}],"discussion":["Audit and accountability policy and procedures address the controls in the AU family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of audit and accountability policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to audit and accountability policy and procedures include assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure."],"params":[{"id":"AU-1_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]"},{"id":"AU-01_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the audit and accountability policy is to be disseminated is/are defined"},{"id":"AU-01_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the audit and accountability procedures are to be disseminated is/are defined"},{"id":"AU-01_ODP[03]","kind":"Selection","value":"[Selection (one or more): organization-level; mission/business process-level; system-level]"},{"id":"AU-01_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined official]","guideline":"an official to manage the audit and accountability policy and procedures is defined"},{"id":"AU-01_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current audit and accountability policy is reviewed and updated is defined"},{"id":"AU-01_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require the current audit and accountability policy to be reviewed and updated are defined"},{"id":"AU-01_ODP[07]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current audit and accountability procedures are reviewed and updated is defined"},{"id":"AU-01_ODP[08]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require audit and accountability procedures to be reviewed and updated are defined"}],"related":["PM-9","PS-8","SI-12"],"references":[{"title":"SP 800-12","url":"https://doi.org/10.6028/NIST.SP.800-12r1"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-39","url":"https://doi.org/10.6028/NIST.SP.800-39"},{"title":"SP 800-100","url":"https://doi.org/10.6028/NIST.SP.800-100"}],"objectives":[{"label":"AU-01a.","prose":"","items":[{"label":"AU-01a.[01]","prose":"an audit and accountability policy is developed and documented;"},{"label":"AU-01a.[02]","prose":"the audit and accountability policy is disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"AU-01a.[03]","prose":"audit and accountability procedures to facilitate the implementation of the audit and accountability policy and associated audit and accountability controls are developed and documented;"},{"label":"AU-01a.[04]","prose":"the audit and accountability procedures are disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"AU-01a.01","prose":"","items":[{"label":"AU-01a.01(a)","prose":"","items":[{"label":"AU-01a.01(a)[01]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] of the audit and accountability policy addresses purpose;"},{"label":"AU-01a.01(a)[02]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] of the audit and accountability policy addresses scope;"},{"label":"AU-01a.01(a)[03]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] of the audit and accountability policy addresses roles;"},{"label":"AU-01a.01(a)[04]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] of the audit and accountability policy addresses responsibilities;"},{"label":"AU-01a.01(a)[05]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] of the audit and accountability policy addresses management commitment;"},{"label":"AU-01a.01(a)[06]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] of the audit and accountability policy addresses coordination among organizational entities;"},{"label":"AU-01a.01(a)[07]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] of the audit and accountability policy addresses compliance;"}]},{"label":"AU-01a.01(b)","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] of the audit and accountability policy is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines;"}]}]},{"label":"AU-01b.","prose":"the [Assignment: organization-defined official] is designated to manage the development, documentation, and dissemination of the audit and accountability policy and procedures;"},{"label":"AU-01c.","prose":"","items":[{"label":"AU-01c.01","prose":"","items":[{"label":"AU-01c.01[01]","prose":"the current audit and accountability policy is reviewed and updated [Assignment: organization-defined frequency];"},{"label":"AU-01c.01[02]","prose":"the current audit and accountability policy is reviewed and updated following [Assignment: organization-defined events];"}]},{"label":"AU-01c.02","prose":"","items":[{"label":"AU-01c.02[01]","prose":"the current audit and accountability procedures are reviewed and updated [Assignment: organization-defined frequency];"},{"label":"AU-01c.02[02]","prose":"the current audit and accountability procedures are reviewed and updated following [Assignment: organization-defined events]."}]}]}],"methods":[{"method":"Examine","objects":["Audit and accountability policy and procedures","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with audit and accountability responsibilities","organizational personnel with information security and privacy responsibilities"]}]},"AU-2":{"statement":[{"label":"a.","prose":"Identify the types of events that the system is capable of logging in support of the audit function: [Assignment: organization-defined event types];"},{"label":"b.","prose":"Coordinate the event logging function with other organizational entities requiring audit-related information to guide and inform the selection criteria for events to be logged;"},{"label":"c.","prose":"Specify the following event types for logging within the system: [Assignment: organization-defined event types (subset of the event types defined in [AU-2a.](#au-2_smt.a)) along with the frequency of (or situation requiring) logging for each identified event type];"},{"label":"d.","prose":"Provide a rationale for why the event types selected for logging are deemed to be adequate to support after-the-fact investigations of incidents; and"},{"label":"e.","prose":"Review and update the event types selected for logging [Assignment: organization-defined frequency]."}],"discussion":["An event is an observable occurrence in a system. The types of events that require logging are those events that are significant and relevant to the security of systems and the privacy of individuals. Event logging also supports specific monitoring and auditing needs. Event types include password changes, failed logons or failed accesses related to systems, security or privacy attribute changes, administrative privilege usage, PIV credential usage, data action changes, query parameters, or external credential usage. In determining the set of event types that require logging, organizations consider the monitoring and auditing appropriate for each of the controls to be implemented. For completeness, event logging includes all protocols that are operational and supported by the system.","To balance monitoring and auditing requirements with other system needs, event logging requires identifying the subset of event types that are logged at a given point in time. For example, organizations may determine that systems need the capability to log every file access successful and unsuccessful, but not activate that capability except for specific circumstances due to the potential burden on system performance. The types of events that organizations desire to be logged may change. Reviewing and updating the set of logged events is necessary to help ensure that the events remain relevant and continue to support the needs of the organization. Organizations consider how the types of logging events can reveal information about individuals that may give rise to privacy risk and how best to mitigate such risks. For example, there is the potential to reveal personally identifiable information in the audit trail, especially if the logging event is based on patterns or time of usage.","Event logging requirements, including the need to log specific event types, may be referenced in other controls and control enhancements. These include [AC-2(4)](#ac-2.4), [AC-3(10)](#ac-3.10), [AC-6(9)](#ac-6.9), [AC-17(1)](#ac-17.1), [CM-3f](#cm-3_smt.f), [CM-5(1)](#cm-5.1), [IA-3(3)(b)](#ia-3.3_smt.b), [MA-4(1)](#ma-4.1), [MP-4(2)](#mp-4.2), [PE-3](#pe-3), [PM-21](#pm-21), [PT-7](#pt-7), [RA-8](#ra-8), [SC-7(9)](#sc-7.9), [SC-7(15)](#sc-7.15), [SI-3(8)](#si-3.8), [SI-4(22)](#si-4.22), [SI-7(8)](#si-7.8), and [SI-10(1)](#si-10.1). Organizations include event types that are required by applicable laws, executive orders, directives, policies, regulations, standards, and guidelines. Audit records can be generated at various levels, including at the packet level as information traverses the network. Selecting the appropriate level of event logging is an important part of a monitoring and auditing capability and can identify the root causes of problems. When defining event types, organizations consider the logging necessary to cover related event types, such as the steps in distributed, transaction-based processes and the actions that occur in service-oriented architectures."],"params":[{"id":"AU-2_PRM_2","kind":"Assignment","value":"[Assignment: organization-defined event types (subset of the event types defined in [AU-2a.](#au-2_smt.a)) along with the frequency of (or situation requiring) logging for each identified event type]"},{"id":"AU-02_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined event types]","guideline":"the event types that the system is capable of logging in support of the audit function are defined"},{"id":"AU-02_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined event types (subset of AU-02_ODP[01])]","guideline":"the event types (subset of AU-02_ODP[01]) for logging within the system are defined"},{"id":"AU-02_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined frequency or situation]","guideline":"the frequency or situation requiring logging for each specified event type is defined"},{"id":"AU-02_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency of event types selected for logging are reviewed and updated"}],"related":["AC-2","AC-3","AC-6","AC-7","AC-8","AC-16","AC-17","AU-3","AU-4","AU-5","AU-6","AU-7","AU-11","AU-12","CM-3","CM-5","CM-6","CM-13","IA-3","MA-4","MP-4","PE-3","PM-21","PT-2","PT-7","RA-8","SA-8","SC-7","SC-18","SI-3","SI-4","SI-7","SI-10","SI-11"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-92","url":"https://doi.org/10.6028/NIST.SP.800-92"}],"objectives":[{"label":"AU-02a.","prose":"[Assignment: organization-defined event types] that the system is capable of logging are identified in support of the audit logging function;"},{"label":"AU-02b.","prose":"the event logging function is coordinated with other organizational entities requiring audit-related information to guide and inform the selection criteria for events to be logged;"},{"label":"AU-02c.","prose":"","items":[{"label":"AU-02c.[01]","prose":"[Assignment: organization-defined event types (subset of AU-02_ODP[01])] are specified for logging within the system;"},{"label":"AU-02c.[02]","prose":"the specified event types are logged within the system [Assignment: organization-defined frequency or situation];"}]},{"label":"AU-02d.","prose":"a rationale is provided for why the event types selected for logging are deemed to be adequate to support after-the-fact investigations of incidents;"},{"label":"AU-02e.","prose":"the event types selected for logging are reviewed and updated [Assignment: organization-defined frequency]."}],"methods":[{"method":"Examine","objects":["Audit and accountability policy","procedures addressing auditable events","system security plan","privacy plan","system design documentation","system configuration settings and associated documentation","system audit records","system auditable events"]},{"method":"Interview","objects":["Organizational personnel with audit and accountability responsibilities","organizational personnel with information security and privacy responsibilities","system/network administrators"]},{"method":"Test","objects":["Mechanisms implementing system auditing"]}]},"AU-3":{"statement":[{"prose":"Ensure that audit records contain information that establishes the following:"},{"label":"a.","prose":"What type of event occurred;"},{"label":"b.","prose":"When the event occurred;"},{"label":"c.","prose":"Where the event occurred;"},{"label":"d.","prose":"Source of the event;"},{"label":"e.","prose":"Outcome of the event; and"},{"label":"f.","prose":"Identity of any individuals, subjects, or objects/entities associated with the event."}],"discussion":["Audit record content that may be necessary to support the auditing function includes event descriptions (item a), time stamps (item b), source and destination addresses (item c), user or process identifiers (items d and f), success or fail indications (item e), and filenames involved (items a, c, e, and f). Event outcomes include indicators of event success or failure and event-specific results, such as the system security and privacy posture after the event occurred. Organizations consider how audit records can reveal information about individuals that may give rise to privacy risks and how best to mitigate such risks. For example, there is the potential to reveal personally identifiable information in the audit trail, especially if the trail records inputs or is based on patterns or time of usage."],"params":[],"related":["AU-2","AU-8","AU-12","AU-14","MA-4","PL-9","SA-8","SI-7","SI-11"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"IR 8062","url":"https://doi.org/10.6028/NIST.IR.8062"}],"objectives":[{"label":"AU-03a.","prose":"audit records contain information that establishes what type of event occurred;"},{"label":"AU-03b.","prose":"audit records contain information that establishes when the event occurred;"},{"label":"AU-03c.","prose":"audit records contain information that establishes where the event occurred;"},{"label":"AU-03d.","prose":"audit records contain information that establishes the source of the event;"},{"label":"AU-03e.","prose":"audit records contain information that establishes the outcome of the event;"},{"label":"AU-03f.","prose":"audit records contain information that establishes the identity of any individuals, subjects, or objects/entities associated with the event."}],"methods":[{"method":"Examine","objects":["Audit and accountability policy","system security plan","privacy plan","procedures addressing content of audit records","system design documentation","system configuration settings and associated documentation","list of organization-defined auditable events","system audit records"]},{"method":"Interview","objects":["Organizational personnel with audit and accountability responsibilities","organizational personnel with information security and privacy responsibilities","system/network administrators"]},{"method":"Test","objects":["Mechanisms implementing system auditing of auditable events"]}]},"AU-3(1)":{"statement":[{"prose":"Generate audit records containing the following additional information: [Assignment: organization-defined additional information]."}],"discussion":["The ability to add information generated in audit records is dependent on system functionality to configure the audit record content. Organizations may consider additional information in audit records including, but not limited to, access control or flow control rules invoked and individual identities of group account users. Organizations may also consider limiting additional audit record information to only information that is explicitly needed for audit requirements. This facilitates the use of audit trails and audit logs by not including information in audit records that could potentially be misleading, make it more difficult to locate information of interest, or increase the risk to individuals' privacy."],"params":[{"id":"AU-03(01)_ODP","kind":"Assignment","value":"[Assignment: organization-defined additional information]","guideline":"additional information to be included in audit records is defined"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Audit and accountability policy","procedures addressing content of audit records","system security plan","privacy plan","system design documentation","system configuration settings and associated documentation","list of organization-defined auditable events","system audit records"]},{"method":"Interview","objects":["Organizational personnel with audit and accountability responsibilities","organizational personnel with information security and privacy responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["system audit capability"]}]},"AU-4":{"statement":[{"prose":"Allocate audit log storage capacity to accommodate [Assignment: organization-defined audit log retention requirements]."}],"discussion":["Organizations consider the types of audit logging to be performed and the audit log processing requirements when allocating audit log storage capacity. Allocating sufficient audit log storage capacity reduces the likelihood of such capacity being exceeded and resulting in the potential loss or reduction of audit logging capability."],"params":[{"id":"AU-04_ODP","kind":"Assignment","value":"[Assignment: organization-defined audit log retention requirements]","guideline":"audit log retention requirements are defined"}],"related":["AU-2","AU-5","AU-6","AU-7","AU-9","AU-11","AU-12","AU-14","SI-4"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Audit and accountability policy","procedures addressing audit storage capacity","system security plan","privacy plan","system design documentation","system configuration settings and associated documentation","audit record storage requirements","audit record storage capability for system components"]},{"method":"Interview","objects":["Organizational personnel with audit and accountability responsibilities","organizational personnel with information security and privacy responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Audit record storage capacity and related configuration settings"]}]},"AU-5":{"statement":[{"label":"a.","prose":"Alert [Assignment: organization-defined personnel or roles] within [Assignment: organization-defined time period] in the event of an audit logging process failure; and"},{"label":"b.","prose":"Take the following additional actions: [Assignment: organization-defined additional actions]."}],"discussion":["Audit logging process failures include software and hardware errors, failures in audit log capturing mechanisms, and reaching or exceeding audit log storage capacity. Organization-defined actions include overwriting oldest audit records, shutting down the system, and stopping the generation of audit records. Organizations may choose to define additional actions for audit logging process failures based on the type of failure, the location of the failure, the severity of the failure, or a combination of such factors. When the audit logging process failure is related to storage, the response is carried out for the audit log storage repository (i.e., the distinct system component where the audit logs are stored), the system on which the audit logs reside, the total audit log storage capacity of the organization (i.e., all audit log storage repositories combined), or all three. Organizations may decide to take no additional actions after alerting designated roles or personnel."],"params":[{"id":"AU-05_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles receiving audit logging process failure alerts are defined"},{"id":"AU-05_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"time period for personnel or roles receiving audit logging process failure alerts is defined"},{"id":"AU-05_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined additional actions]","guideline":"additional actions to be taken in the event of an audit logging process failure are defined"}],"related":["AU-2","AU-4","AU-7","AU-9","AU-11","AU-12","AU-14","SI-4","SI-12"],"references":[],"objectives":[{"label":"AU-05a.","prose":"[Assignment: organization-defined personnel or roles] are alerted in the event of an audit logging process failure within [Assignment: organization-defined time period];"},{"label":"AU-05b.","prose":"[Assignment: organization-defined additional actions] are taken in the event of an audit logging process failure."}],"methods":[{"method":"Examine","objects":["Audit and accountability policy","procedures addressing response to audit processing failures","system design documentation","system security plan","privacy plan","system configuration settings and associated documentation","list of personnel to be notified in case of an audit processing failure","system audit records"]},{"method":"Interview","objects":["Organizational personnel with audit and accountability responsibilities","organizational personnel with information security and privacy responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Mechanisms implementing system response to audit processing failures"]}]},"AU-5(1)":{"statement":[{"prose":"Provide a warning to [Assignment: organization-defined personnel, roles, and/or locations] within [Assignment: organization-defined time period] when allocated audit log storage volume reaches [Assignment: organization-defined percentage] of repository maximum audit log storage capacity."}],"discussion":["Organizations may have multiple audit log storage repositories distributed across multiple system components with each repository having different storage volume capacities."],"params":[{"id":"AU-05(01)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel, roles, and/or locations]","guideline":"personnel, roles, and/or locations to be warned when allocated audit log storage volume reaches a percentage of repository maximum audit log storage capacity."},{"id":"AU-05(01)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"time period for defined personnel, roles, and/or locations to be warned when allocated audit log storage volume reaches a percentage of repository maximum audit log storage capacity is defined"},{"id":"AU-05(01)_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined percentage]","guideline":"percentage of repository maximum audit log storage capacity is defined"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Audit and accountability policy","procedures addressing response to audit processing failures","system design documentation","system security plan","privacy system configuration settings and associated documentation","system audit records","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with audit and accountability responsibilities","organizational personnel with information security and privacy responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Mechanisms implementing audit storage limit warnings"]}]},"AU-5(2)":{"statement":[{"prose":"Provide an alert within [Assignment: organization-defined real-time period] to [Assignment: organization-defined personnel, roles, and/or locations] when the following audit failure events occur: [Assignment: organization-defined audit logging failure events requiring real-time alerts]."}],"discussion":["Alerts provide organizations with urgent messages. Real-time alerts provide these messages at information technology speed (i.e., the time from event detection to alert occurs in seconds or less)."],"params":[{"id":"AU-05(02)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined real-time period]","guideline":"real-time period requiring alerts when audit failure events (defined in AU-05(02)_ODP[03]) occur is defined"},{"id":"AU-05(02)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined personnel, roles, and/or locations]","guideline":"personnel, roles, and/or locations to be alerted in real time when audit failure events (defined in AU-05(02)_ODP[03]) occur is/are defined"},{"id":"AU-05(02)_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined audit logging failure events requiring real-time alerts]","guideline":"audit logging failure events requiring real-time alerts are defined"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Audit and accountability policy","procedures addressing response to audit processing failures","system design documentation","system security plan","privacy plan","system configuration settings and associated documentation","system audit records","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with audit and accountability responsibilities","organizational personnel with information security and privacy responsibilities","system/network administrators","system developers"]}]},"AU-6":{"statement":[{"label":"a.","prose":"Review and analyze system audit records [Assignment: organization-defined frequency] for indications of [Assignment: organization-defined inappropriate or unusual activity] and the potential impact of the inappropriate or unusual activity;"},{"label":"b.","prose":"Report findings to [Assignment: organization-defined personnel or roles]; and"},{"label":"c.","prose":"Adjust the level of audit record review, analysis, and reporting within the system when there is a change in risk based on law enforcement information, intelligence information, or other credible sources of information."}],"discussion":["Audit record review, analysis, and reporting covers information security- and privacy-related logging performed by organizations, including logging that results from the monitoring of account usage, remote access, wireless connectivity, mobile device connection, configuration settings, system component inventory, use of maintenance tools and non-local maintenance, physical access, temperature and humidity, equipment delivery and removal, communications at system interfaces, and use of mobile code or Voice over Internet Protocol (VoIP). Findings can be reported to organizational entities that include the incident response team, help desk, and security or privacy offices. If organizations are prohibited from reviewing and analyzing audit records or unable to conduct such activities, the review or analysis may be carried out by other organizations granted such authority. The frequency, scope, and/or depth of the audit record review, analysis, and reporting may be adjusted to meet organizational needs based on new information received."],"params":[{"id":"AU-06_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which system audit records are reviewed and analyzed is defined"},{"id":"AU-06_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined inappropriate or unusual activity]","guideline":"inappropriate or unusual activity is defined"},{"id":"AU-06_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to receive findings from reviews and analyses of system records is/are defined"}],"related":["AC-2","AC-3","AC-5","AC-6","AC-7","AC-17","AU-7","AU-16","CA-2","CA-7","CM-2","CM-5","CM-6","CM-10","CM-11","IA-2","IA-3","IA-5","IA-8","IR-5","MA-4","MP-4","PE-3","PE-6","RA-5","SA-8","SC-7","SI-3","SI-4","SI-7"],"references":[{"title":"SP 800-86","url":"https://doi.org/10.6028/NIST.SP.800-86"},{"title":"SP 800-101","url":"https://doi.org/10.6028/NIST.SP.800-101r1"}],"objectives":[{"label":"AU-06a.","prose":"system audit records are reviewed and analyzed [Assignment: organization-defined frequency] for indications of [Assignment: organization-defined inappropriate or unusual activity] and the potential impact of the inappropriate or unusual activity;"},{"label":"AU-06b.","prose":"findings are reported to [Assignment: organization-defined personnel or roles];"},{"label":"AU-06c.","prose":"the level of audit record review, analysis, and reporting within the system is adjusted when there is a change in risk based on law enforcement information, intelligence information, or other credible sources of information."}],"methods":[{"method":"Examine","objects":["Audit and accountability policy","system security plan","privacy plan","procedures addressing audit review, analysis, and reporting","reports of audit findings","records of actions taken in response to reviews/analyses of audit records","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with audit review, analysis, and reporting responsibilities","organizational personnel with information security and privacy responsibilities"]}]},"AU-6(1)":{"statement":[{"prose":"Integrate audit record review, analysis, and reporting processes using [Assignment: organization-defined automated mechanisms]."}],"discussion":["Organizational processes that benefit from integrated audit record review, analysis, and reporting include incident response, continuous monitoring, contingency planning, investigation and response to suspicious activities, and Inspector General audits."],"params":[{"id":"AU-06(01)_ODP","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms used for integrating audit record review, analysis, and reporting processes are defined"}],"related":["PM-7"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Audit and accountability policy","system security plan","privacy plan","procedures addressing audit review, analysis, and reporting","procedures addressing investigation and response to suspicious activities","system design documentation","system configuration settings and associated documentation","system audit records"]},{"method":"Interview","objects":["Organizational personnel with audit review, analysis, and reporting responsibilities","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Automated mechanisms integrating audit review, analysis, and reporting processes"]}]},"AU-6(3)":{"statement":[{"prose":"Analyze and correlate audit records across different repositories to gain organization-wide situational awareness."}],"discussion":["Organization-wide situational awareness includes awareness across all three levels of risk management (i.e., organizational level, mission/business process level, and information system level) and supports cross-organization awareness."],"params":[],"related":["AU-12","IR-4"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Audit and accountability policy","system security plan","privacy plan","procedures addressing audit review, analysis, and reporting","system design documentation","system configuration settings and associated documentation","system audit records across different repositories","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with audit review, analysis, and reporting responsibilities","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Mechanisms supporting the analysis and correlation of audit records"]}]},"AU-6(5)":{"statement":[{"prose":"Integrate analysis of audit records with analysis of [Selection (one or more): vulnerability scanning information; performance data; system monitoring information; [Assignment: organization-defined data/information collected from other sources]] to further enhance the ability to identify inappropriate or unusual activity."}],"discussion":["Integrated analysis of audit records does not require vulnerability scanning, the generation of performance data, or system monitoring. Rather, integrated analysis requires that the analysis of information generated by scanning, monitoring, or other data collection activities is integrated with the analysis of audit record information. Security Information and Event Management tools can facilitate audit record aggregation or consolidation from multiple system components as well as audit record correlation and analysis. The use of standardized audit record analysis scripts developed by organizations (with localized script adjustments, as necessary) provides more cost-effective approaches for analyzing audit record information collected. The correlation of audit record information with vulnerability scanning information is important in determining the veracity of vulnerability scans of the system and in correlating attack detection events with scanning results. Correlation with performance data can uncover denial-of-service attacks or other types of attacks that result in the unauthorized use of resources. Correlation with system monitoring information can assist in uncovering attacks and in better relating audit information to operational situations."],"params":[{"id":"AU-06(05)_ODP[01]","kind":"Selection","value":"[Selection (one or more): vulnerability scanning information; performance data; system monitoring information; [Assignment: organization-defined data/information collected from other sources]]"},{"id":"AU-06(05)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined data/information collected from other sources]","guideline":"data/information collected from other sources to be analyzed is defined (if selected)"}],"related":["AU-12","IR-4"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Audit and accountability policy","system security plan","privacy plan","procedures addressing audit review, analysis, and reporting","system design documentation","system configuration settings and associated documentation","integrated analysis of audit records, vulnerability scanning information, performance data, network monitoring information, and associated documentation","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with audit review, analysis, and reporting responsibilities","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Mechanisms implementing the capability to integrate analysis of audit records with analysis of data/information sources"]}]},"AU-6(6)":{"statement":[{"prose":"Correlate information from audit records with information obtained from monitoring physical access to further enhance the ability to identify suspicious, inappropriate, unusual, or malevolent activity."}],"discussion":["The correlation of physical audit record information and the audit records from systems may assist organizations in identifying suspicious behavior or supporting evidence of such behavior. For example, the correlation of an individual’s identity for logical access to certain systems with the additional physical security information that the individual was present at the facility when the logical access occurred may be useful in investigations."],"params":[],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Audit and accountability policy","procedures addressing audit review, analysis, and reporting","procedures addressing physical access monitoring","system design documentation","system configuration settings and associated documentation","documentation providing evidence of correlated information obtained from audit records and physical access monitoring records","system security plan","privacy plan"]},{"method":"Interview","objects":["Organizational personnel with audit review, analysis, and reporting responsibilities","organizational personnel with physical access monitoring responsibilities","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Mechanisms implementing the capability to correlate information from audit records with information from monitoring physical access"]}]},"AU-7":{"statement":[{"prose":"Provide and implement an audit record reduction and report generation capability that:"},{"label":"a.","prose":"Supports on-demand audit record review, analysis, and reporting requirements and after-the-fact investigations of incidents; and"},{"label":"b.","prose":"Does not alter the original content or time ordering of audit records."}],"discussion":["Audit record reduction is a process that manipulates collected audit log information and organizes it into a summary format that is more meaningful to analysts. Audit record reduction and report generation capabilities do not always emanate from the same system or from the same organizational entities that conduct audit logging activities. The audit record reduction capability includes modern data mining techniques with advanced data filters to identify anomalous behavior in audit records. The report generation capability provided by the system can generate customizable reports. Time ordering of audit records can be an issue if the granularity of the timestamp in the record is insufficient."],"params":[],"related":["AC-2","AU-2","AU-3","AU-4","AU-5","AU-6","AU-12","AU-16","CM-5","IA-5","IR-4","PM-12","SI-4"],"references":[],"objectives":[{"label":"AU-07a.","prose":"","items":[{"label":"AU-07a.[01]","prose":"an audit record reduction and report generation capability is provided that supports on-demand audit record review, analysis, and reporting requirements and after-the-fact investigations of incidents;"},{"label":"AU-07a.[02]","prose":"an audit record reduction and report generation capability is implemented that supports on-demand audit record review, analysis, and reporting requirements and after-the-fact investigations of incidents;"}]},{"label":"AU-07b.","prose":"","items":[{"label":"AU-07b.[01]","prose":"an audit record reduction and report generation capability is provided that does not alter the original content or time ordering of audit records;"},{"label":"AU-07b.[02]","prose":"an audit record reduction and report generation capability is implemented that does not alter the original content or time ordering of audit records."}]}],"methods":[{"method":"Examine","objects":["Audit and accountability policy","system security plan","privacy plan","procedures addressing audit reduction and report generation","system design documentation","system configuration settings and associated documentation","audit reduction, review, analysis, and reporting tools","system audit records"]},{"method":"Interview","objects":["Organizational personnel with audit reduction and report generation responsibilities","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Audit reduction and report generation capability"]}]},"AU-7(1)":{"statement":[{"prose":"Provide and implement the capability to process, sort, and search audit records for events of interest based on the following content: [Assignment: organization-defined fields within audit records]."}],"discussion":["Events of interest can be identified by the content of audit records, including system resources involved, information objects accessed, identities of individuals, event types, event locations, event dates and times, Internet Protocol addresses involved, or event success or failure. Organizations may define event criteria to any degree of granularity required, such as locations selectable by a general networking location or by specific system component."],"params":[{"id":"AU-07(01)_ODP","kind":"Assignment","value":"[Assignment: organization-defined fields within audit records]","guideline":"fields within audit records that can be processed, sorted, or searched are defined"}],"related":[],"references":[],"objectives":[{"label":"AU-07(01)[01]","prose":"the capability to process, sort, and search audit records for events of interest based on [Assignment: organization-defined fields within audit records] are provided;"},{"label":"AU-07(01)[02]","prose":"the capability to process, sort, and search audit records for events of interest based on [Assignment: organization-defined fields within audit records] are implemented."}],"methods":[{"method":"Examine","objects":["Audit and accountability policy","system security plan","privacy plan","procedures addressing audit reduction and report generation","system design documentation","system configuration settings and associated documentation","audit reduction, review, analysis, and reporting tools","audit record criteria (fields) establishing events of interest"]},{"method":"Interview","objects":["Organizational personnel with audit reduction and report generation responsibilities","organizational personnel with information security and privacy responsibilities","system developers"]},{"method":"Test","objects":["Audit reduction and report generation capability"]}]},"AU-8":{"statement":[{"label":"a.","prose":"Use internal system clocks to generate time stamps for audit records; and"},{"label":"b.","prose":"Record time stamps for audit records that meet [Assignment: organization-defined granularity of time measurement] and that use Coordinated Universal Time, have a fixed local time offset from Coordinated Universal Time, or that include the local time offset as part of the time stamp."}],"discussion":["Time stamps generated by the system include date and time. Time is commonly expressed in Coordinated Universal Time (UTC), a modern continuation of Greenwich Mean Time (GMT), or local time with an offset from UTC. Granularity of time measurements refers to the degree of synchronization between system clocks and reference clocks (e.g., clocks synchronizing within hundreds of milliseconds or tens of milliseconds). Organizations may define different time granularities for different system components. Time service can be critical to other security capabilities such as access control and identification and authentication, depending on the nature of the mechanisms used to support those capabilities."],"params":[{"id":"AU-08_ODP","kind":"Assignment","value":"[Assignment: organization-defined granularity of time measurement]","guideline":"granularity of time measurement for audit record timestamps is defined"}],"related":["AU-3","AU-12","AU-14","SC-45"],"references":[],"objectives":[{"label":"AU-08a.","prose":"internal system clocks are used to generate timestamps for audit records;"},{"label":"AU-08b.","prose":"timestamps are recorded for audit records that meet [Assignment: organization-defined granularity of time measurement] and that use Coordinated Universal Time, have a fixed local time offset from Coordinated Universal Time, or include the local time offset as part of the timestamp."}],"methods":[{"method":"Examine","objects":["Audit and accountability policy","system security plan","privacy plan","procedures addressing timestamp generation","system design documentation","system configuration settings and associated documentation","system audit records","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with information security and privacy responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Mechanisms implementing timestamp generation"]}]},"AU-9":{"statement":[{"label":"a.","prose":"Protect audit information and audit logging tools from unauthorized access, modification, and deletion; and"},{"label":"b.","prose":"Alert [Assignment: organization-defined personnel or roles] upon detection of unauthorized access, modification, or deletion of audit information."}],"discussion":["Audit information includes all information needed to successfully audit system activity, such as audit records, audit log settings, audit reports, and personally identifiable information. Audit logging tools are those programs and devices used to conduct system audit and logging activities. Protection of audit information focuses on technical protection and limits the ability to access and execute audit logging tools to authorized individuals. Physical protection of audit information is addressed by both media protection controls and physical and environmental protection controls."],"params":[{"id":"AU-09_ODP","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to be alerted upon detection of unauthorized access, modification, or deletion of audit information is/are defined"}],"related":["AC-3","AC-6","AU-6","AU-11","AU-14","AU-15","MP-2","MP-4","PE-2","PE-3","PE-6","SA-8","SC-8","SI-4"],"references":[{"title":"FIPS 140-3","url":"https://doi.org/10.6028/NIST.FIPS.140-3"},{"title":"FIPS 180-4","url":"https://doi.org/10.6028/NIST.FIPS.180-4"},{"title":"FIPS 202","url":"https://doi.org/10.6028/NIST.FIPS.202"}],"objectives":[{"label":"AU-09a.","prose":"audit information and audit logging tools are protected from unauthorized access, modification, and deletion;"},{"label":"AU-09b.","prose":"[Assignment: organization-defined personnel or roles] are alerted upon detection of unauthorized access, modification, or deletion of audit information."}],"methods":[{"method":"Examine","objects":["Audit and accountability policy","system security plan","privacy plan","access control policy and procedures","procedures addressing protection of audit information","system design documentation","system configuration settings and associated documentation","system audit records"]},{"method":"Interview","objects":["Organizational personnel with audit and accountability responsibilities","organizational personnel with information security and privacy responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Mechanisms implementing audit information protection"]}]},"AU-9(2)":{"statement":[{"prose":"Store audit records [Assignment: organization-defined frequency] in a repository that is part of a physically different system or system component than the system or component being audited."}],"discussion":["Storing audit records in a repository separate from the audited system or system component helps to ensure that a compromise of the system being audited does not also result in a compromise of the audit records. Storing audit records on separate physical systems or components also preserves the confidentiality and integrity of audit records and facilitates the management of audit records as an organization-wide activity. Storing audit records on separate systems or components applies to initial generation as well as backup or long-term storage of audit records."],"params":[{"id":"AU-09(02)_ODP","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency of storing audit records in a repository is defined"}],"related":["AU-4","AU-5"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Audit and accountability policy","system security plan","privacy plan","procedures addressing protection of audit information","system design documentation","system configuration settings and associated documentation","system or media storing backups of system audit records","system audit records"]},{"method":"Interview","objects":["Organizational personnel with audit and accountability responsibilities","organizational personnel with information security and privacy responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Mechanisms implementing the backing up of audit records"]}]},"AU-9(3)":{"statement":[{"prose":"Implement cryptographic mechanisms to protect the integrity of audit information and audit tools."}],"discussion":["Cryptographic mechanisms used for protecting the integrity of audit information include signed hash functions using asymmetric cryptography. This enables the distribution of the public key to verify the hash information while maintaining the confidentiality of the secret key used to generate the hash."],"params":[],"related":["AU-10","SC-12","SC-13"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Audit and accountability policy","system security plan","privacy plan","access control policy and procedures","procedures addressing protection of audit information","system design documentation","system hardware settings","system configuration settings and associated documentation"]},{"method":"Interview","objects":["Organizational personnel with audit and accountability responsibilities","organizational personnel with information security and privacy responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Cryptographic mechanisms protecting the integrity of audit information and tools"]}]},"AU-9(4)":{"statement":[{"prose":"Authorize access to management of audit logging functionality to only [Assignment: organization-defined subset of privileged users or roles]."}],"discussion":["Individuals or roles with privileged access to a system and who are also the subject of an audit by that system may affect the reliability of the audit information by inhibiting audit activities or modifying audit records. Requiring privileged access to be further defined between audit-related privileges and other privileges limits the number of users or roles with audit-related privileges."],"params":[{"id":"AU-09(04)_ODP","kind":"Assignment","value":"[Assignment: organization-defined subset of privileged users or roles]","guideline":"a subset of privileged users or roles authorized to access management of audit logging functionality is defined"}],"related":["AC-5"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Audit and accountability policy","system security plan","privacy plan","access control policy and procedures","procedures addressing protection of audit information","system design documentation","system configuration settings and associated documentation","system-generated list of privileged users with access to management of audit functionality"]},{"method":"Interview","objects":["Organizational personnel with audit and accountability responsibilities","organizational personnel with information security and privacy responsibilities","system/network administrators"]},{"method":"Test","objects":["Mechanisms managing access to audit functionality"]}]},"AU-10":{"statement":[{"prose":"Provide irrefutable evidence that an individual (or process acting on behalf of an individual) has performed [Assignment: organization-defined actions]."}],"discussion":["Types of individual actions covered by non-repudiation include creating information, sending and receiving messages, and approving information. Non-repudiation protects against claims by authors of not having authored certain documents, senders of not having transmitted messages, receivers of not having received messages, and signatories of not having signed documents. Non-repudiation services can be used to determine if information originated from an individual or if an individual took specific actions (e.g., sending an email, signing a contract, approving a procurement request, or receiving specific information). Organizations obtain non-repudiation services by employing various techniques or mechanisms, including digital signatures and digital message receipts."],"params":[{"id":"AU-10_ODP","kind":"Assignment","value":"[Assignment: organization-defined actions]","guideline":"actions to be covered by non-repudiation are defined"}],"related":["AU-9","PM-12","SA-8","SC-8","SC-12","SC-13","SC-16","SC-17","SC-23"],"references":[{"title":"FIPS 140-3","url":"https://doi.org/10.6028/NIST.FIPS.140-3"},{"title":"FIPS 180-4","url":"https://doi.org/10.6028/NIST.FIPS.180-4"},{"title":"FIPS 186-4","url":"https://doi.org/10.6028/NIST.FIPS.186-4"},{"title":"FIPS 202","url":"https://doi.org/10.6028/NIST.FIPS.202"},{"title":"SP 800-177","url":"https://doi.org/10.6028/NIST.SP.800-177r1"}],"objectives":[],"methods":[{"method":"Examine","objects":["Audit and accountability policy","system security plan","privacy plan","procedures addressing non-repudiation","system design documentation","system configuration settings and associated documentation","system audit records","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with information security and privacy responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Mechanisms implementing non-repudiation capability"]}]},"AU-11":{"statement":[{"prose":"Retain audit records for [Assignment: organization-defined time period] to provide support for after-the-fact investigations of incidents and to meet regulatory and organizational information retention requirements."}],"discussion":["Organizations retain audit records until it is determined that the records are no longer needed for administrative, legal, audit, or other operational purposes. This includes the retention and availability of audit records relative to Freedom of Information Act (FOIA) requests, subpoenas, and law enforcement actions. Organizations develop standard categories of audit records relative to such types of actions and standard response processes for each type of action. The National Archives and Records Administration (NARA) General Records Schedules provide federal policy on records retention."],"params":[{"id":"AU-11_ODP","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"a time period to retain audit records that is consistent with the records retention policy is defined"}],"related":["AU-2","AU-4","AU-5","AU-6","AU-9","AU-14","MP-6","RA-5","SI-12"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"}],"objectives":[],"methods":[{"method":"Examine","objects":["Audit and accountability policy","system security plan","privacy plan","audit record retention policy and procedures","security plan","organization-defined retention period for audit records","audit record archives","audit logs"]},{"method":"Interview","objects":["Organizational personnel with audit record retention responsibilities","organizational personnel with information security and privacy responsibilities","system/network administrators"]}]},"AU-12":{"statement":[{"label":"a.","prose":"Provide audit record generation capability for the event types the system is capable of auditing as defined in [AU-2a](#au-2_smt.a) on [Assignment: organization-defined system components];"},{"label":"b.","prose":"Allow [Assignment: organization-defined personnel or roles] to select the event types that are to be logged by specific components of the system; and"},{"label":"c.","prose":"Generate audit records for the event types defined in [AU-2c](#au-2_smt.c) that include the audit record content defined in [AU-3](#au-3)."}],"discussion":["Audit records can be generated from many different system components. The event types specified in [AU-2d](#au-2_smt.d) are the event types for which audit logs are to be generated and are a subset of all event types for which the system can generate audit records."],"params":[{"id":"AU-12_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined system components]","guideline":"system components that provide an audit record generation capability for the events types (defined in AU-02_ODP[02]) are defined"},{"id":"AU-12_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles allowed to select the event types that are to be logged by specific components of the system is/are defined"}],"related":["AC-6","AC-17","AU-2","AU-3","AU-4","AU-5","AU-6","AU-7","AU-14","CM-5","MA-4","MP-4","PM-12","SA-8","SC-18","SI-3","SI-4","SI-7","SI-10"],"references":[],"objectives":[{"label":"AU-12a.","prose":"audit record generation capability for the event types the system is capable of auditing (defined in AU-02_ODP[01]) is provided by [Assignment: organization-defined system components];"},{"label":"AU-12b.","prose":"[Assignment: organization-defined personnel or roles] is/are allowed to select the event types that are to be logged by specific components of the system;"},{"label":"AU-12c.","prose":"audit records for the event types defined in AU-02_ODP[02] that include the audit record content defined in AU-03 are generated."}],"methods":[{"method":"Examine","objects":["Audit and accountability policy","procedures addressing audit record generation","system security plan","privacy plan","system design documentation","system configuration settings and associated documentation","list of auditable events","system audit records"]},{"method":"Interview","objects":["Organizational personnel with audit record generation responsibilities","organizational personnel with information security and privacy responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Mechanisms implementing audit record generation capability"]}]},"AU-12(1)":{"statement":[{"prose":"Compile audit records from [Assignment: organization-defined system components] into a system-wide (logical or physical) audit trail that is time-correlated to within [Assignment: organization-defined level of tolerance]."}],"discussion":["Audit trails are time-correlated if the time stamps in the individual audit records can be reliably related to the time stamps in other audit records to achieve a time ordering of the records within organizational tolerances."],"params":[{"id":"AU-12(01)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined system components]","guideline":"system components from which audit records are to be compiled into a system-wide (logical or physical) audit trail are defined"},{"id":"AU-12(01)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined level of tolerance]","guideline":"level of tolerance for the relationship between timestamps of individual records in the audit trail is defined"}],"related":["AU-8","SC-45"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Audit and accountability policy","system security plan","privacy plan","procedures addressing audit record generation","system design documentation","system configuration settings and associated documentation","system-wide audit trail (logical or physical)","system audit records"]},{"method":"Interview","objects":["Organizational personnel with audit record generation responsibilities","organizational personnel with information security and privacy responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Mechanisms implementing audit record generation capability"]}]},"AU-12(3)":{"statement":[{"prose":"Provide and implement the capability for [Assignment: organization-defined individuals or roles] to change the logging to be performed on [Assignment: organization-defined system components] based on [Assignment: organization-defined selectable event criteria] within [Assignment: organization-defined time thresholds]."}],"discussion":["Permitting authorized individuals to make changes to system logging enables organizations to extend or limit logging as necessary to meet organizational requirements. Logging that is limited to conserve system resources may be extended (either temporarily or permanently) to address certain threat situations. In addition, logging may be limited to a specific set of event types to facilitate audit reduction, analysis, and reporting. Organizations can establish time thresholds in which logging actions are changed (e.g., near real-time, within minutes, or within hours)."],"params":[{"id":"AU-12(03)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined individuals or roles]","guideline":"individuals or roles authorized to change the logging on system components are defined"},{"id":"AU-12(03)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined system components]","guideline":"system components on which logging is to be performed are defined"},{"id":"AU-12(03)_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined selectable event criteria]","guideline":"selectable event criteria with which change logging is to be performed are defined"},{"id":"AU-12(03)_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined time thresholds]","guideline":"time thresholds in which logging actions are to change is defined"}],"related":["AC-3"],"references":[],"objectives":[{"label":"AU-12(03)[01]","prose":"the capability for [Assignment: organization-defined individuals or roles] to change the logging to be performed on [Assignment: organization-defined system components] based on [Assignment: organization-defined selectable event criteria] within [Assignment: organization-defined time thresholds] is provided;"},{"label":"AU-12(03)[02]","prose":"the capability for [Assignment: organization-defined individuals or roles] to change the logging to be performed on [Assignment: organization-defined system components] based on [Assignment: organization-defined selectable event criteria] within [Assignment: organization-defined time thresholds] is implemented."}],"methods":[{"method":"Examine","objects":["Audit and accountability policy","system security plan","privacy plan","procedures addressing audit record generation","system design documentation","system configuration settings and associated documentation","system-generated list of individuals or roles authorized to change auditing to be performed","system audit records"]},{"method":"Interview","objects":["Organizational personnel with audit record generation responsibilities","organizational personnel with information security and privacy responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Mechanisms implementing audit record generation capability"]}]},"CA-1":{"statement":[{"label":"a.","prose":"Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:","items":[{"label":"1.","prose":"[Selection (one or more): organization-level; mission/business process-level; system-level] assessment, authorization, and monitoring policy that:","items":[{"label":"(a)","prose":"Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and"},{"label":"(b)","prose":"Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and"}]},{"label":"2.","prose":"Procedures to facilitate the implementation of the assessment, authorization, and monitoring policy and the associated assessment, authorization, and monitoring controls;"}]},{"label":"b.","prose":"Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the assessment, authorization, and monitoring policy and procedures; and"},{"label":"c.","prose":"Review and update the current assessment, authorization, and monitoring:","items":[{"label":"1.","prose":"Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and"},{"label":"2.","prose":"Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]."}]}],"discussion":["Assessment, authorization, and monitoring policy and procedures address the controls in the CA family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of assessment, authorization, and monitoring policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to assessment, authorization, and monitoring policy and procedures include assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure."],"params":[{"id":"CA-1_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]"},{"id":"CA-01_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the assessment, authorization, and monitoring policy is to be disseminated is/are defined"},{"id":"CA-01_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the assessment, authorization, and monitoring procedures are to be disseminated is/are defined"},{"id":"CA-01_ODP[03]","kind":"Selection","value":"[Selection (one or more): organization-level; mission/business process-level; system-level]"},{"id":"CA-01_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined official]","guideline":"an official to manage the assessment, authorization, and monitoring policy and procedures is defined"},{"id":"CA-01_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current assessment, authorization, and monitoring policy is reviewed and updated is defined"},{"id":"CA-01_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require the current assessment, authorization, and monitoring policy to be reviewed and updated are defined"},{"id":"CA-01_ODP[07]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current assessment, authorization, and monitoring procedures are reviewed and updated is defined"},{"id":"CA-01_ODP[08]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require assessment, authorization, and monitoring procedures to be reviewed and updated are defined"}],"related":["PM-9","PS-8","SI-12"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-12","url":"https://doi.org/10.6028/NIST.SP.800-12r1"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-37","url":"https://doi.org/10.6028/NIST.SP.800-37r2"},{"title":"SP 800-39","url":"https://doi.org/10.6028/NIST.SP.800-39"},{"title":"SP 800-53A","url":"https://doi.org/10.6028/NIST.SP.800-53Ar4"},{"title":"SP 800-100","url":"https://doi.org/10.6028/NIST.SP.800-100"},{"title":"SP 800-137","url":"https://doi.org/10.6028/NIST.SP.800-137"},{"title":"SP 800-137A","url":"https://doi.org/10.6028/NIST.SP.800-137A"},{"title":"IR 8062","url":"https://doi.org/10.6028/NIST.IR.8062"}],"objectives":[{"label":"CA-01a.","prose":"","items":[{"label":"CA-01a.[01]","prose":"an assessment, authorization, and monitoring policy is developed and documented;"},{"label":"CA-01a.[02]","prose":"the assessment, authorization, and monitoring policy is disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"CA-01a.[03]","prose":"assessment, authorization, and monitoring procedures to facilitate the implementation of the assessment, authorization, and monitoring policy and associated assessment, authorization, and monitoring controls are developed and documented;"},{"label":"CA-01a.[04]","prose":"the assessment, authorization, and monitoring procedures are disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"CA-01a.01","prose":"","items":[{"label":"CA-01a.01(a)","prose":"","items":[{"label":"CA-01a.01(a)[01]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] assessment, authorization, and monitoring policy addresses purpose;"},{"label":"CA-01a.01(a)[02]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] assessment, authorization, and monitoring policy addresses scope;"},{"label":"CA-01a.01(a)[03]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] assessment, authorization, and monitoring policy addresses roles;"},{"label":"CA-01a.01(a)[04]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] assessment, authorization, and monitoring policy addresses responsibilities;"},{"label":"CA-01a.01(a)[05]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] assessment, authorization, and monitoring policy addresses management commitment;"},{"label":"CA-01a.01(a)[06]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] assessment, authorization, and monitoring policy addresses coordination among organizational entities;"},{"label":"CA-01a.01(a)[07]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] assessment, authorization, and monitoring policy addresses compliance;"}]},{"label":"CA-01a.01(b)","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] assessment, authorization, and monitoring policy is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines;"}]}]},{"label":"CA-01b.","prose":"the [Assignment: organization-defined official] is designated to manage the development, documentation, and dissemination of the assessment, authorization, and monitoring policy and procedures;"},{"label":"CA-01c.","prose":"","items":[{"label":"CA-01c.01","prose":"","items":[{"label":"CA-01c.01[01]","prose":"the current assessment, authorization, and monitoring policy is reviewed and updated [Assignment: organization-defined frequency];"},{"label":"CA-01c.01[02]","prose":"the current assessment, authorization, and monitoring policy is reviewed and updated following [Assignment: organization-defined events];"}]},{"label":"CA-01c.02","prose":"","items":[{"label":"CA-01c.02[01]","prose":"the current assessment, authorization, and monitoring procedures are reviewed and updated [Assignment: organization-defined frequency];"},{"label":"CA-01c.02[02]","prose":"the current assessment, authorization, and monitoring procedures are reviewed and updated following [Assignment: organization-defined events]."}]}]}],"methods":[{"method":"Examine","objects":["Assessment, authorization, and monitoring policy and procedures","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with assessment, authorization, and monitoring policy responsibilities","organizational personnel with information security and privacy responsibilities"]}]},"CA-2":{"statement":[{"label":"a.","prose":"Select the appropriate assessor or assessment team for the type of assessment to be conducted;"},{"label":"b.","prose":"Develop a control assessment plan that describes the scope of the assessment including:","items":[{"label":"1.","prose":"Controls and control enhancements under assessment;"},{"label":"2.","prose":"Assessment procedures to be used to determine control effectiveness; and"},{"label":"3.","prose":"Assessment environment, assessment team, and assessment roles and responsibilities;"}]},{"label":"c.","prose":"Ensure the control assessment plan is reviewed and approved by the authorizing official or designated representative prior to conducting the assessment;"},{"label":"d.","prose":"Assess the controls in the system and its environment of operation [Assignment: organization-defined assessment frequency] to determine the extent to which the controls are implemented correctly, operating as intended, and producing the desired outcome with respect to meeting established security and privacy requirements;"},{"label":"e.","prose":"Produce a control assessment report that document the results of the assessment; and"},{"label":"f.","prose":"Provide the results of the control assessment to [Assignment: organization-defined individuals or roles]."}],"discussion":["Organizations ensure that control assessors possess the required skills and technical expertise to develop effective assessment plans and to conduct assessments of system-specific, hybrid, common, and program management controls, as appropriate. The required skills include general knowledge of risk management concepts and approaches as well as comprehensive knowledge of and experience with the hardware, software, and firmware system components implemented.","Organizations assess controls in systems and the environments in which those systems operate as part of initial and ongoing authorizations, continuous monitoring, FISMA annual assessments, system design and development, systems security engineering, privacy engineering, and the system development life cycle. Assessments help to ensure that organizations meet information security and privacy requirements, identify weaknesses and deficiencies in the system design and development process, provide essential information needed to make risk-based decisions as part of authorization processes, and comply with vulnerability mitigation procedures. Organizations conduct assessments on the implemented controls as documented in security and privacy plans. Assessments can also be conducted throughout the system development life cycle as part of systems engineering and systems security engineering processes. The design for controls can be assessed as RFPs are developed, responses assessed, and design reviews conducted. If a design to implement controls and subsequent implementation in accordance with the design are assessed during development, the final control testing can be a simple confirmation utilizing previously completed control assessment and aggregating the outcomes.","Organizations may develop a single, consolidated security and privacy assessment plan for the system or maintain separate plans. A consolidated assessment plan clearly delineates the roles and responsibilities for control assessment. If multiple organizations participate in assessing a system, a coordinated approach can reduce redundancies and associated costs.","Organizations can use other types of assessment activities, such as vulnerability scanning and system monitoring, to maintain the security and privacy posture of systems during the system life cycle. Assessment reports document assessment results in sufficient detail, as deemed necessary by organizations, to determine the accuracy and completeness of the reports and whether the controls are implemented correctly, operating as intended, and producing the desired outcome with respect to meeting requirements. Assessment results are provided to the individuals or roles appropriate for the types of assessments being conducted. For example, assessments conducted in support of authorization decisions are provided to authorizing officials, senior agency officials for privacy, senior agency information security officers, and authorizing official designated representatives.","To satisfy annual assessment requirements, organizations can use assessment results from the following sources: initial or ongoing system authorizations, continuous monitoring, systems engineering processes, or system development life cycle activities. Organizations ensure that assessment results are current, relevant to the determination of control effectiveness, and obtained with the appropriate level of assessor independence. Existing control assessment results can be reused to the extent that the results are still valid and can also be supplemented with additional assessments as needed. After the initial authorizations, organizations assess controls during continuous monitoring. Organizations also establish the frequency for ongoing assessments in accordance with organizational continuous monitoring strategies. External audits, including audits by external entities such as regulatory agencies, are outside of the scope of [CA-2](#ca-2)."],"params":[{"id":"CA-02_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined assessment frequency]","guideline":"the frequency at which to assess controls in the system and its environment of operation is defined"},{"id":"CA-02_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined individuals or roles]","guideline":"individuals or roles to whom control assessment results are to be provided are defined"}],"related":["AC-20","CA-5","CA-6","CA-7","PM-9","RA-5","RA-10","SA-11","SC-38","SI-3","SI-12","SR-2","SR-3"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"FIPS 199","url":"https://doi.org/10.6028/NIST.FIPS.199"},{"title":"SP 800-18","url":"https://doi.org/10.6028/NIST.SP.800-18r1"},{"title":"SP 800-37","url":"https://doi.org/10.6028/NIST.SP.800-37r2"},{"title":"SP 800-39","url":"https://doi.org/10.6028/NIST.SP.800-39"},{"title":"SP 800-53A","url":"https://doi.org/10.6028/NIST.SP.800-53Ar4"},{"title":"SP 800-115","url":"https://doi.org/10.6028/NIST.SP.800-115"},{"title":"SP 800-137","url":"https://doi.org/10.6028/NIST.SP.800-137"},{"title":"IR 8011-1","url":"https://doi.org/10.6028/NIST.IR.8011-1"},{"title":"IR 8062","url":"https://doi.org/10.6028/NIST.IR.8062"}],"objectives":[{"label":"CA-02a.","prose":"an appropriate assessor or assessment team is selected for the type of assessment to be conducted;"},{"label":"CA-02b.","prose":"","items":[{"label":"CA-02b.01","prose":"a control assessment plan is developed that describes the scope of the assessment, including controls and control enhancements under assessment;"},{"label":"CA-02b.02","prose":"a control assessment plan is developed that describes the scope of the assessment, including assessment procedures to be used to determine control effectiveness;"},{"label":"CA-02b.03","prose":"","items":[{"label":"CA-02b.03[01]","prose":"a control assessment plan is developed that describes the scope of the assessment, including the assessment environment;"},{"label":"CA-02b.03[02]","prose":"a control assessment plan is developed that describes the scope of the assessment, including the assessment team;"},{"label":"CA-02b.03[03]","prose":"a control assessment plan is developed that describes the scope of the assessment, including assessment roles and responsibilities;"}]}]},{"label":"CA-02c.","prose":"the control assessment plan is reviewed and approved by the authorizing official or designated representative prior to conducting the assessment;"},{"label":"CA-02d.","prose":"","items":[{"label":"CA-02d.[01]","prose":"controls are assessed in the system and its environment of operation [Assignment: organization-defined assessment frequency] to determine the extent to which the controls are implemented correctly, operating as intended, and producing the desired outcome with respect to meeting established security requirements;"},{"label":"CA-02d.[02]","prose":"controls are assessed in the system and its environment of operation [Assignment: organization-defined assessment frequency] to determine the extent to which the controls are implemented correctly, operating as intended, and producing the desired outcome with respect to meeting established privacy requirements;"}]},{"label":"CA-02e.","prose":"a control assessment report is produced that documents the results of the assessment;"},{"label":"CA-02f.","prose":"the results of the control assessment are provided to [Assignment: organization-defined individuals or roles]."}],"methods":[{"method":"Examine","objects":["Assessment, authorization, and monitoring policy","procedures addressing assessment planning","procedures addressing control assessments","control assessment plan","control assessment report","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with control assessment responsibilities","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Mechanisms supporting control assessment, control assessment plan development, and/or control assessment reporting"]}]},"CA-2(1)":{"statement":[{"prose":"Employ independent assessors or assessment teams to conduct control assessments."}],"discussion":["Independent assessors or assessment teams are individuals or groups who conduct impartial assessments of systems. Impartiality means that assessors are free from any perceived or actual conflicts of interest regarding the development, operation, sustainment, or management of the systems under assessment or the determination of control effectiveness. To achieve impartiality, assessors do not create a mutual or conflicting interest with the organizations where the assessments are being conducted, assess their own work, act as management or employees of the organizations they are serving, or place themselves in positions of advocacy for the organizations acquiring their services.","Independent assessments can be obtained from elements within organizations or be contracted to public or private sector entities outside of organizations. Authorizing officials determine the required level of independence based on the security categories of systems and/or the risk to organizational operations, organizational assets, or individuals. Authorizing officials also determine if the level of assessor independence provides sufficient assurance that the results are sound and can be used to make credible, risk-based decisions. Assessor independence determination includes whether contracted assessment services have sufficient independence, such as when system owners are not directly involved in contracting processes or cannot influence the impartiality of the assessors conducting the assessments. During the system design and development phase, having independent assessors is analogous to having independent SMEs involved in design reviews.","When organizations that own the systems are small or the structures of the organizations require that assessments be conducted by individuals that are in the developmental, operational, or management chain of the system owners, independence in assessment processes can be achieved by ensuring that assessment results are carefully reviewed and analyzed by independent teams of experts to validate the completeness, accuracy, integrity, and reliability of the results. Assessments performed for purposes other than to support authorization decisions are more likely to be useable for such decisions when performed by assessors with sufficient independence, thereby reducing the need to repeat assessments."],"params":[],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Assessment, authorization, and monitoring policy","procedures addressing control assessments","previous control assessment plan","previous control assessment report","plan of action and milestones","existing authorization statement","system security plan","privacy plan"]},{"method":"Interview","objects":["Organizational personnel with security assessment responsibilities","organizational personnel with information security and privacy responsibilities"]}]},"CA-2(2)":{"statement":[{"prose":"Include as part of control assessments, [Assignment: organization-defined specialized assessment frequency], [Selection: announced; unannounced], [Selection (one or more): in-depth monitoring; security instrumentation; automated security test cases; vulnerability scanning; malicious user testing; insider threat assessment; performance and load testing; data leakage or data loss assessment; [Assignment: organization-defined other forms of assessment]]."}],"discussion":["Organizations can conduct specialized assessments, including verification and validation, system monitoring, insider threat assessments, malicious user testing, and other forms of testing. These assessments can improve readiness by exercising organizational capabilities and indicating current levels of performance as a means of focusing actions to improve security and privacy. Organizations conduct specialized assessments in accordance with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Authorizing officials approve the assessment methods in coordination with the organizational risk executive function. Organizations can include vulnerabilities uncovered during assessments into vulnerability remediation processes. Specialized assessments can also be conducted early in the system development life cycle (e.g., during initial design, development, and unit testing)."],"params":[{"id":"CA-02(02)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined specialized assessment frequency]","guideline":"frequency at which to include specialized assessments as part of the control assessment is defined"},{"id":"CA-02(02)_ODP[02]","kind":"Selection","value":"[Selection: announced; unannounced]"},{"id":"CA-02(02)_ODP[03]","kind":"Selection","value":"[Selection (one or more): in-depth monitoring; security instrumentation; automated security test cases; vulnerability scanning; malicious user testing; insider threat assessment; performance and load testing; data leakage or data loss assessment; [Assignment: organization-defined other forms of assessment]]"},{"id":"CA-02(02)_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined other forms of assessment]","guideline":"other forms of assessment are defined (if selected)"}],"related":["PE-3","SI-2"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Assessment, authorization, and monitoring policy","procedures addressing control assessments","control assessment plan","control assessment report","control assessment evidence","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with control assessment responsibilities","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Mechanisms supporting control assessment"]}]},"CA-3":{"statement":[{"label":"a.","prose":"Approve and manage the exchange of information between the system and other systems using [Selection (one or more): interconnection security agreements; information exchange security agreements; memoranda of understanding or agreement; service level agreements; user agreements; non-disclosure agreements; [Assignment: organization-defined type of agreement]];"},{"label":"b.","prose":"Document, as part of each exchange agreement, the interface characteristics, security and privacy requirements, controls, and responsibilities for each system, and the impact level of the information communicated; and"},{"label":"c.","prose":"Review and update the agreements [Assignment: organization-defined frequency]."}],"discussion":["System information exchange requirements apply to information exchanges between two or more systems. System information exchanges include connections via leased lines or virtual private networks, connections to internet service providers, database sharing or exchanges of database transaction information, connections and exchanges with cloud services, exchanges via web-based services, or exchanges of files via file transfer protocols, network protocols (e.g., IPv4, IPv6), email, or other organization-to-organization communications. Organizations consider the risk related to new or increased threats that may be introduced when systems exchange information with other systems that may have different security and privacy requirements and controls. This includes systems within the same organization and systems that are external to the organization. A joint authorization of the systems exchanging information, as described in [CA-6(1)](#ca-6.1) or [CA-6(2)](#ca-6.2), may help to communicate and reduce risk.","Authorizing officials determine the risk associated with system information exchange and the controls needed for appropriate risk mitigation. The types of agreements selected are based on factors such as the impact level of the information being exchanged, the relationship between the organizations exchanging information (e.g., government to government, government to business, business to business, government or business to service provider, government or business to individual), or the level of access to the organizational system by users of the other system. If systems that exchange information have the same authorizing official, organizations need not develop agreements. Instead, the interface characteristics between the systems (e.g., how the information is being exchanged. how the information is protected) are described in the respective security and privacy plans. If the systems that exchange information have different authorizing officials within the same organization, the organizations can develop agreements or provide the same information that would be provided in the appropriate agreement type from [CA-3a](#ca-3_smt.a) in the respective security and privacy plans for the systems. Organizations may incorporate agreement information into formal contracts, especially for information exchanges established between federal agencies and nonfederal organizations (including service providers, contractors, system developers, and system integrators). Risk considerations include systems that share the same networks."],"params":[{"id":"CA-03_ODP[01]","kind":"Selection","value":"[Selection (one or more): interconnection security agreements; information exchange security agreements; memoranda of understanding or agreement; service level agreements; user agreements; non-disclosure agreements; [Assignment: organization-defined type of agreement]]"},{"id":"CA-03_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined type of agreement]","guideline":"the type of agreement used to approve and manage the exchange of information is defined (if selected)"},{"id":"CA-03_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to review and update agreements is defined"}],"related":["AC-4","AC-20","AU-16","CA-6","IA-3","IR-4","PL-2","PT-7","RA-3","SA-9","SC-7","SI-12"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"FIPS 199","url":"https://doi.org/10.6028/NIST.FIPS.199"},{"title":"SP 800-47","url":"https://doi.org/10.6028/NIST.SP.800-47"}],"objectives":[{"label":"CA-03a.","prose":"the exchange of information between the system and other systems is approved and managed using [Selection (one or more): interconnection security agreements; information exchange security agreements; memoranda of understanding or agreement; service level agreements; user agreements; non-disclosure agreements; [Assignment: organization-defined type of agreement]];"},{"label":"CA-03b.","prose":"","items":[{"label":"CA-03b.[01]","prose":"the interface characteristics are documented as part of each exchange agreement;"},{"label":"CA-03b.[02]","prose":"security requirements are documented as part of each exchange agreement;"},{"label":"CA-03b.[03]","prose":"privacy requirements are documented as part of each exchange agreement;"},{"label":"CA-03b.[04]","prose":"controls are documented as part of each exchange agreement;"},{"label":"CA-03b.[05]","prose":"responsibilities for each system are documented as part of each exchange agreement;"},{"label":"CA-03b.[06]","prose":"the impact level of the information communicated is documented as part of each exchange agreement;"}]},{"label":"CA-03c.","prose":"agreements are reviewed and updated [Assignment: organization-defined frequency]."}],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing system connections","system and communications protection policy","system interconnection security agreements","information exchange security agreements","memoranda of understanding or agreements","service level agreements","non-disclosure agreements"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for developing, implementing, or approving system interconnection agreements","organizational personnel with information security and privacy responsibilities","personnel managing the system(s) to which the interconnection security agreement applies"]}]},"CA-3(6)":{"statement":[{"prose":"Verify that individuals or systems transferring data between interconnecting systems have the requisite authorizations (i.e., write permissions or privileges) prior to accepting such data."}],"discussion":["To prevent unauthorized individuals and systems from making information transfers to protected systems, the protected system verifies—via independent means— whether the individual or system attempting to transfer information is authorized to do so. Verification of the authorization to transfer information also applies to control plane traffic (e.g., routing and DNS) and services (e.g., authenticated SMTP relays)."],"params":[],"related":["AC-2","AC-3","AC-4"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Access control policy","procedures addressing system connections","system and communications protection policy","system interconnection agreements","information exchange security agreements","memoranda of understanding or agreements","service level agreements","non-disclosure agreements"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for managing connections to external systems","network administrators","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Mechanisms implementing restrictions on external system connections"]}]},"CA-5":{"statement":[{"label":"a.","prose":"Develop a plan of action and milestones for the system to document the planned remediation actions of the organization to correct weaknesses or deficiencies noted during the assessment of the controls and to reduce or eliminate known vulnerabilities in the system; and"},{"label":"b.","prose":"Update existing plan of action and milestones [Assignment: organization-defined frequency] based on the findings from control assessments, independent audits or reviews, and continuous monitoring activities."}],"discussion":["Plans of action and milestones are useful for any type of organization to track planned remedial actions. Plans of action and milestones are required in authorization packages and subject to federal reporting requirements established by OMB."],"params":[{"id":"CA-05_ODP","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to update an existing plan of action and milestones based on the findings from control assessments, independent audits or reviews, and continuous monitoring activities is defined"}],"related":["CA-2","CA-7","PM-4","PM-9","RA-7","SI-2","SI-12"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-37","url":"https://doi.org/10.6028/NIST.SP.800-37r2"}],"objectives":[{"label":"CA-05a.","prose":"a plan of action and milestones for the system is developed to document the planned remediation actions of the organization to correct weaknesses or deficiencies noted during the assessment of the controls and to reduce or eliminate known vulnerabilities in the system;"},{"label":"CA-05b.","prose":"existing plan of action and milestones are updated [Assignment: organization-defined frequency] based on the findings from control assessments, independent audits or reviews, and continuous monitoring activities."}],"methods":[{"method":"Examine","objects":["Assessment, authorization, and monitoring policy","procedures addressing plan of action and milestones","control assessment plan","control assessment report","control assessment evidence","plan of action and milestones","system security plan","privacy plan"]},{"method":"Interview","objects":["Organizational personnel with plan of action and milestones development and implementation responsibilities","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Mechanisms for developing, implementing, and maintaining plan of action and milestones"]}]},"CA-6":{"statement":[{"label":"a.","prose":"Assign a senior official as the authorizing official for the system;"},{"label":"b.","prose":"Assign a senior official as the authorizing official for common controls available for inheritance by organizational systems;"},{"label":"c.","prose":"Ensure that the authorizing official for the system, before commencing operations:","items":[{"label":"1.","prose":"Accepts the use of common controls inherited by the system; and"},{"label":"2.","prose":"Authorizes the system to operate;"}]},{"label":"d.","prose":"Ensure that the authorizing official for common controls authorizes the use of those controls for inheritance by organizational systems;"},{"label":"e.","prose":"Update the authorizations [Assignment: organization-defined frequency]."}],"discussion":["Authorizations are official management decisions by senior officials to authorize operation of systems, authorize the use of common controls for inheritance by organizational systems, and explicitly accept the risk to organizational operations and assets, individuals, other organizations, and the Nation based on the implementation of agreed-upon controls. Authorizing officials provide budgetary oversight for organizational systems and common controls or assume responsibility for the mission and business functions supported by those systems or common controls. The authorization process is a federal responsibility, and therefore, authorizing officials must be federal employees. Authorizing officials are both responsible and accountable for security and privacy risks associated with the operation and use of organizational systems. Nonfederal organizations may have similar processes to authorize systems and senior officials that assume the authorization role and associated responsibilities.","Authorizing officials issue ongoing authorizations of systems based on evidence produced from implemented continuous monitoring programs. Robust continuous monitoring programs reduce the need for separate reauthorization processes. Through the employment of comprehensive continuous monitoring processes, the information contained in authorization packages (i.e., security and privacy plans, assessment reports, and plans of action and milestones) is updated on an ongoing basis. This provides authorizing officials, common control providers, and system owners with an up-to-date status of the security and privacy posture of their systems, controls, and operating environments. To reduce the cost of reauthorization, authorizing officials can leverage the results of continuous monitoring processes to the maximum extent possible as the basis for rendering reauthorization decisions."],"params":[{"id":"CA-06_ODP","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to update the authorizations is defined"}],"related":["CA-2","CA-3","CA-7","PM-9","PM-10","RA-3","SA-10","SI-12"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-37","url":"https://doi.org/10.6028/NIST.SP.800-37r2"},{"title":"SP 800-137","url":"https://doi.org/10.6028/NIST.SP.800-137"}],"objectives":[{"label":"CA-06a.","prose":"a senior official is assigned as the authorizing official for the system;"},{"label":"CA-06b.","prose":"a senior official is assigned as the authorizing official for common controls available for inheritance by organizational systems;"},{"label":"CA-06c.","prose":"","items":[{"label":"CA-06c.01","prose":"before commencing operations, the authorizing official for the system accepts the use of common controls inherited by the system;"},{"label":"CA-06c.02","prose":"before commencing operations, the authorizing official for the system authorizes the system to operate;"}]},{"label":"CA-06d.","prose":"the authorizing official for common controls authorizes the use of those controls for inheritance by organizational systems;"},{"label":"CA-06e.","prose":"the authorizations are updated [Assignment: organization-defined frequency]."}],"methods":[{"method":"Examine","objects":["Assessment, authorization, and monitoring policy","procedures addressing authorization","system security plan, privacy plan, assessment report, plan of action and milestones","authorization statement","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with authorization responsibilities","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Mechanisms that facilitate authorizations and updates"]}]},"CA-7":{"statement":[{"prose":"Develop a system-level continuous monitoring strategy and implement continuous monitoring in accordance with the organization-level continuous monitoring strategy that includes:"},{"label":"a.","prose":"Establishing the following system-level metrics to be monitored: [Assignment: organization-defined system-level metrics];"},{"label":"b.","prose":"Establishing [Assignment: organization-defined frequencies] for monitoring and [Assignment: organization-defined frequencies] for assessment of control effectiveness;"},{"label":"c.","prose":"Ongoing control assessments in accordance with the continuous monitoring strategy;"},{"label":"d.","prose":"Ongoing monitoring of system and organization-defined metrics in accordance with the continuous monitoring strategy;"},{"label":"e.","prose":"Correlation and analysis of information generated by control assessments and monitoring;"},{"label":"f.","prose":"Response actions to address results of the analysis of control assessment and monitoring information; and"},{"label":"g.","prose":"Reporting the security and privacy status of the system to [Assignment: organization-defined personnel or roles] [Assignment: organization-defined frequency]."}],"discussion":["Continuous monitoring at the system level facilitates ongoing awareness of the system security and privacy posture to support organizational risk management decisions. The terms \"continuous\" and \"ongoing\" imply that organizations assess and monitor their controls and risks at a frequency sufficient to support risk-based decisions. Different types of controls may require different monitoring frequencies. The results of continuous monitoring generate risk response actions by organizations. When monitoring the effectiveness of multiple controls that have been grouped into capabilities, a root-cause analysis may be needed to determine the specific control that has failed. Continuous monitoring programs allow organizations to maintain the authorizations of systems and common controls in highly dynamic environments of operation with changing mission and business needs, threats, vulnerabilities, and technologies. Having access to security and privacy information on a continuing basis through reports and dashboards gives organizational officials the ability to make effective and timely risk management decisions, including ongoing authorization decisions.","Automation supports more frequent updates to hardware, software, and firmware inventories, authorization packages, and other system information. Effectiveness is further enhanced when continuous monitoring outputs are formatted to provide information that is specific, measurable, actionable, relevant, and timely. Continuous monitoring activities are scaled in accordance with the security categories of systems. Monitoring requirements, including the need for specific monitoring, may be referenced in other controls and control enhancements, such as [AC-2g](#ac-2_smt.g), [AC-2(7)](#ac-2.7), [AC-2(12)(a)](#ac-2.12_smt.a), [AC-2(7)(b)](#ac-2.7_smt.b), [AC-2(7)(c)](#ac-2.7_smt.c), [AC-17(1)](#ac-17.1), [AT-4a](#at-4_smt.a), [AU-13](#au-13), [AU-13(1)](#au-13.1), [AU-13(2)](#au-13.2), [CM-3f](#cm-3_smt.f), [CM-6d](#cm-6_smt.d), [CM-11c](#cm-11_smt.c), [IR-5](#ir-5), [MA-2b](#ma-2_smt.b), [MA-3a](#ma-3_smt.a), [MA-4a](#ma-4_smt.a), [PE-3d](#pe-3_smt.d), [PE-6](#pe-6), [PE-14b](#pe-14_smt.b), [PE-16](#pe-16), [PE-20](#pe-20), [PM-6](#pm-6), [PM-23](#pm-23), [PM-31](#pm-31), [PS-7e](#ps-7_smt.e), [SA-9c](#sa-9_smt.c), [SR-4](#sr-4), [SC-5(3)(b)](#sc-5.3_smt.b), [SC-7a](#sc-7_smt.a), [SC-7(24)(b)](#sc-7.24_smt.b), [SC-18b](#sc-18_smt.b), [SC-43b](#sc-43_smt.b), and [SI-4](#si-4)."],"params":[{"id":"CA-7_PRM_4","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]"},{"id":"CA-7_PRM_5","kind":"Assignment","value":"[Assignment: organization-defined frequency]"},{"id":"CA-07_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined system-level metrics]","guideline":"system-level metrics to be monitored are defined"},{"id":"CA-07_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined frequencies]","guideline":"frequencies at which to monitor control effectiveness are defined"},{"id":"CA-07_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined frequencies]","guideline":"frequencies at which to assess control effectiveness are defined"},{"id":"CA-07_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the security status of the system is reported are defined"},{"id":"CA-07_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which the security status of the system is reported is defined"},{"id":"CA-07_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the privacy status of the system is reported are defined"},{"id":"CA-07_ODP[07]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which the privacy status of the system is reported is defined"}],"related":["AC-2","AC-6","AC-17","AT-4","AU-6","AU-13","CA-2","CA-5","CA-6","CM-3","CM-4","CM-6","CM-11","IA-5","IR-5","MA-2","MA-3","MA-4","PE-3","PE-6","PE-14","PE-16","PE-20","PL-2","PM-4","PM-6","PM-9","PM-10","PM-12","PM-14","PM-23","PM-28","PM-31","PS-7","PT-7","RA-3","RA-5","RA-7","RA-10","SA-8","SA-9","SA-11","SC-5","SC-7","SC-18","SC-38","SC-43","SI-3","SI-4","SI-12","SR-6"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-37","url":"https://doi.org/10.6028/NIST.SP.800-37r2"},{"title":"SP 800-39","url":"https://doi.org/10.6028/NIST.SP.800-39"},{"title":"SP 800-53A","url":"https://doi.org/10.6028/NIST.SP.800-53Ar4"},{"title":"SP 800-115","url":"https://doi.org/10.6028/NIST.SP.800-115"},{"title":"SP 800-137","url":"https://doi.org/10.6028/NIST.SP.800-137"},{"title":"IR 8011-1","url":"https://doi.org/10.6028/NIST.IR.8011-1"},{"title":"IR 8062","url":"https://doi.org/10.6028/NIST.IR.8062"}],"objectives":[{"label":"CA-07[01]","prose":"a system-level continuous monitoring strategy is developed;"},{"label":"CA-07[02]","prose":"system-level continuous monitoring is implemented in accordance with the organization-level continuous monitoring strategy;"},{"label":"CA-07a.","prose":"system-level continuous monitoring includes establishment of the following system-level metrics to be monitored: [Assignment: organization-defined system-level metrics];"},{"label":"CA-07b.","prose":"","items":[{"label":"CA-07b.[01]","prose":"system-level continuous monitoring includes established [Assignment: organization-defined frequencies] for monitoring;"},{"label":"CA-07b.[02]","prose":"system-level continuous monitoring includes established [Assignment: organization-defined frequencies] for assessment of control effectiveness;"}]},{"label":"CA-07c.","prose":"system-level continuous monitoring includes ongoing control assessments in accordance with the continuous monitoring strategy;"},{"label":"CA-07d.","prose":"system-level continuous monitoring includes ongoing monitoring of system and organization-defined metrics in accordance with the continuous monitoring strategy;"},{"label":"CA-07e.","prose":"system-level continuous monitoring includes correlation and analysis of information generated by control assessments and monitoring;"},{"label":"CA-07f.","prose":"system-level continuous monitoring includes response actions to address the results of the analysis of control assessment and monitoring information;"},{"label":"CA-07g.","prose":"","items":[{"label":"CA-07g.[01]","prose":"system-level continuous monitoring includes reporting the security status of the system to [Assignment: organization-defined personnel or roles] [Assignment: organization-defined frequency];"},{"label":"CA-07g.[02]","prose":"system-level continuous monitoring includes reporting the privacy status of the system to [Assignment: organization-defined personnel or roles] [Assignment: organization-defined frequency]."}]}],"methods":[{"method":"Examine","objects":["Assessment, authorization, and monitoring policy","organizational continuous monitoring strategy","system-level continuous monitoring strategy","procedures addressing continuous monitoring of system controls","procedures addressing configuration management","control assessment report","plan of action and milestones","system monitoring records"]},{"method":"Interview","objects":["Organizational personnel with continuous monitoring responsibilities","organizational personnel with information security and privacy responsibilities","system/network administrators"]},{"method":"Test","objects":["Mechanisms implementing continuous monitoring","mechanisms supporting response actions to address assessment and monitoring results","mechanisms supporting security and privacy status reporting"]}]},"CA-7(1)":{"statement":[{"prose":"Employ independent assessors or assessment teams to monitor the controls in the system on an ongoing basis."}],"discussion":["Organizations maximize the value of control assessments by requiring that assessments be conducted by assessors with appropriate levels of independence. The level of required independence is based on organizational continuous monitoring strategies. Assessor independence provides a degree of impartiality to the monitoring process. To achieve such impartiality, assessors do not create a mutual or conflicting interest with the organizations where the assessments are being conducted, assess their own work, act as management or employees of the organizations they are serving, or place themselves in advocacy positions for the organizations acquiring their services."],"params":[],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Assessment, authorization, and monitoring policy","organizational continuous monitoring strategy","system-level continuous monitoring strategy","procedures addressing continuous monitoring of system controls","control assessment report","plan of action and milestones","system monitoring records","impact analyses"]},{"method":"Interview","objects":["Organizational personnel with continuous monitoring responsibilities","organizational personnel with information security and privacy responsibilities"]}]},"CA-7(4)":{"statement":[{"prose":"Ensure risk monitoring is an integral part of the continuous monitoring strategy that includes the following:"},{"label":"(a)","prose":"Effectiveness monitoring;"},{"label":"(b)","prose":"Compliance monitoring; and"},{"label":"(c)","prose":"Change monitoring."}],"discussion":["Risk monitoring is informed by the established organizational risk tolerance. Effectiveness monitoring determines the ongoing effectiveness of the implemented risk response measures. Compliance monitoring verifies that required risk response measures are implemented. It also verifies that security and privacy requirements are satisfied. Change monitoring identifies changes to organizational systems and environments of operation that may affect security and privacy risk."],"params":[],"related":[],"references":[],"objectives":[{"label":"CA-07(04)(a)","prose":"effectiveness monitoring is included in risk monitoring;"},{"label":"CA-07(04)(b)","prose":"compliance monitoring is included in risk monitoring;"},{"label":"CA-07(04)(c)","prose":"change monitoring is included in risk monitoring."}],"methods":[{"method":"Examine","objects":["Assessment, authorization, and monitoring policy","organizational continuous monitoring strategy","system-level continuous monitoring strategy","procedures addressing continuous monitoring of system controls","assessment report","plan of action and milestones","system monitoring records","impact analyses"]},{"method":"Interview","objects":["Organizational personnel with continuous monitoring responsibilities","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Mechanisms supporting risk monitoring"]}]},"CA-8":{"statement":[{"prose":"Conduct penetration testing [Assignment: organization-defined frequency] on [Assignment: organization-defined system(s) or system components]."}],"discussion":["Penetration testing is a specialized type of assessment conducted on systems or individual system components to identify vulnerabilities that could be exploited by adversaries. Penetration testing goes beyond automated vulnerability scanning and is conducted by agents and teams with demonstrable skills and experience that include technical expertise in network, operating system, and/or application level security. Penetration testing can be used to validate vulnerabilities or determine the degree of penetration resistance of systems to adversaries within specified constraints. Such constraints include time, resources, and skills. Penetration testing attempts to duplicate the actions of adversaries and provides a more in-depth analysis of security- and privacy-related weaknesses or deficiencies. Penetration testing is especially important when organizations are transitioning from older technologies to newer technologies (e.g., transitioning from IPv4 to IPv6 network protocols).","Organizations can use the results of vulnerability analyses to support penetration testing activities. Penetration testing can be conducted internally or externally on the hardware, software, or firmware components of a system and can exercise both physical and technical controls. A standard method for penetration testing includes a pretest analysis based on full knowledge of the system, pretest identification of potential vulnerabilities based on the pretest analysis, and testing designed to determine the exploitability of vulnerabilities. All parties agree to the rules of engagement before commencing penetration testing scenarios. Organizations correlate the rules of engagement for the penetration tests with the tools, techniques, and procedures that are anticipated to be employed by adversaries. Penetration testing may result in the exposure of information that is protected by laws or regulations, to individuals conducting the testing. Rules of engagement, contracts, or other appropriate mechanisms can be used to communicate expectations for how to protect this information. Risk assessments guide the decisions on the level of independence required for the personnel conducting penetration testing."],"params":[{"id":"CA-08_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to conduct penetration testing on systems or system components is defined"},{"id":"CA-08_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined system(s) or system components]","guideline":"systems or system components on which penetration testing is to be conducted are defined"}],"related":["RA-5","RA-10","SA-11","SR-5","SR-6"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Assessment, authorization, and monitoring policy","procedures addressing penetration testing","assessment plan","penetration test report","assessment report","assessment evidence","system security plan","privacy plan"]},{"method":"Interview","objects":["Organizational personnel with control assessment responsibilities","organizational personnel with information security and privacy responsibilities","system/network administrators"]},{"method":"Test","objects":["Mechanisms supporting penetration testing"]}]},"CA-8(1)":{"statement":[{"prose":"Employ an independent penetration testing agent or team to perform penetration testing on the system or system components."}],"discussion":["Independent penetration testing agents or teams are individuals or groups who conduct impartial penetration testing of organizational systems. Impartiality implies that penetration testing agents or teams are free from perceived or actual conflicts of interest with respect to the development, operation, or management of the systems that are the targets of the penetration testing. [CA-2(1)](#ca-2.1) provides additional information on independent assessments that can be applied to penetration testing."],"params":[],"related":["CA-2"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Assessment, authorization, and monitoring policy","procedures addressing penetration testing","assessment plan","penetration test report","assessment report","security assessment evidence","system security plan","privacy plan"]},{"method":"Interview","objects":["Organizational personnel with assessment responsibilities","organizational personnel with information security and privacy responsibilities"]}]},"CA-9":{"statement":[{"label":"a.","prose":"Authorize internal connections of [Assignment: organization-defined system components] to the system;"},{"label":"b.","prose":"Document, for each internal connection, the interface characteristics, security and privacy requirements, and the nature of the information communicated;"},{"label":"c.","prose":"Terminate internal system connections after [Assignment: organization-defined conditions]; and"},{"label":"d.","prose":"Review [Assignment: organization-defined frequency] the continued need for each internal connection."}],"discussion":["Internal system connections are connections between organizational systems and separate constituent system components (i.e., connections between components that are part of the same system) including components used for system development. Intra-system connections include connections with mobile devices, notebook and desktop computers, tablets, printers, copiers, facsimile machines, scanners, sensors, and servers. Instead of authorizing each internal system connection individually, organizations can authorize internal connections for a class of system components with common characteristics and/or configurations, including printers, scanners, and copiers with a specified processing, transmission, and storage capability or smart phones and tablets with a specific baseline configuration. The continued need for an internal system connection is reviewed from the perspective of whether it provides support for organizational missions or business functions."],"params":[{"id":"CA-09_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined system components]","guideline":"system components or classes of components requiring internal connections to the system are defined"},{"id":"CA-09_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined conditions]","guideline":"conditions requiring termination of internal connections are defined"},{"id":"CA-09_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to review the continued need for each internal connection is defined"}],"related":["AC-3","AC-4","AC-18","AC-19","CM-2","IA-3","SC-7","SI-12"],"references":[{"title":"SP 800-124","url":"https://doi.org/10.6028/NIST.SP.800-124r1"},{"title":"IR 8023","url":"https://doi.org/10.6028/NIST.IR.8023"}],"objectives":[{"label":"CA-09a.","prose":"internal connections of [Assignment: organization-defined system components] to the system are authorized;"},{"label":"CA-09b.","prose":"","items":[{"label":"CA-09b.[01]","prose":"for each internal connection, the interface characteristics are documented;"},{"label":"CA-09b.[02]","prose":"for each internal connection, the security requirements are documented;"},{"label":"CA-09b.[03]","prose":"for each internal connection, the privacy requirements are documented;"},{"label":"CA-09b.[04]","prose":"for each internal connection, the nature of the information communicated is documented;"}]},{"label":"CA-09c.","prose":"internal system connections are terminated after [Assignment: organization-defined conditions];"},{"label":"CA-09d.","prose":"the continued need for each internal connection is reviewed [Assignment: organization-defined frequency]."}],"methods":[{"method":"Examine","objects":["Assessment, authorization, and monitoring policy","access control policy","procedures addressing system connections","system and communications protection policy","system design documentation","system configuration settings and associated documentation","list of components or classes of components authorized as internal system connections","assessment report"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for developing, implementing, or authorizing internal system connections","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Mechanisms supporting internal system connections"]}]},"CM-1":{"statement":[{"label":"a.","prose":"Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:","items":[{"label":"1.","prose":"[Selection (one or more): organization-level; mission/business process-level; system-level] configuration management policy that:","items":[{"label":"(a)","prose":"Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and"},{"label":"(b)","prose":"Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and"}]},{"label":"2.","prose":"Procedures to facilitate the implementation of the configuration management policy and the associated configuration management controls;"}]},{"label":"b.","prose":"Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the configuration management policy and procedures; and"},{"label":"c.","prose":"Review and update the current configuration management:","items":[{"label":"1.","prose":"Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and"},{"label":"2.","prose":"Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]."}]}],"discussion":["Configuration management policy and procedures address the controls in the CM family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of configuration management policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission/business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to configuration management policy and procedures include, but are not limited to, assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure."],"params":[{"id":"CM-1_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]"},{"id":"CM-01_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the configuration management policy is to be disseminated is/are defined"},{"id":"CM-01_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the configuration management procedures are to be disseminated is/are defined"},{"id":"CM-01_ODP[03]","kind":"Selection","value":"[Selection (one or more): organization-level; mission/business process-level; system-level]"},{"id":"CM-01_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined official]","guideline":"an official to manage the configuration management policy and procedures is defined"},{"id":"CM-01_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current configuration management policy is reviewed and updated is defined"},{"id":"CM-01_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require the current configuration management policy to be reviewed and updated are defined"},{"id":"CM-01_ODP[07]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current configuration management procedures are reviewed and updated is defined"},{"id":"CM-01_ODP[08]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require configuration management procedures to be reviewed and updated are defined"}],"related":["PM-9","PS-8","SA-8","SI-12"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-12","url":"https://doi.org/10.6028/NIST.SP.800-12r1"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-39","url":"https://doi.org/10.6028/NIST.SP.800-39"},{"title":"SP 800-100","url":"https://doi.org/10.6028/NIST.SP.800-100"}],"objectives":[{"label":"CM-01a.","prose":"","items":[{"label":"CM-01a.[01]","prose":"a configuration management policy is developed and documented;"},{"label":"CM-01a.[02]","prose":"the configuration management policy is disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"CM-01a.[03]","prose":"configuration management procedures to facilitate the implementation of the configuration management policy and associated configuration management controls are developed and documented;"},{"label":"CM-01a.[04]","prose":"the configuration management procedures are disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"CM-01a.01","prose":"","items":[{"label":"CM-01a.01(a)","prose":"","items":[{"label":"CM-01a.01(a)[01]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] of the configuration management policy addresses purpose;"},{"label":"CM-01a.01(a)[02]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] of the configuration management policy addresses scope;"},{"label":"CM-01a.01(a)[03]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] of the configuration management policy addresses roles;"},{"label":"CM-01a.01(a)[04]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] of the configuration management policy addresses responsibilities;"},{"label":"CM-01a.01(a)[05]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] of the configuration management policy addresses management commitment;"},{"label":"CM-01a.01(a)[06]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] of the configuration management policy addresses coordination among organizational entities;"},{"label":"CM-01a.01(a)[07]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] of the configuration management policy addresses compliance;"}]},{"label":"CM-01a.01(b)","prose":"the configuration management policy is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines;"}]}]},{"label":"CM-01b.","prose":"the [Assignment: organization-defined official] is designated to manage the development, documentation, and dissemination of the configuration management policy and procedures;"},{"label":"CM-01c.","prose":"","items":[{"label":"CM-01c.01","prose":"","items":[{"label":"CM-01c.01[01]","prose":"the current configuration management policy is reviewed and updated [Assignment: organization-defined frequency];"},{"label":"CM-01c.01[02]","prose":"the current configuration management policy is reviewed and updated following [Assignment: organization-defined events];"}]},{"label":"CM-01c.02","prose":"","items":[{"label":"CM-01c.02[01]","prose":"the current configuration management procedures are reviewed and updated [Assignment: organization-defined frequency];"},{"label":"CM-01c.02[02]","prose":"the current configuration management procedures are reviewed and updated following [Assignment: organization-defined events]."}]}]}],"methods":[{"method":"Examine","objects":["Configuration management policy and procedures","security and privacy program policies and procedures","assessment or audit findings","documentation of security incidents or breaches","system security plan","privacy plan","risk management strategy","other relevant artifacts, documents, or records"]},{"method":"Interview","objects":["Organizational personnel with configuration management responsibilities","organizational personnel with information security and privacy responsibilities"]}]},"CM-2":{"statement":[{"label":"a.","prose":"Develop, document, and maintain under configuration control, a current baseline configuration of the system; and"},{"label":"b.","prose":"Review and update the baseline configuration of the system:","items":[{"label":"1.","prose":"[Assignment: organization-defined frequency];"},{"label":"2.","prose":"When required due to [Assignment: organization-defined circumstances]; and"},{"label":"3.","prose":"When system components are installed or upgraded."}]}],"discussion":["Baseline configurations for systems and system components include connectivity, operational, and communications aspects of systems. Baseline configurations are documented, formally reviewed, and agreed-upon specifications for systems or configuration items within those systems. Baseline configurations serve as a basis for future builds, releases, or changes to systems and include security and privacy control implementations, operational procedures, information about system components, network topology, and logical placement of components in the system architecture. Maintaining baseline configurations requires creating new baselines as organizational systems change over time. Baseline configurations of systems reflect the current enterprise architecture."],"params":[{"id":"CM-02_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency of baseline configuration review and update is defined"},{"id":"CM-02_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined circumstances]","guideline":"the circumstances requiring baseline configuration review and update are defined"}],"related":["AC-19","AU-6","CA-9","CM-1","CM-3","CM-5","CM-6","CM-8","CM-9","CP-9","CP-10","CP-12","MA-2","PL-8","PM-5","SA-8","SA-10","SA-15","SC-18"],"references":[{"title":"SP 800-124","url":"https://doi.org/10.6028/NIST.SP.800-124r1"},{"title":"SP 800-128","url":"https://doi.org/10.6028/NIST.SP.800-128"}],"objectives":[{"label":"CM-02a.","prose":"","items":[{"label":"CM-02a.[01]","prose":"a current baseline configuration of the system is developed and documented;"},{"label":"CM-02a.[02]","prose":"a current baseline configuration of the system is maintained under configuration control;"}]},{"label":"CM-02b.","prose":"","items":[{"label":"CM-02b.01","prose":"the baseline configuration of the system is reviewed and updated [Assignment: organization-defined frequency];"},{"label":"CM-02b.02","prose":"the baseline configuration of the system is reviewed and updated when required due to [Assignment: organization-defined circumstances];"},{"label":"CM-02b.03","prose":"the baseline configuration of the system is reviewed and updated when system components are installed or upgraded."}]}],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing the baseline configuration of the system","configuration management plan","enterprise architecture documentation","system design documentation","system security plan","privacy plan","system architecture and configuration documentation"]},{"method":"Interview","objects":["Organizational personnel with configuration management responsibilities","organizational personnel with information security and privacy responsibilities","system/network administrators"]},{"method":"Test","objects":["Organizational processes for managing baseline configurations","mechanisms supporting configuration control of the baseline configuration"]}]},"CM-2(2)":{"statement":[{"prose":"Maintain the currency, completeness, accuracy, and availability of the baseline configuration of the system using [Assignment: organization-defined automated mechanisms]."}],"discussion":["Automated mechanisms that help organizations maintain consistent baseline configurations for systems include configuration management tools, hardware, software, firmware inventory tools, and network management tools. Automated tools can be used at the organization level, mission and business process level, or system level on workstations, servers, notebook computers, network components, or mobile devices. Tools can be used to track version numbers on operating systems, applications, types of software installed, and current patch levels. Automation support for accuracy and currency can be satisfied by the implementation of [CM-8(2)](#cm-8.2) for organizations that combine system component inventory and baseline configuration activities."],"params":[{"id":"CM-02(02)_ODP","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms for maintaining baseline configuration of the system are defined"}],"related":["CM-7","IA-3","RA-5"],"references":[],"objectives":[{"label":"CM-02(02)[01]","prose":"the currency of the baseline configuration of the system is maintained using [Assignment: organization-defined automated mechanisms];"},{"label":"CM-02(02)[02]","prose":"the completeness of the baseline configuration of the system is maintained using [Assignment: organization-defined automated mechanisms];"},{"label":"CM-02(02)[03]","prose":"the accuracy of the baseline configuration of the system is maintained using [Assignment: organization-defined automated mechanisms];"},{"label":"CM-02(02)[04]","prose":"the availability of the baseline configuration of the system is maintained using [Assignment: organization-defined automated mechanisms]."}],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing the baseline configuration of the system","configuration management plan","system design documentation","system architecture and configuration documentation","system configuration settings and associated documentation","system component inventory","configuration change control records"]},{"method":"Interview","objects":["Organizational personnel with configuration management responsibilities","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Organizational processes for managing baseline configurations","automated mechanisms implementing baseline configuration maintenance"]}]},"CM-2(3)":{"statement":[{"prose":"Retain [Assignment: organization-defined number] of previous versions of baseline configurations of the system to support rollback."}],"discussion":["Retaining previous versions of baseline configurations to support rollback include hardware, software, firmware, configuration files, configuration records, and associated documentation."],"params":[{"id":"CM-02(03)_ODP","kind":"Assignment","value":"[Assignment: organization-defined number]","guideline":"the number of previous baseline configuration versions to be retained is defined"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing the baseline configuration of the system","configuration management plan","system architecture and configuration documentation","system configuration settings and associated documentation","copies of previous baseline configuration versions","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with configuration management responsibilities","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Organizational processes for managing baseline configurations"]}]},"CM-2(7)":{"statement":[{"label":"(a)","prose":"Issue [Assignment: organization-defined systems or system components] with [Assignment: organization-defined configurations] to individuals traveling to locations that the organization deems to be of significant risk; and"},{"label":"(b)","prose":"Apply the following controls to the systems or components when the individuals return from travel: [Assignment: organization-defined controls]."}],"discussion":["When it is known that systems or system components will be in high-risk areas external to the organization, additional controls may be implemented to counter the increased threat in such areas. For example, organizations can take actions for notebook computers used by individuals departing on and returning from travel. Actions include determining the locations that are of concern, defining the required configurations for the components, ensuring that components are configured as intended before travel is initiated, and applying controls to the components after travel is completed. Specially configured notebook computers include computers with sanitized hard drives, limited applications, and more stringent configuration settings. Controls applied to mobile devices upon return from travel include examining the mobile device for signs of physical tampering and purging and reimaging disk drives. Protecting information that resides on mobile devices is addressed in the [MP](#mp) (Media Protection) family."],"params":[{"id":"CM-02(07)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined systems or system components]","guideline":"the systems or system components to be issued when individuals travel to high-risk areas are defined"},{"id":"CM-02(07)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined configurations]","guideline":"configurations for systems or system components to be issued when individuals travel to high-risk areas are defined"},{"id":"CM-02(07)_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined controls]","guideline":"the controls to be applied when the individuals return from travel are defined"}],"related":["MP-4","MP-5"],"references":[],"objectives":[{"label":"CM-02(07)(a)","prose":"[Assignment: organization-defined systems or system components] with [Assignment: organization-defined configurations] are issued to individuals traveling to locations that the organization deems to be of significant risk;"},{"label":"CM-02(07)(b)","prose":"[Assignment: organization-defined controls] are applied to the systems or system components when the individuals return from travel."}],"methods":[{"method":"Examine","objects":["Configuration management policy","configuration management plan","procedures addressing the baseline configuration of the system","procedures addressing system component installations and upgrades","system architecture and configuration documentation","system configuration settings and associated documentation","system component inventory","records of system baseline configuration reviews and updates"]},{"method":"Interview","objects":["Organizational personnel with configuration management responsibilities","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Organizational processes for managing baseline configurations"]}]},"CM-3":{"statement":[{"label":"a.","prose":"Determine and document the types of changes to the system that are configuration-controlled;"},{"label":"b.","prose":"Review proposed configuration-controlled changes to the system and approve or disapprove such changes with explicit consideration for security and privacy impact analyses;"},{"label":"c.","prose":"Document configuration change decisions associated with the system;"},{"label":"d.","prose":"Implement approved configuration-controlled changes to the system;"},{"label":"e.","prose":"Retain records of configuration-controlled changes to the system for [Assignment: organization-defined time period];"},{"label":"f.","prose":"Monitor and review activities associated with configuration-controlled changes to the system; and"},{"label":"g.","prose":"Coordinate and provide oversight for configuration change control activities through [Assignment: organization-defined configuration change control element] that convenes [Selection (one or more): [Assignment: organization-defined frequency]; when [Assignment: organization-defined configuration change conditions]]."}],"discussion":["Configuration change control for organizational systems involves the systematic proposal, justification, implementation, testing, review, and disposition of system changes, including system upgrades and modifications. Configuration change control includes changes to baseline configurations, configuration items of systems, operational procedures, configuration settings for system components, remediate vulnerabilities, and unscheduled or unauthorized changes. Processes for managing configuration changes to systems include Configuration Control Boards or Change Advisory Boards that review and approve proposed changes. For changes that impact privacy risk, the senior agency official for privacy updates privacy impact assessments and system of records notices. For new systems or major upgrades, organizations consider including representatives from the development organizations on the Configuration Control Boards or Change Advisory Boards. Auditing of changes includes activities before and after changes are made to systems and the auditing activities required to implement such changes. See also [SA-10](#sa-10)."],"params":[{"id":"CM-03_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"the time period to retain records of configuration-controlled changes is defined"},{"id":"CM-03_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined configuration change control element]","guideline":"the configuration change control element responsible for coordinating and overseeing change control activities is defined"},{"id":"CM-03_ODP[03]","kind":"Selection","value":"[Selection (one or more): [Assignment: organization-defined frequency]; when [Assignment: organization-defined configuration change conditions]]"},{"id":"CM-03_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the configuration control element convenes is defined (if selected)"},{"id":"CM-03_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined configuration change conditions]","guideline":"configuration change conditions that prompt the configuration control element to convene are defined (if selected)"}],"related":["CA-7","CM-2","CM-4","CM-5","CM-6","CM-9","CM-11","IA-3","MA-2","PE-16","PT-6","RA-8","SA-8","SA-10","SC-28","SC-34","SC-37","SI-2","SI-3","SI-4","SI-7","SI-10","SR-11"],"references":[{"title":"SP 800-124","url":"https://doi.org/10.6028/NIST.SP.800-124r1"},{"title":"SP 800-128","url":"https://doi.org/10.6028/NIST.SP.800-128"},{"title":"IR 8062","url":"https://doi.org/10.6028/NIST.IR.8062"}],"objectives":[{"label":"CM-03a.","prose":"the types of changes to the system that are configuration-controlled are determined and documented;"},{"label":"CM-03b.","prose":"","items":[{"label":"CM-03b.[01]","prose":"proposed configuration-controlled changes to the system are reviewed;"},{"label":"CM-03b.[02]","prose":"proposed configuration-controlled changes to the system are approved or disapproved with explicit consideration for security and privacy impact analyses;"}]},{"label":"CM-03c.","prose":"configuration change decisions associated with the system are documented;"},{"label":"CM-03d.","prose":"approved configuration-controlled changes to the system are implemented;"},{"label":"CM-03e.","prose":"records of configuration-controlled changes to the system are retained for [Assignment: organization-defined time period];"},{"label":"CM-03f.","prose":"","items":[{"label":"CM-03f.[01]","prose":"activities associated with configuration-controlled changes to the system are monitored;"},{"label":"CM-03f.[02]","prose":"activities associated with configuration-controlled changes to the system are reviewed;"}]},{"label":"CM-03g.","prose":"","items":[{"label":"CM-03g.[01]","prose":"configuration change control activities are coordinated and overseen by [Assignment: organization-defined configuration change control element];"},{"label":"CM-03g.[02]","prose":"the configuration control element convenes [Selection (one or more): [Assignment: organization-defined frequency]; when [Assignment: organization-defined configuration change conditions]]."}]}],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing system configuration change control","configuration management plan","system architecture and configuration documentation","change control records","system audit records","change control audit and review reports","agenda/minutes/documentation from configuration change control oversight meetings"]},{"method":"Interview","objects":["Organizational personnel with configuration change control responsibilities","organizational personnel with information security and privacy responsibilities","system/network administrators","members of change control board or similar"]},{"method":"Test","objects":["Organizational processes for configuration change control","mechanisms that implement configuration change control"]}]},"CM-3(1)":{"statement":[{"prose":"Use [Assignment: organization-defined automated mechanisms] to:"},{"label":"(a)","prose":"Document proposed changes to the system;"},{"label":"(b)","prose":"Notify [Assignment: organization-defined approval authorities] of proposed changes to the system and request change approval;"},{"label":"(c)","prose":"Highlight proposed changes to the system that have not been approved or disapproved within [Assignment: organization-defined time period];"},{"label":"(d)","prose":"Prohibit changes to the system until designated approvals are received;"},{"label":"(e)","prose":"Document all changes to the system; and"},{"label":"(f)","prose":"Notify [Assignment: organization-defined personnel] when approved changes to the system are completed."}],"discussion":["None."],"params":[{"id":"CM-03(01)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"mechanisms used to automate configuration change control are defined"},{"id":"CM-03(01)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined approval authorities]","guideline":"approval authorities to be notified of and request approval for proposed changes to the system are defined"},{"id":"CM-03(01)_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"the time period after which to highlight changes that have not been approved or disapproved is defined"},{"id":"CM-03(01)_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined personnel]","guideline":"personnel to be notified when approved changes are complete is/are defined"}],"related":[],"references":[],"objectives":[{"label":"CM-03(01)(a)","prose":"[Assignment: organization-defined automated mechanisms] are used to document proposed changes to the system;"},{"label":"CM-03(01)(b)","prose":"[Assignment: organization-defined automated mechanisms] are used to notify [Assignment: organization-defined approval authorities] of proposed changes to the system and request change approval;"},{"label":"CM-03(01)(c)","prose":"[Assignment: organization-defined automated mechanisms] are used to highlight proposed changes to the system that have not been approved or disapproved within [Assignment: organization-defined time period];"},{"label":"CM-03(01)(d)","prose":"[Assignment: organization-defined automated mechanisms] are used to prohibit changes to the system until designated approvals are received;"},{"label":"CM-03(01)(e)","prose":"[Assignment: organization-defined automated mechanisms] are used to document all changes to the system;"},{"label":"CM-03(01)(f)","prose":"[Assignment: organization-defined automated mechanisms] are used to notify [Assignment: organization-defined personnel] when approved changes to the system are completed."}],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing system configuration change control","configuration management plan","system design documentation","system architecture and configuration documentation","automated configuration control mechanisms","system configuration settings and associated documentation","change control records"]},{"method":"Interview","objects":["Organizational personnel with configuration change control responsibilities","organizational personnel with information security responsibilities","system/network administrators","system developers","members of change control board or similar"]},{"method":"Test","objects":["Organizational processes for configuration change control","automated mechanisms implementing configuration change control activities"]}]},"CM-3(2)":{"statement":[{"prose":"Test, validate, and document changes to the system before finalizing the implementation of the changes."}],"discussion":["Changes to systems include modifications to hardware, software, or firmware components and configuration settings defined in [CM-6](#cm-6). Organizations ensure that testing does not interfere with system operations that support organizational mission and business functions. Individuals or groups conducting tests understand security and privacy policies and procedures, system security and privacy policies and procedures, and the health, safety, and environmental risks associated with specific facilities or processes. Operational systems may need to be taken offline, or replicated to the extent feasible, before testing can be conducted. If systems must be taken offline for testing, the tests are scheduled to occur during planned system outages whenever possible. If the testing cannot be conducted on operational systems, organizations employ compensating controls."],"params":[],"related":[],"references":[],"objectives":[{"label":"CM-03(02)[01]","prose":"changes to the system are tested before finalizing the implementation of the changes;"},{"label":"CM-03(02)[02]","prose":"changes to the system are validated before finalizing the implementation of the changes;"},{"label":"CM-03(02)[03]","prose":"changes to the system are documented before finalizing the implementation of the changes."}],"methods":[{"method":"Examine","objects":["Configuration management policy","configuration management plan","procedures addressing system configuration change control","system design documentation","system architecture and configuration documentation","system configuration settings and associated documentation","test records","validation records"]},{"method":"Interview","objects":["Organizational personnel with configuration change control responsibilities","organizational personnel with information security responsibilities","system/network administrators","system developers","members of change control board or similar"]},{"method":"Test","objects":["Organizational processes for configuration change control","mechanisms supporting and/or implementing, testing, validating, and documenting system changes"]}]},"CM-3(4)":{"statement":[{"prose":"Require [Assignment: organization-defined security and privacy representatives] to be members of the [Assignment: organization-defined configuration change control element]."}],"discussion":["Information security and privacy representatives include system security officers, senior agency information security officers, senior agency officials for privacy, or system privacy officers. Representation by personnel with information security and privacy expertise is important because changes to system configurations can have unintended side effects, some of which may be security- or privacy-relevant. Detecting such changes early in the process can help avoid unintended, negative consequences that could ultimately affect the security and privacy posture of systems. The configuration change control element referred to in the second organization-defined parameter reflects the change control elements defined by organizations in [CM-3g](#cm-3_smt.g)."],"params":[{"id":"CM-3.4_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined security and privacy representatives]"},{"id":"CM-03(04)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined security representatives]","guideline":"security representatives required to be members of the change control element are defined"},{"id":"CM-03(04)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined privacy representatives]","guideline":"privacy representatives required to be members of the change control element are defined"},{"id":"CM-03(04)_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined configuration change control element]","guideline":"the configuration change control element of which the security and privacy representatives are to be members is defined"}],"related":[],"references":[],"objectives":[{"label":"CM-03(04)[01]","prose":"[Assignment: organization-defined security representatives] are required to be members of the [Assignment: organization-defined configuration change control element];"},{"label":"CM-03(04)[02]","prose":"[Assignment: organization-defined privacy representatives] are required to be members of the [Assignment: organization-defined configuration change control element]."}],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing system configuration change control","configuration management plan","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with configuration change control responsibilities","organizational personnel with information security and privacy responsibilities","members of change control board or similar"]},{"method":"Test","objects":["Organizational processes for configuration change control"]}]},"CM-3(6)":{"statement":[{"prose":"Ensure that cryptographic mechanisms used to provide the following controls are under configuration management: [Assignment: organization-defined controls]."}],"discussion":["The controls referenced in the control enhancement refer to security and privacy controls from the control catalog. Regardless of the cryptographic mechanisms employed, processes and procedures are in place to manage those mechanisms. For example, if system components use certificates for identification and authentication, a process is implemented to address the expiration of those certificates."],"params":[{"id":"CM-03(06)_ODP","kind":"Assignment","value":"[Assignment: organization-defined controls]","guideline":"controls provided by cryptographic mechanisms that are to be under configuration management are defined"}],"related":["SC-12"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing system configuration change control","configuration management plan","system design documentation","system architecture and configuration documentation","system configuration settings and associated documentation","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with configuration change control responsibilities","organizational personnel with information security responsibilities","system/network administrators","system developers","members of change control board or similar"]},{"method":"Test","objects":["Organizational processes for configuration change control","cryptographic mechanisms implementing organizational security safeguards (controls)"]}]},"CM-4":{"statement":[{"prose":"Analyze changes to the system to determine potential security and privacy impacts prior to change implementation."}],"discussion":["Organizational personnel with security or privacy responsibilities conduct impact analyses. Individuals conducting impact analyses possess the necessary skills and technical expertise to analyze the changes to systems as well as the security or privacy ramifications. Impact analyses include reviewing security and privacy plans, policies, and procedures to understand control requirements; reviewing system design documentation and operational procedures to understand control implementation and how specific system changes might affect the controls; reviewing the impact of changes on organizational supply chain partners with stakeholders; and determining how potential changes to a system create new risks to the privacy of individuals and the ability of implemented controls to mitigate those risks. Impact analyses also include risk assessments to understand the impact of the changes and determine if additional controls are required."],"params":[],"related":["CA-7","CM-3","CM-8","CM-9","MA-2","RA-3","RA-5","RA-8","SA-5","SA-8","SA-10","SI-2"],"references":[{"title":"SP 800-128","url":"https://doi.org/10.6028/NIST.SP.800-128"}],"objectives":[{"label":"CM-04[01]","prose":"changes to the system are analyzed to determine potential security impacts prior to change implementation;"},{"label":"CM-04[02]","prose":"changes to the system are analyzed to determine potential privacy impacts prior to change implementation."}],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing security impact analyses for changes to the system","procedures addressing privacy impact analyses for changes to the system","configuration management plan","security impact analysis documentation","privacy impact analysis documentation","privacy impact assessment","privacy risk assessment documentation, system design documentation"]},{"method":"Interview","objects":["Organizational personnel with responsibility for conducting security impact analyses","organizational personnel with responsibility for conducting privacy impact analyses","organizational personnel with information security and privacy responsibilities","system developer","system/network administrators","members of change control board or similar"]},{"method":"Test","objects":["Organizational processes for security impact analyses","organizational processes for privacy impact analyses"]}]},"CM-4(1)":{"statement":[{"prose":"Analyze changes to the system in a separate test environment before implementation in an operational environment, looking for security and privacy impacts due to flaws, weaknesses, incompatibility, or intentional malice."}],"discussion":["A separate test environment requires an environment that is physically or logically separate and distinct from the operational environment. The separation is sufficient to ensure that activities in the test environment do not impact activities in the operational environment and that information in the operational environment is not inadvertently transmitted to the test environment. Separate environments can be achieved by physical or logical means. If physically separate test environments are not implemented, organizations determine the strength of mechanism required when implementing logical separation."],"params":[],"related":["SA-11","SC-7"],"references":[],"objectives":[{"label":"CM-04(01)[01]","prose":"changes to the system are analyzed in a separate test environment before implementation in an operational environment;"},{"label":"CM-04(01)[02]","prose":"changes to the system are analyzed for security impacts due to flaws;"},{"label":"CM-04(01)[03]","prose":"changes to the system are analyzed for privacy impacts due to flaws;"},{"label":"CM-04(01)[04]","prose":"changes to the system are analyzed for security impacts due to weaknesses;"},{"label":"CM-04(01)[05]","prose":"changes to the system are analyzed for privacy impacts due to weaknesses;"},{"label":"CM-04(01)[06]","prose":"changes to the system are analyzed for security impacts due to incompatibility;"},{"label":"CM-04(01)[07]","prose":"changes to the system are analyzed for privacy impacts due to incompatibility;"},{"label":"CM-04(01)[08]","prose":"changes to the system are analyzed for security impacts due to intentional malice;"},{"label":"CM-04(01)[09]","prose":"changes to the system are analyzed for privacy impacts due to intentional malice."}],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing security impact analyses for changes to the system","procedures addressing privacy impact analyses for changes to the system","configuration management plan","security impact analysis documentation","privacy impact analysis documentation","privacy impact assessment","privacy risk assessment documentation"]},{"method":"Interview","objects":["Organizational personnel with responsibility for conducting security and privacy impact analyses","organizational personnel with information security and privacy responsibilities","system/network administrators","members of change control board or similar"]},{"method":"Test","objects":["Organizational processes for security and privacy impact analyses","mechanisms supporting and/or implementing security and privacy impact analyses of changes"]}]},"CM-4(2)":{"statement":[{"prose":"After system changes, verify that the impacted controls are implemented correctly, operating as intended, and producing the desired outcome with regard to meeting the security and privacy requirements for the system."}],"discussion":["Implementation in this context refers to installing changed code in the operational system that may have an impact on security or privacy controls."],"params":[],"related":["SA-11","SC-3","SI-6"],"references":[],"objectives":[{"label":"CM-04(02)[01]","prose":"the impacted controls are implemented correctly with regard to meeting the security requirements for the system after system changes;"},{"label":"CM-04(02)[02]","prose":"the impacted controls are implemented correctly with regard to meeting the privacy requirements for the system after system changes;"},{"label":"CM-04(02)[03]","prose":"the impacted controls are operating as intended with regard to meeting the security requirements for the system after system changes;"},{"label":"CM-04(02)[04]","prose":"the impacted controls are operating as intended with regard to meeting the privacy requirements for the system after system changes;"},{"label":"CM-04(02)[05]","prose":"the impacted controls are producing the desired outcome with regard to meeting the security requirements for the system after system changes;"},{"label":"CM-04(02)[06]","prose":"the impacted controls are producing the desired outcome with regard to meeting the privacy requirements for the system after system changes."}],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing security impact analyses for changes to the system","procedures addressing privacy impact analyses for changes to the system","privacy risk assessment documentation","configuration management plan","security and privacy impact analysis documentation","privacy impact assessment","analysis tools and associated outputs"]},{"method":"Interview","objects":["Organizational personnel with responsibility for conducting security and privacy impact analyses","organizational personnel with information security and privacy responsibilities","system/network administrators","security and privacy assessors"]},{"method":"Test","objects":["Organizational processes for security and privacy impact analyses","mechanisms supporting and/or implementing security and privacy impact analyses of changes"]}]},"CM-5":{"statement":[{"prose":"Define, document, approve, and enforce physical and logical access restrictions associated with changes to the system."}],"discussion":["Changes to the hardware, software, or firmware components of systems or the operational procedures related to the system can potentially have significant effects on the security of the systems or individuals’ privacy. Therefore, organizations permit only qualified and authorized individuals to access systems for purposes of initiating changes. Access restrictions include physical and logical access controls (see [AC-3](#ac-3) and [PE-3](#pe-3)), software libraries, workflow automation, media libraries, abstract layers (i.e., changes implemented into external interfaces rather than directly into systems), and change windows (i.e., changes occur only during specified times)."],"params":[],"related":["AC-3","AC-5","AC-6","CM-9","PE-3","SC-28","SC-34","SC-37","SI-2","SI-10"],"references":[{"title":"FIPS 140-3","url":"https://doi.org/10.6028/NIST.FIPS.140-3"},{"title":"FIPS 186-4","url":"https://doi.org/10.6028/NIST.FIPS.186-4"}],"objectives":[{"label":"CM-05[01]","prose":"physical access restrictions associated with changes to the system are defined and documented;"},{"label":"CM-05[02]","prose":"physical access restrictions associated with changes to the system are approved;"},{"label":"CM-05[03]","prose":"physical access restrictions associated with changes to the system are enforced;"},{"label":"CM-05[04]","prose":"logical access restrictions associated with changes to the system are defined and documented;"},{"label":"CM-05[05]","prose":"logical access restrictions associated with changes to the system are approved;"},{"label":"CM-05[06]","prose":"logical access restrictions associated with changes to the system are enforced."}],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing access restrictions for changes to the system","configuration management plan","system design documentation","system architecture and configuration documentation","system configuration settings and associated documentation","logical access approvals","physical access approvals"]},{"method":"Interview","objects":["Organizational personnel with logical access control responsibilities","organizational personnel with physical access control responsibilities","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Organizational processes for managing access restrictions to change","mechanisms supporting, implementing, or enforcing access restrictions associated with changes to the system"]}]},"CM-5(1)":{"statement":[{"label":"(a)","prose":"Enforce access restrictions using [Assignment: organization-defined automated mechanisms]; and"},{"label":"(b)","prose":"Automatically generate audit records of the enforcement actions."}],"discussion":["Organizations log system accesses associated with applying configuration changes to ensure that configuration change control is implemented and to support after-the-fact actions should organizations discover any unauthorized changes."],"params":[{"id":"CM-05(01)_ODP","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"mechanisms used to automate the enforcement of access restrictions are defined"}],"related":["AU-2","AU-6","AU-7","AU-12","CM-6","CM-11","SI-12"],"references":[],"objectives":[{"label":"CM-05(01)(a)","prose":"access restrictions for change are enforced using [Assignment: organization-defined automated mechanisms];"},{"label":"CM-05(01)(b)","prose":"audit records of enforcement actions are automatically generated."}],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing access restrictions for changes to the system","system design documentation","system architecture and configuration documentation","system configuration settings and associated documentation","change control records","system audit records","system security plan"]},{"method":"Interview","objects":["Organizational personnel with logical access control responsibilities","organizational personnel with physical access control responsibilities","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Organizational processes for managing access restrictions to change","automated mechanisms implementing the enforcement of access restrictions for changes to the system","automated mechanisms supporting auditing of enforcement actions"]}]},"CM-6":{"statement":[{"label":"a.","prose":"Establish and document configuration settings for components employed within the system that reflect the most restrictive mode consistent with operational requirements using [Assignment: organization-defined common secure configurations];"},{"label":"b.","prose":"Implement the configuration settings;"},{"label":"c.","prose":"Identify, document, and approve any deviations from established configuration settings for [Assignment: organization-defined system components] based on [Assignment: organization-defined operational requirements]; and"},{"label":"d.","prose":"Monitor and control changes to the configuration settings in accordance with organizational policies and procedures."}],"discussion":["Configuration settings are the parameters that can be changed in the hardware, software, or firmware components of the system that affect the security and privacy posture or functionality of the system. Information technology products for which configuration settings can be defined include mainframe computers, servers, workstations, operating systems, mobile devices, input/output devices, protocols, and applications. Parameters that impact the security posture of systems include registry settings; account, file, or directory permission settings; and settings for functions, protocols, ports, services, and remote connections. Privacy parameters are parameters impacting the privacy posture of systems, including the parameters required to satisfy other privacy controls. Privacy parameters include settings for access controls, data processing preferences, and processing and retention permissions. Organizations establish organization-wide configuration settings and subsequently derive specific configuration settings for systems. The established settings become part of the configuration baseline for the system.","Common secure configurations (also known as security configuration checklists, lockdown and hardening guides, and security reference guides) provide recognized, standardized, and established benchmarks that stipulate secure configuration settings for information technology products and platforms as well as instructions for configuring those products or platforms to meet operational requirements. Common secure configurations can be developed by a variety of organizations, including information technology product developers, manufacturers, vendors, federal agencies, consortia, academia, industry, and other organizations in the public and private sectors.","Implementation of a common secure configuration may be mandated at the organization level, mission and business process level, system level, or at a higher level, including by a regulatory agency. Common secure configurations include the United States Government Configuration Baseline [USGCB](#98498928-3ca3-44b3-8b1e-f48685373087) and security technical implementation guides (STIGs), which affect the implementation of [CM-6](#cm-6) and other controls such as [AC-19](#ac-19) and [CM-7](#cm-7). The Security Content Automation Protocol (SCAP) and the defined standards within the protocol provide an effective method to uniquely identify, track, and control configuration settings."],"params":[{"id":"CM-06_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined common secure configurations]","guideline":"common secure configurations to establish and document configuration settings for components employed within the system are defined"},{"id":"CM-06_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined system components]","guideline":"system components for which approval of deviations is needed are defined"},{"id":"CM-06_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined operational requirements]","guideline":"operational requirements necessitating approval of deviations are defined"}],"related":["AC-3","AC-19","AU-2","AU-6","CA-9","CM-2","CM-3","CM-5","CM-7","CM-11","CP-7","CP-9","CP-10","IA-3","IA-5","PL-8","PL-9","RA-5","SA-4","SA-5","SA-8","SA-9","SC-18","SC-28","SC-43","SI-2","SI-4","SI-6"],"references":[{"title":"SP 800-70","url":"https://doi.org/10.6028/NIST.SP.800-70r4"},{"title":"SP 800-126","url":"https://doi.org/10.6028/NIST.SP.800-126r3"},{"title":"SP 800-128","url":"https://doi.org/10.6028/NIST.SP.800-128"},{"title":"USGCB","url":"https://csrc.nist.gov/projects/united-states-government-configuration-baseline"},{"title":"NCPR","url":"https://nvd.nist.gov/ncp/repository"},{"title":"DOD STIG","url":"https://public.cyber.mil/stigs"}],"objectives":[{"label":"CM-06a.","prose":"configuration settings that reflect the most restrictive mode consistent with operational requirements are established and documented for components employed within the system using [Assignment: organization-defined common secure configurations];"},{"label":"CM-06b.","prose":"the configuration settings documented in CM-06a are implemented;"},{"label":"CM-06c.","prose":"","items":[{"label":"CM-06c.[01]","prose":"any deviations from established configuration settings for [Assignment: organization-defined system components] are identified and documented based on [Assignment: organization-defined operational requirements];"},{"label":"CM-06c.[02]","prose":"any deviations from established configuration settings for [Assignment: organization-defined system components] are approved;"}]},{"label":"CM-06d.","prose":"","items":[{"label":"CM-06d.[01]","prose":"changes to the configuration settings are monitored in accordance with organizational policies and procedures;"},{"label":"CM-06d.[02]","prose":"changes to the configuration settings are controlled in accordance with organizational policies and procedures."}]}],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing configuration settings for the system","configuration management plan","system design documentation","system configuration settings and associated documentation","common secure configuration checklists","system component inventory","evidence supporting approved deviations from established configuration settings"]},{"method":"Interview","objects":["Organizational personnel with security configuration management responsibilities","organizational personnel with privacy configuration management responsibilities","organizational personnel with information security and privacy responsibilities","system/network administrators"]},{"method":"Test","objects":["Organizational processes for managing configuration settings","mechanisms that implement, monitor, and/or control system configuration settings","mechanisms that identify and/or document deviations from established configuration settings"]}]},"CM-6(1)":{"statement":[{"prose":"Manage, apply, and verify configuration settings for [Assignment: organization-defined system components] using [Assignment: organization-defined automated mechanisms]."}],"discussion":["Automated tools (e.g., hardening tools, baseline configuration tools) can improve the accuracy, consistency, and availability of configuration settings information. Automation can also provide data aggregation and data correlation capabilities, alerting mechanisms, and dashboards to support risk-based decision-making within the organization."],"params":[{"id":"CM-6.1_PRM_2","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]"},{"id":"CM-06(01)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined system components]","guideline":"system components for which to manage, apply, and verify configuration settings are defined"},{"id":"CM-06(01)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms to manage configuration settings are defined"},{"id":"CM-06(01)_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms to apply configuration settings are defined"},{"id":"CM-06(01)_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms to verify configuration settings are defined"}],"related":["CA-7"],"references":[],"objectives":[{"label":"CM-06(01)[01]","prose":"configuration settings for [Assignment: organization-defined system components] are managed using [Assignment: organization-defined automated mechanisms];"},{"label":"CM-06(01)[02]","prose":"configuration settings for [Assignment: organization-defined system components] are applied using [Assignment: organization-defined automated mechanisms];"},{"label":"CM-06(01)[03]","prose":"configuration settings for [Assignment: organization-defined system components] are verified using [Assignment: organization-defined automated mechanisms]."}],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing configuration settings for the system","configuration management plan","system design documentation","system configuration settings and associated documentation","system component inventory","common secure configuration checklists","change control records"]},{"method":"Interview","objects":["Organizational personnel with security configuration management responsibilities","organizational personnel with information security and privacy responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Organizational processes for managing configuration settings","automated mechanisms implemented to manage, apply, and verify system configuration settings"]}]},"CM-6(2)":{"statement":[{"prose":"Take the following actions in response to unauthorized changes to [Assignment: organization-defined configuration settings]: [Assignment: organization-defined actions]."}],"discussion":["Responses to unauthorized changes to configuration settings include alerting designated organizational personnel, restoring established configuration settings, or—in extreme cases—halting affected system processing."],"params":[{"id":"CM-06(02)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined actions]","guideline":"actions to be taken upon an unauthorized change are defined"},{"id":"CM-06(02)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined configuration settings]","guideline":"configuration settings requiring action upon an unauthorized change are defined"}],"related":["IR-4","IR-6","SI-7"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System security plan","privacy plan","configuration management policy","procedures addressing configuration settings for the system","configuration management plan","system design documentation","system configuration settings and associated documentation","alerts/notifications of unauthorized changes to system configuration settings"]},{"method":"Interview","objects":["Organizational personnel with security configuration management responsibilities","organizational personnel with security and privacy responsibilities","system/network administrators"]},{"method":"Test","objects":["Organizational process for responding to unauthorized changes to system configuration settings","mechanisms supporting and/or implementing actions in response to unauthorized changes"]}]},"CM-7":{"statement":[{"label":"a.","prose":"Configure the system to provide only [Assignment: organization-defined mission-essential capabilities]; and"},{"label":"b.","prose":"Prohibit or restrict the use of the following functions, ports, protocols, software, and/or services: [Assignment: organization-defined prohibited or restricted functions, system ports, protocols, software, and/or services]."}],"discussion":["Systems provide a wide variety of functions and services. Some of the functions and services routinely provided by default may not be necessary to support essential organizational missions, functions, or operations. Additionally, it is sometimes convenient to provide multiple services from a single system component, but doing so increases risk over limiting the services provided by that single component. Where feasible, organizations limit component functionality to a single function per component. Organizations consider removing unused or unnecessary software and disabling unused or unnecessary physical and logical ports and protocols to prevent unauthorized connection of components, transfer of information, and tunneling. Organizations employ network scanning tools, intrusion detection and prevention systems, and end-point protection technologies, such as firewalls and host-based intrusion detection systems, to identify and prevent the use of prohibited functions, protocols, ports, and services. Least functionality can also be achieved as part of the fundamental design and development of the system (see [SA-8](#sa-8), [SC-2](#sc-2), and [SC-3](#sc-3))."],"params":[{"id":"CM-7_PRM_2","kind":"Assignment","value":"[Assignment: organization-defined prohibited or restricted functions, system ports, protocols, software, and/or services]"},{"id":"CM-07_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined mission-essential capabilities]","guideline":"mission-essential capabilities for the system are defined"},{"id":"CM-07_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined functions]","guideline":"functions to be prohibited or restricted are defined"},{"id":"CM-07_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined ports]","guideline":"ports to be prohibited or restricted are defined"},{"id":"CM-07_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined protocols]","guideline":"protocols to be prohibited or restricted are defined"},{"id":"CM-07_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined software]","guideline":"software to be prohibited or restricted is defined"},{"id":"CM-07_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined services]","guideline":"services to be prohibited or restricted are defined"}],"related":["AC-3","AC-4","CM-2","CM-5","CM-6","CM-11","RA-5","SA-4","SA-5","SA-8","SA-9","SA-15","SC-2","SC-3","SC-7","SC-37","SI-4"],"references":[{"title":"FIPS 140-3","url":"https://doi.org/10.6028/NIST.FIPS.140-3"},{"title":"FIPS 180-4","url":"https://doi.org/10.6028/NIST.FIPS.180-4"},{"title":"FIPS 186-4","url":"https://doi.org/10.6028/NIST.FIPS.186-4"},{"title":"FIPS 202","url":"https://doi.org/10.6028/NIST.FIPS.202"},{"title":"SP 800-167","url":"https://doi.org/10.6028/NIST.SP.800-167"}],"objectives":[{"label":"CM-07a.","prose":"the system is configured to provide only [Assignment: organization-defined mission-essential capabilities];"},{"label":"CM-07b.","prose":"","items":[{"label":"CM-07b.[01]","prose":"the use of [Assignment: organization-defined functions] is prohibited or restricted;"},{"label":"CM-07b.[02]","prose":"the use of [Assignment: organization-defined ports] is prohibited or restricted;"},{"label":"CM-07b.[03]","prose":"the use of [Assignment: organization-defined protocols] is prohibited or restricted;"},{"label":"CM-07b.[04]","prose":"the use of [Assignment: organization-defined software] is prohibited or restricted;"},{"label":"CM-07b.[05]","prose":"the use of [Assignment: organization-defined services] is prohibited or restricted."}]}],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing least functionality in the system","configuration management plan","system design documentation","system configuration settings and associated documentation","system component inventory","common secure configuration checklists","system security plan"]},{"method":"Interview","objects":["Organizational personnel with security configuration management responsibilities","organizational personnel with information security responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Organizational processes prohibiting or restricting functions, ports, protocols, software, and/or services","mechanisms implementing restrictions or prohibition of functions, ports, protocols, software, and/or services"]}]},"CM-7(1)":{"statement":[{"label":"(a)","prose":"Review the system [Assignment: organization-defined frequency] to identify unnecessary and/or nonsecure functions, ports, protocols, software, and services; and"},{"label":"(b)","prose":"Disable or remove [Assignment: organization-defined functions, ports, protocols, software, and services within the system deemed to be unnecessary and/or nonsecure]."}],"discussion":["Organizations review functions, ports, protocols, and services provided by systems or system components to determine the functions and services that are candidates for elimination. Such reviews are especially important during transition periods from older technologies to newer technologies (e.g., transition from IPv4 to IPv6). These technology transitions may require implementing the older and newer technologies simultaneously during the transition period and returning to minimum essential functions, ports, protocols, and services at the earliest opportunity. Organizations can either decide the relative security of the function, port, protocol, and/or service or base the security decision on the assessment of other entities. Unsecure protocols include Bluetooth, FTP, and peer-to-peer networking."],"params":[{"id":"CM-7.1_PRM_2","kind":"Assignment","value":"[Assignment: organization-defined functions, ports, protocols, software, and services within the system deemed to be unnecessary and/or nonsecure]"},{"id":"CM-07(01)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to review the system to identify unnecessary and/or non-secure functions, ports, protocols, software, and/or services is defined"},{"id":"CM-07(01)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined functions]","guideline":"functions to be disabled or removed when deemed unnecessary or non-secure are defined"},{"id":"CM-07(01)_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined ports]","guideline":"ports to be disabled or removed when deemed unnecessary or non-secure are defined"},{"id":"CM-07(01)_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined protocols]","guideline":"protocols to be disabled or removed when deemed unnecessary or non-secure are defined"},{"id":"CM-07(01)_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined software]","guideline":"software to be disabled or removed when deemed unnecessary or non-secure is defined"},{"id":"CM-07(01)_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined services]","guideline":"services to be disabled or removed when deemed unnecessary or non-secure are defined"}],"related":["AC-18"],"references":[],"objectives":[{"label":"CM-07(01)(a)","prose":"the system is reviewed [Assignment: organization-defined frequency] to identify unnecessary and/or non-secure functions, ports, protocols, software, and services:"},{"label":"CM-07(01)(b)","prose":"","items":[{"label":"CM-07(01)(b)[01]","prose":"[Assignment: organization-defined functions] deemed to be unnecessary and/or non-secure are disabled or removed;"},{"label":"CM-07(01)(b)[02]","prose":"[Assignment: organization-defined ports] deemed to be unnecessary and/or non-secure are disabled or removed;"},{"label":"CM-07(01)(b)[03]","prose":"[Assignment: organization-defined protocols] deemed to be unnecessary and/or non-secure are disabled or removed;"},{"label":"CM-07(01)(b)[04]","prose":"[Assignment: organization-defined software] deemed to be unnecessary and/or non-secure is disabled or removed;"},{"label":"CM-07(01)(b)[05]","prose":"[Assignment: organization-defined services] deemed to be unnecessary and/or non-secure are disabled or removed."}]}],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing least functionality in the system","configuration management plan","system design documentation","system configuration settings and associated documentation","common secure configuration checklists","documented reviews of functions, ports, protocols, and/or services","change control records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for reviewing functions, ports, protocols, and services on the system","organizational personnel with information security responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Organizational processes for reviewing or disabling functions, ports, protocols, and services on the system","mechanisms implementing review and disabling of functions, ports, protocols, and/or services"]}]},"CM-7(2)":{"statement":[{"prose":"Prevent program execution in accordance with [Selection (one or more): [Assignment: organization-defined policies, rules of behavior, and/or access agreements regarding software program usage and restrictions]; rules authorizing the terms and conditions of software program usage]."}],"discussion":["Prevention of program execution addresses organizational policies, rules of behavior, and/or access agreements that restrict software usage and the terms and conditions imposed by the developer or manufacturer, including software licensing and copyrights. Restrictions include prohibiting auto-execute features, restricting roles allowed to approve program execution, permitting or prohibiting specific software programs, or restricting the number of program instances executed at the same time."],"params":[{"id":"CM-07(02)_ODP[01]","kind":"Selection","value":"[Selection (one or more): [Assignment: organization-defined policies, rules of behavior, and/or access agreements regarding software program usage and restrictions]; rules authorizing the terms and conditions of software program usage]"},{"id":"CM-07(02)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined policies, rules of behavior, and/or access agreements regarding software program usage and restrictions]","guideline":"policies, rules of behavior, and/or access agreements regarding software program usage and restrictions are defined (if selected)"}],"related":["CM-8","PL-4","PL-9","PM-5","PS-6"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing least functionality in the system","configuration management plan","system design documentation","system configuration settings and associated documentation","system component inventory","common secure configuration checklists","specifications for preventing software program execution"]},{"method":"Interview","objects":["Organizational personnel with information security responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Organizational processes preventing program execution on the system","organizational processes for software program usage and restrictions","mechanisms preventing program execution on the system","mechanisms supporting and/or implementing software program usage and restrictions"]}]},"CM-7(5)":{"statement":[{"label":"(a)","prose":"Identify [Assignment: organization-defined software programs];"},{"label":"(b)","prose":"Employ a deny-all, permit-by-exception policy to allow the execution of authorized software programs on the system; and"},{"label":"(c)","prose":"Review and update the list of authorized software programs [Assignment: organization-defined frequency]."}],"discussion":["Authorized software programs can be limited to specific versions or from a specific source. To facilitate a comprehensive authorized software process and increase the strength of protection for attacks that bypass application level authorized software, software programs may be decomposed into and monitored at different levels of detail. These levels include applications, application programming interfaces, application modules, scripts, system processes, system services, kernel functions, registries, drivers, and dynamic link libraries. The concept of permitting the execution of authorized software may also be applied to user actions, system ports and protocols, IP addresses/ranges, websites, and MAC addresses. Organizations consider verifying the integrity of authorized software programs using digital signatures, cryptographic checksums, or hash functions. Verification of authorized software can occur either prior to execution or at system startup. The identification of authorized URLs for websites is addressed in [CA-3(5)](#ca-3.5) and [SC-7](#sc-7)."],"params":[{"id":"CM-07(05)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined software programs]","guideline":"software programs authorized to execute on the system are defined"},{"id":"CM-07(05)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to review and update the list of authorized software programs is defined"}],"related":["CM-2","CM-6","CM-8","CM-10","PL-9","PM-5","SA-10","SC-34","SI-7"],"references":[],"objectives":[{"label":"CM-07(05)(a)","prose":"[Assignment: organization-defined software programs] are identified;"},{"label":"CM-07(05)(b)","prose":"a deny-all, permit-by-exception policy to allow the execution of authorized software programs on the system is employed;"},{"label":"CM-07(05)(c)","prose":"the list of authorized software programs is reviewed and updated [Assignment: organization-defined frequency]."}],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing least functionality in the system","configuration management plan","system design documentation","system configuration settings and associated documentation","list of software programs authorized to execute on the system","system component inventory","common secure configuration checklists"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for identifying software authorized to execute on the system","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Organizational process for identifying, reviewing, and updating programs authorized to execute on the system","organizational process for implementing authorized software policy","mechanisms supporting and/or implementing authorized software policy"]}]},"CM-8":{"statement":[{"label":"a.","prose":"Develop and document an inventory of system components that:","items":[{"label":"1.","prose":"Accurately reflects the system;"},{"label":"2.","prose":"Includes all components within the system;"},{"label":"3.","prose":"Does not include duplicate accounting of components or components assigned to any other system;"},{"label":"4.","prose":"Is at the level of granularity deemed necessary for tracking and reporting; and"},{"label":"5.","prose":"Includes the following information to achieve system component accountability: [Assignment: organization-defined information]; and"}]},{"label":"b.","prose":"Review and update the system component inventory [Assignment: organization-defined frequency]."}],"discussion":["System components are discrete, identifiable information technology assets that include hardware, software, and firmware. Organizations may choose to implement centralized system component inventories that include components from all organizational systems. In such situations, organizations ensure that the inventories include system-specific information required for component accountability. The information necessary for effective accountability of system components includes the system name, software owners, software version numbers, hardware inventory specifications, software license information, and for networked components, the machine names and network addresses across all implemented protocols (e.g., IPv4, IPv6). Inventory specifications include date of receipt, cost, model, serial number, manufacturer, supplier information, component type, and physical location.","Preventing duplicate accounting of system components addresses the lack of accountability that occurs when component ownership and system association is not known, especially in large or complex connected systems. Effective prevention of duplicate accounting of system components necessitates use of a unique identifier for each component. For software inventory, centrally managed software that is accessed via other systems is addressed as a component of the system on which it is installed and managed. Software installed on multiple organizational systems and managed at the system level is addressed for each individual system and may appear more than once in a centralized component inventory, necessitating a system association for each software instance in the centralized inventory to avoid duplicate accounting of components. Scanning systems implementing multiple network protocols (e.g., IPv4 and IPv6) can result in duplicate components being identified in different address spaces. The implementation of [CM-8(7)](#cm-8.7) can help to eliminate duplicate accounting of components."],"params":[{"id":"CM-08_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined information]","guideline":"information deemed necessary to achieve effective system component accountability is defined"},{"id":"CM-08_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to review and update the system component inventory is defined"}],"related":["CM-2","CM-7","CM-9","CM-10","CM-11","CM-13","CP-2","CP-9","MA-2","MA-6","PE-20","PL-9","PM-5","SA-4","SA-5","SI-2","SR-4"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-57-1","url":"https://doi.org/10.6028/NIST.SP.800-57pt1r5"},{"title":"SP 800-57-2","url":"https://doi.org/10.6028/NIST.SP.800-57pt2r1"},{"title":"SP 800-57-3","url":"https://doi.org/10.6028/NIST.SP.800-57pt3r1"},{"title":"SP 800-128","url":"https://doi.org/10.6028/NIST.SP.800-128"},{"title":"IR 8011-2","url":"https://doi.org/10.6028/NIST.IR.8011-2"},{"title":"IR 8011-3","url":"https://doi.org/10.6028/NIST.IR.8011-3"}],"objectives":[{"label":"CM-08a.","prose":"","items":[{"label":"CM-08a.01","prose":"an inventory of system components that accurately reflects the system is developed and documented;"},{"label":"CM-08a.02","prose":"an inventory of system components that includes all components within the system is developed and documented;"},{"label":"CM-08a.03","prose":"an inventory of system components that does not include duplicate accounting of components or components assigned to any other system is developed and documented;"},{"label":"CM-08a.04","prose":"an inventory of system components that is at the level of granularity deemed necessary for tracking and reporting is developed and documented;"},{"label":"CM-08a.05","prose":"an inventory of system components that includes [Assignment: organization-defined information] is developed and documented;"}]},{"label":"CM-08b.","prose":"the system component inventory is reviewed and updated [Assignment: organization-defined frequency]."}],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing system component inventory","configuration management plan","system security plan","system design documentation","system component inventory","inventory reviews and update records","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with component inventory management responsibilities","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Organizational processes for managing the system component inventory","mechanisms supporting and/or implementing system component inventory"]}]},"CM-8(1)":{"statement":[{"prose":"Update the inventory of system components as part of component installations, removals, and system updates."}],"discussion":["Organizations can improve the accuracy, completeness, and consistency of system component inventories if the inventories are updated as part of component installations or removals or during general system updates. If inventories are not updated at these key times, there is a greater likelihood that the information will not be appropriately captured and documented. System updates include hardware, software, and firmware components."],"params":[],"related":["PM-16"],"references":[],"objectives":[{"label":"CM-08(01)[01]","prose":"the inventory of system components is updated as part of component installations;"},{"label":"CM-08(01)[02]","prose":"the inventory of system components is updated as part of component removals;"},{"label":"CM-08(01)[03]","prose":"the inventory of system components is updated as part of system updates."}],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing system component inventory","configuration management plan","system security plan","system component inventory","inventory reviews and update records","change control records","component installation records"]},{"method":"Interview","objects":["Organizational personnel with component inventory updating responsibilities","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Organizational processes for updating the system component inventory","mechanisms supporting and/or implementing system component inventory updates"]}]},"CM-8(2)":{"statement":[{"prose":"Maintain the currency, completeness, accuracy, and availability of the inventory of system components using [Assignment: organization-defined automated mechanisms]."}],"discussion":["Organizations maintain system inventories to the extent feasible. For example, virtual machines can be difficult to monitor because such machines are not visible to the network when not in use. In such cases, organizations maintain as up-to-date, complete, and accurate an inventory as is deemed reasonable. Automated maintenance can be achieved by the implementation of [CM-2(2)](#cm-2.2) for organizations that combine system component inventory and baseline configuration activities."],"params":[{"id":"CM-8.2_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]"},{"id":"CM-08(02)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms used to maintain the currency of the system component inventory are defined"},{"id":"CM-08(02)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms used to maintain the completeness of the system component inventory are defined"},{"id":"CM-08(02)_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms used to maintain the accuracy of the system component inventory are defined"},{"id":"CM-08(02)_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms used to maintain the availability of the system component inventory are defined"}],"related":[],"references":[],"objectives":[{"label":"CM-08(02)[01]","prose":"[Assignment: organization-defined automated mechanisms] are used to maintain the currency of the system component inventory;"},{"label":"CM-08(02)[02]","prose":"[Assignment: organization-defined automated mechanisms] are used to maintain the completeness of the system component inventory;"},{"label":"CM-08(02)[03]","prose":"[Assignment: organization-defined automated mechanisms] are used to maintain the accuracy of the system component inventory;"},{"label":"CM-08(02)[04]","prose":"[Assignment: organization-defined automated mechanisms] are used to maintain the availability of the system component inventory."}],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing system component inventory","configuration management plan","system design documentation","system security plan","system component inventory","change control records","system maintenance records"]},{"method":"Interview","objects":["Organizational personnel with component inventory management responsibilities","organizational personnel with information security responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Organizational processes for maintaining the system component inventory","automated mechanisms supporting and/or implementing the system component inventory"]}]},"CM-8(3)":{"statement":[{"label":"(a)","prose":"Detect the presence of unauthorized hardware, software, and firmware components within the system using [Assignment: organization-defined automated mechanisms] [Assignment: organization-defined frequency]; and"},{"label":"(b)","prose":"Take the following actions when unauthorized components are detected: [Selection (one or more): disable network access by unauthorized components; isolate unauthorized components; notify [Assignment: organization-defined personnel or roles]]."}],"discussion":["Automated unauthorized component detection is applied in addition to the monitoring for unauthorized remote connections and mobile devices. Monitoring for unauthorized system components may be accomplished on an ongoing basis or by the periodic scanning of systems for that purpose. Automated mechanisms may also be used to prevent the connection of unauthorized components (see [CM-7(9)](#cm-7.9)). Automated mechanisms can be implemented in systems or in separate system components. When acquiring and implementing automated mechanisms, organizations consider whether such mechanisms depend on the ability of the system component to support an agent or supplicant in order to be detected since some types of components do not have or cannot support agents (e.g., IoT devices, sensors). Isolation can be achieved, for example, by placing unauthorized system components in separate domains or subnets or quarantining such components. This type of component isolation is commonly referred to as \"sandboxing.\""],"params":[{"id":"CM-8.3_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]"},{"id":"CM-08(03)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms used to detect the presence of unauthorized hardware within the system are defined"},{"id":"CM-08(03)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms used to detect the presence of unauthorized software within the system are defined"},{"id":"CM-08(03)_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms used to detect the presence of unauthorized firmware within the system are defined"},{"id":"CM-08(03)_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which automated mechanisms are used to detect the presence of unauthorized system components within the system is defined"},{"id":"CM-08(03)_ODP[05]","kind":"Selection","value":"[Selection (one or more): disable network access by unauthorized components; isolate unauthorized components; notify [Assignment: organization-defined personnel or roles]]"},{"id":"CM-08(03)_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to be notified when unauthorized components are detected is/are defined (if selected)"}],"related":["AC-19","CA-7","RA-5","SC-3","SC-39","SC-44","SI-3","SI-4","SI-7"],"references":[],"objectives":[{"label":"CM-08(03)(a)","prose":"","items":[{"label":"CM-08(03)(a)[01]","prose":"the presence of unauthorized hardware within the system is detected using [Assignment: organization-defined automated mechanisms] [Assignment: organization-defined frequency];"},{"label":"CM-08(03)(a)[02]","prose":"the presence of unauthorized software within the system is detected using [Assignment: organization-defined automated mechanisms] [Assignment: organization-defined frequency];"},{"label":"CM-08(03)(a)[03]","prose":"the presence of unauthorized firmware within the system is detected using [Assignment: organization-defined automated mechanisms] [Assignment: organization-defined frequency];"}]},{"label":"CM-08(03)(b)","prose":"","items":[{"label":"CM-08(03)(b)[01]","prose":"[Selection (one or more): disable network access by unauthorized components; isolate unauthorized components; notify [Assignment: organization-defined personnel or roles]] are taken when unauthorized hardware is detected;"},{"label":"CM-08(03)(b)[02]","prose":"[Selection (one or more): disable network access by unauthorized components; isolate unauthorized components; notify [Assignment: organization-defined personnel or roles]] are taken when unauthorized software is detected;"},{"label":"CM-08(03)(b)[03]","prose":"[Selection (one or more): disable network access by unauthorized components; isolate unauthorized components; notify [Assignment: organization-defined personnel or roles]] are taken when unauthorized firmware is detected."}]}],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing system component inventory","configuration management plan","system design documentation","system security plan","system component inventory","change control records","alerts/notifications of unauthorized components within the system"]},{"method":"Interview","objects":["Organizational personnel with component inventory management responsibilities","organizational personnel with responsibilities for managing the automated mechanisms implementing unauthorized system component detection","organizational personnel with information security responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Organizational processes for detection of unauthorized system components","organizational processes for taking action when unauthorized system components are detected","automated mechanisms supporting and/or implementing the detection of unauthorized system components","automated mechanisms supporting and/or implementing actions taken when unauthorized system components are detected"]}]},"CM-8(4)":{"statement":[{"prose":"Include in the system component inventory information, a means for identifying by [Selection (one or more): name; position; role], individuals responsible and accountable for administering those components."}],"discussion":["Identifying individuals who are responsible and accountable for administering system components ensures that the assigned components are properly administered and that organizations can contact those individuals if some action is required (e.g., when the component is determined to be the source of a breach, needs to be recalled or replaced, or needs to be relocated)."],"params":[{"id":"CM-08(04)_ODP","kind":"Selection","value":"[Selection (one or more): name; position; role]"}],"related":["AC-3"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing system component inventory","configuration management plan","system security plan","system component inventory","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with component inventory management responsibilities","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Organizational processes for managing the system component inventory","mechanisms supporting and/or implementing the system component inventory"]}]},"CM-9":{"statement":[{"prose":"Develop, document, and implement a configuration management plan for the system that:"},{"label":"a.","prose":"Addresses roles, responsibilities, and configuration management processes and procedures;"},{"label":"b.","prose":"Establishes a process for identifying configuration items throughout the system development life cycle and for managing the configuration of the configuration items;"},{"label":"c.","prose":"Defines the configuration items for the system and places the configuration items under configuration management;"},{"label":"d.","prose":"Is reviewed and approved by [Assignment: organization-defined personnel or roles]; and"},{"label":"e.","prose":"Protects the configuration management plan from unauthorized disclosure and modification."}],"discussion":["Configuration management activities occur throughout the system development life cycle. As such, there are developmental configuration management activities (e.g., the control of code and software libraries) and operational configuration management activities (e.g., control of installed components and how the components are configured). Configuration management plans satisfy the requirements in configuration management policies while being tailored to individual systems. Configuration management plans define processes and procedures for how configuration management is used to support system development life cycle activities.","Configuration management plans are generated during the development and acquisition stage of the system development life cycle. The plans describe how to advance changes through change management processes; update configuration settings and baselines; maintain component inventories; control development, test, and operational environments; and develop, release, and update key documents.","Organizations can employ templates to help ensure the consistent and timely development and implementation of configuration management plans. Templates can represent a configuration management plan for the organization with subsets of the plan implemented on a system by system basis. Configuration management approval processes include the designation of key stakeholders responsible for reviewing and approving proposed changes to systems, and personnel who conduct security and privacy impact analyses prior to the implementation of changes to the systems. Configuration items are the system components, such as the hardware, software, firmware, and documentation to be configuration-managed. As systems continue through the system development life cycle, new configuration items may be identified, and some existing configuration items may no longer need to be under configuration control."],"params":[{"id":"CM-09_ODP","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to review and approve the configuration management plan is/are defined"}],"related":["CM-2","CM-3","CM-4","CM-5","CM-8","PL-2","RA-8","SA-10","SI-12"],"references":[{"title":"SP 800-128","url":"https://doi.org/10.6028/NIST.SP.800-128"}],"objectives":[{"label":"CM-09[01]","prose":"a configuration management plan for the system is developed and documented;"},{"label":"CM-09[02]","prose":"a configuration management plan for the system is implemented;"},{"label":"CM-09a.","prose":"","items":[{"label":"CM-09a.[01]","prose":"the configuration management plan addresses roles;"},{"label":"CM-09a.[02]","prose":"the configuration management plan addresses responsibilities;"},{"label":"CM-09a.[03]","prose":"the configuration management plan addresses configuration management processes and procedures;"}]},{"label":"CM-09b.","prose":"","items":[{"label":"CM-09b.[01]","prose":"the configuration management plan establishes a process for identifying configuration items throughout the system development life cycle;"},{"label":"CM-09b.[02]","prose":"the configuration management plan establishes a process for managing the configuration of the configuration items;"}]},{"label":"CM-09c.","prose":"","items":[{"label":"CM-09c.[01]","prose":"the configuration management plan defines the configuration items for the system;"},{"label":"CM-09c.[02]","prose":"the configuration management plan places the configuration items under configuration management;"}]},{"label":"CM-09d.","prose":"the configuration management plan is reviewed and approved by [Assignment: organization-defined personnel or roles];"},{"label":"CM-09e.","prose":"","items":[{"label":"CM-09e.[01]","prose":"the configuration management plan is protected from unauthorized disclosure;"},{"label":"CM-09e.[02]","prose":"the configuration management plan is protected from unauthorized modification."}]}],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing configuration management planning","configuration management plan","system design documentation","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for developing the configuration management plan","organizational personnel with responsibilities for implementing and managing processes defined in the configuration management plan","organizational personnel with responsibilities for protecting the configuration management plan","organizational personnel with information security and privacy responsibilities","system/network administrators"]},{"method":"Test","objects":["Organizational processes for developing and documenting the configuration management plan","organizational processes for identifying and managing configuration items","organizational processes for protecting the configuration management plan","mechanisms implementing the configuration management plan","mechanisms for managing configuration items","mechanisms for protecting the configuration management plan"]}]},"CM-10":{"statement":[{"label":"a.","prose":"Use software and associated documentation in accordance with contract agreements and copyright laws;"},{"label":"b.","prose":"Track the use of software and associated documentation protected by quantity licenses to control copying and distribution; and"},{"label":"c.","prose":"Control and document the use of peer-to-peer file sharing technology to ensure that this capability is not used for the unauthorized distribution, display, performance, or reproduction of copyrighted work."}],"discussion":["Software license tracking can be accomplished by manual or automated methods, depending on organizational needs. Examples of contract agreements include software license agreements and non-disclosure agreements."],"params":[],"related":["AC-17","AU-6","CM-7","CM-8","PM-30","SC-7"],"references":[],"objectives":[{"label":"CM-10a.","prose":"software and associated documentation are used in accordance with contract agreements and copyright laws;"},{"label":"CM-10b.","prose":"the use of software and associated documentation protected by quantity licenses is tracked to control copying and distribution;"},{"label":"CM-10c.","prose":"the use of peer-to-peer file sharing technology is controlled and documented to ensure that peer-to-peer file sharing is not used for the unauthorized distribution, display, performance, or reproduction of copyrighted work."}],"methods":[{"method":"Examine","objects":["Configuration management policy","software usage restrictions","software contract agreements and copyright laws","site license documentation","list of software usage restrictions","software license tracking reports","configuration management plan","system security plan"]},{"method":"Interview","objects":["Organizational personnel operating, using, and/or maintaining the system","organizational personnel with software license management responsibilities","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Organizational processes for tracking the use of software protected by quantity licenses","organizational processes for controlling/documenting the use of peer-to-peer file sharing technology","mechanisms implementing software license tracking","mechanisms implementing and controlling the use of peer-to-peer files sharing technology"]}]},"CM-11":{"statement":[{"label":"a.","prose":"Establish [Assignment: organization-defined policies] governing the installation of software by users;"},{"label":"b.","prose":"Enforce software installation policies through the following methods: [Assignment: organization-defined methods]; and"},{"label":"c.","prose":"Monitor policy compliance [Assignment: organization-defined frequency]."}],"discussion":["If provided the necessary privileges, users can install software in organizational systems. To maintain control over the software installed, organizations identify permitted and prohibited actions regarding software installation. Permitted software installations include updates and security patches to existing software and downloading new applications from organization-approved \"app stores.\" Prohibited software installations include software with unknown or suspect pedigrees or software that organizations consider potentially malicious. Policies selected for governing user-installed software are organization-developed or provided by some external entity. Policy enforcement methods can include procedural methods and automated methods."],"params":[{"id":"CM-11_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined policies]","guideline":"policies governing the installation of software by users are defined"},{"id":"CM-11_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined methods]","guideline":"methods used to enforce software installation policies are defined"},{"id":"CM-11_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency with which to monitor compliance is defined"}],"related":["AC-3","AU-6","CM-2","CM-3","CM-5","CM-6","CM-7","CM-8","PL-4","SI-4","SI-7"],"references":[],"objectives":[{"label":"CM-11a.","prose":"[Assignment: organization-defined policies] governing the installation of software by users are established;"},{"label":"CM-11b.","prose":"software installation policies are enforced through [Assignment: organization-defined methods];"},{"label":"CM-11c.","prose":"compliance with [Assignment: organization-defined policies] is monitored [Assignment: organization-defined frequency]."}],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing user-installed software","configuration management plan","system security plan","system design documentation","system configuration settings and associated documentation","list of rules governing user installed software","system monitoring records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for governing user-installed software","organizational personnel operating, using, and/or maintaining the system","organizational personnel monitoring compliance with user-installed software policy","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Organizational processes governing user-installed software on the system","mechanisms enforcing policies and methods for governing the installation of software by users","mechanisms monitoring policy compliance"]}]},"CM-12":{"statement":[{"label":"a.","prose":"Identify and document the location of [Assignment: organization-defined information] and the specific system components on which the information is processed and stored;"},{"label":"b.","prose":"Identify and document the users who have access to the system and system components where the information is processed and stored; and"},{"label":"c.","prose":"Document changes to the location (i.e., system or system components) where the information is processed and stored."}],"discussion":["Information location addresses the need to understand where information is being processed and stored. Information location includes identifying where specific information types and information reside in system components and how information is being processed so that information flow can be understood and adequate protection and policy management provided for such information and system components. The security category of the information is also a factor in determining the controls necessary to protect the information and the system component where the information resides (see [FIPS 199](#628d22a1-6a11-4784-bc59-5cd9497b5445)). The location of the information and system components is also a factor in the architecture and design of the system (see [SA-4](#sa-4), [SA-8](#sa-8), [SA-17](#sa-17))."],"params":[{"id":"CM-12_ODP","kind":"Assignment","value":"[Assignment: organization-defined information]","guideline":"information for which the location is to be identified and documented is defined"}],"related":["AC-2","AC-3","AC-4","AC-6","AC-23","CM-8","PM-5","RA-2","SA-4","SA-8","SA-17","SC-4","SC-16","SC-28","SI-4","SI-7"],"references":[{"title":"FIPS 199","url":"https://doi.org/10.6028/NIST.FIPS.199"},{"title":"SP 800-60-1","url":"https://doi.org/10.6028/NIST.SP.800-60v1r1"},{"title":"SP 800-60-2","url":"https://doi.org/10.6028/NIST.SP.800-60v2r1"}],"objectives":[{"label":"CM-12a.","prose":"","items":[{"label":"CM-12a.[01]","prose":"the location of [Assignment: organization-defined information] is identified and documented;"},{"label":"CM-12a.[02]","prose":"the specific system components on which [Assignment: organization-defined information] is processed are identified and documented;"},{"label":"CM-12a.[03]","prose":"the specific system components on which [Assignment: organization-defined information] is stored are identified and documented;"}]},{"label":"CM-12b.","prose":"","items":[{"label":"CM-12b.[01]","prose":"the users who have access to the system and system components where [Assignment: organization-defined information] is processed are identified and documented;"},{"label":"CM-12b.[02]","prose":"the users who have access to the system and system components where [Assignment: organization-defined information] is stored are identified and documented;"}]},{"label":"CM-12c.","prose":"","items":[{"label":"CM-12c.[01]","prose":"changes to the location (i.e., system or system components) where [Assignment: organization-defined information] is processed are documented;"},{"label":"CM-12c.[02]","prose":"changes to the location (i.e., system or system components) where [Assignment: organization-defined information] is stored are documented."}]}],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing identification and documentation of information location","configuration management plan","system design documentation","system architecture documentation","PII inventory documentation","data mapping documentation","audit records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for managing information location and user access to information","organizational personnel with responsibilities for operating, using, and/or maintaining the system","organizational personnel with information security and privacy responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Organizational processes governing information location","mechanisms enforcing policies and methods for governing information location"]}]},"CM-12(1)":{"statement":[{"prose":"Use automated tools to identify [Assignment: organization-defined information by information type] on [Assignment: organization-defined system components] to ensure controls are in place to protect organizational information and individual privacy."}],"discussion":["The use of automated tools helps to increase the effectiveness and efficiency of the information location capability implemented within the system. Automation also helps organizations manage the data produced during information location activities and share such information across the organization. The output of automated information location tools can be used to guide and inform system architecture and design decisions."],"params":[{"id":"CM-12(01)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined information by information type]","guideline":"information to be protected is defined by information type"},{"id":"CM-12(01)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined system components]","guideline":"system components where the information is located are defined"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Configuration management policy","procedures addressing identification and documentation of information location","configuration management plan","system design documentation","PII inventory documentation","data mapping documentation","change control records","system component inventory"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for managing information location","organizational personnel with information security responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Organizational processes governing information location","automated mechanisms enforcing policies and methods for governing information location","automated tools used to identify information on system components"]}]},"CP-1":{"statement":[{"label":"a.","prose":"Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:","items":[{"label":"1.","prose":"[Selection (one or more): organization-level; mission/business process-level; system-level] contingency planning policy that:","items":[{"label":"(a)","prose":"Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and"},{"label":"(b)","prose":"Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and"}]},{"label":"2.","prose":"Procedures to facilitate the implementation of the contingency planning policy and the associated contingency planning controls;"}]},{"label":"b.","prose":"Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the contingency planning policy and procedures; and"},{"label":"c.","prose":"Review and update the current contingency planning:","items":[{"label":"1.","prose":"Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and"},{"label":"2.","prose":"Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]."}]}],"discussion":["Contingency planning policy and procedures address the controls in the CP family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of contingency planning policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to contingency planning policy and procedures include assessment or audit findings, security incidents or breaches, or changes in laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure."],"params":[{"id":"CP-1_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]"},{"id":"CP-01_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the contingency planning policy is to be disseminated is/are defined"},{"id":"CP-01_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the contingency planning procedures are to be disseminated is/are defined"},{"id":"CP-01_ODP[03]","kind":"Selection","value":"[Selection (one or more): organization-level; mission/business process-level; system-level]"},{"id":"CP-01_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined official]","guideline":"an official to manage the contingency planning policy and procedures is defined"},{"id":"CP-01_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current contingency planning policy is reviewed and updated is defined"},{"id":"CP-01_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require the current contingency planning policy to be reviewed and updated are defined"},{"id":"CP-01_ODP[07]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current contingency planning procedures are reviewed and updated is defined"},{"id":"CP-01_ODP[08]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require procedures to be reviewed and updated are defined"}],"related":["PM-9","PS-8","SI-12"],"references":[{"title":"SP 800-12","url":"https://doi.org/10.6028/NIST.SP.800-12r1"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-34","url":"https://doi.org/10.6028/NIST.SP.800-34r1"},{"title":"SP 800-39","url":"https://doi.org/10.6028/NIST.SP.800-39"},{"title":"SP 800-50","url":"https://doi.org/10.6028/NIST.SP.800-50"},{"title":"SP 800-100","url":"https://doi.org/10.6028/NIST.SP.800-100"}],"objectives":[{"label":"CP-01a.","prose":"","items":[{"label":"CP-01a.[01]","prose":"a contingency planning policy is developed and documented;"},{"label":"CP-01a.[02]","prose":"the contingency planning policy is disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"CP-01a.[03]","prose":"contingency planning procedures to facilitate the implementation of the contingency planning policy and associated contingency planning controls are developed and documented;"},{"label":"CP-01a.[04]","prose":"the contingency planning procedures are disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"CP-01a.01","prose":"","items":[{"label":"CP-01a.01(a)","prose":"","items":[{"label":"CP-01a.01(a)[01]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] contingency planning policy addresses purpose;"},{"label":"CP-01a.01(a)[02]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] contingency planning policy addresses scope;"},{"label":"CP-01a.01(a)[03]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] contingency planning policy addresses roles;"},{"label":"CP-01a.01(a)[04]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] contingency planning policy addresses responsibilities;"},{"label":"CP-01a.01(a)[05]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] contingency planning policy addresses management commitment;"},{"label":"CP-01a.01(a)[06]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] contingency planning policy addresses coordination among organizational entities;"},{"label":"CP-01a.01(a)[07]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] contingency planning policy addresses compliance;"}]},{"label":"CP-01a.01(b)","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] contingency planning policy is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines;"}]}]},{"label":"CP-01b.","prose":"the [Assignment: organization-defined official] is designated to manage the development, documentation, and dissemination of the contingency planning policy and procedures;"},{"label":"CP-01c.","prose":"","items":[{"label":"CP-01c.01","prose":"","items":[{"label":"CP-01c.01[01]","prose":"the current contingency planning policy is reviewed and updated [Assignment: organization-defined frequency];"},{"label":"CP-01c.01[02]","prose":"the current contingency planning policy is reviewed and updated following [Assignment: organization-defined events];"}]},{"label":"CP-01c.02","prose":"","items":[{"label":"CP-01c.02[01]","prose":"the current contingency planning procedures are reviewed and updated [Assignment: organization-defined frequency];"},{"label":"CP-01c.02[02]","prose":"the current contingency planning procedures are reviewed and updated following [Assignment: organization-defined events]."}]}]}],"methods":[{"method":"Examine","objects":["Contingency planning policy and procedures","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with contingency planning responsibilities","organizational personnel with information security and privacy responsibilities"]}]},"CP-2":{"statement":[{"label":"a.","prose":"Develop a contingency plan for the system that:","items":[{"label":"1.","prose":"Identifies essential mission and business functions and associated contingency requirements;"},{"label":"2.","prose":"Provides recovery objectives, restoration priorities, and metrics;"},{"label":"3.","prose":"Addresses contingency roles, responsibilities, assigned individuals with contact information;"},{"label":"4.","prose":"Addresses maintaining essential mission and business functions despite a system disruption, compromise, or failure;"},{"label":"5.","prose":"Addresses eventual, full system restoration without deterioration of the controls originally planned and implemented;"},{"label":"6.","prose":"Addresses the sharing of contingency information; and"},{"label":"7.","prose":"Is reviewed and approved by [Assignment: organization-defined personnel or roles];"}]},{"label":"b.","prose":"Distribute copies of the contingency plan to [Assignment: organization-defined key contingency personnel (identified by name and/or by role) and organizational elements];"},{"label":"c.","prose":"Coordinate contingency planning activities with incident handling activities;"},{"label":"d.","prose":"Review the contingency plan for the system [Assignment: organization-defined frequency];"},{"label":"e.","prose":"Update the contingency plan to address changes to the organization, system, or environment of operation and problems encountered during contingency plan implementation, execution, or testing;"},{"label":"f.","prose":"Communicate contingency plan changes to [Assignment: organization-defined key contingency personnel (identified by name and/or by role) and organizational elements];"},{"label":"g.","prose":"Incorporate lessons learned from contingency plan testing, training, or actual contingency activities into contingency testing and training; and"},{"label":"h.","prose":"Protect the contingency plan from unauthorized disclosure and modification."}],"discussion":["Contingency planning for systems is part of an overall program for achieving continuity of operations for organizational mission and business functions. Contingency planning addresses system restoration and implementation of alternative mission or business processes when systems are compromised or breached. Contingency planning is considered throughout the system development life cycle and is a fundamental part of the system design. Systems can be designed for redundancy, to provide backup capabilities, and for resilience. Contingency plans reflect the degree of restoration required for organizational systems since not all systems need to fully recover to achieve the level of continuity of operations desired. System recovery objectives reflect applicable laws, executive orders, directives, regulations, policies, standards, guidelines, organizational risk tolerance, and system impact level.","Actions addressed in contingency plans include orderly system degradation, system shutdown, fallback to a manual mode, alternate information flows, and operating in modes reserved for when systems are under attack. By coordinating contingency planning with incident handling activities, organizations ensure that the necessary planning activities are in place and activated in the event of an incident. Organizations consider whether continuity of operations during an incident conflicts with the capability to automatically disable the system, as specified in [IR-4(5)](#ir-4.5). Incident response planning is part of contingency planning for organizations and is addressed in the [IR](#ir) (Incident Response) family."],"params":[{"id":"CP-2_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]"},{"id":"CP-2_PRM_2","kind":"Assignment","value":"[Assignment: organization-defined key contingency personnel (identified by name and/or by role) and organizational elements]"},{"id":"CP-2_PRM_4","kind":"Assignment","value":"[Assignment: organization-defined key contingency personnel (identified by name and/or by role) and organizational elements]"},{"id":"CP-02_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to review a contingency plan is/are defined"},{"id":"CP-02_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to approve a contingency plan is/are defined"},{"id":"CP-02_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined key contingency personnel]","guideline":"key contingency personnel (identified by name and/or by role) to whom copies of the contingency plan are distributed are defined"},{"id":"CP-02_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined organizational elements]","guideline":"key contingency organizational elements to which copies of the contingency plan are distributed are defined"},{"id":"CP-02_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency of contingency plan review is defined"},{"id":"CP-02_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined key contingency personnel]","guideline":"key contingency personnel (identified by name and/or by role) to communicate changes to are defined"},{"id":"CP-02_ODP[07]","kind":"Assignment","value":"[Assignment: organization-defined organizational elements]","guideline":"key contingency organizational elements to communicate changes to are defined"}],"related":["CP-3","CP-4","CP-6","CP-7","CP-8","CP-9","CP-10","CP-11","CP-13","IR-4","IR-6","IR-8","IR-9","MA-6","MP-2","MP-4","MP-5","PL-2","PM-8","PM-11","SA-15","SA-20","SC-7","SC-23","SI-12"],"references":[{"title":"SP 800-34","url":"https://doi.org/10.6028/NIST.SP.800-34r1"},{"title":"IR 8179","url":"https://doi.org/10.6028/NIST.IR.8179"}],"objectives":[{"label":"CP-02a.","prose":"","items":[{"label":"CP-02a.01","prose":"a contingency plan for the system is developed that identifies essential mission and business functions and associated contingency requirements;"},{"label":"CP-02a.02","prose":"","items":[{"label":"CP-02a.02[01]","prose":"a contingency plan for the system is developed that provides recovery objectives;"},{"label":"CP-02a.02[02]","prose":"a contingency plan for the system is developed that provides restoration priorities;"},{"label":"CP-02a.02[03]","prose":"a contingency plan for the system is developed that provides metrics;"}]},{"label":"CP-02a.03","prose":"","items":[{"label":"CP-02a.03[01]","prose":"a contingency plan for the system is developed that addresses contingency roles;"},{"label":"CP-02a.03[02]","prose":"a contingency plan for the system is developed that addresses contingency responsibilities;"},{"label":"CP-02a.03[03]","prose":"a contingency plan for the system is developed that addresses assigned individuals with contact information;"}]},{"label":"CP-02a.04","prose":"a contingency plan for the system is developed that addresses maintaining essential mission and business functions despite a system disruption, compromise, or failure;"},{"label":"CP-02a.05","prose":"a contingency plan for the system is developed that addresses eventual, full-system restoration without deterioration of the controls originally planned and implemented;"},{"label":"CP-02a.06","prose":"a contingency plan for the system is developed that addresses the sharing of contingency information;"},{"label":"CP-02a.07","prose":"","items":[{"label":"CP-02a.07[01]","prose":"a contingency plan for the system is developed that is reviewed by [Assignment: organization-defined personnel or roles];"},{"label":"CP-02a.07[02]","prose":"a contingency plan for the system is developed that is approved by [Assignment: organization-defined personnel or roles];"}]}]},{"label":"CP-02b.","prose":"","items":[{"label":"CP-02b.[01]","prose":"copies of the contingency plan are distributed to [Assignment: organization-defined key contingency personnel];"},{"label":"CP-02b.[02]","prose":"copies of the contingency plan are distributed to [Assignment: organization-defined organizational elements];"}]},{"label":"CP-02c.","prose":"contingency planning activities are coordinated with incident handling activities;"},{"label":"CP-02d.","prose":"the contingency plan for the system is reviewed [Assignment: organization-defined frequency];"},{"label":"CP-02e.","prose":"","items":[{"label":"CP-02e.[01]","prose":"the contingency plan is updated to address changes to the organization, system, or environment of operation;"},{"label":"CP-02e.[02]","prose":"the contingency plan is updated to address problems encountered during contingency plan implementation, execution, or testing;"}]},{"label":"CP-02f.","prose":"","items":[{"label":"CP-02f.[01]","prose":"contingency plan changes are communicated to [Assignment: organization-defined key contingency personnel];"},{"label":"CP-02f.[02]","prose":"contingency plan changes are communicated to [Assignment: organization-defined organizational elements];"}]},{"label":"CP-02g.","prose":"","items":[{"label":"CP-02g.[01]","prose":"lessons learned from contingency plan testing or actual contingency activities are incorporated into contingency testing;"},{"label":"CP-02g.[02]","prose":"lessons learned from contingency plan training or actual contingency activities are incorporated into contingency testing and training;"}]},{"label":"CP-02h.","prose":"","items":[{"label":"CP-02h.[01]","prose":"the contingency plan is protected from unauthorized disclosure;"},{"label":"CP-02h.[02]","prose":"the contingency plan is protected from unauthorized modification."}]}],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing contingency operations for the system","contingency plan","evidence of contingency plan reviews and updates","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with contingency planning and plan implementation responsibilities","organizational personnel with incident handling responsibilities","organizational personnel with knowledge of requirements for mission and business functions","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for contingency plan development, review, update, and protection","mechanisms for developing, reviewing, updating, and/or protecting the contingency plan"]}]},"CP-2(1)":{"statement":[{"prose":"Coordinate contingency plan development with organizational elements responsible for related plans."}],"discussion":["Plans that are related to contingency plans include Business Continuity Plans, Disaster Recovery Plans, Critical Infrastructure Plans, Continuity of Operations Plans, Crisis Communications Plans, Insider Threat Implementation Plans, Data Breach Response Plans, Cyber Incident Response Plans, Breach Response Plans, and Occupant Emergency Plans."],"params":[],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing contingency operations for the system","contingency plan","business contingency plans","disaster recovery plans","continuity of operations plans","crisis communications plans","critical infrastructure plans"]},{"method":"Interview","objects":["Organizational personnel with contingency planning and plan implementation responsibilities","organizational personnel with information security responsibilities","personnel with responsibility for related plans"]}]},"CP-2(2)":{"statement":[{"prose":"Conduct capacity planning so that necessary capacity for information processing, telecommunications, and environmental support exists during contingency operations."}],"discussion":["Capacity planning is needed because different threats can result in a reduction of the available processing, telecommunications, and support services intended to support essential mission and business functions. Organizations anticipate degraded operations during contingency operations and factor the degradation into capacity planning. For capacity planning, environmental support refers to any environmental factor for which the organization determines that it needs to provide support in a contingency situation, even if in a degraded state. Such determinations are based on an organizational assessment of risk, system categorization (impact level), and organizational risk tolerance."],"params":[],"related":["PE-11","PE-12","PE-13","PE-14","PE-18","SC-5"],"references":[],"objectives":[{"label":"CP-02(02)[01]","prose":"capacity planning is conducted so that the necessary capacity exists during contingency operations for information processing;"},{"label":"CP-02(02)[02]","prose":"capacity planning is conducted so that the necessary capacity exists during contingency operations for telecommunications;"},{"label":"CP-02(02)[03]","prose":"capacity planning is conducted so that the necessary capacity exists during contingency operations for environmental support."}],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing contingency operations for the system","contingency plan","capacity planning documents","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with contingency planning and plan implementation responsibilities","organizational personnel responsible for capacity planning","organizational personnel with information security responsibilities"]}]},"CP-2(3)":{"statement":[{"prose":"Plan for the resumption of [Selection: all; essential] mission and business functions within [Assignment: organization-defined time period] of contingency plan activation."}],"discussion":["Organizations may choose to conduct contingency planning activities to resume mission and business functions as part of business continuity planning or as part of business impact analyses. Organizations prioritize the resumption of mission and business functions. The time period for resuming mission and business functions may be dependent on the severity and extent of the disruptions to the system and its supporting infrastructure."],"params":[{"id":"CP-02(03)_ODP[01]","kind":"Selection","value":"[Selection: all; essential]"},{"id":"CP-02(03)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"the contingency plan activation time period within which to resume mission and business functions is defined"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing contingency operations for the system","contingency plan","business impact assessment","system security plan","privacy plan","other related plans","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with contingency planning and plan implementation responsibilities","organizational personnel with information security and privacy responsibilities","organizational personnel with knowledge of requirements for mission and business functions"]},{"method":"Test","objects":["Organizational processes for resumption of missions and business functions"]}]},"CP-2(5)":{"statement":[{"prose":"Plan for the continuance of [Selection: all; essential] mission and business functions with minimal or no loss of operational continuity and sustains that continuity until full system restoration at primary processing and/or storage sites."}],"discussion":["Organizations may choose to conduct the contingency planning activities to continue mission and business functions as part of business continuity planning or business impact analyses. Primary processing and/or storage sites defined by organizations as part of contingency planning may change depending on the circumstances associated with the contingency."],"params":[{"id":"CP-02(05)_ODP","kind":"Selection","value":"[Selection: all; essential]"}],"related":[],"references":[],"objectives":[{"label":"CP-02(05)[01]","prose":"the continuance of [Selection: all; essential] mission and business functions with minimal or no loss of operational continuity is planned for;"},{"label":"CP-02(05)[02]","prose":"continuity is sustained until full system restoration at primary processing and/or storage sites."}],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing contingency operations for the system","contingency plan","business impact assessment","primary processing site agreements","primary storage site agreements","alternate processing site agreements","alternate storage site agreements"]},{"method":"Interview","objects":["Organizational personnel with contingency planning and plan implementation responsibilities","organizational personnel with knowledge of requirements for mission and business functions","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for continuing missions and business functions"]}]},"CP-2(8)":{"statement":[{"prose":"Identify critical system assets supporting [Selection: all; essential] mission and business functions."}],"discussion":["Organizations may choose to identify critical assets as part of criticality analysis, business continuity planning, or business impact analyses. Organizations identify critical system assets so that additional controls can be employed (beyond the controls routinely implemented) to help ensure that organizational mission and business functions can continue to be conducted during contingency operations. The identification of critical information assets also facilitates the prioritization of organizational resources. Critical system assets include technical and operational aspects. Technical aspects include system components, information technology services, information technology products, and mechanisms. Operational aspects include procedures (i.e., manually executed operations) and personnel (i.e., individuals operating technical controls and/or executing manual procedures). Organizational program protection plans can assist in identifying critical assets. If critical assets are resident within or supported by external service providers, organizations consider implementing [CP-2(7)](#cp-2.7) as a control enhancement."],"params":[{"id":"CP-02(08)_ODP","kind":"Selection","value":"[Selection: all; essential]"}],"related":["CM-8","RA-9"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing contingency operations for the system","contingency plan","business impact assessment","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with contingency planning and plan implementation responsibilities","organizational personnel with knowledge of requirements for mission and business functions","organizational personnel with information security responsibilities"]}]},"CP-3":{"statement":[{"label":"a.","prose":"Provide contingency training to system users consistent with assigned roles and responsibilities:","items":[{"label":"1.","prose":"Within [Assignment: organization-defined time period] of assuming a contingency role or responsibility;"},{"label":"2.","prose":"When required by system changes; and"},{"label":"3.","prose":"[Assignment: organization-defined frequency] thereafter; and"}]},{"label":"b.","prose":"Review and update contingency training content [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]."}],"discussion":["Contingency training provided by organizations is linked to the assigned roles and responsibilities of organizational personnel to ensure that the appropriate content and level of detail is included in such training. For example, some individuals may only need to know when and where to report for duty during contingency operations and if normal duties are affected; system administrators may require additional training on how to establish systems at alternate processing and storage sites; and organizational officials may receive more specific training on how to conduct mission-essential functions in designated off-site locations and how to establish communications with other governmental entities for purposes of coordination on contingency-related activities. Training for contingency roles or responsibilities reflects the specific continuity requirements in the contingency plan. Events that may precipitate an update to contingency training content include, but are not limited to, contingency plan testing or an actual contingency (lessons learned), assessment or audit findings, security incidents or breaches, or changes in laws, executive orders, directives, regulations, policies, standards, and guidelines. At the discretion of the organization, participation in a contingency plan test or exercise, including lessons learned sessions subsequent to the test or exercise, may satisfy contingency plan training requirements."],"params":[{"id":"CP-03_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"the time period within which to provide contingency training after assuming a contingency role or responsibility is defined"},{"id":"CP-03_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to provide training to system users with a contingency role or responsibility is defined"},{"id":"CP-03_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to review and update contingency training content is defined"},{"id":"CP-03_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events necessitating review and update of contingency training are defined"}],"related":["AT-2","AT-3","AT-4","CP-2","CP-4","CP-8","IR-2","IR-4","IR-9"],"references":[{"title":"SP 800-50","url":"https://doi.org/10.6028/NIST.SP.800-50"}],"objectives":[{"label":"CP-03a.","prose":"","items":[{"label":"CP-03a.01","prose":"contingency training is provided to system users consistent with assigned roles and responsibilities within [Assignment: organization-defined time period] of assuming a contingency role or responsibility;"},{"label":"CP-03a.02","prose":"contingency training is provided to system users consistent with assigned roles and responsibilities when required by system changes;"},{"label":"CP-03a.03","prose":"contingency training is provided to system users consistent with assigned roles and responsibilities [Assignment: organization-defined frequency] thereafter;"}]},{"label":"CP-03b.","prose":"","items":[{"label":"CP-03b.[01]","prose":"the contingency plan training content is reviewed and updated [Assignment: organization-defined frequency];"},{"label":"CP-03b.[02]","prose":"the contingency plan training content is reviewed and updated following [Assignment: organization-defined events]."}]}],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing contingency training","contingency plan","contingency training curriculum","contingency training material","contingency training records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with contingency planning, plan implementation, and training responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for contingency training"]}]},"CP-3(1)":{"statement":[{"prose":"Incorporate simulated events into contingency training to facilitate effective response by personnel in crisis situations."}],"discussion":["The use of simulated events creates an environment for personnel to experience actual threat events, including cyber-attacks that disable websites, ransomware attacks that encrypt organizational data on servers, hurricanes that damage or destroy organizational facilities, or hardware or software failures."],"params":[],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing contingency training","contingency plan","contingency training curriculum","contingency training material","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with contingency planning, plan implementation, and training responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for contingency training","mechanisms for simulating contingency events"]}]},"CP-4":{"statement":[{"label":"a.","prose":"Test the contingency plan for the system [Assignment: organization-defined frequency] using the following tests to determine the effectiveness of the plan and the readiness to execute the plan: [Assignment: organization-defined tests]."},{"label":"b.","prose":"Review the contingency plan test results; and"},{"label":"c.","prose":"Initiate corrective actions, if needed."}],"discussion":["Methods for testing contingency plans to determine the effectiveness of the plans and identify potential weaknesses include checklists, walk-through and tabletop exercises, simulations (parallel or full interrupt), and comprehensive exercises. Organizations conduct testing based on the requirements in contingency plans and include a determination of the effects on organizational operations, assets, and individuals due to contingency operations. Organizations have flexibility and discretion in the breadth, depth, and timelines of corrective actions."],"params":[{"id":"CP-4_PRM_2","kind":"Assignment","value":"[Assignment: organization-defined tests]"},{"id":"CP-04_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency of testing the contingency plan for the system is defined"},{"id":"CP-04_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined tests]","guideline":"tests for determining the effectiveness of the contingency plan are defined"},{"id":"CP-04_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined tests]","guideline":"tests for determining readiness to execute the contingency plan are defined"}],"related":["AT-3","CP-2","CP-3","CP-8","CP-9","IR-3","IR-4","PL-2","PM-14","SR-2"],"references":[{"title":"FIPS 199","url":"https://doi.org/10.6028/NIST.FIPS.199"},{"title":"SP 800-34","url":"https://doi.org/10.6028/NIST.SP.800-34r1"},{"title":"SP 800-84","url":"https://doi.org/10.6028/NIST.SP.800-84"},{"title":"SP 800-160-2","url":"https://doi.org/10.6028/NIST.SP.800-160v2"}],"objectives":[{"label":"CP-04a.","prose":"","items":[{"label":"CP-04a.[01]","prose":"the contingency plan for the system is tested [Assignment: organization-defined frequency];"},{"label":"CP-04a.[02]","prose":"[Assignment: organization-defined tests] are used to determine the effectiveness of the plan;"},{"label":"CP-04a.[03]","prose":"[Assignment: organization-defined tests] are used to determine the readiness to execute the plan;"}]},{"label":"CP-04b.","prose":"the contingency plan test results are reviewed;"},{"label":"CP-04c.","prose":"corrective actions are initiated, if needed."}],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing contingency plan testing","contingency plan","contingency plan test documentation","contingency plan test results","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for contingency plan testing, reviewing, or responding to contingency plan tests","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for contingency plan testing","mechanisms supporting the contingency plan and/or contingency plan testing"]}]},"CP-4(1)":{"statement":[{"prose":"Coordinate contingency plan testing with organizational elements responsible for related plans."}],"discussion":["Plans related to contingency planning for organizational systems include Business Continuity Plans, Disaster Recovery Plans, Continuity of Operations Plans, Crisis Communications Plans, Critical Infrastructure Plans, Cyber Incident Response Plans, and Occupant Emergency Plans. Coordination of contingency plan testing does not require organizations to create organizational elements to handle related plans or to align such elements with specific plans. However, it does require that if such organizational elements are responsible for related plans, organizations coordinate with those elements."],"params":[],"related":["IR-8","PM-8"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Contingency planning policy","incident response policy","procedures addressing contingency plan testing","contingency plan testing documentation","contingency plan","business continuity plans","disaster recovery plans","continuity of operations plans"]},{"method":"Interview","objects":["Organizational personnel with contingency plan testing responsibilities","personnel with responsibilities for related plans","organizational personnel with information security responsibilities"]}]},"CP-4(2)":{"statement":[{"prose":"Test the contingency plan at the alternate processing site:"},{"label":"(a)","prose":"To familiarize contingency personnel with the facility and available resources; and"},{"label":"(b)","prose":"To evaluate the capabilities of the alternate processing site to support contingency operations."}],"discussion":["Conditions at the alternate processing site may be significantly different than the conditions at the primary site. Having the opportunity to visit the alternate site and experience the actual capabilities available at the site can provide valuable information on potential vulnerabilities that could affect essential organizational mission and business functions. The on-site visit can also provide an opportunity to refine the contingency plan to address the vulnerabilities discovered during testing."],"params":[],"related":["CP-7"],"references":[],"objectives":[{"label":"CP-04(02)(a)","prose":"the contingency plan is tested at the alternate processing site to familiarize contingency personnel with the facility and available resources;"},{"label":"CP-04(02)(b)","prose":"the contingency plan is tested at the alternate processing site to evaluate the capabilities of the alternate processing site to support contingency operations."}],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing contingency plan testing","contingency plan","contingency plan test documentation","contingency plan test results","alternate processing site agreements","service-level agreements","system security plan"]},{"method":"Interview","objects":["Organizational personnel with contingency planning and plan implementation responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for contingency plan testing","mechanisms supporting the contingency plan and/or contingency plan testing"]}]},"CP-6":{"statement":[{"label":"a.","prose":"Establish an alternate storage site, including necessary agreements to permit the storage and retrieval of system backup information; and"},{"label":"b.","prose":"Ensure that the alternate storage site provides controls equivalent to that of the primary site."}],"discussion":["Alternate storage sites are geographically distinct from primary storage sites and maintain duplicate copies of information and data if the primary storage site is not available. Similarly, alternate processing sites provide processing capability if the primary processing site is not available. Geographically distributed architectures that support contingency requirements may be considered alternate storage sites. Items covered by alternate storage site agreements include environmental conditions at the alternate sites, access rules for systems and facilities, physical and environmental protection requirements, and coordination of delivery and retrieval of backup media. Alternate storage sites reflect the requirements in contingency plans so that organizations can maintain essential mission and business functions despite compromise, failure, or disruption in organizational systems."],"params":[],"related":["CP-2","CP-7","CP-8","CP-9","CP-10","MP-4","MP-5","PE-3","SC-36","SI-13"],"references":[{"title":"SP 800-34","url":"https://doi.org/10.6028/NIST.SP.800-34r1"}],"objectives":[{"label":"CP-06a.","prose":"","items":[{"label":"CP-06a.[01]","prose":"an alternate storage site is established;"},{"label":"CP-06a.[02]","prose":"establishment of the alternate storage site includes necessary agreements to permit the storage and retrieval of system backup information;"}]},{"label":"CP-06b.","prose":"the alternate storage site provides controls equivalent to that of the primary site."}],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing alternate storage sites","contingency plan","alternate storage site agreements","primary storage site agreements","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with contingency plan alternate storage site responsibilities","organizational personnel with system recovery responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for storing and retrieving system backup information at the alternate storage site","mechanisms supporting and/or implementing the storage and retrieval of system backup information at the alternate storage site"]}]},"CP-6(1)":{"statement":[{"prose":"Identify an alternate storage site that is sufficiently separated from the primary storage site to reduce susceptibility to the same threats."}],"discussion":["Threats that affect alternate storage sites are defined in organizational risk assessments and include natural disasters, structural failures, hostile attacks, and errors of omission or commission. Organizations determine what is considered a sufficient degree of separation between primary and alternate storage sites based on the types of threats that are of concern. For threats such as hostile attacks, the degree of separation between sites is less relevant."],"params":[],"related":["RA-3"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing alternate storage sites","contingency plan","alternate storage site","alternate storage site agreements","primary storage site agreements","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with contingency plan alternate storage site responsibilities","organizational personnel with system recovery responsibilities","organizational personnel with information security responsibilities"]}]},"CP-6(2)":{"statement":[{"prose":"Configure the alternate storage site to facilitate recovery operations in accordance with recovery time and recovery point objectives."}],"discussion":["Organizations establish recovery time and recovery point objectives as part of contingency planning. Configuration of the alternate storage site includes physical facilities and the systems supporting recovery operations that ensure accessibility and correct execution."],"params":[],"related":[],"references":[],"objectives":[{"label":"CP-06(02)[01]","prose":"the alternate storage site is configured to facilitate recovery operations in accordance with recovery time objectives;"},{"label":"CP-06(02)[02]","prose":"the alternate storage site is configured to facilitate recovery operations in accordance with recovery point objectives."}],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing alternate storage sites","contingency plan","alternate storage site","alternate storage site agreements","alternate storage site configurations","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with contingency plan testing responsibilities","organizational personnel with responsibilities for testing related plans","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for contingency plan testing","mechanisms supporting recovery time and point objectives"]}]},"CP-6(3)":{"statement":[{"prose":"Identify potential accessibility problems to the alternate storage site in the event of an area-wide disruption or disaster and outline explicit mitigation actions."}],"discussion":["Area-wide disruptions refer to those types of disruptions that are broad in geographic scope with such determinations made by organizations based on organizational assessments of risk. Explicit mitigation actions include duplicating backup information at other alternate storage sites if access problems occur at originally designated alternate sites or planning for physical access to retrieve backup information if electronic accessibility to the alternate site is disrupted."],"params":[],"related":["RA-3"],"references":[],"objectives":[{"label":"CP-06(03)[01]","prose":"potential accessibility problems to the alternate storage site in the event of an area-wide disruption or disaster are identified;"},{"label":"CP-06(03)[02]","prose":"explicit mitigation actions to address identified accessibility problems are outlined."}],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing alternate storage sites","contingency plan","alternate storage site","list of potential accessibility problems to alternate storage site","mitigation actions for accessibility problems to alternate storage site","organizational risk assessments","system security plan"]},{"method":"Interview","objects":["Organizational personnel with contingency plan alternate storage site responsibilities","organizational personnel with system recovery responsibilities","organizational personnel with information security responsibilities"]}]},"CP-7":{"statement":[{"label":"a.","prose":"Establish an alternate processing site, including necessary agreements to permit the transfer and resumption of [Assignment: organization-defined system operations] for essential mission and business functions within [Assignment: organization-defined time period] when the primary processing capabilities are unavailable;"},{"label":"b.","prose":"Make available at the alternate processing site, the equipment and supplies required to transfer and resume operations or put contracts in place to support delivery to the site within the organization-defined time period for transfer and resumption; and"},{"label":"c.","prose":"Provide controls at the alternate processing site that are equivalent to those at the primary site."}],"discussion":["Alternate processing sites are geographically distinct from primary processing sites and provide processing capability if the primary processing site is not available. The alternate processing capability may be addressed using a physical processing site or other alternatives, such as failover to a cloud-based service provider or other internally or externally provided processing service. Geographically distributed architectures that support contingency requirements may also be considered alternate processing sites. Controls that are covered by alternate processing site agreements include the environmental conditions at alternate sites, access rules, physical and environmental protection requirements, and the coordination for the transfer and assignment of personnel. Requirements are allocated to alternate processing sites that reflect the requirements in contingency plans to maintain essential mission and business functions despite disruption, compromise, or failure in organizational systems."],"params":[{"id":"CP-07_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined system operations]","guideline":"system operations for essential mission and business functions are defined"},{"id":"CP-07_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"time period consistent with recovery time and recovery point objectives is defined"}],"related":["CP-2","CP-6","CP-8","CP-9","CP-10","MA-6","PE-3","PE-11","PE-12","PE-17","SC-36","SI-13"],"references":[{"title":"SP 800-34","url":"https://doi.org/10.6028/NIST.SP.800-34r1"}],"objectives":[{"label":"CP-07a.","prose":"an alternate processing site, including necessary agreements to permit the transfer and resumption of [Assignment: organization-defined system operations] for essential mission and business functions, is established within [Assignment: organization-defined time period] when the primary processing capabilities are unavailable;"},{"label":"CP-07b.","prose":"","items":[{"label":"CP-07b.[01]","prose":"the equipment and supplies required to transfer operations are made available at the alternate processing site or if contracts are in place to support delivery to the site within [Assignment: organization-defined time period] for transfer;"},{"label":"CP-07b.[02]","prose":"the equipment and supplies required to resume operations are made available at the alternate processing site or if contracts are in place to support delivery to the site within [Assignment: organization-defined time period] for resumption;"}]},{"label":"CP-07c.","prose":"controls provided at the alternate processing site are equivalent to those at the primary site."}],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing alternate processing sites","contingency plan","alternate processing site agreements","primary processing site agreements","spare equipment and supplies inventory at alternate processing site","equipment and supply contracts","service-level agreements"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for contingency planning and/or alternate site arrangements","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for recovery at the alternate site","mechanisms supporting and/or implementing recovery at the alternate processing site"]}]},"CP-7(1)":{"statement":[{"prose":"Identify an alternate processing site that is sufficiently separated from the primary processing site to reduce susceptibility to the same threats."}],"discussion":["Threats that affect alternate processing sites are defined in organizational assessments of risk and include natural disasters, structural failures, hostile attacks, and errors of omission or commission. Organizations determine what is considered a sufficient degree of separation between primary and alternate processing sites based on the types of threats that are of concern. For threats such as hostile attacks, the degree of separation between sites is less relevant."],"params":[],"related":["RA-3"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing alternate processing sites","contingency plan","alternate processing site","alternate processing site agreements","primary processing site agreements","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with contingency plan alternate processing site responsibilities","organizational personnel with system recovery responsibilities","organizational personnel with information security responsibilities"]}]},"CP-7(2)":{"statement":[{"prose":"Identify potential accessibility problems to alternate processing sites in the event of an area-wide disruption or disaster and outlines explicit mitigation actions."}],"discussion":["Area-wide disruptions refer to those types of disruptions that are broad in geographic scope with such determinations made by organizations based on organizational assessments of risk."],"params":[],"related":["RA-3"],"references":[],"objectives":[{"label":"CP-07(02)[01]","prose":"potential accessibility problems to alternate processing sites in the event of an area-wide disruption or disaster are identified;"},{"label":"CP-07(02)[02]","prose":"explicit mitigation actions to address identified accessibility problems are outlined."}],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing alternate processing sites","contingency plan","alternate processing site","alternate processing site agreements","primary processing site agreements","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with contingency plan alternate processing site responsibilities","organizational personnel with system recovery responsibilities","organizational personnel with information security responsibilities"]}]},"CP-7(3)":{"statement":[{"prose":"Develop alternate processing site agreements that contain priority-of-service provisions in accordance with availability requirements (including recovery time objectives)."}],"discussion":["Priority of service agreements refer to negotiated agreements with service providers that ensure that organizations receive priority treatment consistent with their availability requirements and the availability of information resources for logical alternate processing and/or at the physical alternate processing site. Organizations establish recovery time objectives as part of contingency planning."],"params":[],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing alternate processing sites","contingency plan","alternate processing site agreements","service-level agreements","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with contingency plan alternate processing site responsibilities","organizational personnel with system recovery responsibilities","organizational personnel with information security responsibilities","organizational personnel with responsibility for acquisitions/contractual agreements"]}]},"CP-7(4)":{"statement":[{"prose":"Prepare the alternate processing site so that the site can serve as the operational site supporting essential mission and business functions."}],"discussion":["Site preparation includes establishing configuration settings for systems at the alternate processing site consistent with the requirements for such settings at the primary site and ensuring that essential supplies and logistical considerations are in place."],"params":[],"related":["CM-2","CM-6","CP-4"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing alternate processing sites","contingency plan","alternate processing site","alternate processing site agreements","alternate processing site configurations","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with contingency plan alternate processing site responsibilities","organizational personnel with system recovery responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing recovery at the alternate processing site"]}]},"CP-8":{"statement":[{"prose":"Establish alternate telecommunications services, including necessary agreements to permit the resumption of [Assignment: organization-defined system operations] for essential mission and business functions within [Assignment: organization-defined time period] when the primary telecommunications capabilities are unavailable at either the primary or alternate processing or storage sites."}],"discussion":["Telecommunications services (for data and voice) for primary and alternate processing and storage sites are in scope for [CP-8](#cp-8). Alternate telecommunications services reflect the continuity requirements in contingency plans to maintain essential mission and business functions despite the loss of primary telecommunications services. Organizations may specify different time periods for primary or alternate sites. Alternate telecommunications services include additional organizational or commercial ground-based circuits or lines, network-based approaches to telecommunications, or the use of satellites. Organizations consider factors such as availability, quality of service, and access when entering into alternate telecommunications agreements."],"params":[{"id":"CP-08_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined system operations]","guideline":"system operations to be resumed for essential mission and business functions are defined"},{"id":"CP-08_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"time period within which to resume essential mission and business functions when the primary telecommunications capabilities are unavailable is defined"}],"related":["CP-2","CP-6","CP-7","CP-11","SC-7"],"references":[{"title":"SP 800-34","url":"https://doi.org/10.6028/NIST.SP.800-34r1"}],"objectives":[],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing alternate telecommunications services","contingency plan","primary and alternate telecommunications service agreements","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with contingency plan telecommunications responsibilities","organizational personnel with system recovery responsibilities","organizational personnel with knowledge of requirements for mission and business functions","organizational personnel with information security responsibilities","organizational personnel with responsibility for acquisitions/contractual agreements"]},{"method":"Test","objects":["Mechanisms supporting telecommunications"]}]},"CP-8(1)":{"statement":[{"label":"(a)","prose":"Develop primary and alternate telecommunications service agreements that contain priority-of-service provisions in accordance with availability requirements (including recovery time objectives); and"},{"label":"(b)","prose":"Request Telecommunications Service Priority for all telecommunications services used for national security emergency preparedness if the primary and/or alternate telecommunications services are provided by a common carrier."}],"discussion":["Organizations consider the potential mission or business impact in situations where telecommunications service providers are servicing other organizations with similar priority of service provisions. Telecommunications Service Priority (TSP) is a Federal Communications Commission (FCC) program that directs telecommunications service providers (e.g., wireline and wireless phone companies) to give preferential treatment to users enrolled in the program when they need to add new lines or have their lines restored following a disruption of service, regardless of the cause. The FCC sets the rules and policies for the TSP program, and the Department of Homeland Security manages the TSP program. The TSP program is always in effect and not contingent on a major disaster or attack taking place. Federal sponsorship is required to enroll in the TSP program."],"params":[],"related":[],"references":[],"objectives":[{"label":"CP-08(01)(a)","prose":"","items":[{"label":"CP-08(01)(a)[01]","prose":"primary telecommunications service agreements that contain priority-of-service provisions in accordance with availability requirements (including recovery time objectives) are developed;"},{"label":"CP-08(01)(a)[02]","prose":"alternate telecommunications service agreements that contain priority-of-service provisions in accordance with availability requirements (including recovery time objectives) are developed;"}]},{"label":"CP-08(01)(b)","prose":"Telecommunications Service Priority is requested for all telecommunications services used for national security emergency preparedness if the primary and/or alternate telecommunications services are provided by a common carrier."}],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing primary and alternate telecommunications services","contingency plan","primary and alternate telecommunications service agreements","Telecommunications Service Priority documentation","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with contingency plan telecommunications responsibilities","organizational personnel with system recovery responsibilities","organizational personnel with information security responsibilities","organizational personnel with responsibility for acquisitions/contractual agreements"]},{"method":"Test","objects":["Mechanisms supporting telecommunications"]}]},"CP-8(2)":{"statement":[{"prose":"Obtain alternate telecommunications services to reduce the likelihood of sharing a single point of failure with primary telecommunications services."}],"discussion":["In certain circumstances, telecommunications service providers or services may share the same physical lines, which increases the vulnerability of a single failure point. It is important to have provider transparency for the actual physical transmission capability for telecommunication services."],"params":[],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing primary and alternate telecommunications services","contingency plan","primary and alternate telecommunications service agreements","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with contingency plan telecommunications responsibilities","organizational personnel with system recovery responsibilities","primary and alternate telecommunications service providers","organizational personnel with information security responsibilities"]}]},"CP-8(3)":{"statement":[{"prose":"Obtain alternate telecommunications services from providers that are separated from primary service providers to reduce susceptibility to the same threats."}],"discussion":["Threats that affect telecommunications services are defined in organizational assessments of risk and include natural disasters, structural failures, cyber or physical attacks, and errors of omission or commission. Organizations can reduce common susceptibilities by minimizing shared infrastructure among telecommunications service providers and achieving sufficient geographic separation between services. Organizations may consider using a single service provider in situations where the service provider can provide alternate telecommunications services that meet the separation needs addressed in the risk assessment."],"params":[],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing primary and alternate telecommunications services","contingency plan","primary and alternate telecommunications service agreements","alternate telecommunications service provider site","primary telecommunications service provider site","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with contingency plan telecommunications responsibilities","organizational personnel with system recovery responsibilities","primary and alternate telecommunications service providers","organizational personnel with information security responsibilities"]}]},"CP-8(4)":{"statement":[{"label":"(a)","prose":"Require primary and alternate telecommunications service providers to have contingency plans;"},{"label":"(b)","prose":"Review provider contingency plans to ensure that the plans meet organizational contingency requirements; and"},{"label":"(c)","prose":"Obtain evidence of contingency testing and training by providers [Assignment: organization-defined frequency]."}],"discussion":["Reviews of provider contingency plans consider the proprietary nature of such plans. In some situations, a summary of provider contingency plans may be sufficient evidence for organizations to satisfy the review requirement. Telecommunications service providers may also participate in ongoing disaster recovery exercises in coordination with the Department of Homeland Security and state and local governments. Organizations may use these types of activities to satisfy evidentiary requirements related to service provider contingency plan reviews, testing, and training."],"params":[{"id":"CP-8.4_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined frequency]"},{"id":"CP-08(04)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to obtain evidence of contingency testing by providers is defined"},{"id":"CP-08(04)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to obtain evidence of contingency training by providers is defined"}],"related":["CP-3","CP-4"],"references":[],"objectives":[{"label":"CP-08(04)(a)","prose":"","items":[{"label":"CP-08(04)(a)[01]","prose":"primary telecommunications service providers are required to have contingency plans;"},{"label":"CP-08(04)(a)[02]","prose":"alternate telecommunications service providers are required to have contingency plans;"}]},{"label":"CP-08(04)(b)","prose":"provider contingency plans are reviewed to ensure that the plans meet organizational contingency requirements;"},{"label":"CP-08(04)(c)","prose":"","items":[{"label":"CP-08(04)(c)[01]","prose":"evidence of contingency testing by providers is obtained [Assignment: organization-defined frequency]."},{"label":"CP-08(04)(c)[02]","prose":"evidence of contingency training by providers is obtained [Assignment: organization-defined frequency]."}]}],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing primary and alternate telecommunications services","contingency plan","provider contingency plans","evidence of contingency testing/training by providers","primary and alternate telecommunications service agreements","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with contingency planning, plan implementation, and testing responsibilities","primary and alternate telecommunications service providers","organizational personnel with information security responsibilities","organizational personnel with responsibility for acquisitions/contractual agreements"]}]},"CP-9":{"statement":[{"label":"a.","prose":"Conduct backups of user-level information contained in [Assignment: organization-defined system components] [Assignment: organization-defined frequency];"},{"label":"b.","prose":"Conduct backups of system-level information contained in the system [Assignment: organization-defined frequency];"},{"label":"c.","prose":"Conduct backups of system documentation, including security- and privacy-related documentation [Assignment: organization-defined frequency]; and"},{"label":"d.","prose":"Protect the confidentiality, integrity, and availability of backup information."}],"discussion":["System-level information includes system state information, operating system software, middleware, application software, and licenses. User-level information includes information other than system-level information. Mechanisms employed to protect the integrity of system backups include digital signatures and cryptographic hashes. Protection of system backup information while in transit is addressed by [MP-5](#mp-5) and [SC-8](#sc-8). System backups reflect the requirements in contingency plans as well as other organizational requirements for backing up information. Organizations may be subject to laws, executive orders, directives, regulations, or policies with requirements regarding specific categories of information (e.g., personal health information). Organizational personnel consult with the senior agency official for privacy and legal counsel regarding such requirements."],"params":[{"id":"CP-09_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined system components]","guideline":"system components for which to conduct backups of user-level information is defined"},{"id":"CP-09_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to conduct backups of user-level information consistent with recovery time and recovery point objectives is defined"},{"id":"CP-09_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to conduct backups of system-level information consistent with recovery time and recovery point objectives is defined"},{"id":"CP-09_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to conduct backups of system documentation consistent with recovery time and recovery point objectives is defined"}],"related":["CP-2","CP-6","CP-10","MP-4","MP-5","SC-8","SC-12","SC-13","SI-4","SI-13"],"references":[{"title":"FIPS 140-3","url":"https://doi.org/10.6028/NIST.FIPS.140-3"},{"title":"FIPS 186-4","url":"https://doi.org/10.6028/NIST.FIPS.186-4"},{"title":"SP 800-34","url":"https://doi.org/10.6028/NIST.SP.800-34r1"},{"title":"SP 800-130","url":"https://doi.org/10.6028/NIST.SP.800-130"},{"title":"SP 800-152","url":"https://doi.org/10.6028/NIST.SP.800-152"}],"objectives":[{"label":"CP-09a.","prose":"backups of user-level information contained in [Assignment: organization-defined system components] are conducted [Assignment: organization-defined frequency];"},{"label":"CP-09b.","prose":"backups of system-level information contained in the system are conducted [Assignment: organization-defined frequency];"},{"label":"CP-09c.","prose":"backups of system documentation, including security- and privacy-related documentation are conducted [Assignment: organization-defined frequency];"},{"label":"CP-09d.","prose":"","items":[{"label":"CP-09d.[01]","prose":"the confidentiality of backup information is protected;"},{"label":"CP-09d.[02]","prose":"the integrity of backup information is protected;"},{"label":"CP-09d.[03]","prose":"the availability of backup information is protected."}]}],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing system backup","contingency plan","backup storage location(s)","system backup logs or records","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system backup responsibilities","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Organizational processes for conducting system backups","mechanisms supporting and/or implementing system backups"]}]},"CP-9(1)":{"statement":[{"prose":"Test backup information [Assignment: organization-defined frequency] to verify media reliability and information integrity."}],"discussion":["Organizations need assurance that backup information can be reliably retrieved. Reliability pertains to the systems and system components where the backup information is stored, the operations used to retrieve the information, and the integrity of the information being retrieved. Independent and specialized tests can be used for each of the aspects of reliability. For example, decrypting and transporting (or transmitting) a random sample of backup files from the alternate storage or backup site and comparing the information to the same information at the primary processing site can provide such assurance."],"params":[{"id":"CP-9.1_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined frequency]"},{"id":"CP-09(01)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to test backup information for media reliability is defined"},{"id":"CP-09(01)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to test backup information for information integrity is defined"}],"related":["CP-4"],"references":[],"objectives":[{"label":"CP-09(01)[01]","prose":"backup information is tested [Assignment: organization-defined frequency] to verify media reliability;"},{"label":"CP-09(01)[02]","prose":"backup information is tested [Assignment: organization-defined frequency] to verify information integrity."}],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing system backup","contingency plan","system backup test results","contingency plan test documentation","contingency plan test results","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system backup responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for conducting system backups","mechanisms supporting and/or implementing system backups"]}]},"CP-9(2)":{"statement":[{"prose":"Use a sample of backup information in the restoration of selected system functions as part of contingency plan testing."}],"discussion":["Organizations need assurance that system functions can be restored correctly and can support established organizational missions. To ensure that the selected system functions are thoroughly exercised during contingency plan testing, a sample of backup information is retrieved to determine whether the functions are operating as intended. Organizations can determine the sample size for the functions and backup information based on the level of assurance needed."],"params":[],"related":["CP-4"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing system backup","contingency plan","system backup test results","contingency plan test documentation","contingency plan test results","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system backup responsibilities","organizational personnel with contingency planning/contingency plan testing responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for conducting system backups","mechanisms supporting and/or implementing system backups"]}]},"CP-9(3)":{"statement":[{"prose":"Store backup copies of [Assignment: organization-defined critical system software and other security-related information] in a separate facility or in a fire rated container that is not collocated with the operational system."}],"discussion":["Separate storage for critical information applies to all critical information regardless of the type of backup storage media. Critical system software includes operating systems, middleware, cryptographic key management systems, and intrusion detection systems. Security-related information includes inventories of system hardware, software, and firmware components. Alternate storage sites, including geographically distributed architectures, serve as separate storage facilities for organizations. Organizations may provide separate storage by implementing automated backup processes at alternative storage sites (e.g., data centers). The General Services Administration (GSA) establishes standards and specifications for security and fire rated containers."],"params":[{"id":"CP-09(03)_ODP","kind":"Assignment","value":"[Assignment: organization-defined critical system software and other security-related information]","guideline":"critical system software and other security-related information backups to be stored in a separate facility are defined"}],"related":["CM-2","CM-6","CM-8"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing system backup","contingency plan","backup storage location(s)","system backup configurations and associated documentation","system backup logs or records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with contingency planning and plan implementation responsibilities","organizational personnel with system backup responsibilities","organizational personnel with information security responsibilities"]}]},"CP-9(5)":{"statement":[{"prose":"Transfer system backup information to the alternate storage site [Assignment: organization-defined time period and transfer rate consistent with the recovery time and recovery point objectives]."}],"discussion":["System backup information can be transferred to alternate storage sites either electronically or by the physical shipment of storage media."],"params":[{"id":"CP-9.5_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined time period and transfer rate consistent with the recovery time and recovery point objectives]"},{"id":"CP-09(05)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"time period consistent with recovery time and recovery point objectives is defined"},{"id":"CP-09(05)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined transfer rate]","guideline":"transfer rate consistent with recovery time and recovery point objectives is defined"}],"related":["CP-7","MP-3","MP-4","MP-5"],"references":[],"objectives":[{"label":"CP-09(05)[01]","prose":"system backup information is transferred to the alternate storage site for [Assignment: organization-defined time period];"},{"label":"CP-09(05)[02]","prose":"system backup information is transferred to the alternate storage site [Assignment: organization-defined transfer rate]."}],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing system backup","contingency plan","system backup logs or records","evidence of system backup information transferred to alternate storage site","alternate storage site agreements","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system backup responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for transferring system backups to the alternate storage site","mechanisms supporting and/or implementing system backups","mechanisms supporting and/or implementing information transfer to the alternate storage site"]}]},"CP-9(8)":{"statement":[{"prose":"Implement cryptographic mechanisms to prevent unauthorized disclosure and modification of [Assignment: organization-defined backup information]."}],"discussion":["The selection of cryptographic mechanisms is based on the need to protect the confidentiality and integrity of backup information. The strength of mechanisms selected is commensurate with the security category or classification of the information. Cryptographic protection applies to system backup information in storage at both primary and alternate locations. Organizations that implement cryptographic mechanisms to protect information at rest also consider cryptographic key management solutions."],"params":[{"id":"CP-09(08)_ODP","kind":"Assignment","value":"[Assignment: organization-defined backup information]","guideline":"backup information to protect against unauthorized disclosure and modification is defined"}],"related":["SC-12","SC-13","SC-28"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing system backup","contingency plan","system design documentation","system configuration settings and associated documentation","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system backup responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing cryptographic protection of backup information"]}]},"CP-10":{"statement":[{"prose":"Provide for the recovery and reconstitution of the system to a known state within [Assignment: organization-defined time period consistent with recovery time and recovery point objectives] after a disruption, compromise, or failure."}],"discussion":["Recovery is executing contingency plan activities to restore organizational mission and business functions. Reconstitution takes place following recovery and includes activities for returning systems to fully operational states. Recovery and reconstitution operations reflect mission and business priorities; recovery point, recovery time, and reconstitution objectives; and organizational metrics consistent with contingency plan requirements. Reconstitution includes the deactivation of interim system capabilities that may have been needed during recovery operations. Reconstitution also includes assessments of fully restored system capabilities, reestablishment of continuous monitoring activities, system reauthorization (if required), and activities to prepare the system and organization for future disruptions, breaches, compromises, or failures. Recovery and reconstitution capabilities can include automated mechanisms and manual procedures. Organizations establish recovery time and recovery point objectives as part of contingency planning."],"params":[{"id":"CP-10_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined time period consistent with recovery time and recovery point objectives]"},{"id":"CP-10_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"time period consistent with recovery time and recovery point objectives for the recovery of the system is determined"},{"id":"CP-10_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"time period consistent with recovery time and recovery point objectives for the reconstitution of the system is determined"}],"related":["CP-2","CP-4","CP-6","CP-7","CP-9","IR-4","SA-8","SC-24","SI-13"],"references":[{"title":"SP 800-34","url":"https://doi.org/10.6028/NIST.SP.800-34r1"}],"objectives":[{"label":"CP-10[01]","prose":"the recovery of the system to a known state is provided within [Assignment: organization-defined time period] after a disruption, compromise, or failure;"},{"label":"CP-10[02]","prose":"a reconstitution of the system to a known state is provided within [Assignment: organization-defined time period] after a disruption, compromise, or failure."}],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing system backup","contingency plan","system backup test results","contingency plan test results","contingency plan test documentation","redundant secondary system for system backups","location(s) of redundant secondary backup system(s)"]},{"method":"Interview","objects":["Organizational personnel with contingency planning, recovery, and/or reconstitution responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes implementing system recovery and reconstitution operations","mechanisms supporting and/or implementing system recovery and reconstitution operations"]}]},"CP-10(2)":{"statement":[{"prose":"Implement transaction recovery for systems that are transaction-based."}],"discussion":["Transaction-based systems include database management systems and transaction processing systems. Mechanisms supporting transaction recovery include transaction rollback and transaction journaling."],"params":[],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing system recovery and reconstitution","contingency plan","system design documentation","system configuration settings and associated documentation","contingency plan test documentation","contingency plan test results","system transaction recovery records"]},{"method":"Interview","objects":["Organizational personnel with responsibility for transaction recovery","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing transaction recovery capability"]}]},"CP-10(4)":{"statement":[{"prose":"Provide the capability to restore system components within [Assignment: organization-defined restoration time periods] from configuration-controlled and integrity-protected information representing a known, operational state for the components."}],"discussion":["Restoration of system components includes reimaging, which restores the components to known, operational states."],"params":[{"id":"CP-10(04)_ODP","kind":"Assignment","value":"[Assignment: organization-defined restoration time periods]","guideline":"restoration time period within which to restore system components to a known, operational state is defined"}],"related":["CM-2","CM-6"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing system recovery and reconstitution","contingency plan","system design documentation","system configuration settings and associated documentation","contingency plan test documentation","contingency plan test results","evidence of system recovery and reconstitution operations"]},{"method":"Interview","objects":["Organizational personnel with system recovery and reconstitution responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing the recovery/reconstitution of system information"]}]},"IA-1":{"statement":[{"label":"a.","prose":"Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:","items":[{"label":"1.","prose":"[Selection (one or more): organization-level; mission/business process-level; system-level] identification and authentication policy that:","items":[{"label":"(a)","prose":"Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and"},{"label":"(b)","prose":"Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and"}]},{"label":"2.","prose":"Procedures to facilitate the implementation of the identification and authentication policy and the associated identification and authentication controls;"}]},{"label":"b.","prose":"Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the identification and authentication policy and procedures; and"},{"label":"c.","prose":"Review and update the current identification and authentication:","items":[{"label":"1.","prose":"Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and"},{"label":"2.","prose":"Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]."}]}],"discussion":["Identification and authentication policy and procedures address the controls in the IA family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of identification and authentication policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to identification and authentication policy and procedures include assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure."],"params":[{"id":"IA-1_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]"},{"id":"IA-01_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the identification and authentication policy is to be disseminated are defined"},{"id":"IA-01_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the identification and authentication procedures are to be disseminated is/are defined"},{"id":"IA-01_ODP[03]","kind":"Selection","value":"[Selection (one or more): organization-level; mission/business process-level; system-level]"},{"id":"IA-01_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined official]","guideline":"an official to manage the identification and authentication policy and procedures is defined"},{"id":"IA-01_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current identification and authentication policy is reviewed and updated is defined"},{"id":"IA-01_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require the current identification and authentication policy to be reviewed and updated are defined"},{"id":"IA-01_ODP[07]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current identification and authentication procedures are reviewed and updated is defined"},{"id":"IA-01_ODP[08]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require identification and authentication procedures to be reviewed and updated are defined"}],"related":["AC-1","PM-9","PS-8","SI-12"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"FIPS 201-2","url":"https://doi.org/10.6028/NIST.FIPS.201-2"},{"title":"SP 800-12","url":"https://doi.org/10.6028/NIST.SP.800-12r1"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-39","url":"https://doi.org/10.6028/NIST.SP.800-39"},{"title":"SP 800-63-3","url":"https://doi.org/10.6028/NIST.SP.800-63-3"},{"title":"SP 800-73-4","url":"https://doi.org/10.6028/NIST.SP.800-73-4"},{"title":"SP 800-76-2","url":"https://doi.org/10.6028/NIST.SP.800-76-2"},{"title":"SP 800-78-4","url":"https://doi.org/10.6028/NIST.SP.800-78-4"},{"title":"SP 800-100","url":"https://doi.org/10.6028/NIST.SP.800-100"},{"title":"IR 7874","url":"https://doi.org/10.6028/NIST.IR.7874"}],"objectives":[{"label":"IA-01a.","prose":"","items":[{"label":"IA-01a.[01]","prose":"an identification and authentication policy is developed and documented;"},{"label":"IA-01a.[02]","prose":"the identification and authentication policy is disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"IA-01a.[03]","prose":"identification and authentication procedures to facilitate the implementation of the identification and authentication policy and associated identification and authentication controls are developed and documented;"},{"label":"IA-01a.[04]","prose":"the identification and authentication procedures are disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"IA-01a.01","prose":"","items":[{"label":"IA-01a.01(a)","prose":"","items":[{"label":"IA-01a.01(a)[01]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] identification and authentication policy addresses purpose;"},{"label":"IA-01a.01(a)[02]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] identification and authentication policy addresses scope;"},{"label":"IA-01a.01(a)[03]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] identification and authentication policy addresses roles;"},{"label":"IA-01a.01(a)[04]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] identification and authentication policy addresses responsibilities;"},{"label":"IA-01a.01(a)[05]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] identification and authentication policy addresses management commitment;"},{"label":"IA-01a.01(a)[06]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] identification and authentication policy addresses coordination among organizational entities;"},{"label":"IA-01a.01(a)[07]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] identification and authentication policy addresses compliance;"}]},{"label":"IA-01a.01(b)","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] identification and authentication policy is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines;"}]}]},{"label":"IA-01b.","prose":"the [Assignment: organization-defined official] is designated to manage the development, documentation, and dissemination of the identification and authentication policy and procedures;"},{"label":"IA-01c.","prose":"","items":[{"label":"IA-01c.01","prose":"","items":[{"label":"IA-01c.01[01]","prose":"the current identification and authentication policy is reviewed and updated [Assignment: organization-defined frequency];"},{"label":"IA-01c.01[02]","prose":"the current identification and authentication policy is reviewed and updated following [Assignment: organization-defined events];"}]},{"label":"IA-01c.02","prose":"","items":[{"label":"IA-01c.02[01]","prose":"the current identification and authentication procedures are reviewed and updated [Assignment: organization-defined frequency];"},{"label":"IA-01c.02[02]","prose":"the current identification and authentication procedures are reviewed and updated following [Assignment: organization-defined events]."}]}]}],"methods":[{"method":"Examine","objects":["Identification and authentication policy and procedures","system security plan","privacy plan","risk management strategy documentation","list of events requiring identification and authentication procedures to be reviewed and updated (e.g., audit findings)","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with identification and authentication responsibilities","organizational personnel with information security and privacy responsibilities"]}]},"IA-2":{"statement":[{"prose":"Uniquely identify and authenticate organizational users and associate that unique identification with processes acting on behalf of those users."}],"discussion":["Organizations can satisfy the identification and authentication requirements by complying with the requirements in [HSPD 12](#f16e438e-7114-4144-bfe2-2dfcad8cb2d0). Organizational users include employees or individuals who organizations consider to have an equivalent status to employees (e.g., contractors and guest researchers). Unique identification and authentication of users applies to all accesses other than those that are explicitly identified in [AC-14](#ac-14) and that occur through the authorized use of group authenticators without individual authentication. Since processes execute on behalf of groups and roles, organizations may require unique identification of individuals in group accounts or for detailed accountability of individual activity.","Organizations employ passwords, physical authenticators, or biometrics to authenticate user identities or, in the case of multi-factor authentication, some combination thereof. Access to organizational systems is defined as either local access or network access. Local access is any access to organizational systems by users or processes acting on behalf of users, where access is obtained through direct connections without the use of networks. Network access is access to organizational systems by users (or processes acting on behalf of users) where access is obtained through network connections (i.e., nonlocal accesses). Remote access is a type of network access that involves communication through external networks. Internal networks include local area networks and wide area networks.","The use of encrypted virtual private networks for network connections between organization-controlled endpoints and non-organization-controlled endpoints may be treated as internal networks with respect to protecting the confidentiality and integrity of information traversing the network. Identification and authentication requirements for non-organizational users are described in [IA-8](#ia-8)."],"params":[],"related":["AC-2","AC-3","AC-4","AC-14","AC-17","AC-18","AU-1","AU-6","IA-4","IA-5","IA-8","IA-13","MA-4","MA-5","PE-2","PL-4","SA-4","SA-8"],"references":[{"title":"FIPS 140-3","url":"https://doi.org/10.6028/NIST.FIPS.140-3"},{"title":"FIPS 201-2","url":"https://doi.org/10.6028/NIST.FIPS.201-2"},{"title":"FIPS 202","url":"https://doi.org/10.6028/NIST.FIPS.202"},{"title":"SP 800-63-3","url":"https://doi.org/10.6028/NIST.SP.800-63-3"},{"title":"SP 800-73-4","url":"https://doi.org/10.6028/NIST.SP.800-73-4"},{"title":"SP 800-76-2","url":"https://doi.org/10.6028/NIST.SP.800-76-2"},{"title":"SP 800-78-4","url":"https://doi.org/10.6028/NIST.SP.800-78-4"},{"title":"SP 800-79-2","url":"https://doi.org/10.6028/NIST.SP.800-79-2"},{"title":"SP 800-156","url":"https://doi.org/10.6028/NIST.SP.800-156"},{"title":"SP 800-166","url":"https://doi.org/10.6028/NIST.SP.800-166"},{"title":"IR 7539","url":"https://doi.org/10.6028/NIST.IR.7539"},{"title":"IR 7676","url":"https://doi.org/10.6028/NIST.IR.7676"},{"title":"IR 7817","url":"https://doi.org/10.6028/NIST.IR.7817"},{"title":"IR 7849","url":"https://doi.org/10.6028/NIST.IR.7849"},{"title":"IR 7870","url":"https://doi.org/10.6028/NIST.IR.7870"},{"title":"IR 7874","url":"https://doi.org/10.6028/NIST.IR.7874"},{"title":"IR 7966","url":"https://doi.org/10.6028/NIST.IR.7966"}],"objectives":[{"label":"IA-02[01]","prose":"organizational users are uniquely identified and authenticated;"},{"label":"IA-02[02]","prose":"the unique identification of authenticated organizational users is associated with processes acting on behalf of those users."}],"methods":[{"method":"Examine","objects":["Identification and authentication policy","procedures addressing user identification and authentication","system security plan, system design documentation","system configuration settings and associated documentation","system audit records","list of system accounts","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system operations responsibilities","organizational personnel with information security responsibilities","system/network administrators","organizational personnel with account management responsibilities","system developers"]},{"method":"Test","objects":["Organizational processes for uniquely identifying and authenticating users","mechanisms supporting and/or implementing identification and authentication capabilities"]}]},"IA-2(1)":{"statement":[{"prose":"Implement multi-factor authentication for access to privileged accounts."}],"discussion":["Multi-factor authentication requires the use of two or more different factors to achieve authentication. The authentication factors are defined as follows: something you know (e.g., a personal identification number [PIN]), something you have (e.g., a physical authenticator such as a cryptographic private key), or something you are (e.g., a biometric). Multi-factor authentication solutions that feature physical authenticators include hardware authenticators that provide time-based or challenge-response outputs and smart cards such as the U.S. Government Personal Identity Verification (PIV) card or the Department of Defense (DoD) Common Access Card (CAC). In addition to authenticating users at the system level (i.e., at logon), organizations may employ authentication mechanisms at the application level, at their discretion, to provide increased security. Regardless of the type of access (i.e., local, network, remote), privileged accounts are authenticated using multi-factor options appropriate for the level of risk. Organizations can add additional security measures, such as additional or more rigorous authentication mechanisms, for specific types of access."],"params":[],"related":["AC-5","AC-6"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Identification and authentication policy","procedures addressing user identification and authentication","system security plan","system design documentation","system configuration settings and associated documentation","system audit records","list of system accounts","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system operations responsibilities","organizational personnel with account management responsibilities","organizational personnel with information security responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing a multi-factor authentication capability"]}]},"IA-2(2)":{"statement":[{"prose":"Implement multi-factor authentication for access to non-privileged accounts."}],"discussion":["Multi-factor authentication requires the use of two or more different factors to achieve authentication. The authentication factors are defined as follows: something you know (e.g., a personal identification number [PIN]), something you have (e.g., a physical authenticator such as a cryptographic private key), or something you are (e.g., a biometric). Multi-factor authentication solutions that feature physical authenticators include hardware authenticators that provide time-based or challenge-response outputs and smart cards such as the U.S. Government Personal Identity Verification card or the DoD Common Access Card. In addition to authenticating users at the system level, organizations may also employ authentication mechanisms at the application level, at their discretion, to provide increased information security. Regardless of the type of access (i.e., local, network, remote), non-privileged accounts are authenticated using multi-factor options appropriate for the level of risk. Organizations can provide additional security measures, such as additional or more rigorous authentication mechanisms, for specific types of access."],"params":[],"related":["AC-5"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Identification and authentication policy","system security plan","procedures addressing user identification and authentication","system design documentation","system configuration settings and associated documentation","system audit records","list of system accounts","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system operations responsibilities","organizational personnel with account management responsibilities","organizational personnel with information security responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing a multi-factor authentication capability"]}]},"IA-2(5)":{"statement":[{"prose":"When shared accounts or authenticators are employed, require users to be individually authenticated before granting access to the shared accounts or resources."}],"discussion":["Individual authentication prior to shared group authentication mitigates the risk of using group accounts or authenticators."],"params":[],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Identification and authentication policy","system security plan","procedures addressing user identification and authentication","system design documentation","system configuration settings and associated documentation","system audit records","list of system accounts","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system operations responsibilities","organizational personnel with account management responsibilities","organizational personnel with information security responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing an authentication capability for group accounts"]}]},"IA-2(8)":{"statement":[{"prose":"Implement replay-resistant authentication mechanisms for access to [Selection (one or more): privileged accounts; non-privileged accounts]."}],"discussion":["Authentication processes resist replay attacks if it is impractical to achieve successful authentications by replaying previous authentication messages. Replay-resistant techniques include protocols that use nonces or challenges such as time synchronous or cryptographic authenticators."],"params":[{"id":"IA-02(08)_ODP","kind":"Selection","value":"[Selection (one or more): privileged accounts; non-privileged accounts]"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Identification and authentication policy","system security plan","procedures addressing user identification and authentication","system design documentation","system configuration settings and associated documentation","system audit records","list of privileged system accounts","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system operations responsibilities","organizational personnel with account management responsibilities","organizational personnel with information security responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing identification and authentication capabilities","Mechanisms supporting and/or implementing replay-resistant authentication mechanisms"]}]},"IA-2(12)":{"statement":[{"prose":"Accept and electronically verify Personal Identity Verification-compliant credentials."}],"discussion":["Acceptance of Personal Identity Verification (PIV)-compliant credentials applies to organizations implementing logical access control and physical access control systems. PIV-compliant credentials are those credentials issued by federal agencies that conform to FIPS Publication 201 and supporting guidance documents. The adequacy and reliability of PIV card issuers are authorized using [SP 800-79-2](#10963761-58fc-4b20-b3d6-b44a54daba03). Acceptance of PIV-compliant credentials includes derived PIV credentials, the use of which is addressed in [SP 800-166](#e8552d48-cf41-40aa-8b06-f45f7fb4706c). The DOD Common Access Card (CAC) is an example of a PIV credential."],"params":[],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Identification and authentication policy","system security plan","procedures addressing user identification and authentication","system design documentation","system configuration settings and associated documentation","system audit records","PIV verification records","evidence of PIV credentials"]},{"method":"Interview","objects":["Organizational personnel with system operations responsibilities","organizational personnel with account management responsibilities","organizational personnel with information security responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing acceptance and verification of PIV credentials"]}]},"IA-3":{"statement":[{"prose":"Uniquely identify and authenticate [Assignment: organization-defined devices and/or types of devices] before establishing a [Selection (one or more): local; remote; network] connection."}],"discussion":["Devices that require unique device-to-device identification and authentication are defined by type, device, or a combination of type and device. Organization-defined device types include devices that are not owned by the organization. Systems use shared known information (e.g., Media Access Control [MAC], Transmission Control Protocol/Internet Protocol [TCP/IP] addresses) for device identification or organizational authentication solutions (e.g., Institute of Electrical and Electronics Engineers (IEEE) 802.1x and Extensible Authentication Protocol [EAP], RADIUS server with EAP-Transport Layer Security [TLS] authentication, Kerberos) to identify and authenticate devices on local and wide area networks. Organizations determine the required strength of authentication mechanisms based on the security categories of systems and mission or business requirements. Because of the challenges of implementing device authentication on a large scale, organizations can restrict the application of the control to a limited number/type of devices based on mission or business needs."],"params":[{"id":"IA-03_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined devices and/or types of devices]","guideline":"devices and/or types of devices to be uniquely identified and authenticated before establishing a connection are defined"},{"id":"IA-03_ODP[02]","kind":"Selection","value":"[Selection (one or more): local; remote; network]"}],"related":["AC-17","AC-18","AC-19","AU-6","CA-3","CA-9","IA-4","IA-5","IA-9","IA-11","IA-13","SI-4"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Identification and authentication policy","system security plan","procedures addressing device identification and authentication","system design documentation","list of devices requiring unique identification and authentication","device connection reports","system configuration settings and associated documentation","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with operational responsibilities for device identification and authentication","organizational personnel with information security responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing device identification and authentication capabilities"]}]},"IA-4":{"statement":[{"prose":"Manage system identifiers by:"},{"label":"a.","prose":"Receiving authorization from [Assignment: organization-defined personnel or roles] to assign an individual, group, role, service, or device identifier;"},{"label":"b.","prose":"Selecting an identifier that identifies an individual, group, role, service, or device;"},{"label":"c.","prose":"Assigning the identifier to the intended individual, group, role, service, or device; and"},{"label":"d.","prose":"Preventing reuse of identifiers for [Assignment: organization-defined time period]."}],"discussion":["Common device identifiers include Media Access Control (MAC) addresses, Internet Protocol (IP) addresses, or device-unique token identifiers. The management of individual identifiers is not applicable to shared system accounts. Typically, individual identifiers are the usernames of the system accounts assigned to those individuals. In such instances, the account management activities of [AC-2](#ac-2) use account names provided by [IA-4](#ia-4). Identifier management also addresses individual identifiers not necessarily associated with system accounts. Preventing the reuse of identifiers implies preventing the assignment of previously used individual, group, role, service, or device identifiers to different individuals, groups, roles, services, or devices."],"params":[{"id":"IA-04_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles from whom authorization must be received to assign an identifier are defined"},{"id":"IA-04_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"a time period for preventing reuse of identifiers is defined"}],"related":["AC-5","IA-2","IA-3","IA-5","IA-8","IA-9","IA-12","MA-4","PE-2","PE-3","PE-4","PL-4","PM-12","PS-3","PS-4","PS-5","SC-37"],"references":[{"title":"FIPS 201-2","url":"https://doi.org/10.6028/NIST.FIPS.201-2"},{"title":"SP 800-63-3","url":"https://doi.org/10.6028/NIST.SP.800-63-3"},{"title":"SP 800-73-4","url":"https://doi.org/10.6028/NIST.SP.800-73-4"},{"title":"SP 800-76-2","url":"https://doi.org/10.6028/NIST.SP.800-76-2"},{"title":"SP 800-78-4","url":"https://doi.org/10.6028/NIST.SP.800-78-4"}],"objectives":[{"label":"IA-04a.","prose":"system identifiers are managed by receiving authorization from [Assignment: organization-defined personnel or roles] to assign to an individual, group, role, or device identifier;"},{"label":"IA-04b.","prose":"system identifiers are managed by selecting an identifier that identifies an individual, group, role, service, or device;"},{"label":"IA-04c.","prose":"system identifiers are managed by assigning the identifier to the intended individual, group, role, service, or device;"},{"label":"IA-04d.","prose":"system identifiers are managed by preventing reuse of identifiers for [Assignment: organization-defined time period]."}],"methods":[{"method":"Examine","objects":["Identification and authentication policy","procedures addressing identifier management","procedures addressing account management","system security plan","system design documentation","system configuration settings and associated documentation","list of system accounts","list of identifiers generated from physical access control devices"]},{"method":"Interview","objects":["Organizational personnel with identifier management responsibilities","organizational personnel with information security responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing identifier management"]}]},"IA-4(4)":{"statement":[{"prose":"Manage individual identifiers by uniquely identifying each individual as [Assignment: organization-defined characteristics]."}],"discussion":["Characteristics that identify the status of individuals include contractors, foreign nationals, and non-organizational users. Identifying the status of individuals by these characteristics provides additional information about the people with whom organizational personnel are communicating. For example, it might be useful for a government employee to know that one of the individuals on an email message is a contractor."],"params":[{"id":"IA-04(04)_ODP","kind":"Assignment","value":"[Assignment: organization-defined characteristics]","guideline":"characteristics used to identify individual status is defined"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Identification and authentication policy","system security plan","procedures addressing identifier management","procedures addressing account management","list of characteristics identifying individual status","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with identifier management responsibilities","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing identifier management"]}]},"IA-5":{"statement":[{"prose":"Manage system authenticators by:"},{"label":"a.","prose":"Verifying, as part of the initial authenticator distribution, the identity of the individual, group, role, service, or device receiving the authenticator;"},{"label":"b.","prose":"Establishing initial authenticator content for any authenticators issued by the organization;"},{"label":"c.","prose":"Ensuring that authenticators have sufficient strength of mechanism for their intended use;"},{"label":"d.","prose":"Establishing and implementing administrative procedures for initial authenticator distribution, for lost or compromised or damaged authenticators, and for revoking authenticators;"},{"label":"e.","prose":"Changing default authenticators prior to first use;"},{"label":"f.","prose":"Changing or refreshing authenticators [Assignment: organization-defined time period by authenticator type] or when [Assignment: organization-defined events] occur;"},{"label":"g.","prose":"Protecting authenticator content from unauthorized disclosure and modification;"},{"label":"h.","prose":"Requiring individuals to take, and having devices implement, specific controls to protect authenticators; and"},{"label":"i.","prose":"Changing authenticators for group or role accounts when membership to those accounts changes."}],"discussion":["Authenticators include passwords, cryptographic devices, biometrics, certificates, one-time password devices, and ID badges. Device authenticators include certificates and passwords. Initial authenticator content is the actual content of the authenticator (e.g., the initial password). In contrast, the requirements for authenticator content contain specific criteria or characteristics (e.g., minimum password length). Developers may deliver system components with factory default authentication credentials (i.e., passwords) to allow for initial installation and configuration. Default authentication credentials are often well known, easily discoverable, and present a significant risk. The requirement to protect individual authenticators may be implemented via control [PL-4](#pl-4) or [PS-6](#ps-6) for authenticators in the possession of individuals and by controls [AC-3](#ac-3), [AC-6](#ac-6), and [SC-28](#sc-28) for authenticators stored in organizational systems, including passwords stored in hashed or encrypted formats or files containing encrypted or hashed passwords accessible with administrator privileges.","Systems support authenticator management by organization-defined settings and restrictions for various authenticator characteristics (e.g., minimum password length, validation time window for time synchronous one-time tokens, and number of allowed rejections during the verification stage of biometric authentication). Actions can be taken to safeguard individual authenticators, including maintaining possession of authenticators, not sharing authenticators with others, and immediately reporting lost, stolen, or compromised authenticators. Authenticator management includes issuing and revoking authenticators for temporary access when no longer needed."],"params":[{"id":"IA-05_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined time period by authenticator type]","guideline":"a time period for changing or refreshing authenticators by authenticator type is defined"},{"id":"IA-05_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that trigger the change or refreshment of authenticators are defined"}],"related":["AC-3","AC-6","CM-6","IA-2","IA-4","IA-7","IA-8","IA-9","MA-4","PE-2","PL-4","SC-12","SC-13"],"references":[{"title":"FIPS 140-3","url":"https://doi.org/10.6028/NIST.FIPS.140-3"},{"title":"FIPS 180-4","url":"https://doi.org/10.6028/NIST.FIPS.180-4"},{"title":"FIPS 201-2","url":"https://doi.org/10.6028/NIST.FIPS.201-2"},{"title":"FIPS 202","url":"https://doi.org/10.6028/NIST.FIPS.202"},{"title":"SP 800-63-3","url":"https://doi.org/10.6028/NIST.SP.800-63-3"},{"title":"SP 800-73-4","url":"https://doi.org/10.6028/NIST.SP.800-73-4"},{"title":"SP 800-76-2","url":"https://doi.org/10.6028/NIST.SP.800-76-2"},{"title":"SP 800-78-4","url":"https://doi.org/10.6028/NIST.SP.800-78-4"},{"title":"IR 7539","url":"https://doi.org/10.6028/NIST.IR.7539"},{"title":"IR 7817","url":"https://doi.org/10.6028/NIST.IR.7817"},{"title":"IR 7849","url":"https://doi.org/10.6028/NIST.IR.7849"},{"title":"IR 7870","url":"https://doi.org/10.6028/NIST.IR.7870"},{"title":"IR 8040","url":"https://doi.org/10.6028/NIST.IR.8040"}],"objectives":[{"label":"IA-05a.","prose":"system authenticators are managed through the verification of the identity of the individual, group, role, service, or device receiving the authenticator as part of the initial authenticator distribution;"},{"label":"IA-05b.","prose":"system authenticators are managed through the establishment of initial authenticator content for any authenticators issued by the organization;"},{"label":"IA-05c.","prose":"system authenticators are managed to ensure that authenticators have sufficient strength of mechanism for their intended use;"},{"label":"IA-05d.","prose":"system authenticators are managed through the establishment and implementation of administrative procedures for initial authenticator distribution; lost, compromised, or damaged authenticators; and the revocation of authenticators;"},{"label":"IA-05e.","prose":"system authenticators are managed through the change of default authenticators prior to first use;"},{"label":"IA-05f.","prose":"system authenticators are managed through the change or refreshment of authenticators [Assignment: organization-defined time period by authenticator type] or when [Assignment: organization-defined events] occur;"},{"label":"IA-05g.","prose":"system authenticators are managed through the protection of authenticator content from unauthorized disclosure and modification;"},{"label":"IA-05h.","prose":"","items":[{"label":"IA-05h.[01]","prose":"system authenticators are managed through the requirement for individuals to take specific controls to protect authenticators;"},{"label":"IA-05h.[02]","prose":"system authenticators are managed through the requirement for devices to implement specific controls to protect authenticators;"}]},{"label":"IA-05i.","prose":"system authenticators are managed through the change of authenticators for group or role accounts when membership to those accounts changes."}],"methods":[{"method":"Examine","objects":["Identification and authentication policy","system security plan","addressing authenticator management","system design documentation","system configuration settings and associated documentation","list of system authenticator types","change control records associated with managing system authenticators","system audit records"]},{"method":"Interview","objects":["Organizational personnel with authenticator management responsibilities","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing authenticator management capability"]}]},"IA-5(1)":{"statement":[{"prose":"For password-based authentication:"},{"label":"(a)","prose":"Maintain a list of commonly-used, expected, or compromised passwords and update the list [Assignment: organization-defined frequency] and when organizational passwords are suspected to have been compromised directly or indirectly;"},{"label":"(b)","prose":"Verify, when users create or update passwords, that the passwords are not found on the list of commonly-used, expected, or compromised passwords in IA-5(1)(a);"},{"label":"(c)","prose":"Transmit passwords only over cryptographically-protected channels;"},{"label":"(d)","prose":"Store passwords using an approved salted key derivation function, preferably using a keyed hash;"},{"label":"(e)","prose":"Require immediate selection of a new password upon account recovery;"},{"label":"(f)","prose":"Allow user selection of long passwords and passphrases, including spaces and all printable characters;"},{"label":"(g)","prose":"Employ automated tools to assist the user in selecting strong password authenticators; and"},{"label":"(h)","prose":"Enforce the following composition and complexity rules: [Assignment: organization-defined composition and complexity rules]."}],"discussion":["Password-based authentication applies to passwords regardless of whether they are used in single-factor or multi-factor authentication. Long passwords or passphrases are preferable over shorter passwords. Enforced composition rules provide marginal security benefits while decreasing usability. However, organizations may choose to establish certain rules for password generation (e.g., minimum character length for long passwords) under certain circumstances and can enforce this requirement in IA-5(1)(h). Account recovery can occur, for example, in situations when a password is forgotten. Cryptographically protected passwords include salted one-way cryptographic hashes of passwords. The list of commonly used, compromised, or expected passwords includes passwords obtained from previous breach corpuses, dictionary words, and repetitive or sequential characters. The list includes context-specific words, such as the name of the service, username, and derivatives thereof."],"params":[{"id":"IA-05(01)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to update the list of commonly used, expected, or compromised passwords is defined"},{"id":"IA-05(01)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined composition and complexity rules]","guideline":"authenticator composition and complexity rules are defined"}],"related":["IA-6"],"references":[],"objectives":[{"label":"IA-05(01)(a)","prose":"for password-based authentication, a list of commonly used, expected, or compromised passwords is maintained and updated [Assignment: organization-defined frequency] and when organizational passwords are suspected to have been compromised directly or indirectly;"},{"label":"IA-05(01)(b)","prose":"for password-based authentication when passwords are created or updated by users, the passwords are verified not to be found on the list of commonly used, expected, or compromised passwords in IA-05(01)(a);"},{"label":"IA-05(01)(c)","prose":"for password-based authentication, passwords are only transmitted over cryptographically protected channels;"},{"label":"IA-05(01)(d)","prose":"for password-based authentication, passwords are stored using an approved salted key derivation function, preferably using a keyed hash;"},{"label":"IA-05(01)(e)","prose":"for password-based authentication, immediate selection of a new password is required upon account recovery;"},{"label":"IA-05(01)(f)","prose":"for password-based authentication, user selection of long passwords and passphrases is allowed, including spaces and all printable characters;"},{"label":"IA-05(01)(g)","prose":"for password-based authentication, automated tools are employed to assist the user in selecting strong password authenticators;"},{"label":"IA-05(01)(h)","prose":"for password-based authentication, [Assignment: organization-defined composition and complexity rules] are enforced."}],"methods":[{"method":"Examine","objects":["Identification and authentication policy","password policy","procedures addressing authenticator management","system security plan","system design documentation","system configuration settings and associated documentation","password configurations and associated documentation","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with authenticator management responsibilities","organizational personnel with information security responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing password-based authenticator management capability"]}]},"IA-5(2)":{"statement":[{"label":"(a)","prose":"For public key-based authentication:","items":[{"label":"(1)","prose":"Enforce authorized access to the corresponding private key; and"},{"label":"(2)","prose":"Map the authenticated identity to the account of the individual or group; and"}]},{"label":"(b)","prose":"When public key infrastructure (PKI) is used:","items":[{"label":"(1)","prose":"Validate certificates by constructing and verifying a certification path to an accepted trust anchor, including checking certificate status information; and"},{"label":"(2)","prose":"Implement a local cache of revocation data to support path discovery and validation."}]}],"discussion":["Public key cryptography is a valid authentication mechanism for individuals, machines, and devices. For PKI solutions, status information for certification paths includes certificate revocation lists or certificate status protocol responses. For PIV cards, certificate validation involves the construction and verification of a certification path to the Common Policy Root trust anchor, which includes certificate policy processing. Implementing a local cache of revocation data to support path discovery and validation also supports system availability in situations where organizations are unable to access revocation information via the network."],"params":[],"related":["IA-3","SC-17"],"references":[],"objectives":[{"label":"IA-05(02)(a)","prose":"","items":[{"label":"IA-05(02)(a)(01)","prose":"authorized access to the corresponding private key is enforced for public key-based authentication;"},{"label":"IA-05(02)(a)(02)","prose":"the authenticated identity is mapped to the account of the individual or group for public key-based authentication;"}]},{"label":"IA-05(02)(b)","prose":"","items":[{"label":"IA-05(02)(b)(01)","prose":"when public key infrastructure (PKI) is used, certificates are validated by constructing and verifying a certification path to an accepted trust anchor, including checking certificate status information;"},{"label":"IA-05(02)(b)(02)","prose":"when public key infrastructure (PKI) is used, a local cache of revocation data is implemented to support path discovery and validation."}]}],"methods":[{"method":"Examine","objects":["Identification and authentication policy","procedures addressing authenticator management","system security plan","system design documentation","system configuration settings and associated documentation","PKI certification validation records","PKI certification revocation lists","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with PKI-based, authenticator management responsibilities","organizational personnel with information security responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing PKI-based, authenticator management capability"]}]},"IA-5(6)":{"statement":[{"prose":"Protect authenticators commensurate with the security category of the information to which use of the authenticator permits access."}],"discussion":["For systems that contain multiple security categories of information without reliable physical or logical separation between categories, authenticators used to grant access to the systems are protected commensurate with the highest security category of information on the systems. Security categories of information are determined as part of the security categorization process."],"params":[],"related":["RA-2"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Identification and authentication policy","procedures addressing authenticator management","security categorization documentation for the system","security assessments of authenticator protections","risk assessment results","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with authenticator management responsibilities","organizational personnel implementing and/or maintaining authenticator protections","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing authenticator management capability","mechanisms protecting authenticators"]}]},"IA-6":{"statement":[{"prose":"Obscure feedback of authentication information during the authentication process to protect the information from possible exploitation and use by unauthorized individuals."}],"discussion":["Authentication feedback from systems does not provide information that would allow unauthorized individuals to compromise authentication mechanisms. For some types of systems, such as desktops or notebooks with relatively large monitors, the threat (referred to as shoulder surfing) may be significant. For other types of systems, such as mobile devices with small displays, the threat may be less significant and is balanced against the increased likelihood of typographic input errors due to small keyboards. Thus, the means for obscuring authentication feedback is selected accordingly. Obscuring authentication feedback includes displaying asterisks when users type passwords into input devices or displaying feedback for a very limited time before obscuring it."],"params":[],"related":["AC-3"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Identification and authentication policy","system security plan","procedures addressing authenticator feedback","system design documentation","system configuration settings and associated documentation","system audit records","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with information security responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing the obscuring of feedback of authentication information during authentication"]}]},"IA-7":{"statement":[{"prose":"Implement mechanisms for authentication to a cryptographic module that meet the requirements of applicable laws, executive orders, directives, policies, regulations, standards, and guidelines for such authentication."}],"discussion":["Authentication mechanisms may be required within a cryptographic module to authenticate an operator accessing the module and to verify that the operator is authorized to assume the requested role and perform services within that role."],"params":[],"related":["AC-3","IA-5","SA-4","SC-12","SC-13"],"references":[{"title":"FIPS 140-3","url":"https://doi.org/10.6028/NIST.FIPS.140-3"}],"objectives":[],"methods":[{"method":"Examine","objects":["Identification and authentication policy","system security plan","procedures addressing cryptographic module authentication","system design documentation","system configuration settings and associated documentation","system audit records","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with responsibility for cryptographic module authentication","organizational personnel with information security responsibilities","system/network administrators","system developers"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing cryptographic module authentication"]}]},"IA-8":{"statement":[{"prose":"Uniquely identify and authenticate non-organizational users or processes acting on behalf of non-organizational users."}],"discussion":["Non-organizational users include system users other than organizational users explicitly covered by [IA-2](#ia-2). Non-organizational users are uniquely identified and authenticated for accesses other than those explicitly identified and documented in [AC-14](#ac-14). Identification and authentication of non-organizational users accessing federal systems may be required to protect federal, proprietary, or privacy-related information (with exceptions noted for national security systems). Organizations consider many factors—including security, privacy, scalability, and practicality—when balancing the need to ensure ease of use for access to federal information and systems with the need to protect and adequately mitigate risk."],"params":[],"related":["AC-2","AC-6","AC-14","AC-17","AC-18","AU-6","IA-2","IA-4","IA-5","IA-10","IA-11","IA-13","MA-4","RA-3","SA-4","SC-8"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"FED PKI","url":"https://www.idmanagement.gov/topics/fpki"},{"title":"FIPS 201-2","url":"https://doi.org/10.6028/NIST.FIPS.201-2"},{"title":"SP 800-63-3","url":"https://doi.org/10.6028/NIST.SP.800-63-3"},{"title":"SP 800-79-2","url":"https://doi.org/10.6028/NIST.SP.800-79-2"},{"title":"SP 800-116","url":"https://doi.org/10.6028/NIST.SP.800-116r1"},{"title":"IR 8062","url":"https://doi.org/10.6028/NIST.IR.8062"}],"objectives":[],"methods":[{"method":"Examine","objects":["Identification and authentication policy","system security plan","privacy plan","procedures addressing user identification and authentication","system design documentation","system configuration settings and associated documentation","system audit records","list of system accounts"]},{"method":"Interview","objects":["Organizational personnel with system operations responsibilities","organizational personnel with information security and privacy responsibilities","system/network administrators","organizational personnel with account management responsibilities"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing identification and authentication capabilities"]}]},"IA-8(1)":{"statement":[{"prose":"Accept and electronically verify Personal Identity Verification-compliant credentials from other federal agencies."}],"discussion":["Acceptance of Personal Identity Verification (PIV) credentials from other federal agencies applies to both logical and physical access control systems. PIV credentials are those credentials issued by federal agencies that conform to FIPS Publication 201 and supporting guidelines. The adequacy and reliability of PIV card issuers are addressed and authorized using [SP 800-79-2](#10963761-58fc-4b20-b3d6-b44a54daba03)."],"params":[],"related":["PE-3"],"references":[],"objectives":[{"label":"IA-08(01)[01]","prose":"Personal Identity Verification-compliant credentials from other federal agencies are accepted;"},{"label":"IA-08(01)[02]","prose":"Personal Identity Verification-compliant credentials from other federal agencies are electronically verified."}],"methods":[{"method":"Examine","objects":["Identification and authentication policy","system security plan","procedures addressing user identification and authentication","system design documentation","system configuration settings and associated documentation","system audit records","PIV verification records","evidence of PIV credentials"]},{"method":"Interview","objects":["Organizational personnel with system operations responsibilities","organizational personnel with information security responsibilities","system/network administrators","system developers","organizational personnel with account management responsibilities"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing identification and authentication capabilities","mechanisms that accept and verify PIV credentials"]}]},"IA-8(2)":{"statement":[{"label":"(a)","prose":"Accept only external authenticators that are NIST-compliant; and"},{"label":"(b)","prose":"Document and maintain a list of accepted external authenticators."}],"discussion":["Acceptance of only NIST-compliant external authenticators applies to organizational systems that are accessible to the public (e.g., public-facing websites). External authenticators are issued by nonfederal government entities and are compliant with [SP 800-63B](#e59c5a7c-8b1f-49ca-8de0-6ee0882180ce). Approved external authenticators meet or exceed the minimum Federal Government-wide technical, security, privacy, and organizational maturity requirements. Meeting or exceeding Federal requirements allows Federal Government relying parties to trust external authenticators in connection with an authentication transaction at a specified authenticator assurance level."],"params":[],"related":[],"references":[],"objectives":[{"label":"IA-08(02)(a)","prose":"only external authenticators that are NIST-compliant are accepted;"},{"label":"IA-08(02)(b)","prose":"","items":[{"label":"IA-08(02)(b)[01]","prose":"a list of accepted external authenticators is documented;"},{"label":"IA-08(02)(b)[02]","prose":"a list of accepted external authenticators is maintained."}]}],"methods":[{"method":"Examine","objects":["Identification and authentication policy","system security plan","procedures addressing user identification and authentication","system design documentation","system configuration settings and associated documentation","system audit records","list of third-party credentialing products, components, or services procured and implemented by organization","third-party credential verification records"]},{"method":"Interview","objects":["Organizational personnel with system operations responsibilities","organizational personnel with information security responsibilities","system/network administrators","system developers","organizational personnel with account management responsibilities"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing identification and authentication capabilities","mechanisms that accept external credentials"]}]},"IA-8(4)":{"statement":[{"prose":"Conform to the following profiles for identity management [Assignment: organization-defined identity management profiles]."}],"discussion":["Organizations define profiles for identity management based on open identity management standards. To ensure that open identity management standards are viable, robust, reliable, sustainable, and interoperable as documented, the Federal Government assesses and scopes the standards and technology implementations against applicable laws, executive orders, directives, policies, regulations, standards, and guidelines."],"params":[{"id":"IA-08(04)_ODP","kind":"Assignment","value":"[Assignment: organization-defined identity management profiles]","guideline":"identity management profiles are defined"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Identification and authentication policy","system security plan","system design documentation","system configuration settings and associated documentation","system audit records","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system operations responsibilities","organizational personnel with information security responsibilities","system/network administrators","system developers","organizational personnel with account management responsibilities"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing identification and authentication capabilities","mechanisms supporting and/or implementing conformance with profiles"]}]},"IA-11":{"statement":[{"prose":"Require users to re-authenticate when [Assignment: organization-defined circumstances or situations]."}],"discussion":["In addition to the re-authentication requirements associated with device locks, organizations may require re-authentication of individuals in certain situations, including when roles, authenticators or credentials change, when security categories of systems change, when the execution of privileged functions occurs, after a fixed time period, or periodically."],"params":[{"id":"IA-11_ODP","kind":"Assignment","value":"[Assignment: organization-defined circumstances or situations]","guideline":"circumstances or situations requiring re-authentication are defined"}],"related":["AC-3","AC-11","IA-2","IA-3","IA-4","IA-8"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Identification and authentication policy","procedures addressing user and device re-authentication","system security plan","system design documentation","system configuration settings and associated documentation","list of circumstances or situations requiring re-authentication","system audit records","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system operations responsibilities","organizational personnel with information security responsibilities","system/network administrators","system developers","organizational personnel with identification and authentication responsibilities"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing identification and authentication capabilities"]}]},"IA-12":{"statement":[{"label":"a.","prose":"Identity proof users that require accounts for logical access to systems based on appropriate identity assurance level requirements as specified in applicable standards and guidelines;"},{"label":"b.","prose":"Resolve user identities to a unique individual; and"},{"label":"c.","prose":"Collect, validate, and verify identity evidence."}],"discussion":["Identity proofing is the process of collecting, validating, and verifying a user’s identity information for the purposes of establishing credentials for accessing a system. Identity proofing is intended to mitigate threats to the registration of users and the establishment of their accounts. Standards and guidelines specifying identity assurance levels for identity proofing include [SP 800-63-3](#737513fa-6758-403f-831d-5ddab5e23cb3) and [SP 800-63A](#9099ed2c-922a-493d-bcb4-d896192243ff). Organizations may be subject to laws, executive orders, directives, regulations, or policies that address the collection of identity evidence. Organizational personnel consult with the senior agency official for privacy and legal counsel regarding such requirements."],"params":[],"related":["AC-5","IA-1","IA-2","IA-3","IA-4","IA-5","IA-6","IA-8","IA-13"],"references":[{"title":"FIPS 201-2","url":"https://doi.org/10.6028/NIST.FIPS.201-2"},{"title":"SP 800-63-3","url":"https://doi.org/10.6028/NIST.SP.800-63-3"},{"title":"SP 800-63A","url":"https://doi.org/10.6028/NIST.SP.800-63a"},{"title":"SP 800-79-2","url":"https://doi.org/10.6028/NIST.SP.800-79-2"}],"objectives":[{"label":"IA-12a.","prose":"users who require accounts for logical access to systems based on appropriate identity assurance level requirements as specified in applicable standards and guidelines are identity proofed;"},{"label":"IA-12b.","prose":"user identities are resolved to a unique individual;"},{"label":"IA-12c.","prose":"","items":[{"label":"IA-12c.[01]","prose":"identity evidence is collected;"},{"label":"IA-12c.[02]","prose":"identity evidence is validated;"},{"label":"IA-12c.[03]","prose":"identity evidence is verified."}]}],"methods":[{"method":"Examine","objects":["Identification and authentication policy","procedures addressing identity proofing","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system operations responsibilities","organizational personnel with information security and privacy responsibilities","legal counsel","system/network administrators","system developers","organizational personnel with identification and authentication responsibilities"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing identification and authentication capabilities"]}]},"IA-12(2)":{"statement":[{"prose":"Require evidence of individual identification be presented to the registration authority."}],"discussion":["Identity evidence, such as documentary evidence or a combination of documents and biometrics, reduces the likelihood of individuals using fraudulent identification to establish an identity or at least increases the work factor of potential adversaries. The forms of acceptable evidence are consistent with the risks to the systems, roles, and privileges associated with the user’s account."],"params":[],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Identification and authentication policy","procedures addressing identity proofing","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system operations responsibilities","organizational personnel with information security responsibilities","system/network administrators","system developers","organizational personnel with identification and authentication responsibilities"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing identification and authentication capabilities"]}]},"IA-12(3)":{"statement":[{"prose":"Require that the presented identity evidence be validated and verified through [Assignment: organization-defined methods of validation and verification]."}],"discussion":["Validation and verification of identity evidence increases the assurance that accounts and identifiers are being established for the correct user and authenticators are being bound to that user. Validation refers to the process of confirming that the evidence is genuine and authentic, and the data contained in the evidence is correct, current, and related to an individual. Verification confirms and establishes a linkage between the claimed identity and the actual existence of the user presenting the evidence. Acceptable methods for validating and verifying identity evidence are consistent with the risks to the systems, roles, and privileges associated with the users account."],"params":[{"id":"IA-12(03)_ODP","kind":"Assignment","value":"[Assignment: organization-defined methods of validation and verification]","guideline":"methods of validation and verification of identity evidence are defined"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Identification and authentication policy","procedures addressing identity proofing","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system operations responsibilities","organizational personnel with information security responsibilities","system/network administrators","system developers","organizational personnel with identification and authentication responsibilities"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing identification and authentication capabilities"]}]},"IA-12(4)":{"statement":[{"prose":"Require that the validation and verification of identity evidence be conducted in person before a designated registration authority."}],"discussion":["In-person proofing reduces the likelihood of fraudulent credentials being issued because it requires the physical presence of individuals, the presentation of physical identity documents, and actual face-to-face interactions with designated registration authorities."],"params":[],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Identification and authentication policy","procedures addressing identity proofing","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system operations responsibilities","organizational personnel with information security responsibilities","system/network administrators","system developers","organizational personnel with identification and authentication responsibilities"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing identification and authentication capabilities"]}]},"IA-12(5)":{"statement":[{"prose":"Require that a [Selection: registration code; notice of proofing] be delivered through an out-of-band channel to verify the users address (physical or digital) of record."}],"discussion":["To make it more difficult for adversaries to pose as legitimate users during the identity proofing process, organizations can use out-of-band methods to ensure that the individual associated with an address of record is the same individual that participated in the registration. Confirmation can take the form of a temporary enrollment code or a notice of proofing. The delivery address for these artifacts is obtained from records and not self-asserted by the user. The address can include a physical or digital address. A home address is an example of a physical address. Email addresses and telephone numbers are examples of digital addresses."],"params":[{"id":"IA-12(05)_ODP","kind":"Selection","value":"[Selection: registration code; notice of proofing]"}],"related":["IA-12"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Identification and authentication policy","procedures addressing identity proofing","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system operations responsibilities","organizational personnel with information security responsibilities","system/network administrators","system developers","organizational personnel with identification and authentication responsibilities"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing identification and authentication capabilities"]}]},"IR-1":{"statement":[{"label":"a.","prose":"Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:","items":[{"label":"1.","prose":"[Selection (one or more): organization-level; mission/business process-level; system-level] incident response policy that:","items":[{"label":"(a)","prose":"Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and"},{"label":"(b)","prose":"Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and"}]},{"label":"2.","prose":"Procedures to facilitate the implementation of the incident response policy and the associated incident response controls;"}]},{"label":"b.","prose":"Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the incident response policy and procedures; and"},{"label":"c.","prose":"Review and update the current incident response:","items":[{"label":"1.","prose":"Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and"},{"label":"2.","prose":"Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]."}]}],"discussion":["Incident response policy and procedures address the controls in the IR family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of incident response policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to incident response policy and procedures include assessment or audit findings, security incidents or breaches, or changes in laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure."],"params":[{"id":"IR-1_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]"},{"id":"IR-01_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the incident response policy is to be disseminated is/are defined"},{"id":"IR-01_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the incident response procedures are to be disseminated is/are defined"},{"id":"IR-01_ODP[03]","kind":"Selection","value":"[Selection (one or more): organization-level; mission/business process-level; system-level]"},{"id":"IR-01_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined official]","guideline":"an official to manage the incident response policy and procedures is defined"},{"id":"IR-01_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current incident response policy is reviewed and updated is defined"},{"id":"IR-01_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require the current incident response policy to be reviewed and updated are defined"},{"id":"IR-01_ODP[07]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current incident response procedures are reviewed and updated is defined"},{"id":"IR-01_ODP[08]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require the incident response procedures to be reviewed and updated are defined"}],"related":["PM-9","PS-8","SI-12"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-12","url":"https://doi.org/10.6028/NIST.SP.800-12r1"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-39","url":"https://doi.org/10.6028/NIST.SP.800-39"},{"title":"SP 800-50","url":"https://doi.org/10.6028/NIST.SP.800-50"},{"title":"SP 800-61","url":"https://doi.org/10.6028/NIST.SP.800-61r2"},{"title":"SP 800-83","url":"https://doi.org/10.6028/NIST.SP.800-83r1"},{"title":"SP 800-100","url":"https://doi.org/10.6028/NIST.SP.800-100"}],"objectives":[{"label":"IR-01a.","prose":"","items":[{"label":"IR-01a.[01]","prose":"an incident response policy is developed and documented;"},{"label":"IR-01a.[02]","prose":"the incident response policy is disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"IR-01a.[03]","prose":"incident response procedures to facilitate the implementation of the incident response policy and associated incident response controls are developed and documented;"},{"label":"IR-01a.[04]","prose":"the incident response procedures are disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"IR-01a.01","prose":"","items":[{"label":"IR-01a.01(a)","prose":"","items":[{"label":"IR-01a.01(a)[01]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] incident response policy addresses purpose;"},{"label":"IR-01a.01(a)[02]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] incident response policy addresses scope;"},{"label":"IR-01a.01(a)[03]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] incident response policy addresses roles;"},{"label":"IR-01a.01(a)[04]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] incident response policy addresses responsibilities;"},{"label":"IR-01a.01(a)[05]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] incident response policy addresses management commitment;"},{"label":"IR-01a.01(a)[06]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] incident response policy addresses coordination among organizational entities;"},{"label":"IR-01a.01(a)[07]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] incident response policy addresses compliance;"}]},{"label":"IR-01a.01(b)","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] incident response policy is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines;"}]}]},{"label":"IR-01b.","prose":"the [Assignment: organization-defined official] is designated to manage the development, documentation, and dissemination of the incident response policy and procedures;"},{"label":"IR-01c.","prose":"","items":[{"label":"IR-01c.01","prose":"","items":[{"label":"IR-01c.01[01]","prose":"the current incident response policy is reviewed and updated [Assignment: organization-defined frequency];"},{"label":"IR-01c.01[02]","prose":"the current incident response policy is reviewed and updated following [Assignment: organization-defined events];"}]},{"label":"IR-01c.02","prose":"","items":[{"label":"IR-01c.02[01]","prose":"the current incident response procedures are reviewed and updated [Assignment: organization-defined frequency];"},{"label":"IR-01c.02[02]","prose":"the current incident response procedures are reviewed and updated following [Assignment: organization-defined events]."}]}]}],"methods":[{"method":"Examine","objects":["Incident response policy and procedures","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with incident response responsibilities","organizational personnel with information security and privacy responsibilities"]}]},"IR-2":{"statement":[{"label":"a.","prose":"Provide incident response training to system users consistent with assigned roles and responsibilities:","items":[{"label":"1.","prose":"Within [Assignment: organization-defined time period] of assuming an incident response role or responsibility or acquiring system access;"},{"label":"2.","prose":"When required by system changes; and"},{"label":"3.","prose":"[Assignment: organization-defined frequency] thereafter; and"}]},{"label":"b.","prose":"Review and update incident response training content [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]."}],"discussion":["Incident response training is associated with the assigned roles and responsibilities of organizational personnel to ensure that the appropriate content and level of detail are included in such training. For example, users may only need to know who to call or how to recognize an incident; system administrators may require additional training on how to handle incidents; and incident responders may receive more specific training on forensics, data collection techniques, reporting, system recovery, and system restoration. Incident response training includes user training in identifying and reporting suspicious activities from external and internal sources. Incident response training for users may be provided as part of [AT-2](#at-2) or [AT-3](#at-3). Events that may precipitate an update to incident response training content include, but are not limited to, incident response plan testing or response to an actual incident (lessons learned), assessment or audit findings, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines."],"params":[{"id":"IR-02_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"a time period within which incident response training is to be provided to system users assuming an incident response role or responsibility is defined"},{"id":"IR-02_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to provide incident response training to users is defined"},{"id":"IR-02_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to review and update incident response training content is defined"},{"id":"IR-02_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that initiate a review of the incident response training content are defined"}],"related":["AT-2","AT-3","AT-4","CP-3","IR-3","IR-4","IR-8","IR-9"],"references":[{"title":"OMB M-17-12","url":"https://obamawhitehouse.archives.gov/sites/default/files/omb/memoranda/2017/m-17-12_0.pdf"},{"title":"SP 800-50","url":"https://doi.org/10.6028/NIST.SP.800-50"}],"objectives":[{"label":"IR-02a.","prose":"","items":[{"label":"IR-02a.01","prose":"incident response training is provided to system users consistent with assigned roles and responsibilities within [Assignment: organization-defined time period] of assuming an incident response role or responsibility or acquiring system access;"},{"label":"IR-02a.02","prose":"incident response training is provided to system users consistent with assigned roles and responsibilities when required by system changes;"},{"label":"IR-02a.03","prose":"incident response training is provided to system users consistent with assigned roles and responsibilities [Assignment: organization-defined frequency] thereafter;"}]},{"label":"IR-02b.","prose":"","items":[{"label":"IR-02b.[01]","prose":"incident response training content is reviewed and updated [Assignment: organization-defined frequency];"},{"label":"IR-02b.[02]","prose":"incident response training content is reviewed and updated following [Assignment: organization-defined events]."}]}],"methods":[{"method":"Examine","objects":["Incident response policy","procedures addressing incident response training","incident response training curriculum","incident response training materials","privacy plan","incident response plan","incident response training records","system security plan"]},{"method":"Interview","objects":["Organizational personnel with incident response training and operational responsibilities","organizational personnel with information security and privacy responsibilities"]}]},"IR-2(1)":{"statement":[{"prose":"Incorporate simulated events into incident response training to facilitate the required response by personnel in crisis situations."}],"discussion":["Organizations establish requirements for responding to incidents in incident response plans. Incorporating simulated events into incident response training helps to ensure that personnel understand their individual responsibilities and what specific actions to take in crisis situations."],"params":[],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Incident response policy","procedures addressing incident response training","incident response training curriculum","incident response training materials","incident response plan","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with incident response training and operational responsibilities","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Mechanisms that support and/or implement simulated events for incident response training"]}]},"IR-2(2)":{"statement":[{"prose":"Provide an incident response training environment using [Assignment: organization-defined automated mechanisms]."}],"discussion":["Automated mechanisms can provide a more thorough and realistic incident response training environment. This can be accomplished, for example, by providing more complete coverage of incident response issues, selecting more realistic training scenarios and environments, and stressing the response capability."],"params":[{"id":"IR-02(02)_ODP","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms used in an incident response training environment are defined"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Incident response policy","procedures addressing incident response training","incident response training curriculum","incident response training materials","automated mechanisms supporting incident response training","incident response plan","system security plan","privacy plan"]},{"method":"Interview","objects":["Organizational personnel with incident response training and operational responsibilities","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Automated mechanisms that provide a thorough and realistic incident response training environment"]}]},"IR-3":{"statement":[{"prose":"Test the effectiveness of the incident response capability for the system [Assignment: organization-defined frequency] using the following tests: [Assignment: organization-defined tests]."}],"discussion":["Organizations test incident response capabilities to determine their effectiveness and identify potential weaknesses or deficiencies. Incident response testing includes the use of checklists, walk-through or tabletop exercises, and simulations (parallel or full interrupt). Incident response testing can include a determination of the effects on organizational operations and assets and individuals due to incident response. The use of qualitative and quantitative data aids in determining the effectiveness of incident response processes."],"params":[{"id":"IR-03_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to test the effectiveness of the incident response capability for the system is defined"},{"id":"IR-03_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined tests]","guideline":"tests used to test the effectiveness of the incident response capability for the system are defined"}],"related":["CP-3","CP-4","IR-2","IR-4","IR-8","PM-14"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-84","url":"https://doi.org/10.6028/NIST.SP.800-84"},{"title":"SP 800-115","url":"https://doi.org/10.6028/NIST.SP.800-115"}],"objectives":[],"methods":[{"method":"Examine","objects":["Incident response policy","contingency planning policy","procedures addressing incident response testing","procedures addressing contingency plan testing","incident response testing material","incident response test results","incident response test plan","incident response plan"]},{"method":"Interview","objects":["Organizational personnel with incident response testing responsibilities","organizational personnel with information security and privacy responsibilities"]}]},"IR-3(2)":{"statement":[{"prose":"Coordinate incident response testing with organizational elements responsible for related plans."}],"discussion":["Organizational plans related to incident response testing include business continuity plans, disaster recovery plans, continuity of operations plans, contingency plans, crisis communications plans, critical infrastructure plans, and occupant emergency plans."],"params":[],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Incident response policy","contingency planning policy","procedures addressing incident response testing","incident response testing documentation","incident response plan","business continuity plans","contingency plans","disaster recovery plans"]},{"method":"Interview","objects":["Organizational personnel with incident response testing responsibilities","organizational personnel with responsibilities for testing organizational plans related to incident response testing","organizational personnel with information security and privacy responsibilities"]}]},"IR-4":{"statement":[{"label":"a.","prose":"Implement an incident handling capability for incidents that is consistent with the incident response plan and includes preparation, detection and analysis, containment, eradication, and recovery;"},{"label":"b.","prose":"Coordinate incident handling activities with contingency planning activities;"},{"label":"c.","prose":"Incorporate lessons learned from ongoing incident handling activities into incident response procedures, training, and testing, and implement the resulting changes accordingly; and"},{"label":"d.","prose":"Ensure the rigor, intensity, scope, and results of incident handling activities are comparable and predictable across the organization."}],"discussion":["Organizations recognize that incident response capabilities are dependent on the capabilities of organizational systems and the mission and business processes being supported by those systems. Organizations consider incident response as part of the definition, design, and development of mission and business processes and systems. Incident-related information can be obtained from a variety of sources, including audit monitoring, physical access monitoring, and network monitoring; user or administrator reports; and reported supply chain events. An effective incident handling capability includes coordination among many organizational entities (e.g., mission or business owners, system owners, authorizing officials, human resources offices, physical security offices, personnel security offices, legal departments, risk executive [function], operations personnel, procurement offices). Suspected security incidents include the receipt of suspicious email communications that can contain malicious code. Suspected supply chain incidents include the insertion of counterfeit hardware or malicious code into organizational systems or system components. For federal agencies, an incident that involves personally identifiable information is considered a breach. A breach results in unauthorized disclosure, the loss of control, unauthorized acquisition, compromise, or a similar occurrence where a person other than an authorized user accesses or potentially accesses personally identifiable information or an authorized user accesses or potentially accesses such information for other than authorized purposes."],"params":[],"related":["AC-19","AU-6","AU-7","CM-6","CP-2","CP-3","CP-4","IR-2","IR-3","IR-5","IR-6","IR-8","PE-6","PL-2","PM-12","SA-8","SC-5","SC-7","SI-3","SI-4","SI-7"],"references":[{"title":"FASC18","url":"https://www.congress.gov/bill/115th-congress/senate-bill/3085"},{"title":"41 CFR 201","url":"https://www.federalregister.gov/d/2020-18939"},{"title":"OMB M-17-12","url":"https://obamawhitehouse.archives.gov/sites/default/files/omb/memoranda/2017/m-17-12_0.pdf"},{"title":"SP 800-61","url":"https://doi.org/10.6028/NIST.SP.800-61r2"},{"title":"SP 800-86","url":"https://doi.org/10.6028/NIST.SP.800-86"},{"title":"SP 800-101","url":"https://doi.org/10.6028/NIST.SP.800-101r1"},{"title":"SP 800-150","url":"https://doi.org/10.6028/NIST.SP.800-150"},{"title":"SP 800-160-2","url":"https://doi.org/10.6028/NIST.SP.800-160v2"},{"title":"SP 800-184","url":"https://doi.org/10.6028/NIST.SP.800-184"},{"title":"IR 7559","url":"https://doi.org/10.6028/NIST.IR.7559"}],"objectives":[{"label":"IR-04a.","prose":"","items":[{"label":"IR-04a.[01]","prose":"an incident handling capability for incidents is implemented that is consistent with the incident response plan;"},{"label":"IR-04a.[02]","prose":"the incident handling capability for incidents includes preparation;"},{"label":"IR-04a.[03]","prose":"the incident handling capability for incidents includes detection and analysis;"},{"label":"IR-04a.[04]","prose":"the incident handling capability for incidents includes containment;"},{"label":"IR-04a.[05]","prose":"the incident handling capability for incidents includes eradication;"},{"label":"IR-04a.[06]","prose":"the incident handling capability for incidents includes recovery;"}]},{"label":"IR-04b.","prose":"incident handling activities are coordinated with contingency planning activities;"},{"label":"IR-04c.","prose":"","items":[{"label":"IR-04c.[01]","prose":"lessons learned from ongoing incident handling activities are incorporated into incident response procedures, training, and testing;"},{"label":"IR-04c.[02]","prose":"the changes resulting from the incorporated lessons learned are implemented accordingly;"}]},{"label":"IR-04d.","prose":"","items":[{"label":"IR-04d.[01]","prose":"the rigor of incident handling activities is comparable and predictable across the organization;"},{"label":"IR-04d.[02]","prose":"the intensity of incident handling activities is comparable and predictable across the organization;"},{"label":"IR-04d.[03]","prose":"the scope of incident handling activities is comparable and predictable across the organization;"},{"label":"IR-04d.[04]","prose":"the results of incident handling activities are comparable and predictable across the organization."}]}],"methods":[{"method":"Examine","objects":["Incident response policy","contingency planning policy","procedures addressing incident handling","incident response plan","contingency plan","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with incident handling responsibilities","organizational personnel with contingency planning responsibilities","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Incident handling capability for the organization"]}]},"IR-4(1)":{"statement":[{"prose":"Support the incident handling process using [Assignment: organization-defined automated mechanisms]."}],"discussion":["Automated mechanisms that support incident handling processes include online incident management systems and tools that support the collection of live response data, full network packet capture, and forensic analysis."],"params":[{"id":"IR-04(01)_ODP","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms used to support the incident handling process are defined"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Incident response policy","procedures addressing incident handling","automated mechanisms supporting incident handling","system design documentation","system configuration settings and associated documentation","system audit records","incident response plan","system security plan"]},{"method":"Interview","objects":["Organizational personnel with incident handling responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Automated mechanisms that support and/or implement the incident handling process"]}]},"IR-4(4)":{"statement":[{"prose":"Correlate incident information and individual incident responses to achieve an organization-wide perspective on incident awareness and response."}],"discussion":["Sometimes, a threat event, such as a hostile cyber-attack, can only be observed by bringing together information from different sources, including various reports and reporting procedures established by organizations."],"params":[],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Incident response policy","procedures addressing incident handling","incident response plan","privacy plan","mechanisms supporting incident and event correlation","system design documentation","system configuration settings and associated documentation","system security plan"]},{"method":"Interview","objects":["Organizational personnel with incident handling responsibilities","organizational personnel with information security and privacy responsibilities","organizational personnel with whom incident information and individual incident responses are to be correlated"]},{"method":"Test","objects":["Organizational processes for correlating incident information and individual incident responses","mechanisms that support and or implement the correlation of incident response information with individual incident responses"]}]},"IR-4(11)":{"statement":[{"prose":"Establish and maintain an integrated incident response team that can be deployed to any location identified by the organization in [Assignment: organization-defined time period]."}],"discussion":["An integrated incident response team is a team of experts that assesses, documents, and responds to incidents so that organizational systems and networks can recover quickly and implement the necessary controls to avoid future incidents. Incident response team personnel include forensic and malicious code analysts, tool developers, systems security and privacy engineers, and real-time operations personnel. The incident handling capability includes performing rapid forensic preservation of evidence and analysis of and response to intrusions. For some organizations, the incident response team can be a cross-organizational entity.","An integrated incident response team facilitates information sharing and allows organizational personnel (e.g., developers, implementers, and operators) to leverage team knowledge of the threat and implement defensive measures that enable organizations to deter intrusions more effectively. Moreover, integrated teams promote the rapid detection of intrusions, the development of appropriate mitigations, and the deployment of effective defensive measures. For example, when an intrusion is detected, the integrated team can rapidly develop an appropriate response for operators to implement, correlate the new incident with information on past intrusions, and augment ongoing cyber intelligence development. Integrated incident response teams are better able to identify adversary tactics, techniques, and procedures that are linked to the operations tempo or specific mission and business functions and to define responsive actions in a way that does not disrupt those mission and business functions. Incident response teams can be distributed within organizations to make the capability resilient."],"params":[{"id":"IR-04(11)_ODP","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"the time period within which an integrated incident response team can be deployed is defined"}],"related":["AT-3"],"references":[],"objectives":[{"label":"IR-04(11)[01]","prose":"an integrated incident response team is established and maintained;"},{"label":"IR-04(11)[02]","prose":"the integrated incident response team can be deployed to any location identified by the organization in [Assignment: organization-defined time period]."}],"methods":[{"method":"Examine","objects":["Incident response policy","procedures addressing incident handling","procedures addressing incident response planning","incident response plan","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with incident handling responsibilities","organizational personnel with information security and privacy responsibilities","members of the integrated incident response team"]}]},"IR-5":{"statement":[{"prose":"Track and document incidents."}],"discussion":["Documenting incidents includes maintaining records about each incident, the status of the incident, and other pertinent information necessary for forensics as well as evaluating incident details, trends, and handling. Incident information can be obtained from a variety of sources, including network monitoring, incident reports, incident response teams, user complaints, supply chain partners, audit monitoring, physical access monitoring, and user and administrator reports. [IR-4](#ir-4) provides information on the types of incidents that are appropriate for monitoring."],"params":[],"related":["AU-6","AU-7","IR-4","IR-6","IR-8","PE-6","PM-5","SC-5","SC-7","SI-3","SI-4","SI-7"],"references":[{"title":"SP 800-61","url":"https://doi.org/10.6028/NIST.SP.800-61r2"}],"objectives":[{"label":"IR-05[01]","prose":"incidents are tracked;"},{"label":"IR-05[02]","prose":"incidents are documented."}],"methods":[{"method":"Examine","objects":["Incident response policy","procedures addressing incident monitoring","incident response records and documentation","incident response plan","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with incident monitoring responsibilities","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Incident monitoring capability for the organization","mechanisms supporting and/or implementing the tracking and documenting of system security incidents"]}]},"IR-5(1)":{"statement":[{"prose":"Track incidents and collect and analyze incident information using [Assignment: organization-defined automated mechanisms]."}],"discussion":["Automated mechanisms for tracking incidents and collecting and analyzing incident information include Computer Incident Response Centers or other electronic databases of incidents and network monitoring devices."],"params":[{"id":"IR-5.1_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]"},{"id":"IR-05(01)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms used to track incidents are defined"},{"id":"IR-05(01)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms used to collect incident information are defined"},{"id":"IR-05(01)_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms used to analyze incident information are defined"}],"related":[],"references":[],"objectives":[{"label":"IR-05(01)[01]","prose":"incidents are tracked using [Assignment: organization-defined automated mechanisms];"},{"label":"IR-05(01)[02]","prose":"incident information is collected using [Assignment: organization-defined automated mechanisms];"},{"label":"IR-05(01)[03]","prose":"incident information is analyzed using [Assignment: organization-defined automated mechanisms]."}],"methods":[{"method":"Examine","objects":["Incident response policy","procedures addressing incident monitoring","incident response records and documentation","system security plan","incident response plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with incident monitoring responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Incident monitoring capability for the organization","automated mechanisms supporting and/or implementing the tracking and documenting of system security incidents"]}]},"IR-6":{"statement":[{"label":"a.","prose":"Require personnel to report suspected incidents to the organizational incident response capability within [Assignment: organization-defined time period]; and"},{"label":"b.","prose":"Report incident information to [Assignment: organization-defined authorities]."}],"discussion":["The types of incidents reported, the content and timeliness of the reports, and the designated reporting authorities reflect applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Incident information can inform risk assessments, control effectiveness assessments, security requirements for acquisitions, and selection criteria for technology products."],"params":[{"id":"IR-06_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"time period for personnel to report suspected incidents to the organizational incident response capability is defined"},{"id":"IR-06_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined authorities]","guideline":"authorities to whom incident information is to be reported are defined"}],"related":["CM-6","CP-2","IR-4","IR-5","IR-8","IR-9"],"references":[{"title":"FASC18","url":"https://www.congress.gov/bill/115th-congress/senate-bill/3085"},{"title":"41 CFR 201","url":"https://www.federalregister.gov/d/2020-18939"},{"title":"USCERT IR","url":"https://us-cert.cisa.gov/incident-notification-guidelines"},{"title":"SP 800-61","url":"https://doi.org/10.6028/NIST.SP.800-61r2"}],"objectives":[{"label":"IR-06a.","prose":"personnel is/are required to report suspected incidents to the organizational incident response capability within [Assignment: organization-defined time period];"},{"label":"IR-06b.","prose":"incident information is reported to [Assignment: organization-defined authorities]."}],"methods":[{"method":"Examine","objects":["Incident response policy","procedures addressing incident reporting","incident reporting records and documentation","incident response plan","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with incident reporting responsibilities","organizational personnel with information security and privacy responsibilities","personnel who have/should have reported incidents","personnel (authorities) to whom incident information is to be reported","system users"]},{"method":"Test","objects":["Organizational processes for incident reporting","mechanisms supporting and/or implementing incident reporting"]}]},"IR-6(1)":{"statement":[{"prose":"Report incidents using [Assignment: organization-defined automated mechanisms]."}],"discussion":["The recipients of incident reports are specified in [IR-6b](#ir-6_smt.b). Automated reporting mechanisms include email, posting on websites (with automatic updates), and automated incident response tools and programs."],"params":[{"id":"IR-06(01)_ODP","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms used for reporting incidents are defined"}],"related":["IR-7"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Incident response policy","procedures addressing incident reporting","automated mechanisms supporting incident reporting","system design documentation","system configuration settings and associated documentation","incident response plan","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with incident reporting responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for incident reporting","automated mechanisms supporting and/or implementing the reporting of security incidents"]}]},"IR-6(3)":{"statement":[{"prose":"Provide incident information to the provider of the product or service and other organizations involved in the supply chain or supply chain governance for systems or system components related to the incident."}],"discussion":["Organizations involved in supply chain activities include product developers, system integrators, manufacturers, packagers, assemblers, distributors, vendors, and resellers. Entities that provide supply chain governance include the Federal Acquisition Security Council (FASC). Supply chain incidents include compromises or breaches that involve information technology products, system components, development processes or personnel, distribution processes, or warehousing facilities. Organizations determine the appropriate information to share and consider the value gained from informing external organizations about supply chain incidents, including the ability to improve processes or to identify the root cause of an incident."],"params":[],"related":["SR-8"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Incident response policy","procedures addressing supply chain coordination and supply chain risk information sharing with the Federal Acquisition Security Council","acquisition policy","acquisition contracts","service-level agreements","incident response plan","supply chain risk management plan","system security plan"]},{"method":"Interview","objects":["Organizational personnel with incident reporting responsibilities","organizational personnel with information security responsibilities","organizational personnel with supply chain risk management responsibilities","organization personnel with acquisition responsibilities"]},{"method":"Test","objects":["Organizational processes for incident reporting","organizational processes for supply chain risk information sharing","mechanisms supporting and/or implementing the reporting of incident information involved in the supply chain"]}]},"IR-7":{"statement":[{"prose":"Provide an incident response support resource, integral to the organizational incident response capability, that offers advice and assistance to users of the system for the handling and reporting of incidents."}],"discussion":["Incident response support resources provided by organizations include help desks, assistance groups, automated ticketing systems to open and track incident response tickets, and access to forensics services or consumer redress services, when required."],"params":[],"related":["AT-2","AT-3","IR-4","IR-6","IR-8","PM-22","PM-26","SA-9","SI-18"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"IR 7559","url":"https://doi.org/10.6028/NIST.IR.7559"}],"objectives":[{"label":"IR-07[01]","prose":"an incident response support resource, integral to the organizational incident response capability, is provided;"},{"label":"IR-07[02]","prose":"the incident response support resource offers advice and assistance to users of the system for the response and reporting of incidents."}],"methods":[{"method":"Examine","objects":["Incident response policy","procedures addressing incident response assistance","incident response plan","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with incident response assistance and support responsibilities","organizational personnel with access to incident response support and assistance capability","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Organizational processes for incident response assistance","mechanisms supporting and/or implementing incident response assistance"]}]},"IR-7(1)":{"statement":[{"prose":"Increase the availability of incident response information and support using [Assignment: organization-defined automated mechanisms]."}],"discussion":["Automated mechanisms can provide a push or pull capability for users to obtain incident response assistance. For example, individuals may have access to a website to query the assistance capability, or the assistance capability can proactively send incident response information to users (general distribution or targeted) as part of increasing understanding of current response capabilities and support."],"params":[{"id":"IR-07(01)_ODP","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms used to increase the availability of incident response information and support are defined"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Incident response policy","procedures addressing incident response assistance","automated mechanisms supporting incident response support and assistance","system design documentation","system configuration settings and associated documentation","incident response plan","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with incident response support and assistance responsibilities","organizational personnel with access to incident response support and assistance capability","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for incident response assistance","automated mechanisms supporting and/or implementing an increase in the availability of incident response information and support"]}]},"IR-8":{"statement":[{"label":"a.","prose":"Develop an incident response plan that:","items":[{"label":"1.","prose":"Provides the organization with a roadmap for implementing its incident response capability;"},{"label":"2.","prose":"Describes the structure and organization of the incident response capability;"},{"label":"3.","prose":"Provides a high-level approach for how the incident response capability fits into the overall organization;"},{"label":"4.","prose":"Meets the unique requirements of the organization, which relate to mission, size, structure, and functions;"},{"label":"5.","prose":"Defines reportable incidents;"},{"label":"6.","prose":"Provides metrics for measuring the incident response capability within the organization;"},{"label":"7.","prose":"Defines the resources and management support needed to effectively maintain and mature an incident response capability;"},{"label":"8.","prose":"Addresses the sharing of incident information;"},{"label":"9.","prose":"Is reviewed and approved by [Assignment: organization-defined personnel or roles] [Assignment: organization-defined frequency]; and"},{"label":"10.","prose":"Explicitly designates responsibility for incident response to [Assignment: organization-defined entities, personnel, or roles]."}]},{"label":"b.","prose":"Distribute copies of the incident response plan to [Assignment: organization-defined incident response personnel];"},{"label":"c.","prose":"Update the incident response plan to address system and organizational changes or problems encountered during plan implementation, execution, or testing;"},{"label":"d.","prose":"Communicate incident response plan changes to [Assignment: organization-defined incident response personnel (identified by name and/or by role) and organizational elements]; and"},{"label":"e.","prose":"Protect the incident response plan from unauthorized disclosure and modification."}],"discussion":["It is important that organizations develop and implement a coordinated approach to incident response. Organizational mission and business functions determine the structure of incident response capabilities. As part of the incident response capabilities, organizations consider the coordination and sharing of information with external organizations, including external service providers and other organizations involved in the supply chain. For incidents involving personally identifiable information (i.e., breaches), include a process to determine whether notice to oversight organizations or affected individuals is appropriate and provide that notice accordingly."],"params":[{"id":"IR-8_PRM_5","kind":"Assignment","value":"[Assignment: organization-defined incident response personnel (identified by name and/or by role) and organizational elements]"},{"id":"IR-08_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles that review and approve the incident response plan is/are identified"},{"id":"IR-08_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to review and approve the incident response plan is defined"},{"id":"IR-08_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined entities, personnel, or roles]","guideline":"entities, personnel, or roles with designated responsibility for incident response are defined"},{"id":"IR-08_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined incident response personnel]","guideline":"incident response personnel (identified by name and/or by role) to whom copies of the incident response plan are to be distributed is/are defined"},{"id":"IR-08_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined organizational elements]","guideline":"organizational elements to which copies of the incident response plan are to be distributed are defined"},{"id":"IR-08_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined incident response personnel]","guideline":"incident response personnel (identified by name and/or by role) to whom changes to the incident response plan is/are communicated are defined"},{"id":"IR-08_ODP[07]","kind":"Assignment","value":"[Assignment: organization-defined organizational elements]","guideline":"organizational elements to which changes to the incident response plan are communicated are defined"}],"related":["AC-2","CP-2","CP-4","IR-4","IR-7","IR-9","PE-6","PL-2","SA-15","SI-12","SR-8"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-61","url":"https://doi.org/10.6028/NIST.SP.800-61r2"},{"title":"OMB M-17-12","url":"https://obamawhitehouse.archives.gov/sites/default/files/omb/memoranda/2017/m-17-12_0.pdf"}],"objectives":[{"label":"IR-08a.","prose":"","items":[{"label":"IR-08a.01","prose":"an incident response plan is developed that provides the organization with a roadmap for implementing its incident response capability;"},{"label":"IR-08a.02","prose":"an incident response plan is developed that describes the structure and organization of the incident response capability;"},{"label":"IR-08a.03","prose":"an incident response plan is developed that provides a high-level approach for how the incident response capability fits into the overall organization;"},{"label":"IR-08a.04","prose":"an incident response plan is developed that meets the unique requirements of the organization with regard to mission, size, structure, and functions;"},{"label":"IR-08a.05","prose":"an incident response plan is developed that defines reportable incidents;"},{"label":"IR-08a.06","prose":"an incident response plan is developed that provides metrics for measuring the incident response capability within the organization;"},{"label":"IR-08a.07","prose":"an incident response plan is developed that defines the resources and management support needed to effectively maintain and mature an incident response capability;"},{"label":"IR-08a.08","prose":"an incident response plan is developed that addresses the sharing of incident information;"},{"label":"IR-08a.09","prose":"an incident response plan is developed that is reviewed and approved by [Assignment: organization-defined personnel or roles] [Assignment: organization-defined frequency];"},{"label":"IR-08a.10","prose":"an incident response plan is developed that explicitly designates responsibility for incident response to [Assignment: organization-defined entities, personnel, or roles]."}]},{"label":"IR-08b.","prose":"","items":[{"label":"IR-08b.[01]","prose":"copies of the incident response plan are distributed to [Assignment: organization-defined incident response personnel];"},{"label":"IR-08b.[02]","prose":"copies of the incident response plan are distributed to [Assignment: organization-defined organizational elements];"}]},{"label":"IR-08c.","prose":"the incident response plan is updated to address system and organizational changes or problems encountered during plan implementation, execution, or testing;"},{"label":"IR-08d.","prose":"","items":[{"label":"IR-08d.[01]","prose":"incident response plan changes are communicated to [Assignment: organization-defined incident response personnel];"},{"label":"IR-08d.[02]","prose":"incident response plan changes are communicated to [Assignment: organization-defined organizational elements];"}]},{"label":"IR-08e.","prose":"","items":[{"label":"IR-08e.[01]","prose":"the incident response plan is protected from unauthorized disclosure;"},{"label":"IR-08e.[02]","prose":"the incident response plan is protected from unauthorized modification."}]}],"methods":[{"method":"Examine","objects":["Incident response policy","procedures addressing incident response planning","incident response plan","system security plan","privacy plan","records of incident response plan reviews and approvals","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with incident response planning responsibilities","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Organizational incident response plan and related organizational processes"]}]},"MA-1":{"statement":[{"label":"a.","prose":"Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:","items":[{"label":"1.","prose":"[Selection (one or more): organization-level; mission/business process-level; system-level] maintenance policy that:","items":[{"label":"(a)","prose":"Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and"},{"label":"(b)","prose":"Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and"}]},{"label":"2.","prose":"Procedures to facilitate the implementation of the maintenance policy and the associated maintenance controls;"}]},{"label":"b.","prose":"Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the maintenance policy and procedures; and"},{"label":"c.","prose":"Review and update the current maintenance:","items":[{"label":"1.","prose":"Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and"},{"label":"2.","prose":"Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]."}]}],"discussion":["Maintenance policy and procedures address the controls in the MA family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of maintenance policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to maintenance policy and procedures assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure."],"params":[{"id":"MA-1_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]"},{"id":"MA-01_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the maintenance policy is to be disseminated is/are defined"},{"id":"MA-01_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the maintenance procedures are to be disseminated is/are defined"},{"id":"MA-01_ODP[03]","kind":"Selection","value":"[Selection (one or more): organization-level; mission/business process-level; system-level]"},{"id":"MA-01_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined official]","guideline":"an official to manage the maintenance policy and procedures is defined"},{"id":"MA-01_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency with which the current maintenance policy is reviewed and updated is defined"},{"id":"MA-01_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require the current maintenance policy to be reviewed and updated are defined"},{"id":"MA-01_ODP[07]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency with which the current maintenance procedures are reviewed and updated is defined"},{"id":"MA-01_ODP[08]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require the maintenance procedures to be reviewed and updated are defined"}],"related":["PM-9","PS-8","SI-12"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-12","url":"https://doi.org/10.6028/NIST.SP.800-12r1"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-39","url":"https://doi.org/10.6028/NIST.SP.800-39"},{"title":"SP 800-100","url":"https://doi.org/10.6028/NIST.SP.800-100"}],"objectives":[{"label":"MA-01a.","prose":"","items":[{"label":"MA-01a.[01]","prose":"a maintenance policy is developed and documented;"},{"label":"MA-01a.[02]","prose":"the maintenance policy is disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"MA-01a.[03]","prose":"maintenance procedures to facilitate the implementation of the maintenance policy and associated maintenance controls are developed and documented;"},{"label":"MA-01a.[04]","prose":"the maintenance procedures are disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"MA-01a.01","prose":"","items":[{"label":"MA-01a.01(a)","prose":"","items":[{"label":"MA-01a.01(a)[01]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] maintenance policy addresses purpose;"},{"label":"MA-01a.01(a)[02]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] maintenance policy addresses scope;"},{"label":"MA-01a.01(a)[03]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] maintenance policy addresses roles;"},{"label":"MA-01a.01(a)[04]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] maintenance policy addresses responsibilities;"},{"label":"MA-01a.01(a)[05]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] maintenance policy addresses management commitment;"},{"label":"MA-01a.01(a)[06]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] maintenance policy addresses coordination among organizational entities;"},{"label":"MA-01a.01(a)[07]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] maintenance policy addresses compliance;"}]},{"label":"MA-01a.01(b)","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] maintenance policy is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines;"}]}]},{"label":"MA-01b.","prose":"the [Assignment: organization-defined official] is designated to manage the development, documentation, and dissemination of the maintenance policy and procedures;"},{"label":"MA-01c.","prose":"","items":[{"label":"MA-01c.01","prose":"","items":[{"label":"MA-01c.01[01]","prose":"the current maintenance policy is reviewed and updated [Assignment: organization-defined frequency];"},{"label":"MA-01c.01[02]","prose":"the current maintenance policy is reviewed and updated following [Assignment: organization-defined events];"}]},{"label":"MA-01c.02","prose":"","items":[{"label":"MA-01c.02[01]","prose":"the current maintenance procedures are reviewed and updated [Assignment: organization-defined frequency];"},{"label":"MA-01c.02[02]","prose":"the current maintenance procedures are reviewed and updated following [Assignment: organization-defined events]."}]}]}],"methods":[{"method":"Examine","objects":["Maintenance policy and procedures","system security plan","privacy plan","organizational risk management strategy","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with maintenance responsibilities","organizational personnel with information security and privacy responsibilities"]}]},"MA-2":{"statement":[{"label":"a.","prose":"Schedule, document, and review records of maintenance, repair, and replacement on system components in accordance with manufacturer or vendor specifications and/or organizational requirements;"},{"label":"b.","prose":"Approve and monitor all maintenance activities, whether performed on site or remotely and whether the system or system components are serviced on site or removed to another location;"},{"label":"c.","prose":"Require that [Assignment: organization-defined personnel or roles] explicitly approve the removal of the system or system components from organizational facilities for off-site maintenance, repair, or replacement;"},{"label":"d.","prose":"Sanitize equipment to remove the following information from associated media prior to removal from organizational facilities for off-site maintenance, repair, or replacement: [Assignment: organization-defined information];"},{"label":"e.","prose":"Check all potentially impacted controls to verify that the controls are still functioning properly following maintenance, repair, or replacement actions; and"},{"label":"f.","prose":"Include the following information in organizational maintenance records: [Assignment: organization-defined information]."}],"discussion":["Controlling system maintenance addresses the information security aspects of the system maintenance program and applies to all types of maintenance to system components conducted by local or nonlocal entities. Maintenance includes peripherals such as scanners, copiers, and printers. Information necessary for creating effective maintenance records includes the date and time of maintenance, a description of the maintenance performed, names of the individuals or group performing the maintenance, name of the escort, and system components or equipment that are removed or replaced. Organizations consider supply chain-related risks associated with replacement components for systems."],"params":[{"id":"MA-02_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles required to explicitly approve the removal of the system or system components from organizational facilities for off-site maintenance or repairs is/are defined"},{"id":"MA-02_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined information]","guideline":"information to be removed from associated media prior to removal from organizational facilities for off-site maintenance, repair, or replacement is defined"},{"id":"MA-02_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined information]","guideline":"information to be included in organizational maintenance records is defined"}],"related":["CM-2","CM-3","CM-4","CM-5","CM-8","MA-4","MP-6","PE-16","SI-2","SR-3","SR-4","SR-11"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"IR 8023","url":"https://doi.org/10.6028/NIST.IR.8023"}],"objectives":[{"label":"MA-02a.","prose":"","items":[{"label":"MA-02a.[01]","prose":"maintenance, repair, and replacement of system components are scheduled in accordance with manufacturer or vendor specifications and/or organizational requirements;"},{"label":"MA-02a.[02]","prose":"maintenance, repair, and replacement of system components are documented in accordance with manufacturer or vendor specifications and/or organizational requirements;"},{"label":"MA-02a.[03]","prose":"records of maintenance, repair, and replacement of system components are reviewed in accordance with manufacturer or vendor specifications and/or organizational requirements;"}]},{"label":"MA-02b.","prose":"","items":[{"label":"MA-02b.[01]","prose":"all maintenance activities, whether performed on site or remotely and whether the system or system components are serviced on site or removed to another location, are approved;"},{"label":"MA-02b.[02]","prose":"all maintenance activities, whether performed on site or remotely and whether the system or system components are serviced on site or removed to another location, are monitored;"}]},{"label":"MA-02c.","prose":"[Assignment: organization-defined personnel or roles] is/are required to explicitly approve the removal of the system or system components from organizational facilities for off-site maintenance, repair, or replacement;"},{"label":"MA-02d.","prose":"equipment is sanitized to remove [Assignment: organization-defined information] from associated media prior to removal from organizational facilities for off-site maintenance, repair, or replacement;"},{"label":"MA-02e.","prose":"all potentially impacted controls are checked to verify that the controls are still functioning properly following maintenance, repair, or replacement actions;"},{"label":"MA-02f.","prose":"[Assignment: organization-defined information] is included in organizational maintenance records."}],"methods":[{"method":"Examine","objects":["Maintenance policy","procedures addressing controlled system maintenance","maintenance records","manufacturer/vendor maintenance specifications","equipment sanitization records","media sanitization records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system maintenance responsibilities","organizational personnel with information security responsibilities","organizational personnel responsible for media sanitization","system/network administrators"]},{"method":"Test","objects":["Organizational processes for scheduling, performing, documenting, reviewing, approving, and monitoring maintenance and repairs for the system","organizational processes for sanitizing system components","mechanisms supporting and/or implementing controlled maintenance","mechanisms implementing the sanitization of system components"]}]},"MA-2(2)":{"statement":[{"label":"(a)","prose":"Schedule, conduct, and document maintenance, repair, and replacement actions for the system using [Assignment: organization-defined automated mechanisms]; and"},{"label":"(b)","prose":"Produce up-to date, accurate, and complete records of all maintenance, repair, and replacement actions requested, scheduled, in process, and completed."}],"discussion":["The use of automated mechanisms to manage and control system maintenance programs and activities helps to ensure the generation of timely, accurate, complete, and consistent maintenance records."],"params":[{"id":"MA-2.2_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]"},{"id":"MA-02(02)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms used to schedule maintenance, repair, and replacement actions for the system are defined"},{"id":"MA-02(02)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms used to conduct maintenance, repair, and replacement actions for the system are defined"},{"id":"MA-02(02)_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms used to document maintenance, repair, and replacement actions for the system are defined"}],"related":["MA-3"],"references":[],"objectives":[{"label":"MA-02(02)(a)","prose":"","items":[{"label":"MA-02(02)(a)[01]","prose":"[Assignment: organization-defined automated mechanisms] are used to schedule maintenance, repair, and replacement actions for the system;"},{"label":"MA-02(02)(a)[02]","prose":"[Assignment: organization-defined automated mechanisms] are used to conduct maintenance, repair, and replacement actions for the system;"},{"label":"MA-02(02)(a)[03]","prose":"[Assignment: organization-defined automated mechanisms] are used to document maintenance, repair, and replacement actions for the system;"}]},{"label":"MA-02(02)(b)","prose":"","items":[{"label":"MA-02(02)(b)[01]","prose":"up-to date, accurate, and complete records of all maintenance actions requested, scheduled, in process, and completed are produced."},{"label":"MA-02(02)(b)[02]","prose":"up-to date, accurate, and complete records of all repair actions requested, scheduled, in process, and completed are produced."},{"label":"MA-02(02)(b)[03]","prose":"up-to date, accurate, and complete records of all replacement actions requested, scheduled, in process, and completed are produced."}]}],"methods":[{"method":"Examine","objects":["Maintenance policy","procedures addressing controlled system maintenance","automated mechanisms supporting system maintenance activities","system configuration settings and associated documentation","maintenance records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system maintenance responsibilities","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Automated mechanisms supporting and/or implementing controlled maintenance","automated mechanisms supporting and/or implementing the production of records of maintenance and repair actions"]}]},"MA-3":{"statement":[{"label":"a.","prose":"Approve, control, and monitor the use of system maintenance tools; and"},{"label":"b.","prose":"Review previously approved system maintenance tools [Assignment: organization-defined frequency]."}],"discussion":["Approving, controlling, monitoring, and reviewing maintenance tools address security-related issues associated with maintenance tools that are not within system authorization boundaries and are used specifically for diagnostic and repair actions on organizational systems. Organizations have flexibility in determining roles for the approval of maintenance tools and how that approval is documented. A periodic review of maintenance tools facilitates the withdrawal of approval for outdated, unsupported, irrelevant, or no-longer-used tools. Maintenance tools can include hardware, software, and firmware items and may be pre-installed, brought in with maintenance personnel on media, cloud-based, or downloaded from a website. Such tools can be vehicles for transporting malicious code, either intentionally or unintentionally, into a facility and subsequently into systems. Maintenance tools can include hardware and software diagnostic test equipment and packet sniffers. The hardware and software components that support maintenance and are a part of the system (including the software implementing utilities such as \"ping,\" \"ls,\" \"ipconfig,\" or the hardware and software implementing the monitoring port of an Ethernet switch) are not addressed by maintenance tools."],"params":[{"id":"MA-03_ODP","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to review previously approved system maintenance tools is defined"}],"related":["MA-2","PE-16"],"references":[{"title":"SP 800-88","url":"https://doi.org/10.6028/NIST.SP.800-88r1"}],"objectives":[{"label":"MA-03a.","prose":"","items":[{"label":"MA-03a.[01]","prose":"the use of system maintenance tools is approved;"},{"label":"MA-03a.[02]","prose":"the use of system maintenance tools is controlled;"},{"label":"MA-03a.[03]","prose":"the use of system maintenance tools is monitored;"}]},{"label":"MA-03b.","prose":"previously approved system maintenance tools are reviewed [Assignment: organization-defined frequency]."}],"methods":[{"method":"Examine","objects":["Maintenance policy","procedures addressing system maintenance tools","system maintenance tools and associated documentation","maintenance records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system maintenance responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for approving, controlling, and monitoring maintenance tools","mechanisms supporting and/or implementing the approval, control, and/or monitoring of maintenance tools"]}]},"MA-3(1)":{"statement":[{"prose":"Inspect the maintenance tools used by maintenance personnel for improper or unauthorized modifications."}],"discussion":["Maintenance tools can be directly brought into a facility by maintenance personnel or downloaded from a vendor’s website. If, upon inspection of the maintenance tools, organizations determine that the tools have been modified in an improper manner or the tools contain malicious code, the incident is handled consistent with organizational policies and procedures for incident handling."],"params":[],"related":["SI-7"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Maintenance policy","procedures addressing system maintenance tools","system maintenance tools and associated documentation","maintenance tool inspection records","maintenance records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system maintenance responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for inspecting maintenance tools","mechanisms supporting and/or implementing the inspection of maintenance tools"]}]},"MA-3(2)":{"statement":[{"prose":"Check media containing diagnostic and test programs for malicious code before the media are used in the system."}],"discussion":["If, upon inspection of media containing maintenance, diagnostic, and test programs, organizations determine that the media contains malicious code, the incident is handled consistent with organizational incident handling policies and procedures."],"params":[],"related":["SI-3"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Maintenance policy","procedures addressing system maintenance tools","system maintenance tools and associated documentation","maintenance records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system maintenance responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational process for inspecting media for malicious code","mechanisms supporting and/or implementing the inspection of media used for maintenance"]}]},"MA-3(3)":{"statement":[{"prose":"Prevent the removal of maintenance equipment containing organizational information by:"},{"label":"(a)","prose":"Verifying that there is no organizational information contained on the equipment;"},{"label":"(b)","prose":"Sanitizing or destroying the equipment;"},{"label":"(c)","prose":"Retaining the equipment within the facility; or"},{"label":"(d)","prose":"Obtaining an exemption from [Assignment: organization-defined personnel or roles] explicitly authorizing removal of the equipment from the facility."}],"discussion":["Organizational information includes all information owned by organizations and any information provided to organizations for which the organizations serve as information stewards."],"params":[{"id":"MA-03(03)_ODP","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles who can authorize removal of equipment from the facility is/are defined"}],"related":["MP-6"],"references":[],"objectives":[{"label":"MA-03(03)(a)","prose":"the removal of maintenance equipment containing organizational information is prevented by verifying that there is no organizational information contained on the equipment; or"},{"label":"MA-03(03)(b)","prose":"the removal of maintenance equipment containing organizational information is prevented by sanitizing or destroying the equipment; or"},{"label":"MA-03(03)(c)","prose":"the removal of maintenance equipment containing organizational information is prevented by retaining the equipment within the facility; or"},{"label":"MA-03(03)(d)","prose":"the removal of maintenance equipment containing organizational information is prevented by obtaining an exemption from [Assignment: organization-defined personnel or roles] explicitly authorizing removal of the equipment from the facility."}],"methods":[{"method":"Examine","objects":["Maintenance policy","procedures addressing system maintenance tools","system maintenance tools and associated documentation","maintenance records","equipment sanitization records","media sanitization records","exemptions for equipment removal","system security plan"]},{"method":"Interview","objects":["Organizational personnel with system maintenance responsibilities","organizational personnel with information security responsibilities","organizational personnel responsible for media sanitization"]},{"method":"Test","objects":["Organizational process for preventing unauthorized removal of information","mechanisms supporting media sanitization or destruction of equipment","mechanisms supporting verification of media sanitization"]}]},"MA-4":{"statement":[{"label":"a.","prose":"Approve and monitor nonlocal maintenance and diagnostic activities;"},{"label":"b.","prose":"Allow the use of nonlocal maintenance and diagnostic tools only as consistent with organizational policy and documented in the security plan for the system;"},{"label":"c.","prose":"Employ strong authentication in the establishment of nonlocal maintenance and diagnostic sessions;"},{"label":"d.","prose":"Maintain records for nonlocal maintenance and diagnostic activities; and"},{"label":"e.","prose":"Terminate session and network connections when nonlocal maintenance is completed."}],"discussion":["Nonlocal maintenance and diagnostic activities are conducted by individuals who communicate through either an external or internal network. Local maintenance and diagnostic activities are carried out by individuals who are physically present at the system location and not communicating across a network connection. Authentication techniques used to establish nonlocal maintenance and diagnostic sessions reflect the network access requirements in [IA-2](#ia-2). Strong authentication requires authenticators that are resistant to replay attacks and employ multi-factor authentication. Strong authenticators include PKI where certificates are stored on a token protected by a password, passphrase, or biometric. Enforcing requirements in [MA-4](#ma-4) is accomplished, in part, by other controls. [SP 800-63B](#e59c5a7c-8b1f-49ca-8de0-6ee0882180ce) provides additional guidance on strong authentication and authenticators."],"params":[],"related":["AC-2","AC-3","AC-6","AC-17","AU-2","AU-3","IA-2","IA-4","IA-5","IA-8","MA-2","MA-5","PL-2","SC-7","SC-10"],"references":[{"title":"FIPS 140-3","url":"https://doi.org/10.6028/NIST.FIPS.140-3"},{"title":"FIPS 197","url":"https://doi.org/10.6028/NIST.FIPS.197"},{"title":"FIPS 201-2","url":"https://doi.org/10.6028/NIST.FIPS.201-2"},{"title":"SP 800-63-3","url":"https://doi.org/10.6028/NIST.SP.800-63-3"},{"title":"SP 800-88","url":"https://doi.org/10.6028/NIST.SP.800-88r1"}],"objectives":[{"label":"MA-04a.","prose":"","items":[{"label":"MA-04a.[01]","prose":"nonlocal maintenance and diagnostic activities are approved;"},{"label":"MA-04a.[02]","prose":"nonlocal maintenance and diagnostic activities are monitored;"}]},{"label":"MA-04b.","prose":"","items":[{"label":"MA-04b.[01]","prose":"the use of nonlocal maintenance and diagnostic tools are allowed only as consistent with organizational policy;"},{"label":"MA-04b.[02]","prose":"the use of nonlocal maintenance and diagnostic tools are documented in the security plan for the system;"}]},{"label":"MA-04c.","prose":"strong authentication is employed in the establishment of nonlocal maintenance and diagnostic sessions;"},{"label":"MA-04d.","prose":"records for nonlocal maintenance and diagnostic activities are maintained;"},{"label":"MA-04e.","prose":"","items":[{"label":"MA-04e.[01]","prose":"session connections are terminated when nonlocal maintenance is completed;"},{"label":"MA-04e.[02]","prose":"network connections are terminated when nonlocal maintenance is completed."}]}],"methods":[{"method":"Examine","objects":["Maintenance policy","procedures addressing nonlocal system maintenance","remote access policy","remote access procedures","system design documentation","system configuration settings and associated documentation","maintenance records","records of remote access"]},{"method":"Interview","objects":["Organizational personnel with system maintenance responsibilities","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Organizational processes for managing nonlocal maintenance","mechanisms implementing, supporting, and/or managing nonlocal maintenance","mechanisms for strong authentication of nonlocal maintenance diagnostic sessions","mechanisms for terminating nonlocal maintenance sessions and network connections"]}]},"MA-4(3)":{"statement":[{"label":"(a)","prose":"Require that nonlocal maintenance and diagnostic services be performed from a system that implements a security capability comparable to the capability implemented on the system being serviced; or"},{"label":"(b)","prose":"Remove the component to be serviced from the system prior to nonlocal maintenance or diagnostic services; sanitize the component (for organizational information); and after the service is performed, inspect and sanitize the component (for potentially malicious software) before reconnecting the component to the system."}],"discussion":["Comparable security capability on systems, diagnostic tools, and equipment providing maintenance services implies that the implemented controls on those systems, tools, and equipment are at least as comprehensive as the controls on the system being serviced."],"params":[],"related":["MP-6","SI-3","SI-7"],"references":[],"objectives":[{"label":"MA-04(03)(a)","prose":"","items":[{"label":"MA-04(03)(a)[01]","prose":"nonlocal maintenance services are required to be performed from a system that implements a security capability comparable to the capability implemented on the system being serviced;"},{"label":"MA-04(03)(a)[02]","prose":"nonlocal diagnostic services are required to be performed from a system that implements a security capability comparable to the capability implemented on the system being serviced; or"}]},{"label":"MA-04(03)(b)","prose":"","items":[{"label":"MA-04(03)(b)[01]","prose":"the component to be serviced is removed from the system prior to nonlocal maintenance or diagnostic services;"},{"label":"MA-04(03)(b)[02]","prose":"the component to be serviced is sanitized (for organizational information);"},{"label":"MA-04(03)(b)[03]","prose":"the component is inspected and sanitized (for potentially malicious software) after the service is performed and before reconnecting the component to the system."}]}],"methods":[{"method":"Examine","objects":["Maintenance policy","procedures addressing nonlocal system maintenance","service provider contracts and/or service-level agreements","maintenance records","inspection records","audit records","equipment sanitization records","media sanitization records"]},{"method":"Interview","objects":["Organizational personnel with system maintenance responsibilities","system maintenance provider","organizational personnel with information security responsibilities","organizational personnel responsible for media sanitization","system/network administrators"]},{"method":"Test","objects":["Organizational processes for comparable security and sanitization for nonlocal maintenance","organizational processes for the removal, sanitization, and inspection of components serviced via nonlocal maintenance","mechanisms supporting and/or implementing component sanitization and inspection"]}]},"MA-5":{"statement":[{"label":"a.","prose":"Establish a process for maintenance personnel authorization and maintain a list of authorized maintenance organizations or personnel;"},{"label":"b.","prose":"Verify that non-escorted personnel performing maintenance on the system possess the required access authorizations; and"},{"label":"c.","prose":"Designate organizational personnel with required access authorizations and technical competence to supervise the maintenance activities of personnel who do not possess the required access authorizations."}],"discussion":["Maintenance personnel refers to individuals who perform hardware or software maintenance on organizational systems, while [PE-2](#pe-2) addresses physical access for individuals whose maintenance duties place them within the physical protection perimeter of the systems. Technical competence of supervising individuals relates to the maintenance performed on the systems, while having required access authorizations refers to maintenance on and near the systems. Individuals not previously identified as authorized maintenance personnel—such as information technology manufacturers, vendors, systems integrators, and consultants—may require privileged access to organizational systems, such as when they are required to conduct maintenance activities with little or no notice. Based on organizational assessments of risk, organizations may issue temporary credentials to these individuals. Temporary credentials may be for one-time use or for very limited time periods."],"params":[],"related":["AC-2","AC-3","AC-5","AC-6","IA-2","IA-8","MA-4","MP-2","PE-2","PE-3","PS-7","RA-3"],"references":[],"objectives":[{"label":"MA-05a.","prose":"","items":[{"label":"MA-05a.[01]","prose":"a process for maintenance personnel authorization is established;"},{"label":"MA-05a.[02]","prose":"a list of authorized maintenance organizations or personnel is maintained;"}]},{"label":"MA-05b.","prose":"non-escorted personnel performing maintenance on the system possess the required access authorizations;"},{"label":"MA-05c.","prose":"organizational personnel with required access authorizations and technical competence is/are designated to supervise the maintenance activities of personnel who do not possess the required access authorizations."}],"methods":[{"method":"Examine","objects":["Maintenance policy","procedures addressing maintenance personnel","service provider contracts","service-level agreements","list of authorized personnel","maintenance records","access control records","system security plan"]},{"method":"Interview","objects":["Organizational personnel with system maintenance responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for authorizing and managing maintenance personnel","mechanisms supporting and/or implementing authorization of maintenance personnel"]}]},"MA-5(1)":{"statement":[{"label":"(a)","prose":"Implement procedures for the use of maintenance personnel that lack appropriate security clearances or are not U.S. citizens, that include the following requirements:","items":[{"label":"(1)","prose":"Maintenance personnel who do not have needed access authorizations, clearances, or formal access approvals are escorted and supervised during the performance of maintenance and diagnostic activities on the system by approved organizational personnel who are fully cleared, have appropriate access authorizations, and are technically qualified; and"},{"label":"(2)","prose":"Prior to initiating maintenance or diagnostic activities by personnel who do not have needed access authorizations, clearances or formal access approvals, all volatile information storage components within the system are sanitized and all nonvolatile storage media are removed or physically disconnected from the system and secured; and"}]},{"label":"(b)","prose":"Develop and implement [Assignment: organization-defined alternate controls] in the event a system component cannot be sanitized, removed, or disconnected from the system."}],"discussion":["Procedures for individuals who lack appropriate security clearances or who are not U.S. citizens are intended to deny visual and electronic access to classified or controlled unclassified information contained on organizational systems. Procedures for the use of maintenance personnel can be documented in security plans for the systems."],"params":[{"id":"MA-05(01)_ODP","kind":"Assignment","value":"[Assignment: organization-defined alternate controls]","guideline":"alternate controls to be developed and implemented in the event that a system component cannot be sanitized, removed, or disconnected from the system are defined"}],"related":["MP-6","PL-2"],"references":[],"objectives":[{"label":"MA-05(01)(a)","prose":"","items":[{"label":"MA-05(01)(a)(01)","prose":"procedures for the use of maintenance personnel who lack appropriate security clearances or are not U.S. citizens are implemented and include approved organizational personnel who are fully cleared, have appropriate access authorizations, and are technically qualified escorting and supervising maintenance personnel without the needed access authorization during the performance of maintenance and diagnostic activities;"},{"label":"MA-05(01)(a)(02)","prose":"procedures for the use of maintenance personnel who lack appropriate security clearances or are not U.S. citizens are implemented and include all volatile information storage components within the system being sanitized and all non-volatile storage media being removed or physically disconnected from the system and secured prior to initiating maintenance or diagnostic activities;"}]},{"label":"MA-05(01)(b)","prose":"[Assignment: organization-defined alternate controls] are developed and implemented in the event that a system cannot be sanitized, removed, or disconnected from the system."}],"methods":[{"method":"Examine","objects":["Maintenance policy","procedures addressing maintenance personnel","system media protection policy","physical and environmental protection policy","list of maintenance personnel requiring escort/supervision","maintenance records","access control records","system security plan"]},{"method":"Interview","objects":["Organizational personnel with system maintenance responsibilities","organizational personnel with personnel security responsibilities","organizational personnel with physical access control responsibilities","organizational personnel with information security responsibilities","organizational personnel responsible for media sanitization","system/network administrators"]},{"method":"Test","objects":["Organizational processes for managing maintenance personnel without appropriate access","mechanisms supporting and/or implementing alternative security safeguards","mechanisms supporting and/or implementing information storage component sanitization"]}]},"MA-6":{"statement":[{"prose":"Obtain maintenance support and/or spare parts for [Assignment: organization-defined system components] within [Assignment: organization-defined time period] of failure."}],"discussion":["Organizations specify the system components that result in increased risk to organizational operations and assets, individuals, other organizations, or the Nation when the functionality provided by those components is not operational. Organizational actions to obtain maintenance support include having appropriate contracts in place."],"params":[{"id":"MA-06_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined system components]","guideline":"system components for which maintenance support and/or spare parts are obtained are defined"},{"id":"MA-06_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"time period within which maintenance support and/or spare parts are to be obtained after a failure are defined"}],"related":["CM-8","CP-2","CP-7","RA-7","SA-15","SI-13","SR-2","SR-3","SR-4"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Maintenance policy","procedures addressing system maintenance","service provider contracts","service-level agreements","inventory and availability of spare parts","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system maintenance responsibilities","organizational personnel with acquisition responsibilities","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Organizational processes for ensuring timely maintenance"]}]},"MP-1":{"statement":[{"label":"a.","prose":"Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:","items":[{"label":"1.","prose":"[Selection (one or more): organization-level; mission/business process-level; system-level] media protection policy that:","items":[{"label":"(a)","prose":"Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and"},{"label":"(b)","prose":"Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and"}]},{"label":"2.","prose":"Procedures to facilitate the implementation of the media protection policy and the associated media protection controls;"}]},{"label":"b.","prose":"Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the media protection policy and procedures; and"},{"label":"c.","prose":"Review and update the current media protection:","items":[{"label":"1.","prose":"Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and"},{"label":"2.","prose":"Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]."}]}],"discussion":["Media protection policy and procedures address the controls in the MP family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of media protection policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to media protection policy and procedures include assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure."],"params":[{"id":"MP-1_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]"},{"id":"MP-01_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the media protection policy is to be disseminated is/are defined"},{"id":"MP-01_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the media protection procedures are to be disseminated is/are defined"},{"id":"MP-01_ODP[03]","kind":"Selection","value":"[Selection (one or more): organization-level; mission/business process-level; system-level]"},{"id":"MP-01_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined official]","guideline":"an official to manage the media protection policy and procedures is defined"},{"id":"MP-01_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency with which the current media protection policy is reviewed and updated is defined"},{"id":"MP-01_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require the current media protection policy to be reviewed and updated are defined"},{"id":"MP-01_ODP[07]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency with which the current media protection procedures are reviewed and updated is defined"},{"id":"MP-01_ODP[08]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require media protection procedures to be reviewed and updated are defined"}],"related":["PM-9","PS-8","SI-12"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-12","url":"https://doi.org/10.6028/NIST.SP.800-12r1"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-39","url":"https://doi.org/10.6028/NIST.SP.800-39"},{"title":"SP 800-100","url":"https://doi.org/10.6028/NIST.SP.800-100"}],"objectives":[{"label":"MP-01a.","prose":"","items":[{"label":"MP-01a.[01]","prose":"a media protection policy is developed and documented;"},{"label":"MP-01a.[02]","prose":"the media protection policy is disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"MP-01a.[03]","prose":"media protection procedures to facilitate the implementation of the media protection policy and associated media protection controls are developed and documented;"},{"label":"MP-01a.[04]","prose":"the media protection procedures are disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"MP-01a.01","prose":"","items":[{"label":"MP-01a.01(a)","prose":"","items":[{"label":"MP-01a.01(a)[01]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] media protection policy addresses purpose;"},{"label":"MP-01a.01(a)[02]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] media protection policy addresses scope;"},{"label":"MP-01a.01(a)[03]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] media protection policy addresses roles;"},{"label":"MP-01a.01(a)[04]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] media protection policy addresses responsibilities;"},{"label":"MP-01a.01(a)[05]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] media protection policy addresses management commitment;"},{"label":"MP-01a.01(a)[06]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] media protection policy addresses coordination among organizational entities;"},{"label":"MP-01a.01(a)[07]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] media protection policy compliance;"}]},{"label":"MP-01a.01(b)","prose":"the media protection policy is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines;"}]}]},{"label":"MP-01b.","prose":"the [Assignment: organization-defined official] is designated to manage the development, documentation, and dissemination of the media protection policy and procedures."},{"label":"MP-01c.","prose":"","items":[{"label":"MP-01c.01","prose":"","items":[{"label":"MP-01c.01[01]","prose":"the current media protection policy is reviewed and updated [Assignment: organization-defined frequency];"},{"label":"MP-01c.01[02]","prose":"the current media protection policy is reviewed and updated following [Assignment: organization-defined events];"}]},{"label":"MP-01c.02","prose":"","items":[{"label":"MP-01c.02[01]","prose":"the current media protection procedures are reviewed and updated [Assignment: organization-defined frequency];"},{"label":"MP-01c.02[02]","prose":"the current media protection procedures are reviewed and updated following [Assignment: organization-defined events]."}]}]}],"methods":[{"method":"Examine","objects":["Media protection policy and procedures","organizational risk management strategy","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with media protection responsibilities","organizational personnel with information security and privacy responsibilities"]}]},"MP-2":{"statement":[{"prose":"Restrict access to [Assignment: organization-defined types of digital and/or non-digital media] to [Assignment: organization-defined personnel or roles]."}],"discussion":["System media includes digital and non-digital media. Digital media includes flash drives, diskettes, magnetic tapes, external or removable hard disk drives (e.g., solid state, magnetic), compact discs, and digital versatile discs. Non-digital media includes paper and microfilm. Denying access to patient medical records in a community hospital unless the individuals seeking access to such records are authorized healthcare providers is an example of restricting access to non-digital media. Limiting access to the design specifications stored on compact discs in the media library to individuals on the system development team is an example of restricting access to digital media."],"params":[{"id":"MP-2_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined types of digital and/or non-digital media]"},{"id":"MP-2_PRM_2","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]"},{"id":"MP-02_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined types of digital media]","guideline":"types of digital media to which access is restricted are defined"},{"id":"MP-02_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles authorized to access digital media is/are defined"},{"id":"MP-02_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined types of non-digital media]","guideline":"types of non-digital media to which access is restricted are defined"},{"id":"MP-02_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles authorized to access non-digital media is/are defined"}],"related":["AC-19","AU-9","CP-2","CP-9","CP-10","MA-5","MP-4","MP-6","PE-2","PE-3","SC-12","SC-13","SC-34","SI-12"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"FIPS 199","url":"https://doi.org/10.6028/NIST.FIPS.199"},{"title":"SP 800-111","url":"https://doi.org/10.6028/NIST.SP.800-111"}],"objectives":[{"label":"MP-02[01]","prose":"access to [Assignment: organization-defined types of digital media] is restricted to [Assignment: organization-defined personnel or roles];"},{"label":"MP-02[02]","prose":"access to [Assignment: organization-defined types of non-digital media] is restricted to [Assignment: organization-defined personnel or roles]."}],"methods":[{"method":"Examine","objects":["System media protection policy","procedures addressing media access restrictions","access control policy and procedures","physical and environmental protection policy and procedures","media storage facilities","access control records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system media protection responsibilities","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Organizational processes for restricting information media","mechanisms supporting and/or implementing media access restrictions"]}]},"MP-3":{"statement":[{"label":"a.","prose":"Mark system media indicating the distribution limitations, handling caveats, and applicable security markings (if any) of the information; and"},{"label":"b.","prose":"Exempt [Assignment: organization-defined types of media exempted from marking] from marking if the media remain within [Assignment: organization-defined controlled areas]."}],"discussion":["Security marking refers to the application or use of human-readable security attributes. Digital media includes diskettes, magnetic tapes, external or removable hard disk drives (e.g., solid state, magnetic), flash drives, compact discs, and digital versatile discs. Non-digital media includes paper and microfilm. Controlled unclassified information is defined by the National Archives and Records Administration along with the appropriate safeguarding and dissemination requirements for such information and is codified in [32 CFR 2002](#91f992fb-f668-4c91-a50f-0f05b95ccee3). Security markings are generally not required for media that contains information determined by organizations to be in the public domain or to be publicly releasable. Some organizations may require markings for public information indicating that the information is publicly releasable. System media marking reflects applicable laws, executive orders, directives, policies, regulations, standards, and guidelines."],"params":[{"id":"MP-03_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined types of media exempted from marking]","guideline":"types of system media exempt from marking when remaining in controlled areas are defined"},{"id":"MP-03_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined controlled areas]","guideline":"controlled areas where media is exempt from marking are defined"}],"related":["AC-16","CP-9","MP-5","PE-22","SI-12"],"references":[{"title":"EO 13556","url":"https://obamawhitehouse.archives.gov/the-press-office/2010/11/04/executive-order-13556-controlled-unclassified-information"},{"title":"32 CFR 2002","url":"https://www.federalregister.gov/documents/2016/09/14/2016-21665/controlled-unclassified-information"},{"title":"FIPS 199","url":"https://doi.org/10.6028/NIST.FIPS.199"}],"objectives":[{"label":"MP-03a.","prose":"system media is marked to indicate distribution limitations, handling caveats, and applicable security markings (if any) of the information;"},{"label":"MP-03b.","prose":"[Assignment: organization-defined types of media exempted from marking] remain within [Assignment: organization-defined controlled areas]."}],"methods":[{"method":"Examine","objects":["System media protection policy","procedures addressing media marking","physical and environmental protection policy and procedures","list of system media marking security attributes","designated controlled areas","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system media protection and marking responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for marking information media","mechanisms supporting and/or implementing media marking"]}]},"MP-4":{"statement":[{"label":"a.","prose":"Physically control and securely store [Assignment: organization-defined types of digital and/or non-digital media] within [Assignment: organization-defined controlled areas]; and"},{"label":"b.","prose":"Protect system media types defined in MP-4a until the media are destroyed or sanitized using approved equipment, techniques, and procedures."}],"discussion":["System media includes digital and non-digital media. Digital media includes flash drives, diskettes, magnetic tapes, external or removable hard disk drives (e.g., solid state, magnetic), compact discs, and digital versatile discs. Non-digital media includes paper and microfilm. Physically controlling stored media includes conducting inventories, ensuring procedures are in place to allow individuals to check out and return media to the library, and maintaining accountability for stored media. Secure storage includes a locked drawer, desk, or cabinet or a controlled media library. The type of media storage is commensurate with the security category or classification of the information on the media. Controlled areas are spaces that provide physical and procedural controls to meet the requirements established for protecting information and systems. Fewer controls may be needed for media that contains information determined to be in the public domain, publicly releasable, or have limited adverse impacts on organizations, operations, or individuals if accessed by other than authorized personnel. In these situations, physical access controls provide adequate protection."],"params":[{"id":"MP-4_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined types of digital and/or non-digital media]"},{"id":"MP-4_PRM_2","kind":"Assignment","value":"[Assignment: organization-defined controlled areas]"},{"id":"MP-04_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined types of digital media]","guideline":"types of digital media to be physically controlled are defined (if selected)"},{"id":"MP-04_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined types of non-digital media]","guideline":"types of non-digital media to be physically controlled are defined (if selected)"},{"id":"MP-04_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined types of digital media]","guideline":"types of digital media to be securely stored are defined (if selected)"},{"id":"MP-04_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined types of non-digital media]","guideline":"types of non-digital media to be securely stored are defined (if selected)"},{"id":"MP-04_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined controlled areas]","guideline":"controlled areas within which to securely store digital media are defined"},{"id":"MP-04_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined controlled areas]","guideline":"controlled areas within which to securely store non-digital media are defined"}],"related":["AC-19","CP-2","CP-6","CP-9","CP-10","MP-2","MP-7","PE-3","PL-2","SC-12","SC-13","SC-28","SC-34","SI-12"],"references":[{"title":"FIPS 199","url":"https://doi.org/10.6028/NIST.FIPS.199"},{"title":"SP 800-56A","url":"https://doi.org/10.6028/NIST.SP.800-56Ar3"},{"title":"SP 800-56B","url":"https://doi.org/10.6028/NIST.SP.800-56Br2"},{"title":"SP 800-56C","url":"https://doi.org/10.6028/NIST.SP.800-56Cr2"},{"title":"SP 800-57-1","url":"https://doi.org/10.6028/NIST.SP.800-57pt1r5"},{"title":"SP 800-57-2","url":"https://doi.org/10.6028/NIST.SP.800-57pt2r1"},{"title":"SP 800-57-3","url":"https://doi.org/10.6028/NIST.SP.800-57pt3r1"},{"title":"SP 800-111","url":"https://doi.org/10.6028/NIST.SP.800-111"}],"objectives":[{"label":"MP-04a.","prose":"","items":[{"label":"MP-04a.[01]","prose":"[Assignment: organization-defined types of digital media] are physically controlled;"},{"label":"MP-04a.[02]","prose":"[Assignment: organization-defined types of non-digital media] are physically controlled;"},{"label":"MP-04a.[03]","prose":"[Assignment: organization-defined types of digital media] are securely stored within [Assignment: organization-defined controlled areas];"},{"label":"MP-04a.[04]","prose":"[Assignment: organization-defined types of non-digital media] are securely stored within [Assignment: organization-defined controlled areas];"}]},{"label":"MP-04b.","prose":"system media types (defined in MP-04_ODP[01], MP-04_ODP[02], MP-04_ODP[03], MP-04_ODP[04]) are protected until the media are destroyed or sanitized using approved equipment, techniques, and procedures."}],"methods":[{"method":"Examine","objects":["System media protection policy","procedures addressing media storage","physical and environmental protection policy and procedures","access control policy and procedures","system media","designated controlled areas","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system media protection and storage responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for storing information media","mechanisms supporting and/or implementing secure media storage/media protection"]}]},"MP-5":{"statement":[{"label":"a.","prose":"Protect and control [Assignment: organization-defined types of system media] during transport outside of controlled areas using [Assignment: organization-defined controls];"},{"label":"b.","prose":"Maintain accountability for system media during transport outside of controlled areas;"},{"label":"c.","prose":"Document activities associated with the transport of system media; and"},{"label":"d.","prose":"Restrict the activities associated with the transport of system media to authorized personnel."}],"discussion":["System media includes digital and non-digital media. Digital media includes flash drives, diskettes, magnetic tapes, external or removable hard disk drives (e.g., solid state and magnetic), compact discs, and digital versatile discs. Non-digital media includes microfilm and paper. Controlled areas are spaces for which organizations provide physical or procedural controls to meet requirements established for protecting information and systems. Controls to protect media during transport include cryptography and locked containers. Cryptographic mechanisms can provide confidentiality and integrity protections depending on the mechanisms implemented. Activities associated with media transport include releasing media for transport, ensuring that media enters the appropriate transport processes, and the actual transport. Authorized transport and courier personnel may include individuals external to the organization. Maintaining accountability of media during transport includes restricting transport activities to authorized personnel and tracking and/or obtaining records of transport activities as the media moves through the transportation system to prevent and detect loss, destruction, or tampering. Organizations establish documentation requirements for activities associated with the transport of system media in accordance with organizational assessments of risk. Organizations maintain the flexibility to define record-keeping methods for the different types of media transport as part of a system of transport-related records."],"params":[{"id":"MP-5_PRM_2","kind":"Assignment","value":"[Assignment: organization-defined controls]"},{"id":"MP-05_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined types of system media]","guideline":"types of system media to protect and control during transport outside of controlled areas are defined"},{"id":"MP-05_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined controls]","guideline":"controls used to protect system media outside of controlled areas are defined"},{"id":"MP-05_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined controls]","guideline":"controls used to control system media outside of controlled areas are defined"}],"related":["AC-7","AC-19","CP-2","CP-9","MP-3","MP-4","PE-16","PL-2","SC-12","SC-13","SC-28","SC-34"],"references":[{"title":"FIPS 199","url":"https://doi.org/10.6028/NIST.FIPS.199"},{"title":"SP 800-60-1","url":"https://doi.org/10.6028/NIST.SP.800-60v1r1"},{"title":"SP 800-60-2","url":"https://doi.org/10.6028/NIST.SP.800-60v2r1"}],"objectives":[{"label":"MP-05a.","prose":"","items":[{"label":"MP-05a.[01]","prose":"[Assignment: organization-defined types of system media] are protected during transport outside of controlled areas using [Assignment: organization-defined controls];"},{"label":"MP-05a.[02]","prose":"[Assignment: organization-defined types of system media] are controlled during transport outside of controlled areas using [Assignment: organization-defined controls];"}]},{"label":"MP-05b.","prose":"accountability for system media is maintained during transport outside of controlled areas;"},{"label":"MP-05c.","prose":"activities associated with the transport of system media are documented;"},{"label":"MP-05d.","prose":"","items":[{"label":"MP-05d.[01]","prose":"personnel authorized to conduct media transport activities is/are identified;"},{"label":"MP-05d.[02]","prose":"activities associated with the transport of system media are restricted to identified authorized personnel."}]}],"methods":[{"method":"Examine","objects":["System media protection policy","procedures addressing media storage","physical and environmental protection policy and procedures","access control policy and procedures","authorized personnel list","system media","designated controlled areas","system security plan"]},{"method":"Interview","objects":["Organizational personnel with system media protection and storage responsibilities","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Organizational processes for storing information media","mechanisms supporting and/or implementing media storage/media protection"]}]},"MP-6":{"statement":[{"label":"a.","prose":"Sanitize [Assignment: organization-defined system media] prior to disposal, release out of organizational control, or release for reuse using [Assignment: organization-defined sanitization techniques and procedures]; and"},{"label":"b.","prose":"Employ sanitization mechanisms with the strength and integrity commensurate with the security category or classification of the information."}],"discussion":["Media sanitization applies to all digital and non-digital system media subject to disposal or reuse, whether or not the media is considered removable. Examples include digital media in scanners, copiers, printers, notebook computers, workstations, network components, mobile devices, and non-digital media (e.g., paper and microfilm). The sanitization process removes information from system media such that the information cannot be retrieved or reconstructed. Sanitization techniques—including clearing, purging, cryptographic erase, de-identification of personally identifiable information, and destruction—prevent the disclosure of information to unauthorized individuals when such media is reused or released for disposal. Organizations determine the appropriate sanitization methods, recognizing that destruction is sometimes necessary when other methods cannot be applied to media requiring sanitization. Organizations use discretion on the employment of approved sanitization techniques and procedures for media that contains information deemed to be in the public domain or publicly releasable or information deemed to have no adverse impact on organizations or individuals if released for reuse or disposal. Sanitization of non-digital media includes destruction, removing a classified appendix from an otherwise unclassified document, or redacting selected sections or words from a document by obscuring the redacted sections or words in a manner equivalent in effectiveness to removing them from the document. NSA standards and policies control the sanitization process for media that contains classified information. NARA policies control the sanitization process for controlled unclassified information."],"params":[{"id":"MP-6_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined system media]"},{"id":"MP-6_PRM_2","kind":"Assignment","value":"[Assignment: organization-defined sanitization techniques and procedures]"},{"id":"MP-06_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined system media]","guideline":"system media to be sanitized prior to disposal is defined"},{"id":"MP-06_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined system media]","guideline":"system media to be sanitized prior to release from organizational control is defined"},{"id":"MP-06_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined system media]","guideline":"system media to be sanitized prior to release for reuse is defined"},{"id":"MP-06_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined sanitization techniques and procedures]","guideline":"sanitization techniques and procedures to be used for sanitization prior to disposal are defined"},{"id":"MP-06_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined sanitization techniques and procedures]","guideline":"sanitization techniques and procedures to be used for sanitization prior to release from organizational control are defined"},{"id":"MP-06_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined sanitization techniques and procedures]","guideline":"sanitization techniques and procedures to be used for sanitization prior to release for reuse are defined"}],"related":["AC-3","AC-7","AU-11","MA-2","MA-3","MA-4","MA-5","PM-22","SI-12","SI-18","SI-19","SR-11"],"references":[{"title":"32 CFR 2002","url":"https://www.federalregister.gov/documents/2016/09/14/2016-21665/controlled-unclassified-information"},{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"NARA CUI","url":"https://www.archives.gov/cui"},{"title":"FIPS 199","url":"https://doi.org/10.6028/NIST.FIPS.199"},{"title":"SP 800-60-1","url":"https://doi.org/10.6028/NIST.SP.800-60v1r1"},{"title":"SP 800-60-2","url":"https://doi.org/10.6028/NIST.SP.800-60v2r1"},{"title":"SP 800-88","url":"https://doi.org/10.6028/NIST.SP.800-88r1"},{"title":"SP 800-124","url":"https://doi.org/10.6028/NIST.SP.800-124r1"},{"title":"IR 8023","url":"https://doi.org/10.6028/NIST.IR.8023"},{"title":"NSA MEDIA","url":"https://www.nsa.gov/resources/everyone/media-destruction"}],"objectives":[{"label":"MP-06a.","prose":"","items":[{"label":"MP-06a.[01]","prose":"[Assignment: organization-defined system media] is sanitized using [Assignment: organization-defined sanitization techniques and procedures] prior to disposal;"},{"label":"MP-06a.[02]","prose":"[Assignment: organization-defined system media] is sanitized using [Assignment: organization-defined sanitization techniques and procedures] prior to release from organizational control;"},{"label":"MP-06a.[03]","prose":"[Assignment: organization-defined system media] is sanitized using [Assignment: organization-defined sanitization techniques and procedures] prior to release for reuse;"}]},{"label":"MP-06b.","prose":"sanitization mechanisms with strength and integrity commensurate with the security category or classification of the information are employed."}],"methods":[{"method":"Examine","objects":["System media protection policy","procedures addressing media sanitization and disposal","applicable federal standards and policies addressing media sanitization policy","media sanitization records","system audit records","system design documentation","records retention and disposition policy","records retention and disposition procedures"]},{"method":"Interview","objects":["Organizational personnel with media sanitization responsibilities","organizational personnel with records retention and disposition responsibilities","organizational personnel with information security and privacy responsibilities","system/network administrators"]},{"method":"Test","objects":["Organizational processes for media sanitization","mechanisms supporting and/or implementing media sanitization"]}]},"MP-6(1)":{"statement":[{"prose":"Review, approve, track, document, and verify media sanitization and disposal actions."}],"discussion":["Organizations review and approve media to be sanitized to ensure compliance with records retention policies. Tracking and documenting actions include listing personnel who reviewed and approved sanitization and disposal actions, types of media sanitized, files stored on the media, sanitization methods used, date and time of the sanitization actions, personnel who performed the sanitization, verification actions taken and personnel who performed the verification, and the disposal actions taken. Organizations verify that the sanitization of the media was effective prior to disposal."],"params":[],"related":[],"references":[],"objectives":[{"label":"MP-06(01)[01]","prose":"media sanitization and disposal actions are reviewed;"},{"label":"MP-06(01)[02]","prose":"media sanitization and disposal actions are approved;"},{"label":"MP-06(01)[03]","prose":"media sanitization and disposal actions are tracked;"},{"label":"MP-06(01)[04]","prose":"media sanitization and disposal actions are documented;"},{"label":"MP-06(01)[05]","prose":"media sanitization and disposal actions are verified."}],"methods":[{"method":"Examine","objects":["System media protection policy","procedures addressing media sanitization and disposal","records retention and disposition policy","records retention and disposition procedures","media sanitization and disposal records","review records for media sanitization and disposal actions","approvals for media sanitization and disposal actions","tracking records"]},{"method":"Interview","objects":["Organizational personnel with system media sanitization and disposal responsibilities","organizational personnel with records retention and disposition responsibilities","organizational personnel with information security and privacy responsibilities","system/network administrators"]},{"method":"Test","objects":["Organizational processes for media sanitization","mechanisms supporting and/or implementing media sanitization","mechanisms supporting and/or implementing verification of media sanitization"]}]},"MP-6(2)":{"statement":[{"prose":"Test sanitization equipment and procedures [Assignment: organization-defined frequency] to ensure that the intended sanitization is being achieved."}],"discussion":["Testing of sanitization equipment and procedures may be conducted by qualified and authorized external entities, including federal agencies or external service providers."],"params":[{"id":"MP-6.2_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined frequency]"},{"id":"MP-06(02)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency with which to test sanitization equipment is defined"},{"id":"MP-06(02)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency with which to test sanitization procedures is defined"}],"related":[],"references":[],"objectives":[{"label":"MP-06(02)[01]","prose":"sanitization equipment is tested [Assignment: organization-defined frequency] to ensure that the intended sanitization is being achieved;"},{"label":"MP-06(02)[02]","prose":"sanitization procedures are tested [Assignment: organization-defined frequency] to ensure that the intended sanitization is being achieved."}],"methods":[{"method":"Examine","objects":["System media protection policy","procedures addressing media sanitization and disposal","procedures addressing testing of media sanitization equipment","results of media sanitization equipment and procedures testing","system audit records","records retention and disposition policy","records retention and disposition procedures","system security plan"]},{"method":"Interview","objects":["Organizational personnel with system media sanitization responsibilities","organizational personnel with records retention and disposition responsibilities","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Organizational processes for media sanitization","automated mechanisms supporting and/or implementing media sanitization","automated mechanisms supporting and/or implementing media sanitization procedures","sanitization equipment"]}]},"MP-6(3)":{"statement":[{"prose":"Apply nondestructive sanitization techniques to portable storage devices prior to connecting such devices to the system under the following circumstances: [Assignment: organization-defined circumstances]."}],"discussion":["Portable storage devices include external or removable hard disk drives (e.g., solid state, magnetic), optical discs, magnetic or optical tapes, flash memory devices, flash memory cards, and other external or removable disks. Portable storage devices can be obtained from untrustworthy sources and contain malicious code that can be inserted into or transferred to organizational systems through USB ports or other entry portals. While scanning storage devices is recommended, sanitization provides additional assurance that such devices are free of malicious code. Organizations consider nondestructive sanitization of portable storage devices when the devices are purchased from manufacturers or vendors prior to initial use or when organizations cannot maintain a positive chain of custody for the devices."],"params":[{"id":"MP-06(03)_ODP","kind":"Assignment","value":"[Assignment: organization-defined circumstances]","guideline":"circumstances requiring sanitization of portable storage devices are defined"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System media protection policy","procedures addressing media sanitization and disposal","information on portable storage devices for the system","list of circumstances requiring sanitization of portable storage devices","media sanitization records","audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system media sanitization responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for media sanitization of portable storage devices","mechanisms supporting and/or implementing media sanitization"]}]},"MP-7":{"statement":[{"label":"a.","prose":"[Selection: restrict; prohibit] the use of [Assignment: organization-defined types of system media] on [Assignment: organization-defined systems or system components] using [Assignment: organization-defined controls]; and"},{"label":"b.","prose":"Prohibit the use of portable storage devices in organizational systems when such devices have no identifiable owner."}],"discussion":["System media includes both digital and non-digital media. Digital media includes diskettes, magnetic tapes, flash drives, compact discs, digital versatile discs, and removable hard disk drives. Non-digital media includes paper and microfilm. Media use protections also apply to mobile devices with information storage capabilities. In contrast to [MP-2](#mp-2), which restricts user access to media, MP-7 restricts the use of certain types of media on systems, for example, restricting or prohibiting the use of flash drives or external hard disk drives. Organizations use technical and nontechnical controls to restrict the use of system media. Organizations may restrict the use of portable storage devices, for example, by using physical cages on workstations to prohibit access to certain external ports or disabling or removing the ability to insert, read, or write to such devices. Organizations may also limit the use of portable storage devices to only approved devices, including devices provided by the organization, devices provided by other approved organizations, and devices that are not personally owned. Finally, organizations may restrict the use of portable storage devices based on the type of device, such as by prohibiting the use of writeable, portable storage devices and implementing this restriction by disabling or removing the capability to write to such devices. Requiring identifiable owners for storage devices reduces the risk of using such devices by allowing organizations to assign responsibility for addressing known vulnerabilities in the devices."],"params":[{"id":"MP-07_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined types of system media]","guideline":"types of system media to be restricted or prohibited from use on systems or system components are defined"},{"id":"MP-07_ODP[02]","kind":"Selection","value":"[Selection: restrict; prohibit]"},{"id":"MP-07_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined systems or system components]","guideline":"systems or system components on which the use of specific types of system media to be restricted or prohibited are defined"},{"id":"MP-07_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined controls]","guideline":"controls to restrict or prohibit the use of specific types of system media on systems or system components are defined"}],"related":["AC-19","AC-20","PL-4","PM-12","SC-34","SC-41"],"references":[{"title":"FIPS 199","url":"https://doi.org/10.6028/NIST.FIPS.199"},{"title":"SP 800-111","url":"https://doi.org/10.6028/NIST.SP.800-111"}],"objectives":[{"label":"MP-07a.","prose":"the use of [Assignment: organization-defined types of system media] is [Selection: restrict; prohibit] on [Assignment: organization-defined systems or system components] using [Assignment: organization-defined controls];"},{"label":"MP-07b.","prose":"the use of portable storage devices in organizational systems is prohibited when such devices have no identifiable owner."}],"methods":[{"method":"Examine","objects":["System media protection policy","system use policy","procedures addressing media usage restrictions","rules of behavior","system design documentation","system configuration settings and associated documentation","audit records","system security plan"]},{"method":"Interview","objects":["Organizational personnel with system media use responsibilities","organizational personnel with information security responsibilities","system/network administrators"]},{"method":"Test","objects":["Organizational processes for media use","mechanisms restricting or prohibiting the use of system media on systems or system components"]}]},"PE-1":{"statement":[{"label":"a.","prose":"Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:","items":[{"label":"1.","prose":"[Selection (one or more): organization-level; mission/business process-level; system-level] physical and environmental protection policy that:","items":[{"label":"(a)","prose":"Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and"},{"label":"(b)","prose":"Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and"}]},{"label":"2.","prose":"Procedures to facilitate the implementation of the physical and environmental protection policy and the associated physical and environmental protection controls;"}]},{"label":"b.","prose":"Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the physical and environmental protection policy and procedures; and"},{"label":"c.","prose":"Review and update the current physical and environmental protection:","items":[{"label":"1.","prose":"Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and"},{"label":"2.","prose":"Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]."}]}],"discussion":["Physical and environmental protection policy and procedures address the controls in the PE family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of physical and environmental protection policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to physical and environmental protection policy and procedures include assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure."],"params":[{"id":"PE-1_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]"},{"id":"PE-01_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the physical and environmental protection policy is to be disseminated is/are defined"},{"id":"PE-01_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the physical and environmental protection procedures are to be disseminated is/are defined"},{"id":"PE-01_ODP[03]","kind":"Selection","value":"[Selection (one or more): organization-level; mission/business process-level; system-level]"},{"id":"PE-01_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined official]","guideline":"an official to manage the physical and environmental protection policy and procedures is defined"},{"id":"PE-01_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current physical and environmental protection policy is reviewed and updated is defined"},{"id":"PE-01_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require the current physical and environmental protection policy to be reviewed and updated are defined"},{"id":"PE-01_ODP[07]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current physical and environmental protection procedures are reviewed and updated is defined"},{"id":"PE-01_ODP[08]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require the physical and environmental protection procedures to be reviewed and updated are defined"}],"related":["AT-3","PM-9","PS-8","SI-12"],"references":[{"title":"SP 800-12","url":"https://doi.org/10.6028/NIST.SP.800-12r1"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-39","url":"https://doi.org/10.6028/NIST.SP.800-39"},{"title":"SP 800-100","url":"https://doi.org/10.6028/NIST.SP.800-100"}],"objectives":[{"label":"PE-01a.","prose":"","items":[{"label":"PE-01a.[01]","prose":"a physical and environmental protection policy is developed and documented;"},{"label":"PE-01a.[02]","prose":"the physical and environmental protection policy is disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"PE-01a.[03]","prose":"physical and environmental protection procedures to facilitate the implementation of the physical and environmental protection policy and associated physical and environmental protection controls are developed and documented;"},{"label":"PE-01a.[04]","prose":"the physical and environmental protection procedures are disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"PE-01a.01","prose":"","items":[{"label":"PE-01a.01(a)","prose":"","items":[{"label":"PE-01a.01(a)[01]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] physical and environmental protection policy addresses purpose;"},{"label":"PE-01a.01(a)[02]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] physical and environmental protection policy addresses scope;"},{"label":"PE-01a.01(a)[03]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] physical and environmental protection policy addresses roles;"},{"label":"PE-01a.01(a)[04]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] physical and environmental protection policy addresses responsibilities;"},{"label":"PE-01a.01(a)[05]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] physical and environmental protection policy addresses management commitment;"},{"label":"PE-01a.01(a)[06]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] physical and environmental protection policy addresses coordination among organizational entities;"},{"label":"PE-01a.01(a)[07]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] physical and environmental protection policy addresses compliance;"}]},{"label":"PE-01a.01(b)","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] physical and environmental protection policy is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines;"}]}]},{"label":"PE-01b.","prose":"the [Assignment: organization-defined official] is designated to manage the development, documentation, and dissemination of the physical and environmental protection policy and procedures;"},{"label":"PE-01c.","prose":"","items":[{"label":"PE-01c.01","prose":"","items":[{"label":"PE-01c.01[01]","prose":"the current physical and environmental protection policy is reviewed and updated [Assignment: organization-defined frequency];"},{"label":"PE-01c.01[02]","prose":"the current physical and environmental protection policy is reviewed and updated following [Assignment: organization-defined events];"}]},{"label":"PE-01c.02","prose":"","items":[{"label":"PE-01c.02[01]","prose":"the current physical and environmental protection procedures are reviewed and updated [Assignment: organization-defined frequency];"},{"label":"PE-01c.02[02]","prose":"the current physical and environmental protection procedures are reviewed and updated following [Assignment: organization-defined events]."}]}]}],"methods":[{"method":"Examine","objects":["Physical and environmental protection policy and procedures","system security plan","privacy plan","organizational risk management strategy","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with physical and environmental protection responsibilities","organizational personnel with information security and privacy responsibilities"]}]},"PE-2":{"statement":[{"label":"a.","prose":"Develop, approve, and maintain a list of individuals with authorized access to the facility where the system resides;"},{"label":"b.","prose":"Issue authorization credentials for facility access;"},{"label":"c.","prose":"Review the access list detailing authorized facility access by individuals [Assignment: organization-defined frequency]; and"},{"label":"d.","prose":"Remove individuals from the facility access list when access is no longer required."}],"discussion":["Physical access authorizations apply to employees and visitors. Individuals with permanent physical access authorization credentials are not considered visitors. Authorization credentials include ID badges, identification cards, and smart cards. Organizations determine the strength of authorization credentials needed consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Physical access authorizations may not be necessary to access certain areas within facilities that are designated as publicly accessible."],"params":[{"id":"PE-02_ODP","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to review the access list detailing authorized facility access by individuals is defined"}],"related":["AT-3","AU-9","IA-4","MA-5","MP-2","PE-3","PE-4","PE-5","PE-8","PM-12","PS-3","PS-4","PS-5","PS-6"],"references":[{"title":"FIPS 201-2","url":"https://doi.org/10.6028/NIST.FIPS.201-2"},{"title":"SP 800-73-4","url":"https://doi.org/10.6028/NIST.SP.800-73-4"},{"title":"SP 800-76-2","url":"https://doi.org/10.6028/NIST.SP.800-76-2"},{"title":"SP 800-78-4","url":"https://doi.org/10.6028/NIST.SP.800-78-4"}],"objectives":[{"label":"PE-02a.","prose":"","items":[{"label":"PE-02a.[01]","prose":"a list of individuals with authorized access to the facility where the system resides has been developed;"},{"label":"PE-02a.[02]","prose":"the list of individuals with authorized access to the facility where the system resides has been approved;"},{"label":"PE-02a.[03]","prose":"the list of individuals with authorized access to the facility where the system resides has been maintained;"}]},{"label":"PE-02b.","prose":"authorization credentials are issued for facility access;"},{"label":"PE-02c.","prose":"the access list detailing authorized facility access by individuals is reviewed [Assignment: organization-defined frequency];"},{"label":"PE-02d.","prose":"individuals are removed from the facility access list when access is no longer required."}],"methods":[{"method":"Examine","objects":["Physical and environmental protection policy","procedures addressing physical access authorizations","authorized personnel access list","authorization credentials","physical access list reviews","physical access termination records and associated documentation","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with physical access authorization responsibilities","organizational personnel with physical access to system facility","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for physical access authorizations","mechanisms supporting and/or implementing physical access authorizations"]}]},"PE-3":{"statement":[{"label":"a.","prose":"Enforce physical access authorizations at [Assignment: organization-defined entry and exit points] by:","items":[{"label":"1.","prose":"Verifying individual access authorizations before granting access to the facility; and"},{"label":"2.","prose":"Controlling ingress and egress to the facility using [Selection (one or more): [Assignment: organization-defined systems or devices]; guards];"}]},{"label":"b.","prose":"Maintain physical access audit logs for [Assignment: organization-defined entry or exit points];"},{"label":"c.","prose":"Control access to areas within the facility designated as publicly accessible by implementing the following controls: [Assignment: organization-defined physical access controls];"},{"label":"d.","prose":"Escort visitors and control visitor activity [Assignment: organization-defined circumstances];"},{"label":"e.","prose":"Secure keys, combinations, and other physical access devices;"},{"label":"f.","prose":"Inventory [Assignment: organization-defined physical access devices] every [Assignment: organization-defined frequency]; and"},{"label":"g.","prose":"Change combinations and keys [Assignment: organization-defined frequency] and/or when keys are lost, combinations are compromised, or when individuals possessing the keys or combinations are transferred or terminated."}],"discussion":["Physical access control applies to employees and visitors. Individuals with permanent physical access authorizations are not considered visitors. Physical access controls for publicly accessible areas may include physical access control logs/records, guards, or physical access devices and barriers to prevent movement from publicly accessible areas to non-public areas. Organizations determine the types of guards needed, including professional security staff, system users, or administrative staff. Physical access devices include keys, locks, combinations, biometric readers, and card readers. Physical access control systems comply with applicable laws, executive orders, directives, policies, regulations, standards, and guidelines. Organizations have flexibility in the types of audit logs employed. Audit logs can be procedural, automated, or some combination thereof. Physical access points can include facility access points, interior access points to systems that require supplemental access controls, or both. Components of systems may be in areas designated as publicly accessible with organizations controlling access to the components."],"params":[{"id":"PE-3_PRM_9","kind":"Assignment","value":"[Assignment: organization-defined frequency]"},{"id":"PE-03_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined entry and exit points]","guideline":"entry and exit points to the facility in which the system resides are defined"},{"id":"PE-03_ODP[02]","kind":"Selection","value":"[Selection (one or more): [Assignment: organization-defined systems or devices]; guards]"},{"id":"PE-03_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined systems or devices]","guideline":"physical access control systems or devices used to control ingress and egress to the facility are defined (if selected)"},{"id":"PE-03_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined entry or exit points]","guideline":"entry or exit points for which physical access logs are maintained are defined"},{"id":"PE-03_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined physical access controls]","guideline":"physical access controls to control access to areas within the facility designated as publicly accessible are defined"},{"id":"PE-03_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined circumstances]","guideline":"circumstances requiring visitor escorts and control of visitor activity are defined"},{"id":"PE-03_ODP[07]","kind":"Assignment","value":"[Assignment: organization-defined physical access devices]","guideline":"physical access devices to be inventoried are defined"},{"id":"PE-03_ODP[08]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to inventory physical access devices is defined"},{"id":"PE-03_ODP[09]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to change combinations is defined"},{"id":"PE-03_ODP[10]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to change keys is defined"}],"related":["AT-3","AU-2","AU-6","AU-9","AU-13","CP-10","IA-3","IA-8","MA-5","MP-2","MP-4","PE-2","PE-4","PE-5","PE-8","PS-2","PS-3","PS-6","PS-7","RA-3","SC-28","SI-4","SR-3"],"references":[{"title":"FIPS 201-2","url":"https://doi.org/10.6028/NIST.FIPS.201-2"},{"title":"SP 800-73-4","url":"https://doi.org/10.6028/NIST.SP.800-73-4"},{"title":"SP 800-76-2","url":"https://doi.org/10.6028/NIST.SP.800-76-2"},{"title":"SP 800-78-4","url":"https://doi.org/10.6028/NIST.SP.800-78-4"},{"title":"SP 800-116","url":"https://doi.org/10.6028/NIST.SP.800-116r1"}],"objectives":[{"label":"PE-03a.","prose":"","items":[{"label":"PE-03a.01","prose":"physical access authorizations are enforced at [Assignment: organization-defined entry and exit points] by verifying individual access authorizations before granting access to the facility;"},{"label":"PE-03a.02","prose":"physical access authorizations are enforced at [Assignment: organization-defined entry and exit points] by controlling ingress and egress to the facility using [Selection (one or more): [Assignment: organization-defined systems or devices]; guards];"}]},{"label":"PE-03b.","prose":"physical access audit logs are maintained for [Assignment: organization-defined entry or exit points];"},{"label":"PE-03c.","prose":"access to areas within the facility designated as publicly accessible are maintained by implementing [Assignment: organization-defined physical access controls];"},{"label":"PE-03d.","prose":"","items":[{"label":"PE-03d.[01]","prose":"visitors are escorted;"},{"label":"PE-03d.[02]","prose":"visitor activity is controlled [Assignment: organization-defined circumstances];"}]},{"label":"PE-03e.","prose":"","items":[{"label":"PE-03e.[01]","prose":"keys are secured;"},{"label":"PE-03e.[02]","prose":"combinations are secured;"},{"label":"PE-03e.[03]","prose":"other physical access devices are secured;"}]},{"label":"PE-03f.","prose":"[Assignment: organization-defined physical access devices] are inventoried [Assignment: organization-defined frequency];"},{"label":"PE-03g.","prose":"","items":[{"label":"PE-03g.[01]","prose":"combinations are changed [Assignment: organization-defined frequency], when combinations are compromised, or when individuals possessing the combinations are transferred or terminated;"},{"label":"PE-03g.[02]","prose":"keys are changed [Assignment: organization-defined frequency], when keys are lost, or when individuals possessing the keys are transferred or terminated."}]}],"methods":[{"method":"Examine","objects":["Physical and environmental protection policy","procedures addressing physical access control","physical access control logs or records","inventory records of physical access control devices","system entry and exit points","records of key and lock combination changes","storage locations for physical access control devices","physical access control devices"]},{"method":"Interview","objects":["Organizational personnel with physical access control responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for physical access control","mechanisms supporting and/or implementing physical access control","physical access control devices"]}]},"PE-3(1)":{"statement":[{"prose":"Enforce physical access authorizations to the system in addition to the physical access controls for the facility at [Assignment: organization-defined physical spaces]."}],"discussion":["Control of physical access to the system provides additional physical security for those areas within facilities where there is a concentration of system components."],"params":[{"id":"PE-03(01)_ODP","kind":"Assignment","value":"[Assignment: organization-defined physical spaces]","guideline":"physical spaces containing one or more components of the system are defined"}],"related":[],"references":[],"objectives":[{"label":"PE-03(01)[01]","prose":"physical access authorizations to the system are enforced;"},{"label":"PE-03(01)[02]","prose":"physical access controls are enforced for the facility at [Assignment: organization-defined physical spaces]."}],"methods":[{"method":"Examine","objects":["Physical and environmental protection policy","procedures addressing physical access control","physical access control logs or records","physical access control devices","access authorizations","access credentials","system entry and exit points","list of areas within the facility containing concentrations of system components or system components requiring additional physical protection"]},{"method":"Interview","objects":["Organizational personnel with physical access authorization responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for physical access control to the information system/components","mechanisms supporting and/or implementing physical access control for facility areas containing system components"]}]},"PE-4":{"statement":[{"prose":"Control physical access to [Assignment: organization-defined system distribution and transmission lines] within organizational facilities using [Assignment: organization-defined security controls]."}],"discussion":["Security controls applied to system distribution and transmission lines prevent accidental damage, disruption, and physical tampering. Such controls may also be necessary to prevent eavesdropping or modification of unencrypted transmissions. Security controls used to control physical access to system distribution and transmission lines include disconnected or locked spare jacks, locked wiring closets, protection of cabling by conduit or cable trays, and wiretapping sensors."],"params":[{"id":"PE-04_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined system distribution and transmission lines]","guideline":"system distribution and transmission lines requiring physical access controls are defined"},{"id":"PE-04_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined security controls]","guideline":"security controls to be implemented to control physical access to system distribution and transmission lines within the organizational facility are defined"}],"related":["AT-3","IA-4","MP-2","MP-4","PE-2","PE-3","PE-5","PE-9","SC-7","SC-8"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Physical and environmental protection policy","procedures addressing access control for transmission mediums","system design documentation","facility communications and wiring diagrams","list of physical security safeguards applied to system distribution and transmission lines","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with physical access control responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for access control to distribution and transmission lines","mechanisms/security safeguards supporting and/or implementing access control to distribution and transmission lines"]}]},"PE-5":{"statement":[{"prose":"Control physical access to output from [Assignment: organization-defined output devices] to prevent unauthorized individuals from obtaining the output."}],"discussion":["Controlling physical access to output devices includes placing output devices in locked rooms or other secured areas with keypad or card reader access controls and allowing access to authorized individuals only, placing output devices in locations that can be monitored by personnel, installing monitor or screen filters, and using headphones. Examples of output devices include monitors, printers, scanners, audio devices, facsimile machines, and copiers."],"params":[{"id":"PE-05_ODP","kind":"Assignment","value":"[Assignment: organization-defined output devices]","guideline":"output devices that require physical access control to output are defined"}],"related":["PE-2","PE-3","PE-4","PE-18"],"references":[{"title":"IR 8023","url":"https://doi.org/10.6028/NIST.IR.8023"}],"objectives":[],"methods":[{"method":"Examine","objects":["Physical and environmental protection policy","procedures addressing access control for display medium","facility layout of system components","actual displays from system components","list of output devices and associated outputs requiring physical access controls","physical access control logs or records for areas containing output devices and related outputs","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with physical access control responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for access control to output devices","mechanisms supporting and/or implementing access control to output devices"]}]},"PE-6":{"statement":[{"label":"a.","prose":"Monitor physical access to the facility where the system resides to detect and respond to physical security incidents;"},{"label":"b.","prose":"Review physical access logs [Assignment: organization-defined frequency] and upon occurrence of [Assignment: organization-defined events]; and"},{"label":"c.","prose":"Coordinate results of reviews and investigations with the organizational incident response capability."}],"discussion":["Physical access monitoring includes publicly accessible areas within organizational facilities. Examples of physical access monitoring include the employment of guards, video surveillance equipment (i.e., cameras), and sensor devices. Reviewing physical access logs can help identify suspicious activity, anomalous events, or potential threats. The reviews can be supported by audit logging controls, such as [AU-2](#au-2), if the access logs are part of an automated system. Organizational incident response capabilities include investigations of physical security incidents and responses to the incidents. Incidents include security violations or suspicious physical access activities. Suspicious physical access activities include accesses outside of normal work hours, repeated accesses to areas not normally accessed, accesses for unusual lengths of time, and out-of-sequence accesses."],"params":[{"id":"PE-06_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to review physical access logs is defined"},{"id":"PE-06_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events or potential indication of events requiring physical access logs to be reviewed are defined"}],"related":["AU-2","AU-6","AU-9","AU-12","CA-7","CP-10","IR-4","IR-8"],"references":[],"objectives":[{"label":"PE-06a.","prose":"physical access to the facility where the system resides is monitored to detect and respond to physical security incidents;"},{"label":"PE-06b.","prose":"","items":[{"label":"PE-06b.[01]","prose":"physical access logs are reviewed [Assignment: organization-defined frequency];"},{"label":"PE-06b.[02]","prose":"physical access logs are reviewed upon occurrence of [Assignment: organization-defined events];"}]},{"label":"PE-06c.","prose":"","items":[{"label":"PE-06c.[01]","prose":"results of reviews are coordinated with organizational incident response capabilities;"},{"label":"PE-06c.[02]","prose":"results of investigations are coordinated with organizational incident response capabilities."}]}],"methods":[{"method":"Examine","objects":["Physical and environmental protection policy","procedures addressing physical access monitoring","physical access logs or records","physical access monitoring records","physical access log reviews","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with physical access monitoring responsibilities","organizational personnel with incident response responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for monitoring physical access","mechanisms supporting and/or implementing physical access monitoring","mechanisms supporting and/or implementing the review of physical access logs"]}]},"PE-6(1)":{"statement":[{"prose":"Monitor physical access to the facility where the system resides using physical intrusion alarms and surveillance equipment."}],"discussion":["Physical intrusion alarms can be employed to alert security personnel when unauthorized access to the facility is attempted. Alarm systems work in conjunction with physical barriers, physical access control systems, and security guards by triggering a response when these other forms of security have been compromised or breached. Physical intrusion alarms can include different types of sensor devices, such as motion sensors, contact sensors, and broken glass sensors. Surveillance equipment includes video cameras installed at strategic locations throughout the facility."],"params":[],"related":[],"references":[],"objectives":[{"label":"PE-06(01)[01]","prose":"physical access to the facility where the system resides is monitored using physical intrusion alarms;"},{"label":"PE-06(01)[02]","prose":"physical access to the facility where the system resides is monitored using physical surveillance equipment."}],"methods":[{"method":"Examine","objects":["Physical and environmental protection policy","procedures addressing physical access monitoring","physical access logs or records","physical access monitoring records","physical access log reviews","system security plan","privacy plan","privacy impact assessment"]},{"method":"Interview","objects":["Organizational personnel with physical access monitoring responsibilities","organizational personnel with incident response responsibilities","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Organizational processes for monitoring physical intrusion alarms and surveillance equipment","mechanisms supporting and/or implementing physical access monitoring","mechanisms supporting and/or implementing physical intrusion alarms and surveillance equipment"]}]},"PE-6(4)":{"statement":[{"prose":"Monitor physical access to the system in addition to the physical access monitoring of the facility at [Assignment: organization-defined physical spaces]."}],"discussion":["Monitoring physical access to systems provides additional monitoring for those areas within facilities where there is a concentration of system components, including server rooms, media storage areas, and communications centers. Physical access monitoring can be coordinated with intrusion detection systems and system monitoring capabilities to provide comprehensive and integrated threat coverage for the organization."],"params":[{"id":"PE-06(04)_ODP","kind":"Assignment","value":"[Assignment: organization-defined physical spaces]","guideline":"physical spaces containing one or more components of the system are defined"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Physical and environmental protection policy","procedures addressing physical access monitoring","physical access control logs or records","physical access control devices","access authorizations","access credentials","list of areas within the facility containing concentrations of system components or system components requiring additional physical access monitoring","system security plan"]},{"method":"Interview","objects":["Organizational personnel with physical access monitoring responsibilities","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Organizational processes for monitoring physical access to the system","mechanisms supporting and/or implementing physical access monitoring for facility areas containing system components"]}]},"PE-8":{"statement":[{"label":"a.","prose":"Maintain visitor access records to the facility where the system resides for [Assignment: organization-defined time period];"},{"label":"b.","prose":"Review visitor access records [Assignment: organization-defined frequency]; and"},{"label":"c.","prose":"Report anomalies in visitor access records to [Assignment: organization-defined personnel]."}],"discussion":["Visitor access records include the names and organizations of individuals visiting, visitor signatures, forms of identification, dates of access, entry and departure times, purpose of visits, and the names and organizations of individuals visited. Access record reviews determine if access authorizations are current and are still required to support organizational mission and business functions. Access records are not required for publicly accessible areas."],"params":[{"id":"PE-08_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"time period for which to maintain visitor access records for the facility where the system resides is defined"},{"id":"PE-08_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to review visitor access records is defined"},{"id":"PE-08_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined personnel]","guideline":"personnel to whom visitor access records anomalies are reported to is/are defined"}],"related":["PE-2","PE-3","PE-6"],"references":[],"objectives":[{"label":"PE-08a.","prose":"visitor access records for the facility where the system resides are maintained for [Assignment: organization-defined time period];"},{"label":"PE-08b.","prose":"visitor access records are reviewed [Assignment: organization-defined frequency];"},{"label":"PE-08c.","prose":"visitor access records anomalies are reported to [Assignment: organization-defined personnel]."}],"methods":[{"method":"Examine","objects":["Physical and environmental protection policy","procedures addressing visitor access records","visitor access control logs or records","visitor access record or log reviews","system security plan","privacy plan","privacy impact assessment","privacy risk assessment documentation"]},{"method":"Interview","objects":["Organizational personnel with visitor access record responsibilities","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Organizational processes for maintaining and reviewing visitor access records","mechanisms supporting and/or implementing the maintenance and review of visitor access records"]}]},"PE-8(1)":{"statement":[{"prose":"Maintain and review visitor access records using [Assignment: organization-defined automated mechanisms]."}],"discussion":["Visitor access records may be stored and maintained in a database management system that is accessible by organizational personnel. Automated access to such records facilitates record reviews on a regular basis to determine if access authorizations are current and still required to support organizational mission and business functions."],"params":[{"id":"PE-8.1_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]"},{"id":"PE-08(01)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms used to maintain visitor access records are defined"},{"id":"PE-08(01)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms used to review visitor access records are defined"}],"related":[],"references":[],"objectives":[{"label":"PE-08(01)[01]","prose":"visitor access records are maintained using [Assignment: organization-defined automated mechanisms];"},{"label":"PE-08(01)[02]","prose":"visitor access records are reviewed using [Assignment: organization-defined automated mechanisms]."}],"methods":[{"method":"Examine","objects":["Physical and environmental protection policy","procedures addressing visitor access records","automated mechanisms supporting management of visitor access records","visitor access control logs or records","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with visitor access record responsibilities","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Organizational processes for maintaining and reviewing visitor access records","automated mechanisms supporting and/or implementing the maintenance and review of visitor access records"]}]},"PE-9":{"statement":[{"prose":"Protect power equipment and power cabling for the system from damage and destruction."}],"discussion":["Organizations determine the types of protection necessary for the power equipment and cabling employed at different locations that are both internal and external to organizational facilities and environments of operation. Types of power equipment and cabling include internal cabling and uninterruptable power sources in offices or data centers, generators and power cabling outside of buildings, and power sources for self-contained components such as satellites, vehicles, and other deployable systems."],"params":[],"related":["PE-4"],"references":[],"objectives":[{"label":"PE-09[01]","prose":"power equipment for the system is protected from damage and destruction;"},{"label":"PE-09[02]","prose":"power cabling for the system is protected from damage and destruction."}],"methods":[{"method":"Examine","objects":["Physical and environmental protection policy","procedures addressing power equipment/cabling protection","facilities housing power equipment/cabling","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with the responsibility to protect power equipment/cabling","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing the protection of power equipment/cabling"]}]},"PE-10":{"statement":[{"label":"a.","prose":"Provide the capability of shutting off power to [Assignment: organization-defined system or individual system components] in emergency situations;"},{"label":"b.","prose":"Place emergency shutoff switches or devices in [Assignment: organization-defined location] to facilitate access for authorized personnel; and"},{"label":"c.","prose":"Protect emergency power shutoff capability from unauthorized activation."}],"discussion":["Emergency power shutoff primarily applies to organizational facilities that contain concentrations of system resources, including data centers, mainframe computer rooms, server rooms, and areas with computer-controlled machinery."],"params":[{"id":"PE-10_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined system or individual system components]","guideline":"system or individual system components that require the capability to shut off power in emergency situations is/are defined"},{"id":"PE-10_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined location]","guideline":"location of emergency shutoff switches or devices by system or system component is defined"}],"related":["PE-15"],"references":[],"objectives":[{"label":"PE-10a.","prose":"the capability to shut off power to [Assignment: organization-defined system or individual system components] in emergency situations is provided;"},{"label":"PE-10b.","prose":"emergency shutoff switches or devices are placed in [Assignment: organization-defined location] to facilitate access for authorized personnel;"},{"label":"PE-10c.","prose":"the emergency power shutoff capability is protected from unauthorized activation."}],"methods":[{"method":"Examine","objects":["Physical and environmental protection policy","procedures addressing power source emergency shutoff","emergency shutoff controls or switches","locations housing emergency shutoff switches and devices","security safeguards protecting the emergency power shutoff capability from unauthorized activation","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with the responsibility for the emergency power shutoff capability (both implementing and using the capability)","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing emergency power shutoff"]}]},"PE-11":{"statement":[{"prose":"Provide an uninterruptible power supply to facilitate [Selection: an orderly shutdown of the system; transition of the system to long-term alternate power] in the event of a primary power source loss."}],"discussion":["An uninterruptible power supply (UPS) is an electrical system or mechanism that provides emergency power when there is a failure of the main power source. A UPS is typically used to protect computers, data centers, telecommunication equipment, or other electrical equipment where an unexpected power disruption could cause injuries, fatalities, serious mission or business disruption, or loss of data or information. A UPS differs from an emergency power system or backup generator in that the UPS provides near-instantaneous protection from unanticipated power interruptions from the main power source by providing energy stored in batteries, supercapacitors, or flywheels. The battery duration of a UPS is relatively short but provides sufficient time to start a standby power source, such as a backup generator, or properly shut down the system."],"params":[{"id":"PE-11_ODP","kind":"Selection","value":"[Selection: an orderly shutdown of the system; transition of the system to long-term alternate power]"}],"related":["AT-3","CP-2","CP-7"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Physical and environmental protection policy","procedures addressing emergency power","uninterruptible power supply","uninterruptible power supply documentation","uninterruptible power supply test records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with the responsibility for emergency power and/or planning","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing an uninterruptible power supply","the uninterruptable power supply"]}]},"PE-11(1)":{"statement":[{"prose":"Provide an alternate power supply for the system that is activated [Selection: manually; automatically] and that can maintain minimally required operational capability in the event of an extended loss of the primary power source."}],"discussion":["Provision of an alternate power supply with minimal operating capability can be satisfied by accessing a secondary commercial power supply or other external power supply."],"params":[{"id":"PE-11(01)_ODP","kind":"Selection","value":"[Selection: manually; automatically]"}],"related":[],"references":[],"objectives":[{"label":"PE-11(01)[01]","prose":"an alternate power supply provided for the system is activated [Selection: manually; automatically];"},{"label":"PE-11(01)[02]","prose":"the alternate power supply provided for the system can maintain minimally required operational capability in the event of an extended loss of the primary power source."}],"methods":[{"method":"Examine","objects":["Physical and environmental protection policy","procedures addressing emergency power","alternate power supply","alternate power supply documentation","alternate power supply test records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with the responsibility for emergency power and/or planning","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing an alternate power supply","the alternate power supply"]}]},"PE-12":{"statement":[{"prose":"Employ and maintain automatic emergency lighting for the system that activates in the event of a power outage or disruption and that covers emergency exits and evacuation routes within the facility."}],"discussion":["The provision of emergency lighting applies primarily to organizational facilities that contain concentrations of system resources, including data centers, server rooms, and mainframe computer rooms. Emergency lighting provisions for the system are described in the contingency plan for the organization. If emergency lighting for the system fails or cannot be provided, organizations consider alternate processing sites for power-related contingencies."],"params":[],"related":["CP-2","CP-7"],"references":[],"objectives":[{"label":"PE-12[01]","prose":"automatic emergency lighting that activates in the event of a power outage or disruption is employed for the system;"},{"label":"PE-12[02]","prose":"automatic emergency lighting that activates in the event of a power outage or disruption is maintained for the system;"},{"label":"PE-12[03]","prose":"automatic emergency lighting for the system covers emergency exits within the facility;"},{"label":"PE-12[04]","prose":"automatic emergency lighting for the system covers evacuation routes within the facility."}],"methods":[{"method":"Examine","objects":["Physical and environmental protection policy","procedures addressing emergency lighting","emergency lighting documentation","emergency lighting test records","emergency exits and evacuation routes","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with the responsibility for emergency lighting and/or planning","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing an emergency lighting capability"]}]},"PE-13":{"statement":[{"prose":"Employ and maintain fire detection and suppression systems that are supported by an independent energy source."}],"discussion":["The provision of fire detection and suppression systems applies primarily to organizational facilities that contain concentrations of system resources, including data centers, server rooms, and mainframe computer rooms. Fire detection and suppression systems that may require an independent energy source include sprinkler systems and smoke detectors. An independent energy source is an energy source, such as a microgrid, that is separate, or can be separated, from the energy sources providing power for the other parts of the facility."],"params":[],"related":["AT-3"],"references":[],"objectives":[{"label":"PE-13[01]","prose":"fire detection systems are employed;"},{"label":"PE-13[02]","prose":"employed fire detection systems are supported by an independent energy source;"},{"label":"PE-13[03]","prose":"employed fire detection systems are maintained;"},{"label":"PE-13[04]","prose":"fire suppression systems are employed;"},{"label":"PE-13[05]","prose":"employed fire suppression systems are supported by an independent energy source;"},{"label":"PE-13[06]","prose":"employed fire suppression systems are maintained."}],"methods":[{"method":"Examine","objects":["Physical and environmental protection policy","procedures addressing fire protection","fire suppression and detection devices/systems","fire suppression and detection devices/systems documentation","test records of fire suppression and detection devices/systems","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for fire detection and suppression devices/systems","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing fire suppression/detection devices/systems"]}]},"PE-13(1)":{"statement":[{"prose":"Employ fire detection systems that activate automatically and notify [Assignment: organization-defined personnel or roles] and [Assignment: organization-defined emergency responders] in the event of a fire."}],"discussion":["Organizations can identify personnel, roles, and emergency responders if individuals on the notification list need to have access authorizations or clearances (e.g., to enter to facilities where access is restricted due to the classification or impact level of information within the facility). Notification mechanisms may require independent energy sources to ensure that the notification capability is not adversely affected by the fire."],"params":[{"id":"PE-13(01)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to be notified in the event of a fire is/are defined"},{"id":"PE-13(01)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined emergency responders]","guideline":"emergency responders to be notified in the event of a fire are defined"}],"related":[],"references":[],"objectives":[{"label":"PE-13(01)[01]","prose":"fire detection systems that activate automatically are employed in the event of a fire;"},{"label":"PE-13(01)[02]","prose":"fire detection systems that notify [Assignment: organization-defined personnel or roles] automatically are employed in the event of a fire;"},{"label":"PE-13(01)[03]","prose":"fire detection systems that notify [Assignment: organization-defined emergency responders] automatically are employed in the event of a fire."}],"methods":[{"method":"Examine","objects":["Physical and environmental protection policy","procedures addressing fire protection","facility housing the information system","alarm service-level agreements","test records of fire suppression and detection devices/systems","fire suppression and detection devices/systems documentation","alerts/notifications of fire events","system security plan"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for fire detection and suppression devices/systems","organizational personnel with responsibilities for notifying appropriate personnel, roles, and emergency responders of fires","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing fire detection devices/systems","activation of fire detection devices/systems (simulated)","automated notifications"]}]},"PE-13(2)":{"statement":[{"label":"(a)","prose":"Employ fire suppression systems that activate automatically and notify [Assignment: organization-defined personnel or roles] and [Assignment: organization-defined emergency responders]; and"},{"label":"(b)","prose":"Employ an automatic fire suppression capability when the facility is not staffed on a continuous basis."}],"discussion":["Organizations can identify specific personnel, roles, and emergency responders if individuals on the notification list need to have appropriate access authorizations and/or clearances (e.g., to enter to facilities where access is restricted due to the impact level or classification of information within the facility). Notification mechanisms may require independent energy sources to ensure that the notification capability is not adversely affected by the fire."],"params":[{"id":"PE-13(02)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to be notified in the event of a fire is/are defined"},{"id":"PE-13(02)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined emergency responders]","guideline":"emergency responders to be notified in the event of a fire are defined"}],"related":[],"references":[],"objectives":[{"label":"PE-13(02)(a)","prose":"","items":[{"label":"PE-13(02)(a)[01]","prose":"fire suppression systems that activate automatically are employed;"},{"label":"PE-13(02)(a)[02]","prose":"fire suppression systems that notify [Assignment: organization-defined personnel or roles] automatically are employed;"},{"label":"PE-13(02)(a)[03]","prose":"fire suppression systems that notify [Assignment: organization-defined emergency responders] automatically are employed;"}]},{"label":"PE-13(02)(b)","prose":"an automatic fire suppression capability is employed when the facility is not staffed on a continuous basis."}],"methods":[{"method":"Examine","objects":["Physical and environmental protection policy","procedures addressing fire protection","fire suppression and detection devices/systems documentation","facility housing the system","alarm service-level agreements","test records of fire suppression and detection devices/systems","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for fire detection and suppression devices/systems","organizational personnel with responsibilities for providing automatic notifications of any activation of fire suppression devices/systems to appropriate personnel, roles, and emergency responders","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Automated mechanisms supporting and/or implementing fire suppression devices/systems","activation of fire suppression devices/systems (simulated)","automated notifications"]}]},"PE-14":{"statement":[{"label":"a.","prose":"Maintain [Selection (one or more): temperature; humidity; pressure; radiation; [Assignment: organization-defined environmental control]] levels within the facility where the system resides at [Assignment: organization-defined acceptable levels]; and"},{"label":"b.","prose":"Monitor environmental control levels [Assignment: organization-defined frequency]."}],"discussion":["The provision of environmental controls applies primarily to organizational facilities that contain concentrations of system resources (e.g., data centers, mainframe computer rooms, and server rooms). Insufficient environmental controls, especially in very harsh environments, can have a significant adverse impact on the availability of systems and system components that are needed to support organizational mission and business functions."],"params":[{"id":"PE-14_ODP[01]","kind":"Selection","value":"[Selection (one or more): temperature; humidity; pressure; radiation; [Assignment: organization-defined environmental control]]"},{"id":"PE-14_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined environmental control]","guideline":"environmental control(s) for which to maintain a specified level in the facility where the system resides are defined (if selected)"},{"id":"PE-14_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined acceptable levels]","guideline":"acceptable levels for environmental controls are defined"},{"id":"PE-14_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to monitor environmental control levels is defined"}],"related":["AT-3","CP-2"],"references":[],"objectives":[{"label":"PE-14a.","prose":"[Selection (one or more): temperature; humidity; pressure; radiation; [Assignment: organization-defined environmental control]] levels are maintained at [Assignment: organization-defined acceptable levels] within the facility where the system resides;"},{"label":"PE-14b.","prose":"environmental control levels are monitored [Assignment: organization-defined frequency]."}],"methods":[{"method":"Examine","objects":["Physical and environmental protection policy","procedures addressing temperature and humidity control","temperature and humidity controls","facility housing the system","temperature and humidity controls documentation","temperature and humidity records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for system environmental controls","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing the maintenance and monitoring of temperature and humidity levels"]}]},"PE-15":{"statement":[{"prose":"Protect the system from damage resulting from water leakage by providing master shutoff or isolation valves that are accessible, working properly, and known to key personnel."}],"discussion":["The provision of water damage protection primarily applies to organizational facilities that contain concentrations of system resources, including data centers, server rooms, and mainframe computer rooms. Isolation valves can be employed in addition to or in lieu of master shutoff valves to shut off water supplies in specific areas of concern without affecting entire organizations."],"params":[],"related":["AT-3","PE-10"],"references":[],"objectives":[{"label":"PE-15[01]","prose":"the system is protected from damage resulting from water leakage by providing master shutoff or isolation valves;"},{"label":"PE-15[02]","prose":"the master shutoff or isolation valves are accessible;"},{"label":"PE-15[03]","prose":"the master shutoff or isolation valves are working properly;"},{"label":"PE-15[04]","prose":"the master shutoff or isolation valves are known to key personnel."}],"methods":[{"method":"Examine","objects":["Physical and environmental protection policy","procedures addressing water damage protection","facility housing the system","master shutoff valves","list of key personnel with knowledge of location and activation procedures for master shutoff valves for the plumbing system","master shutoff valve documentation","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for system environmental controls","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Master water-shutoff valves","organizational process for activating master water shutoff"]}]},"PE-15(1)":{"statement":[{"prose":"Detect the presence of water near the system and alert [Assignment: organization-defined personnel or roles] using [Assignment: organization-defined automated mechanisms]."}],"discussion":["Automated mechanisms include notification systems, water detection sensors, and alarms."],"params":[{"id":"PE-15(01)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to be alerted when the presence of water is detected near the system is/are defined"},{"id":"PE-15(01)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms used to detect the presence of water near the system are defined"}],"related":[],"references":[],"objectives":[{"label":"PE-15(01)[01]","prose":"the presence of water near the system can be detected automatically;"},{"label":"PE-15(01)[02]","prose":"[Assignment: organization-defined personnel or roles] is/are alerted using [Assignment: organization-defined automated mechanisms]."}],"methods":[{"method":"Examine","objects":["Physical and environmental protection policy","procedures addressing water damage protection","facility housing the system","automated mechanisms for water shutoff valves","automated mechanisms for detecting the presence of water in the vicinity of the system","alerts/notifications of water detection in system facility","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for system environmental controls","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Automated mechanisms supporting and/or implementing water detection capabilities and alerts for the system"]}]},"PE-16":{"statement":[{"label":"a.","prose":"Authorize and control [Assignment: organization-defined types of system components] entering and exiting the facility; and"},{"label":"b.","prose":"Maintain records of the system components."}],"discussion":["Enforcing authorizations for entry and exit of system components may require restricting access to delivery areas and isolating the areas from the system and media libraries."],"params":[{"id":"PE-16_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined types of system components]"},{"id":"PE-16_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined types of system components]","guideline":"types of system components to be authorized and controlled when entering the facility are defined"},{"id":"PE-16_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined types of system components]","guideline":"types of system components to be authorized and controlled when exiting the facility are defined"}],"related":["CM-3","CM-8","MA-2","MA-3","MP-5","PE-20","SR-2","SR-3","SR-4","SR-6"],"references":[],"objectives":[{"label":"PE-16a.","prose":"","items":[{"label":"PE-16a.[01]","prose":"[Assignment: organization-defined types of system components] are authorized when entering the facility;"},{"label":"PE-16a.[02]","prose":"[Assignment: organization-defined types of system components] are controlled when entering the facility;"},{"label":"PE-16a.[03]","prose":"[Assignment: organization-defined types of system components] are authorized when exiting the facility;"},{"label":"PE-16a.[04]","prose":"[Assignment: organization-defined types of system components] are controlled when exiting the facility;"}]},{"label":"PE-16b.","prose":"records of the system components are maintained."}],"methods":[{"method":"Examine","objects":["Physical and environmental protection policy","procedures addressing the delivery and removal of system components from the facility","facility housing the system","records of items entering and exiting the facility","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for controlling system components entering and exiting the facility","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational process for authorizing, monitoring, and controlling system-related items entering and exiting the facility","mechanisms supporting and/or implementing, authorizing, monitoring, and controlling system-related items entering and exiting the facility"]}]},"PE-17":{"statement":[{"label":"a.","prose":"Determine and document the [Assignment: organization-defined alternate work sites] allowed for use by employees;"},{"label":"b.","prose":"Employ the following controls at alternate work sites: [Assignment: organization-defined controls];"},{"label":"c.","prose":"Assess the effectiveness of controls at alternate work sites; and"},{"label":"d.","prose":"Provide a means for employees to communicate with information security and privacy personnel in case of incidents."}],"discussion":["Alternate work sites include government facilities or the private residences of employees. While distinct from alternative processing sites, alternate work sites can provide readily available alternate locations during contingency operations. Organizations can define different sets of controls for specific alternate work sites or types of sites depending on the work-related activities conducted at the sites. Implementing and assessing the effectiveness of organization-defined controls and providing a means to communicate incidents at alternate work sites supports the contingency planning activities of organizations."],"params":[{"id":"PE-17_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined alternate work sites]","guideline":"alternate work sites allowed for use by employees are defined"},{"id":"PE-17_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined controls]","guideline":"controls to be employed at alternate work sites are defined"}],"related":["AC-17","AC-18","CP-7"],"references":[{"title":"SP 800-46","url":"https://doi.org/10.6028/NIST.SP.800-46r2"}],"objectives":[{"label":"PE-17a.","prose":"[Assignment: organization-defined alternate work sites] are determined and documented;"},{"label":"PE-17b.","prose":"[Assignment: organization-defined controls] are employed at alternate work sites;"},{"label":"PE-17c.","prose":"the effectiveness of controls at alternate work sites is assessed;"},{"label":"PE-17d.","prose":"a means for employees to communicate with information security and privacy personnel in case of incidents is provided."}],"methods":[{"method":"Examine","objects":["Physical and environmental protection policy","procedures addressing alternate work sites for organizational personnel","list of security controls required for alternate work sites","assessments of security controls at alternate work sites","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel approving the use of alternate work sites","organizational personnel using alternate work sites","organizational personnel assessing controls at alternate work sites","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Organizational processes for security and privacy at alternate work sites","mechanisms supporting alternate work sites","security and privacy controls employed at alternate work sites","means of communication between personnel at alternate work sites and security and privacy personnel"]}]},"PE-18":{"statement":[{"prose":"Position system components within the facility to minimize potential damage from [Assignment: organization-defined physical and environmental hazards] and to minimize the opportunity for unauthorized access."}],"discussion":["Physical and environmental hazards include floods, fires, tornadoes, earthquakes, hurricanes, terrorism, vandalism, an electromagnetic pulse, electrical interference, and other forms of incoming electromagnetic radiation. Organizations consider the location of entry points where unauthorized individuals, while not being granted access, might nonetheless be near systems. Such proximity can increase the risk of unauthorized access to organizational communications using wireless packet sniffers or microphones, or unauthorized disclosure of information."],"params":[{"id":"PE-18_ODP","kind":"Assignment","value":"[Assignment: organization-defined physical and environmental hazards]","guideline":"physical and environmental hazards that could result in potential damage to system components within the facility are defined"}],"related":["CP-2","PE-5","PE-19","PE-20","RA-3"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Physical and environmental protection policy","procedures addressing the positioning of system components","documentation providing the location and position of system components within the facility","locations housing system components within the facility","list of physical and environmental hazards with the potential to damage system components within the facility","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for positioning system components","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for positioning system components"]}]},"PE-19":{"statement":[{"prose":"Protect the system from information leakage due to electromagnetic signals emanations."}],"discussion":["Information leakage is the intentional or unintentional release of data or information to an untrusted environment from electromagnetic signals emanations. The security categories or classifications of systems (with respect to confidentiality), organizational security policies, and risk tolerance guide the selection of controls employed to protect systems against information leakage due to electromagnetic signals emanations."],"params":[],"related":["AC-18","PE-18","PE-20"],"references":[{"title":"FIPS 199","url":"https://doi.org/10.6028/NIST.FIPS.199"}],"objectives":[],"methods":[{"method":"Examine","objects":["Physical and environmental protection policy","procedures addressing information leakage due to electromagnetic signal emanations","mechanisms protecting the system against electronic signal emanations","facility housing the system","records from electromagnetic signal emanation tests","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with responsibilities for system environmental controls","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing protection from information leakage due to electromagnetic signal emanations"]}]},"PL-1":{"statement":[{"label":"a.","prose":"Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:","items":[{"label":"1.","prose":"[Selection (one or more): organization-level; mission/business process-level; system-level] planning policy that:","items":[{"label":"(a)","prose":"Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and"},{"label":"(b)","prose":"Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and"}]},{"label":"2.","prose":"Procedures to facilitate the implementation of the planning policy and the associated planning controls;"}]},{"label":"b.","prose":"Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the planning policy and procedures; and"},{"label":"c.","prose":"Review and update the current planning:","items":[{"label":"1.","prose":"Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and"},{"label":"2.","prose":"Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]."}]}],"discussion":["Planning policy and procedures for the controls in the PL family implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on their development. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission level or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission/business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to planning policy and procedures include, but are not limited to, assessment or audit findings, security incidents or breaches, or changes in laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure."],"params":[{"id":"PL-1_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]"},{"id":"PL-01_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the planning policy is to be disseminated is/are defined"},{"id":"PL-01_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the planning procedures are to be disseminated is/are defined"},{"id":"PL-01_ODP[03]","kind":"Selection","value":"[Selection (one or more): organization-level; mission/business process-level; system-level]"},{"id":"PL-01_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined official]","guideline":"an official to manage the planning policy and procedures is defined"},{"id":"PL-01_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency with which the current planning policy is reviewed and updated is defined"},{"id":"PL-01_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require the current planning policy to be reviewed and updated are defined"},{"id":"PL-01_ODP[07]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency with which the current planning procedures are reviewed and updated is defined"},{"id":"PL-01_ODP[08]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require procedures to be reviewed and updated are defined"}],"related":["PM-9","PS-8","SI-12"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-12","url":"https://doi.org/10.6028/NIST.SP.800-12r1"},{"title":"SP 800-18","url":"https://doi.org/10.6028/NIST.SP.800-18r1"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-39","url":"https://doi.org/10.6028/NIST.SP.800-39"},{"title":"SP 800-100","url":"https://doi.org/10.6028/NIST.SP.800-100"}],"objectives":[{"label":"PL-01a.","prose":"","items":[{"label":"PL-01a.[01]","prose":"a planning policy is developed and documented."},{"label":"PL-01a.[02]","prose":"the planning policy is disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"PL-01a.[03]","prose":"planning procedures to facilitate the implementation of the planning policy and associated planning controls are developed and documented;"},{"label":"PL-01a.[04]","prose":"the planning procedures are disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"PL-01a.01","prose":"","items":[{"label":"PL-01a.01(a)","prose":"","items":[{"label":"PL-01a.01(a)[01]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] planning policy addresses purpose;"},{"label":"PL-01a.01(a)[02]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] planning policy addresses scope;"},{"label":"PL-01a.01(a)[03]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] planning policy addresses roles;"},{"label":"PL-01a.01(a)[04]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] planning policy addresses responsibilities;"},{"label":"PL-01a.01(a)[05]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] planning policy addresses management commitment;"},{"label":"PL-01a.01(a)[06]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] planning policy addresses coordination among organizational entities;"},{"label":"PL-01a.01(a)[07]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] planning policy addresses compliance;"}]},{"label":"PL-01a.01(b)","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] planning policy is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines;"}]}]},{"label":"PL-01b.","prose":"the [Assignment: organization-defined official] is designated to manage the development, documentation, and dissemination of the planning policy and procedures;"},{"label":"PL-01c.","prose":"","items":[{"label":"PL-01c.01","prose":"","items":[{"label":"PL-01c.01[01]","prose":"the current planning policy is reviewed and updated [Assignment: organization-defined frequency];"},{"label":"PL-01c.01[02]","prose":"the current planning policy is reviewed and updated following [Assignment: organization-defined events];"}]},{"label":"PL-01c.02","prose":"","items":[{"label":"PL-01c.02[01]","prose":"the current planning procedures are reviewed and updated [Assignment: organization-defined frequency];"},{"label":"PL-01c.02[02]","prose":"the current planning procedures are reviewed and updated following [Assignment: organization-defined events]."}]}]}],"methods":[{"method":"Examine","objects":["Planning policy and procedures","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with planning responsibilities","organizational personnel with information security and privacy responsibilities"]}]},"PL-2":{"statement":[{"label":"a.","prose":"Develop security and privacy plans for the system that:","items":[{"label":"1.","prose":"Are consistent with the organization’s enterprise architecture;"},{"label":"2.","prose":"Explicitly define the constituent system components;"},{"label":"3.","prose":"Describe the operational context of the system in terms of mission and business processes;"},{"label":"4.","prose":"Identify the individuals that fulfill system roles and responsibilities;"},{"label":"5.","prose":"Identify the information types processed, stored, and transmitted by the system;"},{"label":"6.","prose":"Provide the security categorization of the system, including supporting rationale;"},{"label":"7.","prose":"Describe any specific threats to the system that are of concern to the organization;"},{"label":"8.","prose":"Provide the results of a privacy risk assessment for systems processing personally identifiable information;"},{"label":"9.","prose":"Describe the operational environment for the system and any dependencies on or connections to other systems or system components;"},{"label":"10.","prose":"Provide an overview of the security and privacy requirements for the system;"},{"label":"11.","prose":"Identify any relevant control baselines or overlays, if applicable;"},{"label":"12.","prose":"Describe the controls in place or planned for meeting the security and privacy requirements, including a rationale for any tailoring decisions;"},{"label":"13.","prose":"Include risk determinations for security and privacy architecture and design decisions;"},{"label":"14.","prose":"Include security- and privacy-related activities affecting the system that require planning and coordination with [Assignment: organization-defined individuals or groups]; and"},{"label":"15.","prose":"Are reviewed and approved by the authorizing official or designated representative prior to plan implementation."}]},{"label":"b.","prose":"Distribute copies of the plans and communicate subsequent changes to the plans to [Assignment: organization-defined personnel or roles];"},{"label":"c.","prose":"Review the plans [Assignment: organization-defined frequency];"},{"label":"d.","prose":"Update the plans to address changes to the system and environment of operation or problems identified during plan implementation or control assessments; and"},{"label":"e.","prose":"Protect the plans from unauthorized disclosure and modification."}],"discussion":["System security and privacy plans are scoped to the system and system components within the defined authorization boundary and contain an overview of the security and privacy requirements for the system and the controls selected to satisfy the requirements. The plans describe the intended application of each selected control in the context of the system with a sufficient level of detail to correctly implement the control and to subsequently assess the effectiveness of the control. The control documentation describes how system-specific and hybrid controls are implemented and the plans and expectations regarding the functionality of the system. System security and privacy plans can also be used in the design and development of systems in support of life cycle-based security and privacy engineering processes. System security and privacy plans are living documents that are updated and adapted throughout the system development life cycle (e.g., during capability determination, analysis of alternatives, requests for proposal, and design reviews). [Section 2.1](#c3397cc9-83c6-4459-adb2-836739dc1b94) describes the different types of requirements that are relevant to organizations during the system development life cycle and the relationship between requirements and controls.","Organizations may develop a single, integrated security and privacy plan or maintain separate plans. Security and privacy plans relate security and privacy requirements to a set of controls and control enhancements. The plans describe how the controls and control enhancements meet the security and privacy requirements but do not provide detailed, technical descriptions of the design or implementation of the controls and control enhancements. Security and privacy plans contain sufficient information (including specifications of control parameter values for selection and assignment operations explicitly or by reference) to enable a design and implementation that is unambiguously compliant with the intent of the plans and subsequent determinations of risk to organizational operations and assets, individuals, other organizations, and the Nation if the plan is implemented.","Security and privacy plans need not be single documents. The plans can be a collection of various documents, including documents that already exist. Effective security and privacy plans make extensive use of references to policies, procedures, and additional documents, including design and implementation specifications where more detailed information can be obtained. The use of references helps reduce the documentation associated with security and privacy programs and maintains the security- and privacy-related information in other established management and operational areas, including enterprise architecture, system development life cycle, systems engineering, and acquisition. Security and privacy plans need not contain detailed contingency plan or incident response plan information but can instead provide—explicitly or by reference—sufficient information to define what needs to be accomplished by those plans.","Security- and privacy-related activities that may require coordination and planning with other individuals or groups within the organization include assessments, audits, inspections, hardware and software maintenance, acquisition and supply chain risk management, patch management, and contingency plan testing. Planning and coordination include emergency and nonemergency (i.e., planned or non-urgent unplanned) situations. The process defined by organizations to plan and coordinate security- and privacy-related activities can also be included in other documents, as appropriate."],"params":[{"id":"PL-02_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined individuals or groups]","guideline":"individuals or groups with whom security and privacy-related activities affecting the system that require planning and coordination is/are assigned"},{"id":"PL-02_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to receive distributed copies of the system security and privacy plans is/are assigned"},{"id":"PL-02_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency to review system security and privacy plans is defined"}],"related":["AC-2","AC-6","AC-14","AC-17","AC-20","CA-2","CA-3","CA-7","CM-9","CM-13","CP-2","CP-4","IR-4","IR-8","MA-4","MA-5","MP-4","MP-5","PL-7","PL-8","PL-10","PL-11","PM-1","PM-7","PM-8","PM-9","PM-10","PM-11","RA-3","RA-8","RA-9","SA-5","SA-17","SA-22","SI-12","SR-2","SR-4"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-18","url":"https://doi.org/10.6028/NIST.SP.800-18r1"},{"title":"SP 800-37","url":"https://doi.org/10.6028/NIST.SP.800-37r2"},{"title":"SP 800-160-1","url":"https://doi.org/10.6028/NIST.SP.800-160v1"},{"title":"SP 800-160-2","url":"https://doi.org/10.6028/NIST.SP.800-160v2"}],"objectives":[{"label":"PL-02a.","prose":"","items":[{"label":"PL-02a.01","prose":"","items":[{"label":"PL-02a.01[01]","prose":"a security plan for the system is developed that is consistent with the organization’s enterprise architecture;"},{"label":"PL-02a.01[02]","prose":"a privacy plan for the system is developed that is consistent with the organization’s enterprise architecture;"}]},{"label":"PL-02a.02","prose":"","items":[{"label":"PL-02a.02[01]","prose":"a security plan for the system is developed that explicitly defines the constituent system components;"},{"label":"PL-02a.02[02]","prose":"a privacy plan for the system is developed that explicitly defines the constituent system components;"}]},{"label":"PL-02a.03","prose":"","items":[{"label":"PL-02a.03[01]","prose":"a security plan for the system is developed that describes the operational context of the system in terms of mission and business processes;"},{"label":"PL-02a.03[02]","prose":"a privacy plan for the system is developed that describes the operational context of the system in terms of mission and business processes;"}]},{"label":"PL-02a.04","prose":"","items":[{"label":"PL-02a.04[01]","prose":"a security plan for the system is developed that identifies the individuals that fulfill system roles and responsibilities;"},{"label":"PL-02a.04[02]","prose":"a privacy plan for the system is developed that identifies the individuals that fulfill system roles and responsibilities;"}]},{"label":"PL-02a.05","prose":"","items":[{"label":"PL-02a.05[01]","prose":"a security plan for the system is developed that identifies the information types processed, stored, and transmitted by the system;"},{"label":"PL-02a.05[02]","prose":"a privacy plan for the system is developed that identifies the information types processed, stored, and transmitted by the system;"}]},{"label":"PL-02a.06","prose":"","items":[{"label":"PL-02a.06[01]","prose":"a security plan for the system is developed that provides the security categorization of the system, including supporting rationale;"},{"label":"PL-02a.06[02]","prose":"a privacy plan for the system is developed that provides the security categorization of the system, including supporting rationale;"}]},{"label":"PL-02a.07","prose":"","items":[{"label":"PL-02a.07[01]","prose":"a security plan for the system is developed that describes any specific threats to the system that are of concern to the organization;"},{"label":"PL-02a.07[02]","prose":"a privacy plan for the system is developed that describes any specific threats to the system that are of concern to the organization;"}]},{"label":"PL-02a.08","prose":"","items":[{"label":"PL-02a.08[01]","prose":"a security plan for the system is developed that provides the results of a privacy risk assessment for systems processing personally identifiable information;"},{"label":"PL-02a.08[02]","prose":"a privacy plan for the system is developed that provides the results of a privacy risk assessment for systems processing personally identifiable information;"}]},{"label":"PL-02a.09","prose":"","items":[{"label":"PL-02a.09[01]","prose":"a security plan for the system is developed that describes the operational environment for the system and any dependencies on or connections to other systems or system components;"},{"label":"PL-02a.09[02]","prose":"a privacy plan for the system is developed that describes the operational environment for the system and any dependencies on or connections to other systems or system components;"}]},{"label":"PL-02a.10","prose":"","items":[{"label":"PL-02a.10[01]","prose":"a security plan for the system is developed that provides an overview of the security requirements for the system;"},{"label":"PL-02a.10[02]","prose":"a privacy plan for the system is developed that provides an overview of the privacy requirements for the system;"}]},{"label":"PL-02a.11","prose":"","items":[{"label":"PL-02a.11[01]","prose":"a security plan for the system is developed that identifies any relevant control baselines or overlays, if applicable;"},{"label":"PL-02a.11[02]","prose":"a privacy plan for the system is developed that identifies any relevant control baselines or overlays, if applicable;"}]},{"label":"PL-02a.12","prose":"","items":[{"label":"PL-02a.12[01]","prose":"a security plan for the system is developed that describes the controls in place or planned for meeting the security requirements, including rationale for any tailoring decisions;"},{"label":"PL-02a.12[02]","prose":"a privacy plan for the system is developed that describes the controls in place or planned for meeting the privacy requirements, including rationale for any tailoring decisions;"}]},{"label":"PL-02a.13","prose":"","items":[{"label":"PL-02a.13[01]","prose":"a security plan for the system is developed that includes risk determinations for security architecture and design decisions;"},{"label":"PL-02a.13[02]","prose":"a privacy plan for the system is developed that includes risk determinations for privacy architecture and design decisions;"}]},{"label":"PL-02a.14","prose":"","items":[{"label":"PL-02a.14[01]","prose":"a security plan for the system is developed that includes security-related activities affecting the system that require planning and coordination with [Assignment: organization-defined individuals or groups];"},{"label":"PL-02a.14[02]","prose":"a privacy plan for the system is developed that includes privacy-related activities affecting the system that require planning and coordination with [Assignment: organization-defined individuals or groups];"}]},{"label":"PL-02a.15","prose":"","items":[{"label":"PL-02a.15[01]","prose":"a security plan for the system is developed that is reviewed and approved by the authorizing official or designated representative prior to plan implementation;"},{"label":"PL-02a.15[02]","prose":"a privacy plan for the system is developed that is reviewed and approved by the authorizing official or designated representative prior to plan implementation."}]}]},{"label":"PL-02b.","prose":"","items":[{"label":"PL-02b.[01]","prose":"copies of the plans are distributed to [Assignment: organization-defined personnel or roles];"},{"label":"PL-02b.[02]","prose":"subsequent changes to the plans are communicated to [Assignment: organization-defined personnel or roles];"}]},{"label":"PL-02c.","prose":"plans are reviewed [Assignment: organization-defined frequency];"},{"label":"PL-02d.","prose":"","items":[{"label":"PL-02d.[01]","prose":"plans are updated to address changes to the system and environment of operations;"},{"label":"PL-02d.[02]","prose":"plans are updated to address problems identified during the plan implementation;"},{"label":"PL-02d.[03]","prose":"plans are updated to address problems identified during control assessments;"}]},{"label":"PL-02e.","prose":"","items":[{"label":"PL-02e.[01]","prose":"plans are protected from unauthorized disclosure;"},{"label":"PL-02e.[02]","prose":"plans are protected from unauthorized modification."}]}],"methods":[{"method":"Examine","objects":["Security and privacy planning policy","procedures addressing system security and privacy plan development and implementation","procedures addressing security and privacy plan reviews and updates","enterprise architecture documentation","system security plan","privacy plan","records of system security and privacy plan reviews and updates","security and privacy architecture and design documentation"]},{"method":"Interview","objects":["Organizational personnel with system security and privacy planning and plan implementation responsibilities","system developers","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Organizational processes for system security and privacy plan development, review, update, and approval","mechanisms supporting the system security and privacy plan"]}]},"PL-4":{"statement":[{"label":"a.","prose":"Establish and provide to individuals requiring access to the system, the rules that describe their responsibilities and expected behavior for information and system usage, security, and privacy;"},{"label":"b.","prose":"Receive a documented acknowledgment from such individuals, indicating that they have read, understand, and agree to abide by the rules of behavior, before authorizing access to information and the system;"},{"label":"c.","prose":"Review and update the rules of behavior [Assignment: organization-defined frequency]; and"},{"label":"d.","prose":"Require individuals who have acknowledged a previous version of the rules of behavior to read and re-acknowledge [Selection (one or more): [Assignment: organization-defined frequency]; when the rules are revised or updated]."}],"discussion":["Rules of behavior represent a type of access agreement for organizational users. Other types of access agreements include nondisclosure agreements, conflict-of-interest agreements, and acceptable use agreements (see [PS-6](#ps-6)). Organizations consider rules of behavior based on individual user roles and responsibilities and differentiate between rules that apply to privileged users and rules that apply to general users. Establishing rules of behavior for some types of non-organizational users, including individuals who receive information from federal systems, is often not feasible given the large number of such users and the limited nature of their interactions with the systems. Rules of behavior for organizational and non-organizational users can also be established in [AC-8](#ac-8). The related controls section provides a list of controls that are relevant to organizational rules of behavior. [PL-4b](#pl-4_smt.b), the documented acknowledgment portion of the control, may be satisfied by the literacy training and awareness and role-based training programs conducted by organizations if such training includes rules of behavior. Documented acknowledgements for rules of behavior include electronic or physical signatures and electronic agreement check boxes or radio buttons."],"params":[{"id":"PL-04_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency for reviewing and updating the rules of behavior is defined"},{"id":"PL-04_ODP[02]","kind":"Selection","value":"[Selection (one or more): [Assignment: organization-defined frequency]; when the rules are revised or updated]"},{"id":"PL-04_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency for individuals to read and re-acknowledge the rules of behavior is defined (if selected)"}],"related":["AC-2","AC-6","AC-8","AC-9","AC-17","AC-18","AC-19","AC-20","AT-2","AT-3","CM-11","IA-2","IA-4","IA-5","MP-7","PS-6","PS-8","SA-5","SI-12"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-18","url":"https://doi.org/10.6028/NIST.SP.800-18r1"}],"objectives":[{"label":"PL-04a.","prose":"","items":[{"label":"PL-04a.[01]","prose":"rules that describe responsibilities and expected behavior for information and system usage, security, and privacy are established for individuals requiring access to the system;"},{"label":"PL-04a.[02]","prose":"rules that describe responsibilities and expected behavior for information and system usage, security, and privacy are provided to individuals requiring access to the system;"}]},{"label":"PL-04b.","prose":"before authorizing access to information and the system, a documented acknowledgement from such individuals indicating that they have read, understand, and agree to abide by the rules of behavior is received;"},{"label":"PL-04c.","prose":"rules of behavior are reviewed and updated [Assignment: organization-defined frequency];"},{"label":"PL-04d.","prose":"individuals who have acknowledged a previous version of the rules of behavior are required to read and reacknowledge [Selection (one or more): [Assignment: organization-defined frequency]; when the rules are revised or updated]."}],"methods":[{"method":"Examine","objects":["Security and privacy planning policy","procedures addressing rules of behavior for system users","rules of behavior","signed acknowledgements","records for rules of behavior reviews and updates","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with responsibility for establishing, reviewing, and updating rules of behavior","organizational personnel with responsibility for literacy training and awareness and role-based training","organizational personnel who are authorized users of the system and have signed and resigned rules of behavior","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Organizational processes for establishing, reviewing, disseminating, and updating rules of behavior","mechanisms supporting and/or implementing the establishment, review, dissemination, and update of rules of behavior"]}]},"PL-4(1)":{"statement":[{"prose":"Include in the rules of behavior, restrictions on:"},{"label":"(a)","prose":"Use of social media, social networking sites, and external sites/applications;"},{"label":"(b)","prose":"Posting organizational information on public websites; and"},{"label":"(c)","prose":"Use of organization-provided identifiers (e.g., email addresses) and authentication secrets (e.g., passwords) for creating accounts on external sites/applications."}],"discussion":["Social media, social networking, and external site/application usage restrictions address rules of behavior related to the use of social media, social networking, and external sites when organizational personnel are using such sites for official duties or in the conduct of official business, when organizational information is involved in social media and social networking transactions, and when personnel access social media and networking sites from organizational systems. Organizations also address specific rules that prevent unauthorized entities from obtaining non-public organizational information from social media and networking sites either directly or through inference. Non-public information includes personally identifiable information and system account information."],"params":[],"related":["AC-22","AU-13"],"references":[],"objectives":[{"label":"PL-04(01)(a)","prose":"the rules of behavior include restrictions on the use of social media, social networking sites, and external sites/applications;"},{"label":"PL-04(01)(b)","prose":"the rules of behavior include restrictions on posting organizational information on public websites;"},{"label":"PL-04(01)(c)","prose":"the rules of behavior include restrictions on the use of organization-provided identifiers (e.g., email addresses) and authentication secrets (e.g., passwords) for creating accounts on external sites/applications."}],"methods":[{"method":"Examine","objects":["Security and privacy planning policy","procedures addressing rules of behavior for system users","rules of behavior","training policy","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with responsibility for establishing, reviewing, and updating rules of behavior","organizational personnel with responsibility for literacy training and awareness and role-based training","organizational personnel who are authorized users of the system and have signed rules of behavior","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Organizational processes for establishing rules of behavior","mechanisms supporting and/or implementing the establishment of rules of behavior"]}]},"PL-8":{"statement":[{"label":"a.","prose":"Develop security and privacy architectures for the system that:","items":[{"label":"1.","prose":"Describe the requirements and approach to be taken for protecting the confidentiality, integrity, and availability of organizational information;"},{"label":"2.","prose":"Describe the requirements and approach to be taken for processing personally identifiable information to minimize privacy risk to individuals;"},{"label":"3.","prose":"Describe how the architectures are integrated into and support the enterprise architecture; and"},{"label":"4.","prose":"Describe any assumptions about, and dependencies on, external systems and services;"}]},{"label":"b.","prose":"Review and update the architectures [Assignment: organization-defined frequency] to reflect changes in the enterprise architecture; and"},{"label":"c.","prose":"Reflect planned architecture changes in security and privacy plans, Concept of Operations (CONOPS), criticality analysis, organizational procedures, and procurements and acquisitions."}],"discussion":["The security and privacy architectures at the system level are consistent with the organization-wide security and privacy architectures described in [PM-7](#pm-7), which are integral to and developed as part of the enterprise architecture. The architectures include an architectural description, the allocation of security and privacy functionality (including controls), security- and privacy-related information for external interfaces, information being exchanged across the interfaces, and the protection mechanisms associated with each interface. The architectures can also include other information, such as user roles and the access privileges assigned to each role; security and privacy requirements; types of information processed, stored, and transmitted by the system; supply chain risk management requirements; restoration priorities of information and system services; and other protection needs.","[SP 800-160-1](#e3cc0520-a366-4fc9-abc2-5272db7e3564) provides guidance on the use of security architectures as part of the system development life cycle process. [OMB M-19-03](#c5e11048-1d38-4af3-b00b-0d88dc26860c) requires the use of the systems security engineering concepts described in [SP 800-160-1](#e3cc0520-a366-4fc9-abc2-5272db7e3564) for high value assets. Security and privacy architectures are reviewed and updated throughout the system development life cycle, from analysis of alternatives through review of the proposed architecture in the RFP responses to the design reviews before and during implementation (e.g., during preliminary design reviews and critical design reviews).","In today’s modern computing architectures, it is becoming less common for organizations to control all information resources. There may be key dependencies on external information services and service providers. Describing such dependencies in the security and privacy architectures is necessary for developing a comprehensive mission and business protection strategy. Establishing, developing, documenting, and maintaining under configuration control a baseline configuration for organizational systems is critical to implementing and maintaining effective architectures. The development of the architectures is coordinated with the senior agency information security officer and the senior agency official for privacy to ensure that the controls needed to support security and privacy requirements are identified and effectively implemented. In many circumstances, there may be no distinction between the security and privacy architecture for a system. In other circumstances, security objectives may be adequately satisfied, but privacy objectives may only be partially satisfied by the security requirements. In these cases, consideration of the privacy requirements needed to achieve satisfaction will result in a distinct privacy architecture. The documentation, however, may simply reflect the combined architectures.","[PL-8](#pl-8) is primarily directed at organizations to ensure that architectures are developed for the system and, moreover, that the architectures are integrated with or tightly coupled to the enterprise architecture. In contrast, [SA-17](#sa-17) is primarily directed at the external information technology product and system developers and integrators. [SA-17](#sa-17), which is complementary to [PL-8](#pl-8), is selected when organizations outsource the development of systems or components to external entities and when there is a need to demonstrate consistency with the organization’s enterprise architecture and security and privacy architectures."],"params":[{"id":"PL-08_ODP","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency for review and update to reflect changes in the enterprise architecture"}],"related":["CM-2","CM-6","PL-2","PL-7","PL-9","PM-5","PM-7","RA-9","SA-3","SA-5","SA-8","SA-17","SC-7"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-160-1","url":"https://doi.org/10.6028/NIST.SP.800-160v1"},{"title":"SP 800-160-2","url":"https://doi.org/10.6028/NIST.SP.800-160v2"}],"objectives":[{"label":"PL-08a.","prose":"","items":[{"label":"PL-08a.01","prose":"a security architecture for the system describes the requirements and approach to be taken for protecting the confidentiality, integrity, and availability of organizational information;"},{"label":"PL-08a.02","prose":"a privacy architecture describes the requirements and approach to be taken for processing personally identifiable information to minimize privacy risk to individuals;"},{"label":"PL-08a.03","prose":"","items":[{"label":"PL-08a.03[01]","prose":"a security architecture for the system describes how the architecture is integrated into and supports the enterprise architecture;"},{"label":"PL-08a.03[02]","prose":"a privacy architecture for the system describes how the architecture is integrated into and supports the enterprise architecture;"}]},{"label":"PL-08a.04","prose":"","items":[{"label":"PL-08a.04[01]","prose":"a security architecture for the system describes any assumptions about and dependencies on external systems and services;"},{"label":"PL-08a.04[02]","prose":"a privacy architecture for the system describes any assumptions about and dependencies on external systems and services;"}]}]},{"label":"PL-08b.","prose":"changes in the enterprise architecture are reviewed and updated [Assignment: organization-defined frequency] to reflect changes in the enterprise architecture;"},{"label":"PL-08c.","prose":"","items":[{"label":"PL-08c.[01]","prose":"planned architecture changes are reflected in the security plan;"},{"label":"PL-08c.[02]","prose":"planned architecture changes are reflected in the privacy plan;"},{"label":"PL-08c.[03]","prose":"planned architecture changes are reflected in the Concept of Operations (CONOPS);"},{"label":"PL-08c.[04]","prose":"planned architecture changes are reflected in criticality analysis;"},{"label":"PL-08c.[05]","prose":"planned architecture changes are reflected in organizational procedures;"},{"label":"PL-08c.[06]","prose":"planned architecture changes are reflected in procurements and acquisitions."}]}],"methods":[{"method":"Examine","objects":["Security and privacy planning policy","procedures addressing information security and privacy architecture development","procedures addressing information security and privacy architecture reviews and updates","enterprise architecture documentation","information security and privacy architecture documentation","system security plan","privacy plan","security and privacy CONOPS for the system"]},{"method":"Interview","objects":["Organizational personnel with security and privacy planning and plan implementation responsibilities","organizational personnel with information security and privacy architecture development responsibilities","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Organizational processes for developing, reviewing, and updating the information security and privacy architecture","mechanisms supporting and/or implementing the development, review, and update of the information security and privacy architecture"]}]},"PL-10":{"statement":[{"prose":"Select a control baseline for the system."}],"discussion":["Control baselines are predefined sets of controls specifically assembled to address the protection needs of a group, organization, or community of interest. Controls are chosen for baselines to either satisfy mandates imposed by laws, executive orders, directives, regulations, policies, standards, and guidelines or address threats common to all users of the baseline under the assumptions specific to the baseline. Baselines represent a starting point for the protection of individuals’ privacy, information, and information systems with subsequent tailoring actions to manage risk in accordance with mission, business, or other constraints (see [PL-11](#pl-11)). Federal control baselines are provided in [SP 800-53B](#46d9e201-840e-440e-987c-2c773333c752). The selection of a control baseline is determined by the needs of stakeholders. Stakeholder needs consider mission and business requirements as well as mandates imposed by applicable laws, executive orders, directives, policies, regulations, standards, and guidelines. For example, the control baselines in [SP 800-53B](#46d9e201-840e-440e-987c-2c773333c752) are based on the requirements from [FISMA](#0c67b2a9-bede-43d2-b86d-5f35b8be36e9) and [PRIVACT](#18e71fec-c6fd-475a-925a-5d8495cf8455). The requirements, along with the NIST standards and guidelines implementing the legislation, direct organizations to select one of the control baselines after the reviewing the information types and the information that is processed, stored, and transmitted on the system; analyzing the potential adverse impact of the loss or compromise of the information or system on the organization’s operations and assets, individuals, other organizations, or the Nation; and considering the results from system and organizational risk assessments. [CNSSI 1253](#4e4fbc93-333d-45e6-a875-de36b878b6b9) provides guidance on control baselines for national security systems."],"params":[],"related":["PL-2","PL-11","RA-2","RA-3","SA-8"],"references":[{"title":"FIPS 199","url":"https://doi.org/10.6028/NIST.FIPS.199"},{"title":"FIPS 200","url":"https://doi.org/10.6028/NIST.FIPS.200"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-37","url":"https://doi.org/10.6028/NIST.SP.800-37r2"},{"title":"SP 800-39","url":"https://doi.org/10.6028/NIST.SP.800-39"},{"title":"SP 800-53B","url":"https://doi.org/10.6028/NIST.SP.800-53B"},{"title":"SP 800-60-1","url":"https://doi.org/10.6028/NIST.SP.800-60v1r1"},{"title":"SP 800-60-2","url":"https://doi.org/10.6028/NIST.SP.800-60v2r1"},{"title":"SP 800-160-1","url":"https://doi.org/10.6028/NIST.SP.800-160v1"},{"title":"CNSSI 1253","url":"https://www.cnss.gov/CNSS/issuances/Instructions.cfm"}],"objectives":[],"methods":[{"method":"Examine","objects":["Security and privacy planning policy","procedures addressing system security and privacy plan development and implementation","procedures addressing system security and privacy plan reviews and updates","system design documentation","system architecture and configuration documentation","system categorization decision","information types stored, transmitted, and processed by the system","system element/component information"]},{"method":"Interview","objects":["Organizational personnel with security and privacy planning and plan implementation responsibilities","organizational personnel with information security and privacy responsibilities","organizational personnel with responsibility for organizational risk management activities"]}]},"PL-11":{"statement":[{"prose":"Tailor the selected control baseline by applying specified tailoring actions."}],"discussion":["The concept of tailoring allows organizations to specialize or customize a set of baseline controls by applying a defined set of tailoring actions. Tailoring actions facilitate such specialization and customization by allowing organizations to develop security and privacy plans that reflect their specific mission and business functions, the environments where their systems operate, the threats and vulnerabilities that can affect their systems, and any other conditions or situations that can impact their mission or business success. Tailoring guidance is provided in [SP 800-53B](#46d9e201-840e-440e-987c-2c773333c752). Tailoring a control baseline is accomplished by identifying and designating common controls, applying scoping considerations, selecting compensating controls, assigning values to control parameters, supplementing the control baseline with additional controls as needed, and providing information for control implementation. The general tailoring actions in [SP 800-53B](#46d9e201-840e-440e-987c-2c773333c752) can be supplemented with additional actions based on the needs of organizations. Tailoring actions can be applied to the baselines in [SP 800-53B](#46d9e201-840e-440e-987c-2c773333c752) in accordance with the security and privacy requirements from [FISMA](#0c67b2a9-bede-43d2-b86d-5f35b8be36e9), [PRIVACT](#18e71fec-c6fd-475a-925a-5d8495cf8455), and [OMB A-130](#27847491-5ce1-4f6a-a1e4-9e483782f0ef). Alternatively, other communities of interest adopting different control baselines can apply the tailoring actions in [SP 800-53B](#46d9e201-840e-440e-987c-2c773333c752) to specialize or customize the controls that represent the specific needs and concerns of those entities."],"params":[],"related":["PL-10","RA-2","RA-3","RA-9","SA-8"],"references":[{"title":"FIPS 199","url":"https://doi.org/10.6028/NIST.FIPS.199"},{"title":"FIPS 200","url":"https://doi.org/10.6028/NIST.FIPS.200"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-37","url":"https://doi.org/10.6028/NIST.SP.800-37r2"},{"title":"SP 800-39","url":"https://doi.org/10.6028/NIST.SP.800-39"},{"title":"SP 800-53B","url":"https://doi.org/10.6028/NIST.SP.800-53B"},{"title":"SP 800-60-1","url":"https://doi.org/10.6028/NIST.SP.800-60v1r1"},{"title":"SP 800-60-2","url":"https://doi.org/10.6028/NIST.SP.800-60v2r1"},{"title":"SP 800-160-1","url":"https://doi.org/10.6028/NIST.SP.800-160v1"},{"title":"CNSSI 1253","url":"https://www.cnss.gov/CNSS/issuances/Instructions.cfm"}],"objectives":[],"methods":[{"method":"Examine","objects":["Security and privacy planning policy","procedures addressing system security and privacy plan development and implementation","system design documentation","system categorization decision","information types stored, transmitted, and processed by the system","system element/component information","stakeholder needs analysis","list of security and privacy requirements allocated to the system, system elements, and environment of operation"]},{"method":"Interview","objects":["Organizational personnel with security and privacy planning and plan implementation responsibilities","organizational personnel with information security and privacy responsibilities"]}]},"PM-2":{"statement":[{"prose":"Appoint a senior agency information security officer with the mission and resources to coordinate, develop, implement, and maintain an organization-wide information security program."}],"discussion":["The senior agency information security officer is an organizational official. For federal agencies (as defined by applicable laws, executive orders, regulations, directives, policies, and standards), this official is the senior agency information security officer. Organizations may also refer to this official as the senior information security officer or chief information security officer."],"params":[],"related":[],"references":[{"title":"OMB M-17-25","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/memoranda/2017/M-17-25.pdf"},{"title":"SP 800-37","url":"https://doi.org/10.6028/NIST.SP.800-37r2"},{"title":"SP 800-39","url":"https://doi.org/10.6028/NIST.SP.800-39"},{"title":"SP 800-181","url":"https://doi.org/10.6028/NIST.SP.800-181r1"}],"objectives":[{"label":"PM-02[01]","prose":"a senior agency information security officer is appointed;"},{"label":"PM-02[02]","prose":"the senior agency information security officer is provided with the mission and resources to coordinate an organization-wide information security program;"},{"label":"PM-02[03]","prose":"the senior agency information security officer is provided with the mission and resources to develop an organization-wide information security program;"},{"label":"PM-02[04]","prose":"the senior agency information security officer is provided with the mission and resources to implement an organization-wide information security program;"},{"label":"PM-02[05]","prose":"the senior agency information security officer is provided with the mission and resources to maintain an organization-wide information security program."}],"methods":[{"method":"Examine","objects":["Information security program plan","procedures addressing program plan development and implementation","procedures addressing program plan reviews and updates","procedures addressing coordination of the program plan with relevant entities","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with information security program planning and plan implementation responsibilities","senior information security officer","organizational personnel with information security responsibilities"]}]},"PS-1":{"statement":[{"label":"a.","prose":"Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:","items":[{"label":"1.","prose":"[Selection (one or more): organization-level; mission/business process-level; system-level] personnel security policy that:","items":[{"label":"(a)","prose":"Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and"},{"label":"(b)","prose":"Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and"}]},{"label":"2.","prose":"Procedures to facilitate the implementation of the personnel security policy and the associated personnel security controls;"}]},{"label":"b.","prose":"Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the personnel security policy and procedures; and"},{"label":"c.","prose":"Review and update the current personnel security:","items":[{"label":"1.","prose":"Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and"},{"label":"2.","prose":"Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]."}]}],"discussion":["Personnel security policy and procedures for the controls in the PS family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on their development. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission level or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies reflecting the complex nature of organizations. Procedures can be established for security and privacy programs, for mission/business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to personnel security policy and procedures include, but are not limited to, assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure."],"params":[{"id":"PS-1_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]"},{"id":"PS-01_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the personnel security policy is to be disseminated is/are defined"},{"id":"PS-01_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the personnel security procedures are to be disseminated is/are defined"},{"id":"PS-01_ODP[03]","kind":"Selection","value":"[Selection (one or more): organization-level; mission/business process-level; system-level]"},{"id":"PS-01_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined official]","guideline":"an official to manage the personnel security policy and procedures is defined"},{"id":"PS-01_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current personnel security policy is reviewed and updated is defined"},{"id":"PS-01_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require the current personnel security policy to be reviewed and updated are defined"},{"id":"PS-01_ODP[07]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current personnel security procedures are reviewed and updated is defined"},{"id":"PS-01_ODP[08]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require the personnel security procedures to be reviewed and updated are defined"}],"related":["PM-9","PS-8","SI-12"],"references":[{"title":"SP 800-12","url":"https://doi.org/10.6028/NIST.SP.800-12r1"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-39","url":"https://doi.org/10.6028/NIST.SP.800-39"},{"title":"SP 800-100","url":"https://doi.org/10.6028/NIST.SP.800-100"}],"objectives":[{"label":"PS-01a.","prose":"","items":[{"label":"PS-01a.[01]","prose":"a personnel security policy is developed and documented;"},{"label":"PS-01a.[02]","prose":"the personnel security policy is disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"PS-01a.[03]","prose":"personnel security procedures to facilitate the implementation of the personnel security policy and associated personnel security controls are developed and documented;"},{"label":"PS-01a.[04]","prose":"the personnel security procedures are disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"PS-01a.01","prose":"","items":[{"label":"PS-01a.01(a)","prose":"","items":[{"label":"PS-01a.01(a)[01]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] personnel security policy addresses purpose;"},{"label":"PS-01a.01(a)[02]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] personnel security policy addresses scope;"},{"label":"PS-01a.01(a)[03]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] personnel security policy addresses roles;"},{"label":"PS-01a.01(a)[04]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] personnel security policy addresses responsibilities;"},{"label":"PS-01a.01(a)[05]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] personnel security policy addresses management commitment;"},{"label":"PS-01a.01(a)[06]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] personnel security policy addresses coordination among organizational entities;"},{"label":"PS-01a.01(a)[07]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] personnel security policy addresses compliance;"}]},{"label":"PS-01a.01(b)","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] personnel security policy is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines;"}]}]},{"label":"PS-01b.","prose":"the [Assignment: organization-defined official] is designated to manage the development, documentation, and dissemination of the personnel security policy and procedures;"},{"label":"PS-01c.","prose":"","items":[{"label":"PS-01c.01","prose":"","items":[{"label":"PS-01c.01[01]","prose":"the current personnel security policy is reviewed and updated [Assignment: organization-defined frequency];"},{"label":"PS-01c.01[02]","prose":"the current personnel security policy is reviewed and updated following [Assignment: organization-defined events];"}]},{"label":"PS-01c.02","prose":"","items":[{"label":"PS-01c.02[01]","prose":"the current personnel security procedures are reviewed and updated [Assignment: organization-defined frequency];"},{"label":"PS-01c.02[02]","prose":"the current personnel security procedures are reviewed and updated following [Assignment: organization-defined events]."}]}]}],"methods":[{"method":"Examine","objects":["Personnel security policy","personnel security procedures","system security plan","privacy plan","risk management strategy documentation","audit findings","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with personnel security responsibilities","organizational personnel with information security responsibilities"]}]},"PS-2":{"statement":[{"label":"a.","prose":"Assign a risk designation to all organizational positions;"},{"label":"b.","prose":"Establish screening criteria for individuals filling those positions; and"},{"label":"c.","prose":"Review and update position risk designations [Assignment: organization-defined frequency]."}],"discussion":["Position risk designations reflect Office of Personnel Management (OPM) policy and guidance. Proper position designation is the foundation of an effective and consistent suitability and personnel security program. The Position Designation System (PDS) assesses the duties and responsibilities of a position to determine the degree of potential damage to the efficiency or integrity of the service due to misconduct of an incumbent of a position and establishes the risk level of that position. The PDS assessment also determines if the duties and responsibilities of the position present the potential for position incumbents to bring about a material adverse effect on national security and the degree of that potential effect, which establishes the sensitivity level of a position. The results of the assessment determine what level of investigation is conducted for a position. Risk designations can guide and inform the types of authorizations that individuals receive when accessing organizational information and information systems. Position screening criteria include explicit information security role appointment requirements. Parts 1400 and 731 of Title 5, Code of Federal Regulations, establish the requirements for organizations to evaluate relevant covered positions for a position sensitivity and position risk designation commensurate with the duties and responsibilities of those positions."],"params":[{"id":"PS-02_ODP","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to review and update position risk designations is defined"}],"related":["AC-5","AT-3","PE-2","PE-3","PL-2","PS-3","PS-6","SA-5","SA-21","SI-12"],"references":[{"title":"5 CFR 731","url":"https://www.govinfo.gov/content/pkg/CFR-2012-title5-vol2/pdf/CFR-2012-title5-vol2-sec731-106.pdf"},{"title":"SP 800-181","url":"https://doi.org/10.6028/NIST.SP.800-181r1"}],"objectives":[{"label":"PS-02a.","prose":"a risk designation is assigned to all organizational positions;"},{"label":"PS-02b.","prose":"screening criteria are established for individuals filling organizational positions;"},{"label":"PS-02c.","prose":"position risk designations are reviewed and updated [Assignment: organization-defined frequency]."}],"methods":[{"method":"Examine","objects":["Personnel security policy","procedures addressing position categorization","appropriate codes of federal regulations","list of risk designations for organizational positions","records of position risk designation reviews and updates","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with personnel security responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for assigning, reviewing, and updating position risk designations","organizational processes for establishing screening criteria"]}]},"PS-3":{"statement":[{"label":"a.","prose":"Screen individuals prior to authorizing access to the system; and"},{"label":"b.","prose":"Rescreen individuals in accordance with [Assignment: organization-defined conditions requiring rescreening and, where rescreening is so indicated, the frequency of rescreening]."}],"discussion":["Personnel screening and rescreening activities reflect applicable laws, executive orders, directives, regulations, policies, standards, guidelines, and specific criteria established for the risk designations of assigned positions. Examples of personnel screening include background investigations and agency checks. Organizations may define different rescreening conditions and frequencies for personnel accessing systems based on types of information processed, stored, or transmitted by the systems."],"params":[{"id":"PS-3_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined conditions requiring rescreening and, where rescreening is so indicated, the frequency of rescreening]"},{"id":"PS-03_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined conditions requiring rescreening]","guideline":"conditions requiring rescreening of individuals are defined"},{"id":"PS-03_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency of rescreening individuals where it is so indicated is defined"}],"related":["AC-2","IA-4","MA-5","PE-2","PM-12","PS-2","PS-6","PS-7","SA-21"],"references":[{"title":"EO 13526","url":"https://www.archives.gov/isoo/policy-documents/cnsi-eo.html"},{"title":"EO 13587","url":"https://obamawhitehouse.archives.gov/the-press-office/2011/10/07/executive-order-13587-structural-reforms-improve-security-classified-net"},{"title":"FIPS 199","url":"https://doi.org/10.6028/NIST.FIPS.199"},{"title":"FIPS 201-2","url":"https://doi.org/10.6028/NIST.FIPS.201-2"},{"title":"SP 800-60-1","url":"https://doi.org/10.6028/NIST.SP.800-60v1r1"},{"title":"SP 800-60-2","url":"https://doi.org/10.6028/NIST.SP.800-60v2r1"},{"title":"SP 800-73-4","url":"https://doi.org/10.6028/NIST.SP.800-73-4"},{"title":"SP 800-76-2","url":"https://doi.org/10.6028/NIST.SP.800-76-2"},{"title":"SP 800-78-4","url":"https://doi.org/10.6028/NIST.SP.800-78-4"}],"objectives":[{"label":"PS-03a.","prose":"individuals are screened prior to authorizing access to the system;"},{"label":"PS-03b.","prose":"","items":[{"label":"PS-03b.[01]","prose":"individuals are rescreened in accordance with [Assignment: organization-defined conditions requiring rescreening];"},{"label":"PS-03b.[02]","prose":"where rescreening is so indicated, individuals are rescreened [Assignment: organization-defined frequency]."}]}],"methods":[{"method":"Examine","objects":["Personnel security policy","procedures addressing personnel screening","records of screened personnel","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with personnel security responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for personnel screening"]}]},"PS-4":{"statement":[{"prose":"Upon termination of individual employment:"},{"label":"a.","prose":"Disable system access within [Assignment: organization-defined time period];"},{"label":"b.","prose":"Terminate or revoke any authenticators and credentials associated with the individual;"},{"label":"c.","prose":"Conduct exit interviews that include a discussion of [Assignment: organization-defined information security topics];"},{"label":"d.","prose":"Retrieve all security-related organizational system-related property; and"},{"label":"e.","prose":"Retain access to organizational information and systems formerly controlled by terminated individual."}],"discussion":["System property includes hardware authentication tokens, system administration technical manuals, keys, identification cards, and building passes. Exit interviews ensure that terminated individuals understand the security constraints imposed by being former employees and that proper accountability is achieved for system-related property. Security topics at exit interviews include reminding individuals of nondisclosure agreements and potential limitations on future employment. Exit interviews may not always be possible for some individuals, including in cases related to the unavailability of supervisors, illnesses, or job abandonment. Exit interviews are important for individuals with security clearances. The timely execution of termination actions is essential for individuals who have been terminated for cause. In certain situations, organizations consider disabling the system accounts of individuals who are being terminated prior to the individuals being notified."],"params":[{"id":"PS-04_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"a time period within which to disable system access is defined"},{"id":"PS-04_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined information security topics]","guideline":"information security topics to be discussed when conducting exit interviews are defined"}],"related":["AC-2","IA-4","PE-2","PM-12","PS-6","PS-7"],"references":[],"objectives":[{"label":"PS-04a.","prose":"upon termination of individual employment, system access is disabled within [Assignment: organization-defined time period];"},{"label":"PS-04b.","prose":"upon termination of individual employment, any authenticators and credentials are terminated or revoked;"},{"label":"PS-04c.","prose":"upon termination of individual employment, exit interviews that include a discussion of [Assignment: organization-defined information security topics] are conducted;"},{"label":"PS-04d.","prose":"upon termination of individual employment, all security-related organizational system-related property is retrieved;"},{"label":"PS-04e.","prose":"upon termination of individual employment, access to organizational information and systems formerly controlled by the terminated individual are retained."}],"methods":[{"method":"Examine","objects":["Personnel security policy","procedures addressing personnel termination","records of personnel termination actions","list of system accounts","records of terminated or revoked authenticators/credentials","records of exit interviews","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with personnel security responsibilities","organizational personnel with account management responsibilities","system/network administrators","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for personnel termination","mechanisms supporting and/or implementing personnel termination notifications","mechanisms for disabling system access/revoking authenticators"]}]},"PS-4(2)":{"statement":[{"prose":"Use [Assignment: organization-defined automated mechanisms] to [Selection (one or more): notify [Assignment: organization-defined personnel or roles] of individual termination actions; disable access to system resources]."}],"discussion":["In organizations with many employees, not all personnel who need to know about termination actions receive the appropriate notifications, or if such notifications are received, they may not occur in a timely manner. Automated mechanisms can be used to send automatic alerts or notifications to organizational personnel or roles when individuals are terminated. Such automatic alerts or notifications can be conveyed in a variety of ways, including via telephone, electronic mail, text message, or websites. Automated mechanisms can also be employed to quickly and thoroughly disable access to system resources after an employee is terminated."],"params":[{"id":"PS-04(02)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms to notify personnel or roles of individual termination actions and/or to disable access to system resources are defined"},{"id":"PS-04(02)_ODP[02]","kind":"Selection","value":"[Selection (one or more): notify [Assignment: organization-defined personnel or roles] of individual termination actions; disable access to system resources]"},{"id":"PS-04(02)_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to be notified upon termination of an individual is/are defined (if selected)"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Personnel security policy","procedures addressing personnel termination","system design documentation","system configuration settings and associated documentation","records of personnel termination actions","automated notifications of employee terminations","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with personnel security responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for personnel termination","automated mechanisms supporting and/or implementing personnel termination notifications"]}]},"PS-5":{"statement":[{"label":"a.","prose":"Review and confirm ongoing operational need for current logical and physical access authorizations to systems and facilities when individuals are reassigned or transferred to other positions within the organization;"},{"label":"b.","prose":"Initiate [Assignment: organization-defined transfer or reassignment actions] within [Assignment: organization-defined time period following the formal transfer action];"},{"label":"c.","prose":"Modify access authorization as needed to correspond with any changes in operational need due to reassignment or transfer; and"},{"label":"d.","prose":"Notify [Assignment: organization-defined personnel or roles] within [Assignment: organization-defined time period]."}],"discussion":["Personnel transfer applies when reassignments or transfers of individuals are permanent or of such extended duration as to make the actions warranted. Organizations define actions appropriate for the types of reassignments or transfers, whether permanent or extended. Actions that may be required for personnel transfers or reassignments to other positions within organizations include returning old and issuing new keys, identification cards, and building passes; closing system accounts and establishing new accounts; changing system access authorizations (i.e., privileges); and providing for access to official records to which individuals had access at previous work locations and in previous system accounts."],"params":[{"id":"PS-05_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined transfer or reassignment actions]","guideline":"transfer or reassignment actions to be initiated following transfer or reassignment are defined"},{"id":"PS-05_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined time period following the formal transfer action]","guideline":"the time period within which transfer or reassignment actions must occur following transfer or reassignment is defined"},{"id":"PS-05_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to be notified when individuals are reassigned or transferred to other positions within the organization is/are defined"},{"id":"PS-05_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"time period within which to notify organization-defined personnel or roles when individuals are reassigned or transferred to other positions within the organization is defined"}],"related":["AC-2","IA-4","PE-2","PM-12","PS-4","PS-7"],"references":[],"objectives":[{"label":"PS-05a.","prose":"the ongoing operational need for current logical and physical access authorizations to systems and facilities are reviewed and confirmed when individuals are reassigned or transferred to other positions within the organization;"},{"label":"PS-05b.","prose":"[Assignment: organization-defined transfer or reassignment actions] are initiated within [Assignment: organization-defined time period following the formal transfer action];"},{"label":"PS-05c.","prose":"access authorization is modified as needed to correspond with any changes in operational need due to reassignment or transfer;"},{"label":"PS-05d.","prose":"[Assignment: organization-defined personnel or roles] are notified within [Assignment: organization-defined time period]."}],"methods":[{"method":"Examine","objects":["Personnel security policy","procedures addressing personnel transfer","records of personnel transfer actions","list of system and facility access authorizations","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with personnel security responsibilities","organizational personnel with account management responsibilities","system/network administrators","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for personnel transfer","mechanisms supporting and/or implementing personnel transfer notifications","mechanisms for disabling system access/revoking authenticators"]}]},"PS-6":{"statement":[{"label":"a.","prose":"Develop and document access agreements for organizational systems;"},{"label":"b.","prose":"Review and update the access agreements [Assignment: organization-defined frequency]; and"},{"label":"c.","prose":"Verify that individuals requiring access to organizational information and systems:","items":[{"label":"1.","prose":"Sign appropriate access agreements prior to being granted access; and"},{"label":"2.","prose":"Re-sign access agreements to maintain access to organizational systems when access agreements have been updated or [Assignment: organization-defined frequency]."}]}],"discussion":["Access agreements include nondisclosure agreements, acceptable use agreements, rules of behavior, and conflict-of-interest agreements. Signed access agreements include an acknowledgement that individuals have read, understand, and agree to abide by the constraints associated with organizational systems to which access is authorized. Organizations can use electronic signatures to acknowledge access agreements unless specifically prohibited by organizational policy."],"params":[{"id":"PS-06_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to review and update access agreements is defined"},{"id":"PS-06_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to re-sign access agreements to maintain access to organizational information is defined"}],"related":["AC-17","PE-2","PL-4","PS-2","PS-3","PS-6","PS-7","PS-8","SA-21","SI-12"],"references":[],"objectives":[{"label":"PS-06a.","prose":"access agreements are developed and documented for organizational systems;"},{"label":"PS-06b.","prose":"the access agreements are reviewed and updated [Assignment: organization-defined frequency];"},{"label":"PS-06c.","prose":"","items":[{"label":"PS-06c.01","prose":"individuals requiring access to organizational information and systems sign appropriate access agreements prior to being granted access;"},{"label":"PS-06c.02","prose":"individuals requiring access to organizational information and systems re-sign access agreements to maintain access to organizational systems when access agreements have been updated or [Assignment: organization-defined frequency]."}]}],"methods":[{"method":"Examine","objects":["Personnel security policy","personnel security procedures","procedures addressing access agreements for organizational information and systems","access control policy","access control procedures","access agreements (including non-disclosure agreements, acceptable use agreements, rules of behavior, and conflict-of-interest agreements)","documentation of access agreement reviews, updates, and re-signing","system security plan"]},{"method":"Interview","objects":["Organizational personnel with personnel security responsibilities","organizational personnel who have signed/resigned access agreements","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Organizational processes for reviewing, updating, and re-signing access agreements","mechanisms supporting the reviewing, updating, and re-signing of access agreements"]}]},"PS-7":{"statement":[{"label":"a.","prose":"Establish personnel security requirements, including security roles and responsibilities for external providers;"},{"label":"b.","prose":"Require external providers to comply with personnel security policies and procedures established by the organization;"},{"label":"c.","prose":"Document personnel security requirements;"},{"label":"d.","prose":"Require external providers to notify [Assignment: organization-defined personnel or roles] of any personnel transfers or terminations of external personnel who possess organizational credentials and/or badges, or who have system privileges within [Assignment: organization-defined time period]; and"},{"label":"e.","prose":"Monitor provider compliance with personnel security requirements."}],"discussion":["External provider refers to organizations other than the organization operating or acquiring the system. External providers include service bureaus, contractors, and other organizations that provide system development, information technology services, testing or assessment services, outsourced applications, and network/security management. Organizations explicitly include personnel security requirements in acquisition-related documents. External providers may have personnel working at organizational facilities with credentials, badges, or system privileges issued by organizations. Notifications of external personnel changes ensure the appropriate termination of privileges and credentials. Organizations define the transfers and terminations deemed reportable by security-related characteristics that include functions, roles, and the nature of credentials or privileges associated with transferred or terminated individuals."],"params":[{"id":"PS-07_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to be notified of any personnel transfers or terminations of external personnel who possess organizational credentials and/or badges or who have system privileges is/are defined"},{"id":"PS-07_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"time period within which third-party providers are required to notify organization-defined personnel or roles of any personnel transfers or terminations of external personnel who possess organizational credentials and/or badges or who have system privileges is defined"}],"related":["AT-2","AT-3","MA-5","PE-3","PS-2","PS-3","PS-4","PS-5","PS-6","SA-5","SA-9","SA-21"],"references":[{"title":"SP 800-35","url":"https://doi.org/10.6028/NIST.SP.800-35"},{"title":"SP 800-63-3","url":"https://doi.org/10.6028/NIST.SP.800-63-3"}],"objectives":[{"label":"PS-07a.","prose":"personnel security requirements are established, including security roles and responsibilities for external providers;"},{"label":"PS-07b.","prose":"external providers are required to comply with personnel security policies and procedures established by the organization;"},{"label":"PS-07c.","prose":"personnel security requirements are documented;"},{"label":"PS-07d.","prose":"external providers are required to notify [Assignment: organization-defined personnel or roles] of any personnel transfers or terminations of external personnel who possess organizational credentials and/or badges or who have system privileges within [Assignment: organization-defined time period];"},{"label":"PS-07e.","prose":"provider compliance with personnel security requirements is monitored."}],"methods":[{"method":"Examine","objects":["Personnel security policy","procedures addressing external personnel security","list of personnel security requirements","acquisition documents","service-level agreements","compliance monitoring process","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with personnel security responsibilities","external providers","system/network administrators","organizational personnel with account management responsibilities","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for managing and monitoring external personnel security","mechanisms supporting and/or implementing the monitoring of provider compliance"]}]},"PS-8":{"statement":[{"label":"a.","prose":"Employ a formal sanctions process for individuals failing to comply with established information security and privacy policies and procedures; and"},{"label":"b.","prose":"Notify [Assignment: organization-defined personnel or roles] within [Assignment: organization-defined time period] when a formal employee sanctions process is initiated, identifying the individual sanctioned and the reason for the sanction."}],"discussion":["Organizational sanctions reflect applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Sanctions processes are described in access agreements and can be included as part of general personnel policies for organizations and/or specified in security and privacy policies. Organizations consult with the Office of the General Counsel regarding matters of employee sanctions."],"params":[{"id":"PS-08_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to be notified when a formal employee sanctions process is initiated is/are defined"},{"id":"PS-08_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"the time period within which organization-defined personnel or roles must be notified when a formal employee sanctions process is initiated is defined"}],"related":["PL-4","PM-12","PS-6","PT-1"],"references":[],"objectives":[{"label":"PS-08a.","prose":"a formal sanctions process is employed for individuals failing to comply with established information security and privacy policies and procedures;"},{"label":"PS-08b.","prose":"[Assignment: organization-defined personnel or roles] is/are notified within [Assignment: organization-defined time period] when a formal employee sanctions process is initiated, identifying the individual sanctioned and the reason for the sanction."}],"methods":[{"method":"Examine","objects":["Personnel security policy","personnel security procedures","procedures addressing personnel sanctions","access agreements (including non-disclosure agreements, acceptable use agreements, rules of behavior, and conflict-of-interest agreements)","list of personnel or roles to be notified of formal employee sanctions","records or notifications of formal employee sanctions","system security plan","privacy plan"]},{"method":"Interview","objects":["Organizational personnel with personnel security responsibilities","legal counsel","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Organizational processes for managing formal employee sanctions","mechanisms supporting and/or implementing formal employee sanctions notifications"]}]},"PS-9":{"statement":[{"prose":"Incorporate security and privacy roles and responsibilities into organizational position descriptions."}],"discussion":["Specification of security and privacy roles in individual organizational position descriptions facilitates clarity in understanding the security or privacy responsibilities associated with the roles and the role-based security and privacy training requirements for the roles."],"params":[],"related":[],"references":[{"title":"SP 800-181","url":"https://doi.org/10.6028/NIST.SP.800-181r1"}],"objectives":[{"label":"PS-09[01]","prose":"security roles and responsibilities are incorporated into organizational position descriptions;"},{"label":"PS-09[02]","prose":"privacy roles and responsibilities are incorporated into organizational position descriptions."}],"methods":[{"method":"Examine","objects":["Personnel security policy","personnel security procedures","procedures addressing position descriptions","security and privacy position descriptions","system security plan","privacy plan","privacy program plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with personnel security responsibilities","organizational personnel with information security and privacy responsibilities","organizational personnel with human capital management responsibilities"]},{"method":"Test","objects":["Organizational processes for managing position descriptions"]}]},"PT-3":{"statement":[{"label":"a.","prose":"Identify and document the [Assignment: organization-defined purpose(s)] for processing personally identifiable information;"},{"label":"b.","prose":"Describe the purpose(s) in the public privacy notices and policies of the organization;"},{"label":"c.","prose":"Restrict the [Assignment: organization-defined processing] of personally identifiable information to only that which is compatible with the identified purpose(s); and"},{"label":"d.","prose":"Monitor changes in processing personally identifiable information and implement [Assignment: organization-defined mechanisms] to ensure that any changes are made in accordance with [Assignment: organization-defined requirements]."}],"discussion":["Identifying and documenting the purpose for processing provides organizations with a basis for understanding why personally identifiable information may be processed. The term \"process\" includes every step of the information life cycle, including creation, collection, use, processing, storage, maintenance, dissemination, disclosure, and disposal. Identifying and documenting the purpose of processing is a prerequisite to enabling owners and operators of the system and individuals whose information is processed by the system to understand how the information will be processed. This enables individuals to make informed decisions about their engagement with information systems and organizations and to manage their privacy interests. Once the specific processing purpose has been identified, the purpose is described in the organization’s privacy notices, policies, and any related privacy compliance documentation, including privacy impact assessments, system of records notices, [PRIVACT](#18e71fec-c6fd-475a-925a-5d8495cf8455) statements, computer matching notices, and other applicable Federal Register notices.","Organizations take steps to help ensure that personally identifiable information is processed only for identified purposes, including training organizational personnel and monitoring and auditing organizational processing of personally identifiable information.","Organizations monitor for changes in personally identifiable information processing. Organizational personnel consult with the senior agency official for privacy and legal counsel to ensure that any new purposes that arise from changes in processing are compatible with the purpose for which the information was collected, or if the new purpose is not compatible, implement mechanisms in accordance with defined requirements to allow for the new processing, if appropriate. Mechanisms may include obtaining consent from individuals, revising privacy policies, or other measures to manage privacy risks that arise from changes in personally identifiable information processing purposes."],"params":[{"id":"PT-03_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined purpose(s)]","guideline":"the purpose(s) for processing personally identifiable information is/are defined"},{"id":"PT-03_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined processing]","guideline":"the processing of personally identifiable information to be restricted is defined"},{"id":"PT-03_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined mechanisms]","guideline":"mechanisms to be implemented for ensuring any changes in the processing of personally identifiable information are made in accordance with requirements are defined"},{"id":"PT-03_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined requirements]","guideline":"requirements for changing the processing of personally identifiable information are defined"}],"related":["AC-2","AC-3","AT-3","CM-13","IR-9","PM-9","PM-25","PT-2","PT-5","PT-6","PT-7","RA-8","SC-43","SI-12","SI-18"],"references":[{"title":"PRIVACT","url":"https://www.govinfo.gov/content/pkg/STATUTE-88/pdf/STATUTE-88-Pg1896.pdf"},{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"IR 8112","url":"https://doi.org/10.6028/NIST.IR.8112"}],"objectives":[{"label":"PT-03a.","prose":"the [Assignment: organization-defined purpose(s)] for processing personally identifiable information is/are identified and documented;"},{"label":"PT-03b.","prose":"","items":[{"label":"PT-03b.[01]","prose":"the purpose(s) is/are described in the public privacy notices of the organization;"},{"label":"PT-03b.[02]","prose":"the purpose(s) is/are described in the policies of the organization;"}]},{"label":"PT-03c.","prose":"the [Assignment: organization-defined processing] of personally identifiable information are restricted to only that which is compatible with the identified purpose(s);"},{"label":"PT-03d.","prose":"","items":[{"label":"PT-03d.[01]","prose":"changes in the processing of personally identifiable information are monitored;"},{"label":"PT-03d.[02]","prose":"[Assignment: organization-defined mechanisms] are implemented to ensure that any changes are made in accordance with [Assignment: organization-defined requirements]."}]}],"methods":[{"method":"Examine","objects":["Personally identifiable information processing and transparency policy and procedures","configuration management plan","organizational privacy notices","organizational policies","Privacy Act statements","computer matching notices","applicable Federal Register notices","documented requirements for enforcing and monitoring the processing of personally identifiable information"]},{"method":"Interview","objects":["Organizational personnel with personally identifiable information processing and transparency responsibilities","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Organizational processes for authorizing the processing of personally identifiable information","mechanisms supporting and/or implementing the management of authorized personally identifiable information processing","organizational processes for monitoring changes in processing personally identifiable information"]}]},"PT-5":{"statement":[{"prose":"Provide notice to individuals about the processing of personally identifiable information that:"},{"label":"a.","prose":"Is available to individuals upon first interacting with an organization, and subsequently at [Assignment: organization-defined frequency];"},{"label":"b.","prose":"Is clear and easy-to-understand, expressing information about personally identifiable information processing in plain language;"},{"label":"c.","prose":"Identifies the authority that authorizes the processing of personally identifiable information;"},{"label":"d.","prose":"Identifies the purposes for which personally identifiable information is to be processed; and"},{"label":"e.","prose":"Includes [Assignment: organization-defined information]."}],"discussion":["Privacy notices help inform individuals about how their personally identifiable information is being processed by the system or organization. Organizations use privacy notices to inform individuals about how, under what authority, and for what purpose their personally identifiable information is processed, as well as other information such as choices individuals might have with respect to that processing and other parties with whom information is shared. Laws, executive orders, directives, regulations, or policies may require that privacy notices include specific elements or be provided in specific formats. Federal agency personnel consult with the senior agency official for privacy and legal counsel regarding when and where to provide privacy notices, as well as elements to include in privacy notices and required formats. In circumstances where laws or government-wide policies do not require privacy notices, organizational policies and determinations may require privacy notices and may serve as a source of the elements to include in privacy notices.","Privacy risk assessments identify the privacy risks associated with the processing of personally identifiable information and may help organizations determine appropriate elements to include in a privacy notice to manage such risks. To help individuals understand how their information is being processed, organizations write materials in plain language and avoid technical jargon."],"params":[{"id":"PT-05_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which a notice is provided to individuals after initial interaction with an organization is defined"},{"id":"PT-05_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined information]","guideline":"information to be included with the notice about the processing of personally identifiable information is defined"}],"related":["PM-20","PM-22","PT-2","PT-3","PT-4","PT-7","RA-3","SC-42","SI-18"],"references":[{"title":"PRIVACT","url":"https://www.govinfo.gov/content/pkg/STATUTE-88/pdf/STATUTE-88-Pg1896.pdf"},{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"OMB A-108","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A108/omb_circular_a-108.pdf"}],"objectives":[{"label":"PT-05a.","prose":"","items":[{"label":"PT-05a.[01]","prose":"a notice to individuals about the processing of personally identifiable information is provided such that the notice is available to individuals upon first interacting with an organization;"},{"label":"PT-05a.[02]","prose":"a notice to individuals about the processing of personally identifiable information is provided such that the notice is subsequently available to individuals [Assignment: organization-defined frequency];"}]},{"label":"PT-05b.","prose":"a notice to individuals about the processing of personally identifiable information is provided that is clear, easy-to-understand, and expresses information about personally identifiable information processing in plain language;"},{"label":"PT-05c.","prose":"a notice to individuals about the processing of personally identifiable information that identifies the authority that authorizes the processing of personally identifiable information is provided;"},{"label":"PT-05d.","prose":"a notice to individuals about the processing of personally identifiable information that identifies the purpose for which personally identifiable information is to be processed is provided;"},{"label":"PT-05e.","prose":"a notice to individuals about the processing of personally identifiable information which includes [Assignment: organization-defined information] is provided."}],"methods":[{"method":"Examine","objects":["Personally identifiable information processing and transparency policy and procedures","privacy notice","Privacy Act statements","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with personally identifiable information processing and transparency responsibilities","organizational personnel with user interface or user experience responsibilities","organizational personnel with information security and privacy responsibilities"]},{"method":"Test","objects":["Organizational processes and implementation support or mechanisms for providing notice to individuals regarding the processing of their personally identifiable information"]}]},"RA-1":{"statement":[{"label":"a.","prose":"Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:","items":[{"label":"1.","prose":"[Selection (one or more): organization-level; mission/business process-level; system-level] risk assessment policy that:","items":[{"label":"(a)","prose":"Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and"},{"label":"(b)","prose":"Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and"}]},{"label":"2.","prose":"Procedures to facilitate the implementation of the risk assessment policy and the associated risk assessment controls;"}]},{"label":"b.","prose":"Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the risk assessment policy and procedures; and"},{"label":"c.","prose":"Review and update the current risk assessment:","items":[{"label":"1.","prose":"Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and"},{"label":"2.","prose":"Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]."}]}],"discussion":["Risk assessment policy and procedures address the controls in the RA family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of risk assessment policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies reflecting the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to risk assessment policy and procedures include assessment or audit findings, security incidents or breaches, or changes in laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure."],"params":[{"id":"RA-1_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]"},{"id":"RA-01_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the risk assessment policy is to be disseminated is/are defined"},{"id":"RA-01_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the risk assessment procedures are to be disseminated is/are defined"},{"id":"RA-01_ODP[03]","kind":"Selection","value":"[Selection (one or more): organization-level; mission/business process-level; system-level]"},{"id":"RA-01_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined official]","guideline":"an official to manage the risk assessment policy and procedures is defined"},{"id":"RA-01_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current risk assessment policy is reviewed and updated is defined"},{"id":"RA-01_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require the current risk assessment policy to be reviewed and updated are defined"},{"id":"RA-01_ODP[07]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current risk assessment procedures are reviewed and updated is defined"},{"id":"RA-01_ODP[08]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require risk assessment procedures to be reviewed and updated are defined"}],"related":["PM-9","PS-8","SI-12"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-12","url":"https://doi.org/10.6028/NIST.SP.800-12r1"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-39","url":"https://doi.org/10.6028/NIST.SP.800-39"},{"title":"SP 800-100","url":"https://doi.org/10.6028/NIST.SP.800-100"}],"objectives":[{"label":"RA-01a.","prose":"","items":[{"label":"RA-01a.[01]","prose":"a risk assessment policy is developed and documented;"},{"label":"RA-01a.[02]","prose":"the risk assessment policy is disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"RA-01a.[03]","prose":"risk assessment procedures to facilitate the implementation of the risk assessment policy and associated risk assessment controls are developed and documented;"},{"label":"RA-01a.[04]","prose":"the risk assessment procedures are disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"RA-01a.01","prose":"","items":[{"label":"RA-01a.01(a)","prose":"","items":[{"label":"RA-01a.01(a)[01]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] risk assessment policy addresses purpose;"},{"label":"RA-01a.01(a)[02]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] risk assessment policy addresses scope;"},{"label":"RA-01a.01(a)[03]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] risk assessment policy addresses roles;"},{"label":"RA-01a.01(a)[04]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] risk assessment policy addresses responsibilities;"},{"label":"RA-01a.01(a)[05]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] risk assessment policy addresses management commitment;"},{"label":"RA-01a.01(a)[06]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] risk assessment policy addresses coordination among organizational entities;"},{"label":"RA-01a.01(a)[07]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] risk assessment policy addresses compliance;"}]},{"label":"RA-01a.01(b)","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] risk assessment policy is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines;"}]}]},{"label":"RA-01b.","prose":"the [Assignment: organization-defined official] is designated to manage the development, documentation, and dissemination of the risk assessment policy and procedures;"},{"label":"RA-01c.","prose":"","items":[{"label":"RA-01c.01","prose":"","items":[{"label":"RA-01c.01[01]","prose":"the current risk assessment policy is reviewed and updated [Assignment: organization-defined frequency];"},{"label":"RA-01c.01[02]","prose":"the current risk assessment policy is reviewed and updated following [Assignment: organization-defined events];"}]},{"label":"RA-01c.02","prose":"","items":[{"label":"RA-01c.02[01]","prose":"the current risk assessment procedures are reviewed and updated [Assignment: organization-defined frequency];"},{"label":"RA-01c.02[02]","prose":"the current risk assessment procedures are reviewed and updated following [Assignment: organization-defined events]."}]}]}],"methods":[{"method":"Examine","objects":["Risk assessment policy and procedures","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with risk assessment responsibilities","organizational personnel with security and privacy responsibilities"]}]},"RA-2":{"statement":[{"label":"a.","prose":"Categorize the system and information it processes, stores, and transmits;"},{"label":"b.","prose":"Document the security categorization results, including supporting rationale, in the security plan for the system; and"},{"label":"c.","prose":"Verify that the authorizing official or authorizing official designated representative reviews and approves the security categorization decision."}],"discussion":["Security categories describe the potential adverse impacts or negative consequences to organizational operations, organizational assets, and individuals if organizational information and systems are compromised through a loss of confidentiality, integrity, or availability. Security categorization is also a type of asset loss characterization in systems security engineering processes that is carried out throughout the system development life cycle. Organizations can use privacy risk assessments or privacy impact assessments to better understand the potential adverse effects on individuals. [CNSSI 1253](#4e4fbc93-333d-45e6-a875-de36b878b6b9) provides additional guidance on categorization for national security systems.","Organizations conduct the security categorization process as an organization-wide activity with the direct involvement of chief information officers, senior agency information security officers, senior agency officials for privacy, system owners, mission and business owners, and information owners or stewards. Organizations consider the potential adverse impacts to other organizations and, in accordance with [USA PATRIOT](#13f0c39d-eaf7-417a-baef-69a041878bb5) and Homeland Security Presidential Directives, potential national-level adverse impacts.","Security categorization processes facilitate the development of inventories of information assets and, along with [CM-8](#cm-8), mappings to specific system components where information is processed, stored, or transmitted. The security categorization process is revisited throughout the system development life cycle to ensure that the security categories remain accurate and relevant."],"params":[],"related":["CM-8","MP-4","PL-2","PL-10","PL-11","PM-7","RA-3","RA-5","RA-7","RA-8","SA-8","SC-7","SC-38","SI-12"],"references":[{"title":"FIPS 199","url":"https://doi.org/10.6028/NIST.FIPS.199"},{"title":"FIPS 200","url":"https://doi.org/10.6028/NIST.FIPS.200"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-37","url":"https://doi.org/10.6028/NIST.SP.800-37r2"},{"title":"SP 800-39","url":"https://doi.org/10.6028/NIST.SP.800-39"},{"title":"SP 800-60-1","url":"https://doi.org/10.6028/NIST.SP.800-60v1r1"},{"title":"SP 800-60-2","url":"https://doi.org/10.6028/NIST.SP.800-60v2r1"},{"title":"SP 800-160-1","url":"https://doi.org/10.6028/NIST.SP.800-160v1"},{"title":"CNSSI 1253","url":"https://www.cnss.gov/CNSS/issuances/Instructions.cfm"},{"title":"NARA CUI","url":"https://www.archives.gov/cui"}],"objectives":[{"label":"RA-02a.","prose":"the system and the information it processes, stores, and transmits are categorized;"},{"label":"RA-02b.","prose":"the security categorization results, including supporting rationale, are documented in the security plan for the system;"},{"label":"RA-02c.","prose":"the authorizing official or authorizing official designated representative reviews and approves the security categorization decision."}],"methods":[{"method":"Examine","objects":["Risk assessment policy","security planning policy and procedures","procedures addressing security categorization of organizational information and systems","security categorization documentation","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with security categorization and risk assessment responsibilities","organizational personnel with security and privacy responsibilities"]},{"method":"Test","objects":["Organizational processes for security categorization"]}]},"RA-3":{"statement":[{"label":"a.","prose":"Conduct a risk assessment, including:","items":[{"label":"1.","prose":"Identifying threats to and vulnerabilities in the system;"},{"label":"2.","prose":"Determining the likelihood and magnitude of harm from unauthorized access, use, disclosure, disruption, modification, or destruction of the system, the information it processes, stores, or transmits, and any related information; and"},{"label":"3.","prose":"Determining the likelihood and impact of adverse effects on individuals arising from the processing of personally identifiable information;"}]},{"label":"b.","prose":"Integrate risk assessment results and risk management decisions from the organization and mission or business process perspectives with system-level risk assessments;"},{"label":"c.","prose":"Document risk assessment results in [Selection: security and privacy plans; risk assessment report; [Assignment: organization-defined document]];"},{"label":"d.","prose":"Review risk assessment results [Assignment: organization-defined frequency];"},{"label":"e.","prose":"Disseminate risk assessment results to [Assignment: organization-defined personnel or roles]; and"},{"label":"f.","prose":"Update the risk assessment [Assignment: organization-defined frequency] or when there are significant changes to the system, its environment of operation, or other conditions that may impact the security or privacy state of the system."}],"discussion":["Risk assessments consider threats, vulnerabilities, likelihood, and impact to organizational operations and assets, individuals, other organizations, and the Nation. Risk assessments also consider risk from external parties, including contractors who operate systems on behalf of the organization, individuals who access organizational systems, service providers, and outsourcing entities.","Organizations can conduct risk assessments at all three levels in the risk management hierarchy (i.e., organization level, mission/business process level, or information system level) and at any stage in the system development life cycle. Risk assessments can also be conducted at various steps in the Risk Management Framework, including preparation, categorization, control selection, control implementation, control assessment, authorization, and control monitoring. Risk assessment is an ongoing activity carried out throughout the system development life cycle.","Risk assessments can also address information related to the system, including system design, the intended use of the system, testing results, and supply chain-related information or artifacts. Risk assessments can play an important role in control selection processes, particularly during the application of tailoring guidance and in the earliest phases of capability determination."],"params":[{"id":"RA-03_ODP[01]","kind":"Selection","value":"[Selection: security and privacy plans; risk assessment report; [Assignment: organization-defined document]]"},{"id":"RA-03_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined document]","guideline":"a document in which risk assessment results are to be documented (if not documented in the security and privacy plans or risk assessment report) is defined (if selected)"},{"id":"RA-03_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency to review risk assessment results is defined"},{"id":"RA-03_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom risk assessment results are to be disseminated is/are defined"},{"id":"RA-03_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency to update the risk assessment is defined"}],"related":["CA-3","CA-6","CM-4","CM-13","CP-6","CP-7","IA-8","MA-5","PE-3","PE-8","PE-18","PL-2","PL-10","PL-11","PM-8","PM-9","PM-28","PT-2","PT-7","RA-2","RA-5","RA-7","SA-8","SA-9","SC-38","SI-12"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-39","url":"https://doi.org/10.6028/NIST.SP.800-39"},{"title":"SP 800-161","url":"https://doi.org/10.6028/NIST.SP.800-161"},{"title":"IR 8023","url":"https://doi.org/10.6028/NIST.IR.8023"},{"title":"IR 8062","url":"https://doi.org/10.6028/NIST.IR.8062"},{"title":"IR 8272","url":"https://doi.org/10.6028/NIST.IR.8272"}],"objectives":[{"label":"RA-03a.","prose":"","items":[{"label":"RA-03a.01","prose":"a risk assessment is conducted to identify threats to and vulnerabilities in the system;"},{"label":"RA-03a.02","prose":"a risk assessment is conducted to determine the likelihood and magnitude of harm from unauthorized access, use, disclosure, disruption, modification, or destruction of the system; the information it processes, stores, or transmits; and any related information;"},{"label":"RA-03a.03","prose":"a risk assessment is conducted to determine the likelihood and impact of adverse effects on individuals arising from the processing of personally identifiable information;"}]},{"label":"RA-03b.","prose":"risk assessment results and risk management decisions from the organization and mission or business process perspectives are integrated with system-level risk assessments;"},{"label":"RA-03c.","prose":"risk assessment results are documented in [Selection: security and privacy plans; risk assessment report; [Assignment: organization-defined document]];"},{"label":"RA-03d.","prose":"risk assessment results are reviewed [Assignment: organization-defined frequency];"},{"label":"RA-03e.","prose":"risk assessment results are disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"RA-03f.","prose":"the risk assessment is updated [Assignment: organization-defined frequency] or when there are significant changes to the system, its environment of operation, or other conditions that may impact the security or privacy state of the system."}],"methods":[{"method":"Examine","objects":["Risk assessment policy","risk assessment procedures","security and privacy planning policy and procedures","procedures addressing organizational assessments of risk","risk assessment","risk assessment results","risk assessment reviews","risk assessment updates"]},{"method":"Interview","objects":["Organizational personnel with risk assessment responsibilities","organizational personnel with security and privacy responsibilities"]},{"method":"Test","objects":["Organizational processes for risk assessment","mechanisms supporting and/or conducting, documenting, reviewing, disseminating, and updating the risk assessment"]}]},"RA-3(1)":{"statement":[{"label":"(a)","prose":"Assess supply chain risks associated with [Assignment: organization-defined systems, system components, and system services]; and"},{"label":"(b)","prose":"Update the supply chain risk assessment [Assignment: organization-defined frequency], when there are significant changes to the relevant supply chain, or when changes to the system, environments of operation, or other conditions may necessitate a change in the supply chain."}],"discussion":["Supply chain-related events include disruption, use of defective components, insertion of counterfeits, theft, malicious development practices, improper delivery practices, and insertion of malicious code. These events can have a significant impact on the confidentiality, integrity, or availability of a system and its information and, therefore, can also adversely impact organizational operations (including mission, functions, image, or reputation), organizational assets, individuals, other organizations, and the Nation. The supply chain-related events may be unintentional or malicious and can occur at any point during the system life cycle. An analysis of supply chain risk can help an organization identify systems or components for which additional supply chain risk mitigations are required."],"params":[{"id":"RA-03(01)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined systems, system components, and system services]","guideline":"systems, system components, and system services to assess supply chain risks are defined"},{"id":"RA-03(01)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to update the supply chain risk assessment is defined"}],"related":["RA-2","RA-9","PM-17","PM-30","SR-2"],"references":[],"objectives":[{"label":"RA-03(01)(a)","prose":"supply chain risks associated with [Assignment: organization-defined systems, system components, and system services] are assessed;"},{"label":"RA-03(01)(b)","prose":"the supply chain risk assessment is updated [Assignment: organization-defined frequency], when there are significant changes to the relevant supply chain, or when changes to the system, environments of operation, or other conditions may necessitate a change in the supply chain."}],"methods":[{"method":"Examine","objects":["Supply chain risk management policy","inventory of critical systems, system components, and system services","risk assessment policy","security planning policy and procedures","procedures addressing organizational assessments of supply chain risk","risk assessment","risk assessment results","risk assessment reviews"]},{"method":"Interview","objects":["Organizational personnel with risk assessment responsibilities","organizational personnel with security responsibilities","organizational personnel with supply chain risk management responsibilities"]},{"method":"Test","objects":["Organizational processes for risk assessment","mechanisms supporting and/or conducting, documenting, reviewing, disseminating, and updating the supply chain risk assessment"]}]},"RA-5":{"statement":[{"label":"a.","prose":"Monitor and scan for vulnerabilities in the system and hosted applications [Assignment: organization-defined frequency and/or randomly in accordance with organization-defined process] and when new vulnerabilities potentially affecting the system are identified and reported;"},{"label":"b.","prose":"Employ vulnerability monitoring tools and techniques that facilitate interoperability among tools and automate parts of the vulnerability management process by using standards for:","items":[{"label":"1.","prose":"Enumerating platforms, software flaws, and improper configurations;"},{"label":"2.","prose":"Formatting checklists and test procedures; and"},{"label":"3.","prose":"Measuring vulnerability impact;"}]},{"label":"c.","prose":"Analyze vulnerability scan reports and results from vulnerability monitoring;"},{"label":"d.","prose":"Remediate legitimate vulnerabilities [Assignment: organization-defined response times] in accordance with an organizational assessment of risk;"},{"label":"e.","prose":"Share information obtained from the vulnerability monitoring process and control assessments with [Assignment: organization-defined personnel or roles] to help eliminate similar vulnerabilities in other systems; and"},{"label":"f.","prose":"Employ vulnerability monitoring tools that include the capability to readily update the vulnerabilities to be scanned."}],"discussion":["Security categorization of information and systems guides the frequency and comprehensiveness of vulnerability monitoring (including scans). Organizations determine the required vulnerability monitoring for system components, ensuring that the potential sources of vulnerabilities—such as infrastructure components (e.g., switches, routers, guards, sensors), networked printers, scanners, and copiers—are not overlooked. The capability to readily update vulnerability monitoring tools as new vulnerabilities are discovered and announced and as new scanning methods are developed helps to ensure that new vulnerabilities are not missed by employed vulnerability monitoring tools. The vulnerability monitoring tool update process helps to ensure that potential vulnerabilities in the system are identified and addressed as quickly as possible. Vulnerability monitoring and analyses for custom software may require additional approaches, such as static analysis, dynamic analysis, binary analysis, or a hybrid of the three approaches. Organizations can use these analysis approaches in source code reviews and in a variety of tools, including web-based application scanners, static analysis tools, and binary analyzers.","Vulnerability monitoring includes scanning for patch levels; scanning for functions, ports, protocols, and services that should not be accessible to users or devices; and scanning for flow control mechanisms that are improperly configured or operating incorrectly. Vulnerability monitoring may also include continuous vulnerability monitoring tools that use instrumentation to continuously analyze components. Instrumentation-based tools may improve accuracy and may be run throughout an organization without scanning. Vulnerability monitoring tools that facilitate interoperability include tools that are Security Content Automated Protocol (SCAP)-validated. Thus, organizations consider using scanning tools that express vulnerabilities in the Common Vulnerabilities and Exposures (CVE) naming convention and that employ the Open Vulnerability Assessment Language (OVAL) to determine the presence of vulnerabilities. Sources for vulnerability information include the Common Weakness Enumeration (CWE) listing and the National Vulnerability Database (NVD). Control assessments, such as red team exercises, provide additional sources of potential vulnerabilities for which to scan. Organizations also consider using scanning tools that express vulnerability impact by the Common Vulnerability Scoring System (CVSS).","Vulnerability monitoring includes a channel and process for receiving reports of security vulnerabilities from the public at-large. Vulnerability disclosure programs can be as simple as publishing a monitored email address or web form that can receive reports, including notification authorizing good-faith research and disclosure of security vulnerabilities. Organizations generally expect that such research is happening with or without their authorization and can use public vulnerability disclosure channels to increase the likelihood that discovered vulnerabilities are reported directly to the organization for remediation.","Organizations may also employ the use of financial incentives (also known as \"bug bounties\") to further encourage external security researchers to report discovered vulnerabilities. Bug bounty programs can be tailored to the organization’s needs. Bounties can be operated indefinitely or over a defined period of time and can be offered to the general public or to a curated group. Organizations may run public and private bounties simultaneously and could choose to offer partially credentialed access to certain participants in order to evaluate security vulnerabilities from privileged vantage points."],"params":[{"id":"RA-5_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined frequency and/or randomly in accordance with organization-defined process]"},{"id":"RA-05_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined frequency and/or randomly in accordance with organization-defined process]","guideline":"frequency for monitoring systems and hosted applications for vulnerabilities is defined"},{"id":"RA-05_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined frequency and/or randomly in accordance with organization-defined process]","guideline":"frequency for scanning systems and hosted applications for vulnerabilities is defined"},{"id":"RA-05_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined response times]","guideline":"response times to remediate legitimate vulnerabilities in accordance with an organizational assessment of risk are defined"},{"id":"RA-05_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles with whom information obtained from the vulnerability scanning process and control assessments is to be shared"}],"related":["CA-2","CA-7","CA-8","CM-2","CM-4","CM-6","CM-8","RA-2","RA-3","SA-11","SA-15","SC-38","SI-2","SI-3","SI-4","SI-7","SR-11"],"references":[{"title":"ISO 29147","url":"https://www.iso.org/standard/72311.html"},{"title":"SP 800-40","url":"https://doi.org/10.6028/NIST.SP.800-40r3"},{"title":"SP 800-53A","url":"https://doi.org/10.6028/NIST.SP.800-53Ar4"},{"title":"SP 800-70","url":"https://doi.org/10.6028/NIST.SP.800-70r4"},{"title":"SP 800-115","url":"https://doi.org/10.6028/NIST.SP.800-115"},{"title":"SP 800-126","url":"https://doi.org/10.6028/NIST.SP.800-126r3"},{"title":"IR 7788","url":"https://doi.org/10.6028/NIST.IR.7788"},{"title":"IR 8011-4","url":"https://doi.org/10.6028/NIST.IR.8011-4"},{"title":"IR 8023","url":"https://doi.org/10.6028/NIST.IR.8023"}],"objectives":[{"label":"RA-05a.","prose":"","items":[{"label":"RA-05a.[01]","prose":"systems and hosted applications are monitored for vulnerabilities [Assignment: organization-defined frequency and/or randomly in accordance with organization-defined process] and when new vulnerabilities potentially affecting the system are identified and reported;"},{"label":"RA-05a.[02]","prose":"systems and hosted applications are scanned for vulnerabilities [Assignment: organization-defined frequency and/or randomly in accordance with organization-defined process] and when new vulnerabilities potentially affecting the system are identified and reported;"}]},{"label":"RA-05b.","prose":"vulnerability monitoring tools and techniques are employed to facilitate interoperability among tools;","items":[{"label":"RA-05b.01","prose":"vulnerability monitoring tools and techniques are employed to automate parts of the vulnerability management process by using standards for enumerating platforms, software flaws, and improper configurations;"},{"label":"RA-05b.02","prose":"vulnerability monitoring tools and techniques are employed to facilitate interoperability among tools and to automate parts of the vulnerability management process by using standards for formatting checklists and test procedures;"},{"label":"RA-05b.03","prose":"vulnerability monitoring tools and techniques are employed to facilitate interoperability among tools and to automate parts of the vulnerability management process by using standards for measuring vulnerability impact;"}]},{"label":"RA-05c.","prose":"vulnerability scan reports and results from vulnerability monitoring are analyzed;"},{"label":"RA-05d.","prose":"legitimate vulnerabilities are remediated [Assignment: organization-defined response times] in accordance with an organizational assessment of risk;"},{"label":"RA-05e.","prose":"information obtained from the vulnerability monitoring process and control assessments is shared with [Assignment: organization-defined personnel or roles] to help eliminate similar vulnerabilities in other systems;"},{"label":"RA-05f.","prose":"vulnerability monitoring tools that include the capability to readily update the vulnerabilities to be scanned are employed."}],"methods":[{"method":"Examine","objects":["Risk assessment policy","procedures addressing vulnerability scanning","risk assessment","assessment report","vulnerability scanning tools and associated configuration documentation","vulnerability scanning results","patch and vulnerability management records","system security plan"]},{"method":"Interview","objects":["Organizational personnel with risk assessment, control assessment, and vulnerability scanning responsibilities","organizational personnel with vulnerability scan analysis responsibilities","organizational personnel with vulnerability remediation responsibilities","organizational personnel with security responsibilities","system/network administrators"]},{"method":"Test","objects":["Organizational processes for vulnerability scanning, analysis, remediation, and information sharing","mechanisms supporting and/or implementing vulnerability scanning, analysis, remediation, and information sharing"]}]},"RA-5(2)":{"statement":[{"prose":"Update the system vulnerabilities to be scanned [Selection (one or more): [Assignment: organization-defined frequency]; prior to a new scan; when new vulnerabilities are identified and reported]."}],"discussion":["Due to the complexity of modern software, systems, and other factors, new vulnerabilities are discovered on a regular basis. It is important that newly discovered vulnerabilities are added to the list of vulnerabilities to be scanned to ensure that the organization can take steps to mitigate those vulnerabilities in a timely manner."],"params":[{"id":"RA-05(02)_ODP[01]","kind":"Selection","value":"[Selection (one or more): [Assignment: organization-defined frequency]; prior to a new scan; when new vulnerabilities are identified and reported]"},{"id":"RA-05(02)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency for updating the system vulnerabilities to be scanned is defined (if selected)"}],"related":["SI-5"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Procedures addressing vulnerability scanning","assessment report","vulnerability scanning tools and associated configuration documentation","vulnerability scanning results","patch and vulnerability management records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with vulnerability scanning responsibilities","organizational personnel with vulnerability scan analysis responsibilities","organizational personnel with security responsibilities","system/network administrators"]},{"method":"Test","objects":["Organizational processes for vulnerability scanning","mechanisms/tools supporting and/or implementing vulnerability scanning"]}]},"RA-5(4)":{"statement":[{"prose":"Determine information about the system that is discoverable and take [Assignment: organization-defined corrective actions]."}],"discussion":["Discoverable information includes information that adversaries could obtain without compromising or breaching the system, such as by collecting information that the system is exposing or by conducting extensive web searches. Corrective actions include notifying appropriate organizational personnel, removing designated information, or changing the system to make the designated information less relevant or attractive to adversaries. This enhancement excludes intentionally discoverable information that may be part of a decoy capability (e.g., honeypots, honeynets, or deception nets) deployed by the organization."],"params":[{"id":"RA-05(04)_ODP","kind":"Assignment","value":"[Assignment: organization-defined corrective actions]","guideline":"corrective actions to be taken if information about the system is discoverable are defined"}],"related":["AU-13","SC-26"],"references":[],"objectives":[{"label":"RA-05(04)[01]","prose":"information about the system is discoverable;"},{"label":"RA-05(04)[02]","prose":"[Assignment: organization-defined corrective actions] are taken when information about the system is confirmed as discoverable."}],"methods":[{"method":"Examine","objects":["Procedures addressing vulnerability scanning","assessment report","penetration test results","vulnerability scanning results","risk assessment report","records of corrective actions taken","incident response records","audit records"]},{"method":"Interview","objects":["Organizational personnel with vulnerability scanning and/or penetration testing responsibilities","organizational personnel with vulnerability scan analysis responsibilities","organizational personnel responsible for risk response","organizational personnel responsible for incident management and response","organizational personnel with security responsibilities"]},{"method":"Test","objects":["Organizational processes for vulnerability scanning","organizational processes for risk response","organizational processes for incident management and response","mechanisms/tools supporting and/or implementing vulnerability scanning","mechanisms supporting and/or implementing risk response","mechanisms supporting and/or implementing incident management and response"]}]},"RA-5(5)":{"statement":[{"prose":"Implement privileged access authorization to [Assignment: organization-defined system components] for [Assignment: organization-defined vulnerability scanning activities]."}],"discussion":["In certain situations, the nature of the vulnerability scanning may be more intrusive, or the system component that is the subject of the scanning may contain classified or controlled unclassified information, such as personally identifiable information. Privileged access authorization to selected system components facilitates more thorough vulnerability scanning and protects the sensitive nature of such scanning."],"params":[{"id":"RA-05(05)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined system components]","guideline":"system components to which privileged access is authorized for selected vulnerability scanning activities are defined"},{"id":"RA-05(05)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined vulnerability scanning activities]","guideline":"vulnerability scanning activities selected for privileged access authorization to system components are defined"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Risk assessment policy","procedures addressing vulnerability scanning","system design documentation","system configuration settings and associated documentation","list of system components for vulnerability scanning","personnel access authorization list","authorization credentials","access authorization records"]},{"method":"Interview","objects":["Organizational personnel with vulnerability scanning responsibilities","system/network administrators","organizational personnel responsible for access control to the system","organizational personnel responsible for configuration management of the system","system developers","organizational personnel with security responsibilities"]},{"method":"Test","objects":["Organizational processes for vulnerability scanning","organizational processes for access control","mechanisms supporting and/or implementing access control","mechanisms/tools supporting and/or implementing vulnerability scanning"]}]},"RA-5(11)":{"statement":[{"prose":"Establish a public reporting channel for receiving reports of vulnerabilities in organizational systems and system components."}],"discussion":["The reporting channel is publicly discoverable and contains clear language authorizing good-faith research and the disclosure of vulnerabilities to the organization. The organization does not condition its authorization on an expectation of indefinite non-disclosure to the public by the reporting entity but may request a specific time period to properly remediate the vulnerability."],"params":[],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Risk assessment policy","procedures addressing vulnerability scanning","risk assessment","vulnerability scanning tools and techniques documentation","vulnerability scanning results","vulnerability management records","audit records","public reporting channel"]},{"method":"Interview","objects":["Organizational personnel with vulnerability scanning responsibilities","organizational personnel with vulnerability scan analysis responsibilities","organizational personnel with security responsibilities"]},{"method":"Test","objects":["Organizational processes for vulnerability scanning","mechanisms/tools supporting and/or implementing vulnerability scanning","mechanisms implementing the public reporting of vulnerabilities"]}]},"RA-7":{"statement":[{"prose":"Respond to findings from security and privacy assessments, monitoring, and audits in accordance with organizational risk tolerance."}],"discussion":["Organizations have many options for responding to risk including mitigating risk by implementing new controls or strengthening existing controls, accepting risk with appropriate justification or rationale, sharing or transferring risk, or avoiding risk. The risk tolerance of the organization influences risk response decisions and actions. Risk response addresses the need to determine an appropriate response to risk before generating a plan of action and milestones entry. For example, the response may be to accept risk or reject risk, or it may be possible to mitigate the risk immediately so that a plan of action and milestones entry is not needed. However, if the risk response is to mitigate the risk, and the mitigation cannot be completed immediately, a plan of action and milestones entry is generated."],"params":[],"related":["CA-5","IR-9","PM-4","PM-28","RA-2","RA-3","SR-2"],"references":[{"title":"FIPS 199","url":"https://doi.org/10.6028/NIST.FIPS.199"},{"title":"FIPS 200","url":"https://doi.org/10.6028/NIST.FIPS.200"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-37","url":"https://doi.org/10.6028/NIST.SP.800-37r2"},{"title":"SP 800-39","url":"https://doi.org/10.6028/NIST.SP.800-39"},{"title":"SP 800-160-1","url":"https://doi.org/10.6028/NIST.SP.800-160v1"}],"objectives":[{"label":"RA-07[01]","prose":"findings from security assessments are responded to in accordance with organizational risk tolerance;"},{"label":"RA-07[02]","prose":"findings from privacy assessments are responded to in accordance with organizational risk tolerance;"},{"label":"RA-07[03]","prose":"findings from monitoring are responded to in accordance with organizational risk tolerance;"},{"label":"RA-07[04]","prose":"findings from audits are responded to in accordance with organizational risk tolerance."}],"methods":[{"method":"Examine","objects":["Risk assessment policy","assessment reports","audit records/event logs","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with assessment and auditing responsibilities","system/network administrators","organizational personnel with security and privacy responsibilities"]},{"method":"Test","objects":["Organizational processes for assessments and audits","mechanisms/tools supporting and/or implementing assessments and auditing"]}]},"RA-9":{"statement":[{"prose":"Identify critical system components and functions by performing a criticality analysis for [Assignment: organization-defined systems, system components, or system services] at [Assignment: organization-defined decision points in the system development life cycle]."}],"discussion":["Not all system components, functions, or services necessarily require significant protections. For example, criticality analysis is a key tenet of supply chain risk management and informs the prioritization of protection activities. The identification of critical system components and functions considers applicable laws, executive orders, regulations, directives, policies, standards, system functionality requirements, system and component interfaces, and system and component dependencies. Systems engineers conduct a functional decomposition of a system to identify mission-critical functions and components. The functional decomposition includes the identification of organizational missions supported by the system, decomposition into the specific functions to perform those missions, and traceability to the hardware, software, and firmware components that implement those functions, including when the functions are shared by many components within and external to the system.","The operational environment of a system or a system component may impact the criticality, including the connections to and dependencies on cyber-physical systems, devices, system-of-systems, and outsourced IT services. System components that allow unmediated access to critical system components or functions are considered critical due to the inherent vulnerabilities that such components create. Component and function criticality are assessed in terms of the impact of a component or function failure on the organizational missions that are supported by the system that contains the components and functions.","Criticality analysis is performed when an architecture or design is being developed, modified, or upgraded. If such analysis is performed early in the system development life cycle, organizations may be able to modify the system design to reduce the critical nature of these components and functions, such as by adding redundancy or alternate paths into the system design. Criticality analysis can also influence the protection measures required by development contractors. In addition to criticality analysis for systems, system components, and system services, criticality analysis of information is an important consideration. Such analysis is conducted as part of security categorization in [RA-2](#ra-2)."],"params":[{"id":"RA-09_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined systems, system components, or system services]","guideline":"systems, system components, or system services to be analyzed for criticality are defined"},{"id":"RA-09_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined decision points in the system development life cycle]","guideline":"decision points in the system development life cycle when a criticality analysis is to be performed are defined"}],"related":["CP-2","PL-2","PL-8","PL-11","PM-1","PM-11","RA-2","SA-8","SA-15","SA-20","SR-5"],"references":[{"title":"IR 8179","url":"https://doi.org/10.6028/NIST.IR.8179"}],"objectives":[],"methods":[{"method":"Examine","objects":["Risk assessment policy","assessment reports","criticality analysis/finalized criticality for each component/subcomponent","audit records/event logs","analysis reports","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with assessment and auditing responsibilities","organizational personnel with criticality analysis responsibilities","system/network administrators","organizational personnel with security responsibilities"]},{"method":"Test","objects":["Organizational processes for assessments and audits","mechanisms/tools supporting and/or implementing assessments and auditing"]}]},"SA-1":{"statement":[{"label":"a.","prose":"Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:","items":[{"label":"1.","prose":"[Selection (one or more): organization-level; mission/business process-level; system-level] system and services acquisition policy that:","items":[{"label":"(a)","prose":"Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and"},{"label":"(b)","prose":"Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and"}]},{"label":"2.","prose":"Procedures to facilitate the implementation of the system and services acquisition policy and the associated system and services acquisition controls;"}]},{"label":"b.","prose":"Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the system and services acquisition policy and procedures; and"},{"label":"c.","prose":"Review and update the current system and services acquisition:","items":[{"label":"1.","prose":"Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and"},{"label":"2.","prose":"Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]."}]}],"discussion":["System and services acquisition policy and procedures address the controls in the SA family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of system and services acquisition policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to system and services acquisition policy and procedures include assessment or audit findings, security incidents or breaches, or changes in laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure."],"params":[{"id":"SA-1_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]"},{"id":"SA-01_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the system and services acquisition policy is to be disseminated is/are defined"},{"id":"SA-01_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the system and services acquisition procedures are to be disseminated is/are defined"},{"id":"SA-01_ODP[03]","kind":"Selection","value":"[Selection (one or more): organization-level; mission/business process-level; system-level]"},{"id":"SA-01_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined official]","guideline":"an official to manage the system and services acquisition policy and procedures is defined"},{"id":"SA-01_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current system and services acquisition policy is reviewed and updated is defined"},{"id":"SA-01_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require the current system and services acquisition policy to be reviewed and updated are defined"},{"id":"SA-01_ODP[07]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current system and services acquisition procedures are reviewed and updated is defined"},{"id":"SA-01_ODP[08]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require the system and services acquisition procedures to be reviewed and updated are defined"}],"related":["PM-9","PS-8","SA-8","SI-12"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-12","url":"https://doi.org/10.6028/NIST.SP.800-12r1"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-39","url":"https://doi.org/10.6028/NIST.SP.800-39"},{"title":"SP 800-100","url":"https://doi.org/10.6028/NIST.SP.800-100"},{"title":"SP 800-160-1","url":"https://doi.org/10.6028/NIST.SP.800-160v1"}],"objectives":[{"label":"SA-01a.","prose":"","items":[{"label":"SA-01a.[01]","prose":"a system and services acquisition policy is developed and documented;"},{"label":"SA-01a.[02]","prose":"the system and services acquisition policy is disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"SA-01a.[03]","prose":"system and services acquisition procedures to facilitate the implementation of the system and services acquisition policy and associated system and services acquisition controls are developed and documented;"},{"label":"SA-01a.[04]","prose":"the system and services acquisition procedures are disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"SA-01a.01","prose":"","items":[{"label":"SA-01a.01(a)","prose":"","items":[{"label":"SA-01a.01(a)[01]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] system and services acquisition policy addresses purpose;"},{"label":"SA-01a.01(a)[02]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] system and services acquisition policy addresses scope;"},{"label":"SA-01a.01(a)[03]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] system and services acquisition policy addresses roles;"},{"label":"SA-01a.01(a)[04]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] system and services acquisition policy addresses responsibilities;"},{"label":"SA-01a.01(a)[05]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] system and services acquisition policy addresses management commitment;"},{"label":"SA-01a.01(a)[06]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] system and services acquisition policy addresses coordination among organizational entities;"},{"label":"SA-01a.01(a)[07]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] system and services acquisition policy addresses compliance;"}]},{"label":"SA-01a.01(b)","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] system and services acquisition policy is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines;"}]}]},{"label":"SA-01b.","prose":"the [Assignment: organization-defined official] is designated to manage the development, documentation, and dissemination of the system and services acquisition policy and procedures;"},{"label":"SA-01c.","prose":"","items":[{"label":"SA-01c.01","prose":"","items":[{"label":"SA-01c.01[01]","prose":"the system and services acquisition policy is reviewed and updated [Assignment: organization-defined frequency];"},{"label":"SA-01c.01[02]","prose":"the current system and services acquisition policy is reviewed and updated following [Assignment: organization-defined events];"}]},{"label":"SA-01c.02","prose":"","items":[{"label":"SA-01c.02[01]","prose":"the current system and services acquisition procedures are reviewed and updated [Assignment: organization-defined frequency];"},{"label":"SA-01c.02[02]","prose":"the current system and services acquisition procedures are reviewed and updated following [Assignment: organization-defined events]."}]}]}],"methods":[{"method":"Examine","objects":["System and services acquisition policy","system and services acquisition procedures","supply chain risk management policy","supply chain risk management procedures","supply chain risk management plan","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system and services acquisition responsibilities","organizational personnel with information security and privacy responsibilities","organizational personnel with supply chain risk management responsibilities"]}]},"SA-2":{"statement":[{"label":"a.","prose":"Determine the high-level information security and privacy requirements for the system or system service in mission and business process planning;"},{"label":"b.","prose":"Determine, document, and allocate the resources required to protect the system or system service as part of the organizational capital planning and investment control process; and"},{"label":"c.","prose":"Establish a discrete line item for information security and privacy in organizational programming and budgeting documentation."}],"discussion":["Resource allocation for information security and privacy includes funding for system and services acquisition, sustainment, and supply chain-related risks throughout the system development life cycle."],"params":[],"related":["PL-7","PM-3","PM-11","SA-9","SR-3","SR-5"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-37","url":"https://doi.org/10.6028/NIST.SP.800-37r2"},{"title":"SP 800-160-1","url":"https://doi.org/10.6028/NIST.SP.800-160v1"}],"objectives":[{"label":"SA-02a.","prose":"","items":[{"label":"SA-02a.[01]","prose":"the high-level information security requirements for the system or system service are determined in mission and business process planning;"},{"label":"SA-02a.[02]","prose":"the high-level privacy requirements for the system or system service are determined in mission and business process planning;"}]},{"label":"SA-02b.","prose":"","items":[{"label":"SA-02b.[01]","prose":"the resources required to protect the system or system service are determined and documented as part of the organizational capital planning and investment control process;"},{"label":"SA-02b.[02]","prose":"the resources required to protect the system or system service are allocated as part of the organizational capital planning and investment control process;"}]},{"label":"SA-02c.","prose":"","items":[{"label":"SA-02c.[01]","prose":"a discrete line item for information security is established in organizational programming and budgeting documentation;"},{"label":"SA-02c.[02]","prose":"a discrete line item for privacy is established in organizational programming and budgeting documentation."}]}],"methods":[{"method":"Examine","objects":["System and services acquisition policy","system and services acquisition procedures","system and services acquisition strategy and plans","procedures addressing the allocation of resources to information security and privacy requirements","procedures addressing capital planning and investment control","organizational programming and budgeting documentation","system security plan","privacy plan"]},{"method":"Interview","objects":["Organizational personnel with capital planning, investment control, organizational programming, and budgeting responsibilities","organizational personnel with information security and privacy responsibilities","organizational personnel with supply chain risk management responsibilities"]},{"method":"Test","objects":["Organizational processes for determining information security and privacy requirements","organizational processes for capital planning, programming, and budgeting","mechanisms supporting and/or implementing organizational capital planning, programming, and budgeting"]}]},"SA-3":{"statement":[{"label":"a.","prose":"Acquire, develop, and manage the system using [Assignment: organization-defined system-development life cycle] that incorporates information security and privacy considerations;"},{"label":"b.","prose":"Define and document information security and privacy roles and responsibilities throughout the system development life cycle;"},{"label":"c.","prose":"Identify individuals having information security and privacy roles and responsibilities; and"},{"label":"d.","prose":"Integrate the organizational information security and privacy risk management process into system development life cycle activities."}],"discussion":["A system development life cycle process provides the foundation for the successful development, implementation, and operation of organizational systems. The integration of security and privacy considerations early in the system development life cycle is a foundational principle of systems security engineering and privacy engineering. To apply the required controls within the system development life cycle requires a basic understanding of information security and privacy, threats, vulnerabilities, adverse impacts, and risk to critical mission and business functions. The security engineering principles in [SA-8](#sa-8) help individuals properly design, code, and test systems and system components. Organizations include qualified personnel (e.g., senior agency information security officers, senior agency officials for privacy, security and privacy architects, and security and privacy engineers) in system development life cycle processes to ensure that established security and privacy requirements are incorporated into organizational systems. Role-based security and privacy training programs can ensure that individuals with key security and privacy roles and responsibilities have the experience, skills, and expertise to conduct assigned system development life cycle activities.","The effective integration of security and privacy requirements into enterprise architecture also helps to ensure that important security and privacy considerations are addressed throughout the system life cycle and that those considerations are directly related to organizational mission and business processes. This process also facilitates the integration of the information security and privacy architectures into the enterprise architecture, consistent with the risk management strategy of the organization. Because the system development life cycle involves multiple organizations, (e.g., external suppliers, developers, integrators, service providers), acquisition and supply chain risk management functions and controls play significant roles in the effective management of the system during the life cycle."],"params":[{"id":"SA-03_ODP","kind":"Assignment","value":"[Assignment: organization-defined system-development life cycle]","guideline":"system development life cycle is defined"}],"related":["AT-3","PL-8","PM-7","SA-4","SA-5","SA-8","SA-11","SA-15","SA-17","SA-22","SR-3","SR-4","SR-5","SR-9"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-37","url":"https://doi.org/10.6028/NIST.SP.800-37r2"},{"title":"SP 800-160-1","url":"https://doi.org/10.6028/NIST.SP.800-160v1"},{"title":"SP 800-171","url":"https://doi.org/10.6028/NIST.SP.800-171r2"},{"title":"SP 800-172","url":"https://doi.org/10.6028/NIST.SP.800-172-draft"}],"objectives":[{"label":"SA-03a.","prose":"","items":[{"label":"SA-03a.[01]","prose":"the system is acquired, developed, and managed using [Assignment: organization-defined system-development life cycle] that incorporates information security considerations;"},{"label":"SA-03a.[02]","prose":"the system is acquired, developed, and managed using [Assignment: organization-defined system-development life cycle] that incorporates privacy considerations;"}]},{"label":"SA-03b.","prose":"","items":[{"label":"SA-03b.[01]","prose":"information security roles and responsibilities are defined and documented throughout the system development life cycle;"},{"label":"SA-03b.[02]","prose":"privacy roles and responsibilities are defined and documented throughout the system development life cycle;"}]},{"label":"SA-03c.","prose":"","items":[{"label":"SA-03c.[01]","prose":"individuals with information security roles and responsibilities are identified;"},{"label":"SA-03c.[02]","prose":"individuals with privacy roles and responsibilities are identified;"}]},{"label":"SA-03d.","prose":"","items":[{"label":"SA-03d.[01]","prose":"organizational information security risk management processes are integrated into system development life cycle activities;"},{"label":"SA-03d.[02]","prose":"organizational privacy risk management processes are integrated into system development life cycle activities."}]}],"methods":[{"method":"Examine","objects":["System and services acquisition policy","system and services acquisition procedures","procedures addressing the integration of information security and privacy and supply chain risk management into the system development life cycle process","system development life cycle documentation","organizational risk management strategy","information security and privacy risk management strategy documentation","system security plan","privacy plan"]},{"method":"Interview","objects":["Organizational personnel with information security and privacy responsibilities","organizational personnel with system life cycle development responsibilities","organizational personnel with supply chain risk management responsibilities"]},{"method":"Test","objects":["Organizational processes for defining and documenting the system development life cycle","organizational processes for identifying system development life cycle roles and responsibilities","organizational processes for integrating information security and privacy and supply chain risk management into the system development life cycle","mechanisms supporting and/or implementing the system development life cycle"]}]},"SA-4":{"statement":[{"prose":"Include the following requirements, descriptions, and criteria, explicitly or by reference, using [Selection (one or more): standardized contract language; [Assignment: organization-defined contract language]] in the acquisition contract for the system, system component, or system service:"},{"label":"a.","prose":"Security and privacy functional requirements;"},{"label":"b.","prose":"Strength of mechanism requirements;"},{"label":"c.","prose":"Security and privacy assurance requirements;"},{"label":"d.","prose":"Controls needed to satisfy the security and privacy requirements."},{"label":"e.","prose":"Security and privacy documentation requirements;"},{"label":"f.","prose":"Requirements for protecting security and privacy documentation;"},{"label":"g.","prose":"Description of the system development environment and environment in which the system is intended to operate;"},{"label":"h.","prose":"Allocation of responsibility or identification of parties responsible for information security, privacy, and supply chain risk management; and"},{"label":"i.","prose":"Acceptance criteria."}],"discussion":["Security and privacy functional requirements are typically derived from the high-level security and privacy requirements described in [SA-2](#sa-2). The derived requirements include security and privacy capabilities, functions, and mechanisms. Strength requirements associated with such capabilities, functions, and mechanisms include degree of correctness, completeness, resistance to tampering or bypass, and resistance to direct attack. Assurance requirements include development processes, procedures, and methodologies as well as the evidence from development and assessment activities that provide grounds for confidence that the required functionality is implemented and possesses the required strength of mechanism. [SP 800-160-1](#e3cc0520-a366-4fc9-abc2-5272db7e3564) describes the process of requirements engineering as part of the system development life cycle.","Controls can be viewed as descriptions of the safeguards and protection capabilities appropriate for achieving the particular security and privacy objectives of the organization and for reflecting the security and privacy requirements of stakeholders. Controls are selected and implemented in order to satisfy system requirements and include developer and organizational responsibilities. Controls can include technical, administrative, and physical aspects. In some cases, the selection and implementation of a control may necessitate additional specification by the organization in the form of derived requirements or instantiated control parameter values. The derived requirements and control parameter values may be necessary to provide the appropriate level of implementation detail for controls within the system development life cycle.","Security and privacy documentation requirements address all stages of the system development life cycle. Documentation provides user and administrator guidance for the implementation and operation of controls. The level of detail required in such documentation is based on the security categorization or classification level of the system and the degree to which organizations depend on the capabilities, functions, or mechanisms to meet risk response expectations. Requirements can include mandated configuration settings that specify allowed functions, ports, protocols, and services. Acceptance criteria for systems, system components, and system services are defined in the same manner as the criteria for any organizational acquisition or procurement.","Organizations can determine other requirements that support security and operations, to include responsibilities for the organization and developer, and notification and timing requirements for support, maintenance and updates."],"params":[{"id":"SA-04_ODP[01]","kind":"Selection","value":"[Selection (one or more): standardized contract language; [Assignment: organization-defined contract language]]"},{"id":"SA-04_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined contract language]","guideline":"contract language is defined (if selected)"}],"related":["CM-6","CM-8","PS-7","SA-3","SA-5","SA-8","SA-11","SA-15","SA-16","SA-17","SA-21","SR-3","SR-5"],"references":[{"title":"PRIVACT","url":"https://www.govinfo.gov/content/pkg/STATUTE-88/pdf/STATUTE-88-Pg1896.pdf"},{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"ISO 15408-1","url":"https://www.commoncriteriaportal.org/files/ccfiles/CCPART1V3.1R5.pdf"},{"title":"ISO 15408-2","url":"https://www.commoncriteriaportal.org/files/ccfiles/CCPART2V3.1R5.pdf"},{"title":"ISO 15408-3","url":"https://www.commoncriteriaportal.org/files/ccfiles/CCPART3V3.1R5.pdf"},{"title":"ISO 29148","url":"https://www.iso.org/standard/72089.html"},{"title":"FIPS 140-3","url":"https://doi.org/10.6028/NIST.FIPS.140-3"},{"title":"FIPS 201-2","url":"https://doi.org/10.6028/NIST.FIPS.201-2"},{"title":"SP 800-35","url":"https://doi.org/10.6028/NIST.SP.800-35"},{"title":"SP 800-37","url":"https://doi.org/10.6028/NIST.SP.800-37r2"},{"title":"SP 800-70","url":"https://doi.org/10.6028/NIST.SP.800-70r4"},{"title":"SP 800-73-4","url":"https://doi.org/10.6028/NIST.SP.800-73-4"},{"title":"SP 800-137","url":"https://doi.org/10.6028/NIST.SP.800-137"},{"title":"SP 800-160-1","url":"https://doi.org/10.6028/NIST.SP.800-160v1"},{"title":"SP 800-161","url":"https://doi.org/10.6028/NIST.SP.800-161"},{"title":"IR 7539","url":"https://doi.org/10.6028/NIST.IR.7539"},{"title":"IR 7622","url":"https://doi.org/10.6028/NIST.IR.7622"},{"title":"IR 7676","url":"https://doi.org/10.6028/NIST.IR.7676"},{"title":"IR 7870","url":"https://doi.org/10.6028/NIST.IR.7870"},{"title":"IR 8062","url":"https://doi.org/10.6028/NIST.IR.8062"},{"title":"NIAP CCEVS","url":"https://www.niap-ccevs.org"},{"title":"NSA CSFC","url":"https://www.nsa.gov/resources/everyone/csfc"}],"objectives":[{"label":"SA-04a.","prose":"","items":[{"label":"SA-04a.[01]","prose":"security functional requirements, descriptions, and criteria are included explicitly or by reference using [Selection (one or more): standardized contract language; [Assignment: organization-defined contract language]] in the acquisition contract for the system, system component, or system service;"},{"label":"SA-04a.[02]","prose":"privacy functional requirements, descriptions, and criteria are included explicitly or by reference using [Selection (one or more): standardized contract language; [Assignment: organization-defined contract language]] in the acquisition contract for the system, system component, or system service;"}]},{"label":"SA-04b.","prose":"strength of mechanism requirements, descriptions, and criteria are included explicitly or by reference using [Selection (one or more): standardized contract language; [Assignment: organization-defined contract language]] in the acquisition contract for the system, system component, or system service;"},{"label":"SA-04c.","prose":"","items":[{"label":"SA-04c.[01]","prose":"security assurance requirements, descriptions, and criteria are included explicitly or by reference using [Selection (one or more): standardized contract language; [Assignment: organization-defined contract language]] in the acquisition contract for the system, system component, or system service;"},{"label":"SA-04c.[02]","prose":"privacy assurance requirements, descriptions, and criteria are included explicitly or by reference using [Selection (one or more): standardized contract language; [Assignment: organization-defined contract language]] in the acquisition contract for the system, system component, or system service;"}]},{"label":"SA-04d.","prose":"","items":[{"label":"SA-04d.[01]","prose":"controls needed to satisfy the security requirements, descriptions, and criteria are included explicitly or by reference using [Selection (one or more): standardized contract language; [Assignment: organization-defined contract language]] in the acquisition contract for the system, system component, or system service;"},{"label":"SA-04d.[02]","prose":"controls needed to satisfy the privacy requirements, descriptions, and criteria are included explicitly or by reference using [Selection (one or more): standardized contract language; [Assignment: organization-defined contract language]] in the acquisition contract for the system, system component, or system service;"}]},{"label":"SA-04e.","prose":"","items":[{"label":"SA-04e.[01]","prose":"security documentation requirements, descriptions, and criteria are included explicitly or by reference using [Selection (one or more): standardized contract language; [Assignment: organization-defined contract language]] in the acquisition contract for the system, system component, or system service;"},{"label":"SA-04e.[02]","prose":"privacy documentation requirements, descriptions, and criteria are included explicitly or by reference using [Selection (one or more): standardized contract language; [Assignment: organization-defined contract language]] in the acquisition contract for the system, system component, or system service;"}]},{"label":"SA-04f.","prose":"","items":[{"label":"SA-04f.[01]","prose":"requirements for protecting security documentation, descriptions, and criteria are included explicitly or by reference using [Selection (one or more): standardized contract language; [Assignment: organization-defined contract language]] in the acquisition contract for the system, system component, or system service;"},{"label":"SA-04f.[02]","prose":"requirements for protecting privacy documentation, descriptions, and criteria are included explicitly or by reference using [Selection (one or more): standardized contract language; [Assignment: organization-defined contract language]] in the acquisition contract for the system, system component, or system service;"}]},{"label":"SA-04g.","prose":"the description of the system development environment and environment in which the system is intended to operate, requirements, and criteria are included explicitly or by reference using [Selection (one or more): standardized contract language; [Assignment: organization-defined contract language]] in the acquisition contract for the system, system component, or system service;"},{"label":"SA-04h.","prose":"","items":[{"label":"SA-04h.[01]","prose":"the allocation of responsibility or identification of parties responsible for information security requirements, descriptions, and criteria are included explicitly or by reference using [Selection (one or more): standardized contract language; [Assignment: organization-defined contract language]] in the acquisition contract for the system, system component, or system service;"},{"label":"SA-04h.[02]","prose":"the allocation of responsibility or identification of parties responsible for privacy requirements, descriptions, and criteria are included explicitly or by reference using [Selection (one or more): standardized contract language; [Assignment: organization-defined contract language]];"},{"label":"SA-04h.[03]","prose":"the allocation of responsibility or identification of parties responsible for supply chain risk management requirements, descriptions, and criteria are included explicitly or by reference using [Selection (one or more): standardized contract language; [Assignment: organization-defined contract language]];"}]},{"label":"SA-04i.","prose":"acceptance criteria requirements and descriptions are included explicitly or by reference using [Selection (one or more): standardized contract language; [Assignment: organization-defined contract language]] in the acquisition contract for the system, system component, or system service."}],"methods":[{"method":"Examine","objects":["System and services acquisition policy","system and services acquisition procedures","procedures addressing the integration of information security and privacy and supply chain risk management into the acquisition process","configuration management plan","acquisition contracts for the system, system component, or system service","system design documentation","system security plan","supply chain risk management plan"]},{"method":"Interview","objects":["Organizational personnel with acquisition/contracting responsibilities","organizational personnel with information security and privacy responsibilities","system/network administrators","organizational personnel with supply chain risk management responsibilities"]},{"method":"Test","objects":["Organizational processes for determining system security and privacy functional, strength, and assurance requirements","organizational processes for developing acquisition contracts","mechanisms supporting and/or implementing acquisitions and the inclusion of security and privacy requirements in contracts"]}]},"SA-4(1)":{"statement":[{"prose":"Require the developer of the system, system component, or system service to provide a description of the functional properties of the controls to be implemented."}],"discussion":["Functional properties of security and privacy controls describe the functionality (i.e., security or privacy capability, functions, or mechanisms) visible at the interfaces of the controls and specifically exclude functionality and data structures internal to the operation of the controls."],"params":[],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and services acquisition policy","system and services acquisition procedures","procedures addressing the integration of security and privacy requirements, descriptions, and criteria into the acquisition process","solicitation documents","acquisition documentation","acquisition contracts for the system, system component, or system services","system security plan","privacy plan"]},{"method":"Interview","objects":["Organizational personnel with acquisition/contracting responsibilities","organizational personnel with information security and privacy responsibilities","system developers"]},{"method":"Test","objects":["Organizational processes for determining system security functional requirements","organizational processes for developing acquisition contracts","mechanisms supporting and/or implementing acquisitions and the inclusion of security and privacy requirements in contracts"]}]},"SA-4(2)":{"statement":[{"prose":"Require the developer of the system, system component, or system service to provide design and implementation information for the controls that includes: [Selection (one or more): security-relevant external system interfaces; high-level design; low-level design; source code or hardware schematics; [Assignment: organization-defined design and implementation information]] at [Assignment: organization-defined level of detail]."}],"discussion":["Organizations may require different levels of detail in the documentation for the design and implementation of controls in organizational systems, system components, or system services based on mission and business requirements, requirements for resiliency and trustworthiness, and requirements for analysis and testing. Systems can be partitioned into multiple subsystems. Each subsystem within the system can contain one or more modules. The high-level design for the system is expressed in terms of subsystems and the interfaces between subsystems providing security-relevant functionality. The low-level design for the system is expressed in terms of modules and the interfaces between modules providing security-relevant functionality. Design and implementation documentation can include manufacturer, version, serial number, verification hash signature, software libraries used, date of purchase or download, and the vendor or download source. Source code and hardware schematics are referred to as the implementation representation of the system."],"params":[{"id":"SA-04(02)_ODP[01]","kind":"Selection","value":"[Selection (one or more): security-relevant external system interfaces; high-level design; low-level design; source code or hardware schematics; [Assignment: organization-defined design and implementation information]]"},{"id":"SA-04(02)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined design and implementation information]","guideline":"design and implementation information is defined (if selected)"},{"id":"SA-04(02)_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined level of detail]","guideline":"level of detail is defined"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and services acquisition policy","system and services acquisition procedures","procedures addressing the integration of security requirements, descriptions, and criteria into the acquisition process","solicitation documents","acquisition documentation","acquisition contracts for the system, system components, or system services","design and implementation information for controls employed in the system, system component, or system service","system security plan"]},{"method":"Interview","objects":["Organizational personnel with acquisition/contracting responsibilities","organizational personnel with the responsibility to determine system security requirements","system developers or service provider","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for determining the level of detail for system design and controls","organizational processes for developing acquisition contracts","mechanisms supporting and/or implementing the development of system design details"]}]},"SA-4(5)":{"statement":[{"prose":"Require the developer of the system, system component, or system service to:"},{"label":"(a)","prose":"Deliver the system, component, or service with [Assignment: organization-defined security configurations] implemented; and"},{"label":"(b)","prose":"Use the configurations as the default for any subsequent system, component, or service reinstallation or upgrade."}],"discussion":["Examples of security configurations include the U.S. Government Configuration Baseline (USGCB), Security Technical Implementation Guides (STIGs), and any limitations on functions, ports, protocols, and services. Security characteristics can include requiring that default passwords have been changed."],"params":[{"id":"SA-04(05)_ODP","kind":"Assignment","value":"[Assignment: organization-defined security configurations]","guideline":"security configurations for the system, component, or service are defined"}],"related":[],"references":[],"objectives":[{"label":"SA-04(05)(a)","prose":"the developer of the system, system component, or system service is required to deliver the system, component, or service with [Assignment: organization-defined security configurations] implemented;"},{"label":"SA-04(05)(b)","prose":"the configurations are used as the default for any subsequent system, component, or service reinstallation or upgrade."}],"methods":[{"method":"Examine","objects":["System and services acquisition policy","procedures addressing the integration of security requirements, descriptions, and criteria into the acquisition process","solicitation documents","acquisition documentation","acquisition contracts for the system, system component, or system service","security configurations to be implemented by the developer of the system, system component, or system service","service level agreements","system security plan"]},{"method":"Interview","objects":["Organizational personnel with acquisition/contracting responsibilities","organizational personnel with the responsibility to determine system security requirements","system developers or service provider","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Mechanisms used to verify that the configuration of the system, component, or service is delivered as specified"]}]},"SA-4(9)":{"statement":[{"prose":"Require the developer of the system, system component, or system service to identify the functions, ports, protocols, and services intended for organizational use."}],"discussion":["The identification of functions, ports, protocols, and services early in the system development life cycle (e.g., during the initial requirements definition and design stages) allows organizations to influence the design of the system, system component, or system service. This early involvement in the system development life cycle helps organizations avoid or minimize the use of functions, ports, protocols, or services that pose unnecessarily high risks and understand the trade-offs involved in blocking specific ports, protocols, or services or requiring system service providers to do so. Early identification of functions, ports, protocols, and services avoids costly retrofitting of controls after the system, component, or system service has been implemented. [SA-9](#sa-9) describes the requirements for external system services. Organizations identify which functions, ports, protocols, and services are provided from external sources."],"params":[],"related":["CM-7","SA-9"],"references":[],"objectives":[{"label":"SA-04(09)[01]","prose":"the developer of the system, system component, or system service is required to identify the functions intended for organizational use;"},{"label":"SA-04(09)[02]","prose":"the developer of the system, system component, or system service is required to identify the ports intended for organizational use;"},{"label":"SA-04(09)[03]","prose":"the developer of the system, system component, or system service is required to identify the protocols intended for organizational use;"},{"label":"SA-04(09)[04]","prose":"the developer of the system, system component, or system service is required to identify the services intended for organizational use."}],"methods":[{"method":"Examine","objects":["System and services acquisition policy","procedures addressing the integration of security requirements, descriptions, and criteria into the acquisition process","system design documentation","system documentation, including functions, ports, protocols, and services intended for organizational use","acquisition contracts for systems or services","acquisition documentation","solicitation documentation","service level agreements"]},{"method":"Interview","objects":["Organizational personnel with acquisition/contracting responsibilities","organizational personnel with the responsibility for determining system security requirements","system/network administrators","organizational personnel operating, using, and/or maintaining the system","system developers","organizational personnel with information security responsibilities"]}]},"SA-4(10)":{"statement":[{"prose":"Employ only information technology products on the FIPS 201-approved products list for Personal Identity Verification (PIV) capability implemented within organizational systems."}],"discussion":["Products on the FIPS 201-approved products list meet NIST requirements for Personal Identity Verification (PIV) of Federal Employees and Contractors. PIV cards are used for multi-factor authentication in systems and organizations."],"params":[],"related":["IA-2","IA-8","PM-9"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Supply chain risk management plan","system and services acquisition policy","procedures addressing the integration of security requirements, descriptions, and criteria into the acquisition process","solicitation documentation","acquisition documentation","acquisition contracts for the system, system component, or system service","service level agreements","FIPS 201 approved products list"]},{"method":"Interview","objects":["Organizational personnel with acquisition/contracting responsibilities","organizational personnel with the responsibility for determining system security requirements","organizational personnel with the responsibility for ensuring that only FIPS 201- approved products are implemented","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for selecting and employing FIPS 201-approved products"]}]},"SA-5":{"statement":[{"label":"a.","prose":"Obtain or develop administrator documentation for the system, system component, or system service that describes:","items":[{"label":"1.","prose":"Secure configuration, installation, and operation of the system, component, or service;"},{"label":"2.","prose":"Effective use and maintenance of security and privacy functions and mechanisms; and"},{"label":"3.","prose":"Known vulnerabilities regarding configuration and use of administrative or privileged functions;"}]},{"label":"b.","prose":"Obtain or develop user documentation for the system, system component, or system service that describes:","items":[{"label":"1.","prose":"User-accessible security and privacy functions and mechanisms and how to effectively use those functions and mechanisms;"},{"label":"2.","prose":"Methods for user interaction, which enables individuals to use the system, component, or service in a more secure manner and protect individual privacy; and"},{"label":"3.","prose":"User responsibilities in maintaining the security of the system, component, or service and privacy of individuals;"}]},{"label":"c.","prose":"Document attempts to obtain system, system component, or system service documentation when such documentation is either unavailable or nonexistent and take [Assignment: organization-defined actions] in response; and"},{"label":"d.","prose":"Distribute documentation to [Assignment: organization-defined personnel or roles]."}],"discussion":["System artifacts and documentation created by the developer helps organizational personnel understand the implementation and operation of controls. Organizations consider establishing specific measures to determine the quality and completeness of the content provided. System documentation may be used to delineate roles, responsibilities and expectations of the developer and organization, support the management of supply chain risk, incident response, flaw remediation, and other functions. Personnel or roles that require documentation include system owners, system security officers, and system administrators. Attempts to obtain documentation include contacting manufacturers or suppliers and conducting web-based searches. The inability to obtain documentation may occur due to the age of the system or component or the lack of support from developers and contractors. When documentation cannot be obtained, organizations may need to recreate the documentation if it is essential to the implementation or operation of the controls. The protection provided for the documentation is commensurate with the security category or classification of the system. Documentation that addresses system vulnerabilities may require an increased level of protection. Secure operation of the system includes initially starting the system and resuming secure system operation after a lapse in system operation. An example of least privilege in software development is minimizing the functions that operate with elevated privileges (e.g., limiting the tools and functionality that operate in kernel mode)"],"params":[{"id":"SA-05_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined actions]","guideline":"actions to take when system, system component, or system service documentation is either unavailable or nonexistent are defined"},{"id":"SA-05_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to distribute system documentation to is/are defined"}],"related":["CM-4","CM-6","CM-7","CM-8","PL-2","PL-4","PL-8","PS-2","SA-3","SA-4","SA-8","SA-9","SA-10","SA-11","SA-15","SA-16","SA-17","SI-12","SR-3"],"references":[{"title":"SP 800-160-1","url":"https://doi.org/10.6028/NIST.SP.800-160v1"}],"objectives":[{"label":"SA-05a.","prose":"","items":[{"label":"SA-05a.01","prose":"","items":[{"label":"SA-05a.01[01]","prose":"administrator documentation for the system, system component, or system service that describes the secure configuration of the system, component, or service is obtained or developed;"},{"label":"SA-05a.01[02]","prose":"administrator documentation for the system, system component, or system service that describes the secure installation of the system, component, or service is obtained or developed;"},{"label":"SA-05a.01[03]","prose":"administrator documentation for the system, system component, or system service that describes the secure operation of the system, component, or service is obtained or developed;"}]},{"label":"SA-05a.02","prose":"","items":[{"label":"SA-05a.02[01]","prose":"administrator documentation for the system, system component, or system service that describes the effective use of security functions and mechanisms is obtained or developed;"},{"label":"SA-05a.02[02]","prose":"administrator documentation for the system, system component, or system service that describes the effective maintenance of security functions and mechanisms is obtained or developed;"},{"label":"SA-05a.02[03]","prose":"administrator documentation for the system, system component, or system service that describes the effective use of privacy functions and mechanisms is obtained or developed;"},{"label":"SA-05a.02[04]","prose":"administrator documentation for the system, system component, or system service that describes the effective maintenance of privacy functions and mechanisms is obtained or developed;"}]},{"label":"SA-05a.03","prose":"","items":[{"label":"SA-05a.03[01]","prose":"administrator documentation for the system, system component, or system service that describes known vulnerabilities regarding the configuration of administrative or privileged functions is obtained or developed;"},{"label":"SA-05a.03[02]","prose":"administrator documentation for the system, system component, or system service that describes known vulnerabilities regarding the use of administrative or privileged functions is obtained or developed;"}]}]},{"label":"SA-05b.","prose":"","items":[{"label":"SA-05b.01","prose":"","items":[{"label":"SA-05b.01[01]","prose":"user documentation for the system, system component, or system service that describes user-accessible security functions and mechanisms is obtained or developed;"},{"label":"SA-05b.01[02]","prose":"user documentation for the system, system component, or system service that describes how to effectively use those (user-accessible security) functions and mechanisms is obtained or developed;"},{"label":"SA-05b.01[03]","prose":"user documentation for the system, system component, or system service that describes user-accessible privacy functions and mechanisms is obtained or developed;"},{"label":"SA-05b.01[04]","prose":"user documentation for the system, system component, or system service that describes how to effectively use those (user-accessible privacy) functions and mechanisms is obtained or developed;"}]},{"label":"SA-05b.02","prose":"","items":[{"label":"SA-05b.02[01]","prose":"user documentation for the system, system component, or system service that describes methods for user interaction, which enable individuals to use the system, component, or service in a more secure manner is obtained or developed;"},{"label":"SA-05b.02[02]","prose":"user documentation for the system, system component, or system service that describes methods for user interaction, which enable individuals to use the system, component, or service to protect individual privacy is obtained or developed;"}]},{"label":"SA-05b.03","prose":"","items":[{"label":"SA-05b.03[01]","prose":"user documentation for the system, system component, or system service that describes user responsibilities for maintaining the security of the system, component, or service is obtained or developed;"},{"label":"SA-05b.03[02]","prose":"user documentation for the system, system component, or system service that describes user responsibilities for maintaining the privacy of individuals is obtained or developed;"}]}]},{"label":"SA-05c.","prose":"","items":[{"label":"SA-05c.[01]","prose":"attempts to obtain system, system component, or system service documentation when such documentation is either unavailable or nonexistent is documented;"},{"label":"SA-05c.[02]","prose":"after attempts to obtain system, system component, or system service documentation when such documentation is either unavailable or nonexistent, [Assignment: organization-defined actions] are taken in response;"}]},{"label":"SA-05d.","prose":"documentation is distributed to [Assignment: organization-defined personnel or roles]."}],"methods":[{"method":"Examine","objects":["System and services acquisition policy","system and services acquisition procedures","procedures addressing system documentation","system documentation, including administrator and user guides","system design documentation","records documenting attempts to obtain unavailable or nonexistent system documentation","list of actions to be taken in response to documented attempts to obtain system, system component, or system service documentation","risk management strategy documentation"]},{"method":"Interview","objects":["Organizational personnel with acquisition/contracting responsibilities","organizational personnel with information security and privacy responsibilities","system administrators","organizational personnel responsible for operating, using, and/or maintaining the system","system developers"]},{"method":"Test","objects":["Organizational processes for obtaining, protecting, and distributing system administrator and user documentation"]}]},"SA-8":{"statement":[{"prose":"Apply the following systems security and privacy engineering principles in the specification, design, development, implementation, and modification of the system and system components: [Assignment: organization-defined systems security and privacy engineering principles]."}],"discussion":["Systems security and privacy engineering principles are closely related to and implemented throughout the system development life cycle (see [SA-3](#sa-3)). Organizations can apply systems security and privacy engineering principles to new systems under development or to systems undergoing upgrades. For existing systems, organizations apply systems security and privacy engineering principles to system upgrades and modifications to the extent feasible, given the current state of hardware, software, and firmware components within those systems.","The application of systems security and privacy engineering principles helps organizations develop trustworthy, secure, and resilient systems and reduces the susceptibility to disruptions, hazards, threats, and the creation of privacy problems for individuals. Examples of system security engineering principles include: developing layered protections; establishing security and privacy policies, architecture, and controls as the foundation for design and development; incorporating security and privacy requirements into the system development life cycle; delineating physical and logical security boundaries; ensuring that developers are trained on how to build secure software; tailoring controls to meet organizational needs; and performing threat modeling to identify use cases, threat agents, attack vectors and patterns, design patterns, and compensating controls needed to mitigate risk.","Organizations that apply systems security and privacy engineering concepts and principles can facilitate the development of trustworthy, secure systems, system components, and system services; reduce risk to acceptable levels; and make informed risk management decisions. System security engineering principles can also be used to protect against certain supply chain risks, including incorporating tamper-resistant hardware into a design."],"params":[{"id":"SA-8_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined systems security and privacy engineering principles]"},{"id":"SA-08_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined systems security engineering principles]","guideline":"systems security engineering principles are defined"},{"id":"SA-08_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined privacy engineering principles]","guideline":"privacy engineering principles are defined"}],"related":["PL-8","PM-7","RA-2","RA-3","RA-9","SA-3","SA-4","SA-15","SA-17","SA-20","SC-2","SC-3","SC-32","SC-39","SR-2","SR-3","SR-4","SR-5"],"references":[{"title":"PRIVACT","url":"https://www.govinfo.gov/content/pkg/STATUTE-88/pdf/STATUTE-88-Pg1896.pdf"},{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"FIPS 199","url":"https://doi.org/10.6028/NIST.FIPS.199"},{"title":"FIPS 200","url":"https://doi.org/10.6028/NIST.FIPS.200"},{"title":"SP 800-37","url":"https://doi.org/10.6028/NIST.SP.800-37r2"},{"title":"SP 800-53A","url":"https://doi.org/10.6028/NIST.SP.800-53Ar4"},{"title":"SP 800-60-1","url":"https://doi.org/10.6028/NIST.SP.800-60v1r1"},{"title":"SP 800-60-2","url":"https://doi.org/10.6028/NIST.SP.800-60v2r1"},{"title":"SP 800-160-1","url":"https://doi.org/10.6028/NIST.SP.800-160v1"},{"title":"IR 8062","url":"https://doi.org/10.6028/NIST.IR.8062"},{"title":"SP 800-160-2","url":"https://doi.org/10.6028/NIST.SP.800-160v2"}],"objectives":[{"label":"SA-08[01]","prose":"[Assignment: organization-defined systems security engineering principles] are applied in the specification of the system and system components;"},{"label":"SA-08[02]","prose":"[Assignment: organization-defined systems security engineering principles] are applied in the design of the system and system components;"},{"label":"SA-08[03]","prose":"[Assignment: organization-defined systems security engineering principles] are applied in the development of the system and system components;"},{"label":"SA-08[04]","prose":"[Assignment: organization-defined systems security engineering principles] are applied in the implementation of the system and system components;"},{"label":"SA-08[05]","prose":"[Assignment: organization-defined systems security engineering principles] are applied in the modification of the system and system components;"},{"label":"SA-08[06]","prose":"[Assignment: organization-defined privacy engineering principles] are applied in the specification of the system and system components;"},{"label":"SA-08[07]","prose":"[Assignment: organization-defined privacy engineering principles] are applied in the design of the system and system components;"},{"label":"SA-08[08]","prose":"[Assignment: organization-defined privacy engineering principles] are applied in the development of the system and system components;"},{"label":"SA-08[09]","prose":"[Assignment: organization-defined privacy engineering principles] are applied in the implementation of the system and system components;"},{"label":"SA-08[10]","prose":"[Assignment: organization-defined privacy engineering principles] are applied in the modification of the system and system components."}],"methods":[{"method":"Examine","objects":["System and services acquisition policy","system and services acquisition procedures","assessment and authorization procedures","procedures addressing security and privacy engineering principles used in the specification, design, development, implementation, and modification of the system","system design documentation","security and privacy requirements and specifications for the system","system security plan","privacy plan"]},{"method":"Interview","objects":["Organizational personnel with acquisition/contracting responsibilities","organizational personnel with information security and privacy responsibilities","organizational personnel with system specification, design, development, implementation, and modification responsibilities","system developers"]},{"method":"Test","objects":["Organizational processes for applying security and privacy engineering principles in system specification, design, development, implementation, and modification","mechanisms supporting the application of security and privacy engineering principles in system specification, design, development, implementation, and modification"]}]},"SA-9":{"statement":[{"label":"a.","prose":"Require that providers of external system services comply with organizational security and privacy requirements and employ the following controls: [Assignment: organization-defined controls];"},{"label":"b.","prose":"Define and document organizational oversight and user roles and responsibilities with regard to external system services; and"},{"label":"c.","prose":"Employ the following processes, methods, and techniques to monitor control compliance by external service providers on an ongoing basis: [Assignment: organization-defined processes, methods, and techniques]."}],"discussion":["External system services are provided by an external provider, and the organization has no direct control over the implementation of the required controls or the assessment of control effectiveness. Organizations establish relationships with external service providers in a variety of ways, including through business partnerships, contracts, interagency agreements, lines of business arrangements, licensing agreements, joint ventures, and supply chain exchanges. The responsibility for managing risks from the use of external system services remains with authorizing officials. For services external to organizations, a chain of trust requires that organizations establish and retain a certain level of confidence that each provider in the consumer-provider relationship provides adequate protection for the services rendered. The extent and nature of this chain of trust vary based on relationships between organizations and the external providers. Organizations document the basis for the trust relationships so that the relationships can be monitored. External system services documentation includes government, service providers, end user security roles and responsibilities, and service-level agreements. Service-level agreements define the expectations of performance for implemented controls, describe measurable outcomes, and identify remedies and response requirements for identified instances of noncompliance."],"params":[{"id":"SA-09_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined controls]","guideline":"controls to be employed by external system service providers are defined"},{"id":"SA-09_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined processes, methods, and techniques]","guideline":"processes, methods, and techniques employed to monitor control compliance by external service providers are defined"}],"related":["AC-20","CA-3","CP-2","IR-4","IR-7","PL-10","PL-11","PS-7","SA-2","SA-4","SR-3","SR-5"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-35","url":"https://doi.org/10.6028/NIST.SP.800-35"},{"title":"SP 800-160-1","url":"https://doi.org/10.6028/NIST.SP.800-160v1"},{"title":"SP 800-161","url":"https://doi.org/10.6028/NIST.SP.800-161"},{"title":"SP 800-171","url":"https://doi.org/10.6028/NIST.SP.800-171r2"}],"objectives":[{"label":"SA-09a.","prose":"","items":[{"label":"SA-09a.[01]","prose":"providers of external system services comply with organizational security requirements;"},{"label":"SA-09a.[02]","prose":"providers of external system services comply with organizational privacy requirements;"},{"label":"SA-09a.[03]","prose":"providers of external system services employ [Assignment: organization-defined controls];"}]},{"label":"SA-09b.","prose":"","items":[{"label":"SA-09b.[01]","prose":"organizational oversight with regard to external system services are defined and documented;"},{"label":"SA-09b.[02]","prose":"user roles and responsibilities with regard to external system services are defined and documented;"}]},{"label":"SA-09c.","prose":"[Assignment: organization-defined processes, methods, and techniques] are employed to monitor control compliance by external service providers on an ongoing basis."}],"methods":[{"method":"Examine","objects":["System and services acquisition policy","system and services acquisition procedures","procedures addressing methods and techniques for monitoring control compliance by external service providers of system services","acquisition documentation","contracts","service level agreements","interagency agreements","licensing agreements"]},{"method":"Interview","objects":["Organizational personnel with acquisition responsibilities","external providers of system services","organizational personnel with information security and privacy responsibilities","organizational personnel with supply chain risk management responsibilities"]},{"method":"Test","objects":["Organizational processes for monitoring security and privacy control compliance by external service providers on an ongoing basis","mechanisms for monitoring security and privacy control compliance by external service providers on an ongoing basis"]}]},"SA-9(2)":{"statement":[{"prose":"Require providers of the following external system services to identify the functions, ports, protocols, and other services required for the use of such services: [Assignment: organization-defined external system services]."}],"discussion":["Information from external service providers regarding the specific functions, ports, protocols, and services used in the provision of such services can be useful when the need arises to understand the trade-offs involved in restricting certain functions and services or blocking certain ports and protocols."],"params":[{"id":"SA-09(02)_ODP","kind":"Assignment","value":"[Assignment: organization-defined external system services]","guideline":"external system services that require the identification of functions, ports, protocols, and other services are defined"}],"related":["CM-6","CM-7"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and services acquisition policy","supply chain risk management policy and procedures","procedures addressing external system services","acquisition contracts for the system, system component, or system service","acquisition documentation","solicitation documentation","service level agreements","organizational security requirements and security specifications for external service providers"]},{"method":"Interview","objects":["Organizational personnel with system and service acquisition responsibilities","organizational personnel with information security responsibilities","system/network administrators","external providers of system services"]}]},"SA-10":{"statement":[{"prose":"Require the developer of the system, system component, or system service to:"},{"label":"a.","prose":"Perform configuration management during system, component, or service [Selection (one or more): design; development; implementation; operation; disposal];"},{"label":"b.","prose":"Document, manage, and control the integrity of changes to [Assignment: organization-defined configuration items];"},{"label":"c.","prose":"Implement only organization-approved changes to the system, component, or service;"},{"label":"d.","prose":"Document approved changes to the system, component, or service and the potential security and privacy impacts of such changes; and"},{"label":"e.","prose":"Track security flaws and flaw resolution within the system, component, or service and report findings to [Assignment: organization-defined personnel]."}],"discussion":["Organizations consider the quality and completeness of configuration management activities conducted by developers as direct evidence of applying effective security controls. Controls include protecting the master copies of material used to generate security-relevant portions of the system hardware, software, and firmware from unauthorized modification or destruction. Maintaining the integrity of changes to the system, system component, or system service requires strict configuration control throughout the system development life cycle to track authorized changes and prevent unauthorized changes.","The configuration items that are placed under configuration management include the formal model; the functional, high-level, and low-level design specifications; other design data; implementation documentation; source code and hardware schematics; the current running version of the object code; tools for comparing new versions of security-relevant hardware descriptions and source code with previous versions; and test fixtures and documentation. Depending on the mission and business needs of organizations and the nature of the contractual relationships in place, developers may provide configuration management support during the operations and maintenance stage of the system development life cycle."],"params":[{"id":"SA-10_ODP[01]","kind":"Selection","value":"[Selection (one or more): design; development; implementation; operation; disposal]"},{"id":"SA-10_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined configuration items]","guideline":"configuration items under configuration management are defined"},{"id":"SA-10_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined personnel]","guideline":"personnel to whom security flaws and flaw resolutions within the system, component, or service are reported is/are defined"}],"related":["CM-2","CM-3","CM-4","CM-7","CM-9","SA-4","SA-5","SA-8","SA-15","SI-2","SR-3","SR-4","SR-5","SR-6"],"references":[{"title":"FIPS 140-3","url":"https://doi.org/10.6028/NIST.FIPS.140-3"},{"title":"FIPS 180-4","url":"https://doi.org/10.6028/NIST.FIPS.180-4"},{"title":"FIPS 202","url":"https://doi.org/10.6028/NIST.FIPS.202"},{"title":"SP 800-128","url":"https://doi.org/10.6028/NIST.SP.800-128"},{"title":"SP 800-160-1","url":"https://doi.org/10.6028/NIST.SP.800-160v1"}],"objectives":[{"label":"SA-10a.","prose":"the developer of the system, system component, or system service is required to perform configuration management during system, component, or service [Selection (one or more): design; development; implementation; operation; disposal];"},{"label":"SA-10b.","prose":"","items":[{"label":"SA-10b.[01]","prose":"the developer of the system, system component, or system service is required to document the integrity of changes to [Assignment: organization-defined configuration items];"},{"label":"SA-10b.[02]","prose":"the developer of the system, system component, or system service is required to manage the integrity of changes to [Assignment: organization-defined configuration items];"},{"label":"SA-10b.[03]","prose":"the developer of the system, system component, or system service is required to control the integrity of changes to [Assignment: organization-defined configuration items];"}]},{"label":"SA-10c.","prose":"the developer of the system, system component, or system service is required to implement only organization-approved changes to the system, component, or service;"},{"label":"SA-10d.","prose":"","items":[{"label":"SA-10d.[01]","prose":"the developer of the system, system component, or system service is required to document approved changes to the system, component, or service;"},{"label":"SA-10d.[02]","prose":"the developer of the system, system component, or system service is required to document the potential security impacts of approved changes;"},{"label":"SA-10d.[03]","prose":"the developer of the system, system component, or system service is required to document the potential privacy impacts of approved changes;"}]},{"label":"SA-10e.","prose":"","items":[{"label":"SA-10e.[01]","prose":"the developer of the system, system component, or system service is required to track security flaws within the system, component, or service;"},{"label":"SA-10e.[02]","prose":"the developer of the system, system component, or system service is required to track security flaw resolutions within the system, component, or service;"},{"label":"SA-10e.[03]","prose":"the developer of the system, system component, or system service is required to report findings to [Assignment: organization-defined personnel]."}]}],"methods":[{"method":"Examine","objects":["System and services acquisition policy","procedures addressing system developer configuration management","solicitation documentation","acquisition documentation","service level agreements","acquisition contracts for the system, system component, or system service","system developer configuration management plan","security flaw and flaw resolution tracking records"]},{"method":"Interview","objects":["Organizational personnel with system and service acquisition responsibilities","organizational personnel with information security responsibilities","organizational personnel with configuration management responsibilities","system developers"]},{"method":"Test","objects":["Organizational processes for monitoring developer configuration management","mechanisms supporting and/or implementing the monitoring of developer configuration management"]}]},"SA-11":{"statement":[{"prose":"Require the developer of the system, system component, or system service, at all post-design stages of the system development life cycle, to:"},{"label":"a.","prose":"Develop and implement a plan for ongoing security and privacy control assessments;"},{"label":"b.","prose":"Perform [Selection (one or more): unit; integration; system; regression] testing/evaluation [Assignment: organization-defined frequency to conduct] at [Assignment: organization-defined depth and coverage];"},{"label":"c.","prose":"Produce evidence of the execution of the assessment plan and the results of the testing and evaluation;"},{"label":"d.","prose":"Implement a verifiable flaw remediation process; and"},{"label":"e.","prose":"Correct flaws identified during testing and evaluation."}],"discussion":["Developmental testing and evaluation confirms that the required controls are implemented correctly, operating as intended, enforcing the desired security and privacy policies, and meeting established security and privacy requirements. Security properties of systems and the privacy of individuals may be affected by the interconnection of system components or changes to those components. The interconnections or changes—including upgrading or replacing applications, operating systems, and firmware—may adversely affect previously implemented controls. Ongoing assessment during development allows for additional types of testing and evaluation that developers can conduct to reduce or eliminate potential flaws. Testing custom software applications may require approaches such as manual code review, security architecture review, and penetration testing, as well as and static analysis, dynamic analysis, binary analysis, or a hybrid of the three analysis approaches.","Developers can use the analysis approaches, along with security instrumentation and fuzzing, in a variety of tools and in source code reviews. The security and privacy assessment plans include the specific activities that developers plan to carry out, including the types of analyses, testing, evaluation, and reviews of software and firmware components; the degree of rigor to be applied; the frequency of the ongoing testing and evaluation; and the types of artifacts produced during those processes. The depth of testing and evaluation refers to the rigor and level of detail associated with the assessment process. The coverage of testing and evaluation refers to the scope (i.e., number and type) of the artifacts included in the assessment process. Contracts specify the acceptance criteria for security and privacy assessment plans, flaw remediation processes, and the evidence that the plans and processes have been diligently applied. Methods for reviewing and protecting assessment plans, evidence, and documentation are commensurate with the security category or classification level of the system. Contracts may specify protection requirements for documentation."],"params":[{"id":"SA-11_ODP[01]","kind":"Selection","value":"[Selection (one or more): unit; integration; system; regression]"},{"id":"SA-11_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined frequency to conduct]","guideline":"frequency at which to conduct [Selection (one or more): unit; integration; system; regression] testing/evaluation is defined"},{"id":"SA-11_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined depth and coverage]","guideline":"depth and coverage of [Selection (one or more): unit; integration; system; regression] testing/evaluation is defined"}],"related":["CA-2","CA-7","CM-4","SA-3","SA-4","SA-5","SA-8","SA-15","SA-17","SI-2","SR-5","SR-6","SR-7"],"references":[{"title":"ISO 15408-3","url":"https://www.commoncriteriaportal.org/files/ccfiles/CCPART3V3.1R5.pdf"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-53A","url":"https://doi.org/10.6028/NIST.SP.800-53Ar4"},{"title":"SP 800-154","url":"https://csrc.nist.gov/publications/detail/sp/800-154/draft"},{"title":"SP 800-160-1","url":"https://doi.org/10.6028/NIST.SP.800-160v1"}],"objectives":[{"label":"SA-11a.","prose":"","items":[{"label":"SA-11a.[01]","prose":"the developer of the system, system component, or system service is required at all post-design stages of the system development life cycle to develop a plan for ongoing security assessments;"},{"label":"SA-11a.[02]","prose":"the developer of the system, system component, or system service is required at all post-design stages of the system development life cycle to implement a plan for ongoing security assessments;"},{"label":"SA-11a.[03]","prose":"the developer of the system, system component, or system service is required at all post-design stages of the system development life cycle to develop a plan for privacy assessments;"},{"label":"SA-11a.[04]","prose":"the developer of the system, system component, or system service is required at all post-design stages of the system development life cycle to implement a plan for ongoing privacy assessments;"}]},{"label":"SA-11b.","prose":"the developer of the system, system component, or system service is required at all post-design stages of the system development life cycle to perform [Selection (one or more): unit; integration; system; regression] testing/evaluation [Assignment: organization-defined frequency to conduct] at [Assignment: organization-defined depth and coverage];"},{"label":"SA-11c.","prose":"","items":[{"label":"SA-11c.[01]","prose":"the developer of the system, system component, or system service is required at all post-design stages of the system development life cycle to produce evidence of the execution of the assessment plan;"},{"label":"SA-11c.[02]","prose":"the developer of the system, system component, or system service is required at all post-design stages of the system development life cycle to produce the results of the testing and evaluation;"}]},{"label":"SA-11d.","prose":"the developer of the system, system component, or system service is required at all post-design stages of the system development life cycle to implement a verifiable flaw remediation process;"},{"label":"SA-11e.","prose":"the developer of the system, system component, or system service is required at all post-design stages of the system development life cycle to correct flaws identified during testing and evaluation."}],"methods":[{"method":"Examine","objects":["System and services acquisition policy","system and services acquisition procedures","procedures addressing system developer security and privacy testing","procedures addressing flaw remediation","solicitation documentation","acquisition documentation","service level agreements","acquisition contracts for the system, system component, or system service"]},{"method":"Interview","objects":["Organizational personnel with system and service acquisition responsibilities","organizational personnel with information security and privacy responsibilities","organizational personnel with developer security and privacy testing responsibilities","system developers"]},{"method":"Test","objects":["Organizational processes for monitoring developer security testing and evaluation","mechanisms supporting and/or implementing the monitoring of developer security and privacy testing and evaluation"]}]},"SA-15":{"statement":[{"label":"a.","prose":"Require the developer of the system, system component, or system service to follow a documented development process that:","items":[{"label":"1.","prose":"Explicitly addresses security and privacy requirements;"},{"label":"2.","prose":"Identifies the standards and tools used in the development process;"},{"label":"3.","prose":"Documents the specific tool options and tool configurations used in the development process; and"},{"label":"4.","prose":"Documents, manages, and ensures the integrity of changes to the process and/or tools used in development; and"}]},{"label":"b.","prose":"Review the development process, standards, tools, tool options, and tool configurations [Assignment: organization-defined frequency] to determine if the process, standards, tools, tool options and tool configurations selected and employed can satisfy the following security and privacy requirements: [Assignment: organization-defined security and privacy requirements]."}],"discussion":["Development tools include programming languages and computer-aided design systems. Reviews of development processes include the use of maturity models to determine the potential effectiveness of such processes. Maintaining the integrity of changes to tools and processes facilitates effective supply chain risk assessment and mitigation. Such integrity requires configuration control throughout the system development life cycle to track authorized changes and prevent unauthorized changes."],"params":[{"id":"SA-15_PRM_2","kind":"Assignment","value":"[Assignment: organization-defined security and privacy requirements]"},{"id":"SA-15_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to review the development process, standards, tools, tool options, and tool configurations is defined"},{"id":"SA-15_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined security requirements]","guideline":"security requirements to be satisfied by the process, standards, tools, tool options, and tool configurations are defined"},{"id":"SA-15_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined privacy requirements]","guideline":"privacy requirements to be satisfied by the process, standards, tools, tool options, and tool configurations are defined"}],"related":["MA-6","SA-3","SA-4","SA-8","SA-10","SA-11","SR-3","SR-4","SR-5","SR-6","SR-9"],"references":[{"title":"SP 800-160-1","url":"https://doi.org/10.6028/NIST.SP.800-160v1"},{"title":"IR 8179","url":"https://doi.org/10.6028/NIST.IR.8179"}],"objectives":[{"label":"SA-15a.","prose":"","items":[{"label":"SA-15a.01","prose":"","items":[{"label":"SA-15a.01[01]","prose":"the developer of the system, system component, or system service is required to follow a documented development process that explicitly addresses security requirements;"},{"label":"SA-15a.01[02]","prose":"the developer of the system, system component, or system service is required to follow a documented development process that explicitly addresses privacy requirements;"}]},{"label":"SA-15a.02","prose":"","items":[{"label":"SA-15a.02[01]","prose":"the developer of the system, system component, or system service is required to follow a documented development process that identifies the standards used in the development process;"},{"label":"SA-15a.02[02]","prose":"the developer of the system, system component, or system service is required to follow a documented development process that identifies the tools used in the development process;"}]},{"label":"SA-15a.03","prose":"","items":[{"label":"SA-15a.03[01]","prose":"the developer of the system, system component, or system service is required to follow a documented development process that documents the specific tool used in the development process;"},{"label":"SA-15a.03[02]","prose":"the developer of the system, system component, or system service is required to follow a documented development process that documents the specific tool configurations used in the development process;"}]},{"label":"SA-15a.04","prose":"the developer of the system, system component, or system service is required to follow a documented development process that documents, manages, and ensures the integrity of changes to the process and/or tools used in development;"}]},{"label":"SA-15b.","prose":"","items":[{"label":"SA-15b.[01]","prose":"the developer of the system, system component, or system service is required to follow a documented development process in which the development process, standards, tools, tool options, and tool configurations are reviewed [Assignment: organization-defined frequency] to determine that the process, standards, tools, tool options, and tool configurations selected and employed satisfy [Assignment: organization-defined security requirements];"},{"label":"SA-15b.[02]","prose":"the developer of the system, system component, or system service is required to follow a documented development process in which the development process, standards, tools, tool options, and tool configurations are reviewed [Assignment: organization-defined frequency] to determine that the process, standards, tools, tool options, and tool configurations selected and employed satisfy [Assignment: organization-defined privacy requirements]."}]}],"methods":[{"method":"Examine","objects":["System and services acquisition policy","system and services acquisition procedures","procedures addressing development process, standards, and tools","procedures addressing the integration of security and privacy requirements during the development process","solicitation documentation","acquisition documentation","critical component inventory documentation","service level agreements"]},{"method":"Interview","objects":["Organizational personnel with system and service acquisition responsibilities","organizational personnel with information security and privacy responsibilities","system developer"]}]},"SA-15(3)":{"statement":[{"prose":"Require the developer of the system, system component, or system service to perform a criticality analysis:"},{"label":"(a)","prose":"At the following decision points in the system development life cycle: [Assignment: organization-defined decision points]; and"},{"label":"(b)","prose":"At the following level of rigor: [Assignment: organization-defined breadth and depth of criticality analysis]."}],"discussion":["Criticality analysis performed by the developer provides input to the criticality analysis performed by organizations. Developer input is essential to organizational criticality analysis because organizations may not have access to detailed design documentation for system components that are developed as commercial off-the-shelf products. Such design documentation includes functional specifications, high-level designs, low-level designs, source code, and hardware schematics. Criticality analysis is important for organizational systems that are designated as high value assets. High value assets can be moderate- or high-impact systems due to heightened adversarial interest or potential adverse effects on the federal enterprise. Developer input is especially important when organizations conduct supply chain criticality analyses."],"params":[{"id":"SA-15.3_PRM_2","kind":"Assignment","value":"[Assignment: organization-defined breadth and depth of criticality analysis]"},{"id":"SA-15(03)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined decision points]","guideline":"decision points in the system development life cycle are defined"},{"id":"SA-15(03)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined breadth]","guideline":"the breadth of criticality analysis is defined"},{"id":"SA-15(03)_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined depth]","guideline":"the depth of criticality analysis is defined"}],"related":["RA-9"],"references":[],"objectives":[{"label":"SA-15(03)(a)","prose":"the developer of the system, system component, or system service is required to perform a criticality analysis at [Assignment: organization-defined decision points] in the system development life cycle;"},{"label":"SA-15(03)(b)","prose":"","items":[{"label":"SA-15(03)(b)[01]","prose":"the developer of the system, system component, or system service is required to perform a criticality analysis at the following rigor level: [Assignment: organization-defined breadth];"},{"label":"SA-15(03)(b)[02]","prose":"the developer of the system, system component, or system service is required to perform a criticality analysis at the following rigor level: [Assignment: organization-defined depth]."}]}],"methods":[{"method":"Examine","objects":["Supply chain risk management plan","system and services acquisition policy","procedures addressing development process, standards, and tools","procedures addressing criticality analysis requirements for the system, system component, or system service","solicitation documentation","acquisition documentation","service level agreements","acquisition contracts for the system, system component, or system service"]},{"method":"Interview","objects":["Organizational personnel with system and service acquisition responsibilities","organizational personnel with information security responsibilities","organizational personnel responsible for performing criticality analysis","system developer","organizational personnel with supply chain risk management responsibilities"]},{"method":"Test","objects":["Organizational processes for performing criticality analysis","mechanisms supporting and/or implementing criticality analysis"]}]},"SA-16":{"statement":[{"prose":"Require the developer of the system, system component, or system service to provide the following training on the correct use and operation of the implemented security and privacy functions, controls, and/or mechanisms: [Assignment: organization-defined training]."}],"discussion":["Developer-provided training applies to external and internal (in-house) developers. Training personnel is essential to ensuring the effectiveness of the controls implemented within organizational systems. Types of training include web-based and computer-based training, classroom-style training, and hands-on training (including micro-training). Organizations can also request training materials from developers to conduct in-house training or offer self-training to organizational personnel. Organizations determine the type of training necessary and may require different types of training for different security and privacy functions, controls, and mechanisms."],"params":[{"id":"SA-16_ODP","kind":"Assignment","value":"[Assignment: organization-defined training]","guideline":"training on the correct use and operation of the implemented security and privacy functions, controls, and/or mechanisms provided by the developer of the system, system component, or system service is defined"}],"related":["AT-2","AT-3","PE-3","SA-4","SA-5"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and services acquisition policy","system and services acquisition procedures","procedures addressing developer-provided training","solicitation documentation","acquisition documentation","service level agreements","acquisition contracts for the system, system component, or system service","organizational security and privacy training policy"]},{"method":"Interview","objects":["Organizational personnel with system and service acquisition responsibilities","organizational personnel with information security and privacy responsibilities","system developer","external or internal (in-house) developers with training responsibilities for the system, system component, or information system service"]}]},"SA-17":{"statement":[{"prose":"Require the developer of the system, system component, or system service to produce a design specification and security and privacy architecture that:"},{"label":"a.","prose":"Is consistent with the organization’s security and privacy architecture that is an integral part the organization’s enterprise architecture;"},{"label":"b.","prose":"Accurately and completely describes the required security and privacy functionality, and the allocation of controls among physical and logical components; and"},{"label":"c.","prose":"Expresses how individual security and privacy functions, mechanisms, and services work together to provide required security and privacy capabilities and a unified approach to protection."}],"discussion":["Developer security and privacy architecture and design are directed at external developers, although they could also be applied to internal (in-house) development. In contrast, [PL-8](#pl-8) is directed at internal developers to ensure that organizations develop a security and privacy architecture that is integrated with the enterprise architecture. The distinction between SA-17 and [PL-8](#pl-8) is especially important when organizations outsource the development of systems, system components, or system services and when there is a requirement to demonstrate consistency with the enterprise architecture and security and privacy architecture of the organization. [ISO 15408-2](#87087451-2af5-43d4-88c1-d66ad850f614), [ISO 15408-3](#4452efc0-e79e-47b8-aa30-b54f3ef61c2f), and [SP 800-160-1](#e3cc0520-a366-4fc9-abc2-5272db7e3564) provide information on security architecture and design, including formal policy models, security-relevant components, formal and informal correspondence, conceptually simple design, and structuring for least privilege and testing."],"params":[],"related":["PL-2","PL-8","PM-7","SA-3","SA-4","SA-8","SC-7"],"references":[{"title":"ISO 15408-2","url":"https://www.commoncriteriaportal.org/files/ccfiles/CCPART2V3.1R5.pdf"},{"title":"ISO 15408-3","url":"https://www.commoncriteriaportal.org/files/ccfiles/CCPART3V3.1R5.pdf"},{"title":"SP 800-160-1","url":"https://doi.org/10.6028/NIST.SP.800-160v1"}],"objectives":[{"label":"SA-17(a)","prose":"","items":[{"label":"SA-17(a)[01]","prose":"the developer of the system, system component, or system service is required to produce a design specification and security architecture that are consistent with the organization’s security architecture, which is an integral part the organization’s enterprise architecture;"},{"label":"SA-17(a)[02]","prose":"the developer of the system, system component, or system service is required to produce a design specification and privacy architecture that are consistent with the organization’s privacy architecture, which is an integral part the organization’s enterprise architecture;"}]},{"label":"SA-17(b)","prose":"","items":[{"label":"SA-17(b)[01]","prose":"the developer of the system, system component, or system service is required to produce a design specification and security architecture that accurately and completely describe the required security functionality and the allocation of controls among physical and logical components;"},{"label":"SA-17(b)[02]","prose":"the developer of the system, system component, or system service is required to produce a design specification and privacy architecture that accurately and completely describe the required privacy functionality and the allocation of controls among physical and logical components;"}]},{"label":"SA-17(c)","prose":"","items":[{"label":"SA-17(c)[01]","prose":"the developer of the system, system component, or system service is required to produce a design specification and security architecture that express how individual security functions, mechanisms, and services work together to provide required security capabilities and a unified approach to protection;"},{"label":"SA-17(c)[02]","prose":"the developer of the system, system component, or system service is required to produce a design specification and privacy architecture that express how individual privacy functions, mechanisms, and services work together to provide required privacy capabilities and a unified approach to protection."}]}],"methods":[{"method":"Examine","objects":["System and services acquisition policy","system and services acquisition procedures","enterprise architecture policy","enterprise architecture documentation","procedures addressing developer security and privacy architecture and design specifications for the system","solicitation documentation","acquisition documentation","service level agreements"]},{"method":"Interview","objects":["Organizational personnel with acquisition responsibilities","organizational personnel with information security and privacy responsibilities","system developer"]}]},"SA-21":{"statement":[{"prose":"Require that the developer of [Assignment: organization-defined system, systems component, or system service]:"},{"label":"a.","prose":"Has appropriate access authorizations as determined by assigned [Assignment: organization-defined official government duties]; and"},{"label":"b.","prose":"Satisfies the following additional personnel screening criteria: [Assignment: organization-defined additional personnel screening criteria]."}],"discussion":["Developer screening is directed at external developers. Internal developer screening is addressed by [PS-3](#ps-3). Because the system, system component, or system service may be used in critical activities essential to the national or economic security interests of the United States, organizations have a strong interest in ensuring that developers are trustworthy. The degree of trust required of developers may need to be consistent with that of the individuals who access the systems, system components, or system services once deployed. Authorization and personnel screening criteria include clearances, background checks, citizenship, and nationality. Developer trustworthiness may also include a review and analysis of company ownership and relationships that the company has with entities that may potentially affect the quality and reliability of the systems, components, or services being developed. Satisfying the required access authorizations and personnel screening criteria includes providing a list of all individuals who are authorized to perform development activities on the selected system, system component, or system service so that organizations can validate that the developer has satisfied the authorization and screening requirements."],"params":[{"id":"SA-21_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined system, systems component, or system service]","guideline":"the system, systems component, or system service that the developer has access to is/are defined"},{"id":"SA-21_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined official government duties]","guideline":"official government duties assigned to the developer are defined"},{"id":"SA-21_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined additional personnel screening criteria]","guideline":"additional personnel screening criteria for the developer are defined"}],"related":["PS-2","PS-3","PS-6","PS-7","SA-4","SR-6"],"references":[],"objectives":[{"label":"SA-21a.","prose":"the developer of [Assignment: organization-defined system, systems component, or system service] is required to have appropriate access authorizations as determined by assigned [Assignment: organization-defined official government duties];"},{"label":"SA-21b.","prose":"the developer of [Assignment: organization-defined system, systems component, or system service] is required to satisfy [Assignment: organization-defined additional personnel screening criteria]."}],"methods":[{"method":"Examine","objects":["System and services acquisition policy","personnel security policy and procedures","procedures addressing personnel screening","system design documentation","acquisition documentation","service level agreements","acquisition contracts for developer services","system configuration settings and associated documentation"]},{"method":"Interview","objects":["Organizational personnel with system and service acquisition responsibilities","organizational personnel with information security responsibilities","organizational personnel responsible for developer screening"]},{"method":"Test","objects":["Organizational processes for developer screening","mechanisms supporting developer screening"]}]},"SA-22":{"statement":[{"label":"a.","prose":"Replace system components when support for the components is no longer available from the developer, vendor, or manufacturer; or"},{"label":"b.","prose":"Provide the following options for alternative sources for continued support for unsupported components [Selection (one or more): in-house support; [Assignment: organization-defined support from external providers]]."}],"discussion":["Support for system components includes software patches, firmware updates, replacement parts, and maintenance contracts. An example of unsupported components includes when vendors no longer provide critical software patches or product updates, which can result in an opportunity for adversaries to exploit weaknesses in the installed components. Exceptions to replacing unsupported system components include systems that provide critical mission or business capabilities where newer technologies are not available or where the systems are so isolated that installing replacement components is not an option.","Alternative sources for support address the need to provide continued support for system components that are no longer supported by the original manufacturers, developers, or vendors when such components remain essential to organizational mission and business functions. If necessary, organizations can establish in-house support by developing customized patches for critical software components or, alternatively, obtain the services of external providers who provide ongoing support for the designated unsupported components through contractual relationships. Such contractual relationships can include open-source software value-added vendors. The increased risk of using unsupported system components can be mitigated, for example, by prohibiting the connection of such components to public or uncontrolled networks, or implementing other forms of isolation."],"params":[{"id":"SA-22_ODP[01]","kind":"Selection","value":"[Selection (one or more): in-house support; [Assignment: organization-defined support from external providers]]"},{"id":"SA-22_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined support from external providers]","guideline":"support from external providers is defined (if selected)"}],"related":["PL-2","SA-3"],"references":[],"objectives":[{"label":"SA-22a.","prose":"system components are replaced when support for the components is no longer available from the developer, vendor, or manufacturer;"},{"label":"SA-22b.","prose":"[Selection (one or more): in-house support; [Assignment: organization-defined support from external providers]] provide options for alternative sources for continued support for unsupported components."}],"methods":[{"method":"Examine","objects":["System and services acquisition policy","procedures addressing the replacement or continued use of unsupported system components","documented evidence of replacing unsupported system components","documented approvals (including justification) for the continued use of unsupported system components","system security plan","supply chain risk management plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system and service acquisition responsibilities","organizational personnel with information security responsibilities","organizational personnel with the responsibility for the system development life cycle","organizational personnel responsible for component replacement"]},{"method":"Test","objects":["Organizational processes for replacing unsupported system components","mechanisms supporting and/or implementing the replacement of unsupported system components"]}]},"SC-1":{"statement":[{"label":"a.","prose":"Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:","items":[{"label":"1.","prose":"[Selection (one or more): organization-level; mission/business-process-level; system-level] system and communications protection policy that:","items":[{"label":"(a)","prose":"Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and"},{"label":"(b)","prose":"Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and"}]},{"label":"2.","prose":"Procedures to facilitate the implementation of the system and communications protection policy and the associated system and communications protection controls;"}]},{"label":"b.","prose":"Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the system and communications protection policy and procedures; and"},{"label":"c.","prose":"Review and update the current system and communications protection:","items":[{"label":"1.","prose":"Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and"},{"label":"2.","prose":"Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]."}]}],"discussion":["System and communications protection policy and procedures address the controls in the SC family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of system and communications protection policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to system and communications protection policy and procedures include assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure."],"params":[{"id":"SC-1_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]"},{"id":"SC-01_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the system and communications protection policy is to be disseminated is/are defined"},{"id":"SC-01_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the system and communications protection procedures are to be disseminated is/are defined"},{"id":"SC-01_ODP[03]","kind":"Selection","value":"[Selection (one or more): organization-level; mission/business-process-level; system-level]"},{"id":"SC-01_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined official]","guideline":"an official to manage the system and communications protection policy and procedures is defined"},{"id":"SC-01_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current system and communications protection policy is reviewed and updated is defined"},{"id":"SC-01_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require the current system and communications protection policy to be reviewed and updated are defined"},{"id":"SC-01_ODP[07]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current system and communications protection procedures are reviewed and updated is defined"},{"id":"SC-01_ODP[08]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require the system and communications protection procedures to be reviewed and updated are defined"}],"related":["PM-9","PS-8","SA-8","SI-12"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-12","url":"https://doi.org/10.6028/NIST.SP.800-12r1"},{"title":"SP 800-100","url":"https://doi.org/10.6028/NIST.SP.800-100"}],"objectives":[{"label":"SC-01a.","prose":"","items":[{"label":"SC-01a.[01]","prose":"a system and communications protection policy is developed and documented;"},{"label":"SC-01a.[02]","prose":"the system and communications protection policy is disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"SC-01a.[03]","prose":"system and communications protection procedures to facilitate the implementation of the system and communications protection policy and associated system and communications protection controls are developed and documented;"},{"label":"SC-01a.[04]","prose":"the system and communications protection procedures are disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"SC-01a.01","prose":"","items":[{"label":"SC-01a.01(a)","prose":"","items":[{"label":"SC-01a.01(a)[01]","prose":"the [Selection (one or more): organization-level; mission/business-process-level; system-level] system and communications protection policy addresses purpose;"},{"label":"SC-01a.01(a)[02]","prose":"the [Selection (one or more): organization-level; mission/business-process-level; system-level] system and communications protection policy addresses scope;"},{"label":"SC-01a.01(a)[03]","prose":"the [Selection (one or more): organization-level; mission/business-process-level; system-level] system and communications protection policy addresses roles;"},{"label":"SC-01a.01(a)[04]","prose":"the [Selection (one or more): organization-level; mission/business-process-level; system-level] system and communications protection policy addresses responsibilities;"},{"label":"SC-01a.01(a)[05]","prose":"the [Selection (one or more): organization-level; mission/business-process-level; system-level] system and communications protection policy addresses management commitment;"},{"label":"SC-01a.01(a)[06]","prose":"the [Selection (one or more): organization-level; mission/business-process-level; system-level] system and communications protection policy addresses coordination among organizational entities;"},{"label":"SC-01a.01(a)[07]","prose":"the [Selection (one or more): organization-level; mission/business-process-level; system-level] system and communications protection policy addresses compliance;"}]},{"label":"SC-01a.01(b)","prose":"the [Selection (one or more): organization-level; mission/business-process-level; system-level] system and communications protection policy is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines;"}]}]},{"label":"SC-01b.","prose":"the [Assignment: organization-defined official] is designated to manage the development, documentation, and dissemination of the system and communications protection policy and procedures;"},{"label":"SC-01c.","prose":"","items":[{"label":"SC-01c.01","prose":"","items":[{"label":"SC-01c.01[01]","prose":"the current system and communications protection policy is reviewed and updated [Assignment: organization-defined frequency];"},{"label":"SC-01c.01[02]","prose":"the current system and communications protection policy is reviewed and updated following [Assignment: organization-defined events];"}]},{"label":"SC-01c.02","prose":"","items":[{"label":"SC-01c.02[01]","prose":"the current system and communications protection procedures are reviewed and updated [Assignment: organization-defined frequency];"},{"label":"SC-01c.02[02]","prose":"the current system and communications protection procedures are reviewed and updated following [Assignment: organization-defined events]."}]}]}],"methods":[{"method":"Examine","objects":["System and communications protection policy","system and communications protection procedures","system security plan","privacy plan","risk management strategy documentation","audit findings","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system and communications protection responsibilities","organizational personnel with information security and privacy responsibilities"]}]},"SC-2":{"statement":[{"prose":"Separate user functionality, including user interface services, from system management functionality."}],"discussion":["System management functionality includes functions that are necessary to administer databases, network components, workstations, or servers. These functions typically require privileged user access. The separation of user functions from system management functions is physical or logical. Organizations may separate system management functions from user functions by using different computers, instances of operating systems, central processing units, or network addresses; by employing virtualization techniques; or some combination of these or other methods. Separation of system management functions from user functions includes web administrative interfaces that employ separate authentication methods for users of any other system resources. Separation of system and user functions may include isolating administrative interfaces on different domains and with additional access controls. The separation of system and user functionality can be achieved by applying the systems security engineering design principles in [SA-8](#sa-8), including [SA-8(1)](#sa-8.1), [SA-8(3)](#sa-8.3), [SA-8(4)](#sa-8.4), [SA-8(10)](#sa-8.10), [SA-8(12)](#sa-8.12), [SA-8(13)](#sa-8.13), [SA-8(14)](#sa-8.14), and [SA-8(18)](#sa-8.18)."],"params":[],"related":["AC-6","SA-4","SA-8","SC-3","SC-7","SC-22","SC-32","SC-39"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing application partitioning","system design documentation","system configuration settings and associated documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developer"]},{"method":"Test","objects":["Separation of user functionality from system management functionality"]}]},"SC-3":{"statement":[{"prose":"Isolate security functions from nonsecurity functions."}],"discussion":["Security functions are isolated from nonsecurity functions by means of an isolation boundary implemented within a system via partitions and domains. The isolation boundary controls access to and protects the integrity of the hardware, software, and firmware that perform system security functions. Systems implement code separation in many ways, such as through the provision of security kernels via processor rings or processor modes. For non-kernel code, security function isolation is often achieved through file system protections that protect the code on disk and address space protections that protect executing code. Systems can restrict access to security functions using access control mechanisms and by implementing least privilege capabilities. While the ideal is for all code within the defined security function isolation boundary to only contain security-relevant code, it is sometimes necessary to include nonsecurity functions as an exception. The isolation of security functions from nonsecurity functions can be achieved by applying the systems security engineering design principles in [SA-8](#sa-8), including [SA-8(1)](#sa-8.1), [SA-8(3)](#sa-8.3), [SA-8(4)](#sa-8.4), [SA-8(10)](#sa-8.10), [SA-8(12)](#sa-8.12), [SA-8(13)](#sa-8.13), [SA-8(14)](#sa-8.14), and [SA-8(18)](#sa-8.18)."],"params":[],"related":["AC-3","AC-6","AC-25","CM-2","CM-4","SA-4","SA-5","SA-8","SA-15","SA-17","SC-2","SC-7","SC-32","SC-39","SI-16"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing security function isolation","list of security functions to be isolated from non-security functions","system design documentation","system configuration settings and associated documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developer"]},{"method":"Test","objects":["Separation of security functions from non-security functions within the system"]}]},"SC-4":{"statement":[{"prose":"Prevent unauthorized and unintended information transfer via shared system resources."}],"discussion":["Preventing unauthorized and unintended information transfer via shared system resources stops information produced by the actions of prior users or roles (or the actions of processes acting on behalf of prior users or roles) from being available to current users or roles (or current processes acting on behalf of current users or roles) that obtain access to shared system resources after those resources have been released back to the system. Information in shared system resources also applies to encrypted representations of information. In other contexts, control of information in shared system resources is referred to as object reuse and residual information protection. Information in shared system resources does not address information remanence, which refers to the residual representation of data that has been nominally deleted; covert channels (including storage and timing channels), where shared system resources are manipulated to violate information flow restrictions; or components within systems for which there are only single users or roles."],"params":[],"related":["AC-3","AC-4","SA-8"],"references":[],"objectives":[{"label":"SC-04[01]","prose":"unauthorized information transfer via shared system resources is prevented;"},{"label":"SC-04[02]","prose":"unintended information transfer via shared system resources is prevented."}],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing information protection in shared system resources","system design documentation","system configuration settings and associated documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developer"]},{"method":"Test","objects":["Mechanisms preventing the unauthorized and unintended transfer of information via shared system resources"]}]},"SC-5":{"statement":[{"label":"a.","prose":"[Selection: protect against; limit] the effects of the following types of denial-of-service events: [Assignment: organization-defined types of denial-of-service events]; and"},{"label":"b.","prose":"Employ the following controls to achieve the denial-of-service objective: [Assignment: organization-defined controls by type of denial-of-service event]."}],"discussion":["Denial-of-service events may occur due to a variety of internal and external causes, such as an attack by an adversary or a lack of planning to support organizational needs with respect to capacity and bandwidth. Such attacks can occur across a wide range of network protocols (e.g., IPv4, IPv6). A variety of technologies are available to limit or eliminate the origination and effects of denial-of-service events. For example, boundary protection devices can filter certain types of packets to protect system components on internal networks from being directly affected by or the source of denial-of-service attacks. Employing increased network capacity and bandwidth combined with service redundancy also reduces the susceptibility to denial-of-service events."],"params":[{"id":"SC-05_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined types of denial-of-service events]","guideline":"types of denial-of-service events to be protected against or limited are defined"},{"id":"SC-05_ODP[02]","kind":"Selection","value":"[Selection: protect against; limit]"},{"id":"SC-05_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined controls by type of denial-of-service event]","guideline":"controls to achieve the denial-of-service objective by type of denial-of-service event are defined"}],"related":["CP-2","IR-4","SC-6","SC-7","SC-40"],"references":[{"title":"SP 800-189","url":"https://doi.org/10.6028/NIST.SP.800-189"}],"objectives":[{"label":"SC-05a.","prose":"the effects of [Assignment: organization-defined types of denial-of-service events] are [Selection: protect against; limit];"},{"label":"SC-05b.","prose":"[Assignment: organization-defined controls by type of denial-of-service event] are employed to achieve the denial-of-service protection objective."}],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing denial-of-service protection","system design documentation","list of denial-of-service attacks requiring employment of security safeguards to protect against or limit effects of such attacks","list of security safeguards protecting against or limiting the effects of denial-of-service attacks","system configuration settings and associated documentation","system audit records","system security plan"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","organizational personnel with incident response responsibilities","system developer"]},{"method":"Test","objects":["Mechanisms protecting against or limiting the effects of denial-of-service attacks"]}]},"SC-7":{"statement":[{"label":"a.","prose":"Monitor and control communications at the external managed interfaces to the system and at key internal managed interfaces within the system;"},{"label":"b.","prose":"Implement subnetworks for publicly accessible system components that are [Selection: physically; logically] separated from internal organizational networks; and"},{"label":"c.","prose":"Connect to external networks or systems only through managed interfaces consisting of boundary protection devices arranged in accordance with an organizational security and privacy architecture."}],"discussion":["Managed interfaces include gateways, routers, firewalls, guards, network-based malicious code analysis, virtualization systems, or encrypted tunnels implemented within a security architecture. Subnetworks that are physically or logically separated from internal networks are referred to as demilitarized zones or DMZs. Restricting or prohibiting interfaces within organizational systems includes restricting external web traffic to designated web servers within managed interfaces, prohibiting external traffic that appears to be spoofing internal addresses, and prohibiting internal traffic that appears to be spoofing external addresses. [SP 800-189](#f5edfe51-d1f2-422e-9b27-5d0e90b49c72) provides additional information on source address validation techniques to prevent ingress and egress of traffic with spoofed addresses. Commercial telecommunications services are provided by network components and consolidated management systems shared by customers. These services may also include third party-provided access lines and other service elements. Such services may represent sources of increased risk despite contract security provisions. Boundary protection may be implemented as a common control for all or part of an organizational network such that the boundary to be protected is greater than a system-specific boundary (i.e., an authorization boundary)."],"params":[{"id":"SC-07_ODP","kind":"Selection","value":"[Selection: physically; logically]"}],"related":["AC-4","AC-17","AC-18","AC-19","AC-20","AU-13","CA-3","CM-2","CM-4","CM-7","CM-10","CP-8","CP-10","IR-4","MA-4","PE-3","PL-8","PM-12","SA-8","SA-17","SC-5","SC-26","SC-32","SC-35","SC-43"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"FIPS 199","url":"https://doi.org/10.6028/NIST.FIPS.199"},{"title":"SP 800-37","url":"https://doi.org/10.6028/NIST.SP.800-37r2"},{"title":"SP 800-41","url":"https://doi.org/10.6028/NIST.SP.800-41r1"},{"title":"SP 800-77","url":"https://doi.org/10.6028/NIST.SP.800-77r1"},{"title":"SP 800-189","url":"https://doi.org/10.6028/NIST.SP.800-189"}],"objectives":[{"label":"SC-07a.","prose":"","items":[{"label":"SC-07a.[01]","prose":"communications at external managed interfaces to the system are monitored;"},{"label":"SC-07a.[02]","prose":"communications at external managed interfaces to the system are controlled;"},{"label":"SC-07a.[03]","prose":"communications at key internal managed interfaces within the system are monitored;"},{"label":"SC-07a.[04]","prose":"communications at key internal managed interfaces within the system are controlled;"}]},{"label":"SC-07b.","prose":"subnetworks for publicly accessible system components are [Selection: physically; logically] separated from internal organizational networks;"},{"label":"SC-07c.","prose":"external networks or systems are only connected to through managed interfaces consisting of boundary protection devices arranged in accordance with an organizational security and privacy architecture."}],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing boundary protection","list of key internal boundaries of the system","system design documentation","boundary protection hardware and software","system configuration settings and associated documentation","enterprise security architecture documentation","system audit records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developer","organizational personnel with boundary protection responsibilities"]},{"method":"Test","objects":["Mechanisms implementing boundary protection capabilities"]}]},"SC-7(3)":{"statement":[{"prose":"Limit the number of external network connections to the system."}],"discussion":["Limiting the number of external network connections facilitates monitoring of inbound and outbound communications traffic. The Trusted Internet Connection [DHS TIC](#4f42ee6e-86cc-403b-a51f-76c2b4f81b54) initiative is an example of a federal guideline that requires limits on the number of external network connections. Limiting the number of external network connections to the system is important during transition periods from older to newer technologies (e.g., transitioning from IPv4 to IPv6 network protocols). Such transitions may require implementing the older and newer technologies simultaneously during the transition period and thus increase the number of access points to the system."],"params":[],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing boundary protection","system design documentation","boundary protection hardware and software","system architecture and configuration documentation","system configuration settings and associated documentation","communications and network traffic monitoring logs","system audit records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","organizational personnel with boundary protection responsibilities"]},{"method":"Test","objects":["Mechanisms implementing boundary protection capabilities","mechanisms limiting the number of external network connections to the system"]}]},"SC-7(4)":{"statement":[{"label":"(a)","prose":"Implement a managed interface for each external telecommunication service;"},{"label":"(b)","prose":"Establish a traffic flow policy for each managed interface;"},{"label":"(c)","prose":"Protect the confidentiality and integrity of the information being transmitted across each interface;"},{"label":"(d)","prose":"Document each exception to the traffic flow policy with a supporting mission or business need and duration of that need;"},{"label":"(e)","prose":"Review exceptions to the traffic flow policy [Assignment: organization-defined frequency] and remove exceptions that are no longer supported by an explicit mission or business need;"},{"label":"(f)","prose":"Prevent unauthorized exchange of control plane traffic with external networks;"},{"label":"(g)","prose":"Publish information to enable remote networks to detect unauthorized control plane traffic from internal networks; and"},{"label":"(h)","prose":"Filter unauthorized control plane traffic from external networks."}],"discussion":["External telecommunications services can provide data and/or voice communications services. Examples of control plane traffic include Border Gateway Protocol (BGP) routing, Domain Name System (DNS), and management protocols. See [SP 800-189](#f5edfe51-d1f2-422e-9b27-5d0e90b49c72) for additional information on the use of the resource public key infrastructure (RPKI) to protect BGP routes and detect unauthorized BGP announcements."],"params":[{"id":"SC-07(04)_ODP","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to review exceptions to traffic flow policy is defined"}],"related":["AC-3","SC-8","SC-20","SC-21","SC-22"],"references":[],"objectives":[{"label":"SC-07(04)(a)","prose":"a managed interface is implemented for each external telecommunication service;"},{"label":"SC-07(04)(b)","prose":"a traffic flow policy is established for each managed interface;"},{"label":"SC-07(04)(c)","prose":"","items":[{"label":"SC-07(04)(c)[01]","prose":"the confidentiality of the information being transmitted across each interface is protected;"},{"label":"SC-07(04)(c)[02]","prose":"the integrity of the information being transmitted across each interface is protected;"}]},{"label":"SC-07(04)(d)","prose":"each exception to the traffic flow policy is documented with a supporting mission or business need and duration of that need;"},{"label":"SC-07(04)(e)","prose":"","items":[{"label":"SC-07(04)(e)[01]","prose":"exceptions to the traffic flow policy are reviewed [Assignment: organization-defined frequency];"},{"label":"SC-07(04)(e)[02]","prose":"exceptions to the traffic flow policy that are no longer supported by an explicit mission or business need are removed;"}]},{"label":"SC-07(04)(f)","prose":"unauthorized exchanges of control plan traffic with external networks are prevented;"},{"label":"SC-07(04)(g)","prose":"information is published to enable remote networks to detect unauthorized control plane traffic from internal networks;"},{"label":"SC-07(04)(h)","prose":"unauthorized control plane traffic is filtered from external networks."}],"methods":[{"method":"Examine","objects":["System and communications protection policy","traffic flow policy","information flow control policy","procedures addressing boundary protection","system security architecture","system design documentation","boundary protection hardware and software","system architecture and configuration documentation"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","organizational personnel with boundary protection responsibilities"]},{"method":"Test","objects":["Organizational processes for documenting and reviewing exceptions to the traffic flow policy","organizational processes for removing exceptions to the traffic flow policy","mechanisms implementing boundary protection capabilities","managed interfaces implementing traffic flow policy"]}]},"SC-7(5)":{"statement":[{"prose":"Deny network communications traffic by default and allow network communications traffic by exception [Selection (one or more): at managed interfaces; for [Assignment: organization-defined systems]]."}],"discussion":["Denying by default and allowing by exception applies to inbound and outbound network communications traffic. A deny-all, permit-by-exception network communications traffic policy ensures that only those system connections that are essential and approved are allowed. Deny by default, allow by exception also applies to a system that is connected to an external system."],"params":[{"id":"SC-07(05)_ODP[01]","kind":"Selection","value":"[Selection (one or more): at managed interfaces; for [Assignment: organization-defined systems]]"},{"id":"SC-07(05)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined systems]","guideline":"systems for which network communications traffic is denied by default and network communications traffic is allowed by exception are defined (if selected)."}],"related":[],"references":[],"objectives":[{"label":"SC-07(05)[01]","prose":"network communications traffic is denied by default [Selection (one or more): at managed interfaces; for [Assignment: organization-defined systems]];"},{"label":"SC-07(05)[02]","prose":"network communications traffic is allowed by exception [Selection (one or more): at managed interfaces; for [Assignment: organization-defined systems]]."}],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing boundary protection","system design documentation","system configuration settings and associated documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developer","organizational personnel with boundary protection responsibilities"]},{"method":"Test","objects":["Mechanisms implementing traffic management at managed interfaces"]}]},"SC-7(7)":{"statement":[{"prose":"Prevent split tunneling for remote devices connecting to organizational systems unless the split tunnel is securely provisioned using [Assignment: organization-defined safeguards]."}],"discussion":["Split tunneling is the process of allowing a remote user or device to establish a non-remote connection with a system and simultaneously communicate via some other connection to a resource in an external network. This method of network access enables a user to access remote devices and simultaneously, access uncontrolled networks. Split tunneling might be desirable by remote users to communicate with local system resources, such as printers or file servers. However, split tunneling can facilitate unauthorized external connections, making the system vulnerable to attack and to exfiltration of organizational information. Split tunneling can be prevented by disabling configuration settings that allow such capability in remote devices and by preventing those configuration settings from being configurable by users. Prevention can also be achieved by the detection of split tunneling (or of configuration settings that allow split tunneling) in the remote device, and by prohibiting the connection if the remote device is using split tunneling. A virtual private network (VPN) can be used to securely provision a split tunnel. A securely provisioned VPN includes locking connectivity to exclusive, managed, and named environments, or to a specific set of pre-approved addresses, without user control."],"params":[{"id":"SC-07(07)_ODP","kind":"Assignment","value":"[Assignment: organization-defined safeguards]","guideline":"safeguards to securely provision split tunneling are defined"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing boundary protection","system design documentation","system hardware and software","system architecture","system configuration settings and associated documentation","system audit records","system security plan"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developer","organizational personnel with boundary protection responsibilities"]},{"method":"Test","objects":["Mechanisms implementing boundary protection capabilities","mechanisms supporting/restricting non-remote connections"]}]},"SC-7(8)":{"statement":[{"prose":"Route [Assignment: organization-defined internal communications traffic] to [Assignment: organization-defined external networks] through authenticated proxy servers at managed interfaces."}],"discussion":["External networks are networks outside of organizational control. A proxy server is a server (i.e., system or application) that acts as an intermediary for clients requesting system resources from non-organizational or other organizational servers. System resources that may be requested include files, connections, web pages, or services. Client requests established through a connection to a proxy server are assessed to manage complexity and provide additional protection by limiting direct connectivity. Web content filtering devices are one of the most common proxy servers that provide access to the Internet. Proxy servers can support the logging of Transmission Control Protocol sessions and the blocking of specific Uniform Resource Locators, Internet Protocol addresses, and domain names. Web proxies can be configured with organization-defined lists of authorized and unauthorized websites. Note that proxy servers may inhibit the use of virtual private networks (VPNs) and create the potential for \"man-in-the-middle\" attacks (depending on the implementation)."],"params":[{"id":"SC-07(08)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined internal communications traffic]","guideline":"internal communications traffic to be routed to external networks is defined"},{"id":"SC-07(08)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined external networks]","guideline":"external networks to which internal communications traffic is to be routed are defined"}],"related":["AC-3"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing boundary protection","system design documentation","system hardware and software","system architecture","system configuration settings and associated documentation","system audit records","system security plan"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developer","organizational personnel with boundary protection responsibilities"]},{"method":"Test","objects":["Mechanisms implementing traffic management through authenticated proxy servers at managed interfaces"]}]},"SC-7(18)":{"statement":[{"prose":"Prevent systems from entering unsecure states in the event of an operational failure of a boundary protection device."}],"discussion":["Fail secure is a condition achieved by employing mechanisms to ensure that in the event of operational failures of boundary protection devices at managed interfaces, systems do not enter into unsecure states where intended security properties no longer hold. Managed interfaces include routers, firewalls, and application gateways that reside on protected subnetworks (commonly referred to as demilitarized zones). Failures of boundary protection devices cannot lead to or cause information external to the devices to enter the devices nor can failures permit unauthorized information releases."],"params":[],"related":["CP-2","CP-12","SC-24"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing boundary protection","system design documentation","system architecture","system configuration settings and associated documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developer","organizational personnel with boundary protection responsibilities"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing secure failure"]}]},"SC-7(21)":{"statement":[{"prose":"Employ boundary protection mechanisms to isolate [Assignment: organization-defined system components] supporting [Assignment: organization-defined missions and/or business functions]."}],"discussion":["Organizations can isolate system components that perform different mission or business functions. Such isolation limits unauthorized information flows among system components and provides the opportunity to deploy greater levels of protection for selected system components. Isolating system components with boundary protection mechanisms provides the capability for increased protection of individual system components and to more effectively control information flows between those components. Isolating system components provides enhanced protection that limits the potential harm from hostile cyber-attacks and errors. The degree of isolation varies depending upon the mechanisms chosen. Boundary protection mechanisms include routers, gateways, and firewalls that separate system components into physically separate networks or subnetworks; cross-domain devices that separate subnetworks; virtualization techniques; and the encryption of information flows among system components using distinct encryption keys."],"params":[{"id":"SC-07(21)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined system components]","guideline":"system components to be isolated by boundary protection mechanisms are defined"},{"id":"SC-07(21)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined missions and/or business functions]","guideline":"missions and/or business functions to be supported by system components isolated by boundary protection mechanisms are defined"}],"related":["CA-9"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing boundary protection","system design documentation","system hardware and software","enterprise architecture documentation","system architecture","system configuration settings and associated documentation","system audit records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","organizational personnel with boundary protection responsibilities"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing the capability to separate system components supporting organizational missions and/or business functions"]}]},"SC-8":{"statement":[{"prose":"Protect the [Selection (one or more): confidentiality; integrity] of transmitted information."}],"discussion":["Protecting the confidentiality and integrity of transmitted information applies to internal and external networks as well as any system components that can transmit information, including servers, notebook computers, desktop computers, mobile devices, printers, copiers, scanners, facsimile machines, and radios. Unprotected communication paths are exposed to the possibility of interception and modification. Protecting the confidentiality and integrity of information can be accomplished by physical or logical means. Physical protection can be achieved by using protected distribution systems. A protected distribution system is a wireline or fiber-optics telecommunications system that includes terminals and adequate electromagnetic, acoustical, electrical, and physical controls to permit its use for the unencrypted transmission of classified information. Logical protection can be achieved by employing encryption techniques.","Organizations that rely on commercial providers who offer transmission services as commodity services rather than as fully dedicated services may find it difficult to obtain the necessary assurances regarding the implementation of needed controls for transmission confidentiality and integrity. In such situations, organizations determine what types of confidentiality or integrity services are available in standard, commercial telecommunications service packages. If it is not feasible to obtain the necessary controls and assurances of control effectiveness through appropriate contracting vehicles, organizations can implement appropriate compensating controls."],"params":[{"id":"SC-08_ODP","kind":"Selection","value":"[Selection (one or more): confidentiality; integrity]"}],"related":["AC-17","AC-18","AU-10","IA-3","IA-8","IA-9","MA-4","PE-4","SA-4","SA-8","SC-7","SC-16","SC-20","SC-23","SC-28"],"references":[{"title":"FIPS 140-3","url":"https://doi.org/10.6028/NIST.FIPS.140-3"},{"title":"FIPS 197","url":"https://doi.org/10.6028/NIST.FIPS.197"},{"title":"SP 800-52","url":"https://doi.org/10.6028/NIST.SP.800-52r2"},{"title":"SP 800-77","url":"https://doi.org/10.6028/NIST.SP.800-77r1"},{"title":"SP 800-81-2","url":"https://doi.org/10.6028/NIST.SP.800-81-2"},{"title":"SP 800-113","url":"https://doi.org/10.6028/NIST.SP.800-113"},{"title":"SP 800-177","url":"https://doi.org/10.6028/NIST.SP.800-177r1"},{"title":"IR 8023","url":"https://doi.org/10.6028/NIST.IR.8023"}],"objectives":[],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing transmission confidentiality and integrity","system design documentation","system configuration settings and associated documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developer"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing transmission confidentiality and/or integrity"]}]},"SC-8(1)":{"statement":[{"prose":"Implement cryptographic mechanisms to [Selection (one or more): prevent unauthorized disclosure of information; detect changes to information] during transmission."}],"discussion":["Encryption protects information from unauthorized disclosure and modification during transmission. Cryptographic mechanisms that protect the confidentiality and integrity of information during transmission include TLS and IPSec. Cryptographic mechanisms used to protect information integrity include cryptographic hash functions that have applications in digital signatures, checksums, and message authentication codes."],"params":[{"id":"SC-08(01)_ODP","kind":"Selection","value":"[Selection (one or more): prevent unauthorized disclosure of information; detect changes to information]"}],"related":["SC-12","SC-13"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing transmission confidentiality and integrity","system design documentation","system configuration settings and associated documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developer"]},{"method":"Test","objects":["Cryptographic mechanisms supporting and/or implementing transmission confidentiality and/or integrity","mechanisms supporting and/or implementing alternative physical safeguards","organizational processes for defining and implementing alternative physical safeguards"]}]},"SC-10":{"statement":[{"prose":"Terminate the network connection associated with a communications session at the end of the session or after [Assignment: organization-defined time period] of inactivity."}],"discussion":["Network disconnect applies to internal and external networks. Terminating network connections associated with specific communications sessions includes de-allocating TCP/IP address or port pairs at the operating system level and de-allocating the networking assignments at the application level if multiple application sessions are using a single operating system-level network connection. Periods of inactivity may be established by organizations and include time periods by type of network access or for specific network accesses."],"params":[{"id":"SC-10_ODP","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"a time period of inactivity after which the system terminates a network connection associated with a communication session is defined"}],"related":["AC-17","SC-23"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing network disconnect","system design documentation","security plan","system configuration settings and associated documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developer"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing a network disconnect capability"]}]},"SC-12":{"statement":[{"prose":"Establish and manage cryptographic keys when cryptography is employed within the system in accordance with the following key management requirements: [Assignment: organization-defined requirements]."}],"discussion":["Cryptographic key management and establishment can be performed using manual procedures or automated mechanisms with supporting manual procedures. Organizations define key management requirements in accordance with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines and specify appropriate options, parameters, and levels. Organizations manage trust stores to ensure that only approved trust anchors are part of such trust stores. This includes certificates with visibility external to organizational systems and certificates related to the internal operations of systems. [NIST CMVP](#1acdc775-aafb-4d11-9341-dc6a822e9d38) and [NIST CAVP](#84dc1b0c-acb7-4269-84c4-00dbabacd78c) provide additional information on validated cryptographic modules and algorithms that can be used in cryptographic key management and establishment."],"params":[{"id":"SC-12_ODP","kind":"Assignment","value":"[Assignment: organization-defined requirements]","guideline":"requirements for key generation, distribution, storage, access, and destruction are defined"}],"related":["AC-17","AU-9","AU-10","CM-3","IA-3","IA-7","IA-13","SA-4","SA-8","SA-9","SC-8","SC-11","SC-13","SC-17","SC-20","SC-37","SC-40","SI-3","SI-7"],"references":[{"title":"FIPS 140-3","url":"https://doi.org/10.6028/NIST.FIPS.140-3"},{"title":"SP 800-56A","url":"https://doi.org/10.6028/NIST.SP.800-56Ar3"},{"title":"SP 800-56B","url":"https://doi.org/10.6028/NIST.SP.800-56Br2"},{"title":"SP 800-56C","url":"https://doi.org/10.6028/NIST.SP.800-56Cr2"},{"title":"SP 800-57-1","url":"https://doi.org/10.6028/NIST.SP.800-57pt1r5"},{"title":"SP 800-57-2","url":"https://doi.org/10.6028/NIST.SP.800-57pt2r1"},{"title":"SP 800-57-3","url":"https://doi.org/10.6028/NIST.SP.800-57pt3r1"},{"title":"SP 800-63-3","url":"https://doi.org/10.6028/NIST.SP.800-63-3"},{"title":"IR 7956","url":"https://doi.org/10.6028/NIST.IR.7956"},{"title":"IR 7966","url":"https://doi.org/10.6028/NIST.IR.7966"}],"objectives":[{"label":"SC-12[01]","prose":"cryptographic keys are established when cryptography is employed within the system in accordance with [Assignment: organization-defined requirements];"},{"label":"SC-12[02]","prose":"cryptographic keys are managed when cryptography is employed within the system in accordance with [Assignment: organization-defined requirements]."}],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing cryptographic key establishment and management","system design documentation","cryptographic mechanisms","system configuration settings and associated documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","organizational personnel with responsibilities for cryptographic key establishment and/or management"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing cryptographic key establishment and management"]}]},"SC-12(1)":{"statement":[{"prose":"Maintain availability of information in the event of the loss of cryptographic keys by users."}],"discussion":["Escrowing of encryption keys is a common practice for ensuring availability in the event of key loss. A forgotten passphrase is an example of losing a cryptographic key."],"params":[],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing cryptographic key establishment, management, and recovery","system design documentation","system configuration settings and associated documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","organizational personnel with responsibilities for cryptographic key establishment or management"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing cryptographic key establishment and management"]}]},"SC-13":{"statement":[{"label":"a.","prose":"Determine the [Assignment: organization-defined cryptographic uses]; and"},{"label":"b.","prose":"Implement the following types of cryptography required for each specified cryptographic use: [Assignment: organization-defined types of cryptography]."}],"discussion":["Cryptography can be employed to support a variety of security solutions, including the protection of classified information and controlled unclassified information, the provision and implementation of digital signatures, and the enforcement of information separation when authorized individuals have the necessary clearances but lack the necessary formal access approvals. Cryptography can also be used to support random number and hash generation. Generally applicable cryptographic standards include FIPS-validated cryptography and NSA-approved cryptography. For example, organizations that need to protect classified information may specify the use of NSA-approved cryptography. Organizations that need to provision and implement digital signatures may specify the use of FIPS-validated cryptography. Cryptography is implemented in accordance with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines."],"params":[{"id":"SC-13_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined cryptographic uses]","guideline":"cryptographic uses are defined"},{"id":"SC-13_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined types of cryptography]","guideline":"types of cryptography for each specified cryptographic use are defined"}],"related":["AC-2","AC-3","AC-7","AC-17","AC-18","AC-19","AU-9","AU-10","CM-11","CP-9","IA-3","IA-5","IA-7","IA-13","MA-4","MP-2","MP-4","MP-5","SA-4","SA-8","SA-9","SC-8","SC-12","SC-20","SC-23","SC-28","SC-40","SI-3","SI-7"],"references":[{"title":"FIPS 140-3","url":"https://doi.org/10.6028/NIST.FIPS.140-3"}],"objectives":[{"label":"SC-13a.","prose":"[Assignment: organization-defined cryptographic uses] are identified;"},{"label":"SC-13b.","prose":"[Assignment: organization-defined types of cryptography] for each specified cryptographic use (defined in SC-13_ODP[01]) are implemented."}],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing cryptographic protection","system design documentation","system configuration settings and associated documentation","cryptographic module validation certificates","list of FIPS-validated cryptographic modules","system audit records","system security plan"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developer","organizational personnel with responsibilities for cryptographic protection"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing cryptographic protection"]}]},"SC-15":{"statement":[{"label":"a.","prose":"Prohibit remote activation of collaborative computing devices and applications with the following exceptions: [Assignment: organization-defined exceptions where remote activation is to be allowed]; and"},{"label":"b.","prose":"Provide an explicit indication of use to users physically present at the devices."}],"discussion":["Collaborative computing devices and applications include remote meeting devices and applications, networked white boards, cameras, and microphones. The explicit indication of use includes signals to users when collaborative computing devices and applications are activated."],"params":[{"id":"SC-15_ODP","kind":"Assignment","value":"[Assignment: organization-defined exceptions where remote activation is to be allowed]","guideline":"exceptions where remote activation is to be allowed are defined"}],"related":["AC-21","SC-42"],"references":[],"objectives":[{"label":"SC-15a.","prose":"remote activation of collaborative computing devices and applications is prohibited except [Assignment: organization-defined exceptions where remote activation is to be allowed];"},{"label":"SC-15b.","prose":"an explicit indication of use is provided to users physically present at the devices."}],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing collaborative computing","access control policy and procedures","system design documentation","system configuration settings and associated documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developer","organizational personnel with responsibilities for managing collaborative computing devices"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing the management of remote activation of collaborative computing devices","mechanisms providing an indication of use of collaborative computing devices"]}]},"SC-17":{"statement":[{"label":"a.","prose":"Issue public key certificates under an [Assignment: organization-defined certificate policy] or obtain public key certificates from an approved service provider; and"},{"label":"b.","prose":"Include only approved trust anchors in trust stores or certificate stores managed by the organization."}],"discussion":["Public key infrastructure (PKI) certificates are certificates with visibility external to organizational systems and certificates related to the internal operations of systems, such as application-specific time services. In cryptographic systems with a hierarchical structure, a trust anchor is an authoritative source (i.e., a certificate authority) for which trust is assumed and not derived. A root certificate for a PKI system is an example of a trust anchor. A trust store or certificate store maintains a list of trusted root certificates."],"params":[{"id":"SC-17_ODP","kind":"Assignment","value":"[Assignment: organization-defined certificate policy]","guideline":"a certificate policy for issuing public key certificates is defined"}],"related":["AU-10","IA-5","SC-12"],"references":[{"title":"SP 800-32","url":"https://doi.org/10.6028/NIST.SP.800-32"},{"title":"SP 800-57-1","url":"https://doi.org/10.6028/NIST.SP.800-57pt1r5"},{"title":"SP 800-57-2","url":"https://doi.org/10.6028/NIST.SP.800-57pt2r1"},{"title":"SP 800-57-3","url":"https://doi.org/10.6028/NIST.SP.800-57pt3r1"},{"title":"SP 800-63-3","url":"https://doi.org/10.6028/NIST.SP.800-63-3"}],"objectives":[{"label":"SC-17a.","prose":"public key certificates are issued under [Assignment: organization-defined certificate policy], or public key certificates are obtained from an approved service provider;"},{"label":"SC-17b.","prose":"only approved trust anchors are included in trust stores or certificate stores managed by the organization."}],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing public key infrastructure certificates","public key certificate policy or policies","public key issuing process","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","organizational personnel with responsibilities for issuing public key certificates","service providers"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing the management of public key infrastructure certificates"]}]},"SC-18":{"statement":[{"label":"a.","prose":"Define acceptable and unacceptable mobile code and mobile code technologies; and"},{"label":"b.","prose":"Authorize, monitor, and control the use of mobile code within the system."}],"discussion":["Mobile code includes any program, application, or content that can be transmitted across a network (e.g., embedded in an email, document, or website) and executed on a remote system. Decisions regarding the use of mobile code within organizational systems are based on the potential for the code to cause damage to the systems if used maliciously. Mobile code technologies include Java applets, JavaScript, HTML5, WebGL, and VBScript. Usage restrictions and implementation guidelines apply to both the selection and use of mobile code installed on servers and mobile code downloaded and executed on individual workstations and devices, including notebook computers and smart phones. Mobile code policy and procedures address specific actions taken to prevent the development, acquisition, and introduction of unacceptable mobile code within organizational systems, including requiring mobile code to be digitally signed by a trusted source."],"params":[],"related":["AU-2","AU-12","CM-2","CM-6","SI-3"],"references":[{"title":"SP 800-28","url":"https://doi.org/10.6028/NIST.SP.800-28ver2"}],"objectives":[{"label":"SC-18a.","prose":"","items":[{"label":"SC-18a.[01]","prose":"acceptable mobile code is defined;"},{"label":"SC-18a.[02]","prose":"unacceptable mobile code is defined;"},{"label":"SC-18a.[03]","prose":"acceptable mobile code technologies are defined;"},{"label":"SC-18a.[04]","prose":"unacceptable mobile code technologies are defined;"}]},{"label":"SC-18b.","prose":"","items":[{"label":"SC-18b.[01]","prose":"the use of mobile code is authorized within the system;"},{"label":"SC-18b.[02]","prose":"the use of mobile code is monitored within the system;"},{"label":"SC-18b.[03]","prose":"the use of mobile code is controlled within the system."}]}],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing mobile code","mobile code implementation policy and procedures","list of acceptable mobile code and mobile code technologies","list of unacceptable mobile code and mobile technologies","authorization records","system monitoring records","system audit records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","organizational personnel with responsibilities for managing mobile code"]},{"method":"Test","objects":["Organizational process for authorizing, monitoring, and controlling mobile code","mechanisms supporting and/or implementing the management of mobile code","mechanisms supporting and/or implementing the monitoring of mobile code"]}]},"SC-20":{"statement":[{"label":"a.","prose":"Provide additional data origin authentication and integrity verification artifacts along with the authoritative name resolution data the system returns in response to external name/address resolution queries; and"},{"label":"b.","prose":"Provide the means to indicate the security status of child zones and (if the child supports secure resolution services) to enable verification of a chain of trust among parent and child domains, when operating as part of a distributed, hierarchical namespace."}],"discussion":["Providing authoritative source information enables external clients, including remote Internet clients, to obtain origin authentication and integrity verification assurances for the host/service name to network address resolution information obtained through the service. Systems that provide name and address resolution services include domain name system (DNS) servers. Additional artifacts include DNS Security Extensions (DNSSEC) digital signatures and cryptographic keys. Authoritative data includes DNS resource records. The means for indicating the security status of child zones include the use of delegation signer resource records in the DNS. Systems that use technologies other than the DNS to map between host and service names and network addresses provide other means to assure the authenticity and integrity of response data."],"params":[],"related":["AU-10","SC-8","SC-12","SC-13","SC-21","SC-22"],"references":[{"title":"FIPS 140-3","url":"https://doi.org/10.6028/NIST.FIPS.140-3"},{"title":"FIPS 186-4","url":"https://doi.org/10.6028/NIST.FIPS.186-4"},{"title":"SP 800-81-2","url":"https://doi.org/10.6028/NIST.SP.800-81-2"}],"objectives":[{"label":"SC-20a.","prose":"","items":[{"label":"SC-20a.[01]","prose":"additional data origin authentication is provided along with the authoritative name resolution data that the system returns in response to external name/address resolution queries;"},{"label":"SC-20a.[02]","prose":"integrity verification artifacts are provided along with the authoritative name resolution data that the system returns in response to external name/address resolution queries;"}]},{"label":"SC-20b.","prose":"","items":[{"label":"SC-20b.[01]","prose":"the means to indicate the security status of child zones (and if the child supports secure resolution services) is provided when operating as part of a distributed, hierarchical namespace;"},{"label":"SC-20b.[02]","prose":"the means to enable verification of a chain of trust among parent and child domains when operating as part of a distributed, hierarchical namespace is provided."}]}],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing secure name/address resolution services (authoritative source)","system design documentation","system configuration settings and associated documentation","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","organizational personnel with responsibilities for managing DNS"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing secure name/address resolution services"]}]},"SC-21":{"statement":[{"prose":"Request and perform data origin authentication and data integrity verification on the name/address resolution responses the system receives from authoritative sources."}],"discussion":["Each client of name resolution services either performs this validation on its own or has authenticated channels to trusted validation providers. Systems that provide name and address resolution services for local clients include recursive resolving or caching domain name system (DNS) servers. DNS client resolvers either perform validation of DNSSEC signatures, or clients use authenticated channels to recursive resolvers that perform such validations. Systems that use technologies other than the DNS to map between host and service names and network addresses provide some other means to enable clients to verify the authenticity and integrity of response data."],"params":[],"related":["SC-20","SC-22"],"references":[{"title":"SP 800-81-2","url":"https://doi.org/10.6028/NIST.SP.800-81-2"}],"objectives":[{"label":"SC-21[01]","prose":"data origin authentication is requested for the name/address resolution responses that the system receives from authoritative sources;"},{"label":"SC-21[02]","prose":"data origin authentication is performed on the name/address resolution responses that the system receives from authoritative sources;"},{"label":"SC-21[03]","prose":"data integrity verification is requested for the name/address resolution responses that the system receives from authoritative sources;"},{"label":"SC-21[04]","prose":"data integrity verification is performed on the name/address resolution responses that the system receives from authoritative sources."}],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing secure name/address resolution services (recursive or caching resolver)","system design documentation","system configuration settings and associated documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","organizational personnel with responsibilities for managing DNS"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing data origin authentication and data integrity verification for name/address resolution services"]}]},"SC-22":{"statement":[{"prose":"Ensure the systems that collectively provide name/address resolution service for an organization are fault-tolerant and implement internal and external role separation."}],"discussion":["Systems that provide name and address resolution services include domain name system (DNS) servers. To eliminate single points of failure in systems and enhance redundancy, organizations employ at least two authoritative domain name system servers—one configured as the primary server and the other configured as the secondary server. Additionally, organizations typically deploy the servers in two geographically separated network subnetworks (i.e., not located in the same physical facility). For role separation, DNS servers with internal roles only process name and address resolution requests from within organizations (i.e., from internal clients). DNS servers with external roles only process name and address resolution information requests from clients external to organizations (i.e., on external networks, including the Internet). Organizations specify clients that can access authoritative DNS servers in certain roles (e.g., by address ranges and explicit lists)."],"params":[],"related":["SC-2","SC-20","SC-21","SC-24"],"references":[{"title":"SP 800-81-2","url":"https://doi.org/10.6028/NIST.SP.800-81-2"}],"objectives":[{"label":"SC-22[01]","prose":"the systems that collectively provide name/address resolution services for an organization are fault-tolerant;"},{"label":"SC-22[02]","prose":"the systems that collectively provide name/address resolution services for an organization implement internal role separation;"},{"label":"SC-22[03]","prose":"the systems that collectively provide name/address resolution services for an organization implement external role separation."}],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing architecture and provisioning for name/address resolution services","access control policy and procedures","system design documentation","assessment results from independent testing organizations","system configuration settings and associated documentation","system audit records","system security plan"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","organizational personnel with responsibilities for managing DNS"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing name/address resolution services for fault tolerance and role separation"]}]},"SC-23":{"statement":[{"prose":"Protect the authenticity of communications sessions."}],"discussion":["Protecting session authenticity addresses communications protection at the session level, not at the packet level. Such protection establishes grounds for confidence at both ends of communications sessions in the ongoing identities of other parties and the validity of transmitted information. Authenticity protection includes protecting against \"man-in-the-middle\" attacks, session hijacking, and the insertion of false information into sessions."],"params":[],"related":["AU-10","SC-8","SC-10","SC-11"],"references":[{"title":"SP 800-52","url":"https://doi.org/10.6028/NIST.SP.800-52r2"},{"title":"SP 800-77","url":"https://doi.org/10.6028/NIST.SP.800-77r1"},{"title":"SP 800-95","url":"https://doi.org/10.6028/NIST.SP.800-95"},{"title":"SP 800-113","url":"https://doi.org/10.6028/NIST.SP.800-113"}],"objectives":[],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing session authenticity","system design documentation","system configuration settings and associated documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing session authenticity"]}]},"SC-24":{"statement":[{"prose":"Fail to a [Assignment: organization-defined known system state] for the following failures on the indicated components while preserving [Assignment: organization-defined system state information] in failure: [Assignment: organization-defined types of system failures on system components]."}],"discussion":["Failure in a known state addresses security concerns in accordance with the mission and business needs of organizations. Failure in a known state prevents the loss of confidentiality, integrity, or availability of information in the event of failures of organizational systems or system components. Failure in a known safe state helps to prevent systems from failing to a state that may cause injury to individuals or destruction to property. Preserving system state information facilitates system restart and return to the operational mode with less disruption of mission and business processes."],"params":[{"id":"SC-24_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined types of system failures on system components]","guideline":"types of system failures for which the system components fail to a known state are defined"},{"id":"SC-24_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined known system state]","guideline":"known system state to which system components fail in the event of a system failure is defined"},{"id":"SC-24_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined system state information]","guideline":"system state information to be preserved in the event of a system failure is defined"}],"related":["CP-2","CP-4","CP-10","CP-12","SA-8","SC-7","SC-22","SI-13"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing system failure to known state","system design documentation","system configuration settings and associated documentation","list of failures requiring system to fail in a known state","state information to be preserved in system failure","system audit records","system security plan"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developer"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing the fail in known state capability","mechanisms preserving system state information in the event of a system failure"]}]},"SC-28":{"statement":[{"prose":"Protect the [Selection (one or more): confidentiality; integrity] of the following information at rest: [Assignment: organization-defined information at rest]."}],"discussion":["Information at rest refers to the state of information when it is not in process or in transit and is located on system components. Such components include internal or external hard disk drives, storage area network devices, or databases. However, the focus of protecting information at rest is not on the type of storage device or frequency of access but rather on the state of the information. Information at rest addresses the confidentiality and integrity of information and covers user information and system information. System-related information that requires protection includes configurations or rule sets for firewalls, intrusion detection and prevention systems, filtering routers, and authentication information. Organizations may employ different mechanisms to achieve confidentiality and integrity protections, including the use of cryptographic mechanisms and file share scanning. Integrity protection can be achieved, for example, by implementing write-once-read-many (WORM) technologies. When adequate protection of information at rest cannot otherwise be achieved, organizations may employ other controls, including frequent scanning to identify malicious code at rest and secure offline storage in lieu of online storage."],"params":[{"id":"SC-28_ODP[01]","kind":"Selection","value":"[Selection (one or more): confidentiality; integrity]"},{"id":"SC-28_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined information at rest]","guideline":"information at rest requiring protection is defined"}],"related":["AC-3","AC-4","AC-6","AC-19","CA-7","CM-3","CM-5","CM-6","CP-9","MP-4","MP-5","PE-3","SC-8","SC-12","SC-13","SC-34","SI-3","SI-7","SI-16"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-56A","url":"https://doi.org/10.6028/NIST.SP.800-56Ar3"},{"title":"SP 800-56B","url":"https://doi.org/10.6028/NIST.SP.800-56Br2"},{"title":"SP 800-56C","url":"https://doi.org/10.6028/NIST.SP.800-56Cr2"},{"title":"SP 800-57-1","url":"https://doi.org/10.6028/NIST.SP.800-57pt1r5"},{"title":"SP 800-57-2","url":"https://doi.org/10.6028/NIST.SP.800-57pt2r1"},{"title":"SP 800-57-3","url":"https://doi.org/10.6028/NIST.SP.800-57pt3r1"},{"title":"SP 800-111","url":"https://doi.org/10.6028/NIST.SP.800-111"},{"title":"SP 800-124","url":"https://doi.org/10.6028/NIST.SP.800-124r1"}],"objectives":[],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing the protection of information at rest","system design documentation","system configuration settings and associated documentation","cryptographic mechanisms and associated configuration documentation","list of information at rest requiring confidentiality and integrity protections","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developer"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing confidentiality and integrity protections for information at rest"]}]},"SC-28(1)":{"statement":[{"prose":"Implement cryptographic mechanisms to prevent unauthorized disclosure and modification of the following information at rest on [Assignment: organization-defined system components or media]: [Assignment: organization-defined information]."}],"discussion":["The selection of cryptographic mechanisms is based on the need to protect the confidentiality and integrity of organizational information. The strength of mechanism is commensurate with the security category or classification of the information. Organizations have the flexibility to encrypt information on system components or media or encrypt data structures, including files, records, or fields."],"params":[{"id":"SC-28(01)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined information]","guideline":"information requiring cryptographic protection is defined"},{"id":"SC-28(01)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined system components or media]","guideline":"system components or media requiring cryptographic protection is/are defined"}],"related":["AC-19","SC-12","SC-13"],"references":[],"objectives":[{"label":"SC-28(01)[01]","prose":"cryptographic mechanisms are implemented to prevent unauthorized disclosure of [Assignment: organization-defined information] at rest on [Assignment: organization-defined system components or media];"},{"label":"SC-28(01)[02]","prose":"cryptographic mechanisms are implemented to prevent unauthorized modification of [Assignment: organization-defined information] at rest on [Assignment: organization-defined system components or media]."}],"methods":[{"method":"Examine","objects":["System and communications protection policy","procedures addressing the protection of information at rest","system design documentation","system configuration settings and associated documentation","cryptographic mechanisms and associated configuration documentation","system audit records","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developer"]},{"method":"Test","objects":["Cryptographic mechanisms implementing confidentiality and integrity protections for information at rest"]}]},"SC-39":{"statement":[{"prose":"Maintain a separate execution domain for each executing system process."}],"discussion":["Systems can maintain separate execution domains for each executing process by assigning each process a separate address space. Each system process has a distinct address space so that communication between processes is performed in a manner controlled through the security functions, and one process cannot modify the executing code of another process. Maintaining separate execution domains for executing processes can be achieved, for example, by implementing separate address spaces. Process isolation technologies, including sandboxing or virtualization, logically separate software and firmware from other software, firmware, and data. Process isolation helps limit the access of potentially untrusted software to other system resources. The capability to maintain separate execution domains is available in commercial operating systems that employ multi-state processor technologies."],"params":[],"related":["AC-3","AC-4","AC-6","AC-25","SA-8","SC-2","SC-3","SI-16"],"references":[{"title":"SP 800-160-1","url":"https://doi.org/10.6028/NIST.SP.800-160v1"}],"objectives":[],"methods":[{"method":"Examine","objects":["System design documentation","system architecture","independent verification and validation documentation","testing and evaluation documentation","other relevant documents or records"]},{"method":"Interview","objects":["System developers/integrators","system security architect"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing separate execution domains for each executing process"]}]},"SC-40":{"statement":[{"prose":"Protect external and internal [Assignment: organization-defined wireless links] from the following signal parameter attacks: [Assignment: organization-defined types of signal parameter attacks or references to sources for such attacks]."}],"discussion":["Wireless link protection applies to internal and external wireless communication links that may be visible to individuals who are not authorized system users. Adversaries can exploit the signal parameters of wireless links if such links are not adequately protected. There are many ways to exploit the signal parameters of wireless links to gain intelligence, deny service, or spoof system users. Protection of wireless links reduces the impact of attacks that are unique to wireless systems. If organizations rely on commercial service providers for transmission services as commodity items rather than as fully dedicated services, it may not be possible to implement wireless link protections to the extent necessary to meet organizational security requirements."],"params":[{"id":"SC-40_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined wireless links]"},{"id":"SC-40_PRM_2","kind":"Assignment","value":"[Assignment: organization-defined types of signal parameter attacks or references to sources for such attacks]"},{"id":"SC-40_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined wireless links]","guideline":"external wireless links to be protected from particular types of signal parameter attacks are defined"},{"id":"SC-40_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined types of signal parameter attacks or references to sources for such attacks]","guideline":"types of signal parameter attacks or references to sources for such attacks from which to protect external wireless links are defined"},{"id":"SC-40_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined wireless links]","guideline":"internal wireless links to be protected from particular types of signal parameter attacks are defined"},{"id":"SC-40_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined types of signal parameter attacks or references to sources for such attacks]","guideline":"types of signal parameter attacks or references to sources for such attacks from which to protect internal wireless links are defined"}],"related":["AC-18","SC-5"],"references":[],"objectives":[{"label":"SC-40[01]","prose":"external [Assignment: organization-defined wireless links] are protected from [Assignment: organization-defined types of signal parameter attacks or references to sources for such attacks]."},{"label":"SC-40[02]","prose":"internal [Assignment: organization-defined wireless links] are protected from [Assignment: organization-defined types of signal parameter attacks or references to sources for such attacks]."}],"methods":[{"method":"Examine","objects":["System and communications protection policy","access control policy and procedures","procedures addressing wireless link protection","system design documentation","wireless network diagrams","system configuration settings and associated documentation","system architecture","list of internal and external wireless links"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developer","organizational personnel installing, configuring, and/or maintaining the system","organizational personnel authorizing, installing, configuring, and/or maintaining internal and external wireless links"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing the protection of wireless links"]}]},"SI-1":{"statement":[{"label":"a.","prose":"Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:","items":[{"label":"1.","prose":"[Selection (one or more): organization-level; mission/business process-level; system-level] system and information integrity policy that:","items":[{"label":"(a)","prose":"Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and"},{"label":"(b)","prose":"Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and"}]},{"label":"2.","prose":"Procedures to facilitate the implementation of the system and information integrity policy and the associated system and information integrity controls;"}]},{"label":"b.","prose":"Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the system and information integrity policy and procedures; and"},{"label":"c.","prose":"Review and update the current system and information integrity:","items":[{"label":"1.","prose":"Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and"},{"label":"2.","prose":"Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]."}]}],"discussion":["System and information integrity policy and procedures address the controls in the SI family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of system and information integrity policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to system and information integrity policy and procedures include assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure."],"params":[{"id":"SI-1_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]"},{"id":"SI-01_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the system and information integrity policy is to be disseminated is/are defined"},{"id":"SI-01_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom the system and information integrity procedures are to be disseminated is/are defined"},{"id":"SI-01_ODP[03]","kind":"Selection","value":"[Selection (one or more): organization-level; mission/business process-level; system-level]"},{"id":"SI-01_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined official]","guideline":"an official to manage the system and information integrity policy and procedures is defined"},{"id":"SI-01_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current system and information integrity policy is reviewed and updated is defined"},{"id":"SI-01_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require the current system and information integrity policy to be reviewed and updated are defined"},{"id":"SI-01_ODP[07]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current system and information integrity procedures are reviewed and updated is defined"},{"id":"SI-01_ODP[08]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that would require the system and information integrity procedures to be reviewed and updated are defined"}],"related":["PM-9","PS-8","SA-8","SI-12"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"SP 800-12","url":"https://doi.org/10.6028/NIST.SP.800-12r1"},{"title":"SP 800-100","url":"https://doi.org/10.6028/NIST.SP.800-100"}],"objectives":[{"label":"SI-01a.","prose":"","items":[{"label":"SI-01a.[01]","prose":"a system and information integrity policy is developed and documented;"},{"label":"SI-01a.[02]","prose":"the system and information integrity policy is disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"SI-01a.[03]","prose":"system and information integrity procedures to facilitate the implementation of the system and information integrity policy and associated system and information integrity controls are developed and documented;"},{"label":"SI-01a.[04]","prose":"the system and information integrity procedures are disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"SI-01a.01","prose":"","items":[{"label":"SI-01a.01(a)","prose":"","items":[{"label":"SI-01a.01(a)[01]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] system and information integrity policy addresses purpose;"},{"label":"SI-01a.01(a)[02]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] system and information integrity policy addresses scope;"},{"label":"SI-01a.01(a)[03]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] system and information integrity policy addresses roles;"},{"label":"SI-01a.01(a)[04]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] system and information integrity policy addresses responsibilities;"},{"label":"SI-01a.01(a)[05]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] system and information integrity policy addresses management commitment;"},{"label":"SI-01a.01(a)[06]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] system and information integrity policy addresses coordination among organizational entities;"},{"label":"SI-01a.01(a)[07]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] system and information integrity policy addresses compliance;"}]},{"label":"SI-01a.01(b)","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] system and information integrity policy is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines;"}]}]},{"label":"SI-01b.","prose":"the [Assignment: organization-defined official] is designated to manage the development, documentation, and dissemination of the system and information integrity policy and procedures;"},{"label":"SI-01c.","prose":"","items":[{"label":"SI-01c.01","prose":"","items":[{"label":"SI-01c.01[01]","prose":"the current system and information integrity policy is reviewed and updated [Assignment: organization-defined frequency];"},{"label":"SI-01c.01[02]","prose":"the current system and information integrity policy is reviewed and updated following [Assignment: organization-defined events];"}]},{"label":"SI-01c.02","prose":"","items":[{"label":"SI-01c.02[01]","prose":"the current system and information integrity procedures are reviewed and updated [Assignment: organization-defined frequency];"},{"label":"SI-01c.02[02]","prose":"the current system and information integrity procedures are reviewed and updated following [Assignment: organization-defined events]."}]}]}],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with system and information integrity responsibilities","organizational personnel with information security and privacy responsibilities"]}]},"SI-2":{"statement":[{"label":"a.","prose":"Identify, report, and correct system flaws;"},{"label":"b.","prose":"Test software and firmware updates related to flaw remediation for effectiveness and potential side effects before installation;"},{"label":"c.","prose":"Install security-relevant software and firmware updates within [Assignment: organization-defined time period] of the release of the updates; and"},{"label":"d.","prose":"Incorporate flaw remediation into the organizational configuration management process."}],"discussion":["The need to remediate system flaws applies to all types of software and firmware. Organizations identify systems affected by software flaws, including potential vulnerabilities resulting from those flaws, and report this information to designated organizational personnel with information security and privacy responsibilities. Organizations consider establishing a controlled patching environment for mission-critical systems. Security-relevant updates include patches, service packs, and malicious code signatures. Organizations also address flaws discovered during assessments, continuous monitoring, incident response activities, and system error handling. By incorporating flaw remediation into configuration management processes, required remediation actions can be tracked and verified.","Organization-defined time periods for updating security-relevant software and firmware may vary based on a variety of risk factors, including the security category of the system, the criticality of the update (i.e., severity of the vulnerability related to the discovered flaw), the organizational risk tolerance, the mission supported by the system, or the threat environment. Some types of flaw remediation may require more testing than other types. Organizations determine the type of testing needed for the specific type of flaw remediation activity under consideration and the types of changes that are to be configuration-managed. Flaw remediation testing addresses both effectiveness of addressing security issues and for potential side effects on functionality, system and system component performance and operations. When implementing remediation activities, organizations consider the order and timing of updates to validate correct execution within the system environment, and to support system and component availability needs (i.e., implementing a staggered deployment strategy). In some situations, organizations may determine that the testing of software or firmware updates is not necessary or practical, such as when implementing simple malicious code signature updates. In testing decisions, organizations consider whether security-relevant software or firmware updates are obtained from authorized sources with appropriate digital signatures.","When implementing remediation activities, organizations consider the order and timing of updates to validate correct execution within the system environment, and to support system and component availability needs (i.e., implementing a staggered deployment strategy). Organizations verify that software and firmware updates come from authorized sources prior to downloading."],"params":[{"id":"SI-02_ODP","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"time period within which to install security-relevant software updates after the release of the updates is defined"}],"related":["CA-5","CM-3","CM-4","CM-5","CM-6","CM-8","MA-2","RA-5","SA-8","SA-10","SA-11","SI-3","SI-5","SI-7","SI-11"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"FIPS 140-3","url":"https://doi.org/10.6028/NIST.FIPS.140-3"},{"title":"FIPS 186-4","url":"https://doi.org/10.6028/NIST.FIPS.186-4"},{"title":"SP 800-39","url":"https://doi.org/10.6028/NIST.SP.800-39"},{"title":"SP 800-40","url":"https://doi.org/10.6028/NIST.SP.800-40r3"},{"title":"SP 800-128","url":"https://doi.org/10.6028/NIST.SP.800-128"},{"title":"IR 7788","url":"https://doi.org/10.6028/NIST.IR.7788"},{"title":"SP 800-81-2","url":"https://doi.org/10.6028/NIST.SP.800-81-2"}],"objectives":[{"label":"SI-02a.","prose":"","items":[{"label":"SI-02a.[01]","prose":"system flaws are identified;"},{"label":"SI-02a.[02]","prose":"system flaws are reported;"},{"label":"SI-02a.[03]","prose":"system flaws are corrected;"}]},{"label":"SI-02b.","prose":"","items":[{"label":"SI-02b.[01]","prose":"software updates related to flaw remediation are tested for effectiveness before installation;"},{"label":"SI-02b.[02]","prose":"software updates related to flaw remediation are tested for potential side effects before installation;"},{"label":"SI-02b.[03]","prose":"firmware updates related to flaw remediation are tested for effectiveness before installation;"},{"label":"SI-02b.[04]","prose":"firmware updates related to flaw remediation are tested for potential side effects before installation;"}]},{"label":"SI-02c.","prose":"","items":[{"label":"SI-02c.[01]","prose":"security-relevant software updates are installed within [Assignment: organization-defined time period] of the release of the updates;"},{"label":"SI-02c.[02]","prose":"security-relevant firmware updates are installed within [Assignment: organization-defined time period] of the release of the updates;"}]},{"label":"SI-02d.","prose":"flaw remediation is incorporated into the organizational configuration management process."}],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","procedures addressing flaw remediation","procedures addressing configuration management","list of flaws and vulnerabilities potentially affecting the system","list of recent security flaw remediation actions performed on the system (e.g., list of installed patches, service packs, hot fixes, and other software updates to correct system flaws)","test results from the installation of software and firmware updates to correct system flaws","installation/change control records for security-relevant software and firmware updates"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security and privacy responsibilities","organizational personnel responsible for installing, configuring, and/or maintaining the system","organizational personnel responsible for flaw remediation","organizational personnel with configuration management responsibilities"]},{"method":"Test","objects":["Organizational processes for identifying, reporting, and correcting system flaws","organizational process for installing software and firmware updates","mechanisms supporting and/or implementing the reporting and correcting of system flaws","mechanisms supporting and/or implementing testing software and firmware updates"]}]},"SI-2(2)":{"statement":[{"prose":"Determine if system components have applicable security-relevant software and firmware updates installed using [Assignment: organization-defined automated mechanisms] [Assignment: organization-defined frequency]."}],"discussion":["Automated mechanisms can track and determine the status of known flaws for system components."],"params":[{"id":"SI-02(02)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms to determine if applicable security-relevant software and firmware updates are installed on system components are defined"},{"id":"SI-02(02)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to determine if applicable security-relevant software and firmware updates are installed on system components is defined"}],"related":["CA-7","SI-4"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","procedures addressing flaw remediation","automated mechanisms supporting centralized management of flaw remediation","system design documentation","system configuration settings and associated documentation","system audit records","system security plan"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","organizational personnel installing, configuring, and/or maintaining the system","organizational personnel responsible for flaw remediation"]},{"method":"Test","objects":["Automated mechanisms used to determine the state of system components with regard to flaw remediation"]}]},"SI-3":{"statement":[{"label":"a.","prose":"Implement [Selection (one or more): signature-based; non-signature-based] malicious code protection mechanisms at system entry and exit points to detect and eradicate malicious code;"},{"label":"b.","prose":"Automatically update malicious code protection mechanisms as new releases are available in accordance with organizational configuration management policy and procedures;"},{"label":"c.","prose":"Configure malicious code protection mechanisms to:","items":[{"label":"1.","prose":"Perform periodic scans of the system [Assignment: organization-defined frequency] and real-time scans of files from external sources at [Selection (one or more): endpoint; network entry and exit points] as the files are downloaded, opened, or executed in accordance with organizational policy; and"},{"label":"2.","prose":"[Selection (one or more): block malicious code; quarantine malicious code; take [Assignment: organization-defined action]]; and send alert to [Assignment: organization-defined personnel or roles] in response to malicious code detection; and"}]},{"label":"d.","prose":"Address the receipt of false positives during malicious code detection and eradication and the resulting potential impact on the availability of the system."}],"discussion":["System entry and exit points include firewalls, remote access servers, workstations, electronic mail servers, web servers, proxy servers, notebook computers, and mobile devices. Malicious code includes viruses, worms, Trojan horses, and spyware. Malicious code can also be encoded in various formats contained within compressed or hidden files or hidden in files using techniques such as steganography. Malicious code can be inserted into systems in a variety of ways, including by electronic mail, the world-wide web, and portable storage devices. Malicious code insertions occur through the exploitation of system vulnerabilities. A variety of technologies and methods exist to limit or eliminate the effects of malicious code.","Malicious code protection mechanisms include both signature- and nonsignature-based technologies. Nonsignature-based detection mechanisms include artificial intelligence techniques that use heuristics to detect, analyze, and describe the characteristics or behavior of malicious code and to provide controls against such code for which signatures do not yet exist or for which existing signatures may not be effective. Malicious code for which active signatures do not yet exist or may be ineffective includes polymorphic malicious code (i.e., code that changes signatures when it replicates). Nonsignature-based mechanisms also include reputation-based technologies. In addition to the above technologies, pervasive configuration management, comprehensive software integrity controls, and anti-exploitation software may be effective in preventing the execution of unauthorized code. Malicious code may be present in commercial off-the-shelf software as well as custom-built software and could include logic bombs, backdoors, and other types of attacks that could affect organizational mission and business functions.","In situations where malicious code cannot be detected by detection methods or technologies, organizations rely on other types of controls, including secure coding practices, configuration management and control, trusted procurement processes, and monitoring practices to ensure that software does not perform functions other than the functions intended. Organizations may determine that, in response to the detection of malicious code, different actions may be warranted. For example, organizations can define actions in response to malicious code detection during periodic scans, the detection of malicious downloads, or the detection of maliciousness when attempting to open or execute files."],"params":[{"id":"SI-03_ODP[01]","kind":"Selection","value":"[Selection (one or more): signature-based; non-signature-based]"},{"id":"SI-03_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which malicious code protection mechanisms perform scans is defined"},{"id":"SI-03_ODP[03]","kind":"Selection","value":"[Selection (one or more): endpoint; network entry and exit points]"},{"id":"SI-03_ODP[04]","kind":"Selection","value":"[Selection (one or more): block malicious code; quarantine malicious code; take [Assignment: organization-defined action]]"},{"id":"SI-03_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined action]","guideline":"action to be taken in response to malicious code detection are defined (if selected)"},{"id":"SI-03_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to be alerted when malicious code is detected is/are defined"}],"related":["AC-4","AC-19","CM-3","CM-8","IR-4","MA-3","MA-4","PL-9","RA-5","SC-7","SC-23","SC-26","SC-28","SC-44","SI-2","SI-4","SI-7","SI-8","SI-15"],"references":[{"title":"SP 800-83","url":"https://doi.org/10.6028/NIST.SP.800-83r1"},{"title":"SP 800-125B","url":"https://doi.org/10.6028/NIST.SP.800-125B"},{"title":"SP 800-177","url":"https://doi.org/10.6028/NIST.SP.800-177r1"}],"objectives":[{"label":"SI-03a.","prose":"","items":[{"label":"SI-03a.[01]","prose":"[Selection (one or more): signature-based; non-signature-based] malicious code protection mechanisms are implemented at system entry and exit points to detect malicious code;"},{"label":"SI-03a.[02]","prose":"[Selection (one or more): signature-based; non-signature-based] malicious code protection mechanisms are implemented at system entry and exit points to eradicate malicious code;"}]},{"label":"SI-03b.","prose":"malicious code protection mechanisms are updated automatically as new releases are available in accordance with organizational configuration management policy and procedures;"},{"label":"SI-03c.","prose":"","items":[{"label":"SI-03c.01","prose":"","items":[{"label":"SI-03c.01[01]","prose":"malicious code protection mechanisms are configured to perform periodic scans of the system [Assignment: organization-defined frequency];"},{"label":"SI-03c.01[02]","prose":"malicious code protection mechanisms are configured to perform real-time scans of files from external sources at [Selection (one or more): endpoint; network entry and exit points] as the files are downloaded, opened, or executed in accordance with organizational policy;"}]},{"label":"SI-03c.02","prose":"","items":[{"label":"SI-03c.02[01]","prose":"malicious code protection mechanisms are configured to [Selection (one or more): block malicious code; quarantine malicious code; take [Assignment: organization-defined action]] in response to malicious code detection;"},{"label":"SI-03c.02[02]","prose":"malicious code protection mechanisms are configured to send alerts to [Assignment: organization-defined personnel or roles] in response to malicious code detection;"}]}]},{"label":"SI-03d.","prose":"the receipt of false positives during malicious code detection and eradication and the resulting potential impact on the availability of the system are addressed."}],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","configuration management policy and procedures","procedures addressing malicious code protection","malicious code protection mechanisms","records of malicious code protection updates","system design documentation","system configuration settings and associated documentation"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","organizational personnel installing, configuring, and/or maintaining the system","organizational personnel responsible for malicious code protection","organizational personnel with configuration management responsibilities"]},{"method":"Test","objects":["Organizational processes for employing, updating, and configuring malicious code protection mechanisms","organizational processes for addressing false positives and resulting potential impacts","mechanisms supporting and/or implementing, employing, updating, and configuring malicious code protection mechanisms","mechanisms supporting and/or implementing malicious code scanning and subsequent actions"]}]},"SI-4":{"statement":[{"label":"a.","prose":"Monitor the system to detect:","items":[{"label":"1.","prose":"Attacks and indicators of potential attacks in accordance with the following monitoring objectives: [Assignment: organization-defined monitoring objectives]; and"},{"label":"2.","prose":"Unauthorized local, network, and remote connections;"}]},{"label":"b.","prose":"Identify unauthorized use of the system through the following techniques and methods: [Assignment: organization-defined techniques and methods];"},{"label":"c.","prose":"Invoke internal monitoring capabilities or deploy monitoring devices:","items":[{"label":"1.","prose":"Strategically within the system to collect organization-determined essential information; and"},{"label":"2.","prose":"At ad hoc locations within the system to track specific types of transactions of interest to the organization;"}]},{"label":"d.","prose":"Analyze detected events and anomalies;"},{"label":"e.","prose":"Adjust the level of system monitoring activity when there is a change in risk to organizational operations and assets, individuals, other organizations, or the Nation;"},{"label":"f.","prose":"Obtain legal opinion regarding system monitoring activities; and"},{"label":"g.","prose":"Provide [Assignment: organization-defined system monitoring information] to [Assignment: organization-defined personnel or roles] [Selection (one or more): as needed; [Assignment: organization-defined frequency]]."}],"discussion":["System monitoring includes external and internal monitoring. External monitoring includes the observation of events occurring at external interfaces to the system. Internal monitoring includes the observation of events occurring within the system. Organizations monitor systems by observing audit activities in real time or by observing other system aspects such as access patterns, characteristics of access, and other actions. The monitoring objectives guide and inform the determination of the events. System monitoring capabilities are achieved through a variety of tools and techniques, including intrusion detection and prevention systems, malicious code protection software, scanning tools, audit record monitoring software, and network monitoring software.","Depending on the security architecture, the distribution and configuration of monitoring devices may impact throughput at key internal and external boundaries as well as at other locations across a network due to the introduction of network throughput latency. If throughput management is needed, such devices are strategically located and deployed as part of an established organization-wide security architecture. Strategic locations for monitoring devices include selected perimeter locations and near key servers and server farms that support critical applications. Monitoring devices are typically employed at the managed interfaces associated with controls [SC-7](#sc-7) and [AC-17](#ac-17). The information collected is a function of the organizational monitoring objectives and the capability of systems to support such objectives. Specific types of transactions of interest include Hypertext Transfer Protocol (HTTP) traffic that bypasses HTTP proxies. System monitoring is an integral part of organizational continuous monitoring and incident response programs, and output from system monitoring serves as input to those programs. System monitoring requirements, including the need for specific types of system monitoring, may be referenced in other controls (e.g., [AC-2g](#ac-2_smt.g), [AC-2(7)](#ac-2.7), [AC-2(12)(a)](#ac-2.12_smt.a), [AC-17(1)](#ac-17.1), [AU-13](#au-13), [AU-13(1)](#au-13.1), [AU-13(2)](#au-13.2), [CM-3f](#cm-3_smt.f), [CM-6d](#cm-6_smt.d), [MA-3a](#ma-3_smt.a), [MA-4a](#ma-4_smt.a), [SC-5(3)(b)](#sc-5.3_smt.b), [SC-7a](#sc-7_smt.a), [SC-7(24)(b)](#sc-7.24_smt.b), [SC-18b](#sc-18_smt.b), [SC-43b](#sc-43_smt.b)). Adjustments to levels of system monitoring are based on law enforcement information, intelligence information, or other sources of information. The legality of system monitoring activities is based on applicable laws, executive orders, directives, regulations, policies, standards, and guidelines."],"params":[{"id":"SI-04_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined monitoring objectives]","guideline":"monitoring objectives to detect attacks and indicators of potential attacks on the system are defined"},{"id":"SI-04_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined techniques and methods]","guideline":"techniques and methods used to identify unauthorized use of the system are defined"},{"id":"SI-04_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined system monitoring information]","guideline":"system monitoring information to be provided to personnel or roles is defined"},{"id":"SI-04_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom system monitoring information is to be provided is/are defined"},{"id":"SI-04_ODP[05]","kind":"Selection","value":"[Selection (one or more): as needed; [Assignment: organization-defined frequency]]"},{"id":"SI-04_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"a frequency for providing system monitoring to personnel or roles is defined (if selected)"}],"related":["AC-2","AC-3","AC-4","AC-8","AC-17","AU-2","AU-6","AU-7","AU-9","AU-12","AU-13","AU-14","CA-7","CM-3","CM-6","CM-8","CM-11","IA-10","IR-4","MA-3","MA-4","PL-9","PM-12","RA-5","RA-10","SC-5","SC-7","SC-18","SC-26","SC-31","SC-35","SC-36","SC-37","SC-43","SI-3","SI-6","SI-7","SR-9","SR-10"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"FIPS 140-3","url":"https://doi.org/10.6028/NIST.FIPS.140-3"},{"title":"SP 800-61","url":"https://doi.org/10.6028/NIST.SP.800-61r2"},{"title":"SP 800-83","url":"https://doi.org/10.6028/NIST.SP.800-83r1"},{"title":"SP 800-92","url":"https://doi.org/10.6028/NIST.SP.800-92"},{"title":"SP 800-94","url":"https://doi.org/10.6028/NIST.SP.800-94"},{"title":"SP 800-137","url":"https://doi.org/10.6028/NIST.SP.800-137"}],"objectives":[{"label":"SI-04a.","prose":"","items":[{"label":"SI-04a.01","prose":"the system is monitored to detect attacks and indicators of potential attacks in accordance with [Assignment: organization-defined monitoring objectives];"},{"label":"SI-04a.02","prose":"","items":[{"label":"SI-04a.02[01]","prose":"the system is monitored to detect unauthorized local connections;"},{"label":"SI-04a.02[02]","prose":"the system is monitored to detect unauthorized network connections;"},{"label":"SI-04a.02[03]","prose":"the system is monitored to detect unauthorized remote connections;"}]}]},{"label":"SI-04b.","prose":"unauthorized use of the system is identified through [Assignment: organization-defined techniques and methods];"},{"label":"SI-04c.","prose":"","items":[{"label":"SI-04c.01","prose":"internal monitoring capabilities are invoked or monitoring devices are deployed strategically within the system to collect organization-determined essential information;"},{"label":"SI-04c.02","prose":"internal monitoring capabilities are invoked or monitoring devices are deployed at ad hoc locations within the system to track specific types of transactions of interest to the organization;"}]},{"label":"SI-04d.","prose":"","items":[{"label":"SI-04d.[01]","prose":"detected events are analyzed;"},{"label":"SI-04d.[02]","prose":"detected anomalies are analyzed;"}]},{"label":"SI-04e.","prose":"the level of system monitoring activity is adjusted when there is a change in risk to organizational operations and assets, individuals, other organizations, or the Nation;"},{"label":"SI-04f.","prose":"a legal opinion regarding system monitoring activities is obtained;"},{"label":"SI-04g.","prose":"[Assignment: organization-defined system monitoring information] is provided to [Assignment: organization-defined personnel or roles] [Selection (one or more): as needed; [Assignment: organization-defined frequency]]."}],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","procedures addressing system monitoring tools and techniques","continuous monitoring strategy","facility diagram/layout","system design documentation","system monitoring tools and techniques documentation","locations within the system where monitoring devices are deployed"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","organizational personnel installing, configuring, and/or maintaining the system","organizational personnel responsible for monitoring the system"]},{"method":"Test","objects":["Organizational processes for system monitoring","mechanisms supporting and/or implementing system monitoring capabilities"]}]},"SI-4(2)":{"statement":[{"prose":"Employ automated tools and mechanisms to support near real-time analysis of events."}],"discussion":["Automated tools and mechanisms include host-based, network-based, transport-based, or storage-based event monitoring tools and mechanisms or security information and event management (SIEM) technologies that provide real-time analysis of alerts and notifications generated by organizational systems. Automated monitoring techniques can create unintended privacy risks because automated controls may connect to external or otherwise unrelated systems. The matching of records between these systems may create linkages with unintended consequences. Organizations assess and document these risks in their privacy impact assessment and make determinations that are in alignment with their privacy program plan."],"params":[],"related":["PM-23","PM-25"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","procedures addressing system monitoring tools and techniques","system design documentation","system monitoring tools and techniques documentation","system configuration settings and associated documentation","system audit records","system security plan"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security and privacy responsibilities","organizational personnel installing, configuring, and/or maintaining the system","organizational personnel responsible for monitoring the system","organizational personnel responsible for incident response/management"]},{"method":"Test","objects":["Organizational processes for the near real-time analysis of events","organizational processes for system monitoring","mechanisms supporting and/or implementing system monitoring","mechanisms/tools supporting and/or implementing an analysis of events"]}]},"SI-4(4)":{"statement":[{"label":"(a)","prose":"Determine criteria for unusual or unauthorized activities or conditions for inbound and outbound communications traffic;"},{"label":"(b)","prose":"Monitor inbound and outbound communications traffic [Assignment: organization-defined frequency] for [Assignment: organization-defined unusual or unauthorized activities or conditions]."}],"discussion":["Unusual or unauthorized activities or conditions related to system inbound and outbound communications traffic includes internal traffic that indicates the presence of malicious code or unauthorized use of legitimate code or credentials within organizational systems or propagating among system components, signaling to external systems, and the unauthorized exporting of information. Evidence of malicious code or unauthorized use of legitimate code or credentials is used to identify potentially compromised systems or system components."],"params":[{"id":"SI-4.4_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined frequency]"},{"id":"SI-4.4_PRM_2","kind":"Assignment","value":"[Assignment: organization-defined unusual or unauthorized activities or conditions]"},{"id":"SI-04(04)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to monitor inbound communications traffic for unusual or unauthorized activities or conditions is defined"},{"id":"SI-04(04)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined unusual or unauthorized activities or conditions]","guideline":"unusual or unauthorized activities or conditions that are to be monitored in inbound communications traffic are defined"},{"id":"SI-04(04)_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to monitor outbound communications traffic for unusual or unauthorized activities or conditions is defined"},{"id":"SI-04(04)_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined unusual or unauthorized activities or conditions]","guideline":"unusual or unauthorized activities or conditions that are to be monitored in outbound communications traffic are defined"}],"related":[],"references":[],"objectives":[{"label":"SI-04(04)(a)","prose":"","items":[{"label":"SI-04(04)(a)[01]","prose":"criteria for unusual or unauthorized activities or conditions for inbound communications traffic are defined;"},{"label":"SI-04(04)(a)[02]","prose":"criteria for unusual or unauthorized activities or conditions for outbound communications traffic are defined;"}]},{"label":"SI-04(04)(b)","prose":"","items":[{"label":"SI-04(04)(b)[01]","prose":"inbound communications traffic is monitored [Assignment: organization-defined frequency] for [Assignment: organization-defined unusual or unauthorized activities or conditions];"},{"label":"SI-04(04)(b)[02]","prose":"outbound communications traffic is monitored [Assignment: organization-defined frequency] for [Assignment: organization-defined unusual or unauthorized activities or conditions]."}]}],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","procedures addressing system monitoring tools and techniques","system design documentation","system monitoring tools and techniques documentation","system configuration settings and associated documentation","system protocols","system audit records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","organizational personnel installing, configuring, and/or maintaining the system","organizational personnel responsible for monitoring the system","organizational personnel responsible for the intrusion detection system"]},{"method":"Test","objects":["Organizational processes for intrusion detection and system monitoring","mechanisms supporting and/or implementing intrusion detection and system monitoring capabilities","mechanisms supporting and/or implementing the monitoring of inbound and outbound communications traffic"]}]},"SI-4(5)":{"statement":[{"prose":"Alert [Assignment: organization-defined personnel or roles] when the following system-generated indications of compromise or potential compromise occur: [Assignment: organization-defined compromise indicators]."}],"discussion":["Alerts may be generated from a variety of sources, including audit records or inputs from malicious code protection mechanisms, intrusion detection or prevention mechanisms, or boundary protection devices such as firewalls, gateways, and routers. Alerts can be automated and may be transmitted telephonically, by electronic mail messages, or by text messaging. Organizational personnel on the alert notification list can include system administrators, mission or business owners, system owners, information owners/stewards, senior agency information security officers, senior agency officials for privacy, system security officers, or privacy officers. In contrast to alerts generated by the system, alerts generated by organizations in [SI-4(12)](#si-4.12) focus on information sources external to the system, such as suspicious activity reports and reports on potential insider threats."],"params":[{"id":"SI-04(05)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to be alerted when indications of compromise or potential compromise occur is/are defined"},{"id":"SI-04(05)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined compromise indicators]","guideline":"compromise indicators are defined"}],"related":["AU-4","AU-5","PE-6"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","procedures addressing system monitoring tools and techniques","system monitoring tools and techniques documentation","system configuration settings and associated documentation","list of personnel selected to receive alerts","documentation of alerts generated based on compromise indicators","system audit records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security and privacy responsibilities","system developers","organizational personnel installing, configuring, and/or maintaining the system","organizational personnel responsible for monitoring the system","organizational personnel on the system alert notification list","organizational personnel responsible for the intrusion detection system"]},{"method":"Test","objects":["Organizational processes for intrusion detection and system monitoring","mechanisms supporting and/or implementing intrusion detection and system monitoring capabilities","mechanisms supporting and/or implementing alerts for compromise indicators"]}]},"SI-4(10)":{"statement":[{"prose":"Make provisions so that [Assignment: organization-defined encrypted communications traffic] is visible to [Assignment: organization-defined system monitoring tools and mechanisms]."}],"discussion":["Organizations balance the need to encrypt communications traffic to protect data confidentiality with the need to maintain visibility into such traffic from a monitoring perspective. Organizations determine whether the visibility requirement applies to internal encrypted traffic, encrypted traffic intended for external destinations, or a subset of the traffic types."],"params":[{"id":"SI-04(10)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined encrypted communications traffic]","guideline":"encrypted communications traffic to be made visible to system monitoring tools and mechanisms is defined"},{"id":"SI-04(10)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined system monitoring tools and mechanisms]","guideline":"system monitoring tools and mechanisms to be provided access to encrypted communications traffic are defined"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","procedures addressing system monitoring tools and techniques","system design documentation","system monitoring tools and techniques documentation","system configuration settings and associated documentation","system protocols","system security plan"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","organizational personnel installing, configuring, and/or maintaining the system","organizational personnel responsible for monitoring the system","organizational personnel responsible for the intrusion detection system"]},{"method":"Test","objects":["Organizational processes for intrusion detection and system monitoring","mechanisms supporting and/or implementing intrusion detection and system monitoring capabilities","mechanisms supporting and/or implementing the visibility of encrypted communications traffic to monitoring tools"]}]},"SI-4(12)":{"statement":[{"prose":"Alert [Assignment: organization-defined personnel or roles] using [Assignment: organization-defined automated mechanisms] when the following indications of inappropriate or unusual activities with security or privacy implications occur: [Assignment: organization-defined activities that trigger alerts]."}],"discussion":["Organizational personnel on the system alert notification list include system administrators, mission or business owners, system owners, senior agency information security officer, senior agency official for privacy, system security officers, or privacy officers. Automated organization-generated alerts are the security alerts generated by organizations and transmitted using automated means. The sources for organization-generated alerts are focused on other entities such as suspicious activity reports and reports on potential insider threats. In contrast to alerts generated by the organization, alerts generated by the system in [SI-4(5)](#si-4.5) focus on information sources that are internal to the systems, such as audit records."],"params":[{"id":"SI-04(12)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to be alerted when indications of inappropriate or unusual activity with security or privacy implications occur is/are defined"},{"id":"SI-04(12)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms used to alert personnel or roles are defined"},{"id":"SI-04(12)_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined activities that trigger alerts]","guideline":"activities that trigger alerts to personnel or are defined"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","procedures addressing system monitoring tools and techniques","system design documentation","system monitoring tools and techniques documentation","system configuration settings and associated documentation","list of inappropriate or unusual activities with security and privacy implications that trigger alerts","suspicious activity reports"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security and privacy responsibilities","system developers","organizational personnel installing, configuring, and/or maintaining the system","organizational personnel responsible for monitoring the system","organizational personnel responsible for the intrusion detection system"]},{"method":"Test","objects":["Organizational processes for intrusion detection and system monitoring","automated mechanisms supporting and/or implementing intrusion detection and system monitoring capabilities","automated mechanisms supporting and/or implementing automated alerts to security personnel"]}]},"SI-4(14)":{"statement":[{"prose":"Employ a wireless intrusion detection system to identify rogue wireless devices and to detect attack attempts and potential compromises or breaches to the system."}],"discussion":["Wireless signals may radiate beyond organizational facilities. Organizations proactively search for unauthorized wireless connections, including the conduct of thorough scans for unauthorized wireless access points. Wireless scans are not limited to those areas within facilities containing systems but also include areas outside of facilities to verify that unauthorized wireless access points are not connected to organizational systems."],"params":[],"related":["AC-18","IA-3"],"references":[],"objectives":[{"label":"SI-04(14)[01]","prose":"a wireless intrusion detection system is employed to identify rogue wireless devices;"},{"label":"SI-04(14)[02]","prose":"a wireless intrusion detection system is employed to detect attack attempts on the system;"},{"label":"SI-04(14)[03]","prose":"a wireless intrusion detection system is employed to detect potential compromises or breaches to the system."}],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","procedures addressing system monitoring tools and techniques","system design documentation","system monitoring tools and techniques documentation","system configuration settings and associated documentation","system protocols","system audit records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","organizational personnel installing, configuring, and/or maintaining the system","organizational personnel responsible for monitoring the system","organizational personnel responsible for the intrusion detection system"]},{"method":"Test","objects":["Organizational processes for intrusion detection","mechanisms supporting and/or implementing a wireless intrusion detection capability"]}]},"SI-4(20)":{"statement":[{"prose":"Implement the following additional monitoring of privileged users: [Assignment: organization-defined additional monitoring]."}],"discussion":["Privileged users have access to more sensitive information, including security-related information, than the general user population. Access to such information means that privileged users can potentially do greater damage to systems and organizations than non-privileged users. Therefore, implementing additional monitoring on privileged users helps to ensure that organizations can identify malicious activity at the earliest possible time and take appropriate actions."],"params":[{"id":"SI-04(20)_ODP","kind":"Assignment","value":"[Assignment: organization-defined additional monitoring]","guideline":"additional monitoring of privileged users is defined"}],"related":["AC-18"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","procedures addressing system monitoring tools and techniques","system design documentation","system monitoring tools and techniques documentation","system configuration settings and associated documentation","system monitoring logs or records","system audit records"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","organizational personnel installing, configuring, and/or maintaining the system","organizational personnel responsible for monitoring the system"]},{"method":"Test","objects":["Organizational processes for system monitoring","mechanisms supporting and/or implementing a system monitoring capability"]}]},"SI-4(22)":{"statement":[{"label":"(a)","prose":"Detect network services that have not been authorized or approved by [Assignment: organization-defined authorization or approval processes]; and"},{"label":"(b)","prose":"[Selection (one or more): audit; alert [Assignment: organization-defined personnel or roles]] when detected."}],"discussion":["Unauthorized or unapproved network services include services in service-oriented architectures that lack organizational verification or validation and may therefore be unreliable or serve as malicious rogues for valid services."],"params":[{"id":"SI-04(22)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined authorization or approval processes]","guideline":"authorization or approval processes for network services are defined"},{"id":"SI-04(22)_ODP[02]","kind":"Selection","value":"[Selection (one or more): audit; alert [Assignment: organization-defined personnel or roles]]"},{"id":"SI-04(22)_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to be alerted upon the detection of network services that have not been authorized or approved by authorization or approval processes is/are defined (if selected)"}],"related":["CM-7"],"references":[],"objectives":[{"label":"SI-04(22)(a)","prose":"network services that have not been authorized or approved by [Assignment: organization-defined authorization or approval processes] are detected;"},{"label":"SI-04(22)(b)","prose":"[Selection (one or more): audit; alert [Assignment: organization-defined personnel or roles]] is/are initiated when network services that have not been authorized or approved by authorization or approval processes are detected."}],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","procedures addressing system monitoring tools and techniques","system design documentation","system monitoring tools and techniques documentation","system configuration settings and associated documentation","documented authorization/approval of network services","notifications or alerts of unauthorized network services"]},{"method":"Interview","objects":["System/network administrators","organizational personnel with information security responsibilities","system developer","organizational personnel installing, configuring, and/or maintaining the system","organizational personnel responsible for monitoring the system"]},{"method":"Test","objects":["Organizational processes for system monitoring","mechanisms supporting and/or implementing a system monitoring capability","mechanisms for auditing network services","mechanisms for providing alerts"]}]},"SI-5":{"statement":[{"label":"a.","prose":"Receive system security alerts, advisories, and directives from [Assignment: organization-defined external organizations] on an ongoing basis;"},{"label":"b.","prose":"Generate internal security alerts, advisories, and directives as deemed necessary;"},{"label":"c.","prose":"Disseminate security alerts, advisories, and directives to: [Selection (one or more): [Assignment: organization-defined personnel or roles]; [Assignment: organization-defined elements]; [Assignment: organization-defined external organizations]]; and"},{"label":"d.","prose":"Implement security directives in accordance with established time frames, or notify the issuing organization of the degree of noncompliance."}],"discussion":["The Cybersecurity and Infrastructure Security Agency (CISA) generates security alerts and advisories to maintain situational awareness throughout the Federal Government. Security directives are issued by OMB or other designated organizations with the responsibility and authority to issue such directives. Compliance with security directives is essential due to the critical nature of many of these directives and the potential (immediate) adverse effects on organizational operations and assets, individuals, other organizations, and the Nation should the directives not be implemented in a timely manner. External organizations include supply chain partners, external mission or business partners, external service providers, and other peer or supporting organizations."],"params":[{"id":"SI-05_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined external organizations]","guideline":"external organizations from whom system security alerts, advisories, and directives are to be received on an ongoing basis are defined"},{"id":"SI-05_ODP[02]","kind":"Selection","value":"[Selection (one or more): [Assignment: organization-defined personnel or roles]; [Assignment: organization-defined elements]; [Assignment: organization-defined external organizations]]"},{"id":"SI-05_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom security alerts, advisories, and directives are to be disseminated is/are defined (if selected)"},{"id":"SI-05_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined elements]","guideline":"elements within the organization to whom security alerts, advisories, and directives are to be disseminated are defined (if selected)"},{"id":"SI-05_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined external organizations]","guideline":"external organizations to whom security alerts, advisories, and directives are to be disseminated are defined (if selected)"}],"related":["PM-15","RA-5","SI-2"],"references":[{"title":"SP 800-40","url":"https://doi.org/10.6028/NIST.SP.800-40r3"}],"objectives":[{"label":"SI-05a.","prose":"system security alerts, advisories, and directives are received from [Assignment: organization-defined external organizations] on an ongoing basis;"},{"label":"SI-05b.","prose":"internal security alerts, advisories, and directives are generated as deemed necessary;"},{"label":"SI-05c.","prose":"security alerts, advisories, and directives are disseminated to [Selection (one or more): [Assignment: organization-defined personnel or roles]; [Assignment: organization-defined elements]; [Assignment: organization-defined external organizations]];"},{"label":"SI-05d.","prose":"security directives are implemented in accordance with established time frames or if the issuing organization is notified of the degree of noncompliance."}],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","procedures addressing security alerts, advisories, and directives","records of security alerts and advisories","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with security alert and advisory responsibilities","organizational personnel implementing, operating, maintaining, and using the system","organizational personnel, organizational elements, and/or external organizations to whom alerts, advisories, and directives are to be disseminated","system/network administrators","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for defining, receiving, generating, disseminating, and complying with security alerts, advisories, and directives","mechanisms supporting and/or implementing the definition, receipt, generation, and dissemination of security alerts, advisories, and directives","mechanisms supporting and/or implementing security directives"]}]},"SI-5(1)":{"statement":[{"prose":"Broadcast security alert and advisory information throughout the organization using [Assignment: organization-defined automated mechanisms]."}],"discussion":["The significant number of changes to organizational systems and environments of operation requires the dissemination of security-related information to a variety of organizational entities that have a direct interest in the success of organizational mission and business functions. Based on information provided by security alerts and advisories, changes may be required at one or more of the three levels related to the management of risk, including the governance level, mission and business process level, and the information system level."],"params":[{"id":"SI-05(01)_ODP","kind":"Assignment","value":"[Assignment: organization-defined automated mechanisms]","guideline":"automated mechanisms used to broadcast security alert and advisory information throughout the organization are defined"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","procedures addressing security alerts, advisories, and directives","system design documentation","system configuration settings and associated documentation","automated mechanisms supporting the distribution of security alert and advisory information","records of security alerts and advisories","system audit records"]},{"method":"Interview","objects":["Organizational personnel with security alert and advisory responsibilities","organizational personnel implementing, operating, maintaining, and using the system","organizational personnel, organizational elements, and/or external organizations to whom alerts and advisories are to be disseminated","system/network administrators","organizational personnel with information security responsibilities"]},{"method":"Test","objects":["Organizational processes for defining, receiving, generating, and disseminating security alerts and advisories","automated mechanisms supporting and/or implementing the dissemination of security alerts and advisories"]}]},"SI-6":{"statement":[{"label":"a.","prose":"Verify the correct operation of [Assignment: organization-defined security and privacy functions];"},{"label":"b.","prose":"Perform the verification of the functions specified in SI-6a [Selection (one or more): [Assignment: organization-defined system transitional states]; upon command by user with appropriate privilege; [Assignment: organization-defined frequency]];"},{"label":"c.","prose":"Alert [Assignment: organization-defined personnel or roles] to failed security and privacy verification tests; and"},{"label":"d.","prose":"[Selection (one or more): shut the system down; restart the system; [Assignment: organization-defined alternative action(s)]] when anomalies are discovered."}],"discussion":["Transitional states for systems include system startup, restart, shutdown, and abort. System notifications include hardware indicator lights, electronic alerts to system administrators, and messages to local computer consoles. In contrast to security function verification, privacy function verification ensures that privacy functions operate as expected and are approved by the senior agency official for privacy or that privacy attributes are applied or used as expected."],"params":[{"id":"SI-6_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined security and privacy functions]"},{"id":"SI-06_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined security functions]","guideline":"security functions to be verified for correct operation are defined"},{"id":"SI-06_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined privacy functions]","guideline":"privacy functions to be verified for correct operation are defined"},{"id":"SI-06_ODP[03]","kind":"Selection","value":"[Selection (one or more): [Assignment: organization-defined system transitional states]; upon command by user with appropriate privilege; [Assignment: organization-defined frequency]]"},{"id":"SI-06_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined system transitional states]","guideline":"system transitional states requiring the verification of security and privacy functions are defined; (if selected)"},{"id":"SI-06_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to verify the correct operation of security and privacy functions is defined; (if selected)"},{"id":"SI-06_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to be alerted of failed security and privacy verification tests is/are defined"},{"id":"SI-06_ODP[07]","kind":"Selection","value":"[Selection (one or more): shut the system down; restart the system; [Assignment: organization-defined alternative action(s)]]"},{"id":"SI-06_ODP[08]","kind":"Assignment","value":"[Assignment: organization-defined alternative action(s)]","guideline":"alternative action(s) to be performed when anomalies are discovered are defined (if selected)"}],"related":["CA-7","CM-4","CM-6","SI-7"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"}],"objectives":[{"label":"SI-06a.","prose":"","items":[{"label":"SI-06a.[01]","prose":"[Assignment: organization-defined security functions] are verified to be operating correctly;"},{"label":"SI-06a.[02]","prose":"[Assignment: organization-defined privacy functions] are verified to be operating correctly;"}]},{"label":"SI-06b.","prose":"","items":[{"label":"SI-06b.[01]","prose":"[Assignment: organization-defined security functions] are verified [Selection (one or more): [Assignment: organization-defined system transitional states]; upon command by user with appropriate privilege; [Assignment: organization-defined frequency]];"},{"label":"SI-06b.[02]","prose":"[Assignment: organization-defined privacy functions] are verified [Selection (one or more): [Assignment: organization-defined system transitional states]; upon command by user with appropriate privilege; [Assignment: organization-defined frequency]];"}]},{"label":"SI-06c.","prose":"","items":[{"label":"SI-06c.[01]","prose":"[Assignment: organization-defined personnel or roles] is/are alerted to failed security verification tests;"},{"label":"SI-06c.[02]","prose":"[Assignment: organization-defined personnel or roles] is/are alerted to failed privacy verification tests;"}]},{"label":"SI-06d.","prose":"[Selection (one or more): shut the system down; restart the system; [Assignment: organization-defined alternative action(s)]] is/are initiated when anomalies are discovered."}],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","procedures addressing security and privacy function verification","system design documentation","system configuration settings and associated documentation","alerts/notifications of failed security verification tests","list of system transition states requiring security functionality verification","system audit records"]},{"method":"Interview","objects":["Organizational personnel with security and privacy function verification responsibilities","organizational personnel implementing, operating, and maintaining the system","system/network administrators","organizational personnel with information security and privacy responsibilities","system developer"]},{"method":"Test","objects":["Organizational processes for security and privacy function verification","mechanisms supporting and/or implementing the security and privacy function verification capability"]}]},"SI-7":{"statement":[{"label":"a.","prose":"Employ integrity verification tools to detect unauthorized changes to the following software, firmware, and information: [Assignment: organization-defined software, firmware, and information]; and"},{"label":"b.","prose":"Take the following actions when unauthorized changes to the software, firmware, and information are detected: [Assignment: organization-defined actions]."}],"discussion":["Unauthorized changes to software, firmware, and information can occur due to errors or malicious activity. Software includes operating systems (with key internal components, such as kernels or drivers), middleware, and applications. Firmware interfaces include Unified Extensible Firmware Interface (UEFI) and Basic Input/Output System (BIOS). Information includes personally identifiable information and metadata that contains security and privacy attributes associated with information. Integrity-checking mechanisms—including parity checks, cyclical redundancy checks, cryptographic hashes, and associated tools—can automatically monitor the integrity of systems and hosted applications."],"params":[{"id":"SI-7_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined software, firmware, and information]"},{"id":"SI-7_PRM_2","kind":"Assignment","value":"[Assignment: organization-defined actions]"},{"id":"SI-07_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined software]","guideline":"software requiring integrity verification tools to be employed to detect unauthorized changes is defined"},{"id":"SI-07_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined firmware]","guideline":"firmware requiring integrity verification tools to be employed to detect unauthorized changes is defined"},{"id":"SI-07_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined information]","guideline":"information requiring integrity verification tools to be employed to detect unauthorized changes is defined"},{"id":"SI-07_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined actions]","guideline":"actions to be taken when unauthorized changes to software are detected are defined"},{"id":"SI-07_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined actions]","guideline":"actions to be taken when unauthorized changes to firmware are detected are defined"},{"id":"SI-07_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined actions]","guideline":"actions to be taken when unauthorized changes to information are detected are defined"}],"related":["AC-4","CM-3","CM-7","CM-8","MA-3","MA-4","RA-5","SA-8","SA-9","SA-10","SC-8","SC-12","SC-13","SC-28","SC-37","SI-3","SR-3","SR-4","SR-5","SR-6","SR-9","SR-10","SR-11"],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"},{"title":"FIPS 140-3","url":"https://doi.org/10.6028/NIST.FIPS.140-3"},{"title":"FIPS 180-4","url":"https://doi.org/10.6028/NIST.FIPS.180-4"},{"title":"FIPS 186-4","url":"https://doi.org/10.6028/NIST.FIPS.186-4"},{"title":"FIPS 202","url":"https://doi.org/10.6028/NIST.FIPS.202"},{"title":"SP 800-70","url":"https://doi.org/10.6028/NIST.SP.800-70r4"},{"title":"SP 800-147","url":"https://doi.org/10.6028/NIST.SP.800-147"}],"objectives":[{"label":"SI-07a.","prose":"","items":[{"label":"SI-07a.[01]","prose":"integrity verification tools are employed to detect unauthorized changes to [Assignment: organization-defined software];"},{"label":"SI-07a.[02]","prose":"integrity verification tools are employed to detect unauthorized changes to [Assignment: organization-defined firmware];"},{"label":"SI-07a.[03]","prose":"integrity verification tools are employed to detect unauthorized changes to [Assignment: organization-defined information];"}]},{"label":"SI-07b.","prose":"","items":[{"label":"SI-07b.[01]","prose":"[Assignment: organization-defined actions] are taken when unauthorized changes to the software, are detected;"},{"label":"SI-07b.[02]","prose":"[Assignment: organization-defined actions] are taken when unauthorized changes to the firmware are detected;"},{"label":"SI-07b.[03]","prose":"[Assignment: organization-defined actions] are taken when unauthorized changes to the information are detected."}]}],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","procedures addressing software, firmware, and information integrity","personally identifiable information processing policy","system design documentation","system configuration settings and associated documentation","integrity verification tools and associated documentation","records generated or triggered by integrity verification tools regarding unauthorized software, firmware, and information changes"]},{"method":"Interview","objects":["Organizational personnel responsible for software, firmware, and/or information integrity","organizational personnel with information security and privacy responsibilities","system/network administrators"]},{"method":"Test","objects":["Software, firmware, and information integrity verification tools"]}]},"SI-7(1)":{"statement":[{"prose":"Perform an integrity check of [Assignment: organization-defined software, firmware, and information] [Selection (one or more): at startup; at [Assignment: organization-defined transitional states or security-relevant events]; [Assignment: organization-defined frequency]]."}],"discussion":["Security-relevant events include the identification of new threats to which organizational systems are susceptible and the installation of new hardware, software, or firmware. Transitional states include system startup, restart, shutdown, and abort."],"params":[{"id":"SI-7.1_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined software, firmware, and information]"},{"id":"SI-7.1_PRM_2","kind":"Selection","value":"[Selection (one or more): at startup; at [Assignment: organization-defined transitional states or security-relevant events]; [Assignment: organization-defined frequency]]"},{"id":"SI-7.1_PRM_3","kind":"Assignment","value":"[Assignment: organization-defined transitional states or security-relevant events]"},{"id":"SI-7.1_PRM_4","kind":"Assignment","value":"[Assignment: organization-defined frequency]"},{"id":"SI-07(01)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined software]","guideline":"software on which an integrity check is to be performed is defined"},{"id":"SI-07(01)_ODP[02]","kind":"Selection","value":"[Selection (one or more): at startup; at [Assignment: organization-defined transitional states or security-relevant events]; [Assignment: organization-defined frequency]]"},{"id":"SI-07(01)_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined transitional states or security-relevant events]","guideline":"transitional states or security-relevant events requiring integrity checks (on software) are defined (if selected)"},{"id":"SI-07(01)_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency with which to perform an integrity check (on software) is defined (if selected)"},{"id":"SI-07(01)_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined firmware]","guideline":"firmware on which an integrity check is to be performed is defined"},{"id":"SI-07(01)_ODP[06]","kind":"Selection","value":"[Selection (one or more): at startup; at [Assignment: organization-defined transitional states or security-relevant events]; [Assignment: organization-defined frequency]]"},{"id":"SI-07(01)_ODP[07]","kind":"Assignment","value":"[Assignment: organization-defined transitional states or security-relevant events]","guideline":"transitional states or security-relevant events requiring integrity checks (on firmware) are defined (if selected)"},{"id":"SI-07(01)_ODP[08]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency with which to perform an integrity check (on firmware) is defined (if selected)"},{"id":"SI-07(01)_ODP[09]","kind":"Assignment","value":"[Assignment: organization-defined information]","guideline":"information on which an integrity check is to be performed is defined"},{"id":"SI-07(01)_ODP[10]","kind":"Selection","value":"[Selection (one or more): at startup; at [Assignment: organization-defined transitional states or security-relevant events]; [Assignment: organization-defined frequency]]"},{"id":"SI-07(01)_ODP[11]","kind":"Assignment","value":"[Assignment: organization-defined transitional states or security-relevant events]","guideline":"transitional states or security-relevant events requiring integrity checks (of information) are defined (if selected)"},{"id":"SI-07(01)_ODP[12]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency with which to perform an integrity check (of information) is defined (if selected)"}],"related":[],"references":[],"objectives":[{"label":"SI-07(01)[01]","prose":"an integrity check of [Assignment: organization-defined software] is performed [Selection (one or more): at startup; at [Assignment: organization-defined transitional states or security-relevant events]; [Assignment: organization-defined frequency]];"},{"label":"SI-07(01)[02]","prose":"an integrity check of [Assignment: organization-defined firmware] is performed [Selection (one or more): at startup; at [Assignment: organization-defined transitional states or security-relevant events]; [Assignment: organization-defined frequency]];"},{"label":"SI-07(01)[03]","prose":"an integrity check of [Assignment: organization-defined information] is performed [Selection (one or more): at startup; at [Assignment: organization-defined transitional states or security-relevant events]; [Assignment: organization-defined frequency]]."}],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","procedures addressing software, firmware, and information integrity testing","system design documentation","system configuration settings and associated documentation","integrity verification tools and associated documentation","records of integrity scans","system security plan"]},{"method":"Interview","objects":["Organizational personnel responsible for software, firmware, and/or information integrity","organizational personnel with information security responsibilities","system/network administrators","system developer"]},{"method":"Test","objects":["Software, firmware, and information integrity verification tools"]}]},"SI-7(2)":{"statement":[{"prose":"Employ automated tools that provide notification to [Assignment: organization-defined personnel or roles] upon discovering discrepancies during integrity verification."}],"discussion":["The employment of automated tools to report system and information integrity violations and to notify organizational personnel in a timely matter is essential to effective risk response. Personnel with an interest in system and information integrity violations include mission and business owners, system owners, senior agency information security official, senior agency official for privacy, system administrators, software developers, systems integrators, information security officers, and privacy officers."],"params":[{"id":"SI-07(02)_ODP","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom notification is to be provided upon discovering discrepancies during integrity verification is/are defined"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","procedures addressing software, firmware, and information integrity","personally identifiable information processing policy","system design documentation","system configuration settings and associated documentation","integrity verification tools and associated documentation","records of integrity scans"]},{"method":"Interview","objects":["Organizational personnel responsible for software, firmware, and/or information integrity","organizational personnel with information security and privacy responsibilities","system administrators","software developers"]},{"method":"Test","objects":["Software, firmware, and information integrity verification tools","mechanisms providing integrity discrepancy notifications"]}]},"SI-7(5)":{"statement":[{"prose":"Automatically [Selection (one or more): shut down the system; restart the system; implement [Assignment: organization-defined controls]] when integrity violations are discovered."}],"discussion":["Organizations may define different integrity-checking responses by type of information, specific information, or a combination of both. Types of information include firmware, software, and user data. Specific information includes boot firmware for certain types of machines. The automatic implementation of controls within organizational systems includes reversing the changes, halting the system, or triggering audit alerts when unauthorized modifications to critical security files occur."],"params":[{"id":"SI-07(05)_ODP[01]","kind":"Selection","value":"[Selection (one or more): shut down the system; restart the system; implement [Assignment: organization-defined controls]]"},{"id":"SI-07(05)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined controls]","guideline":"controls to be implemented automatically when integrity violations are discovered are defined (if selected)"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","procedures addressing software, firmware, and information integrity","system design documentation","system configuration settings and associated documentation","integrity verification tools and associated documentation","records of integrity scans","records of integrity checks and responses to integrity violations"]},{"method":"Interview","objects":["Organizational personnel responsible for software, firmware, and/or information integrity","organizational personnel with information security responsibilities","system/network administrators","system developer"]},{"method":"Test","objects":["Software, firmware, and information integrity verification tools","mechanisms providing an automated response to integrity violations","mechanisms supporting and/or implementing security safeguards to be implemented when integrity violations are discovered"]}]},"SI-7(7)":{"statement":[{"prose":"Incorporate the detection of the following unauthorized changes into the organizational incident response capability: [Assignment: organization-defined changes]."}],"discussion":["Integrating detection and response helps to ensure that detected events are tracked, monitored, corrected, and available for historical purposes. Maintaining historical records is important for being able to identify and discern adversary actions over an extended time period and for possible legal actions. Security-relevant changes include unauthorized changes to established configuration settings or the unauthorized elevation of system privileges."],"params":[{"id":"SI-07(07)_ODP","kind":"Assignment","value":"[Assignment: organization-defined changes]","guideline":"security-relevant changes to the system are defined"}],"related":["AU-2","AU-6","IR-4","IR-5","SI-4"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","procedures addressing software, firmware, and information integrity","procedures addressing incident response","system design documentation","system configuration settings and associated documentation","incident response records","audit records"]},{"method":"Interview","objects":["Organizational personnel responsible for software, firmware, and/or information integrity","organizational personnel with information security responsibilities","organizational personnel with incident response responsibilities"]},{"method":"Test","objects":["Organizational processes for incorporating the detection of unauthorized security-relevant changes into the incident response capability","software, firmware, and information integrity verification tools","mechanisms supporting and/or implementing the incorporation of detection of unauthorized security-relevant changes into the incident response capability"]}]},"SI-7(15)":{"statement":[{"prose":"Implement cryptographic mechanisms to authenticate the following software or firmware components prior to installation: [Assignment: organization-defined software or firmware components]."}],"discussion":["Cryptographic authentication includes verifying that software or firmware components have been digitally signed using certificates recognized and approved by organizations. Code signing is an effective method to protect against malicious code. Organizations that employ cryptographic mechanisms also consider cryptographic key management solutions."],"params":[{"id":"SI-07(15)_ODP","kind":"Assignment","value":"[Assignment: organization-defined software or firmware components]","guideline":"software or firmware components to be authenticated by cryptographic mechanisms prior to installation are defined"}],"related":["CM-5","SC-12","SC-13"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","procedures addressing software, firmware, and information integrity","system design documentation","system configuration settings and associated documentation","cryptographic mechanisms and associated documentation","system audit records","system security plan"]},{"method":"Interview","objects":["Organizational personnel responsible for software, firmware, and/or information integrity","organizational personnel with information security responsibilities","system/network administrators","system developer"]},{"method":"Test","objects":["Cryptographic mechanisms authenticating software and firmware prior to installation"]}]},"SI-8":{"statement":[{"label":"a.","prose":"Employ spam protection mechanisms at system entry and exit points to detect and act on unsolicited messages; and"},{"label":"b.","prose":"Update spam protection mechanisms when new releases are available in accordance with organizational configuration management policy and procedures."}],"discussion":["System entry and exit points include firewalls, remote-access servers, electronic mail servers, web servers, proxy servers, workstations, notebook computers, and mobile devices. Spam can be transported by different means, including email, email attachments, and web accesses. Spam protection mechanisms include signature definitions."],"params":[],"related":["PL-9","SC-5","SC-7","SC-38","SI-3","SI-4"],"references":[{"title":"SP 800-45","url":"https://doi.org/10.6028/NIST.SP.800-45ver2"},{"title":"SP 800-177","url":"https://doi.org/10.6028/NIST.SP.800-177r1"}],"objectives":[{"label":"SI-08a.","prose":"","items":[{"label":"SI-08a.[01]","prose":"spam protection mechanisms are employed at system entry points to detect unsolicited messages;"},{"label":"SI-08a.[02]","prose":"spam protection mechanisms are employed at system exit points to detect unsolicited messages;"},{"label":"SI-08a.[03]","prose":"spam protection mechanisms are employed at system entry points to act on unsolicited messages;"},{"label":"SI-08a.[04]","prose":"spam protection mechanisms are employed at system exit points to act on unsolicited messages;"}]},{"label":"SI-08b.","prose":"spam protection mechanisms are updated when new releases are available in accordance with organizational configuration management policies and procedures."}],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","configuration management policies and procedures (CM-01)","procedures addressing spam protection","spam protection mechanisms","records of spam protection updates","system design documentation","system configuration settings and associated documentation"]},{"method":"Interview","objects":["Organizational personnel responsible for spam protection","organizational personnel with information security responsibilities","system/network administrators","system developer"]},{"method":"Test","objects":["Organizational processes for implementing spam protection","mechanisms supporting and/or implementing spam protection"]}]},"SI-8(2)":{"statement":[{"prose":"Automatically update spam protection mechanisms [Assignment: organization-defined frequency]."}],"discussion":["Using automated mechanisms to update spam protection mechanisms helps to ensure that updates occur on a regular basis and provide the latest content and protection capabilities."],"params":[{"id":"SI-08(02)_ODP","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to automatically update spam protection mechanisms is defined"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","procedures addressing spam protection","spam protection mechanisms","records of spam protection updates","system design documentation","system configuration settings and associated documentation","system audit records"]},{"method":"Interview","objects":["Organizational personnel responsible for spam protection","organizational personnel with information security responsibilities","system/network administrators","system developer"]},{"method":"Test","objects":["Organizational processes for spam protection","mechanisms supporting and/or implementing automatic updates to spam protection mechanisms"]}]},"SI-10":{"statement":[{"prose":"Check the validity of the following information inputs: [Assignment: organization-defined information inputs]."}],"discussion":["Checking the valid syntax and semantics of system inputs—including character set, length, numerical range, and acceptable values—verifies that inputs match specified definitions for format and content. For example, if the organization specifies that numerical values between 1-100 are the only acceptable inputs for a field in a given application, inputs of \"387,\" \"abc,\" or \"%K%\" are invalid inputs and are not accepted as input to the system. Valid inputs are likely to vary from field to field within a software application. Applications typically follow well-defined protocols that use structured messages (i.e., commands or queries) to communicate between software modules or system components. Structured messages can contain raw or unstructured data interspersed with metadata or control information. If software applications use attacker-supplied inputs to construct structured messages without properly encoding such messages, then the attacker could insert malicious commands or special characters that can cause the data to be interpreted as control information or metadata. Consequently, the module or component that receives the corrupted output will perform the wrong operations or otherwise interpret the data incorrectly. Prescreening inputs prior to passing them to interpreters prevents the content from being unintentionally interpreted as commands. Input validation ensures accurate and correct inputs and prevents attacks such as cross-site scripting and a variety of injection attacks."],"params":[{"id":"SI-10_ODP","kind":"Assignment","value":"[Assignment: organization-defined information inputs]","guideline":"information inputs to the system requiring validity checks are defined"}],"related":[],"references":[{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"}],"objectives":[],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","access control policy and procedures","separation of duties policy and procedures","procedures addressing information input validation","documentation for automated tools and applications to verify the validity of information","list of information inputs requiring validity checks","system design documentation"]},{"method":"Interview","objects":["Organizational personnel responsible for information input validation","organizational personnel with information security responsibilities","system/network administrators","system developer"]},{"method":"Test","objects":["Mechanisms supporting and/or implementing validity checks on information inputs"]}]},"SI-11":{"statement":[{"label":"a.","prose":"Generate error messages that provide information necessary for corrective actions without revealing information that could be exploited; and"},{"label":"b.","prose":"Reveal error messages only to [Assignment: organization-defined personnel or roles]."}],"discussion":["Organizations consider the structure and content of error messages. The extent to which systems can handle error conditions is guided and informed by organizational policy and operational requirements. Exploitable information includes stack traces and implementation details; erroneous logon attempts with passwords mistakenly entered as the username; mission or business information that can be derived from, if not stated explicitly by, the information recorded; and personally identifiable information, such as account numbers, social security numbers, and credit card numbers. Error messages may also provide a covert channel for transmitting information."],"params":[{"id":"SI-11_ODP","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom error messages are to be revealed is/are defined"}],"related":["AU-2","AU-3","SC-31","SI-2","SI-15"],"references":[],"objectives":[{"label":"SI-11a.","prose":"error messages that provide the information necessary for corrective actions are generated without revealing information that could be exploited;"},{"label":"SI-11b.","prose":"error messages are revealed only to [Assignment: organization-defined personnel or roles]."}],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","procedures addressing system error handling","system design documentation","system configuration settings and associated documentation","documentation providing the structure and content of error messages","system audit records","system security plan"]},{"method":"Interview","objects":["Organizational personnel responsible for information input validation","organizational personnel with information security responsibilities","system/network administrators","system developer"]},{"method":"Test","objects":["Organizational processes for error handling","automated mechanisms supporting and/or implementing error handling","automated mechanisms supporting and/or implementing the management of error messages"]}]},"SI-12":{"statement":[{"prose":"Manage and retain information within the system and information output from the system in accordance with applicable laws, executive orders, directives, regulations, policies, standards, guidelines and operational requirements."}],"discussion":["Information management and retention requirements cover the full life cycle of information, in some cases extending beyond system disposal. Information to be retained may also include policies, procedures, plans, reports, data output from control implementation, and other types of administrative information. The National Archives and Records Administration (NARA) provides federal policy and guidance on records retention and schedules. If organizations have a records management office, consider coordinating with records management personnel. Records produced from the output of implemented controls that may require management and retention include, but are not limited to: All XX-1, [AC-6(9)](#ac-6.9), [AT-4](#at-4), [AU-12](#au-12), [CA-2](#ca-2), [CA-3](#ca-3), [CA-5](#ca-5), [CA-6](#ca-6), [CA-7](#ca-7), [CA-8](#ca-8), [CA-9](#ca-9), [CM-2](#cm-2), [CM-3](#cm-3), [CM-4](#cm-4), [CM-6](#cm-6), [CM-8](#cm-8), [CM-9](#cm-9), [CM-12](#cm-12), [CM-13](#cm-13), [CP-2](#cp-2), [IR-6](#ir-6), [IR-8](#ir-8), [MA-2](#ma-2), [MA-4](#ma-4), [PE-2](#pe-2), [PE-8](#pe-8), [PE-16](#pe-16), [PE-17](#pe-17), [PL-2](#pl-2), [PL-4](#pl-4), [PL-7](#pl-7), [PL-8](#pl-8), [PM-5](#pm-5), [PM-8](#pm-8), [PM-9](#pm-9), [PM-18](#pm-18), [PM-21](#pm-21), [PM-27](#pm-27), [PM-28](#pm-28), [PM-30](#pm-30), [PM-31](#pm-31), [PS-2](#ps-2), [PS-6](#ps-6), [PS-7](#ps-7), [PT-2](#pt-2), [PT-3](#pt-3), [PT-7](#pt-7), [RA-2](#ra-2), [RA-3](#ra-3), [RA-5](#ra-5), [RA-8](#ra-8), [SA-4](#sa-4), [SA-5](#sa-5), [SA-8](#sa-8), [SA-10](#sa-10), [SI-4](#si-4), [SR-2](#sr-2), [SR-4](#sr-4), [SR-8](#sr-8)."],"params":[],"related":["AC-16","AU-5","AU-11","CA-2","CA-3","CA-5","CA-6","CA-7","CA-9","CM-5","CM-9","CP-2","IR-8","MP-2","MP-3","MP-4","MP-6","PL-2","PL-4","PM-4","PM-8","PM-9","PS-2","PS-6","PT-2","PT-3","RA-2","RA-3","SA-5","SA-8","SR-2"],"references":[{"title":"USC 2901","url":"https://www.govinfo.gov/content/pkg/USCODE-2011-title44/pdf/USCODE-2011-title44-chap29-sec2901.pdf"},{"title":"OMB A-130","url":"https://www.whitehouse.gov/sites/whitehouse.gov/files/omb/circulars/A130/a130revised.pdf"}],"objectives":[{"label":"SI-12[01]","prose":"information within the system is managed in accordance with applicable laws, Executive Orders, directives, regulations, policies, standards, guidelines, and operational requirements;"},{"label":"SI-12[02]","prose":"information within the system is retained in accordance with applicable laws, Executive Orders, directives, regulations, policies, standards, guidelines, and operational requirements;"},{"label":"SI-12[03]","prose":"information output from the system is managed in accordance with applicable laws, Executive Orders, directives, regulations, policies, standards, guidelines, and operational requirements;"},{"label":"SI-12[04]","prose":"information output from the system is retained in accordance with applicable laws, Executive Orders, directives, regulations, policies, standards, guidelines, and operational requirements."}],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","personally identifiable information processing policy","records retention and disposition policy","records retention and disposition procedures","federal laws, Executive Orders, directives, policies, regulations, standards, and operational requirements applicable to information management and retention","media protection policy","media protection procedures"]},{"method":"Interview","objects":["Organizational personnel with information and records management, retention, and disposition responsibilities","organizational personnel with information security and privacy responsibilities","network administrators"]},{"method":"Test","objects":["Organizational processes for information management, retention, and disposition","automated mechanisms supporting and/or implementing information management, retention, and disposition"]}]},"SI-16":{"statement":[{"prose":"Implement the following controls to protect the system memory from unauthorized code execution: [Assignment: organization-defined controls]."}],"discussion":["Some adversaries launch attacks with the intent of executing code in non-executable regions of memory or in memory locations that are prohibited. Controls employed to protect memory include data execution prevention and address space layout randomization. Data execution prevention controls can either be hardware-enforced or software-enforced with hardware enforcement providing the greater strength of mechanism."],"params":[{"id":"SI-16_ODP","kind":"Assignment","value":"[Assignment: organization-defined controls]","guideline":"controls to be implemented to protect the system memory from unauthorized code execution are defined"}],"related":["AC-25","SC-3","SI-7"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","procedures addressing memory protection for the system","system design documentation","system configuration settings and associated documentation","list of security safeguards protecting system memory from unauthorized code execution","system audit records","system security plan"]},{"method":"Interview","objects":["Organizational personnel responsible for memory protection","organizational personnel with information security responsibilities","system/network administrators","system developer"]},{"method":"Test","objects":["Automated mechanisms supporting and/or implementing safeguards to protect the system memory from unauthorized code execution"]}]},"SI-18":{"statement":[{"label":"a.","prose":"Check the accuracy, relevance, timeliness, and completeness of personally identifiable information across the information life cycle [Assignment: organization-defined frequency]; and"},{"label":"b.","prose":"Correct or delete inaccurate or outdated personally identifiable information."}],"discussion":["Personally identifiable information quality operations include the steps that organizations take to confirm the accuracy and relevance of personally identifiable information throughout the information life cycle. The information life cycle includes the creation, collection, use, processing, storage, maintenance, dissemination, disclosure, and disposal of personally identifiable information. Personally identifiable information quality operations include editing and validating addresses as they are collected or entered into systems using automated address verification look-up application programming interfaces. Checking personally identifiable information quality includes the tracking of updates or changes to data over time, which enables organizations to know how and what personally identifiable information was changed should erroneous information be identified. The measures taken to protect personally identifiable information quality are based on the nature and context of the personally identifiable information, how it is to be used, how it was obtained, and the potential de-identification methods employed. The measures taken to validate the accuracy of personally identifiable information used to make determinations about the rights, benefits, or privileges of individuals covered under federal programs may be more comprehensive than the measures used to validate personally identifiable information used for less sensitive purposes."],"params":[{"id":"SI-18_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined frequency]"},{"id":"SI-18_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to check the accuracy of personally identifiable information across the information life cycle is defined"},{"id":"SI-18_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to check the relevance of personally identifiable information across the information life cycle is defined"},{"id":"SI-18_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to check the timeliness of personally identifiable information across the information life cycle is defined"},{"id":"SI-18_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to check the completeness of personally identifiable information across the information life cycle is defined"}],"related":["PM-22","PM-24","PT-2","SI-4"],"references":[{"title":"OMB M-19-15","url":"https://www.whitehouse.gov/wp-content/uploads/2019/04/M-19-15.pdf"},{"title":"SP 800-188","url":"https://csrc.nist.gov/publications/detail/sp/800-188/draft"},{"title":"IR 8112","url":"https://doi.org/10.6028/NIST.IR.8112"}],"objectives":[{"label":"SI-18a.","prose":"","items":[{"label":"SI-18a.[01]","prose":"the accuracy of personally identifiable information across the information life cycle is checked [Assignment: organization-defined frequency];"},{"label":"SI-18a.[02]","prose":"the relevance of personally identifiable information across the information life cycle is checked [Assignment: organization-defined frequency];"},{"label":"SI-18a.[03]","prose":"the timeliness of personally identifiable information across the information life cycle is checked [Assignment: organization-defined frequency];"},{"label":"SI-18a.[04]","prose":"the completeness of personally identifiable information across the information life cycle is checked [Assignment: organization-defined frequency];"}]},{"label":"SI-18b.","prose":"inaccurate or outdated personally identifiable information is corrected or deleted."}],"methods":[{"method":"Examine","objects":["System and information integrity policy","system and information integrity procedures","personally identifiable information processing policy","documentation addressing personally identifiable information quality operations","quality reports","maintenance logs","system audit records","audit findings"]},{"method":"Interview","objects":["Organizational personnel responsible for performing personally identifiable information quality inspections","organizational personnel with information security responsibilities","organizational personnel with privacy responsibilities"]},{"method":"Test","objects":["Organizational processes for personally identifiable information quality inspection","automated mechanisms supporting and/or implementing personally identifiable information quality operations"]}]},"SR-1":{"statement":[{"label":"a.","prose":"Develop, document, and disseminate to [Assignment: organization-defined personnel or roles]:","items":[{"label":"1.","prose":"[Selection (one or more): organization-level; mission/business process-level; system-level] supply chain risk management policy that:","items":[{"label":"(a)","prose":"Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and"},{"label":"(b)","prose":"Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and"}]},{"label":"2.","prose":"Procedures to facilitate the implementation of the supply chain risk management policy and the associated supply chain risk management controls;"}]},{"label":"b.","prose":"Designate an [Assignment: organization-defined official] to manage the development, documentation, and dissemination of the supply chain risk management policy and procedures; and"},{"label":"c.","prose":"Review and update the current supply chain risk management:","items":[{"label":"1.","prose":"Policy [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]; and"},{"label":"2.","prose":"Procedures [Assignment: organization-defined frequency] and following [Assignment: organization-defined events]."}]}],"discussion":["Supply chain risk management policy and procedures address the controls in the SR family as well as supply chain-related controls in other families that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of supply chain risk management policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to supply chain risk management policy and procedures include assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure."],"params":[{"id":"SR-1_PRM_1","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]"},{"id":"SR-01_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom supply chain risk management policy is to be disseminated to is/are defined"},{"id":"SR-01_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom supply chain risk management procedures are disseminated to is/are defined"},{"id":"SR-01_ODP[03]","kind":"Selection","value":"[Selection (one or more): organization-level; mission/business process-level; system-level]"},{"id":"SR-01_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined official]","guideline":"an official to manage the development, documentation, and dissemination of the supply chain risk management policy and procedures is defined"},{"id":"SR-01_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current supply chain risk management policy is reviewed and updated is defined"},{"id":"SR-01_ODP[06]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that require the current supply chain risk management policy to be reviewed and updated are defined"},{"id":"SR-01_ODP[07]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which the current supply chain risk management procedure is reviewed and updated is defined"},{"id":"SR-01_ODP[08]","kind":"Assignment","value":"[Assignment: organization-defined events]","guideline":"events that require the supply chain risk management procedures to be reviewed and updated are defined"}],"related":["PM-9","PM-30","PS-8","SI-12"],"references":[{"title":"FASC18","url":"https://www.congress.gov/bill/115th-congress/senate-bill/3085"},{"title":"41 CFR 201","url":"https://www.federalregister.gov/d/2020-18939"},{"title":"EO 13873","url":"https://www.whitehouse.gov/presidential-actions/executive-order-securing-information-communications-technology-services-supply-chain"},{"title":"CNSSD 505","url":"https://www.cnss.gov/CNSS/issuances/Directives.cfm"},{"title":"SP 800-12","url":"https://doi.org/10.6028/NIST.SP.800-12r1"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-39","url":"https://doi.org/10.6028/NIST.SP.800-39"},{"title":"SP 800-100","url":"https://doi.org/10.6028/NIST.SP.800-100"},{"title":"SP 800-161","url":"https://doi.org/10.6028/NIST.SP.800-161"}],"objectives":[{"label":"SR-01a.","prose":"","items":[{"label":"SR-01a.[01]","prose":"a supply chain risk management policy is developed and documented;"},{"label":"SR-01a.[02]","prose":"the supply chain risk management policy is disseminated to [Assignment: organization-defined personnel or roles];"},{"label":"SR-01a.[03]","prose":"supply chain risk management procedures to facilitate the implementation of the supply chain risk management policy and the associated supply chain risk management controls are developed and documented;"},{"label":"SR-01a.[04]","prose":"the supply chain risk management procedures are disseminated to [Assignment: organization-defined personnel or roles]."},{"label":"SR-01a.01","prose":"","items":[{"label":"SR-01a.01(a)","prose":"","items":[{"label":"SR-01a.01(a)[01]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] supply chain risk management policy addresses purpose;"},{"label":"SR-01a.01(a)[02]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] supply chain risk management policy addresses scope;"},{"label":"SR-01a.01(a)[03]","prose":"[Selection (one or more): organization-level; mission/business process-level; system-level] supply chain risk management policy addresses roles;"},{"label":"SR-01a.01(a)[04]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] supply chain risk management policy addresses responsibilities;"},{"label":"SR-01a.01(a)[05]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] supply chain risk management policy addresses management commitment;"},{"label":"SR-01a.01(a)[06]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] supply chain risk management policy addresses coordination among organizational entities;"},{"label":"SR-01a.01(a)[07]","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] supply chain risk management policy addresses compliance."}]},{"label":"SR-01a.01(b)","prose":"the [Selection (one or more): organization-level; mission/business process-level; system-level] supply chain risk management policy is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines;"}]}]},{"label":"SR-01b.","prose":"the [Assignment: organization-defined official] is designated to manage the development, documentation, and dissemination of the supply chain risk management policy and procedures;"},{"label":"SR-01c.","prose":"","items":[{"label":"SR-01c.01","prose":"","items":[{"label":"SR-01c.01[01]","prose":"the current supply chain risk management policy is reviewed and updated [Assignment: organization-defined frequency];"},{"label":"SR-01c.01[02]","prose":"the current supply chain risk management policy is reviewed and updated following [Assignment: organization-defined events];"}]},{"label":"SR-01c.02","prose":"","items":[{"label":"SR-01c.02[01]","prose":"the current supply chain risk management procedures are reviewed and updated [Assignment: organization-defined frequency];"},{"label":"SR-01c.02[02]","prose":"the current supply chain risk management procedures are reviewed and updated following [Assignment: organization-defined events]."}]}]}],"methods":[{"method":"Examine","objects":["Supply chain risk management policy","supply chain risk management procedures","system security plan","privacy plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with supply chain risk management responsibilities","organizational personnel with information security and privacy responsibilities","organizational personnel with acquisition responsibilities","organizational personnel with enterprise risk management responsibilities"]}]},"SR-2":{"statement":[{"label":"a.","prose":"Develop a plan for managing supply chain risks associated with the research and development, design, manufacturing, acquisition, delivery, integration, operations and maintenance, and disposal of the following systems, system components or system services: [Assignment: organization-defined systems, system components, or system services];"},{"label":"b.","prose":"Review and update the supply chain risk management plan [Assignment: organization-defined frequency] or as required, to address threat, organizational or environmental changes; and"},{"label":"c.","prose":"Protect the supply chain risk management plan from unauthorized disclosure and modification."}],"discussion":["The dependence on products, systems, and services from external providers, as well as the nature of the relationships with those providers, present an increasing level of risk to an organization. Threat actions that may increase security or privacy risks include unauthorized production, the insertion or use of counterfeits, tampering, theft, insertion of malicious software and hardware, and poor manufacturing and development practices in the supply chain. Supply chain risks can be endemic or systemic within a system element or component, a system, an organization, a sector, or the Nation. Managing supply chain risk is a complex, multifaceted undertaking that requires a coordinated effort across an organization to build trust relationships and communicate with internal and external stakeholders. Supply chain risk management (SCRM) activities include identifying and assessing risks, determining appropriate risk response actions, developing SCRM plans to document response actions, and monitoring performance against plans. The SCRM plan (at the system-level) is implementation specific, providing policy implementation, requirements, constraints and implications. It can either be stand-alone, or incorporated into system security and privacy plans. The SCRM plan addresses managing, implementation, and monitoring of SCRM controls and the development/sustainment of systems across the SDLC to support mission and business functions.","Because supply chains can differ significantly across and within organizations, SCRM plans are tailored to the individual program, organizational, and operational contexts. Tailored SCRM plans provide the basis for determining whether a technology, service, system component, or system is fit for purpose, and as such, the controls need to be tailored accordingly. Tailored SCRM plans help organizations focus their resources on the most critical mission and business functions based on mission and business requirements and their risk environment. Supply chain risk management plans include an expression of the supply chain risk tolerance for the organization, acceptable supply chain risk mitigation strategies or controls, a process for consistently evaluating and monitoring supply chain risk, approaches for implementing and communicating the plan, a description of and justification for supply chain risk mitigation measures taken, and associated roles and responsibilities. Finally, supply chain risk management plans address requirements for developing trustworthy, secure, privacy-protective, and resilient system components and systems, including the application of the security design principles implemented as part of life cycle-based systems security engineering processes (see [SA-8](#sa-8))."],"params":[{"id":"SR-02_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined systems, system components, or system services]","guideline":"systems, system components, or system services for which a supply chain risk management plan is developed are defined"},{"id":"SR-02_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to review and update the supply chain risk management plan is defined"}],"related":["CA-2","CP-4","IR-4","MA-2","MA-6","PE-16","PL-2","PM-9","PM-30","RA-3","RA-7","SA-8","SI-4"],"references":[{"title":"FASC18","url":"https://www.congress.gov/bill/115th-congress/senate-bill/3085"},{"title":"41 CFR 201","url":"https://www.federalregister.gov/d/2020-18939"},{"title":"EO 13873","url":"https://www.whitehouse.gov/presidential-actions/executive-order-securing-information-communications-technology-services-supply-chain"},{"title":"CNSSD 505","url":"https://www.cnss.gov/CNSS/issuances/Directives.cfm"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-39","url":"https://doi.org/10.6028/NIST.SP.800-39"},{"title":"SP 800-160-1","url":"https://doi.org/10.6028/NIST.SP.800-160v1"},{"title":"SP 800-161","url":"https://doi.org/10.6028/NIST.SP.800-161"},{"title":"SP 800-181","url":"https://doi.org/10.6028/NIST.SP.800-181r1"},{"title":"IR 7622","url":"https://doi.org/10.6028/NIST.IR.7622"},{"title":"IR 8272","url":"https://doi.org/10.6028/NIST.IR.8272"}],"objectives":[{"label":"SR-02a.","prose":"","items":[{"label":"SR-02a.[01]","prose":"a plan for managing supply chain risks is developed;"},{"label":"SR-02a.[02]","prose":"the supply chain risk management plan addresses risks associated with the research and development of [Assignment: organization-defined systems, system components, or system services];"},{"label":"SR-02a.[03]","prose":"the supply chain risk management plan addresses risks associated with the design of [Assignment: organization-defined systems, system components, or system services];"},{"label":"SR-02a.[04]","prose":"the supply chain risk management plan addresses risks associated with the manufacturing of [Assignment: organization-defined systems, system components, or system services];"},{"label":"SR-02a.[05]","prose":"the supply chain risk management plan addresses risks associated with the acquisition of [Assignment: organization-defined systems, system components, or system services];"},{"label":"SR-02a.[06]","prose":"the supply chain risk management plan addresses risks associated with the delivery of [Assignment: organization-defined systems, system components, or system services];"},{"label":"SR-02a.[07]","prose":"the supply chain risk management plan addresses risks associated with the integration of [Assignment: organization-defined systems, system components, or system services];"},{"label":"SR-02a.[08]","prose":"the supply chain risk management plan addresses risks associated with the operation and maintenance of [Assignment: organization-defined systems, system components, or system services];"},{"label":"SR-02a.[09]","prose":"the supply chain risk management plan addresses risks associated with the disposal of [Assignment: organization-defined systems, system components, or system services];"}]},{"label":"SR-02b.","prose":"the supply chain risk management plan is reviewed and updated [Assignment: organization-defined frequency] or as required to address threat, organizational, or environmental changes;"},{"label":"SR-02c.","prose":"","items":[{"label":"SR-02c.[01]","prose":"the supply chain risk management plan is protected from unauthorized disclosure;"},{"label":"SR-02c.[02]","prose":"the supply chain risk management plan is protected from unauthorized modification."}]}],"methods":[{"method":"Examine","objects":["Supply chain risk management policy","supply chain risk management procedures","supply chain risk management plan","system and services acquisition policy","system and services acquisition procedures","procedures addressing supply chain protection","procedures for protecting the supply chain risk management plan from unauthorized disclosure and modification","system development life cycle procedures"]},{"method":"Interview","objects":["Organizational personnel with acquisition responsibilities","organizational personnel with information security and privacy responsibilities","organizational personnel with supply chain risk management responsibilities"]},{"method":"Test","objects":["Organizational processes for defining and documenting the system development life cycle (SDLC)","organizational processes for identifying SDLC roles and responsibilities","organizational processes for integrating supply chain risk management into the SDLC","mechanisms supporting and/or implementing the SDLC"]}]},"SR-2(1)":{"statement":[{"prose":"Establish a supply chain risk management team consisting of [Assignment: organization-defined personnel, roles and responsibilities] to lead and support the following SCRM activities: [Assignment: organization-defined supply chain risk management activities]."}],"discussion":["To implement supply chain risk management plans, organizations establish a coordinated, team-based approach to identify and assess supply chain risks and manage these risks by using programmatic and technical mitigation techniques. The team approach enables organizations to conduct an analysis of their supply chain, communicate with internal and external partners or stakeholders, and gain broad consensus regarding the appropriate resources for SCRM. The SCRM team consists of organizational personnel with diverse roles and responsibilities for leading and supporting SCRM activities, including risk executive, information technology, contracting, information security, privacy, mission or business, legal, supply chain and logistics, acquisition, business continuity, and other relevant functions. Members of the SCRM team are involved in various aspects of the SDLC and, collectively, have an awareness of and provide expertise in acquisition processes, legal practices, vulnerabilities, threats, and attack vectors, as well as an understanding of the technical aspects and dependencies of systems. The SCRM team can be an extension of the security and privacy risk management processes or be included as part of an organizational risk management team."],"params":[{"id":"SR-02(01)_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined personnel, roles and responsibilities]","guideline":"the personnel, roles, and responsibilities of the supply chain risk management team are defined"},{"id":"SR-02(01)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined supply chain risk management activities]","guideline":"supply chain risk management activities are defined"}],"related":[],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Supply chain risk management policy","supply chain risk management procedures","supply chain risk management team charter documentation","supply chain risk management strategy","supply chain risk management implementation plan","procedures addressing supply chain protection","system security plan","privacy plan"]},{"method":"Interview","objects":["Organizational personnel with acquisition responsibilities","organizational personnel with information security and privacy responsibilities","organizational personnel with supply chain risk management responsibilities","organizational personnel with enterprise risk management responsibilities","legal counsel","organizational personnel with business continuity responsibilities"]}]},"SR-3":{"statement":[{"label":"a.","prose":"Establish a process or processes to identify and address weaknesses or deficiencies in the supply chain elements and processes of [Assignment: organization-defined system or system component] in coordination with [Assignment: organization-defined supply chain personnel];"},{"label":"b.","prose":"Employ the following controls to protect against supply chain risks to the system, system component, or system service and to limit the harm or consequences from supply chain-related events: [Assignment: organization-defined supply chain controls]; and"},{"label":"c.","prose":"Document the selected and implemented supply chain processes and controls in [Selection (one or more): security and privacy plans; supply chain risk management plan; [Assignment: organization-defined document]]."}],"discussion":["Supply chain elements include organizations, entities, or tools employed for the research and development, design, manufacturing, acquisition, delivery, integration, operations and maintenance, and disposal of systems and system components. Supply chain processes include hardware, software, and firmware development processes; shipping and handling procedures; personnel security and physical security programs; configuration management tools, techniques, and measures to maintain provenance; or other programs, processes, or procedures associated with the development, acquisition, maintenance and disposal of systems and system components. Supply chain elements and processes may be provided by organizations, system integrators, or external providers. Weaknesses or deficiencies in supply chain elements or processes represent potential vulnerabilities that can be exploited by adversaries to cause harm to the organization and affect its ability to carry out its core missions or business functions. Supply chain personnel are individuals with roles and responsibilities in the supply chain."],"params":[{"id":"SR-03_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined system or system component]","guideline":"the system or system component requiring a process or processes to identify and address weaknesses or deficiencies is defined"},{"id":"SR-03_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined supply chain personnel]","guideline":"supply chain personnel with whom to coordinate the process or processes to identify and address weaknesses or deficiencies in the supply chain elements and processes is/are defined"},{"id":"SR-03_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined supply chain controls]","guideline":"supply chain controls employed to protect against supply chain risks to the system, system component, or system service and to limit the harm or consequences from supply chain-related events are defined"},{"id":"SR-03_ODP[04]","kind":"Selection","value":"[Selection (one or more): security and privacy plans; supply chain risk management plan; [Assignment: organization-defined document]]"},{"id":"SR-03_ODP[05]","kind":"Assignment","value":"[Assignment: organization-defined document]","guideline":"the document identifying the selected and implemented supply chain processes and controls is defined (if selected)"}],"related":["CA-2","MA-2","MA-6","PE-3","PE-16","PL-8","PM-30","SA-2","SA-3","SA-4","SA-5","SA-8","SA-9","SA-10","SA-15","SC-7","SC-29","SC-30","SC-38","SI-7","SR-6","SR-9","SR-11"],"references":[{"title":"FASC18","url":"https://www.congress.gov/bill/115th-congress/senate-bill/3085"},{"title":"41 CFR 201","url":"https://www.federalregister.gov/d/2020-18939"},{"title":"EO 13873","url":"https://www.whitehouse.gov/presidential-actions/executive-order-securing-information-communications-technology-services-supply-chain"},{"title":"ISO 20243","url":"https://www.iso.org/standard/74399.html"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-161","url":"https://doi.org/10.6028/NIST.SP.800-161"},{"title":"IR 7622","url":"https://doi.org/10.6028/NIST.IR.7622"}],"objectives":[{"label":"SR-03a.","prose":"","items":[{"label":"SR-03a.[01]","prose":"a process or processes is/are established to identify and address weaknesses or deficiencies in the supply chain elements and processes of [Assignment: organization-defined system or system component];"},{"label":"SR-03a.[02]","prose":"the process or processes to identify and address weaknesses or deficiencies in the supply chain elements and processes of [Assignment: organization-defined system or system component] is/are coordinated with [Assignment: organization-defined supply chain personnel];"}]},{"label":"SR-03b.","prose":"[Assignment: organization-defined supply chain controls] are employed to protect against supply chain risks to the system, system component, or system service and to limit the harm or consequences from supply chain-related events;"},{"label":"SR-03c.","prose":"the selected and implemented supply chain processes and controls are documented in [Selection (one or more): security and privacy plans; supply chain risk management plan; [Assignment: organization-defined document]]."}],"methods":[{"method":"Examine","objects":["Supply chain risk management policy","supply chain risk management procedures","supply chain risk management strategy","supply chain risk management plan","systems and critical system components inventory documentation","system and services acquisition policy","system and services acquisition procedures","procedures addressing the integration of information security and privacy requirements into the acquisition process"]},{"method":"Interview","objects":["Organizational personnel with acquisition responsibilities","organizational personnel with information security and privacy responsibilities","organizational personnel with supply chain risk management responsibilities"]},{"method":"Test","objects":["Organizational processes for identifying and addressing supply chain element and process deficiencies"]}]},"SR-4":{"statement":[{"prose":"Document, monitor, and maintain valid provenance of the following systems, system components, and associated data: [Assignment: organization-defined systems, system components, and associated data]."}],"discussion":["Every system and system component has a point of origin and may be changed throughout its existence. Provenance is the chronology of the origin, development, ownership, location, and changes to a system or system component and associated data. It may also include personnel and processes used to interact with or make modifications to the system, component, or associated data. Organizations consider developing procedures (see [SR-1](#sr-1)) for allocating responsibilities for the creation, maintenance, and monitoring of provenance for systems and system components; transferring provenance documentation and responsibility between organizations; and preventing and monitoring for unauthorized changes to the provenance records. Organizations have methods to document, monitor, and maintain valid provenance baselines for systems, system components, and related data. These actions help track, assess, and document any changes to the provenance, including changes in supply chain elements or configuration, and help ensure non-repudiation of provenance information and the provenance change records. Provenance considerations are addressed throughout the system development life cycle and incorporated into contracts and other arrangements, as appropriate."],"params":[{"id":"SR-04_ODP","kind":"Assignment","value":"[Assignment: organization-defined systems, system components, and associated data]","guideline":"systems, system components, and associated data that require valid provenance are defined"}],"related":["CM-8","MA-2","MA-6","RA-9","SA-3","SA-8","SI-4"],"references":[{"title":"FASC18","url":"https://www.congress.gov/bill/115th-congress/senate-bill/3085"},{"title":"41 CFR 201","url":"https://www.federalregister.gov/d/2020-18939"},{"title":"EO 13873","url":"https://www.whitehouse.gov/presidential-actions/executive-order-securing-information-communications-technology-services-supply-chain"},{"title":"ISO 27036","url":"https://www.iso.org/standard/59648.html"},{"title":"ISO 20243","url":"https://www.iso.org/standard/74399.html"},{"title":"SP 800-160-1","url":"https://doi.org/10.6028/NIST.SP.800-160v1"},{"title":"SP 800-161","url":"https://doi.org/10.6028/NIST.SP.800-161"},{"title":"IR 7622","url":"https://doi.org/10.6028/NIST.IR.7622"},{"title":"IR 8112","url":"https://doi.org/10.6028/NIST.IR.8112"},{"title":"IR 8272","url":"https://doi.org/10.6028/NIST.IR.8272"}],"objectives":[{"label":"SR-04[01]","prose":"valid provenance is documented for [Assignment: organization-defined systems, system components, and associated data];"},{"label":"SR-04[02]","prose":"valid provenance is monitored for [Assignment: organization-defined systems, system components, and associated data];"},{"label":"SR-04[03]","prose":"valid provenance is maintained for [Assignment: organization-defined systems, system components, and associated data]."}],"methods":[{"method":"Examine","objects":["Supply chain risk management policy","supply chain risk management procedures","supply chain risk management plan","documentation of critical systems, critical system components, and associated data","documentation showing the history of ownership, custody, and location of and changes to critical systems or critical system components","system architecture","inter-organizational agreements and procedures","contracts"]},{"method":"Interview","objects":["Organizational personnel with acquisition responsibilities","organizational personnel with information security and privacy responsibilities","organizational personnel with supply chain risk management responsibilities"]},{"method":"Test","objects":["Organizational processes for identifying the provenance of critical systems and critical system components","mechanisms used to document, monitor, or maintain provenance"]}]},"SR-5":{"statement":[{"prose":"Employ the following acquisition strategies, contract tools, and procurement methods to protect against, identify, and mitigate supply chain risks: [Assignment: organization-defined strategies, tools, and methods]."}],"discussion":["The use of the acquisition process provides an important vehicle to protect the supply chain. There are many useful tools and techniques available, including obscuring the end use of a system or system component, using blind or filtered buys, requiring tamper-evident packaging, or using trusted or controlled distribution. The results from a supply chain risk assessment can guide and inform the strategies, tools, and methods that are most applicable to the situation. Tools and techniques may provide protections against unauthorized production, theft, tampering, insertion of counterfeits, insertion of malicious software or backdoors, and poor development practices throughout the system development life cycle. Organizations also consider providing incentives for suppliers who implement controls, promote transparency into their processes and security and privacy practices, provide contract language that addresses the prohibition of tainted or counterfeit components, and restrict purchases from untrustworthy suppliers. Organizations consider providing training, education, and awareness programs for personnel regarding supply chain risk, available mitigation strategies, and when the programs should be employed. Methods for reviewing and protecting development plans, documentation, and evidence are commensurate with the security and privacy requirements of the organization. Contracts may specify documentation protection requirements."],"params":[{"id":"SR-05_ODP","kind":"Assignment","value":"[Assignment: organization-defined strategies, tools, and methods]","guideline":"acquisition strategies, contract tools, and procurement methods to protect against, identify, and mitigate supply chain risks are defined"}],"related":["AT-3","SA-2","SA-3","SA-4","SA-5","SA-8","SA-9","SA-10","SA-15","SR-6","SR-9","SR-10","SR-11"],"references":[{"title":"FASC18","url":"https://www.congress.gov/bill/115th-congress/senate-bill/3085"},{"title":"41 CFR 201","url":"https://www.federalregister.gov/d/2020-18939"},{"title":"EO 13873","url":"https://www.whitehouse.gov/presidential-actions/executive-order-securing-information-communications-technology-services-supply-chain"},{"title":"ISO 27036","url":"https://www.iso.org/standard/59648.html"},{"title":"ISO 20243","url":"https://www.iso.org/standard/74399.html"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-161","url":"https://doi.org/10.6028/NIST.SP.800-161"},{"title":"IR 7622","url":"https://doi.org/10.6028/NIST.IR.7622"},{"title":"IR 8272","url":"https://doi.org/10.6028/NIST.IR.8272"}],"objectives":[{"label":"SR-05[01]","prose":"[Assignment: organization-defined strategies, tools, and methods] are employed to protect against supply chain risks;"},{"label":"SR-05[02]","prose":"[Assignment: organization-defined strategies, tools, and methods] are employed to identify supply chain risks;"},{"label":"SR-05[03]","prose":"[Assignment: organization-defined strategies, tools, and methods] are employed to mitigate supply chain risks."}],"methods":[{"method":"Examine","objects":["Supply chain risk management policy","supply chain risk management procedures","supply chain risk management plan","system and services acquisition policy","system and services acquisition procedures","procedures addressing supply chain protection","procedures addressing the integration of information security and privacy requirements into the acquisition process","solicitation documentation"]},{"method":"Interview","objects":["Organizational personnel with acquisition responsibilities","organizational personnel with information security and privacy responsibilities","organizational personnel with supply chain risk management responsibilities"]},{"method":"Test","objects":["Organizational processes for defining and employing tailored acquisition strategies, contract tools, and procurement methods","mechanisms supporting and/or implementing the definition and employment of tailored acquisition strategies, contract tools, and procurement methods"]}]},"SR-6":{"statement":[{"prose":"Assess and review the supply chain-related risks associated with suppliers or contractors and the system, system component, or system service they provide [Assignment: organization-defined frequency]."}],"discussion":["An assessment and review of supplier risk includes security and supply chain risk management processes, foreign ownership, control or influence (FOCI), and the ability of the supplier to effectively assess subordinate second-tier and third-tier suppliers and contractors. The reviews may be conducted by the organization or by an independent third party. The reviews consider documented processes, documented controls, all-source intelligence, and publicly available information related to the supplier or contractor. Organizations can use open-source information to monitor for indications of stolen information, poor development and quality control practices, information spillage, or counterfeits. In some cases, it may be appropriate or required to share assessment and review results with other organizations in accordance with any applicable rules, policies, or inter-organizational agreements or contracts."],"params":[{"id":"SR-06_ODP","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"the frequency at which to assess and review the supply chain-related risks associated with suppliers or contractors and the systems, system components, or system services they provide is defined"}],"related":["SR-3","SR-5"],"references":[{"title":"FASC18","url":"https://www.congress.gov/bill/115th-congress/senate-bill/3085"},{"title":"41 CFR 201","url":"https://www.federalregister.gov/d/2020-18939"},{"title":"EO 13873","url":"https://www.whitehouse.gov/presidential-actions/executive-order-securing-information-communications-technology-services-supply-chain"},{"title":"ISO 27036","url":"https://www.iso.org/standard/59648.html"},{"title":"ISO 20243","url":"https://www.iso.org/standard/74399.html"},{"title":"FIPS 140-3","url":"https://doi.org/10.6028/NIST.FIPS.140-3"},{"title":"FIPS 180-4","url":"https://doi.org/10.6028/NIST.FIPS.180-4"},{"title":"FIPS 186-4","url":"https://doi.org/10.6028/NIST.FIPS.186-4"},{"title":"FIPS 202","url":"https://doi.org/10.6028/NIST.FIPS.202"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-161","url":"https://doi.org/10.6028/NIST.SP.800-161"},{"title":"IR 7622","url":"https://doi.org/10.6028/NIST.IR.7622"},{"title":"IR 8272","url":"https://doi.org/10.6028/NIST.IR.8272"}],"objectives":[],"methods":[{"method":"Examine","objects":["Supply chain risk management policy and procedures","supply chain risk management strategy","supply chain risk management plan","system and services acquisition policy","procedures addressing supply chain protection","procedures addressing the integration of information security requirements into the acquisition process","records of supplier due diligence reviews","system security plan"]},{"method":"Interview","objects":["Organizational personnel with system and services acquisition responsibilities","organizational personnel with information security responsibilities","organizational personnel with supply chain protection responsibilities"]},{"method":"Test","objects":["Organizational processes for conducting supplier reviews","mechanisms supporting and/or implementing supplier reviews"]}]},"SR-8":{"statement":[{"prose":"Establish agreements and procedures with entities involved in the supply chain for the system, system component, or system service for the [Selection (one or more): notification of supply chain compromises; [Assignment: organization-defined results of assessments or audits]]."}],"discussion":["The establishment of agreements and procedures facilitates communications among supply chain entities. Early notification of compromises and potential compromises in the supply chain that can potentially adversely affect or have adversely affected organizational systems or system components is essential for organizations to effectively respond to such incidents. The results of assessments or audits may include open-source information that contributed to a decision or result and could be used to help the supply chain entity resolve a concern or improve its processes."],"params":[{"id":"SR-08_ODP[01]","kind":"Selection","value":"[Selection (one or more): notification of supply chain compromises; [Assignment: organization-defined results of assessments or audits]]"},{"id":"SR-08_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined results of assessments or audits]","guideline":"information for which agreements and procedures are to be established are defined (if selected)"}],"related":["IR-4","IR-6","IR-8"],"references":[{"title":"FASC18","url":"https://www.congress.gov/bill/115th-congress/senate-bill/3085"},{"title":"41 CFR 201","url":"https://www.federalregister.gov/d/2020-18939"},{"title":"EO 13873","url":"https://www.whitehouse.gov/presidential-actions/executive-order-securing-information-communications-technology-services-supply-chain"},{"title":"ISO 27036","url":"https://www.iso.org/standard/59648.html"},{"title":"SP 800-30","url":"https://doi.org/10.6028/NIST.SP.800-30r1"},{"title":"SP 800-161","url":"https://doi.org/10.6028/NIST.SP.800-161"},{"title":"IR 7622","url":"https://doi.org/10.6028/NIST.IR.7622"}],"objectives":[],"methods":[{"method":"Examine","objects":["Supply chain risk management policy and procedures","supply chain risk management plan","system and services acquisition policy","procedures addressing supply chain protection","acquisition documentation","service level agreements","acquisition contracts for the system, system component, or system service","inter-organizational agreements and procedures"]},{"method":"Interview","objects":["Organizational personnel with system and service acquisition responsibilities","organizational personnel with information security responsibilities","organizational personnel with supply chain risk management responsibilities"]},{"method":"Test","objects":["Organizational processes for establishing inter-organizational agreements and procedures with supply chain entities"]}]},"SR-9":{"statement":[{"prose":"Implement a tamper protection program for the system, system component, or system service."}],"discussion":["Anti-tamper technologies, tools, and techniques provide a level of protection for systems, system components, and services against many threats, including reverse engineering, modification, and substitution. Strong identification combined with tamper resistance and/or tamper detection is essential to protecting systems and components during distribution and when in use."],"params":[],"related":["PE-3","PM-30","SA-15","SI-4","SI-7","SR-3","SR-4","SR-5","SR-10","SR-11"],"references":[{"title":"ISO 20243","url":"https://www.iso.org/standard/74399.html"}],"objectives":[],"methods":[{"method":"Examine","objects":["Supply chain risk management policy and procedures","supply chain risk management plan","system and services acquisition policy","procedures addressing supply chain protection","procedures addressing tamper resistance and detection","tamper protection program documentation","tamper protection tools and techniques documentation","tamper resistance and detection tools and techniques documentation"]},{"method":"Interview","objects":["Organizational personnel with tamper protection program responsibilities","organizational personnel with information security responsibilities","organizational personnel with supply chain risk management responsibilities"]},{"method":"Test","objects":["Organizational processes for the implementation of the tamper protection program","mechanisms supporting and/or implementing the tamper protection program"]}]},"SR-9(1)":{"statement":[{"prose":"Employ anti-tamper technologies, tools, and techniques throughout the system development life cycle."}],"discussion":["The system development life cycle includes research and development, design, manufacturing, acquisition, delivery, integration, operations and maintenance, and disposal. Organizations use a combination of hardware and software techniques for tamper resistance and detection. Organizations use obfuscation and self-checking to make reverse engineering and modifications more difficult, time-consuming, and expensive for adversaries. The customization of systems and system components can make substitutions easier to detect and therefore limit damage."],"params":[],"related":["SA-3"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Supply chain risk management policy and procedures","supply chain risk management plan","system and services acquisition policy","procedures addressing tamper resistance and detection","tamper protection program documentation","tamper protection tools and techniques documentation","tamper resistance and detection tools (technologies) and techniques documentation","system development life cycle documentation"]},{"method":"Interview","objects":["Organizational personnel with system and services acquisition responsibilities","organizational personnel with information security responsibilities","organizational personnel with supply chain risk management responsibilities","organizational personnel with SDLC responsibilities"]},{"method":"Test","objects":["Organizational processes for employing anti-tamper technologies","mechanisms supporting and/or implementing anti-tamper technologies"]}]},"SR-10":{"statement":[{"prose":"Inspect the following systems or system components [Selection (one or more): at random; at [Assignment: organization-defined frequency]; upon [Assignment: organization-defined indications of need for inspection]] to detect tampering: [Assignment: organization-defined systems or system components]."}],"discussion":["The inspection of systems or systems components for tamper resistance and detection addresses physical and logical tampering and is applied to systems and system components removed from organization-controlled areas. Indications of a need for inspection include changes in packaging, specifications, factory location, or entity in which the part is purchased, and when individuals return from travel to high-risk locations."],"params":[{"id":"SR-10_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined systems or system components]","guideline":"systems or system components that require inspection are defined"},{"id":"SR-10_ODP[02]","kind":"Selection","value":"[Selection (one or more): at random; at [Assignment: organization-defined frequency]; upon [Assignment: organization-defined indications of need for inspection]]"},{"id":"SR-10_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined frequency]","guideline":"frequency at which to inspect systems or system components is defined (if selected)"},{"id":"SR-10_ODP[04]","kind":"Assignment","value":"[Assignment: organization-defined indications of need for inspection]","guideline":"indications of the need for an inspection of systems or system components are defined (if selected)"}],"related":["AT-3","PM-30","SI-4","SI-7","SR-3","SR-4","SR-5","SR-9","SR-11"],"references":[{"title":"ISO 20243","url":"https://www.iso.org/standard/74399.html"}],"objectives":[],"methods":[{"method":"Examine","objects":["Supply chain risk management policy and procedures","supply chain risk management plan","system and services acquisition policy","records of random inspections","inspection reports/results","assessment reports/results","acquisition documentation","service level agreements"]},{"method":"Interview","objects":["Organizational personnel with system and services acquisition responsibilities","organizational personnel with information security responsibilities","organizational personnel with supply chain risk management responsibilities"]},{"method":"Test","objects":["Organizational processes for establishing inter-organizational agreements and procedures with supply chain entities","organizational processes to inspect for tampering"]}]},"SR-11":{"statement":[{"label":"a.","prose":"Develop and implement anti-counterfeit policy and procedures that include the means to detect and prevent counterfeit components from entering the system; and"},{"label":"b.","prose":"Report counterfeit system components to [Selection (one or more): source of counterfeit component; [Assignment: organization-defined external reporting organizations]; [Assignment: organization-defined personnel or roles]]."}],"discussion":["Sources of counterfeit components include manufacturers, developers, vendors, and contractors. Anti-counterfeiting policies and procedures support tamper resistance and provide a level of protection against the introduction of malicious code. External reporting organizations include CISA."],"params":[{"id":"SR-11_ODP[01]","kind":"Selection","value":"[Selection (one or more): source of counterfeit component; [Assignment: organization-defined external reporting organizations]; [Assignment: organization-defined personnel or roles]]"},{"id":"SR-11_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined external reporting organizations]","guideline":"external reporting organizations to whom counterfeit system components are to be reported is/are defined (if selected)"},{"id":"SR-11_ODP[03]","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles to whom counterfeit system components are to be reported is/are defined (if selected)"}],"related":["PE-3","SA-4","SI-7","SR-9","SR-10"],"references":[{"title":"ISO 20243","url":"https://www.iso.org/standard/74399.html"}],"objectives":[{"label":"SR-11a.","prose":"","items":[{"label":"SR-11a.[01]","prose":"an anti-counterfeit policy is developed and implemented;"},{"label":"SR-11a.[02]","prose":"anti-counterfeit procedures are developed and implemented;"},{"label":"SR-11a.[03]","prose":"the anti-counterfeit procedures include the means to detect counterfeit components entering the system;"},{"label":"SR-11a.[04]","prose":"the anti-counterfeit procedures include the means to prevent counterfeit components from entering the system;"}]},{"label":"SR-11b.","prose":"counterfeit system components are reported to [Selection (one or more): source of counterfeit component; [Assignment: organization-defined external reporting organizations]; [Assignment: organization-defined personnel or roles]]."}],"methods":[{"method":"Examine","objects":["Supply chain risk management policy and procedures","supply chain risk management plan","system and services acquisition policy","anti-counterfeit plan","anti-counterfeit policy and procedures","media disposal policy","media protection policy","incident response policy"]},{"method":"Interview","objects":["Organizational personnel with system and service acquisition responsibilities","organizational personnel with information security responsibilities","organizational personnel with supply chain risk management responsibilities","organizational personnel with responsibilities for anti-counterfeit policies, procedures, and reporting"]},{"method":"Test","objects":["Organizational processes for counterfeit prevention, detection, and reporting","mechanisms supporting and/or implementing anti-counterfeit detection, prevention, and reporting"]}]},"SR-11(1)":{"statement":[{"prose":"Train [Assignment: organization-defined personnel or roles] to detect counterfeit system components (including hardware, software, and firmware)."}],"discussion":["None."],"params":[{"id":"SR-11(01)_ODP","kind":"Assignment","value":"[Assignment: organization-defined personnel or roles]","guideline":"personnel or roles requiring training to detect counterfeit system components (including hardware, software, and firmware) is/are defined"}],"related":["AT-3"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Supply chain risk management policy and procedures","supply chain risk management plan","system and services acquisition policy","anti-counterfeit plan","anti-counterfeit policy and procedures","media disposal policy","media protection policy","incident response policy"]},{"method":"Interview","objects":["Organizational personnel with information security responsibilities","organizational personnel with supply chain risk management responsibilities","organizational personnel with responsibilities for anti-counterfeit policies, procedures, and training"]},{"method":"Test","objects":["Organizational processes for anti-counterfeit training"]}]},"SR-11(2)":{"statement":[{"prose":"Maintain configuration control over the following system components awaiting service or repair and serviced or repaired components awaiting return to service: [Assignment: organization-defined system components]."}],"discussion":["None."],"params":[{"id":"SR-11(02)_ODP","kind":"Assignment","value":"[Assignment: organization-defined system components]","guideline":"system components requiring configuration control are defined"}],"related":["CM-3","MA-2","MA-4","SA-10"],"references":[],"objectives":[{"label":"SR-11(02)[01]","prose":"configuration control over [Assignment: organization-defined system components] awaiting service or repair is maintained;"},{"label":"SR-11(02)[02]","prose":"configuration control over serviced or repaired [Assignment: organization-defined system components] awaiting return to service is maintained."}],"methods":[{"method":"Examine","objects":["Supply chain risk management policy and procedures","supply chain risk management plan","configuration control procedures","acquisition documentation","service level agreements","acquisition contracts for the system component","inter-organizational agreements and procedures","system security plan"]},{"method":"Interview","objects":["Organizational personnel with system and services acquisition responsibilities","organizational personnel with information security responsibilities","organizational personnel with supply chain risk management responsibilities"]},{"method":"Test","objects":["Organizational processes for establishing inter-organizational agreements and procedures with supply chain entities","organizational configuration control processes"]}]},"SR-12":{"statement":[{"prose":"Dispose of [Assignment: organization-defined data, documentation, tools, or system components] using the following techniques and methods: [Assignment: organization-defined techniques and methods]."}],"discussion":["Data, documentation, tools, or system components can be disposed of at any time during the system development life cycle (not only in the disposal or retirement phase of the life cycle). For example, disposal can occur during research and development, design, prototyping, or operations/maintenance and include methods such as disk cleaning, removal of cryptographic keys, partial reuse of components. Opportunities for compromise during disposal affect physical and logical data, including system documentation in paper-based or digital files; shipping and delivery documentation; memory sticks with software code; or complete routers or servers that include permanent media, which contain sensitive or proprietary information. Additionally, proper disposal of system components helps to prevent such components from entering the gray market."],"params":[{"id":"SR-12_ODP[01]","kind":"Assignment","value":"[Assignment: organization-defined data, documentation, tools, or system components]","guideline":"data, documentation, tools, or system components to be disposed of are defined"},{"id":"SR-12_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined techniques and methods]","guideline":"techniques and methods for disposing of data, documentation, tools, or system components are defined"}],"related":["MP-6"],"references":[],"objectives":[],"methods":[{"method":"Examine","objects":["Supply chain risk management policy and procedures","supply chain risk management plan","disposal procedures addressing supply chain protection","media disposal policy","media protection policy","disposal records for system components","documentation of the system components identified for disposal","documentation of the disposal techniques and methods employed for system components"]},{"method":"Interview","objects":["Organizational personnel with system component disposal responsibilities","organizational personnel with information security responsibilities","organizational personnel with supply chain protection responsibilities"]},{"method":"Test","objects":["Organizational techniques and methods for system component disposal","mechanisms supporting and/or implementing system component disposal"]}]}};
